    private const val PRELUDE = """
// Shared by every scene. AGSL (Android 13+), written in the GLSL ES 1.0 subset so the same text
// also runs in the WebGL preview (tools/themes/preview.html): constant loop bounds, no arrays,
// no integer %, no derivatives.
uniform float2 uRes;     // size in pixels
uniform float uTime;     // seconds, wrapped every hour
uniform float4 uBg;      // theme background
uniform float4 uSurf;    // theme surface
uniform float4 uAcc;     // theme accent
uniform float4 uSec;     // theme secondary
uniform float uLod;      // 0 = full detail; 1-2 = fewer noise octaves (Low / Lowest background quality)
uniform float uDensity;  // scene editor's particles + 1 (0 = not set: normal amount)

const float PI = 3.14159265;
const float TAU = 6.2831853;

float sat(float x) { return clamp(x, 0.0, 1.0); }
// x squared. Use this, not pow(x, 2.0): pow() of a negative number is undefined on GPUs (NaN, black).
float sqf(float x) { return x * x; }

// Sine-free hashes: stable on mobile GPUs.
float hash11(float p) { p = fract(p * 0.1031); p *= p + 33.33; p *= p + p; return fract(p); }
float hash12(float2 p) {
    float3 p3 = fract(float3(p.x, p.y, p.x) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}
float2 hash22(float2 p) {
    float3 p3 = fract(float3(p.x, p.y, p.x) * float3(0.1031, 0.1030, 0.0973));
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.xx + p3.yz) * p3.zy);
}

float vnoise(float2 p) {
    float2 i = floor(p);
    float2 f = fract(p);
    float2 u = f * f * (3.0 - 2.0 * f);
    float a = hash12(i);
    float b = hash12(i + float2(1.0, 0.0));
    float c = hash12(i + float2(0.0, 1.0));
    float d = hash12(i + float2(1.0, 1.0));
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

// At reduced resolution (Low / Lowest quality) the finest octaves are smaller than a pixel anyway:
// uLod skips them, and the sum is rescaled so the scene keeps the same brightness and coverage.
float fbm(float2 p) {
    float v = 0.0;
    float a = 0.5;
    float n = max(2.0, 4.0 - uLod);
    for (int i = 0; i < 4; i++) {
        if (float(i) >= n) break;
        v += a * vnoise(p);
        p = p * 2.03 + float2(17.1, 9.2);
        a *= 0.5;
    }
    return v * 0.9375 / (1.0 - 2.0 * a);
}

float fbm3(float2 p) {
    float v = 0.0;
    float a = 0.5;
    float n = max(2.0, 3.0 - uLod);
    for (int i = 0; i < 3; i++) {
        if (float(i) >= n) break;
        v += a * vnoise(p);
        p = p * 2.07 + float2(5.3, 11.7);
        a *= 0.5;
    }
    return v * 0.875 / (1.0 - 2.0 * a);
}

float2x2 rot(float a) { float c = cos(a); float s = sin(a); return float2x2(c, s, -s, c); }

float sdSegment(float2 p, float2 a, float2 b) {
    float2 pa = p - a;
    float2 ba = b - a;
    float h = sat(dot(pa, ba) / max(dot(ba, ba), 1e-6));
    return length(pa - ba * h);
}

float sdRoundBox(float2 p, float2 b, float r) {
    float2 q = abs(p) - b + r;
    return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r;
}

// Soft light falloff: 1 at d = 0, about r/d further out.
float glow(float d, float r) { return r / (d + r); }

// One layer of drifting, twinkling points. uv is in screen heights; the layer moves by drift.
float dots(float2 uv, float scale, float2 drift, float density, float size, float seed) {
    float2 p = uv * scale + drift;
    float2 id = floor(p);
    float2 f = fract(p) - 0.5;
    float2 r = hash22(id + seed);
    if (r.x > density * (uDensity > 0.5 ? uDensity - 1.0 : 1.0)) return 0.0;
    float2 o = (hash22(id + seed + 7.31) - 0.5) * 0.6;
    float d = length(f - o);
    float tw = 0.55 + 0.45 * sin(uTime * (0.6 + 1.6 * r.y) + r.x * 40.0);
    return (1.0 - smoothstep(0.0, size, d)) * tw;
}

// Vignette, plus a little noise so dark gradients don't band on 8-bit panels.
float3 finish(float3 col, float2 fc) {
    float2 q = fc / uRes;
    float v = 16.0 * q.x * q.y * (1.0 - q.x) * (1.0 - q.y);
    col *= 0.62 + 0.38 * pow(max(v, 0.0), 0.3);
    // Pure black stays pure black (OLED themes).
    float lit = sat(max(col.r, max(col.g, col.b)) * 80.0);
    col += (hash12(fc + fract(uTime) * 61.0) - 0.5) / 255.0 * lit;
    return max(col, 0.0);
}
"""

    private const val SPARKS = """
// Volt / Spark: a thunderstorm rolling over flooded plains at night. Towering clouds churn, lit
// from inside by flickering charge; every few seconds a branching bolt rips down to the horizon,
// floods the clouds with light and strikes the ground with a flash - all of it mirrored in the
// water below. Rain curtains sweep across, sparks drift up off the plain.

// Straight segments between random points: jagged like real lightning, not wavy.
float jag(float y, float n, float seed) {
    float i = floor(y * n);
    float f = fract(y * n);
    return mix(hash11(i + seed * 31.0), hash11(i + 1.0 + seed * 31.0), f) - 0.5;
}

float boltDist(float2 uv, float x0, float seed, float top, float bottom) {
    float y = uv.y - top;
    float x = x0 + jag(y, 6.0, seed) * 0.17 + jag(y, 19.0, seed + 5.0) * 0.05 + jag(y, 57.0, seed + 9.0) * 0.014;
    float inside = step(0.0, y) * (1.0 - smoothstep(bottom - top - 0.06, bottom - top, y));
    return abs(uv.x - x) + (1.0 - inside) * 0.25 + step(y, 0.0) * 10.0;
}

// Where bolt k strikes, and how bright it is at phase ph (seconds into its cycle).
float strike(float ph) {
    return exp(-ph * 5.0) * (0.55 + 0.45 * sin(ph * 80.0)) + 0.8 * exp(-abs(ph - 0.22) * 24.0) + 0.5 * exp(-abs(ph - 0.42) * 30.0);
}

// Cloud density and how lit its top is (x = density, y = light from above).
float2 cloud(float2 q, float t) {
    float2 w = float2(fbm3(q * 0.7 + float2(t * 0.01, 0.0)), fbm3(q * 0.7 + float2(5.2, t * 0.008)));
    float2 p = q * 2.1 + (w - 0.5) * 0.9 + float2(t * 0.025, 0.0);
    float d = fbm(p);
    float u = fbm(p + float2(0.035, -0.075));
    return float2(d, sat((d - u) * 8.0 + 0.45));
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float px = 1.0 / uRes.y;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float horizon = 0.70;

    // Bolt timing: a strike every 5 s, alternating sides of the screen.
    float cyc = 5.0;
    float k = floor(t / cyc);
    float ph = t - k * cyc;
    float flash = strike(ph);
    float bx = asp * (0.15 + 0.7 * hash11(k * 13.7));
    float boltOn = sat(flash * 1.6) * (1.0 - smoothstep(0.5, 0.7, ph));
    // Charge flickering inside the clouds between strikes.
    float pc = 1.7;
    float pk = floor(t / pc);
    float pph = t - pk * pc;
    float2 pp = float2(asp * hash11(pk * 4.7 + 2.0), 0.12 + 0.3 * hash11(pk * 8.3));
    float pulse = exp(-pph * 4.0) * (0.6 + 0.4 * sin(pph * 55.0)) * step(0.3, hash11(pk * 2.9));

    // Above the horizon draw the sky; below it, the same sky mirrored in the water.
    float water = step(horizon, uv.y);
    float2 s = uv;
    if (water > 0.5) {
        s.y = 2.0 * horizon - uv.y;
        // Ripples break the reflection up.
        s.x += 0.006 * sin(uv.y * 160.0 + t * 2.0) * (uv.y - horizon) * 8.0;
        s.y += 0.004 * sin(uv.x * 60.0 + t * 1.3);
    }

    float3 col = mix(BG * 0.5, BG * 1.4 + A * 0.04, sat(s.y / horizon));
    // The clouds: a heavy deck, thickest high up, with towers rising into it.
    float2 cq = float2(s.x, s.y * 1.3);
    float2 c = cloud(cq, t);
    float cover = smoothstep(0.36, 0.62, c.x + 0.22 * (1.0 - s.y / horizon)) * smoothstep(horizon + 0.02, horizon - 0.22, s.y);
    float3 shadow = mix(BG * 0.7, float3(0.035, 0.04, 0.055), 0.5);
    float3 lit = mix(float3(0.20, 0.21, 0.25), S * 0.35 + A * 0.05, 0.35);
    float3 cc = mix(shadow, lit, c.y * c.y);
    // Glow of a far-off town under the clouds, low on the horizon.
    col += A * 0.10 * exp(-abs(s.y - horizon + 0.03) * 14.0);
    // Lit from inside: near the bolt during a strike, and in flickering pockets.
    float near = exp(-abs(s.x - bx) * 2.2) * exp(-max(s.y - 0.1, 0.0) * 1.5);
    float glowIn = flash * near * 1.6 + pulse * exp(-length((s - pp) * float2(1.0, 1.6)) * 6.0) * 1.2;
    cc += mix(A, float3(1.0), 0.45) * glowIn * (0.35 + 0.65 * c.y) * smoothstep(0.35, 0.7, c.x);
    col = mix(col, cc, cover);
    // The whole sky brightens for an instant.
    col += mix(A, S, 0.5) * flash * 0.06 * (1.0 - cover * 0.5);

    // Distant land: two ridges along the horizon, a darker strip of shore.
    float r1 = horizon - 0.02 - 0.035 * fbm3(float2(s.x * 3.0, 1.0)) - 0.02 * vnoise(float2(s.x * 14.0, 3.0));
    float r2 = horizon - 0.004 - 0.012 * vnoise(float2(s.x * 9.0 + 4.0, 0.0));
    col = mix(col, BG * 0.55 + A * 0.02 * flash, smoothstep(r1, r1 + 0.002, s.y));
    col = mix(col, BG * 0.25, smoothstep(r2, r2 + 0.002, s.y));

    // The bolt, a fork, and the strike's flash on the ground.
    float bottom = horizon - 0.01;
    float d = boltDist(s, bx, k, 0.02, bottom);
    float by = 0.18 + 0.2 * hash11(k * 7.1);
    float bdir = hash11(k * 5.9) > 0.5 ? 1.0 : -1.0;
    float2 buv = s;
    buv.x -= (s.y - by) * 0.55 * bdir;
    float bx2 = bx + jag(by - 0.02, 6.0, k) * 0.17 + jag(by - 0.02, 19.0, k + 5.0) * 0.05;
    float d2 = boltDist(buv, bx2, k + 17.0, by, by + 0.2 + 0.12 * hash11(k));
    float core = (1.0 - smoothstep(0.6 * px, 2.2 * px, d)) + 0.7 * (1.0 - smoothstep(0.4 * px, 1.6 * px, d2));
    float halo = exp(-d * 80.0) * 0.8 + exp(-d * 14.0) * 0.22 + exp(-d2 * 100.0) * 0.45;
    float3 boltCol = float3(1.0) * core + mix(A, float3(1.0), 0.45) * halo;
    float impact = exp(-length((s - float2(bx + jag(bottom - 0.02, 6.0, k) * 0.17, bottom)) * float2(0.5, 2.5)) * 7.0);
    boltCol += mix(A, float3(1.0), 0.5) * impact * 1.8;
    col += boltCol * boltOn;

    // The water: darker, a little bluer, brighter streaks where it catches the light.
    if (water > 0.5) {
        float depth = (uv.y - horizon) / (1.0 - horizon);
        col *= 0.72 - 0.3 * depth;
        col += BG * 0.15;
        float glint = pow(sat(sin(uv.y * 300.0 - t * 3.0 + vnoise(uv * float2(8.0, 40.0)) * 6.0)), 12.0);
        col += mix(A, float3(1.0), 0.4) * glint * (flash * near * 0.5 + 0.04) * (1.0 - depth);
    }

    // Rain: curtains of streaks, seen where there's light behind them.
    float rainAmt = 0.3 + 0.7 * smoothstep(0.3, 0.7, vnoise(float2(uv.x * 1.5 - t * 0.15, 0.0)));
    float2 rp = float2(uv.x * 140.0 + uv.y * 30.0, uv.y * 3.0 + t * 7.0);
    float drop = step(0.92, hash12(floor(rp))) * smoothstep(0.5, 0.0, abs(fract(rp.x) - 0.5)) * fract(rp.y);
    float bright = dot(col, float3(0.33));
    col += mix(S, float3(1.0), 0.5) * drop * rainAmt * (0.03 + bright * 0.5 + flash * 0.08);

    // Sparks drifting up off the plain.
    float s1 = dots(uv + float2(sin(uv.y * 6.0 + t * 0.5) * 0.02, 0.0), 14.0, float2(0.0, t * 0.35), 0.3, 0.09, 1.0);
    float s2 = dots(uv, 26.0, float2(t * 0.1, t * 0.5), 0.25, 0.12, 9.0);
    col += (A * s1 * 0.6 + S * s2 * 0.25) * smoothstep(0.2, 0.75, uv.y);

    return half4(finish(col, fc), 1.0);
}
"""

    private const val LIQUID = """
// Tide / Liquid: looking up from shallow water. Light shafts sway down from the surface,
// caustic light ripples across the sand below, and specks drift in the current.

// Caustic web: the gap between the nearest and second-nearest moving cell points.
float caustic(float2 p, float t) {
    float2 i = floor(p);
    float2 f = fract(p);
    float f1 = 8.0;
    float f2 = 8.0;
    for (int y = -1; y <= 1; y++) {
        for (int x = -1; x <= 1; x++) {
            float2 g = float2(float(x), float(y));
            float2 o = hash22(i + g);
            o = 0.5 + 0.42 * sin(t * 0.55 + TAU * o);
            float d = length(g + o - f);
            if (d < f1) { f2 = f1; f1 = d; } else if (d < f2) { f2 = d; }
        }
    }
    return f2 - f1;
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    // Water: lighter towards the surface.
    float3 col = mix(BG + A * 0.16, BG * 0.8, smoothstep(0.0, 0.9, uv.y));

    // The surface: a bright, rippling band at the very top.
    float wave = sin(uv.x * 9.0 + t * 0.8) * 0.006 + sin(uv.x * 23.0 - t * 1.3) * 0.003;
    col += mix(A, S, 0.3) * 0.35 * exp(-max(uv.y - 0.02 - wave, 0.0) * 30.0);

    // Light shafts fanning down from above the screen.
    float2 src = float2(asp * 0.5 + 0.25 * sin(t * 0.05), -0.6);
    float2 d = uv - src;
    float ang = atan(d.x, d.y);
    float rays = vnoise(float2(ang * 14.0, t * 0.12)) * 0.6 + vnoise(float2(ang * 31.0 + 4.0, -t * 0.09)) * 0.4;
    rays = smoothstep(0.42, 0.95, rays) * exp(-max(length(d) - 0.6, 0.0) * 1.3);
    col += mix(A, float3(1.0), 0.25) * rays * 0.22;

    // Caustics: strongest on the "floor" (lower part), warped so the web looks liquid.
    float2 cp = float2(uv.x, uv.y * 1.6) * 3.2;
    cp += float2(vnoise(cp * 0.7 + t * 0.1), vnoise(cp * 0.7 - t * 0.1 + 5.0)) * 0.9;
    float c = caustic(cp, t);
    float web = pow(1.0 - smoothstep(0.0, 0.16, c), 4.0);
    float c2 = caustic(cp * 1.7 + 3.0, t * 1.2);
    web = web * 0.7 + 0.45 * pow(1.0 - smoothstep(0.0, 0.12, c2), 4.0);
    web *= smoothstep(0.25, 0.75, vnoise(cp * 0.45 + t * 0.05));
    float floorMask = smoothstep(0.25, 0.85, uv.y);
    col += mix(A, S, 0.35) * web * (0.02 + 0.2 * floorMask);

    // Drifting specks, two depths.
    float2 cur = float2(t * 0.03, -t * 0.012);
    col += mix(A, float3(1.0), 0.5) * dots(uv, 22.0, cur * 22.0, 0.25, 0.1, 3.0) * 0.35;
    col += S * dots(uv, 9.0, cur * 14.0 + float2(0.0, sin(t * 0.3)), 0.18, 0.08, 11.0) * 0.4;

    return half4(finish(col, fc), 1.0);
}
