    private const val RETRO_GRID = """
// Synthwave / Retro wave: a striped sun sinking behind dark ridges with neon edges, and a
// glowing grid rolling towards you across the plain.
half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float px = 1.0 / uRes.y;
    float h = 0.6;

    float3 col;
    if (uv.y < h) {
        // Sky: deep at the top, warm near the horizon, a few stars.
        float k = uv.y / h;
        col = mix(BG * 0.9, mix(BG, A, 0.35), pow(k, 2.2));
        col += float3(1.0) * dots(uv, 30.0, float2(t * 0.02, 0.0), 0.3, 0.06, 2.0) * 0.5 * (1.0 - k);

        // Sun with slats that slide down.
        float2 sc = float2(asp * 0.5, h - 0.14);
        float sr = 0.25;
        float sd = length(uv - sc);
        float sy = (uv.y - sc.y) / sr; // -1 top .. 1 bottom
        float slat = 1.0;
        if (sy > -0.1) {
            float s = fract(sy * 5.0 - t * 0.25);
            float w = 0.12 + 0.45 * sat((sy + 0.1) / 1.1);
            slat = smoothstep(w - 0.04, w, s);
        }
        float3 sunCol = mix(S, A, sat(sy * 0.5 + 0.5));
        float disc = (1.0 - smoothstep(sr - px * 1.5, sr, sd)) * slat;
        col = mix(col, sunCol, disc);
        col += mix(A, S, 0.4) * exp(-max(sd - sr, 0.0) * 7.0) * 0.28;

        // Ridges in front of the sun, edged with neon.
        float x = uv.x;
        float ridge = h - 0.035 - 0.09 * pow(fbm(float2(x * 2.2 + 7.0, 1.0)), 1.6) - 0.05 * sqf(1.0 - abs(2.0 * vnoise(float2(x * 6.0, 3.0)) - 1.0));
        float far = h - 0.02 - 0.05 * fbm3(float2(x * 4.0 + 20.0, 2.0));
        if (uv.y > far) col = mix(col, BG * 1.25 + A * 0.06, 0.85);
        if (uv.y > ridge) {
            col = BG * 0.7;
            col += A * exp(-(uv.y - ridge) * 140.0) * 0.8;
        }
    } else {
        // The plain: a perspective grid scrolling towards the viewer.
        float dy = uv.y - h;
        float z = 0.32 / (dy + 0.002);
        float xw = (uv.x - asp * 0.5) * z;
        float zw = z + t * 1.6;
        float fx = z * px * 1.6;
        float fz = z * z / 0.32 * px * 1.6;
        float dx = abs(fract(xw + 0.5) - 0.5);
        float dz = abs(fract(zw * 0.5 + 0.5) - 0.5) * 2.0;
        float lx = (1.0 - smoothstep(0.0, fx * 1.5, dx)) + 0.35 * exp(-dx / (fx * 6.0));
        float lz = (1.0 - smoothstep(0.0, fz * 1.5, dz)) + 0.35 * exp(-dz / (fz * 6.0));
        lx *= 1.0 - smoothstep(0.08, 0.45, fx);
        lz *= 1.0 - smoothstep(0.08, 0.45, fz);
        float dist = exp(-z * 0.05);
        col = BG * 0.6 + mix(A, S, 0.25) * 0.08 * exp(-dy * 10.0);
        col += mix(S, A, sat(dy * 3.0)) * sat(lx + lz) * (0.25 + 0.75 * dist) * 0.85;
        // Sun reflected on the ground.
        float refl = exp(-abs(uv.x - asp * 0.5) * 9.0) * exp(-dy * 6.0);
        col += mix(S, A, 0.5) * refl * 0.25 * (0.7 + 0.3 * sin(dy * 120.0 - t * 2.0));
    }
    // Horizon haze.
    col += mix(A, S, 0.5) * exp(-abs(uv.y - h) * 45.0) * 0.35;
    return half4(finish(col, fc), 1.0);
}
"""

    private const val LEAVES = """
// Matcha / Sprout: a quiet forest clearing. Sun filters through the canopy in shafts, soft
// out-of-focus light hangs in the air and leaves tumble down at three depths.
// Leaves / petals tumbling down (or along the wind). One per cell at most, so it stays cheap.
// kind 0 = leaf, 1 = petal. Returns colour (not premultiplied) and coverage.
float4 fallingLayer(float2 uv, float scale, float2 vel, float sway, float seed, float kind, float blur, float3 c1, float3 c2) {
    float2 p = uv * scale - vel * uTime;
    p.x += sway * sin(uTime * 0.55 + p.y * 1.7 + seed);
    float2 id = floor(p);
    float2 f = fract(p) - 0.5;
    float2 r = hash22(id + seed);
    if (r.x > 0.5) return float4(0.0);
    float2 o = (hash22(id + seed + 3.7) - 0.5) * 0.36;
    float2 q = f - o;
    float dir = r.x > 0.25 ? 1.0 : -1.0;
    q = rot(uTime * (0.35 + 0.7 * r.y) * dir + r.y * TAU) * q;
    float flip = cos(uTime * (0.7 + r.x) + r.y * 9.0);
    q.y /= max(abs(flip), 0.22);
    float d;
    float shade;
    if (kind < 0.5) {
        float L = 0.2;
        float x = q.x / L;
        float w = 0.075 * (1.0 - x * x) * (1.0 + 0.25 * x);
        d = max(abs(q.y) - w, abs(q.x) - L);
        float vein = (1.0 - smoothstep(0.0, 0.01, abs(q.y))) * step(abs(q.x), L * 0.85);
        shade = (0.8 + 0.3 * sign(q.y) * flip) * (1.0 - 0.3 * vein);
    } else {
        float w = 0.1 * (0.5 + 0.5 * sat((q.x + 0.15) / 0.3));
        d = (length(float2(q.x / 0.15, q.y / w)) - 1.0) * 0.07;
        d = max(d, -(length(q - float2(0.165, 0.0)) - 0.04));
        shade = 0.85 + 0.25 * (q.x / 0.15) * flip;
    }
    float a = 1.0 - smoothstep(-blur, blur, d);
    return float4(mix(c1, c2, r.y) * shade, a);
}

float bokeh(float2 uv, float scale, float2 drift, float seed, float soft) {
    float2 p = uv * scale + drift;
    float2 id = floor(p);
    float2 f = fract(p) - 0.5;
    float2 r = hash22(id + seed);
    if (r.x > 0.45) return 0.0;
    float2 o = (hash22(id + seed + 1.3) - 0.5) * 0.4;
    float rad = 0.12 + 0.16 * r.y;
    float d = length(f - o);
    float pulse = 0.6 + 0.4 * sin(uTime * 0.4 + r.y * 20.0);
    return (1.0 - smoothstep(rad - soft, rad, d)) * (0.6 + 0.4 * smoothstep(rad * 0.4, rad, d)) * pulse;
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    float3 col = mix(BG + A * 0.12, BG * 0.85, smoothstep(0.0, 1.0, uv.y));

    // Light shafts slanting in from the top left.
    float s = uv.x * 0.8 + uv.y * 0.55;
    float shafts = vnoise(float2(s * 9.0, t * 0.04)) * 0.6 + vnoise(float2(s * 21.0, t * 0.06 + 3.0)) * 0.4;
    shafts = smoothstep(0.5, 0.95, shafts) * (1.0 - smoothstep(0.0, 0.9, uv.y));
    col += mix(S, float3(1.0), 0.3) * shafts * 0.13;

    // Out-of-focus light: two depths.
    col += mix(A, S, 0.5) * bokeh(uv, 3.0, float2(t * 0.02, -t * 0.01), 2.0, 0.05) * 0.07;
    col += S * bokeh(uv, 5.5, float2(-t * 0.03, -t * 0.015), 8.0, 0.03) * 0.06;

    // Leaves: far (small, soft), middle, near (larger, sharp).
    float4 l = fallingLayer(uv, 11.0, float2(0.25, 0.55), 0.35, 1.0, 0.0, 0.04, A * 0.7, S * 0.7);
    col = mix(col, l.rgb * 0.6, l.a * 0.45);
    l = fallingLayer(uv, 7.0, float2(0.2, 0.45), 0.3, 5.0, 0.0, 0.02, A, mix(A, S, 0.6));
    col = mix(col, l.rgb * 0.85, l.a * 0.7);
    l = fallingLayer(uv, 4.2, float2(0.15, 0.32), 0.25, 9.0, 0.0, 0.01, A * 1.05, S);
    col = mix(col, l.rgb, l.a * 0.85);

    return half4(finish(col, fc), 1.0);
}
"""

    private const val MINIMAL = """
// Mono / Minimal console: a light sculpture in an endless dark room. Three thin rings of light turn
// slowly inside each other like a gyroscope, floating over a black mirror floor that reflects them,
// and a perspective grid of dots fades away to the horizon. Now and then a soft beam sweeps round the
// floor and lights the dots it passes. Everything else stays pure black (OLED friendly).

// Distance (in screen units) from p to the ellipse c + U cos a + V sin a (a projected circle): a few
// Newton steps on the angle, which stays right even when the ring is seen almost edge-on.
float2 ellipseD(float2 p, float2 c, float2 U, float2 V) {
    float2 d = p - c;
    float det = U.x * V.y - U.y * V.x;
    float sd = abs(det) > 1e-5 ? det : (det < 0.0 ? -1e-5 : 1e-5);
    float2 q = float2(V.y * d.x - V.x * d.y, -U.y * d.x + U.x * d.y) / sd;
    float a = atan(q.y, q.x);
    float best = 1e3;
    float bestA = a;
    for (int i = 0; i < 5; i++) {
        float ca = cos(a);
        float sa = sin(a);
        float2 P = U * ca + V * sa - d;
        float dist = length(P);
        if (dist < best) { best = dist; bestA = a; }
        float2 P1 = V * ca - U * sa;
        float2 P2 = -U * ca - V * sa;
        float f = dot(P, P1);
        float fp = max(dot(P1, P1) + dot(P, P2), dot(P1, P1) * 0.3 + 1e-6);
        a -= clamp(f / fp, -0.6, 0.6);
    }
    float last = length(U * cos(a) + V * sin(a) - d);
    if (last < best) { best = last; bestA = a; }
    return float2(best, bestA);
}

// Projects point w with the camera (ro, basis) to screen units (heights). z = depth.
float3 proj(float3 w, float3 ro, float3 fw, float3 rt, float3 up, float fov) {
    float3 v = w - ro;
    float z = dot(v, fw);
    return float3(dot(v, rt), dot(v, up), z) / float3(z * fov, z * fov, 1.0);
}

// Glow of ring i (centre c, radius r, tilted by its own spin) as seen on screen at sp.
float ring(float2 sp, float3 c, float r, float a, float b, float mirror, float3 ro, float3 fw, float3 rt, float3 up, float fov, float px) {
    float3 u = float3(cos(a), 0.0, sin(a));
    float3 v = float3(-sin(a) * sin(b), cos(b), cos(a) * sin(b));
    float3 cc = c;
    if (mirror > 0.5) { cc.y = -cc.y; u.y = -u.y; v.y = -v.y; }
    float3 pc = proj(cc, ro, fw, rt, up, fov);
    float3 pu = proj(cc + u * r, ro, fw, rt, up, fov);
    float3 pv = proj(cc + v * r, ro, fw, rt, up, fov);
    float2 e = ellipseD(sp, pc.xy, pu.xy - pc.xy, pv.xy - pc.xy);
    float d = e.x;
    float soft = 1.0 + mirror * 4.0;
    // A brighter glint travels round each ring.
    float glint = 0.7 + 0.9 * exp(-sqf(abs(mod(e.y - uTime * 0.9 - a * 3.0 + PI, TAU) - PI)) * 3.0);
    return ((1.0 - smoothstep(0.6 * px * soft, 1.8 * px * soft, d)) * (1.0 - mirror * 0.6) + exp(-d / (0.012 * soft)) * 0.35) * glint + exp(-d / (0.06 * soft)) * 0.08;
}

half4 main(float2 fc) {
    float t = uTime;
    float2 sp = (fc - 0.5 * uRes) / uRes.y;
    sp.y = -sp.y;
    float px = 1.0 / uRes.y;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    float3 ro = float3(0.45 * sin(t * 0.04), 1.30 + 0.06 * sin(t * 0.05), 3.4);
    float3 ta = float3(0.0, 0.70, 0.0);
    float3 fw = normalize(ta - ro);
    float3 rt = normalize(cross(fw, float3(0.0, 1.0, 0.0)));
    float3 up = cross(rt, fw);
    float fov = 0.62;
    float3 rd = normalize(fw + fov * (sp.x * rt + sp.y * up));

    float3 col = BG;

    // The floor: a mirror-black plane with a grid of dots fading towards the horizon.
    if (rd.y < 0.0) {
        float tf = -ro.y / rd.y;
        float2 f = ro.xz + rd.xz * tf;
        float2 g = f * 2.2;
        float2 gp = fract(g) - 0.5;
        float size = clamp(tf * 0.004 * uRes.y / 540.0, 0.02, 0.2);
        float dotM = 1.0 - smoothstep(0.03, 0.03 + size, length(gp));
        float fade = exp(-tf * 0.16) * smoothstep(0.0, 0.3, -rd.y * 3.0);
        // The beam: a slow turn round the sculpture, every 14 s.
        float ang = atan(f.y, f.x);
        float beamA = t * TAU / 14.0;
        float da = abs(mod(ang - beamA + PI, TAU) - PI);
        float beam = exp(-da * da * 30.0) * exp(-length(f) * 0.25);
        col += S * dotM * fade * 0.16;
        col += A * dotM * beam * 0.9 * fade * 1.5;
        col += A * beam * fade * 0.025;
        // A soft pool of light under the rings.
        col += A * 0.05 * exp(-length(f - float2(0.0, 0.0)) * 2.2) * fade;
    }

    // Three rings, nested, each turning on its own axis; and their reflections in the floor.
    float3 c = float3(0.0, 1.0 + 0.05 * sin(t * 0.6), 0.0);
    float glowSum = 0.0;
    float refl = 0.0;
    for (int i = 0; i < 3; i++) {
        float fi = float(i);
        float r = 0.62 - fi * 0.16;
        float a = t * (0.11 + fi * 0.05) + fi * 1.9;
        float b = 1.2 + 0.5 * sin(t * (0.07 + fi * 0.03) + fi * 2.0);
        glowSum += ring(sp, c, r, a, b, 0.0, ro, fw, rt, up, fov, px) * (1.0 - fi * 0.18);
        if (rd.y < 0.0) refl += ring(sp, c, r, a, b, 1.0, ro, fw, rt, up, fov, px) * (1.0 - fi * 0.18);
    }
    // The core: a small bright point that breathes.
    float3 pc = proj(c, ro, fw, rt, up, fov);
    float cd = length(sp - pc.xy);
    float core = exp(-cd / 0.006) + exp(-cd / 0.03) * 0.25 * (0.8 + 0.2 * sin(t * 1.3));
    float3 ringCol = mix(A, S, 0.25);
    col += ringCol * glowSum + A * core;
    // Reflections fade with distance from the floor line.
    col += ringCol * refl * 0.30;

    // A few motes of dust in the light.
    float mote = dots(sp + float2(t * 0.003, 0.0), 30.0, float2(0.0, -t * 0.02), 0.25, 0.05, 3.0);
    col += S * mote * 0.18 * exp(-length(sp - pc.xy) * 2.5);

    return half4(finish(col, fc), 1.0);
}
"""

    private const val BUBBLES = """
// Torrent / Deep sea: deep under water, looking up at the light. The surface ripples far above,
// shafts of sunlight sway down through the blue, caustics dance over the rocks of the seabed where
// kelp sways, and streams of bubbles wobble up from vents - each a little glass sphere catching the
// light. Glowing jellyfish pulse as they drift, trailing their tentacles, and marine snow sinks
// slowly through it all.

// Bright web of light on the seabed (after the well-known tileable caustic).
float caustic(float2 p, float t) {
    p = mod(p, TAU) - 250.0;
    float2 i = p;
    float c = 1.0;
    float inten = 0.005;
    for (int n = 0; n < 4; n++) {
        float tt = t * (1.0 - (3.5 / float(n + 1)));
        i = p + float2(cos(tt - i.x) + sin(tt + i.y), sin(tt - i.y) + cos(tt + i.x));
        c += 1.0 / length(float2(p.x / (sin(i.x + tt) / inten), p.y / (cos(i.y + tt) / inten)));
    }
    c /= 4.0;
    c = 1.17 - pow(max(c, 0.0), 1.4);
    return min(pow(abs(c), 8.0), 2.0);
}

// One layer of bubbles. Returns light (glass sphere: dark core, bright rim, highlight).
float bubbleLayer(float2 uv, float scale, float speed, float seed, float t, float density) {
    float2 p = uv * scale + float2(0.0, t * speed);
    float2 id = floor(p);
    float2 r = hash22(id + seed);
    if (r.x > density) return 0.0;
    float2 f = fract(p) - 0.5;
    float2 o = (hash22(id + seed + 2.2) - 0.5) * 0.4;
    o.x += 0.08 * sin(t * (1.5 + r.y * 2.0) + r.x * 30.0);
    float rad = 0.06 + 0.12 * r.y;
    float2 q = f - o;
    q.x *= 1.0 + 0.07 * sin(t * 4.0 + r.y * 10.0);
    float d = length(q) / rad;
    if (d > 1.15) return 0.0;
    float edge = 1.5 / (uRes.y / scale) / rad;
    float inside = 1.0 - smoothstep(1.0 - edge, 1.0, d);
    float fres = pow(sat(d), 4.0);
    float hl = exp(-length(q / rad - float2(-0.38, -0.42)) * 9.0);
    float hl2 = exp(-length(q / rad - float2(0.35, 0.45)) * 14.0) * 0.4;
    return inside * (0.08 + fres * 0.8 + hl * 1.2 + hl2);
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float px = 1.5 / uRes.y;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float3 water = mix(A, float3(0.1, 0.45, 0.6), 0.4);

    // Water: brighter up towards the light, deep and dark below.
    float3 col = mix(water * 0.55 + BG, BG * 0.6, smoothstep(0.0, 1.0, uv.y));

    // The surface far above: a bright rippling sheet near the top.
    float2 sp = float2(uv.x * 1.5, uv.y * 6.0);
    float surf = caustic(sp * 3.0 + float2(t * 0.1, 0.0), t * 0.4);
    col += mix(water, float3(1.0), 0.5) * (0.25 + surf * 0.6) * exp(-uv.y * 9.0);

    // Shafts of light swaying down from the surface.
    float2 d = uv - float2(asp * 0.42 + 0.15 * sin(t * 0.05), -0.6);
    float ang = atan(d.x, d.y);
    float rays = vnoise(float2(ang * 14.0, t * 0.12)) * 0.6 + vnoise(float2(ang * 31.0, -t * 0.09 + 2.0)) * 0.4;
    float shaft = smoothstep(0.42, 0.95, rays) * exp(-max(length(d) - 0.6, 0.0) * 1.4);
    col += mix(water, float3(0.9, 1.0, 1.0), 0.4) * shaft * 0.32;

    // Far haze of particles, then the nearer marine snow.
    col += mix(water, float3(1.0), 0.3) * dots(uv, 60.0, float2(t * 0.02, -t * 0.03), 0.3, 0.06, 6.0) * 0.18;

    // Jellyfish: pulsing bells drifting up, glowing in the secondary colour, tentacles trailing.
    for (int i = 0; i < 3; i++) {
        float fi = float(i);
        float per = 40.0 + 12.0 * fi;
        float ph = fract(t / per + hash11(fi * 3.7));
        float2 jc = float2(asp * (0.18 + 0.32 * fi + 0.06 * sin(t * 0.1 + fi)), 1.1 - ph * 1.4);
        float sz = 0.045 + 0.02 * hash11(fi * 9.1);
        float pulse = 0.5 + 0.5 * sin(t * 2.2 + fi * 2.0);
        float2 q = (uv - jc) / sz;
        q.x *= 1.0 + 0.18 * pulse;
        q.y *= 1.0 - 0.12 * pulse;
        float bell = length(q * float2(1.0, 1.35)) - 1.0;
        bell = max(bell, q.y - 0.15);
        float3 jcol = mix(S, float3(1.0), 0.25);
        float inside = smoothstep(0.08, -0.08, bell);
        float rimJ = exp(-abs(bell) * 10.0) * step(q.y, 0.2);
        col += jcol * (inside * (0.12 + 0.18 * (1.0 + q.y) * pulse) + rimJ * 0.35);
        col += jcol * 0.12 * exp(-length(uv - jc) * 14.0);
        // Tentacles: wavy lines hanging below the bell.
        for (int k = 0; k < 4; k++) {
            float fk = float(k);
            float tx = (fk - 1.5) * 0.45;
            float ty = q.y - 0.15;
            if (ty > 0.0 && ty < 4.5) {
                float wav = tx + 0.25 * sin(ty * 2.2 - t * 2.5 + fk * 1.3) * (ty / 4.5 + 0.2);
                float dd = abs(q.x - wav) * sz;
                col += jcol * (1.0 - smoothstep(0.0, px * 1.2, dd)) * (1.0 - ty / 4.5) * 0.4;
            }
        }
    }

    // The seabed: rocks in silhouette with caustics dancing on their tops, and swaying kelp.
    float bed = 0.86 - 0.05 * fbm3(float2(uv.x * 3.0, 1.0)) - 0.035 * abs(sin(uv.x * 5.0 + 1.0));
    float cs = caustic(float2(uv.x * 4.0, uv.y * 10.0) + float2(t * 0.05, 0.0), t * 0.5);
    float onBed = smoothstep(bed, bed + px, uv.y);
    float3 rock = BG * 0.5 + water * 0.06 * (0.6 + 0.4 * vnoise(uv * 40.0));
    rock += mix(water, float3(1.0), 0.5) * cs * 0.5 * exp(-(uv.y - bed) * 25.0);
    col = mix(col, rock, onBed);
    // Kelp: tall ribbons rooted in the bed, swaying, lit on their upper edges.
    for (int i = 0; i < 6; i++) {
        float fi = float(i);
        float kx = asp * (0.05 + fi * 0.17 + 0.05 * hash11(fi * 4.4));
        float kh = 0.25 + 0.2 * hash11(fi * 2.3);
        float y = (0.9 - uv.y) / kh;
        if (y > 0.0 && y < 1.0) {
            float sway = 0.04 * sin(t * 0.8 + fi + y * 3.0) * y * y;
            float wdt = 0.010 * (1.0 - y * 0.6) * (0.8 + 0.4 * sin(y * 20.0 + fi));
            float kd = abs(uv.x - kx - sway) - wdt;
            float3 kc = mix(float3(0.04, 0.12, 0.08), water * 0.3, y * 0.5) + mix(water, float3(1.0), 0.4) * 0.15 * exp(-abs(kd + wdt * 0.5) * 300.0) * y;
            col = mix(col, kc, smoothstep(px, -px, kd));
        }
    }

    // Streams of bubbles rising from two vents, plus loose ones at three depths.
    for (int v = 0; v < 2; v++) {
        float fv = float(v);
        float vx = asp * (0.3 + 0.42 * fv);
        float2 bq = float2((uv.x - vx) * 9.0 + 0.5, uv.y);
        if (abs(uv.x - vx) < 0.06) col += mix(water, float3(1.0), 0.6) * bubbleLayer(float2(bq.x / 9.0, uv.y), 9.0, 1.4, 20.0 + fv, t, 0.9) * 0.5;
    }
    col += mix(water, float3(1.0), 0.4) * bubbleLayer(uv, 13.0, 0.9, 1.0, t, 0.35) * 0.30;
    col += mix(water, float3(1.0), 0.5) * bubbleLayer(uv, 7.0, 0.6, 4.0, t, 0.3) * 0.45;
    col += mix(S, float3(1.0), 0.4) * bubbleLayer(uv, 4.0, 0.38, 9.0, t, 0.25) * 0.6;

    // Marine snow drifting down, nearest the camera.
    col += float3(0.9, 1.0, 1.0) * dots(uv, 24.0, float2(sin(t * 0.2) * 0.3, -t * 0.12), 0.22, 0.09, 13.0) * 0.28;

    return half4(finish(col, fc), 1.0);
}
"""

    private const val PSY_WAVES = """
// Mind: a psychic orb hovering over a still, glossy pool. The orb swirls with light inside; rings of
// force spread from under it and from two wandering points, so the pool's mirror surface ripples in
// interfering waves with an oily, iridescent sheen. Stones float round the orb, lit by it, and
// everything - orb, stones, the dark sky - is reflected in the water.

float sphereHit(float3 ro, float3 rd, float3 c, float r) {
    float3 oc = ro - c;
    float b = dot(oc, rd);
    float h = b * b - dot(oc, oc) + r * r;
    if (h < 0.0) return -1.0;
    return -b - sqrt(h);
}

// One of the floating stones: its centre at time t.
float3 stonePos(float i, float t, float3 orb) {
    float a = t * (0.25 + 0.06 * i) + i * 1.9;
    float r = 0.75 + 0.15 * hash11(i * 3.3);
    return orb + float3(cos(a) * r, 0.12 * sin(t * 0.7 + i * 2.1) + (hash11(i * 5.1) - 0.5) * 0.3, sin(a) * r * 0.8);
}

// The pool's height and its slope (x = height, yz = d/dx, d/dz) at p.
float3 pool(float2 p, float t, float2 orbXZ) {
    float3 h = float3(0.0);
    for (int i = 0; i < 3; i++) {
        float fi = float(i);
        float2 c = i == 0 ? orbXZ : float2(1.6 * sin(t * (0.07 + fi * 0.03) + fi * 2.0), -0.8 + 1.2 * cos(t * (0.05 + fi * 0.02) + fi));
        float k = i == 0 ? 18.0 : 13.0;
        float amp = i == 0 ? 0.02 : 0.011;
        float2 d = p - c;
        float r = max(length(d), 1e-3);
        float fall = exp(-r * 0.9);
        float ph = k * r - t * (i == 0 ? 2.2 : 1.6);
        float s = sin(ph);
        float cs = cos(ph);
        h.x += amp * s * fall;
        float dr = amp * fall * (k * cs - 0.9 * s);
        h.yz += dr * d / r;
    }
    return h;
}

float3 skyCol(float3 rd, float3 A, float3 S, float3 BG, float t) {
    float y = rd.y;
    float3 c = mix(BG * 1.6 + A * 0.05, BG * 0.6, sat(y * 2.0));
    float2 q = rd.xz / max(rd.y + 0.35, 0.05);
    c += mix(A, S, 0.5) * 0.10 * fbm3(q * 1.5 + float2(t * 0.01, 0.0)) * sat(y * 3.0);
    float st = dots(q * 0.6, 40.0, float2(0.0), 0.15, 0.05, 4.0);
    c += st * 0.5 * sat(y * 4.0);
    return c;
}

half4 main(float2 fc) {
    float t = uTime;
    float2 sp = (fc - 0.5 * uRes) / uRes.y;
    sp.y = -sp.y;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    float3 ro = float3(0.3 * sin(t * 0.05), 0.36, 3.0);
    float3 ta = float3(0.0, 0.62, -2.2);
    float3 fw = normalize(ta - ro);
    float3 rt = normalize(cross(fw, float3(0.0, 1.0, 0.0)));
    float3 up = cross(rt, fw);
    float3 rd = normalize(fw + 0.75 * (sp.x * rt + sp.y * up));

    float3 orb = float3(0.0, 0.86 + 0.06 * sin(t * 0.8), -2.2);
    float orbR = 0.42;
    float3 orbCol = mix(A, S, 0.35);

    float3 col = skyCol(rd, A, S, BG, t);
    float tHit = 1e4;
    float3 surf = float3(0.0);
    float kind = 0.0; // 1 orb, 2 stone, 3 pool

    float to = sphereHit(ro, rd, orb, orbR);
    if (to > 0.0) { tHit = to; kind = 1.0; }
    for (int i = 0; i < 5; i++) {
        float fi = float(i);
        float3 c = stonePos(fi, t, orb);
        float r = 0.045 + 0.045 * hash11(fi * 7.7);
        float ts = sphereHit(ro, rd, c, r);
        if (ts > 0.0 && ts < tHit) { tHit = ts; kind = 2.0; surf = c; }
    }
    if (rd.y < 0.0) {
        float tp = -ro.y / rd.y;
        if (tp < tHit) { tHit = tp; kind = 3.0; }
    }

    float3 p = ro + rd * tHit;
    if (kind > 2.5) {
        // ---- the pool ----
        float3 h = pool(p.xz, t, orb.xz);
        float3 n = normalize(float3(-h.y, 1.0, -h.z));
        float3 r = reflect(rd, n);
        // Reflected: the orb, the stones, or the sky.
        float3 refl = skyCol(r, A, S, BG, t);
        // The orb's halo, seen in the water too.
        float3 oc = orb - p;
        float ca = max(dot(oc, r), 0.0);
        float miss = length(oc - r * ca);
        refl += orbCol * (exp(-miss * 2.5) * 0.35 + exp(-miss * 8.0) * 0.3);
        float tr = sphereHit(p, r, orb, orbR);
        if (tr > 0.0) {
            float3 q = p + r * tr;
            float3 on = normalize(q - orb);
            refl = orbCol * (0.8 + 0.6 * sqf(1.0 - sat(dot(on, -r)))) + float3(1.0) * 0.4 * pow(sat(dot(on, -r)), 6.0);
        }
        for (int i = 0; i < 5; i++) {
            float fi = float(i);
            float3 c = stonePos(fi, t, orb);
            float rr = 0.045 + 0.045 * hash11(fi * 7.7);
            if (sphereHit(p, r, c, rr) > 0.0) refl = BG * 0.6 + orbCol * 0.15;
        }
        float fres = 0.06 + 0.94 * pow(1.0 - sat(dot(n, -rd)), 5.0);
        // Oily sheen: colour shifts with the ripples' height and the viewing angle.
        float film = h.x * 30.0 + dot(n, -rd) * 2.0 + t * 0.05;
        float3 iri = 0.5 + 0.5 * cos(TAU * (film + float3(0.0, 0.33, 0.67)));
        float3 sheen = mix(A, S, iri.r) * (0.5 + 0.5 * iri.g);
        float3 deep = BG * 0.5;
        // Light from the orb on the surface.
        float3 lo = orb - p;
        float ld = length(lo);
        lo /= ld;
        float3 hv = normalize(lo - rd);
        float spec = pow(sat(dot(n, hv)), 90.0);
        float3 lit = orbCol * (sat(dot(n, lo)) * 0.25 / (1.0 + ld * ld)) + float3(1.0, 0.95, 1.0) * spec * 1.4 / (0.5 + ld * ld);
        col = deep + refl * fres + sheen * 0.10 * (0.4 + fres) + lit;
        // Fade into the dark far off.
        float far = sat((tHit - 4.0) / 14.0);
        col = mix(col, skyCol(float3(rd.x, 0.0, rd.z), A, S, BG, t), far * far);
    } else if (kind > 1.5) {
        // ---- a floating stone, lit by the orb ----
        float3 n = normalize(p - surf);
        n = normalize(n + 0.25 * (float3(vnoise(p.xy * 40.0), vnoise(p.yz * 40.0), vnoise(p.zx * 40.0)) - 0.5));
        float3 lo = normalize(orb - p);
        float dif = sat(dot(n, lo));
        col = BG * 0.4 + uSurf.rgb * 0.3 + orbCol * dif * 0.9 + mix(A, S, 0.5) * pow(1.0 - sat(dot(n, -rd)), 3.0) * 0.15;
    } else if (kind > 0.5) {
        // ---- the orb: glass sphere with swirling light inside ----
        float3 n = normalize(p - orb);
        float fr = pow(1.0 - sat(dot(n, -rd)), 2.5);
        float3 q = n;
        float sw = fbm(float2(atan(q.z, q.x) * 1.5 + t * 0.4, q.y * 3.0 - t * 0.2) + fbm3(q.xy * 3.0 + t * 0.3));
        float3 inner = mix(orbCol * 0.6, mix(S, float3(1.0), 0.5), smoothstep(0.45, 0.85, sw));
        inner *= 0.7 + 0.5 * (1.0 - fr);
        float core = pow(sat(dot(n, -rd)), 6.0);
        col = inner + float3(1.0) * core * 0.6 + A * fr * 0.9;
        // A window-like highlight on the glass.
        float3 hl = normalize(float3(-0.5, 0.7, 0.6) - rd);
        col += float3(1.0) * pow(sat(dot(n, hl)), 60.0) * 0.6;
    }

    // The orb's glow in the air, and rings of force flashing out now and then.
    float3 po = float3(dot(orb - ro, rt), dot(orb - ro, up), dot(orb - ro, fw));
    float2 os = po.xy / (po.z * 0.75);
    float od = length(sp - os);
    col += orbCol * (exp(-od * 6.0) * 0.35 + exp(-od * 18.0) * 0.4) * step(kind, 0.5 + step(2.5, kind) * 3.0);

    return half4(finish(col, fc), 1.0);
}
"""

    private const val WISPS = """
// Phantom: a haunted ruin under a veiled moon. Layer behind layer - a far castle, a row of broken
// arches, crooked dead trees and leaning gravestones - with fog banks drifting between them. Pale
// wisps float through the ruins on slow looping paths, trailing light and lighting the fog round
// them; the moon rims the stones and a faint shimmer runs over the wet ground.

// One wisp's position at time t (screen heights).
float2 wispPos(float i, float t, float asp) {
    return float2(
        asp * (0.1 + 0.8 * hash11(i * 3.1)) + 0.25 * sin(t * (0.08 + 0.05 * hash11(i)) + i * 1.7),
        0.40 + 0.28 * hash11(i * 7.3) + 0.07 * sin(t * (0.13 + 0.06 * hash11(i + 4.0)) + i * 2.3));
}

// Skyline of the far castle: towers and walls with battlements. Returns the top (y) at x.
float castleTop(float x) {
    float cell = floor(x / 0.09);
    float h = hash11(cell * 1.3);
    float top = 0.47 - 0.05 * h - 0.09 * step(0.72, h);
    // Battlements.
    top += 0.008 * step(0.5, fract(x / 0.018)) * step(h, 0.72);
    // Pointed roofs on the towers.
    float fx = abs(fract(x / 0.09) - 0.5);
    top -= step(0.72, h) * max(0.0, 0.05 - fx * 0.2) * 1.5;
    return top;
}

// The broken arches: negative inside the stone.
float arches(float2 p) {
    float w = 0.34;
    float cell = floor(p.x / w);
    float2 q = float2(fract(p.x / w) - 0.5, p.y) * float2(w, 1.0);
    float h = hash11(cell * 4.1 + 2.0);
    float top = 0.36 + 0.12 * h;
    float wall = max(-q.y + top, q.y - 0.74);
    // The arch opening.
    float open = min(length(float2(q.x, q.y - 0.54)) - 0.115, max(abs(q.x) - 0.115, -(q.y - 0.54)));
    float d = max(wall, -open);
    // Broken top: a jagged line.
    float brk = top + 0.05 * hash11(floor(p.x / 0.03) + cell) * step(0.4, h);
    d = max(d, -(p.y - brk));
    return d;
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float px = 1.5 / uRes.y;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    // Sky: deep violet, lighter round the moon, thin clouds sliding over it.
    float2 mc = float2(asp * 0.72, 0.2);
    float md = length(uv - mc);
    float3 col = mix(BG * 2.2 + A * 0.06, BG * 0.8, sat(uv.y * 1.3));
    col += mix(A, float3(0.9, 0.9, 1.0), 0.5) * 0.18 * exp(-md * 3.0);
    float moon = smoothstep(0.082, 0.078, md);
    float3 moonCol = float3(0.86, 0.86, 0.95) * (0.85 + 0.15 * vnoise((uv - mc) * 40.0));
    col = mix(col, moonCol, moon);
    float veil = fbm3(float2(uv.x * 2.5 - t * 0.02, uv.y * 7.0));
    col = mix(col, BG * 1.5 + A * 0.05, smoothstep(0.45, 0.8, veil) * 0.7 * (1.0 - smoothstep(0.35, 0.5, uv.y)));
    col += dots(uv, 70.0, float2(0.0), 0.12, 0.04, 3.0) * 0.5 * smoothstep(0.4, 0.0, uv.y) * smoothstep(0.08, 0.2, md);

    float3 fogCol = mix(BG * 2.5, A * 0.3 + S * 0.1, 0.35);
    // Light of the wisps, summed once (they light every layer of fog).
    float3 wl = float3(0.0);
    for (int i = 0; i < 6; i++) {
        float fi = float(i);
        float2 wp = wispPos(fi, t, asp);
        float3 wc = mix(A, S, step(0.5, hash11(fi * 9.1)));
        wl += wc * exp(-length(uv - wp) * 4.0) * 1.3;
    }

    // Far castle.
    float ct = castleTop(uv.x + t * 0.002);
    float castle = smoothstep(ct, ct + px, uv.y);
    col = mix(col, BG * 1.1 + A * 0.03, castle);
    // Lit windows in the castle, a few.
    float2 wcf = float2(uv.x / 0.013, uv.y / 0.02);
    float2 wcell = floor(wcf);
    float win = step(0.95, hash12(wcell)) * castle * step(ct + 0.02, uv.y) * step(uv.y, 0.52) * step(0.35, fract(wcf.x)) * step(0.3, fract(wcf.y));
    col += float3(1.0, 0.75, 0.4) * win * 0.35 * (0.6 + 0.4 * sin(t * 0.7 + wcell.x));
