half4 main(float2 fc) {
    float2 uv0 = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 BG = uBg.rgb;

    // ---- Form: 0 = first (gold), 1 = evolved (blue). 150 s cycle: 45 s gold, 30 s rising, 45 s blue, 30 s back.
    float cy = mod(t, 150.0);
    float form = smoothstep(45.0, 75.0, cy) * (1.0 - smoothstep(120.0, 150.0, cy));
    // The power-up burst: once as the change starts, once more as it lands, and a small one every 7 s.
    float jump = exp(-abs(cy - 47.0) * 2.2) + exp(-abs(cy - 72.0) * 1.6);
    float cyc = fract(t / 7.0);
    float burst = exp(-cyc * 9.0) * smoothstep(0.0, 0.35, t) * (0.6 + 0.4 * form) + jump;
    float2 uv = uv0 + min(burst, 1.2) * 0.005 * float2(sin(t * 91.0), cos(t * 77.0));

    float3 gold = uAcc.rgb;
    float3 blue = uSec.rgb;
    float3 A = mix(gold, blue, form);
    float3 hot = mix(mix(gold, float3(1.0, 0.97, 0.86), 0.6), mix(blue, float3(0.9, 0.97, 1.0), 0.7), form);
    float3 core = mix(float3(1.0, 0.98, 0.9), float3(0.94, 0.98, 1.0), form);

    // Heartbeat: a soft double pulse every 2.6 s (faster when evolved).
    float beatT = fract(t / mix(2.6, 1.9, form));
    float beat = exp(-beatT * 14.0) + 0.6 * exp(-abs(beatT - 0.18) * 16.0);

    float3 col = mix(BG * 0.7, BG + A * 0.07, smoothstep(0.0, 1.0, uv.y));
    col += A * exp(-(1.0 - uv.y) * 4.5) * (0.13 + 0.06 * beat);

    // ---- The aura body: spiky flame crown around the source. The spikes sway, and flame tongues flow
    // up along the edge (noise scrolling outward), so the outline is never still.
    float2 c = float2(asp * 0.5, 1.06);
    float2 d = uv - c;
    float grow = 1.0 + 0.05 * beat + 0.12 * min(burst, 1.0) + 0.1 * form;
    float2 q = d / grow;
    float r = length(q * float2(1.0, 0.6));
    float ang = atan(q.x, -q.y);
    float sway = sin(t * 1.7 + ang * 2.0) * 0.06;
    // Sharp spikes, each its own length, flickering a little.
    float sa = ang * 6.0 + sway + t * 0.05;
    float teeth = 1.0 - abs(fract(sa) * 2.0 - 1.0);
    float len = 0.7 + 0.45 * vnoise(float2(floor(sa) * 3.1, t * 1.3));
    teeth = sqf(teeth) * len;
    float flow = fbm3(float2(ang * 5.0, r * 4.5 - t * (3.2 + 1.5 * form)));
    float flow2 = vnoise(float2(ang * 13.0 + 4.0, r * 9.0 - t * (5.0 + 2.0 * form)));
    float flame = flow * 0.7 + flow2 * 0.3;
    // Tallest straight up, shorter towards the sides.
    float crown = 0.5 + 0.5 * smoothstep(-0.4, 1.0, cos(ang));
    float edgeR = (0.3 + 0.24 * teeth + 0.16 * flame + 0.08 * beat + 0.14 * min(burst, 1.0) + 0.06 * form) * crown;
    float u = r / max(edgeR, 0.01);
    float outer = 1.0 - smoothstep(0.985, 1.0, u);
    float mid = 1.0 - smoothstep(0.72, 0.735, u + 0.06 * flow2);
    float inner = 1.0 - smoothstep(0.44, 0.455, u + 0.05 * flow);
    // Loose tongues breaking off above the edge and rising away.
    float wisp = smoothstep(0.62, 0.8, vnoise(float2(ang * 9.0, r * 6.0 - t * 4.0))) * (1.0 - smoothstep(1.0, 1.35, u)) * step(1.0, u);

    // The evolved colour grows from the core outward while it powers up (not a flat colour swap).
    float fm = smoothstep(u - 0.3, u + 0.02, form * 1.35);
    float3 Al = mix(gold, blue, fm);
    float3 hotl = mix(mix(gold, float3(1.0, 0.97, 0.86), 0.6), mix(blue, float3(0.9, 0.97, 1.0), 0.7), fm);
    float3 corel = mix(float3(1.0, 0.98, 0.9), float3(0.94, 0.98, 1.0), fm);

    // Glow spilling outside the edge.
    col += A * exp(-max(u - 1.0, 0.0) * 4.0) * (0.18 + 0.16 * beat + 0.25 * min(burst, 1.0)) * (1.0 - outer);
    col = mix(col, Al * 0.9, wisp * 0.7);
    // Cel bands with energy running up through them.
    col = mix(col, Al * (0.85 + 0.3 * flame), outer * 0.84);
    col = mix(col, hotl, mid * 0.86);
    col = mix(col, corel, inner * 0.92);
    // Dark ink outline (anime style), thinner in the evolved form where it burns brighter.
    col = mix(col, BG * 0.4, (1.0 - smoothstep(0.0, 0.03, abs(u - 1.0))) * mix(0.55, 0.28, form));
    float3 hotc = hotl;

    // Power streaks: thin vertical lines shooting up through the aura.
    float2 sq = float2(d.x * 70.0, d.y * 2.2 + t * (3.0 + 2.0 * form));
    float streak = smoothstep(0.72, 0.97, vnoise(sq)) * smoothstep(0.55, 0.95, vnoise(float2(d.x * 9.0, d.y * 1.4 + t * 2.0)));
    col += hotc * streak * outer * (1.0 - inner * 0.6) * 0.55;

    // ---- Lightning: occasional in the first form, crackling all round in the evolved one.
    for (int k = 0; k < 4; k++) {
        if (uLod > 1.5 && k > 1) break;
        float fk = float(k);
        float seed = fk * 13.1;
        float per = mix(1.6, 0.55, form) + 0.6 * hash11(seed + 0.5);
        float run = t / per + hash11(seed + 1.0);
        float ph = fract(run);
        float epoch = floor(run);
        // In the first form only two of the four bolts ever fire, and only sometimes.
        float allowed = (fk < 2.0 ? step(0.45 - 0.45 * form, hash11(epoch + seed + 9.0)) : form);
        float on = (1.0 - step(0.14, ph)) * (0.6 + 0.4 * step(0.5, fract(ph * 25.0))) * allowed;
        if (on <= 0.0) continue;
        float2 a = c + float2((hash11(epoch + seed) - 0.5) * 0.7, -0.15 - 0.3 * hash11(epoch + seed + 2.0));
        float2 b = a + float2((hash11(epoch + seed + 3.0) - 0.5) * 0.7, -0.2 - 0.35 * hash11(epoch + seed + 4.0));
        float bd = bolt(uv, a, b, epoch + seed, 0.07);
        float3 lc = mix(mix(blue, float3(1.0), 0.6), mix(gold, float3(1.0), 0.55), form * 0.5);
        col += lc * on * (exp(-bd * 700.0) + 0.3 * exp(-bd * 45.0));
    }

    // ---- Sparks rising with short trails, more of them when evolved.
    float density = (uDensity > 0.0 ? uDensity - 1.0 : 1.0) * (1.0 + form);
    for (int k = 0; k < 14; k++) {
        if (float(k) > 5.0 + 9.0 * min(density, 1.5) / 1.5) break;
        if (uLod > 1.5 && k > 5) break;
        float fk = float(k);
        float h = hash11(fk * 5.3 + 2.0);
        float life = fract(t * (0.22 + 0.25 * h) + h * 3.0);
        float2 p = float2(asp * 0.5 + (hash11(fk * 7.7) - 0.5) * 0.9 * (0.6 + life), 1.05 - life * 1.05);
        p.x += sin(t * 2.0 + fk * 3.0) * 0.012;
        float2 dq = uv - p;
        // Elongated upward: a spark with a trail below it.
        float trail = exp(-length(float2(dq.x * 1.0, max(dq.y, 0.0) * 0.22 + min(dq.y, 0.0))) * 260.0);
        col += hot * trail * (1.0 - life) * 0.9;
    }

    // ---- Rocks lifting off the ground, lit from below.
    for (int k = 0; k < 8; k++) {
        if (uLod > 1.5 && k > 3) break;
        float fk = float(k);
        float h = hash11(fk * 3.7 + 1.0);
        float life = fract(t * (0.04 + 0.05 * h + 0.03 * form) + h);
        float2 p = float2(asp * (0.1 + 0.8 * hash11(fk * 9.1)), 1.04 - life * 1.15);
        p.x += sin(t * 0.8 + fk) * 0.01;
        float size = 0.01 + 0.018 * h;
        float2 rq = uv - p;
        if (dot(rq, rq) < size * size * 6.0) {
            rq = rot(t * (0.3 + h) + fk) * rq;
            float dd = sdRoundBox(rq, float2(size, size * 0.7), size * 0.35) + (vnoise(rq * 90.0 + fk) - 0.5) * size * 0.35;
            float rock = (1.0 - smoothstep(0.0, 0.0015, dd)) * smoothstep(0.0, 0.08, life) * (1.0 - smoothstep(0.8, 1.0, life));
            float lit = sat(0.5 + 0.6 * (rq.y / size));
            float3 rc = mix(uSurf.rgb * 0.7, mix(A, hot, 0.4), step(0.55, lit));
            col = mix(col, rc, rock);
        }
    }

    // Dust in the aura's light.
    float2 su = float2(uv.x, uv.y * 0.4);
    float sp = dots(su, 22.0, float2(0.0, t * 1.1), 0.22, 0.12, 3.0);
    col += hot * sp * 0.45 * smoothstep(0.15, 0.9, uv.y);

    // Focus lines and the ground shockwave on each burst; a ring on every heartbeat.
    col += float3(1.0) * focusLines(uv, float2(asp * 0.5, 0.72), t, 110.0, 1.0) * (0.04 + 0.3 * min(burst, 1.0));
    float rr = length((uv - float2(asp * 0.5, 1.02)) * float2(1.0, 3.2));
    col += hot * exp(-abs(rr - cyc * 2.4) * 35.0) * (1.0 - cyc) * 0.5;
    col += hot * exp(-abs(rr - beatT * 1.3) * 60.0) * (1.0 - beatT) * 0.18;
    // Flash (the power-up gets a big one).
    col += mix(A, float3(1.0), 0.5) * min(burst, 1.5) * 0.16;

    return half4(finish(col, fc), 1.0);
}
"""

    private const val AURORA = """
// Aurora: the northern lights over a frozen lake. Curtains of light hang in depth - stacked sheets
// that fold and ripple slowly, bright along their lower hem with rays reaching up, green fading to
// violet - above snowy mountains that catch their glow. Stars behind, a dark fringe of pines on the
// far shore, and the whole sky mirrored, a little softened, in the ice and open water below.

// Curtain pattern on a sheet at height-layer i: thin folded bands drifting slowly. 0..1.
float curtain(float2 p, float t) {
    // p = (across, away) on the sheet. Bands run across the view and fold slowly.
    float w = fbm3(float2(p.x * 0.15 + t * 0.01, p.y * 0.1)) * 5.0;
    float b = sin(p.y * 1.15 + w + sin(p.x * 0.2 + t * 0.05) * 1.5 + t * 0.04);
    float band = exp(-abs(b) * 10.0);
    float b2 = sin(p.y * 1.9 - w * 0.8 + 1.7 + t * 0.03);
    band += exp(-abs(b2) * 14.0) * 0.5;
    // Rays: brightness varying finely along the band.
    float rays = 0.4 + 0.6 * vnoise(float2(p.x * 6.0 + w * 2.0, t * 0.25));
    return band * rays;
}

// Light of the aurora seen along direction rd (rd.y > 0).
float3 auroraCol(float3 rd, float t, float3 A, float3 S, float lod, float jit) {
    float3 acc = float3(0.0);
    float n = 22.0 - lod * 6.0;
    for (int i = 0; i < 22; i++) {
        float fi = float(i);
        if (fi >= n) break;
        float h = 0.8 + (fi + jit) * 0.06;       // height of this sheet above the eye (jittered: no banding)
        float d = h / max(rd.y, 0.02);
        float2 p = rd.xz * d + float2(0.0, 6.0);
        float c = curtain(p * 0.35, t);
        float k = fi / n;
        float3 tint = mix(A, S, smoothstep(0.15, 0.9, k));
        // The hem is brightest; higher sheets fade.
        float fall = exp(-k * 3.2) * (1.0 + 2.5 * exp(-k * 25.0));
        acc += tint * c * fall * smoothstep(40.0, 8.0, d);
    }
    return acc * (1.6 / n) * 4.2;
}

float3 skyCol(float3 rd, float t, float3 A, float3 S, float3 BG, float lod, float jit) {
    float y = max(rd.y, 0.0);
    float3 c = mix(BG * 1.6 + A * 0.03, BG * 0.6, sat(y * 2.2));
    float2 sp = rd.xz / (rd.y + 0.15);
    c += float3(0.9, 0.95, 1.0) * dots(sp * 0.5, 60.0, float2(0.0), 0.3, 0.07, 3.0) * 0.5 * sat(y * 6.0);
    c += float3(1.0) * dots(sp * 0.5, 22.0, float2(0.0), 0.12, 0.06, 8.0) * 0.6 * sat(y * 6.0);
    if (rd.y > 0.0) c += auroraCol(rd, t, A, S, lod, jit);
    return c;
}

half4 main(float2 fc) {
    float t = uTime;
    float2 sp = (fc - 0.5 * uRes) / uRes.y;
    sp.y = -sp.y;
    float px = 1.5 / uRes.y;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    // Looking a little up over the lake; the horizon sits low.
    float yaw = 0.06 * sin(t * 0.02);
    float3 rd = normalize(float3(sp.x, sp.y + 0.10, -1.0));
    rd.xz = rot(yaw) * rd.xz;
    float horizonY = -0.10;   // in sp units, where rd.y = 0

    float3 col;
    float jit = fract(52.9829189 * fract(dot(fc, float2(0.06711056, 0.00583715))));
    float3 sky = skyCol(rd, t, A, S, BG, uLod, jit);
    // Average aurora light, for the snow and ice (cheap: it changes slowly).
    float3 glowA = mix(A, S, 0.3) * (0.22 + 0.08 * sin(t * 0.13) + 0.05 * sin(sp.x * 3.0 + t * 0.05));

    if (rd.y > 0.0) {
        col = sky;
    } else {
        // The lake: ice with open water, mirroring the sky, rippled and darker.
        float3 r = float3(rd.x, -rd.y, rd.z);
        float dist = 1.0 / max(-rd.y, 0.01);
        float2 wp = rd.xz * dist;
        r.x += 0.004 * sin(wp.y * 3.0 + t * 0.8) * (1.0 + 0.5 * sin(wp.x));
        float3 refl = skyCol(normalize(r), t, A, S, BG, max(uLod, 1.0), jit);
        float ice = smoothstep(0.45, 0.6, fbm3(wp * float2(0.6, 1.5)));
        float3 iceCol = mix(float3(0.12, 0.15, 0.2), glowA * 0.4 + float3(0.15), 0.4) * (0.6 + 0.4 * vnoise(wp * 4.0));
        col = mix(refl * 0.75 + BG * 0.1, iceCol * 0.6 + refl * 0.25, ice);
        // Cracks in the ice.
        col *= 1.0 - 0.4 * ice * smoothstep(0.03, 0.0, abs(vnoise(wp * 3.0) - 0.5));
    }

    // Mountains on the far shore: snow on the slopes catching the aurora, two ridges; mirrored in the lake.
    float mx = sp.x + yaw;
    float hy = sp.y;
    float under = step(hy, horizonY);
    float my = under > 0.5 ? 2.0 * horizonY - hy : hy;
    float m1 = horizonY + 0.05 + 0.07 * fbm(float2(mx * 1.6, 2.0)) + 0.035 * (1.0 - abs(2.0 * vnoise(float2(mx * 4.0, 1.0)) - 1.0));
    float m1r = horizonY + 0.05 + 0.07 * fbm(float2((mx + 0.01) * 1.6, 2.0)) + 0.035 * (1.0 - abs(2.0 * vnoise(float2((mx + 0.01) * 4.0, 1.0)) - 1.0));
    float3 snow = mix(float3(0.55, 0.6, 0.7), glowA * 1.3 + float3(0.1), 0.55);
    float3 mcol = col;
    float mcov = 0.0;
    if (my < m1) {
        // Lit on slopes facing left (towards the brightest aurora), snow higher up, rocky streaks.
        float slope = (m1r - m1) / 0.01;
        float shade = sat(0.55 + slope * 1.5);
        float hgt = (my - horizonY) / max(m1 - horizonY, 0.01);
        float streak = vnoise(float2(mx * 60.0, my * 6.0));
        float snowy = smoothstep(0.35, 0.7, hgt + (streak - 0.5) * 0.6);
        float3 mc = mix(BG * 0.45, snow * (0.3 + 0.6 * shade), snowy);
        mcol = mix(mc, sky * 0.5, 0.2 * (1.0 - hgt));
        mcov = smoothstep(m1, m1 - px, my);
    }
    // In the water the mountains are darker, and the ripples break them up.
    if (under > 0.5) mcol = mcol * 0.45 + BG * 0.05;
    col = mix(col, mcol, mcov * (1.0 - under * 0.15));

    // Pines on the shore, and their reflection in the water.
    float tx = mx * 30.0;
    float th = 0.03 + 0.03 * hash11(floor(tx)) * step(0.3, hash11(floor(tx) + 7.0));
    float tf = abs(fract(tx) - 0.5) / 30.0;
    float tr = abs(hy - horizonY);
    float pine = step(tf, (1.0 - tr / th) * 0.012 * (0.7 + 0.3 * step(0.5, fract(tr / th * 5.0)))) * step(tr, th);
    float3 pineCol = hy > horizonY ? BG * 0.25 : BG * 0.3 + glowA * 0.03;
    col = mix(col, pineCol, pine);

    // A soft glow of the aurora low over everything.
    col += glowA * 0.05;
    return half4(finish(col, fc), 1.0);
}
"""

    private const val NEBULA = """
// Nebula: a gas cloud drifting very slowly, folded by its own currents, with dark dust lanes,
// a field of stars and a few bright ones with soft diffraction spikes.
half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    float2 p = uv * 1.5 + float2(t * 0.006, t * 0.002);
    float2 q = float2(fbm(p + float2(0.0, t * 0.01)), fbm(p + float2(5.2, 1.3) - t * 0.008));
    float r = fbm(p + 2.2 * q + float2(1.7, 9.2));
    float gas = smoothstep(0.3, 0.9, r);
    float3 col = BG;
    col += mix(A, S, sat(q.x * 1.4 - 0.2)) * gas * 0.55;
    col += mix(S, float3(1.0), 0.3) * pow(gas, 3.0) * 0.25;
    // Dust lanes.
    float dust = smoothstep(0.5, 0.75, fbm3(p * 2.4 + q * 1.5 + 3.0));
    col *= 1.0 - dust * 0.55;

    // Stars.
    col += float3(1.0) * dots(uv, 55.0, float2(t * 0.02, 0.0), 0.4, 0.08, 1.0) * 0.45;
    col += mix(S, float3(1.0), 0.6) * dots(uv, 24.0, float2(t * 0.03, 0.0), 0.25, 0.07, 5.0) * 0.7;
    // Bright stars with spikes.
    float2 bp = uv * 3.0 + float2(t * 0.012, 0.0);
    float2 id = floor(bp);
    float2 f = fract(bp) - 0.5;
    float2 rr = hash22(id + 21.0);
    if (rr.x < 0.35) {
        float2 g = f - (hash22(id + 4.0) - 0.5) * 0.5;
        float tw = 0.75 + 0.25 * sin(t * (0.8 + rr.y) + rr.x * 30.0);
        float spike = (exp(-abs(g.x) * 220.0) * exp(-abs(g.y) * 14.0) + exp(-abs(g.y) * 220.0) * exp(-abs(g.x) * 14.0));
        float core = exp(-length(g) * 60.0);
        col += mix(S, float3(1.0), 0.7) * (spike * 0.35 + core) * tw * 0.9;
    }
    return half4(finish(col, fc), 1.0);
}
"""

    private const val PIXELS = """
// Pixel flow: a field of rounded pixels that swell and glow as a slow current passes through
// them, colours shifting across the screen, with the odd pixel sparkling.
half4 main(float2 fc) {
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    float cs = max(14.0, floor(uRes.y / 30.0));
    float2 id = floor(fc / cs);
    float2 local = fract(fc / cs) - 0.5;
    float2 g = id * 0.07;

    float flow = fbm(g * 1.4 + float2(t * 0.06, t * 0.025)) + 0.22 * sin(id.x * 0.16 - id.y * 0.07 + t * 0.5);
    float b = smoothstep(0.3, 0.8, flow);
    float sparkle = step(0.997, hash12(id + floor(t * 1.5)));
    b = max(b, sparkle);

    float size = 0.08 + 0.32 * b;
    float d = sdRoundBox(local, float2(size), 0.12);
    float px = 1.0 / cs;
    float m = 1.0 - smoothstep(-px, px, d);

    float3 c = mix(A, S, vnoise(g * 0.6 + float2(t * 0.02, 0.0)));
    float3 col = BG + c * 0.03;
    col += c * m * (0.12 + 0.6 * b);
    // Soft glow under bright pixels.
    col += c * b * exp(-max(d, 0.0) * 6.0) * 0.12;
    return half4(finish(col, fc), 1.0);
}
"""

    private const val GLASS = """
// Glass: soft coloured lights drift behind frosted glass panels. The panels blur and bend what
// is behind them, catch a highlight along their edges and cast faint shadows.
float3 lights(float2 uv, float asp, float t, float blur, float3 A, float3 S) {
    float3 c = float3(0.0);
    float2 p1 = float2(asp * (0.3 + 0.2 * sin(t * 0.07)), 0.35 + 0.2 * cos(t * 0.05));
    float2 p2 = float2(asp * (0.7 + 0.2 * cos(t * 0.06)), 0.55 + 0.2 * sin(t * 0.045));
    float2 p3 = float2(asp * (0.5 + 0.35 * sin(t * 0.04 + 2.0)), 0.75 + 0.15 * cos(t * 0.08));
    float k = 1.0 / (0.04 + blur);
    c += A * exp(-dot(uv - p1, uv - p1) * k * 0.6) * 0.55;
    c += S * exp(-dot(uv - p2, uv - p2) * k * 0.8) * 0.4;
    c += mix(A, S, 0.5) * exp(-dot(uv - p3, uv - p3) * k) * 0.35;
    return c;
}

float panelSd(float2 uv, float i, float asp, float t) {
    float2 c = float2(asp * (0.2 + 0.6 * hash11(i * 5.1)) + 0.04 * sin(t * 0.08 + i * 2.0), 0.22 + 0.5 * hash11(i * 9.7) + 0.03 * cos(t * 0.06 + i));
    float2 s = float2(0.16 + 0.14 * hash11(i * 2.3), 0.1 + 0.08 * hash11(i * 3.9));
    float2 q = rot(0.08 * sin(t * 0.05 + i)) * (uv - c);
    return sdRoundBox(q, s, 0.035);
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float px = 1.0 / uRes.y;

    float3 col = BG + lights(uv, asp, t, 0.0, A, S);
    for (int k = 0; k < 4; k++) {
        float i = float(k);
        float d = panelSd(uv, i, asp, t);
        // Shadow just below and right.
        float sh = panelSd(uv - float2(0.012, 0.02), i, asp, t);
        col *= 1.0 - 0.3 * (1.0 - smoothstep(-0.02, 0.04, sh)) * step(0.0, d);
        if (d < 0.0) {
            float edgeK = exp(d * 40.0);
            float2 bend = float2(d, d) * 0.0;
            float2 nrm = normalize(float2(
                panelSd(uv + float2(px, 0.0), i, asp, t) - d,
                panelSd(uv + float2(0.0, px), i, asp, t) - d) + 1e-5);
            bend = -nrm * edgeK * 0.05;
            float3 behind = BG + lights(uv + bend, asp, t, 0.06, A, S);
            float3 frost = behind * 0.9 + float3(1.0) * 0.045 + (hash12(fc) - 0.5) * 0.015;
            // Light sweep across the panel.
            float sw = exp(-sqf((uv.x - uv.y * 0.6) * 4.0 - (fract(t * 0.05 + i * 0.25) * 8.0 - 3.0))) * 0.05;
            col = frost + sw;
        }
        float rim = 1.0 - smoothstep(0.0, 1.5 * px, abs(d));
        float lightSide = 0.5 + 0.5 * sat(-(uv.y) + 0.8);
        col += float3(1.0) * rim * 0.22 * lightSide;
    }
    return half4(finish(col, fc), 1.0);
}
"""

    private const val RAIN = """
// Digital rain: columns of made-up glyphs falling at their own pace, bright at the head and
// fading behind, with a dimmer, smaller layer further back.
float3 rainLayer(float2 fc, float cw, float seed, float t, float3 A, float3 S) {
    float ch = cw * 1.3;
    float cx = floor(fc.x / cw);
    float cy = floor(fc.y / ch);
    float2 local = float2(fract(fc.x / cw), fract(fc.y / ch));
    float rows = uRes.y / ch;
    float speed = 3.0 + 7.0 * hash11(cx * 1.7 + seed);
    float tail = 8.0 + 14.0 * hash11(cx * 3.1 + seed);
    float cycle = rows + tail + 10.0 * hash11(cx + seed * 2.0);
    float head = mod(t * speed + hash11(cx * 9.1 + seed) * 200.0, cycle);
    float behind = head - cy;
    if (behind < 0.0 || behind > tail) return float3(0.0);
    // Glyph: a 4x6 bit pattern per cell that changes now and then.
    float2 g = floor(local * float2(4.0, 6.0));
    float change = floor(t * (0.5 + 2.0 * hash12(float2(cx, cy) + seed)));
    float bit = step(0.48, hash12(float2(cx * 13.0 + g.x, cy * 7.0 + g.y) + change * 3.7 + seed));
    float inside = step(0.12, local.x) * step(local.x, 0.88) * step(0.08, local.y) * step(local.y, 0.92);
    float on = bit * inside;
    float fade = pow(1.0 - behind / tail, 1.6);
    float3 c = behind < 1.0 ? mix(S, float3(1.0), 0.5) : A;
    return c * on * fade;
}

half4 main(float2 fc) {
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float2 uv = fc / uRes.y;

    float3 col = mix(BG * 1.2 + A * 0.03, BG * 0.8, uv.y);
    float near = max(12.0, floor(uRes.y / 34.0));
    float far = max(8.0, floor(uRes.y / 58.0));
    col += rainLayer(fc + float2(far * 0.5, 0.0), far, 7.0, t * 0.8, A, S) * 0.28;
    col += rainLayer(fc, near, 1.0, t, A, S) * 0.75;
    // Faint glow behind it all.
    col += A * 0.05 * fbm3(float2(uv.x * 3.0, uv.y * 2.0 - t * 0.1));
    return half4(finish(col, fc), 1.0);
}
"""

    private const val STARS = """
// Constellation: a deep, clear night far from any town. The galaxy's band arcs over the sky - a
// glowing core, dark lanes of dust, tinted clouds of gas - and the whole sky turns very slowly round
// the pole. Bright stars twinkle with soft spikes, two invented constellations trace themselves in
// and fade away, and now and then a meteor streaks past. Below, hills in silhouette, a lone tree
// and a little observatory with its slit open, a dim light inside.

float conLine(float2 uv, float2 a, float2 b, float prog) {
    float2 e = mix(a, b, sat(prog));
    float d = sdSegment(uv, a, e);
    return ((1.0 - smoothstep(0.0, 1.6 / uRes.y, d)) + exp(-d * 400.0) * 0.4) * step(0.001, prog);
}

float2 conPoint(float i, float seed, float2 center) {
    return center + (float2(hash11(i * 7.7 + seed), hash11(i * 3.3 + seed + 1.0)) - 0.5) * float2(0.42, 0.26);
}

// Bright stars with soft cross-shaped spikes (one per cell, a few cells only).
float bigStars(float2 p, float scale, float seed) {
    float2 q = p * scale;
    float2 id = floor(q);
    float2 f = fract(q) - 0.5;
    float2 r = hash22(id + seed);
    if (r.x > 0.18) return 0.0;
    float2 o = (hash22(id + seed + 3.1) - 0.5) * 0.6;
    float2 d = (f - o) / scale;
    float l = length(d);
    float tw = 0.6 + 0.4 * sin(uTime * (1.0 + 2.0 * r.y) + r.x * 50.0);
    float core = exp(-l * uRes.y * 0.45);
    float spike = exp(-abs(d.x) * uRes.y * 0.9) * exp(-abs(d.y) * 60.0) + exp(-abs(d.y) * uRes.y * 0.9) * exp(-abs(d.x) * 60.0);
    return (core + spike * 0.35 + exp(-l * 90.0) * 0.15) * tw * (0.5 + r.y);
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float px = 1.5 / uRes.y;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    // The sky turns slowly round a pole above the top of the screen.
    float2 pole = float2(asp * 0.5, -0.6);
    float2 sky = pole + rot(t * 0.004) * (uv - pole);

    float3 col = mix(BG * 0.6, BG * 1.5 + S * 0.03, smoothstep(0.0, 0.9, uv.y));
    // Airglow low down.
    col += mix(A, S, 0.6) * 0.05 * exp(-(0.78 - uv.y) * 6.0) * step(uv.y, 0.8);

    // The galaxy: a band across the sky with a brighter core, gas clouds and dust lanes.
    float2 bdir = normalize(float2(1.0, -0.42));
    float2 bc = sky - float2(asp * 0.5, 0.32);
    float across = dot(bc, float2(-bdir.y, bdir.x));
    float along = dot(bc, bdir);
    float warp = 0.05 * fbm3(float2(along * 3.0, 1.0));
    float band = exp(-sqf((across + warp) * 6.5));
    float coreG = exp(-sqf(along * 1.6 - 0.25)) * exp(-sqf((across + warp) * 9.0));
    float gas = fbm(sky * float2(3.0, 3.0) + float2(7.0, 0.0));
    float dust = fbm(float2(along * 6.0, across * 22.0) + 3.0);
    float lanes = smoothstep(0.45, 0.75, dust) * band;
    float3 milky = mix(float3(0.55, 0.6, 0.8), float3(1.0, 0.85, 0.65), coreG);
    float glowG = band * (0.12 + 0.25 * gas) + coreG * 0.35;
    col += milky * glowG * (1.0 - lanes * 0.8) * 0.9;
    col += mix(A, S, 0.3) * band * smoothstep(0.5, 0.85, gas) * 0.10;
    col += float3(0.8, 0.3, 0.45) * coreG * smoothstep(0.55, 0.8, fbm3(sky * 9.0)) * 0.12;
    // Countless faint stars, thickest along the band.
    col += float3(1.0) * dots(sky, 140.0, float2(0.0), 0.35 + 0.5 * band, 0.12, 2.0) * 0.30 * (0.5 + band);
    col += float3(0.95, 0.97, 1.0) * dots(sky, 60.0, float2(0.0), 0.30, 0.09, 5.0) * 0.45;
    // Bright stars with a hint of colour.
    col += mix(float3(0.8, 0.88, 1.0), S, 0.3) * bigStars(sky, 7.0, 11.0);
    col += mix(float3(1.0, 0.85, 0.7), A, 0.2) * bigStars(sky, 4.5, 23.0) * 0.8;

    // Two constellations drawing themselves in turn (each 26 s).
    float3 lines = float3(0.0);
    for (int c = 0; c < 2; c++) {
        float ci = float(c);
        float ph = fract(t / 26.0 + ci * 0.5);
        float2 center = float2(asp * (0.26 + 0.48 * ci), 0.24 + 0.08 * ci);
        float seed = 3.0 + ci * 11.0;
        float vis = smoothstep(0.0, 0.05, ph) * (1.0 - smoothstep(0.42, 0.5, ph));
        for (int k = 0; k < 5; k++) {
            float kk = float(k);
            float2 a = conPoint(kk, seed, center);
            float2 b = conPoint(kk + 1.0, seed, center);
            float prog = (ph - 0.03 - kk * 0.045) / 0.045;
            lines += mix(A, S, 0.4) * conLine(sky, a, b, prog) * vis * 0.45;
            float sd = length(sky - a);
            lines += mix(S, float3(1.0), 0.6) * (exp(-sd * 300.0) + exp(-sd * 60.0) * 0.25) * (0.35 + 0.65 * vis);
        }
        float ld = length(sky - conPoint(5.0, seed, center));
        lines += mix(S, float3(1.0), 0.6) * (exp(-ld * 300.0) + exp(-ld * 60.0) * 0.25) * (0.35 + 0.65 * vis);
    }
    col += lines;

    // A meteor every ~9 s, with a glowing head and a fading train.
    float sk = floor(t / 9.0);
    float sph = t - sk * 9.0;
    if (sph < 1.1) {
        float2 st = float2(asp * (0.2 + 0.7 * hash11(sk * 5.3)), 0.05 + 0.25 * hash11(sk * 2.1));
        float2 dir = normalize(float2(-0.85, 0.42 + 0.2 * hash11(sk)));
        float2 head = st + dir * sph * 0.7;
        float len = 0.25 * sat(sph * 3.0);
        float2 tailP = head - dir * len;
        float d = sdSegment(uv, tailP, head);
        float al = sat(dot(uv - tailP, dir) / max(len, 1e-3));
        float fade = sat(1.0 - sph / 1.1);
        col += mix(S, float3(1.0), 0.7) * (exp(-d * 1100.0) * al * al + exp(-d * 120.0) * 0.12 * al) * fade;
        col += float3(1.0) * exp(-length(uv - head) * 400.0) * fade;
    }

    // Hills in silhouette, two layers, the far one a little lit by the sky.
    float h1 = 0.74 - 0.06 * fbm3(float2(uv.x * 1.6, 2.0)) - 0.02 * vnoise(float2(uv.x * 9.0, 0.0));
    float h2 = 0.82 - 0.07 * smoothstep(0.0, 1.0, sin(uv.x * 1.3 + 0.6) * 0.5 + 0.5) - 0.015 * vnoise(float2(uv.x * 14.0, 5.0));
    col = mix(col, BG * 0.55 + S * 0.015, smoothstep(h1, h1 + px, uv.y));
    // The observatory on the near hill: a drum, a dome, its slit open and lit.
    float ox = asp * 0.74;
    float oy = 0.82 - 0.07 * smoothstep(0.0, 1.0, sin(ox * 1.3 + 0.6) * 0.5 + 0.5);
    float2 oq = uv - float2(ox, oy - 0.035);
    float drum = sdRoundBox(oq, float2(0.04, 0.03), 0.002);
    float dome = length(oq - float2(0.0, -0.03)) - 0.042;
    dome = max(dome, oq.y + 0.03);
    float obs = min(drum, dome);
    float slit = step(abs(oq.x + (oq.y + 0.03) * 0.25), 0.006) * step(dome, 0.0) * step(oq.y, -0.034);
    float near = min(obs, h2 - uv.y);
    // The lone tree on the left: a trunk and a rounded, ragged crown.
    float2 tq = uv - float2(asp * 0.18, 0.8);
    float trunk = sdRoundBox(tq + float2(0.0, 0.035), float2(0.004, 0.04), 0.002);
    float crown = length((tq + float2(0.0, 0.09)) * float2(1.0, 1.25)) - 0.05 - 0.012 * fbm3(tq * 60.0);
    near = min(near, min(trunk, crown));
    // The near hill catches a little skylight along its top.
    float3 nearCol = BG * 0.3 + mix(S, A, 0.3) * 0.03 * exp(-max(uv.y - h2, 0.0) * 30.0);
    col = mix(col, nearCol, smoothstep(px, -px, near));
    col += float3(1.0, 0.78, 0.45) * slit * 0.8;
    col += float3(1.0, 0.75, 0.4) * 0.05 * exp(-length(uv - float2(ox, oy - 0.07)) * 30.0);

    return half4(finish(col, fc), 1.0);
}
"""

    private const val PETALS = """
// Sakura: a spring night under a cherry tree. A gnarled branch heavy with blossom reaches in over
// the top of the screen, its flowers lit by a big pale moon; far below, misty hills with a pagoda and
// glowing stone lanterns by a still pond that mirrors the moon. Petals drift down at three depths -
// soft and out of focus close up, crisp in the middle - and some settle on the water.
// Leaves / petals tumbling down (or along the wind). One per cell at most, so it stays cheap.
// kind 0 = leaf, 1 = petal. Returns colour (not premultiplied) and coverage.
float4 fallingLayer(float2 uv, float scale, float2 vel, float sway, float seed, float kind, float blur, float3 c1, float3 c2) {
    float2 p = uv * scale - vel * uTime;
    p.x += sway * sin(uTime * 0.55 + p.y * 1.7 + seed);
    float2 id = floor(p);
    float2 f = fract(p) - 0.5;
    float2 r = hash22(id + seed);
    if (r.x > 0.5) return float4(0.0);
    float2 o = (hash22(id + seed + 3.7) - 0.5) * 0.36;
    float2 q = f - o;
    float dir = r.x > 0.25 ? 1.0 : -1.0;
    q = rot(uTime * (0.35 + 0.7 * r.y) * dir + r.y * TAU) * q;
    float flip = cos(uTime * (0.7 + r.x) + r.y * 9.0);
    q.y /= max(abs(flip), 0.22);
    float d;
    float shade;
    if (kind < 0.5) {
        float L = 0.2;
        float x = q.x / L;
        float w = 0.075 * (1.0 - x * x) * (1.0 + 0.25 * x);
        d = max(abs(q.y) - w, abs(q.x) - L);
        float vein = (1.0 - smoothstep(0.0, 0.01, abs(q.y))) * step(abs(q.x), L * 0.85);
        shade = (0.8 + 0.3 * sign(q.y) * flip) * (1.0 - 0.3 * vein);
    } else {
        float w = 0.1 * (0.5 + 0.5 * sat((q.x + 0.15) / 0.3));
        d = (length(float2(q.x / 0.15, q.y / w)) - 1.0) * 0.07;
        d = max(d, -(length(q - float2(0.165, 0.0)) - 0.04));
        shade = 0.85 + 0.25 * (q.x / 0.15) * flip;
    }
    float a = 1.0 - smoothstep(-blur, blur, d);
    return float4(mix(c1, c2, r.y) * shade, a);
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float px = 1.5 / uRes.y;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float3 blossom = mix(A, float3(1.0, 0.75, 0.85), 0.35);

    // Night sky: plum to deep blue, a big moon upper right with a halo.
    float3 col = mix(BG * 1.6 + A * 0.06, BG * 0.8, smoothstep(0.0, 0.7, uv.y));
    float2 mc = float2(asp * 0.78, 0.24);
    float md = length(uv - mc);
    col += mix(S, float3(1.0), 0.4) * (exp(-md * 4.0) * 0.25 + exp(-md * 14.0) * 0.2);
    float moon = smoothstep(0.075, 0.07, md);
    col = mix(col, float3(1.0, 0.96, 0.93) * (0.88 + 0.12 * vnoise((uv - mc) * 30.0)), moon);
    col += dots(uv, 60.0, float2(0.0), 0.12, 0.05, 2.0) * 0.4 * smoothstep(0.5, 0.0, uv.y) * smoothstep(0.1, 0.25, md);

    // Far hills in mist, a pagoda on the left one.
    float h1 = 0.60 - 0.06 * fbm3(float2(uv.x * 1.5, 1.0)) - 0.05 * smoothstep(0.0, 1.0, 1.0 - abs(uv.x - asp * 0.25) * 2.0);
    col = mix(col, mix(BG * 1.2, A * 0.12 + BG, 0.4), smoothstep(h1, h1 + px, uv.y) * 0.85);
    float2 pq = uv - float2(asp * 0.25, h1 + 0.005);
    float pag = 1.0;
    for (int i = 0; i < 4; i++) {
        float fi = float(i);
        float y0 = -0.03 - fi * 0.035;
        float w = 0.05 - fi * 0.009;
        // A roof that curls up at its ends, and the storey under it.
        float roof = max(abs(pq.y - y0 + 0.006 * sqf(pq.x / w) * 3.0) - 0.004, abs(pq.x) - w);
        float wall = max(abs(pq.y - y0 - 0.017) - 0.013, abs(pq.x) - w * 0.65);
        pag = min(pag, min(roof, wall));
    }
    pag = min(pag, max(abs(pq.x) - 0.0025, abs(pq.y + 0.175) - 0.03));
    col = mix(col, BG * 0.6, smoothstep(px, -px, pag));
    col += float3(1.0, 0.7, 0.4) * smoothstep(0.004, 0.0, max(abs(pq.x) - 0.006, abs(pq.y + 0.045) - 0.004)) * 0.6;
    // Mist lying in the valley.
    float mist = fbm3(float2(uv.x * 2.0 - t * 0.02, uv.y * 8.0));
    col = mix(col, mix(BG * 2.0, A * 0.2 + S * 0.05, 0.4), smoothstep(0.55, 0.75, uv.y) * mist * 0.6);

    // The pond: mirror of the sky, the moon's reflection broken by ripples.
    float py = 0.76;
    if (uv.y > py) {
        float dy = uv.y - py;
        float2 r = float2(uv.x + 0.004 * sin(uv.y * 220.0 + t * 1.5) * (1.0 + dy * 20.0), py - dy * 3.7);
        float3 rc = mix(BG * 1.6 + A * 0.06, BG * 0.8, smoothstep(0.0, 0.7, r.y));
        float rmd = length(r - mc);
        rc += mix(S, float3(1.0), 0.4) * exp(-rmd * 6.0) * 0.25;
        rc += float3(1.0, 0.96, 0.93) * smoothstep(0.08, 0.06, rmd) * 0.7 * (0.6 + 0.4 * sin(uv.y * 400.0 + t * 2.0));
        col = mix(col, rc * 0.8 + BG * 0.1, smoothstep(py, py + px, uv.y));
    }
    // Stone lanterns on the shore, glowing warm, their light on the water.
    for (int i = 0; i < 3; i++) {
        float fi = float(i);
        float lx = asp * (0.42 + 0.22 * fi);
        float2 lq = uv - float2(lx, py - 0.012);
        float body = min(sdRoundBox(lq + float2(0.0, 0.03), float2(0.012, 0.012), 0.002), sdRoundBox(lq + float2(0.0, 0.05), float2(0.02, 0.004), 0.002));
        body = min(body, sdRoundBox(lq + float2(0.0, 0.012), float2(0.004, 0.012), 0.001));
        col = mix(col, BG * 0.5, smoothstep(px, -px, body));
        float flick = 0.85 + 0.15 * sin(t * 7.0 + fi * 3.0) * sin(t * 4.3 + fi);
        col += float3(1.0, 0.65, 0.3) * smoothstep(0.008, 0.0, length(lq + float2(0.0, 0.03))) * flick;
        col += float3(1.0, 0.6, 0.3) * 0.12 * exp(-length((lq + float2(0.0, 0.03)) * float2(1.0, 0.6)) * 25.0) * flick;
        col += float3(1.0, 0.6, 0.3) * 0.08 * exp(-abs(uv.x - lx) * 60.0) * step(py, uv.y) * exp(-(uv.y - py) * 8.0) * flick;
    }

    // Petals far away (soft), then the branch, then near petals.
    float4 l = fallingLayer(uv, 13.0, float2(0.3, 0.5), 0.4, 3.0, 1.0, 0.035, blossom * 0.8, S * 0.8);
    col = mix(col, l.rgb * 0.7, l.a * 0.3);

    // The branch: gnarled, swaying a little, dark bark rimmed by the moon.
    float sw = 0.006 * sin(t * 0.5);
    float2 b0 = float2(-0.05, 0.07);
    float2 b1 = float2(asp * 0.22, 0.14 + sw);
    float2 b2 = float2(asp * 0.45, 0.10 + sw * 1.5);
    float2 b3 = float2(asp * 0.62, 0.17 + sw * 2.0);
    float2 c1 = b1 + float2(0.10, 0.17 + sw);
    float2 c2 = b2 + float2(0.06, -0.10 + sw);
    float2 c3 = b2 + float2(0.12, 0.13 + sw * 2.0);
    float bd = sdSegment(uv, b0, b1) - 0.016;
    bd = min(bd, sdSegment(uv, b1, b2) - 0.011);
    bd = min(bd, sdSegment(uv, b2, b3) - 0.007);
    bd = min(bd, sdSegment(uv, b1, c1) - 0.006);
    bd = min(bd, sdSegment(uv, b2, c2) - 0.005);
    bd = min(bd, sdSegment(uv, b2, c3) - 0.005);
    bd += 0.002 * (vnoise(uv * 120.0) - 0.5);
    float3 bark = BG * 0.4 + float3(0.04, 0.025, 0.03);
    bark += mix(S, float3(1.0), 0.5) * 0.12 * smoothstep(0.0, -0.004, bd) * (1.0 - smoothstep(-0.004, -0.009, bd));
    col = mix(col, bark, smoothstep(px, -px, bd));

    // Blossom: sprays of small five-petal flowers along the twigs, denser near the wood, lit from
    // the moon's side; two offset grids so they overlap like the real thing.
    if (bd < 0.06) {
        for (int g = 0; g < 2; g++) {
            float fg = float(g);
            float scale = 38.0 + fg * 13.0;
            float2 fq = uv * scale + fg * 0.37;
            float2 fid = floor(fq);
            float2 ff = fract(fq) - 0.5;
            float2 h = hash22(fid + fg * 13.0);
            float2 cpos = (fid + 0.5 + (h - 0.5) * 0.5 - fg * 0.37) / scale;
            // Distance of this flower's centre to the wood decides whether it's there.
            float wd = sdSegment(cpos, b0, b1) - 0.016;
            wd = min(wd, sdSegment(cpos, b1, b2) - 0.011);
            wd = min(wd, sdSegment(cpos, b2, b3) - 0.007);
            wd = min(wd, sdSegment(cpos, b1, c1) - 0.006);
            wd = min(wd, sdSegment(cpos, b2, c2) - 0.005);
            wd = min(wd, sdSegment(cpos, b2, c3) - 0.005);
            float present = step(h.x, 0.95 - smoothstep(0.0, 0.045, wd) * 0.95) * step(-0.004, wd);
            if (present > 0.5) {
                float2 q = ff - (h - 0.5) * 0.5;
                float sz = 0.36 + 0.14 * h.y;
                float a = atan(q.y, q.x) + h.y * 6.0 + 0.2 * sin(t * 0.6 + h.x * 9.0);
                float rr = length(q) / sz;
                float petal = rr - (0.7 + 0.3 * abs(cos(a * 2.5)));
                if (petal < 0.1) {
                    float lit = sat(0.55 + dot(normalize(mc - cpos), normalize(q + 1e-4)) * 0.3 * rr + (h.y - 0.5) * 0.4);
                    float3 fcol = blossom * (0.45 + 0.75 * lit);
                    fcol = mix(fcol, float3(1.0, 0.95, 0.97), (1.0 - rr) * 0.3 * lit);
                    fcol = mix(fcol, mix(A, float3(0.55, 0.08, 0.2), 0.5), smoothstep(0.25, 0.0, rr) * 0.7);
                    // Petal edges a touch darker so neighbouring flowers read apart.
                    fcol *= 0.8 + 0.2 * smoothstep(0.0, -0.15, petal);
                    col = mix(col, fcol, smoothstep(px * scale / sz, -px * scale / sz, petal * sz / scale * 1.0) * 0.97);
                }
            }
        }
        col += blossom * 0.05 * exp(-max(bd, 0.0) * 60.0);
    }

    // Nearer petals over everything.
    l = fallingLayer(uv, 8.0, float2(0.25, 0.4), 0.35, 7.0, 1.0, 0.018, blossom, S);
    col = mix(col, l.rgb * 0.95, l.a * 0.6);
    l = fallingLayer(uv, 4.6, float2(0.2, 0.3), 0.3, 12.0, 1.0, 0.012, blossom, mix(S, float3(1.0), 0.3));
    col = mix(col, l.rgb, l.a * 0.8);

    return half4(finish(col, fc), 1.0);
}
"""

    private const val SCANLINES = """
// Arcade CRT: an arcade cabinet's attract mode on a curved tube. A vector shooter plays itself: a
// formation of neon ships sways over a scrolling perspective grid and wireframe mountains, the
// player's ship slides along the bottom and picks them off one by one - laser, flash, a burst of
// sparks, the score ticking up - while INSERT COIN blinks. Glowing phosphor, scanlines, a shadow
// mask, a rolling band, the glass's curve and reflection, and the cabinet's bezel round it.

float vline(float d, float w) { return 1.0 - smoothstep(0.0, w, abs(d)); }

// 3 x 5 pixel font: 0-9, then C H I N E R T U P S O, 21 = space.
float fontCode(float g) {
    if (g < 0.5) return 31599.0;
    if (g < 1.5) return 11415.0;
    if (g < 2.5) return 29671.0;
    if (g < 3.5) return 29647.0;
    if (g < 4.5) return 23497.0;
    if (g < 5.5) return 31183.0;
    if (g < 6.5) return 31215.0;
    if (g < 7.5) return 29257.0;
    if (g < 8.5) return 31727.0;
    if (g < 9.5) return 31695.0;
    if (g < 10.5) return 31015.0;
    if (g < 11.5) return 23533.0;
    if (g < 12.5) return 29847.0;
    if (g < 13.5) return 27501.0;
    if (g < 14.5) return 31143.0;
    if (g < 15.5) return 27565.0;
    if (g < 16.5) return 29842.0;
    if (g < 17.5) return 23407.0;
    if (g < 18.5) return 31716.0;
    if (g < 19.5) return 31183.0;
    if (g < 20.5) return 31599.0;
    return 0.0;
}

float glyphBit(float2 p, float g) {
    if (p.x < 0.0 || p.y < 0.0 || p.x >= 3.0 || p.y >= 5.0) return 0.0;
    float idx = 14.0 - (floor(p.y) * 3.0 + floor(p.x));
    return mod(floor(fontCode(g) / exp2(idx)), 2.0);
}

// "INSERT COIN"
float insertCoin(float i) {
    if (i < 0.5) return 12.0;
    if (i < 1.5) return 13.0;
    if (i < 2.5) return 19.0;
    if (i < 3.5) return 14.0;
    if (i < 4.5) return 15.0;
    if (i < 5.5) return 16.0;
    if (i < 6.5) return 21.0;
    if (i < 7.5) return 10.0;
    if (i < 8.5) return 20.0;
    if (i < 9.5) return 12.0;
    return 13.0;
}

// p in glyph pixels (4 per character). n characters of text; kind 0 = INSERT COIN, 1 = "1UP", 2 = "HI".
float label(float2 p, float kind) {
    float cell = floor(p.x / 4.0);
    float2 lp = float2(p.x - cell * 4.0, p.y);
    float g = 21.0;
    if (kind < 0.5) { if (cell >= 0.0 && cell < 11.0) g = insertCoin(cell); }
    else if (kind < 1.5) { if (cell < 0.5 && cell > -0.5) g = 1.0; else if (cell < 1.5 && cell > 0.5) g = 17.0; else if (cell < 2.5 && cell > 1.5) g = 18.0; }
    else { if (cell < 0.5 && cell > -0.5) g = 11.0; else if (cell < 1.5 && cell > 0.5) g = 12.0; }
    return glyphBit(lp, g);
}

// A 6-digit number at glyph pixels p.
float number(float2 p, float v) {
    float cell = floor(p.x / 4.0);
    if (cell < 0.0 || cell > 5.0) return 0.0;
    float dgt = mod(floor(v / exp2(log2(10.0) * (5.0 - cell)) + 0.0001), 10.0);
    return glyphBit(float2(p.x - cell * 4.0, p.y), floor(dgt));
}

// An enemy ship's outline distance, shape by row.
float enemyD(float2 p, float row, float s) {
    if (row < 0.5) return max(abs(p.x) + abs(p.y) - s, -(abs(p.x) + abs(p.y) - s * 0.45));
    if (row < 1.5) {
        float2 q = float2(abs(p.x), p.y);
        return min(sdSegment(q, float2(0.0, -s * 0.6), float2(s, s * 0.5)), sdSegment(q, float2(s, s * 0.5), float2(s * 0.4, s * 0.1)));
    }
    float r = length(p) - s * 0.6;
    float a = atan(p.y, p.x);
    return min(abs(r), max(abs(length(p) - s * 0.95), abs(fract(a / TAU * 6.0) - 0.5) * 2.0 - 0.25 + 0.0));
}

half4 main(float2 fc) {
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float asp = uRes.x / uRes.y;

    // The tube: the picture bulges, with a bezel round its rounded corners.
    float2 q = fc / uRes * 2.0 - 1.0;
    q *= 0.94;
    float2 qc = q * (1.0 + 0.05 * float2(q.y * q.y, q.x * q.x));
    float2 uv = (qc * 0.5 + 0.5) * float2(asp, 1.0);
    float edge = sdRoundBox(qc * float2(asp, 1.0), float2(asp, 1.0) - 0.002, 0.12);
    float w = 2.4 / uRes.y;

    float3 col = BG * 0.6;
    // Stars streaming down behind everything.
    col += float3(0.9, 0.95, 1.0) * dots(uv, 34.0, float2(0.0, -t * 0.9), 0.3, 0.08, 2.0) * 0.55;
    col += S * dots(uv, 16.0, float2(0.0, -t * 0.45), 0.2, 0.07, 6.0) * 0.4;

    // Horizon: wireframe mountains and the grid rushing towards us.
    float hz = 0.60;
    float mx = uv.x * 4.0;
    float mt = hz - 0.07 * abs(fract(mx) - 0.5) * 2.0 * (0.5 + hash11(floor(mx))) - 0.02 * abs(fract(mx * 3.0) - 0.5);
    float mdist = abs(uv.y - mt);
    col += mix(A, S, 0.5) * (vline(mdist, w) * 0.8 + exp(-mdist * 120.0) * 0.25) * step(uv.y, hz + 0.002);
    col += A * 0.18 * exp(-abs(uv.y - hz) * 30.0);
    if (uv.y > hz) {
        float camH = 0.06;
        float z = camH / (uv.y - hz);
        float gx = (uv.x - asp * 0.5) * z;
        float gz = z + t * 0.35;
        float sx = abs(fract(gx * 22.0) - 0.5) / 22.0 / z;
        float sz = abs(fract(gz * 7.0) - 0.5) / 7.0 * camH / (z * z);
        float fade = sat((uv.y - hz) * 9.0);
        float grid = vline(sx, w * 1.3) + vline(sz, w * 1.3);
        float glowG = exp(-sx * 220.0) + exp(-sz * 220.0);
        col += mix(S, A, 0.35) * (sat(grid) * 1.1 + glowG * 0.25) * fade;
        col += A * 0.06 * fade * (1.0 - sat((uv.y - hz) * 2.0));
    }

    // The formation: 3 rows of 7, swaying. Each round of 16 s the player shoots some down.
    float wave = floor(t / 16.0);
    float rt = t - wave * 16.0;
    float2 sway = float2(0.09 * sin(t * 0.55), 0.015 * sin(t * 1.3));
    float3 shipsCol = float3(0.0);
    float2 target = float2(-10.0);
    float laserT = -1.0;
    float score = 1200.0 + wave * 4200.0;
    for (int r = 0; r < 3; r++) {
        for (int c = 0; c < 7; c++) {
            float fr = float(r);
            float fcol = float(c);
            float n = fr * 7.0 + fcol;
            float2 pos = float2(asp * 0.5 + (fcol - 3.0) * 0.105, 0.17 + fr * 0.085) + sway;
            pos.y += 0.01 * sin(t * 2.0 + fcol * 0.8 + fr);
            // When this one is shot (some survive the round).
            float hit = 1.0 + 13.5 * hash11(n * 7.3 + wave * 3.1);
            float shot = step(0.35, hash11(n * 2.9 + wave));
            float dead = shot * step(hit, rt);
            score += shot * step(hit, rt) * (150.0 - fr * 50.0);
            float since = rt - hit;
            // The next one due gets the laser.
            if (shot > 0.5 && since > -0.3 && since < 0.0) { target = pos; laserT = since; }
            if (dead < 0.5) {
                float d = enemyD(uv - pos, fr, 0.026);
                float3 ec = fr < 0.5 ? A : (fr < 1.5 ? S : mix(A, S, 0.5));
                shipsCol += ec * (vline(d, w) + exp(-abs(d) * 90.0) * 0.35);
            } else if (since < 0.7) {
                // Explosion: a flash and sparks flying out.
                float2 e = uv - pos;
                float el = length(e);
                float ring = 0.01 + since * 0.09;
                float ea = atan(e.y, e.x);
                float spark = step(0.5, hash11(floor(ea / TAU * 16.0) + n)) * exp(-abs(el - ring) * 260.0) * step(abs(fract(ea / TAU * 16.0) - 0.5), 0.22) * (1.0 - since / 0.7);
                shipsCol += mix(float3(1.0), A, sat(since * 2.0)) * (spark * 1.5 + exp(-el * 40.0) * (1.0 - since / 0.7) * 1.2);
            }
        }
    }
    col += shipsCol;

    // The player's ship: slides under its next target, fires.
    float px0 = asp * 0.5 + 0.32 * sin(t * 0.43) * cos(t * 0.17);
    if (laserT > -0.3) px0 = mix(px0, target.x, 0.85);
    float2 sp = float2(px0, 0.82);
    float2 sq = uv - sp;
    float hull = min(sdSegment(float2(abs(sq.x), sq.y), float2(0.0, -0.03), float2(0.03, 0.015)), sdSegment(float2(abs(sq.x), sq.y), float2(0.03, 0.015), float2(0.0, 0.006)));
    col += float3(0.85, 1.0, 0.95) * (vline(hull, w) + exp(-hull * 80.0) * 0.4);
    col += A * exp(-length(sq - float2(0.0, 0.02)) * 90.0) * (0.6 + 0.4 * sin(t * 30.0));
    if (laserT > -0.3) {
        float ld = sdSegment(uv, sp + float2(0.0, -0.035), target);
        col += mix(S, float3(1.0), 0.5) * (vline(ld, w * 1.2) * 1.4 + exp(-ld * 160.0) * 0.5);
    }

    // The score, the high score, INSERT COIN blinking.
    float gs = 170.0;
    float2 hud = uv * gs;
    float txt = label(hud - float2(0.08 * gs, 0.05 * gs), 1.0) + number(hud - float2(0.08 * gs, 0.09 * gs), score);
    txt += label(hud - float2(asp * 0.5 * gs - 4.0, 0.05 * gs), 2.0) + number(hud - float2(asp * 0.5 * gs - 12.0, 0.09 * gs), 42000.0 + wave * 1000.0);
    float blink = step(0.5, fract(t * 0.8));
    txt += label(hud - float2(asp * 0.5 * gs - 22.0, 0.92 * gs), 0.0) * blink;
    col = mix(col, float3(1.0, 0.95, 0.85), sat(txt) * 0.9);

    // Tube: scanlines (about 240 of them), the shadow mask, a rolling band, phosphor bloom.
    float lines = 240.0;
    float scan = 0.72 + 0.28 * (0.5 + 0.5 * cos(uv.y * lines * TAU));
    float m = mod(floor(fc.x), 3.0);
    float3 mask = m < 1.0 ? float3(1.0, 0.85, 0.85) : (m < 2.0 ? float3(0.85, 1.0, 0.85) : float3(0.85, 0.85, 1.0));
    col *= scan * mask;
    col *= 1.0 + 0.08 * exp(-abs(fract(uv.y * 0.5 - t * 0.06) - 0.5) * 16.0);
    col += col * col * 0.3;
    float vig = pow(max((1.0 - q.x * q.x * 0.9) * (1.0 - q.y * q.y * 0.9), 0.0), 0.4);
    col *= vig;
    // The glass catches the room: a soft highlight top left.
    col += float3(0.6, 0.65, 0.8) * 0.05 * exp(-length((q - float2(-0.55, -0.6)) * float2(1.0, 1.6)) * 2.5);
    // Outside the tube: the cabinet's bezel, black plastic with a little sheen.
    float inside = smoothstep(0.004, -0.004, edge);
    float3 bezel = float3(0.025, 0.025, 0.03) + mix(A, S, 0.5) * 0.04 * exp(-max(edge, 0.0) * 18.0) + float3(0.05) * sat(-q.y) * 0.3;
    col = mix(bezel, col, inside);
    return half4(finish(col, fc), 1.0);
}
"""

    private const val MUSIC = """
// Now playing: a soft field of the cover's colours (or the cover itself, heavily blurred), and across
// it an equalizer wave: a glowing band whose height follows eight frequency bands (bass in the middle,
// highs towards the edges), with thin lines riding it like an audio visualizer. A ring rolls out on
// every kick and sparks are lifted by the highs. Without real audio the bands are simulated.
uniform shader uArt;     // the cover, square and blurred smooth (MusicTheme.softArt)
uniform float2 uArtSize; // its size in pixels
uniform float uHasArt;   // 0 = no cover yet (or the cover is switched off)
uniform float uBass;     // 0..1, smoothed
uniform float uMid;
uniform float uHigh;
uniform float uBeatAge;  // seconds since the last kick (large = none)
uniform float uPlaying;  // 0..1, fades when paused
uniform float uPlayT;    // seconds spent playing (NowPlayingScene): motion that eases to a stop when paused
uniform float uIntensity; // 0..1, Settings › strength
uniform float4 uEqA;     // bands 0-3 (low), 0..1
uniform float4 uEqB;     // bands 4-7 (high)
uniform float uWaveY;    // 0..1 from the top: where the wave runs (clear of the game row)
uniform float uWaveH;    // room for the wave above / below that line (share of the height; the player sits under it)

float2 mirrorUv(float2 q) { return 1.0 - abs(1.0 - mod(q, 2.0)); }

float eqBand(float i) {
    if (i < 0.5) return uEqA.x;
    if (i < 1.5) return uEqA.y;
    if (i < 2.5) return uEqA.z;
    if (i < 3.5) return uEqA.w;
    if (i < 4.5) return uEqB.x;
    if (i < 5.5) return uEqB.y;
    if (i < 6.5) return uEqB.z;
    return uEqB.w;
}

// The spectrum at m (0 = centre of the screen = bass, 1 = edge = highs), smoothly interpolated.
float eqAt(float m) {
    float f = clamp(m, 0.0, 1.0) * 7.0;
    float i = floor(f);
    float u = f - i;
    u = u * u * (3.0 - 2.0 * u);
    return mix(eqBand(i), eqBand(min(i + 1.0, 7.0)), u);
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float k = uIntensity;
    float play = uPlaying;
    float bass = uBass * play;
    float mid = uMid * play;
    float high = uHigh * play;
    float kick = exp(-uBeatAge * 4.0) * play;

    // 1. Background: the cover, very soft and slowly drifting; or, without one, the palette swirling.
    float2 p = uv - float2(asp * 0.5, 0.5);
    float zoom = 1.6 + 0.08 * sin(t * 0.045) - (0.05 * bass + 0.03 * kick) * k;
    p = rot(0.05 * sin(t * 0.031)) * p / zoom;
    float2 wq = p * 2.0;
    p += (float2(vnoise(wq + float2(t * 0.1, 0.0)), vnoise(wq + float2(7.3, -t * 0.08))) - 0.5) * (0.08 + 0.08 * mid * k);
    float2 q = p / max(asp, 1.0) + 0.5;
    float3 art = float3(uArt.eval(mirrorUv(q) * uArtSize).rgb);
    float sw = fbm3(uv * 1.4 + float2(t * 0.03, -t * 0.02));
    float3 noArt = mix(BG * 1.4 + A * 0.08, mix(A, S, sw) * 0.5, smoothstep(0.25, 0.8, sw));
    float al = dot(art, float3(0.299, 0.587, 0.114));
    art = max(mix(float3(al), art, 1.3), 0.0);
    float3 col = mix(noArt, art * (0.56 + 0.12 * bass * k), uHasArt);
    col = mix(col, BG, 0.16);

    // 2. Coloured light that swells with the overall level.
    float lvl = bass * 0.5 + mid * 0.3 + high * 0.2;
    float2 g1 = float2(asp * (0.25 + 0.1 * sin(t * 0.07)), uWaveY - 0.15 + 0.08 * cos(t * 0.05));
    float2 g2 = float2(asp * (0.78 + 0.08 * cos(t * 0.06)), uWaveY + 0.05 + 0.1 * sin(t * 0.04));
    col += A * exp(-length(uv - g1) * 2.6) * (0.06 + 0.25 * lvl * k);
    col += S * exp(-length(uv - g2) * 3.0) * (0.05 + 0.2 * lvl * k);

    // 3. The equalizer wave. m: 0 in the middle (bass) to 1 at the edges (highs).
    float x = uv.x / asp;
    float m = abs(x - 0.5) * 2.0;
    float e = eqAt(m) * play;
    // A little travelling ripple so neighbouring bands never look like flat steps.
    e *= 0.85 + 0.15 * sin(x * 38.0 - t * 4.0);
    float gain = 0.45 + 0.55 * k;
    // Tapers to nothing at the screen edges.
    float edge = smoothstep(1.0, 0.82, m);
    // Never taller than its room, so the player right under it doesn't cover it.
    float room = uWaveH > 0.001 ? uWaveH : 0.2;
    float h = (0.006 + (room - 0.012) * e * gain) * edge;
    float dy = uv.y - uWaveY;
    // The filled band: brightest along its rims, soft inside.
    float inside = smoothstep(h + 0.004, h - 0.004, abs(dy));
    float rim = exp(-abs(abs(dy) - h) / 0.0035);
    float3 waveCol = mix(A, S, smoothstep(0.0, 1.0, m));
    col += waveCol * inside * (0.1 + 0.25 * e) * (abs(dy) / max(h, 0.001) * 0.6 + 0.4);
    col += mix(waveCol, float3(1.0), 0.35) * rim * (0.35 + 0.65 * e) * edge;
    // Thin lines riding the band, each a different frequency and speed, scaled by the spectrum.
    float l1 = uWaveY + h * 0.85 * sin(x * 9.0 + t * 1.6);
    float l2 = uWaveY + h * 0.7 * sin(x * 14.0 - t * 2.3 + 1.7);
    float l3 = uWaveY + h * 0.55 * sin(x * 23.0 + t * 3.1 + 4.0);
    float lines = exp(-abs(uv.y - l1) / 0.0025) + 0.8 * exp(-abs(uv.y - l2) / 0.002) + 0.6 * exp(-abs(uv.y - l3) / 0.0018);
    col += mix(S, A, 0.5) * lines * (0.15 + 0.6 * e) * edge * (0.4 + 0.6 * play);
    // A wide glow around the band that pumps with the bass.
    col += waveCol * exp(-abs(dy) / (0.04 + h)) * (0.04 + 0.18 * bass * k) * edge;

    // 4. A ring rolling out from the wave's centre on every kick.
    float2 rc = float2(asp * 0.5, uWaveY);
    float r = length((uv - rc) * float2(1.0, 1.25));
    float ringR = uBeatAge * 0.8;
    r += (vnoise(float2(atan(uv.y - rc.y, uv.x - rc.x) * 3.0, t * 0.5)) - 0.5) * 0.08 * min(ringR, 0.4);
    float ring = exp(-abs(r - ringR) * 20.0) + 0.5 * exp(-abs(r - ringR * 0.7) * 30.0);
    col += mix(A, S, 0.4) * ring * exp(-uBeatAge * 2.4) * smoothstep(0.02, 0.12, ringR) * 0.4 * k * play;

    // 5. Sparks lifted by the highs.
    float rise = 0.15 * t + 0.25 * uPlayT;
    float sp = dots(uv + float2(sin(uv.y * 5.0 + t) * 0.02, 0.0), 22.0, float2(0.0, rise * 22.0 / 6.0), 0.3, 0.1, 3.0);
    float sp2 = dots(uv, 12.0, float2(t * 0.05, rise * 2.0), 0.2, 0.08, 9.0);
    col += mix(S, float3(1.0), 0.4) * sp * (0.12 + 0.6 * high * k) + A * sp2 * (0.1 + 0.4 * high * k);

    // 6. The whole picture pumps a little on the kick.
    col *= 1.0 + 0.12 * kick * k;
    return half4(finish(col, fc), 1.0);
}
"""

    private const val ANIME_FLAMES = """
// Blaze: anime fire. Big flame tongues drawn in flat, hard-edged colour bands with a dark outline
// (no soft gradients), a burst of light turning behind them, manga halftone dots in the shadows,
// diamond sparks with star glints and speed lines rushing upwards. Every few seconds the fire
// surges higher.
// Anime / manga drawing tricks shared by the anime-inspired scenes: focus (speed) lines, halftone
// dots, flat cel bands and jagged lightning. Generic drawing styles only - no characters or symbols.

// Focus lines radiating from c, the classic "speed lines" of a dramatic panel. n = how many around,
// they flicker to new positions 8 times a second. Clear near the centre, strongest at the edges.
float focusLines(float2 uv, float2 c, float t, float n, float seed) {
    float2 d = uv - c;
    float a = atan(d.y, d.x) / TAU + 0.5;
    float r = length(d);
    float id = floor(a * n);
    float h = hash11(id + seed + floor(t * 8.0) * 13.0);
    float w = abs(fract(a * n) - 0.5) * 2.0;
    float line = (1.0 - smoothstep(0.0, 0.12 + 0.25 * h, w)) * step(0.62, h);
    return line * smoothstep(0.22 + 0.35 * h, 0.95, r);
}

// Manga halftone: dots on a 45-degree grid, bigger where v is larger (0..1). 1 inside a dot.
float halftone(float2 uv, float scale, float v) {
    float2 p = rot(0.785398) * uv * scale;
    float2 g = fract(p) - 0.5;
    return 1.0 - smoothstep(v * 0.62 - 0.04, v * 0.62 + 0.04, length(g));
}

// Linear noise between random points: kinked, jagged lines (lightning) instead of smooth curves.
float jag(float x, float s) {
    float i = floor(x);
    return mix(hash11(i * 1.37 + s), hash11((i + 1.0) * 1.37 + s), fract(x)) - 0.5;
}

// Distance to a lightning bolt from a to b: a straight segment pushed sideways by jagged noise,
// thinning towards its ends.
float bolt(float2 p, float2 a, float2 b, float seed, float amp) {
    float2 ba = b - a;
    float L = max(length(ba), 1e-4);
    float2 dir = ba / L;
    float2 nrm = float2(-dir.y, dir.x);
    float2 pa = p - a;
    float along = dot(pa, dir);
    float h = sat(along / L);
    float off = (jag(h * 7.0, seed) + 0.45 * jag(h * 23.0, seed + 9.0)) * amp * sin(PI * h);
    float side = dot(pa, nrm) - off;
    float outside = max(-along, along - L);
    return length(float2(side, max(outside, 0.0)));
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float yb = 1.0 - uv.y;

    float surge = 0.5 + 0.5 * sin(t * 0.9);
    surge = surge * surge * surge;

    // Background: dark, warmer towards the fire, halftone dots growing towards the bottom.
    float3 col = mix(BG * 0.8, BG + A * 0.12, smoothstep(0.0, 1.0, uv.y));
    float ht = halftone(uv, 70.0, 0.12 + 0.5 * smoothstep(0.25, 1.0, uv.y));
    col = mix(col, BG + A * 0.22, ht * 0.35);

    // Light burst behind the fire: turning wedges from below the centre.
    float2 bc = float2(asp * 0.5, 1.2);
    float2 bd = uv - bc;
    float ba = atan(bd.x, -bd.y);
    float br = length(bd);
    float rays = step(0.5, fract(ba * 3.8197 + t * 0.04));
    col += mix(A, S, 0.5) * rays * exp(-br * 1.4) * (0.1 + 0.08 * surge);

    // Flame field: noise scrolled up and warped, cut off with height, then posterised.
    float warp = fbm3(float2(uv.x * 2.0, yb * 1.5 - t * 0.9));
    // Tongues lick upwards and sway; their sides lean in so the tips come to a point.
    float sx = uv.x + (warp - 0.5) * 0.12 * (0.3 + yb * 2.0);
    float2 fp = float2(sx * 4.0, yb * 2.6 - t * 1.7);
    float n = fbm(fp);
    float t1 = pow(abs(sin(sx * 6.0 + t * 0.7)), 5.0);
    float t2 = pow(abs(sin(sx * 11.0 - t * 1.1 + 1.3)), 7.0);
    float height = 0.13 + 0.3 * t1 + 0.16 * t2 + 0.05 * vnoise(float2(sx * 2.0 + t * 0.3, 1.0)) + 0.1 * surge;
    float f = n * 0.9 - yb / height + 0.62;
    float b1 = step(0.18, f);
    float b2 = step(0.36, f);
    float b3 = step(0.55, f);
    float b4 = step(0.74, f);
    float rim = step(0.13, f) - b1;
    float3 deep = A * float3(0.8, 0.28, 0.12);
    col = mix(col, BG * 0.3, rim * 0.9);
    col = mix(col, deep, b1);
    col = mix(col, A, b2);
    col = mix(col, mix(A, S, 0.6), b3);
    col = mix(col, mix(S, float3(1.0), 0.6), b4);
    // Halftone shading inside the darkest band.
    col = mix(col, deep * 0.6, (b1 - b2) * halftone(uv, 110.0, 0.45) * 0.5);
    // Glow over the fire.
    col += A * 0.12 * exp(-yb * 4.0);

    // Speed lines rushing up.
    float lx = floor(uv.x * 60.0);
    float hl = hash11(lx + 3.0);
    float ly = fract(uv.y * 0.6 + t * (1.0 + hl) + hl * 7.0);
    float thin = 1.0 - smoothstep(0.0, 0.25, abs(fract(uv.x * 60.0) - 0.5) * 2.0 - 0.55);
    float sl = step(0.82, hl) * smoothstep(0.0, 0.3, ly) * (1.0 - smoothstep(0.3, 0.42, ly)) * thin;
    col += mix(S, float3(1.0), 0.5) * sl * (0.2 + 0.2 * surge) * smoothstep(0.05, 0.7, uv.y);

    // Diamond sparks rising and swaying, with a four-point glint.
    for (int k = 0; k < 2; k++) {
        float fk = float(k);
        float scale = 9.0 + fk * 7.0;
        float2 p = (uv + float2(sin(uv.y * 6.0 + t * 0.9 + fk) * 0.02, 0.0)) * scale + float2(fk * 3.7, t * (1.3 + fk * 0.6));
        float2 id = floor(p);
        float2 g = fract(p) - 0.5;
        float2 rr = hash22(id + 11.0 * fk);
        if (rr.x < 0.32) {
            float2 q = g - (hash22(id + 5.3 + fk) - 0.5) * 0.5;
            float tw = 0.5 + 0.5 * sin(t * (3.0 + 4.0 * rr.y) + rr.x * 40.0);
            float dia = abs(q.x) + abs(q.y) * 0.65;
            float body = 1.0 - smoothstep(0.05, 0.065, dia);
            float glint = exp(-abs(q.x) * 70.0) * exp(-abs(q.y) * 7.0) + exp(-abs(q.y) * 70.0) * exp(-abs(q.x) * 7.0);
            float fade = smoothstep(0.0, 0.8, uv.y);
            col += (mix(S, float3(1.0), 0.5) * body + mix(A, float3(1.0), 0.6) * glint * tw * 0.6) * fade * (0.8 - 0.3 * fk);
        }
    }

    return half4(finish(col, fc), 1.0);
}
"""

    private const val CEL_SKY = """
// Summer sky: a deep anime-blue sky, big cel-shaded cumulus clouds drifting by (flat bottoms,
// bright tops, one hard shadow tone), a sun with a lens streak and ghosts, a contrail slowly
// drawing itself across, birds now and then, and power lines swaying gently in the foreground.

// Cloud density for one layer: puffy noise in a band standing on a flat base line (nothing
// below it), broken into separate clouds by a slow mask. Inside where it's above 0.5.
float cloudDens(float2 uv, float base, float seed, float t, float speed, float scale) {
    float x = uv.x * scale + t * speed + seed * 13.0;
    float lift = (base - uv.y) * scale;
    float n = fbm(float2(x * 2.2, uv.y * scale * 3.4 + seed * 5.0));
    float shape = n - 0.08 - abs(lift - 0.1) * 3.4;
    shape += (vnoise(float2(x * 0.9, seed * 3.0)) - 0.5) * 1.3;
    return shape - step(lift, 0.0) * 9.0;
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    // Sky: deep at the top, pale near the horizon.
    float3 top = mix(BG, A, 0.5);
    float3 hor = mix(A, float3(1.0), 0.6);
    float3 col = mix(top, hor, pow(sat(uv.y / 0.95), 1.5));

    // Sun up on the right, its glow, a soft streak and lens ghosts towards the middle.
    float2 sc = float2(asp * 0.84, 0.14);
    float sd = length(uv - sc);
    col += mix(S, float3(1.0), 0.5) * exp(-sd * 4.5) * 0.4;
    col += float3(1.0) * exp(-abs(uv.y - sc.y) * 90.0) * exp(-abs(uv.x - sc.x) * 2.5) * 0.18;
    float2 toC = float2(asp * 0.5, 0.5) - sc;
    for (int k = 0; k < 3; k++) {
        float fk = float(k);
        float2 gp = sc + toC * (0.55 + fk * 0.45);
        float gr = 0.025 + fk * 0.02;
        float gd = length(uv - gp);
        col += mix(S, A, fk * 0.4) * (1.0 - smoothstep(gr * 0.85, gr, gd)) * 0.06;
    }
    col = mix(col, float3(1.0), 1.0 - smoothstep(0.042, 0.047, sd));

    // Contrail: a plane drawing a line across over 40 s, the line spreading and fading behind it.
    float cyc = fract(t / 40.0);
    float cx = (cyc * 1.4 - 0.2) * asp;
    float cyl = 0.24 + 0.06 * sin(uv.x * 0.8) - uv.x * 0.04;
    float behind = cx - uv.x;
    float spread = 0.0015 + max(behind, 0.0) * 0.004;
    float trail = step(0.0, behind) * exp(-max(behind, 0.0) * 1.2) * (1.0 - smoothstep(spread, spread * 2.5, abs(uv.y - cyl)));
    col = mix(col, float3(1.0), trail * 0.6);

    // Cloud layers, far to near: farther ones smaller, paler and slower.
    float3 shadeCol = mix(top, hor, 0.45) * 0.9 + mix(A, S, 0.3) * 0.08;
    for (int k = 0; k < 3; k++) {
        float fk = float(k);
        float base = 0.5 + fk * 0.17;
        float scale = 1.6 - fk * 0.45;
        float speed = 0.022 + fk * 0.016;
        float dens = cloudDens(uv, base, fk, t, speed, scale);
        float cover = step(0.5, dens);
        // Cel shadow: a band along the underside (the point a little lower is already outside).
        float below = cloudDens(uv + float2(-0.012, 0.035 / scale), base, fk, t, speed, scale);
        float lit = step(0.5, below);
        float far = 1.0 - fk * 0.35;
        float3 litC = mix(float3(1.0), hor, 0.25 * far);
        float3 sh = mix(shadeCol, hor, 0.4 * far);
        col = mix(col, mix(sh, litC, lit), cover);
    }

    // Birds: a small flock crossing every 25 s.
    float bc = fract(t / 25.0);
    for (int k = 0; k < 5; k++) {
        float fk = float(k);
        float2 bp = float2((bc * 1.5 - 0.25) * asp - fk * 0.035, 0.3 + fk * 0.018 + 0.01 * sin(t + fk));
        float2 q = uv - bp;
        float flap = sin(t * 9.0 + fk * 1.3) * 0.006;
        float wing = abs(q.y + abs(q.x) * 0.55 - flap * (1.0 - abs(q.x) / 0.012));
        float bird = (1.0 - smoothstep(0.0008, 0.0018, wing)) * step(abs(q.x), 0.012);
        col = mix(col, BG * 0.6, bird * 0.8);
    }

    // Power lines and a pole in the foreground, swaying a little.
    float sway = sin(t * 0.6) * 0.004;
    float3 dark = BG * 0.45;
    for (int k = 0; k < 3; k++) {
        float fk = float(k);
        float xx = uv.x / asp;
        float y = 0.8 + fk * 0.035 + 0.07 * (xx - 0.3) * (xx - 0.3) + sway * (1.0 + fk) * sin(xx * PI);
        col = mix(col, dark, 1.0 - smoothstep(0.0012, 0.0024, abs(uv.y - y)));
    }
    float px = asp * 0.92;
    col = mix(col, dark, step(abs(uv.x - px), 0.006) * step(0.74, uv.y));
    col = mix(col, dark, step(abs(uv.y - 0.785), 0.004) * step(abs(uv.x - px), 0.06));

    return half4(finish(col, fc), 1.0);
}
"""

    private const val MECHA_HUD = """
// Mecha HUD: a cockpit display. A faint hex grid with pulses running through it, target rings
// turning at different speeds with tick marks, a radar sweep, data bars ticking along the left,
// a horizon ladder on the right and a warning chevron band that flashes now and then.

float4 hexCell(float2 p) {
    float2 r = float2(1.0, 1.7320508);
    float2 h = r * 0.5;
    float2 a = mod(p, r) - h;
    float2 b = mod(p - h, r) - h;
    float2 gv = dot(a, a) < dot(b, b) ? a : b;
    return float4(gv, p - gv);
}

float hexEdge(float2 gv) {
    float2 q = abs(gv);
    return 0.5 - max(dot(q, float2(0.5, 0.8660254)), q.x);
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    float3 col = BG * 0.85 + mix(A, S, 0.5) * 0.03 * (1.0 - uv.y);

    // Hex grid with pulses.
    float4 hc = hexCell(uv * 16.0);
    float e = hexEdge(hc.xy);
    float grid = 1.0 - smoothstep(0.0, 0.05, e);
    float pulse = sin(length(hc.zw / 16.0 - float2(asp * 0.5, 0.5)) * 9.0 - t * 1.6);
    float cellLit = step(0.97, hash12(hc.zw + floor(t * 1.5)));
    col += S * grid * (0.05 + 0.08 * smoothstep(0.85, 1.0, pulse));
    col += S * cellLit * (1.0 - smoothstep(0.0, 0.35, -e + 0.5)) * 0.04;

    // Target rings in the middle.
    float2 c = float2(asp * 0.5, 0.48);
    float2 d = uv - c;
    float r = length(d);
    float a = atan(d.y, d.x) / TAU + 0.5;
    float ring1 = 1.0 - smoothstep(0.0015, 0.003, abs(r - 0.17));
    float ring2 = (1.0 - smoothstep(0.002, 0.0035, abs(r - 0.25))) * step(0.5, fract(a * 3.0 + t * 0.06));
    float ring3 = (1.0 - smoothstep(0.004, 0.007, abs(r - 0.33))) * step(0.82, fract(a * 8.0 - t * 0.035));
    float ticks = (1.0 - smoothstep(0.0, 0.012, abs(r - 0.205) - 0.012)) * step(0.85, fract(a * 72.0 + t * 0.02));
    float majors = (1.0 - smoothstep(0.0, 0.02, abs(r - 0.21) - 0.02)) * step(0.93, fract(a * 8.0 + t * 0.02));
    col += A * (ring1 * 0.5 + ring2 * 0.4 + ring3 * 0.35 + ticks * 0.45 + majors * 0.6);
    // Crosshair gaps.
    float xhair = (1.0 - smoothstep(0.0008, 0.0018, min(abs(d.x), abs(d.y)))) * step(0.04, r) * (1.0 - step(0.12, r));
    col += A * xhair * 0.6;
    // Radar sweep with its fading trail.
    float sw = fract(t * 0.12);
    float lag = fract(sw - a);
    col += S * (1.0 - step(0.33, r)) * exp(-lag * 18.0) * 0.18;
    col += S * (1.0 - step(0.33, r)) * (1.0 - smoothstep(0.0, 0.004, lag)) * 0.35;
    // Blips the sweep has just passed.
    float2 bp = floor(d * 18.0);
    float bh = hash12(bp + 7.0);
    float ba = atan(bp.y + 0.5, bp.x + 0.5) / TAU + 0.5;
    float blipLag = fract(sw - ba);
    float blip = step(0.985, bh) * (1.0 - step(0.31, r)) * exp(-blipLag * 4.0) * (1.0 - smoothstep(0.1, 0.25, length(fract(d * 18.0) - 0.5)));
    col += A * blip * 0.9;

    // Data bars along the left, a new reading every half second.
    float lx = uv.x - 0.06;
    float row = floor((uv.y - 0.2) * 40.0);
    if (row >= 0.0 && row < 14.0 && lx > 0.0) {
        float len = 0.04 + 0.16 * hash11(row * 3.1 + floor(t * 2.0 + row * 0.13));
        float inRow = step(0.2, fract((uv.y - 0.2) * 40.0));
        col += mix(S, A, step(0.15, len - 0.04)) * step(lx, len) * inRow * 0.35;
    }

    // Horizon ladder on the right, rolling slowly.
    float rx = uv.x - asp * 0.86;
    if (abs(rx) < 0.07) {
        float roll = sin(t * 0.3) * 0.15;
        float2 q = rot(roll) * float2(rx, uv.y - 0.5);
        float rung = abs(fract(q.y * 9.0 + t * 0.15) - 0.5);
        float rl = (1.0 - smoothstep(0.02, 0.05, rung)) * step(abs(q.x), 0.05) * step(0.012, abs(q.x));
        col += S * rl * 0.4 * (1.0 - smoothstep(0.2, 0.32, abs(uv.y - 0.5)));
    }

    // Warning band: chevrons racing along the bottom, flashing for a few seconds every 15 s.
    float wc = fract(t / 15.0);
    float warn = step(wc, 0.18) * step(0.5, fract(t * 2.5));
    float band = step(abs(uv.y - 0.9), 0.012);
    float chev = step(0.5, fract((uv.x + abs(uv.y - 0.9) * 1.5) * 14.0 - t * 2.0));
    col = mix(col, mix(col, A, 0.75), band * chev * warn);
    col += A * warn * 0.04;

    // Scanlines.
    col *= 0.93 + 0.07 * sin(fc.y * 1.6);

    return half4(finish(col, fc), 1.0);
}
"""

    private const val MOON_BLADE = """
// Moon blade: a night field under a huge moon, thin clouds sliding across it, petals on the wind
// and grass swaying below - and every few seconds a crescent sword slash flashes across the screen
// with speed lines, an afterimage and a brief white flash.
// Leaves / petals tumbling down (or along the wind). One per cell at most, so it stays cheap.
// kind 0 = leaf, 1 = petal. Returns colour (not premultiplied) and coverage.
float4 fallingLayer(float2 uv, float scale, float2 vel, float sway, float seed, float kind, float blur, float3 c1, float3 c2) {
    float2 p = uv * scale - vel * uTime;
    p.x += sway * sin(uTime * 0.55 + p.y * 1.7 + seed);
    float2 id = floor(p);
    float2 f = fract(p) - 0.5;
    float2 r = hash22(id + seed);
    if (r.x > 0.5) return float4(0.0);
    float2 o = (hash22(id + seed + 3.7) - 0.5) * 0.36;
    float2 q = f - o;
    float dir = r.x > 0.25 ? 1.0 : -1.0;
    q = rot(uTime * (0.35 + 0.7 * r.y) * dir + r.y * TAU) * q;
    float flip = cos(uTime * (0.7 + r.x) + r.y * 9.0);
    q.y /= max(abs(flip), 0.22);
    float d;
    float shade;
    if (kind < 0.5) {
        float L = 0.2;
        float x = q.x / L;
        float w = 0.075 * (1.0 - x * x) * (1.0 + 0.25 * x);
        d = max(abs(q.y) - w, abs(q.x) - L);
        float vein = (1.0 - smoothstep(0.0, 0.01, abs(q.y))) * step(abs(q.x), L * 0.85);
        shade = (0.8 + 0.3 * sign(q.y) * flip) * (1.0 - 0.3 * vein);
    } else {
        float w = 0.1 * (0.5 + 0.5 * sat((q.x + 0.15) / 0.3));
        d = (length(float2(q.x / 0.15, q.y / w)) - 1.0) * 0.07;
        d = max(d, -(length(q - float2(0.165, 0.0)) - 0.04));
        shade = 0.85 + 0.25 * (q.x / 0.15) * flip;
    }
    float a = 1.0 - smoothstep(-blur, blur, d);
    return float4(mix(c1, c2, r.y) * shade, a);
}

// Anime / manga drawing tricks shared by the anime-inspired scenes: focus (speed) lines, halftone
// dots, flat cel bands and jagged lightning. Generic drawing styles only - no characters or symbols.

// Focus lines radiating from c, the classic "speed lines" of a dramatic panel. n = how many around,
// they flicker to new positions 8 times a second. Clear near the centre, strongest at the edges.
float focusLines(float2 uv, float2 c, float t, float n, float seed) {
    float2 d = uv - c;
    float a = atan(d.y, d.x) / TAU + 0.5;
    float r = length(d);
    float id = floor(a * n);
    float h = hash11(id + seed + floor(t * 8.0) * 13.0);
    float w = abs(fract(a * n) - 0.5) * 2.0;
    float line = (1.0 - smoothstep(0.0, 0.12 + 0.25 * h, w)) * step(0.62, h);
    return line * smoothstep(0.22 + 0.35 * h, 0.95, r);
}

// Manga halftone: dots on a 45-degree grid, bigger where v is larger (0..1). 1 inside a dot.
float halftone(float2 uv, float scale, float v) {
    float2 p = rot(0.785398) * uv * scale;
    float2 g = fract(p) - 0.5;
    return 1.0 - smoothstep(v * 0.62 - 0.04, v * 0.62 + 0.04, length(g));
}

// Linear noise between random points: kinked, jagged lines (lightning) instead of smooth curves.
float jag(float x, float s) {
    float i = floor(x);
    return mix(hash11(i * 1.37 + s), hash11((i + 1.0) * 1.37 + s), fract(x)) - 0.5;
}

// Distance to a lightning bolt from a to b: a straight segment pushed sideways by jagged noise,
// thinning towards its ends.
float bolt(float2 p, float2 a, float2 b, float seed, float amp) {
    float2 ba = b - a;
    float L = max(length(ba), 1e-4);
    float2 dir = ba / L;
    float2 nrm = float2(-dir.y, dir.x);
    float2 pa = p - a;
    float along = dot(pa, dir);
    float h = sat(along / L);
    float off = (jag(h * 7.0, seed) + 0.45 * jag(h * 23.0, seed + 9.0)) * amp * sin(PI * h);
    float side = dot(pa, nrm) - off;
    float outside = max(-along, along - L);
    return length(float2(side, max(outside, 0.0)));
}

// The slash: a bright crescent stroke along a big circle, drawn in quickly, then fading.
float slashStroke(float2 uv, float2 c, float R, float a0, float a1, float prog, float width) {
    float2 d = uv - c;
    float ang = atan(d.y, d.x);
    float u = (ang - a0) / (a1 - a0);
    if (u < 0.0 || u > 1.0) return 0.0;
    float w = width * sin(PI * u) * sin(PI * u);
    float reveal = 1.0 - smoothstep(prog - 0.05, prog, u);
    return (1.0 - smoothstep(w * 0.4, w, abs(length(d) - R))) * reveal;
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    // Night sky, a little lighter round the moon.
    float3 col = mix(BG * 0.7, BG + A * 0.08, smoothstep(0.0, 1.0, uv.y));
    col += S * 0.5 * dots(uv, 60.0, float2(t * 0.01, 0.0), 0.12, 0.08, 4.0);

    // The moon: big, pale, with soft mottling and a wide glow.
    float2 mc = float2(asp * 0.62, 0.38);
    float md = length(uv - mc);
    float3 moonCol = mix(S, float3(1.0), 0.65);
    col += moonCol * exp(-md * 3.0) * 0.28;
    float disc = 1.0 - smoothstep(0.235, 0.24, md);
    float mott = fbm3((uv - mc) * 7.0 + 2.0);
    col = mix(col, moonCol * (0.86 + 0.14 * smoothstep(0.35, 0.7, mott)), disc);

    // Thin clouds sliding across, dark with lit edges near the moon.
    float cl = fbm(float2(uv.x * 2.2 - t * 0.02, uv.y * 9.0));
    float band = smoothstep(0.5, 0.62, cl) * (1.0 - smoothstep(0.15, 0.55, abs(uv.y - 0.42)));
    float nearMoon = exp(-md * 3.5);
    col = mix(col, BG * 0.6 + moonCol * 0.25 * nearMoon, band * 0.75);
    col += moonCol * (smoothstep(0.5, 0.53, cl) - smoothstep(0.53, 0.58, cl)) * nearMoon * 0.35 * (1.0 - smoothstep(0.15, 0.55, abs(uv.y - 0.42)));

    // Grass: a swaying silhouette of blades along the bottom.
    float wind = sin(t * 0.8 + uv.x * 3.0) * 0.6;
    float blades = pow(abs(fract(uv.x * 70.0 + wind * (1.0 - uv.y) * 2.0) - 0.5) * 2.0, 3.0);
    float gl = 0.85 + 0.04 * vnoise(float2(uv.x * 30.0 + wind, 0.0)) + 0.035 * blades;
    float grass = step(gl, uv.y);
    col = mix(col, BG * 0.35, grass);
    col += moonCol * exp(-abs(uv.y - gl) * 300.0) * 0.12 * (1.0 - grass);

    // Petals on the wind.
    float4 p = fallingLayer(uv, 8.0, float2(-0.6, 0.35), 0.5, 4.0, 1.0, 0.03, A, S);
    col = mix(col, p.rgb * 0.75, p.a * 0.45);
    p = fallingLayer(uv, 4.5, float2(-0.45, 0.3), 0.45, 9.0, 1.0, 0.012, A, mix(S, float3(1.0), 0.4));
    col = mix(col, p.rgb, p.a * 0.85);

    // The slash: every 5 s, a new angle and place.
    float cyc = fract(t / 5.0);
    float epoch = floor(t / 5.0);
    if (cyc < 0.3) {
        float tilt = (hash11(epoch) - 0.5) * 1.1;
        float2 cc = float2(asp * 0.5, 0.5);
        float2 q = rot(tilt) * (uv - cc) + cc;
        float2 sc2 = cc + float2((hash11(epoch + 2.0) - 0.5) * 0.4, 1.0);
        float R = 1.0;
        float prog = sat(cyc / 0.06);
        float fade = 1.0 - smoothstep(0.06, 0.3, cyc);
        float main1 = slashStroke(q, sc2, R, -2.45, -0.7, prog, 0.035);
        float after1 = slashStroke(q, sc2 + float2(0.0, 0.03), R, -2.4, -0.75, prog, 0.02);
        col += float3(1.0) * main1 * fade;
        col += mix(A, S, 0.5) * slashStroke(q, sc2, R, -2.45, -0.7, prog, 0.09) * fade * 0.5;
        col += mix(A, float3(1.0), 0.3) * after1 * fade * 0.5;
        // Speed lines along the slash.
        float row = floor(q.y * 50.0);
        float hr = hash11(row + epoch * 7.0);
        float xs = fract(q.x * 0.6 + hr * 5.0 + cyc * 9.0);
        col += float3(1.0) * step(0.8, hr) * step(0.7, xs) * (1.0 - step(0.9, xs)) * fade * 0.18;
        col += float3(1.0) * exp(-cyc * 35.0) * 0.18;
    }

    return half4(finish(col, fc), 1.0);
}
