        float rim = 1.0 - smoothstep(0.0, 0.004, R0 - r);
        col = mix(disc, mix(A, float3(1.0), 0.4), rim * 0.8);
    }

    return half4(finish(col, fc), 1.0);
}
"""

    private const val BEAT_TUNNEL = """
// Beat tunnel: rushing through a neon tunnel in the cover's colours. It lurches forward on every
// kick, its walls glow brighter where the spectrum is strong (bass along the floor and ceiling,
// highs at the sides), rings of light sweep past on the beat and sparks stream by. The vanishing
// point sits where the equalizer is set (uWaveY).
// Shared by the music-reactive scenes (besides "Now playing", which has its own copy): the same
// uniforms NowPlayingScene feeds the music scene - cover, levels, kicks, eight equalizer bands and
// where on screen the visualizer goes - plus the soft cover background.
uniform shader uArt;      // the cover, square and blurred smooth (MusicTheme.softArt)
uniform float2 uArtSize;  // its size in pixels
uniform float uHasArt;    // 0 = no cover yet (or the cover is switched off)
uniform float uBass;      // 0..1, smoothed
uniform float uMid;
uniform float uHigh;
uniform float uBeatAge;   // seconds since the last kick (large = none)
uniform float uPlaying;   // 0..1, fades when paused
uniform float uIntensity; // 0..1, Settings > strength
uniform float4 uEqA;      // bands 0-3 (low), 0..1
uniform float4 uEqB;      // bands 4-7 (high)
uniform float uWaveY;     // 0..1 from the top: where the visualizer sits (Appearance > Equalizer)
uniform float uWaveH;     // room above / below that line (share of the height); the player sits under it
uniform float uWaveX;     // 0..1 from the left: where the visualizer sits across (0 = the middle; the player beside it)
uniform shader uCover;    // the cover, sharp (256 px square) - for the record / disc labels
uniform float2 uCoverSize;
uniform shader uLabel;    // the song's title and artist in dark ink on a clear picture (NowPlayingScene.songLabel)
uniform float2 uLabelSize;
uniform shader uHistory;  // covers of the last songs: a 4 x 2 grid (newest first), MusicTheme.historyAtlas
uniform float uHistCount; // how many of the 8 are filled
uniform float3 uSubject;   // where the cover's subject is: x, y (0..1 across the square) and its size; z = 0 until known (MusicTheme.subject)
// Clocks that only run while the music plays, so spins and scrolls slow down and stop smoothly instead of
// jumping (t * (a + b * level) jumps whenever the level moves). Kept by NowPlayingScene, in seconds:
uniform float uPlayT;     // time spent playing (integral of uPlaying)
uniform float uBassT;     // integral of uBass x uPlaying
uniform float uMidT;      // integral of uMid x uPlaying
uniform float uHighT;     // integral of uHigh x uPlaying

// The visualizer's room, with a sensible size when it isn't set (previews).
float room(float fallback) { return uWaveH > 0.001 ? uWaveH : fallback; }
// Across: the middle, or the left part when the player sits beside the visualizer (MusicPlayerLayout.SIDE).
float waveX(float asp) { return uWaveX > 0.001 ? uWaveX * asp : asp * 0.5; }

float2 mirrorUv(float2 q) { return 1.0 - abs(1.0 - mod(q, 2.0)); }

float eqBand(float i) {
    if (i < 0.5) return uEqA.x;
    if (i < 1.5) return uEqA.y;
    if (i < 2.5) return uEqA.z;
    if (i < 3.5) return uEqA.w;
    if (i < 4.5) return uEqB.x;
    if (i < 5.5) return uEqB.y;
    if (i < 6.5) return uEqB.z;
    return uEqB.w;
}

// The spectrum at m (0 = lowest band, 1 = highest), smoothly interpolated.
float eqAt(float m) {
    float f = clamp(m, 0.0, 1.0) * 7.0;
    float i = floor(f);
    float u = f - i;
    u = u * u * (3.0 - 2.0 * u);
    return mix(eqBand(i), eqBand(min(i + 1.0, 7.0)), u);
}

// Pushes a colour's saturation by s (1 = unchanged) around its own brightness.
float3 vivid(float3 c, float s) {
    float l = dot(c, float3(0.299, 0.587, 0.114));
    return max(mix(float3(l), c, s), 0.0);
}

// The cover, very soft and slowly drifting (or, without one, the palette swirling), dimmed by dim.
float3 coverField(float2 uv, float asp, float t, float bass, float dim, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float zoom = 1.7 + 0.08 * sin(t * 0.045) - 0.05 * bass * uIntensity;
    p = rot(0.05 * sin(t * 0.031)) * p / zoom;
    p += (float2(vnoise(p * 2.0 + float2(t * 0.1, 0.0)), vnoise(p * 2.0 + float2(7.3, -t * 0.08))) - 0.5) * 0.1;
    float2 q = p / max(asp, 1.0) + 0.5;
    float3 art = float3(uArt.eval(mirrorUv(q) * uArtSize).rgb);
    float sw = fbm3(uv * 1.4 + float2(t * 0.03, -t * 0.02));
    float3 noArt = mix(BG * 1.4 + A * 0.08, mix(A, S, sw) * 0.5, smoothstep(0.25, 0.8, sw));
    float3 col = mix(noArt, vivid(art, 1.35) * 0.62, uHasArt);
    return mix(col, BG, 0.14) * dim;
}

// The palette as a living gradient: A and S (the cover's colours) flowing round each other with a
// third, hue-shifted colour, brighter on the beat. A colourful base instead of a near-black one.
float3 paletteField(float2 uv, float asp, float t, float lift, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float n1 = fbm3(p * 1.3 + float2(t * 0.05, -t * 0.04));
    float n2 = fbm3(p * 1.7 + float2(-t * 0.035, t * 0.05) + 4.7);
    float3 C = float3(S.z, A.x, (A.y + S.y) * 0.5); // a third colour from the two
    float3 col = mix(A, S, smoothstep(0.25, 0.75, n1));
    col = mix(col, C, smoothstep(0.45, 0.85, n2) * 0.55);
    col = mix(BG, col, 0.42 + 0.18 * lift);
    return col;
}

// The sharp cover at q (0..1 across the square), or the palette when there's no cover yet.
float3 sharpCover(float2 q, float3 A, float3 S) {
    float3 art = float3(uCover.eval(clamp(q, 0.0, 1.0) * uCoverSize).rgb);
    return mix(mix(A, S, q.y), art, uHasArt);
}

// Where the cover's subject sits (x, y, size), with a sensible guess before it's known.
float3 subjectOf() { return uSubject.z > 0.001 ? uSubject : float3(0.5, 0.45, 0.3); }

// Ink of the song label at q (0..1 across the writing area): 0 = paper, 1 = ink.
float labelInk(float2 q) {
    if (q.x < 0.0 || q.x > 1.0 || q.y < 0.0 || q.y > 1.0) return 0.0;
    return float(uLabel.eval(q * uLabelSize).a);
}

// Cover of an earlier song: i = 0 the one before this, 1 the one before that... (wraps round the
// ones there are; with none yet, the current cover in the song's colours instead).
float3 pastCover(float i, float2 q, float3 A, float3 S) {
    q = clamp(q, 0.0, 1.0);
    if (uHistCount < 0.5) return mix(sharpCover(q, A, S), mix(A, S, q.y), 0.35);
    float n = mod(floor(i), uHistCount);
    float2 tile = float2(mod(n, 4.0), floor(n / 4.0));
    float2 p = (tile + 0.01 + q * 0.98) * 192.0;
    return float3(uHistory.eval(p).rgb);
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float k = uIntensity;
    float play = uPlaying;
    float bass = uBass * play;
    float kick = exp(-uBeatAge * 5.0) * play;

    float2 c = float2(asp * 0.5, clamp(uWaveY, 0.2, 0.8));
    float2 d = uv - c;
    d *= 1.0 + 0.04 * kick * k;
    float r = max(length(d * float2(0.8, 1.0)), 0.001);
    float a = atan(d.y, d.x) / TAU + 0.5;
    float z = 0.22 / r + 0.9 * t + 0.5 * uPlayT + kick * 0.25;
    float fog = smoothstep(0.02, 0.35, r);

    float3 col = coverField(uv, asp, t, bass, 0.35, BG, A, S) * (1.0 - fog * 0.5);

    // Walls: a grid of glowing lines.
    float gx = abs(fract(a * 18.0) - 0.5);
    float gz = abs(fract(z * 1.2) - 0.5);
    float m = abs(abs(a - 0.5) * 2.0 - 0.5) * 2.0;
    float e = eqAt(1.0 - m) * play;
    float3 wc = mix(A, S, 0.5 + 0.5 * sin(z * 0.5));
    float lines = exp(-gx * 30.0) * 0.8 + exp(-gz * 28.0);
    col += wc * lines * fog * (0.45 + 0.8 * e * (0.5 + 0.5 * k));
    // Panels between the lines, faintly lit by the spectrum.
    col += wc * fog * e * 0.06;

    // A ring of light passing on each beat.
    col += mix(A, float3(1.0), 0.5) * exp(-gz * 70.0) * kick * fog * k;

    // Sparks streaming past.
    float2 sp = float2(a * 60.0, z * 3.0);
    float2 sid = floor(sp);
    float2 sf = fract(sp) - 0.5;
    float2 sh = hash22(sid + 5.0);
    float spark = step(sh.x, 0.08) * (1.0 - smoothstep(0.08, 0.2, length(sf * float2(1.0, 0.3))));
    col += mix(S, float3(1.0), 0.6) * spark * fog * (0.3 + 0.6 * uHigh * play);

    // Light at the far end, pulsing with the bass.
    col += mix(A, S, 0.3) * exp(-r * 9.0) * (0.25 + 0.7 * bass * k);

    return half4(finish(col, fc), 1.0);
}
"""

    private const val CIRCUIT = """
// Circuit: a dark circuit board seen from above. Traces run between pads on a grid, pulses of light
// race along them (rows one way, columns the other), chips sit in the gaps with status LEDs
// blinking, and now and then a wave of power sweeps across the whole board.

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    float3 col = BG * 0.75 + mix(A, S, 0.5) * 0.025;
    // Faint solder-mask texture.
    col += BG * 0.15 * (vnoise(uv * 60.0) - 0.5);

    float scale = 13.0;
    float2 p = uv * scale;
    float2 id = floor(p);
    float2 f = fract(p) - 0.5;

    // Connections from this cell to its neighbours (shared hashes so both sides agree).
    float r = step(0.42, hash12(id + 1.3));
    float l = step(0.42, hash12(id - float2(1.0, 0.0) + 1.3));
    float dn = step(0.5, hash12(id + 5.7));
    float up = step(0.5, hash12(id - float2(0.0, 1.0) + 5.7));
    float dH = 1e3;
    float dV = 1e3;
    if (r > 0.5) dH = min(dH, sdSegment(f, float2(0.0), float2(0.5, 0.0)));
    if (l > 0.5) dH = min(dH, sdSegment(f, float2(0.0), float2(-0.5, 0.0)));
    if (dn > 0.5) dV = min(dV, sdSegment(f, float2(0.0), float2(0.0, 0.5)));
    if (up > 0.5) dV = min(dV, sdSegment(f, float2(0.0), float2(0.0, -0.5)));
    float links = r + l + dn + up;
    float d = min(dH, dV);
    float trace = 1.0 - smoothstep(0.035, 0.06, d);
    float3 copper = mix(A, S, 0.35) * 0.35;
    col = mix(col, copper, trace * 0.8);

    // Pads where traces meet or end.
    float pd = length(f);
    float pad = (1.0 - smoothstep(0.1, 0.13, pd)) * step(0.5, links) * (step(links, 1.5) + step(2.5, links));
    col = mix(col, mix(copper, S, 0.4), pad);
    col = mix(col, BG * 0.4, (1.0 - smoothstep(0.04, 0.06, pd)) * pad);

    // Pulses: along each row to the right, along each column downwards.
    float rowPh = fract((uv.x * scale) * 0.08 - t * 0.35 + hash11(id.y * 3.1));
    float colPh = fract((uv.y * scale) * 0.08 - t * 0.28 + hash11(id.x * 7.7));
    float hHead = exp(-rowPh * 30.0) + 0.0 * rowPh;
    float vHead = exp(-colPh * 30.0);
    float onH = 1.0 - smoothstep(0.03, 0.08, dH);
    float onV = 1.0 - smoothstep(0.03, 0.08, dV);
    col += S * (onH * hHead + onV * vHead) * 1.2;
    col += S * (exp(-dH * 30.0) * hHead + exp(-dV * 30.0) * vHead) * 0.25;

    // Chips: dark blocks with pins, in some cells, each with a blinking LED.
    float2 cid = floor(uv * scale / float2(3.0, 2.0));
    float ch = hash12(cid + 17.0);
    if (ch > 0.86) {
        float2 cf = fract(uv * scale / float2(3.0, 2.0)) - 0.5;
        float body = sdRoundBox(cf * float2(3.0, 2.0), float2(0.9, 0.5), 0.08);
        float pinsX = step(0.5, fract(cf.x * 3.0 * 3.0)) * step(abs(cf.y * 2.0), 0.72) * step(0.5, abs(cf.y * 2.0));
        col = mix(col, copper * 1.4, pinsX * step(abs(cf.x * 3.0), 0.8));
        col = mix(col, BG * 0.3 + float3(0.03), 1.0 - smoothstep(0.0, 0.02, body));
        float2 ledP = cf * float2(3.0, 2.0) - float2(0.7, -0.3);
        float blink = step(0.5, fract(t * (0.6 + ch * 2.0) + ch * 9.0));
        col += mix(A, S, step(0.93, ch)) * (1.0 - smoothstep(0.03, 0.06, length(ledP))) * (0.3 + 0.9 * blink);
        // A faint marking line on the chip.
        col += float3(0.08) * (1.0 - smoothstep(0.0, 0.02, abs(cf.y * 2.0))) * step(abs(cf.x * 3.0), 0.5) * (1.0 - step(0.0, body));
    }

    // Power wave sweeping across every 9 s.
    float wave = fract(t / 9.0) * (asp + 1.0) - 0.5;
    float band = exp(-abs(uv.x + uv.y * 0.3 - wave) * 14.0);
    col += A * trace * band * 0.5 + A * band * 0.03;

    return half4(finish(col, fc), 1.0);
}
"""

    private const val GEARWORKS = """
// Gearworks: inside a brass machine, lit by a warm lamp. Heavy bevelled gears of brass, steel and
// copper mesh and turn (each at the speed its teeth demand), catching the light on their edges and
// brushed faces and throwing soft shadows on the riveted plate behind; a big flywheel turns out of
// focus at the back. Pipes run across, a pressure gauge's needle trembles, pistons pump, steam puffs
// from a vent and sparks fly where the teeth bite.

// A gear: radius R, n teeth, turned by a (tooth phase); spoke holes and a hub. Negative inside.
float gearD(float2 p, float R, float n, float a) {
    float r = length(p);
    float ang = atan(p.y, p.x);
    float tooth = sat(cos(ang * n + a) * 2.4 + 0.3);
    float d = r - (R + R * 0.13 * tooth);
    // Five spoke holes, turning with the gear.
    float sector = TAU / 5.0;
    float la = mod(ang + a / n, sector) - sector * 0.5;
    float2 q = r * float2(cos(la), sin(la));
    float hole = length(q - float2(R * 0.56, 0.0)) - R * 0.2;
    d = max(d, -hole);
    // Axle hole.
    d = max(d, -(r - R * 0.09));
    return d;
}

// Shades one gear over col: bevelled metal lit by the lamp (top left) and an accent rim light.
float3 gear(float3 col, float2 p, float R, float n, float a, float3 metal, float3 rim, float blur, float px) {
    if (length(p) > R * 1.3 + 0.02) return col;
    float e = 0.0015;
    float d = gearD(p, R, n, a);
    float dx = gearD(p + float2(e, 0.0), R, n, a) - d;
    float dy = gearD(p + float2(0.0, e), R, n, a) - d;
    float2 g = float2(dx, dy) / e;
    float bevel = R * 0.07;
    float edge = sat(1.0 + d / bevel);                  // 1 at the outline, 0 on the flat face
    float3 nrm = normalize(float3(g * edge * 1.6, 1.0));
    nrm.y = -nrm.y;
    // Raised hub ring.
    float r = length(p);
    float hub = smoothstep(R * 0.24, R * 0.22, r) * smoothstep(R * 0.09, R * 0.12, r);
    float3 L = normalize(float3(-0.55, 0.6, 0.6));
    float3 V = float3(0.0, 0.0, 1.0);
    float dif = sat(dot(nrm, L));
    float spec = pow(sat(dot(nrm, normalize(L + V))), 40.0);
    // Brushed face: fine rings round the axle.
    float brush = 0.85 + 0.15 * vnoise(float2(r * 500.0, atan(p.y, p.x) * 2.0));
    float aniso = pow(sat(1.0 - abs(dot(normalize(float2(p.y, -p.x) + 1e-4), normalize(float2(-0.55, -0.6))))), 6.0);
    float3 c = metal * (0.25 + 0.85 * dif) * brush;
    c += mix(float3(1.0, 0.9, 0.75), metal, 0.3) * (spec * 0.9 + aniso * 0.25 * (1.0 - edge));
    c += rim * pow(sat(dot(nrm, normalize(float3(0.8, -0.3, 0.4)))), 3.0) * 0.5;
    c *= 1.0 + hub * 0.25;
    // Teeth biting into each other get darker in the gaps.
    float cover = smoothstep(px * blur, -px * blur, d);
    return mix(col, c, cover);
}

// Soft shadow of a gear on the plate behind it.
float gearShadow(float2 p, float R, float n, float a) {
    if (length(p) > R * 1.5) return 0.0;
    return smoothstep(0.03, -0.02, gearD(p, R, n, a)) * 0.6;
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float px = 1.5 / uRes.y;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    float3 brass = mix(float3(0.78, 0.58, 0.28), A, 0.25);
    float3 steel = mix(float3(0.55, 0.58, 0.62), S, 0.25);
    float3 copper = float3(0.72, 0.38, 0.22);

    // The lamp: a warm pool from the top left.
    float2 lampP = float2(asp * 0.18, -0.1);
    float lamp = exp(-length(uv - lampP) * 1.3);

    // The riveted plate, grimy, with seams.
    float3 col = BG * 0.8 + brass * 0.05;
    float2 pp = uv * float2(3.0, 2.5);
    float2 seam = abs(fract(pp) - 0.5);
    col *= 0.85 + 0.25 * fbm3(uv * 6.0);
    col *= 1.0 - 0.35 * smoothstep(0.485, 0.5, max(seam.x, seam.y));
    float2 rv = fract(pp * float2(4.0, 4.0)) - 0.5;
    float rivet = smoothstep(0.12, 0.08, length(rv)) * step(0.4, max(seam.x, seam.y));
    col += brass * rivet * 0.25 * (0.5 + 0.5 * sat(-rv.x - rv.y + 0.1));
    col *= 0.45 + 1.1 * lamp;

    float spin = t * 0.55;
    float2 g1 = float2(asp * 0.52, 0.47);
    float2 g2 = g1 + float2(0.262, -0.07);
    float2 g3 = g1 + float2(-0.07, 0.315);
    float2 g4 = g2 + float2(0.16, 0.17);
    float2 fw = float2(asp * 0.2, 0.36);

    // Shadows of the near gears on the plate (cast down and right, away from the lamp).
    float2 so = float2(0.025, 0.03);
    float sh = gearShadow(uv - g1 - so, 0.17, 16.0, spin);
    sh = max(sh, gearShadow(uv - g2 - so, 0.085, 8.0, -spin * 2.0 + 0.4));
    sh = max(sh, gearShadow(uv - g3 - so, 0.12, 12.0, -spin * 16.0 / 12.0 + 0.2));
    sh = max(sh, gearShadow(uv - g4 - so, 0.11, 11.0, spin * 16.0 / 11.0));
    col *= 1.0 - sh * 0.75;

    // Pipes across the back: round, lit along the top.
    for (int i = 0; i < 2; i++) {
        float fi = float(i);
        float y = 0.16 + fi * 0.62;
        float rr = 0.022 + fi * 0.008;
        float dy = (uv.y - y) / rr;
        if (abs(dy) < 1.0) {
            float3 pc = mix(copper, steel, fi) * (0.25 + 0.9 * sat(1.0 - abs(dy + 0.45) * 1.2)) * (0.5 + lamp);
            pc += float3(1.0, 0.9, 0.7) * exp(-abs(dy + 0.55) * 14.0) * 0.4 * (0.4 + lamp);
            float flange = step(abs(fract(uv.x * 2.2 + fi * 0.3) - 0.5), 0.02);
            pc *= 1.0 + flange * 0.4;
            col = mix(col, pc, smoothstep(1.0, 0.85, abs(dy)));
        }
    }

    // The flywheel at the back, out of focus.
    col = gear(col, uv - fw, 0.30, 26.0, t * 0.22, steel * 0.45, A * 0.2, 9.0, px);

    // The gear train: speeds in proportion to tooth counts so the teeth mesh.
    col = gear(col, uv - g1, 0.17, 16.0, spin, brass, A, 1.0, px);
    col = gear(col, uv - g2, 0.085, 8.0, -spin * 2.0 + 0.4, steel, A, 1.0, px);
    col = gear(col, uv - g3, 0.12, 12.0, -spin * 16.0 / 12.0 + 0.2, copper, A, 1.0, px);
    col = gear(col, uv - g4, 0.11, 11.0, spin * 16.0 / 11.0, brass * 0.92, A, 1.0, px);

    // Pressure gauge: a brass rim, a cream face, a trembling needle.
    float2 gc = float2(asp * 0.12, 0.62);
    float2 gq = uv - gc;
    float gr = length(gq);
    if (gr < 0.075) {
        float3 face = float3(0.85, 0.8, 0.68) * (0.55 + 0.6 * lamp);
        float ang = atan(gq.y, gq.x);
        face *= 1.0 - 0.6 * step(0.052, gr) * step(gr, 0.056) * step(0.6, fract(ang / TAU * 30.0)) * step(gq.y, 0.01);
        float na = PI * 0.75 + (0.55 + 0.25 * sin(t * 0.5) + 0.03 * sin(t * 17.0)) * PI * 1.5;
        float2 nd = float2(cos(na), sin(na));
        float needle = sdSegment(gq, float2(0.0), nd * 0.05) - 0.0025;
        face = mix(face, float3(0.6, 0.05, 0.03), smoothstep(px, -px, needle));
        float3 rimC = brass * (0.4 + 0.9 * sat(-gq.x - gq.y + 0.04) * 6.0) * (0.5 + lamp);
        float3 gcol = mix(face, rimC, smoothstep(0.058, 0.062, gr));
        gcol = mix(gcol, BG * 0.3, smoothstep(0.012, 0.009, gr));
        gcol += float3(1.0) * 0.12 * smoothstep(0.06, 0.0, length(gq - float2(-0.02, -0.025)));
        col = mix(col, gcol, smoothstep(0.075, 0.072, gr));
    }

    // Pistons on the right, pumping in turn.
    for (int k = 0; k < 3; k++) {
        float fk = float(k);
        float x = asp * 0.88 + fk * 0.055 - 0.055;
        float stroke = 0.5 + 0.5 * sin(t * 2.4 + fk * 2.1);
        float top = 0.42 + stroke * 0.12;
        float rodD = abs(uv.x - x) / 0.009;
        if (rodD < 1.0 && uv.y > top && uv.y < 0.86) {
            float3 rc = steel * (0.3 + 0.9 * sat(1.0 - abs(rodD + 0.4))) + float3(1.0) * exp(-abs(rodD + 0.5) * 8.0) * 0.4;
            col = mix(col, rc, smoothstep(1.0, 0.8, rodD));
        }
        float hd = sdRoundBox(uv - float2(x, top), float2(0.022, 0.024), 0.005);
        if (hd < px) {
            float2 hq = (uv - float2(x, top)) / float2(0.022, 0.024);
            float3 hc = brass * (0.3 + 0.8 * sat(-hq.x * 0.5 - hq.y * 0.5 + 0.5)) * (0.6 + lamp);
            hc += float3(1.0, 0.9, 0.7) * exp(-abs(hq.y + 0.8) * 6.0) * 0.2;
            col = mix(col, hc, smoothstep(px, -px, hd));
        }
        col += A * exp(-abs(uv.y - top) * 60.0) * step(abs(uv.x - x), 0.028) * 0.08;
    }

    // Steam: a puff every 6 s from a vent at the lower left, rising and spreading.
    float sc = fract(t / 6.0);
    float2 vent = float2(asp * 0.1, 0.9);
    float2 q = (uv - vent) / (0.06 + sc * 0.35);
    float steam = smoothstep(0.45, 0.75, fbm3(uv * 5.0 + float2(0.0, t * 0.5))) * exp(-length(q + float2(0.0, 0.8)) * 1.6) * (1.0 - sc);
    col = mix(col, float3(0.8, 0.78, 0.74) * (0.6 + 0.6 * lamp), steam * 0.55);

    // Sparks where the big gears bite.
    float2 mesh = g1 + normalize(g2 - g1) * 0.19;
    float sp = dots((uv - mesh) * float2(1.0, 0.6) + float2(0.0, t * 0.4), 40.0, float2(t * 2.0, 0.0), 0.12, 0.12, 5.0);
    col += mix(A, float3(1.0), 0.5) * sp * exp(-length(uv - mesh) * 14.0) * 1.6;
    // Dust hanging in the lamp light.
    col += float3(1.0, 0.85, 0.6) * dots(uv + float2(t * 0.004, t * 0.002), 30.0, float2(0.0), 0.2, 0.05, 8.0) * lamp * 0.3;

    return half4(finish(col, fc), 1.0);
}
