    private const val FROST = """
// Frost: an ice-type night. Six-armed snowflakes tumble down in two layers, frost creeps in
// crystal facets from the corners and slowly breathes, an aurora ripples across the top and ice
// glints sparkle here and there.

// A snowflake (six arms with side branches), radius about s. Negative inside-ish (a distance).
float flakeD(float2 p, float s) {
    float r = length(p);
    float a = atan(p.y, p.x);
    a = mod(a + PI / 6.0, PI / 3.0) - PI / 6.0;
    float2 q = float2(cos(a), abs(sin(a))) * r;
    float d = sdSegment(q, float2(0.0), float2(s, 0.0));
    d = min(d, sdSegment(q, float2(s * 0.45, 0.0), float2(s * 0.68, s * 0.2)));
    d = min(d, sdSegment(q, float2(s * 0.7, 0.0), float2(s * 0.85, s * 0.12)));
    return d;
}

float4 flakeLayer(float2 uv, float scale, float speed, float seed, float t) {
    float2 p = uv * scale + float2(sin(t * 0.3 + uv.y * 3.0 + seed) * 0.4, -t * speed);
    float2 id = floor(p);
    float2 f = fract(p) - 0.5;
    float2 r = hash22(id + seed);
    if (r.x > 0.45) return float4(0.0);
    float2 q = rot(t * (0.3 + r.y) + r.x * 20.0) * (f - (r - 0.5) * 0.4);
    float s = 0.18 + 0.12 * r.y;
    float d = flakeD(q, s);
    float a = 1.0 - smoothstep(0.012, 0.03, d);
    return float4(float3(1.0), a * (0.6 + 0.4 * r.y));
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    float3 col = mix(BG * 0.8, mix(BG, A, 0.25), uv.y);

    // Aurora ripples along the top.
    float ax = uv.x * 1.5 + sin(uv.x * 2.0 + t * 0.2) * 0.4;
    float curtain = exp(-abs(uv.y - (0.22 + 0.06 * sin(ax * 2.0 + t * 0.3))) * 14.0);
    float rays = 0.5 + 0.5 * sin(ax * 30.0 + fbm3(float2(ax * 3.0, t * 0.2)) * 6.0);
    col += mix(A, S, 0.5 + 0.5 * sin(ax + t * 0.1)) * curtain * rays * 0.3;

    // Distant snowy hills.
    float hill = 0.82 - 0.06 * fbm3(float2(uv.x * 1.5, 1.0));
    col = mix(col, mix(BG, float3(0.85), 0.25), step(hill, uv.y));
    col += float3(1.0) * exp(-abs(uv.y - hill) * 200.0) * 0.12;

    // Snowflakes, far then near.
    float4 fl = flakeLayer(uv, 14.0, 0.6, 3.0, t);
    col = mix(col, mix(col, float3(0.9, 0.95, 1.0), 0.6), fl.a * 0.5);
    fl = flakeLayer(uv, 6.0, 0.35, 11.0, t);
    col = mix(col, mix(S, float3(1.0), 0.7), fl.a * 0.9);

    // Frost creeping from the corners: faceted (voronoi-ish cells), breathing slowly.
    float2 c = uv * 9.0;
    float2 ci = floor(c);
    float2 cf = fract(c);
    float best = 9.0;
    float second = 9.0;
    for (int j = -1; j <= 1; j++) {
        for (int i = -1; i <= 1; i++) {
            float2 g = float2(float(i), float(j));
            float2 o = hash22(ci + g);
            float dd = length(g + o - cf);
            if (dd < best) { second = best; best = dd; } else if (dd < second) { second = dd; }
        }
    }
    float facet = second - best;
    // Distance to the nearest screen corner: the frost only grows in from the corners.
    float2 cuv = float2(min(uv.x, asp - uv.x), min(uv.y, 1.0 - uv.y));
    float corner = length(cuv);
    float reach = 0.3 + 0.04 * sin(t * 0.25);
    float frost = 1.0 - smoothstep(reach - 0.08, reach, corner + 0.08 * fbm3(uv * 6.0));
    col = mix(col, mix(float3(0.85, 0.93, 1.0), S, 0.2) * (0.7 + 0.3 * smoothstep(0.0, 0.2, facet)), frost * 0.55);
    col += float3(1.0) * (1.0 - smoothstep(0.0, 0.03, facet)) * frost * 0.35;

    // Glints.
    col += float3(1.0) * dots(uv, 40.0, float2(0.0), 0.06, 0.06, 7.0) * (0.3 + 0.7 * frost);

    return half4(finish(col, fc), 1.0);
}
"""

    private const val TERRA = """
// Terra: a ground-type desert. Dunes roll away in layers under a hazy sun, a sandstorm sweeps
// across in streaks and gusts, pebbles bounce along, heat shimmer bends the horizon and glowing
// cracks pulse in the hard ground at the front.

float duneH(float x, float base, float amp, float seed) {
    return base - amp * (0.6 * (0.5 + 0.5 * sin(x * 2.2 + seed)) + 0.4 * fbm3(float2(x * 1.6 + seed, seed)));
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    // Gusts: the storm swells every few seconds.
    float gust = 0.5 + 0.5 * sin(t * 0.5) * sin(t * 0.21 + 1.0);

    // Sky: dusty, warmer near the horizon; a soft sun.
    float3 col = mix(BG * 0.9, mix(A, S, 0.5) * 0.6, pow(sat(uv.y / 0.7), 1.6));
    float sd = length(uv - float2(asp * 0.3, 0.3));
    col += mix(S, float3(1.0), 0.4) * exp(-sd * 6.0) * 0.5;
    col = mix(col, mix(S, float3(1.0), 0.6), (1.0 - smoothstep(0.06, 0.065, sd)) * (0.7 - 0.4 * gust));

    // Heat shimmer near the horizon.
    float2 hu = uv + float2(0.0, (vnoise(float2(uv.x * 20.0, t * 2.0)) - 0.5) * 0.006 * smoothstep(0.45, 0.6, uv.y));

    // Dune layers, far to near, each darker and slowly drifting.
    for (int k = 0; k < 3; k++) {
        float fk = float(k);
        float x = hu.x * (1.0 + fk * 0.5) + t * 0.006 * (fk + 1.0) + fk * 5.0;
        float h = duneH(x, 0.6 + fk * 0.13, 0.09 + fk * 0.04, fk * 3.0);
        float inD = smoothstep(h - 0.0015, h + 0.0015, hu.y);
        float lit = 0.5 + 0.5 * sin(x * 2.2 + fk * 3.0 + 1.2);
        float3 sand = mix(A * 0.55, mix(A, S, 0.6) * 0.85, lit) * (1.0 - fk * 0.18);
        col = mix(col, sand, inD);
        // Ripples on the near dunes.
        // Soft wind ripples on the near dunes (a smooth sine, no hard steps).
        col *= 1.0 - inD * 0.04 * (0.5 + 0.5 * sin((hu.y - h) * 700.0 + hu.x * 60.0 + sin(hu.x * 9.0) * 2.0)) * step(0.5, fk);
        // Wind lifting sand off the crests.
        col += mix(S, float3(1.0), 0.3) * exp(-abs(hu.y - h + 0.01) * 120.0) * 0.12 * gust * (1.0 - inD);
    }

    // Cracked hard ground at the front with glowing seams.
    float groundY = 0.9;
    if (uv.y > groundY) {
        float2 c = float2(uv.x * 6.0, (uv.y - groundY) * 30.0);
        float2 ci = floor(c);
        float2 cf = fract(c);
        float best = 9.0;
        float second = 9.0;
        for (int j = -1; j <= 1; j++) {
            for (int i = -1; i <= 1; i++) {
                float2 g = float2(float(i), float(j));
                float dd = length(g + hash22(ci + g) - cf);
                if (dd < best) { second = best; best = dd; } else if (dd < second) { second = dd; }
            }
        }
        float seam = 1.0 - smoothstep(0.02, 0.12, second - best);
        col = mix(col, A * 0.35, 0.7);
        col += mix(A, S, 0.5) * seam * (0.35 + 0.35 * sin(t * 1.5 + ci.x));
    }

    // Pebbles hopping along the ground.
    for (int k = 0; k < 4; k++) {
        float fk = float(k);
        float x = fract(t * (0.05 + 0.03 * hash11(fk)) + hash11(fk + 4.0)) * (asp + 0.2) - 0.1;
        float hop = abs(sin(t * (2.0 + fk) + fk)) * 0.04 * gust;
        float2 pp = float2(x, groundY - 0.01 - hop);
        float pd = length((uv - pp) * float2(1.0, 1.3)) - 0.008 - 0.004 * hash11(fk + 9.0);
        col = mix(col, A * 0.3, 1.0 - smoothstep(0.0, 0.002, pd));
    }

    // Sandstorm: soft, wavy veils of sand blown across (warped noise stretched sideways, no hard lines).
    float2 wp = float2(uv.x * 1.2 - t * (0.25 + 0.5 * gust), uv.y * 7.0 + sin(uv.x * 2.5 + t * 0.4) * 0.8);
    float veil = fbm3(wp + float2(fbm3(wp * 0.7 + t * 0.1), 0.0) * 0.8);
    float streak = smoothstep(0.5, 0.85, veil) * smoothstep(0.25, 0.7, uv.y);
    col = mix(col, mix(A, S, 0.6) * 0.9, streak * (0.1 + 0.25 * gust));
    // Dust haze.
    col = mix(col, mix(A, S, 0.5) * 0.6, fbm3(float2(uv.x * 2.0 - t * 0.3, uv.y * 3.0)) * 0.25 * gust);

    return half4(finish(col, fc), 1.0);
}
"""

    private const val VENOM = """
// Venom: a poison-type swamp at night. Glowing ooze hangs from the top and drips — each drip
// stretches, its neck thins, the drop snaps off, falls through the haze and splashes into the
// glowing pool. Behind it a dead forest stands in the toxic mist, lit from below by the pool;
// slanted light falls through the haze, motes drift, bubbles pop into rings, and the whole pool
// breathes with a slow sickly glow.

float smin(float a, float b, float k) {
    float h = sat(0.5 + 0.5 * (b - a) / k);
    return mix(b, a, h) - k * h * (1.0 - h);
}

// Lower edge of the ooze hanging from the top, at x (in screen heights).
float oozeEdge(float x, float t) {
    return 0.07 + 0.022 * sin(x * 4.3 + t * 0.21) + 0.012 * sin(x * 11.7 - t * 0.17)
        + 0.045 * vnoise(float2(x * 6.0, 3.1)) + 0.02 * vnoise(float2(x * 17.0, 8.3));
}

// The pool's surface line.
float surfAt(float x, float t) { return 0.72 + 0.006 * sin(x * 14.0 + t * 1.3); }

// A gnarled dead tree: a twisting, tapering trunk with flared roots, four crooked boughs that each
// split into two twigs, and strands of moss hanging from them. q: x from the trunk, y up; th its
// height. Returns the wood distance in x and the moss distance in y.
float tapered(float2 p, float2 a, float2 b, float ra, float rb) {
    float2 pa = p - a, ba = b - a;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h) - mix(ra, rb, h);
}
float2 deadTree(float2 q, float th, float id, float sc) {
    float h01 = clamp(q.y / th, 0.0, 1.0);
    float2 tq = q;
    tq.x -= 0.012 * th * sin(q.y / th * 5.0 + id) + 0.02 * th * sin(q.y / th * 2.0 + id * 1.7);
    float wood = abs(tq.x) - mix(0.009, 0.0015, sqrt(h01)) * sc;
    wood = max(wood, max(-q.y, q.y - th));
    // Roots flaring out at the foot.
    wood = min(wood, tapered(q, float2(0.0, 0.012), float2(-0.022, -0.004), 0.003 * sc, 0.0006));
    wood = min(wood, tapered(q, float2(0.0, 0.012), float2(0.02, -0.004), 0.003 * sc, 0.0006));
    float moss = 1e5;
    for (int i = 0; i < 4; i++) {
        float fi = float(i);
        float side = mod(fi + floor(hash11(id) * 2.0), 2.0) * 2.0 - 1.0;
        float y0 = th * (0.38 + 0.17 * fi + 0.06 * hash11(id + fi));
        float2 b0 = float2(0.012 * th * sin(y0 / th * 5.0 + id) + 0.02 * th * sin(y0 / th * 2.0 + id * 1.7), y0);
        float len = th * (0.27 - 0.045 * fi) * (0.7 + 0.5 * hash11(id * 3.0 + fi));
        float2 b1 = b0 + float2(side * len * 0.85, len * (0.35 + 0.3 * hash11(id + fi * 7.0)));
        float2 elbow = mix(b0, b1, 0.5) + float2(0.0, -len * 0.12);
        float rw = mix(0.005, 0.0016, fi / 3.0) * sc;
        wood = min(wood, tapered(q, b0, elbow, rw, rw * 0.7));
        wood = min(wood, tapered(q, elbow, b1, rw * 0.7, 0.0005));
        // Two twigs from the bough's tip.
        float2 t1 = b1 + float2(side * len * 0.35, len * 0.35);
        float2 t2 = b1 + float2(side * len * 0.15, -len * 0.25);
        wood = min(wood, tapered(q, b1, t1, 0.0008, 0.0003));
        wood = min(wood, tapered(q, elbow, t2 + float2(0.0, len * 0.2), 0.0008, 0.0003));
        // Moss hanging from the elbow: a thin strand, swaying a little.
        float ml = len * (0.3 + 0.3 * hash11(id + fi * 11.0));
        float2 m0 = elbow + float2(side * len * 0.1, 0.0);
        float2 mq = q - m0;
        float mu = clamp(-mq.y / ml, 0.0, 1.0);
        moss = min(moss, length(float2(mq.x - 0.004 * sin(mu * 6.0 + id), mq.y + mu * ml)) - 0.0012 * (1.0 - mu) - 0.0003);
    }
    return float2(wood, moss);
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float px = 1.6 / uRes.y;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float3 TOX = mix(S, A, 0.15);          // the glowing poison
    float3 HAZE = mix(BG, A, 0.3);

    float breathe = 0.5 + 0.5 * sin(t * 0.6);
    float surf = surfAt(uv.x, t);

    // ---- Sky: deep at the top, a sick haze rising off the pool ----
    float3 col = mix(BG * 0.3, HAZE * 0.9, smoothstep(0.02, surf, uv.y));
    float2 sp = rot(0.38) * (uv - float2(asp * 0.25, 0.0));
    float shafts = smoothstep(0.42, 0.85, fbm3(float2(sp.x * 5.0 + t * 0.03, 0.4 + t * 0.02)));
    col += mix(A, S, 0.35) * shafts * smoothstep(surf, 0.08, uv.y) * smoothstep(0.08, 0.25, uv.y) * 0.2;
    // A sick moon behind the haze, a focal point for the sky.
    float2 mc = float2(asp * 0.76, 0.27);
    float md = length(uv - mc);
    float3 MOON = mix(S, float3(1.0), 0.55);
    float veil = fbm3(float2(uv.x * 3.0 - t * 0.02, uv.y * 6.0));
    float moonDisk = (1.0 - smoothstep(0.068, 0.068 + px, md));
    float crater = smoothstep(0.5, 0.75, fbm3((uv - mc) * 26.0 + 4.0));
    col = mix(col, MOON * (0.75 - 0.25 * crater), moonDisk * (0.85 - 0.5 * smoothstep(0.45, 0.8, veil)));
    col += MOON * glow(max(md - 0.068, 0.0), 0.05) * 0.35;
    col += mix(S, A, 0.5) * exp(-md * 4.0) * 0.08;
    // Far haze clouds drifting.
    float far = fbm3(float2(uv.x * 1.6 - t * 0.012, uv.y * 3.0));
    col = mix(col, HAZE, smoothstep(0.45, 0.8, far) * smoothstep(0.15, 0.6, uv.y) * 0.35);

    // ---- Dead forest standing in the mist (two layers) ----
    for (int layer = 0; layer < 2; layer++) {
        float fl = float(layer);
        float scale = 6.0 + 4.0 * fl;                      // trees per screen height
        float base = surf - 0.015 + 0.012 * fl;           // the nearer layer stands a little lower
        float ridge = base - (0.03 + 0.05 * fl) * fbm3(float2(uv.x * 2.5 + fl * 7.0, fl));
        float cell = uv.x * scale + fl * 3.7;
        float id = floor(cell);
        float present = step(0.3, hash11(id * 1.37 + fl * 9.0));
        float th = (0.18 + 0.2 * hash11(id * 2.11 + fl)) * (1.0 - 0.3 * fl);
        float lean = (hash11(id * 5.3 + fl) - 0.5) * 0.06;
        // Local coordinates in screen heights: x from the cell's trunk, y up from the ridge.
        float2 q = float2((fract(cell) - 0.5 - (hash11(id + 4.0) - 0.5) * 0.4) / scale, ridge - uv.y);
        q.x -= lean * q.y;
        float2 dt = deadTree(q, th, id, 1.4 - 0.4 * fl);
        float sil = max(present * (1.0 - smoothstep(-px, px, dt.x)), step(ridge, uv.y));
        // Far trees fade into the haze; both are lit from below by the pool.
        float3 dark = mix(BG * 0.08, HAZE * 0.6, 0.6 - 0.55 * fl);
        dark += A * exp(-(surf - uv.y) * 14.0) * (0.12 + 0.1 * breathe);
        col = mix(col, dark, sil * step(uv.y, surf));
        // A toxic rim on the wood's underside edges, and faintly glowing moss.
        float rim = present * smoothstep(px * 2.5, 0.0, abs(dt.x + px)) * (1.0 - smoothstep(-px, px, dt.x - px * 2.0));
        col += TOX * rim * 0.18 * fl * exp(-(surf - uv.y) * 5.0) * (0.6 + 0.4 * breathe);
        float mossM = present * (1.0 - smoothstep(-px, px, dt.y)) * step(uv.y, surf);
        col = mix(col, mix(dark, TOX * 0.5, 0.35 + 0.25 * breathe), mossM * (0.5 + 0.5 * fl));
        // Mist band in front of each layer.
        float m = fbm(float2(uv.x * 2.2 - t * (0.03 + 0.03 * fl) + fl * 5.0, uv.y * 5.0 + t * 0.02));
        float band = exp(-abs(uv.y - (ridge + 0.02)) * (14.0 - 4.0 * fl));
        col = mix(col, mix(HAZE, A, 0.3) * 0.85, smoothstep(0.45, 0.85, m) * band * 0.45 * step(uv.y, surf + 0.02));
    }

    // Glow from the pool on everything above it.
    if (uv.y < surf) col += A * exp(-(surf - uv.y) * 7.0) * (0.1 + 0.1 * breathe);

    // ---- The pool ----
    if (uv.y >= surf) {
        float depth = (uv.y - surf) / (1.0 - surf);
        float3 pool = mix(A * (0.48 + 0.25 * breathe), BG * 0.55, depth * 0.8);
        // Upside-down reflection of the haze line and the glowing ooze colour.
        pool += TOX * 0.06 * (1.0 - depth);
        float caust = fbm3(float2(uv.x * 5.0 + t * 0.2, uv.y * 12.0 - t * 0.3));
        pool += S * smoothstep(0.55, 0.8, caust) * 0.16;
        // Slow sickly swirls.
        float swirl = fbm3(float2(uv.x * 2.0 - t * 0.05, uv.y * 4.0 + sin(uv.x * 3.0 + t * 0.2)));
        pool += mix(A, S, 0.5) * smoothstep(0.55, 0.75, swirl) * 0.08;
        col = pool;
        col += mix(A, float3(1.0), 0.4) * exp(-(uv.y - surf) * 160.0) * 0.45;
    }

    // ---- Ooze hanging from the top, and its drips (each pixel checks its own column and the next ones) ----
    float d = uv.y - oozeEdge(uv.x, t);   // < 0 inside the ooze
    float dropD = 1e5;
    float splash = 0.0;
    float cw = 0.105;
    float ci = floor(uv.x / cw);
    for (int k = -1; k <= 1; k++) {
        float id = ci + float(k);
        float h = hash11(id * 3.17 + 0.5);
        if (h > 0.2) {
            float cx = (id + 0.3 + 0.4 * hash11(id + 11.0)) * cw;
            float per = 4.5 + 5.0 * hash11(id + 5.0);
            float ph = fract(t / per + hash11(id + 2.0));
            float top = oozeEdge(cx, t);
            float L = 0.05 + 0.12 * hash11(id + 7.0);           // how far it stretches before snapping
            float rb = 0.009 + 0.007 * hash11(id + 13.0);      // the drop's size
            if (ph < 0.72) {
                float g = ph / 0.72;
                float grow = g * g * (3.0 - 2.0 * g);
                float2 tip = float2(cx + 0.002 * sin(t * 2.0 + id), top + L * grow);
                float neck = sdSegment(uv, float2(cx, top - 0.02), tip) - mix(0.011, 0.0028, grow);
                float bulb = length((uv - tip) * float2(1.0, 0.85)) - rb * (0.55 + 0.45 * grow);
                d = smin(d, smin(neck, bulb, 0.01), 0.022);
            } else {
                float f = (ph - 0.72) / 0.28;
                // The neck springs back up…
                float stub = sdSegment(uv, float2(cx, top - 0.02), float2(cx, top + L * 0.45 * (1.0 - smoothstep(0.0, 0.5, f)))) - 0.006;
                d = smin(d, stub, 0.02);
                // …while the drop falls (stretched a little by the speed) and splashes into the pool.
                float s0 = surfAt(cx, t);
                float y0 = top + L;
                float fall = sat(f / 0.8);
                float y = y0 + (s0 - y0) * fall * fall;
                if (fall < 1.0) {
                    // A teardrop: round below, pointed above, longer the faster it falls.
                    float2 dq = uv - float2(cx, y);
                    float up = sat(-dq.y / (rb * (1.6 + 2.0 * fall)));
                    dropD = min(dropD, length(dq * float2(1.0, mix(1.0, 0.45, up))) - rb * 0.8 * (1.0 - 0.65 * up));
                } else {
                    float sp2 = (f - 0.8) / 0.2;
                    float rd = abs(length((uv - float2(cx, s0)) * float2(1.0, 3.2)) - sp2 * 0.07);
                    splash += exp(-rd * 260.0) * (1.0 - sp2);
                    // A few flecks thrown up.
                    float2 fp = float2(cx + (sp2 * 0.03), s0 - sp2 * 0.05 * (1.0 - sp2) * 3.0);
                    float2 fq = float2(cx - (sp2 * 0.025), s0 - sp2 * 0.04 * (1.0 - sp2) * 3.0);
                    splash += (1.0 - smoothstep(0.0, 0.004, length(uv - fp))) * (1.0 - sp2);
                    splash += (1.0 - smoothstep(0.0, 0.0035, length(uv - fq))) * (1.0 - sp2);
                }
            }
        }
    }

    // Shading of the ooze: dark poison with a glowing skin, lit from the pool below, with a wet sheen.
    float inside = 1.0 - smoothstep(-px, px, d);
    float skin = exp(min(d, 0.0) * 70.0);
    float depthIn = sat(-d * 12.0);
    float3 goo = mix(TOX * 0.55, BG * 0.25 + TOX * 0.08, depthIn);
    goo += TOX * skin * (0.35 + 0.15 * breathe);
    // Sheen: a thin bright line just inside the lower edge.
    goo += mix(TOX, float3(1.0), 0.6) * exp(-abs(d + 0.0035) * 900.0) * 0.35;
    // Slow bubbles of light moving inside the ooze.
    float inner = fbm3(float2(uv.x * 9.0 + t * 0.15, uv.y * 14.0 - t * 0.1));
    goo += TOX * smoothstep(0.62, 0.8, inner) * 0.22 * depthIn;
    col = mix(col, goo, inside);
    // Soft halo round it.
    col += TOX * glow(max(d, 0.0), 0.006) * 0.16 * (0.75 + 0.25 * breathe);

    // Falling drops: bright, with a halo.
    float dropIn = 1.0 - smoothstep(-px, px, dropD);
    col = mix(col, mix(TOX, float3(1.0), 0.35), dropIn);
    col += TOX * glow(max(dropD, 0.0), 0.004) * 0.25;
    col += mix(TOX, float3(1.0), 0.4) * splash * 0.8;

    // ---- Bubbles: rise inside the pool, pop into a ring on the surface ----
    for (int k = 0; k < 7; k++) {
        float fk = float(k);
        float per = 3.0 + 2.0 * hash11(fk * 1.9);
        float ph = fract(t / per + hash11(fk + 7.0));
        float x = asp * (0.05 + 0.9 * hash11(fk * 5.1 + floor(t / per + hash11(fk + 7.0))));
        float s0 = surfAt(x, t);
        if (ph < 0.8) {
            float y = 1.0 - (ph / 0.8) * (1.0 - s0);
            float rr = 0.006 + 0.01 * hash11(fk + 3.0);
            float bd = abs(length(uv - float2(x + sin(t * 3.0 + fk) * 0.004, y)) - rr);
            col += mix(S, float3(1.0), 0.5) * (1.0 - smoothstep(0.0, 0.0025, bd)) * 0.55;
        } else {
            float pp = (ph - 0.8) / 0.2;
            float rd = abs(length((uv - float2(x, s0)) * float2(1.0, 3.5)) - pp * 0.06);
            col += mix(A, float3(1.0), 0.5) * exp(-rd * 300.0) * (1.0 - pp) * 0.8;
        }
    }

    // ---- Toxic mist rolling low over the surface ----
    float mist = fbm(float2(uv.x * 2.0 - t * 0.08, uv.y * 4.0 + t * 0.03));
    float low = exp(-abs(uv.y - (surf - 0.04)) * 9.0);
    col = mix(col, mix(A, S, 0.4) * 0.7, smoothstep(0.4, 0.75, mist) * low * (0.32 + 0.2 * breathe));

    // ---- Glowing motes drifting up through the haze ----
    float motes = dots(uv, 16.0, float2(t * 0.04, t * 0.12), 0.07, 0.16, 4.0);
    motes += 0.6 * dots(uv, 28.0, float2(-t * 0.03, t * 0.2), 0.08, 0.12, 9.0);
    col += TOX * motes * 0.7 * smoothstep(0.05, 0.25, uv.y);

    return half4(finish(col, fc), 1.0);
}
"""

    private const val MEADOW = """
// Meadow (normal type): a gentle, everyday afternoon. Soft clouds drift over two rows of hazy hills,
// a windmill turns slowly on the far rise, tall grass fills the front and the wind runs through it in
// visible gusts - bright sheens rolling across the blades - while dandelion seeds float past.

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float px = 1.5 / uRes.y;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    // Sky: warm pale near the horizon, soft blue above, a sun glow at the upper right.
    float3 skyTop = mix(float3(0.42, 0.62, 0.86), BG * 2.0, 0.25);
    float3 skyLow = mix(float3(0.98, 0.92, 0.78), S, 0.15);
    float3 col = mix(skyTop, skyLow, smoothstep(0.0, 0.6, uv.y));
    float2 sunP = float2(asp * 0.78, 0.12);
    col += float3(1.0, 0.95, 0.8) * (exp(-length(uv - sunP) * 9.0) * 0.6 + exp(-length(uv - sunP) * 2.5) * 0.15);
    // Clouds: soft, lit from the top, drifting.
    float2 cp = float2(uv.x * 1.4 + t * 0.012, uv.y * 3.2);
    float cl = fbm(cp);
    float cm = smoothstep(0.5, 0.72, cl) * smoothstep(0.55, 0.15, uv.y);
    float clTop = fbm(cp + float2(0.0, 0.08));
    col = mix(col, mix(float3(0.82, 0.84, 0.9), float3(1.0, 0.99, 0.96), smoothstep(0.45, 0.7, clTop)), cm * 0.9);

    // Far hills, then nearer hills; each hazier with distance.
    float h1 = 0.5 - 0.05 * sin(uv.x * 2.2 + 0.5) - 0.03 * sin(uv.x * 5.1 + 2.0);
    float h2 = 0.6 - 0.06 * sin(uv.x * 1.6 + 2.4) - 0.025 * sin(uv.x * 4.3 + t * 0.0);
    float3 hill1 = mix(mix(float3(0.45, 0.62, 0.45), A, 0.12), col, 0.45);
    float3 hill2 = mix(float3(0.36, 0.56, 0.3), A, 0.1);
    col = mix(col, hill1, smoothstep(h1 - px, h1 + px, uv.y));
    // The windmill on the far rise: a tapered tower with a cap and four slowly turning sails.
    float2 wm = float2(asp * 0.3, 0.5 - 0.05 * sin(asp * 0.3 * 2.2 + 0.5) - 0.03 * sin(asp * 0.3 * 5.1 + 2.0));
    float2 wq = uv - wm;
    float tower = max(abs(wq.x) - (0.012 + 0.008 * sat(wq.y / -0.09 + 1.0) * 0.0) - 0.006 * sat(1.0 + wq.y / 0.09), max(wq.y, -wq.y - 0.09));
    float cap = length((wq - float2(0.0, -0.092)) * float2(1.0, 1.4)) - 0.014;
    float2 hub = wm + float2(0.0, -0.094);
    float2 hq = rot(t * 0.35) * (uv - hub);
    float sails = 1e5;
    for (int i = 0; i < 4; i++) {
        float2 r = rot(float(i) * PI * 0.5) * hq;
        sails = min(sails, sdRoundBox(r - float2(0.0, 0.034), float2(0.007, 0.03), 0.002));
        sails = min(sails, sdSegment(r, float2(0.0), float2(0.0, 0.066)) - 0.0012);
    }
    float3 wmCol = mix(float3(0.92, 0.9, 0.86), col, 0.35);
    col = mix(col, wmCol * 0.9, 1.0 - smoothstep(-px, px, min(tower, cap)));
    col = mix(col, mix(float3(0.95, 0.94, 0.9), col, 0.3), 1.0 - smoothstep(-px, px, sails));
    col = mix(col, hill2 * (0.85 + 0.15 * vnoise(uv * float2(20.0, 60.0))), smoothstep(h2 - px, h2 + px, uv.y));

    // Front grass: blades in two rows; the wind runs through as travelling gusts.
    float gustF = sin(uv.x * 3.0 - t * 1.4) * 0.5 + 0.5;
    float gust = smoothstep(0.55, 1.0, gustF) * (0.6 + 0.4 * vnoise(float2(uv.x * 2.0 - t * 0.5, 3.0)));
    for (int r = 0; r < 2; r++) {
        float fr = float(r);
        float base = 0.82 + fr * 0.12;
        float bw = 0.006 + 0.004 * fr;
        float x = uv.x / bw + fr * 0.37;
        float id = floor(x);
        float lx = fract(x) - 0.5;
        float hgt = (0.16 + 0.12 * hash11(id + fr * 11.0)) * (1.0 + 0.4 * fr);
        float yy = (base - uv.y) / hgt;                // 0 at the foot, 1 at the tip
        float g = sin(id * 0.05 * bw * 100.0 - t * 1.4) * 0.5 + 0.5;
        float bend = (0.35 + 1.4 * smoothstep(0.55, 1.0, g)) * yy * yy + 0.15 * sin(t * 2.0 + id) * yy * yy;
        float w = 0.45 * (1.0 - yy);
        float blade = step(0.0, yy) * step(yy, 1.0) * step(abs(lx - bend), w);
        float3 gc = mix(float3(0.22, 0.45, 0.16), float3(0.6, 0.78, 0.32), yy * 0.8 + 0.2 * hash11(id));
        gc = mix(gc, A * 0.5 + gc * 0.6, 0.1);
        gc += float3(1.0, 0.98, 0.8) * 0.18 * gust * yy;             // the gust's sheen
        col = mix(col, gc * (0.75 + 0.25 * fr), blade);
        col = mix(col, gc * 0.55 * (0.75 + 0.25 * fr), step(base, uv.y) * step(fr, 0.5) * step(uv.y, 1.0));
    }
    col = mix(col, float3(0.18, 0.34, 0.12), step(0.94, uv.y) * 0.8);

    // Dandelion seeds: a dot with a fuzzy crown, drifting with the wind.
    for (int i = 0; i < 9; i++) {
        float fi = float(i);
        float life = fract(t * (0.035 + 0.01 * hash11(fi)) + hash11(fi * 7.0));
        float2 p = float2(fract(hash11(fi * 3.0) + life * 1.4) * (asp + 0.2) - 0.1,
                          0.25 + 0.5 * hash11(fi * 5.0) + 0.05 * sin(life * 12.0 + fi) - 0.1 * life);
        float2 q = uv - p;
        float d = length(q);
        float sz = 0.006 + 0.004 * hash11(fi * 13.0);
        float a = atan(q.y, q.x);
        float crown = exp(-abs(d - sz) * 600.0) * (0.5 + 0.5 * sin(a * 9.0 + life * 3.0)) * step(q.y, 0.002);
        col += float3(1.0) * (crown * 0.5 + exp(-d * 900.0) * 0.3);
    }
    return half4(finish(col * 0.92, fc), 1.0);
}
