    private const val THICKET = """
// Thicket (bug type): the undergrowth at dusk, seen from an insect's height. Huge leaves lean in from
// the sides, backlit so their veins glow; grass stalks rise against a green-gold haze; a spider web
// strung between two stems sways and its dew drops glint; swarms of fireflies wander and blink, and a
// beetle trundles along a stalk.

// A leaf: an almond shape along a curved midrib from a to b; returns (distance, along, across).
float3 leaf(float2 p, float2 a, float2 b, float w, float curve) {
    float2 ab = b - a;
    float L = length(ab);
    float2 dir = ab / L;
    float2 q = float2(dot(p - a, dir), dot(p - a, float2(-dir.y, dir.x)));
    float u = q.x / L;
    q.y -= curve * L * u * (1.0 - u) * 4.0;
    float half_ = w * L * sin(PI * sat(u)) * (0.7 + 0.3 * sat(1.0 - u));
    float d = max(abs(q.y) - half_, max(-q.x, q.x - L));
    return float3(d, u, q.y / max(half_, 1e-4));
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float px = 1.5 / uRes.y;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    // Haze: deep green above, warm gold glow low down where the last light comes through.
    float3 col = mix(mix(BG * 1.4, A * 0.25, 0.4), mix(float3(0.85, 0.7, 0.35), S, 0.3) * 0.75, smoothstep(0.1, 0.85, uv.y));
    col += mix(float3(1.0, 0.8, 0.4), S, 0.3) * exp(-length((uv - float2(asp * 0.55, 0.7)) * float2(0.6, 1.0)) * 3.0) * 0.25;
    // Far stalks: soft, out of focus.
    float fs = abs(fract(uv.x * 9.0 + 0.3 * sin(uv.y * 3.0 + floor(uv.x * 9.0))) - 0.5);
    col = mix(col, col * 0.6, (1.0 - smoothstep(0.03, 0.08, fs)) * step(hash11(floor(uv.x * 9.0)), 0.6) * smoothstep(0.2, 0.6, uv.y) * 0.6);

    // Near stalks with the web between two of them.
    float2 s1a = float2(asp * 0.62, 1.05), s1b = float2(asp * 0.6 + 0.02 * sin(t * 0.4), 0.18);
    float2 s2a = float2(asp * 0.86, 1.05), s2b = float2(asp * 0.9 + 0.02 * sin(t * 0.37 + 1.0), 0.28);
    float st = min(sdSegment(uv, s1a, s1b) - 0.006, sdSegment(uv, s2a, s2b) - 0.005);
    float3 stalkC = mix(float3(0.16, 0.26, 0.1), BG, 0.3);
    col = mix(col, stalkC + float3(0.9, 0.7, 0.3) * 0.08 * step(0.0, uv.x - asp * 0.6), 1.0 - smoothstep(-px, px, st));
    // The web: radial threads and a spiral between the stalks, swaying, with dew.
    float2 wc = float2(asp * 0.75 + 0.01 * sin(t * 0.5), 0.45 + 0.006 * sin(t * 0.7));
    float2 wq = uv - wc;
    float wr = length(wq);
    float wa = atan(wq.y, wq.x);
    float inWeb = step(wr, 0.15);
    float radial = exp(-abs(fract(wa / TAU * 14.0) - 0.5) * (TAU / 14.0) * wr * 700.0);
    float spiral = exp(-abs(fract((wr - wa / TAU * 0.012) / 0.012) - 0.5) * 0.012 * 700.0);
    float thread = max(radial, spiral * step(0.012, wr)) * inWeb;
    float shimmer = 0.5 + 0.5 * sin(wa * 3.0 + t * 0.6 + wr * 20.0);
    col += float3(0.95, 0.95, 0.85) * thread * (0.08 + 0.18 * shimmer);
    float2 dg = floor(float2(wa / TAU * 14.0, (wr - wa / TAU * 0.012) / 0.012));
    float dew = step(0.75, hash12(dg)) * inWeb * spiral * radial;
    col += float3(1.0) * dew * (0.6 + 0.4 * sin(t * 2.0 + hash12(dg) * 6.0));

    // The beetle on the left stalk, slowly climbing and coming back down.
    float by = mix(0.75, 0.35, 0.5 + 0.5 * sin(t * 0.12));
    float2 bpos = mix(s1a, s1b, (1.05 - by) / (1.05 - 0.18)) + float2(-0.012, 0.0);
    float2 bq = uv - bpos;
    float shell = length(bq * float2(1.6, 1.0)) - 0.016;
    float head = length(bq - float2(0.0, -0.019)) - 0.006;
    float3 beetle = mix(A * 0.6, float3(0.1, 0.35, 0.3), 0.5);
    beetle += float3(1.0) * 0.35 * exp(-length(bq - float2(-0.004, -0.006)) * 300.0);
    col = mix(col, beetle, 1.0 - smoothstep(-px, px, min(shell, head)));
    col = mix(col, float3(0.05), (1.0 - smoothstep(0.0, px, abs(bq.x))) * step(abs(bq.y + 0.002), 0.014) * step(shell, 0.0));

    // Big leaves leaning in from the sides, backlit: translucent green with glowing veins.
    for (int i = 0; i < 4; i++) {
        float fi = float(i);
        float side = fi < 2.0 ? -1.0 : 1.0;
        float2 a = float2(side < 0.0 ? -0.05 : asp + 0.05, 0.95 - fi * 0.0 - mod(fi, 2.0) * 0.35);
        float2 b = a + float2(-side * (0.55 - mod(fi, 2.0) * 0.15), -0.3 + mod(fi, 2.0) * 0.08) * (1.0 + 0.02 * sin(t * 0.5 + fi));
        float3 lf = leaf(uv, a, b, 0.32, 0.12 * side);
        float m = 1.0 - smoothstep(-px, px, lf.x);
        float veins = exp(-abs(lf.z) * 60.0) + exp(-abs(fract(lf.y * 9.0 - abs(lf.z) * 1.2) - 0.5) * 16.0) * 0.5 * (1.0 - abs(lf.z));
        float3 lc = mix(float3(0.12, 0.28, 0.08), float3(0.45, 0.62, 0.15), 0.4 + 0.4 * (1.0 - abs(lf.z)));
        lc = mix(lc, A * 0.4 + lc * 0.7, 0.15);
        lc += mix(float3(0.9, 0.85, 0.35), S, 0.2) * veins * 0.18;
        lc *= 0.85 + 0.15 * vnoise(uv * 80.0);
        col = mix(col, lc * (0.7 + 0.15 * mod(fi, 2.0)), m);
    }

    // Fireflies: swarms wandering on slow curling paths, each blinking on its own rhythm.
    float n = uLod > 1.5 ? 14.0 : 26.0;
    for (int i = 0; i < 26; i++) {
        float fi = float(i);
        if (fi >= n) break;
        float2 h = hash22(float2(fi, fi * 1.7));
        float2 p = float2(h.x * asp, 0.2 + 0.65 * h.y);
        p += 0.08 * float2(sin(t * (0.21 + 0.1 * h.y) + fi), cos(t * (0.17 + 0.1 * h.x) + fi * 1.3));
        p += 0.03 * float2(sin(t * 0.9 + fi * 2.1), sin(t * 1.1 + fi * 0.7));
        float blink = smoothstep(0.55, 0.9, sin(t * (1.2 + h.x) + fi * 3.0));
        float d = length(uv - p);
        float3 fcol = mix(float3(0.85, 1.0, 0.4), S, 0.25);
        col += fcol * (exp(-d * 700.0) * 1.2 + exp(-d * 60.0) * 0.15) * blink;
    }
    return half4(finish(col, fc), 1.0);
}
"""

    private const val BEDROCK = """
// Bedrock (rock type): a deep canyon at golden hour. Layered sandstone walls close in from both sides,
// every stratum its own colour and grain, carved into ledges; a natural arch and a far mesa stand in
// the haze down the canyon; dust hangs in the low sun, and now and then a pebble breaks loose and
// bounces down a wall, leaving a little puff behind it.

// A canyon wall's edge (distance from the screen side, in screen heights) at height y: ledges where
// harder layers stick out.
float wallEdge(float y, float seed) {
    float layer = floor(y * 14.0 + seed);
    float hard = hash11(layer + seed * 7.0);
    float base = 0.32 + 0.12 * sin(y * 2.3 + seed) + 0.06 * sin(y * 6.1 + seed * 2.0);
    return base + 0.035 * hard + 0.012 * vnoise(float2(y * 60.0, seed));
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float px = 1.5 / uRes.y;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float cx = asp * 0.5;

    // Sky strip above the canyon and the warm haze down it.
    float3 sky = mix(mix(float3(0.35, 0.5, 0.75), BG * 2.0, 0.3), mix(float3(1.0, 0.78, 0.5), S, 0.2), smoothstep(0.0, 0.6, uv.y));
    float3 col = sky;
    float2 sunP = float2(cx + 0.15, 0.3);
    col += float3(1.0, 0.85, 0.6) * exp(-length(uv - sunP) * 6.0) * 0.35;
    // The far mesa and the arch, flat and hazy.
    float mesa = step(0.48 - 0.05 * step(abs(uv.x - cx - 0.25), 0.18) - 0.012 * vnoise(float2(uv.x * 30.0, 1.0)), uv.y);
    float3 far = mix(mix(float3(0.75, 0.45, 0.3), A, 0.15), sky, 0.55);
    col = mix(col, far, mesa);
    float2 aq = uv - float2(cx - 0.12, 0.6);
    float archOuter = sdRoundBox(aq + float2(0.0, 0.07), float2(0.1, 0.09), 0.08);
    float archInner = sdRoundBox(aq + float2(0.0, 0.02), float2(0.065, 0.08), 0.06);
    float arch = max(archOuter, -archInner);
    col = mix(col, mix(far * 0.85, sky, 0.25), (1.0 - smoothstep(-px, px, arch)) * step(uv.y, 0.62));
    // Canyon floor: a dry wash with stones.
    float3 ground = mix(float3(0.55, 0.36, 0.22), A * 0.4, 0.1) * (0.8 + 0.2 * vnoise(uv * float2(40.0, 120.0)));
    col = mix(col, mix(ground, sky, 0.3 * smoothstep(0.8, 0.6, uv.y)), smoothstep(0.6, 0.62, uv.y));

    // The two walls: strata in bands, lit on the left wall's face by the low sun, the right in shade.
    for (int s = 0; s < 2; s++) {
        float side = s == 0 ? -1.0 : 1.0;
        float seed = s == 0 ? 1.3 : 4.7;
        float xd = side < 0.0 ? uv.x : asp - uv.x;         // distance from this side
        float e = wallEdge(uv.y, seed) * (0.9 + 0.25 * smoothstep(0.7, 0.2, uv.y)) * asp / 1.78;
        float m = 1.0 - smoothstep(e - px, e + px, xd);
        float layer = floor(uv.y * 14.0 + seed);
        float3 strata = mix(float3(0.72, 0.38, 0.22), float3(0.88, 0.66, 0.42), hash11(layer * 3.1));
        strata = mix(strata, float3(0.55, 0.3, 0.22), step(0.8, hash11(layer * 1.7)) * 0.6);
        strata = mix(strata, strata * A * 1.6, 0.08);
        // Grain inside each band, and darker cracks between them.
        strata *= 0.85 + 0.2 * vnoise(float2(uv.x * 30.0 * side, uv.y * 140.0 + layer));
        strata *= 1.0 - 0.3 * exp(-abs(fract(uv.y * 14.0 + seed) - 0.0) * 30.0);
        // Light: the face near the edge catches the sun (left wall), the rest falls into shade.
        float edgeLight = exp(-(e - xd) * 25.0);
        float lit = side < 0.0 ? 0.75 + 0.45 * edgeLight : 0.45 + 0.2 * edgeLight;
        strata *= lit;
        // Ledges: the top of each hard layer catches a line of light.
        strata += float3(1.0, 0.85, 0.6) * 0.12 * exp(-fract(uv.y * 14.0 + seed) * 40.0) * edgeLight;
        strata = mix(strata, sky, 0.12);
        col = mix(col, strata, m);
    }

    // Dust hanging in the light.
    col += float3(1.0, 0.85, 0.6) * dots(uv + float2(t * 0.003, t * 0.001), 110.0, float2(0.0), 0.08, 0.05, 6.0) * 0.4;
    float haze = fbm3(float2(uv.x * 2.0 + t * 0.02, uv.y * 4.0));
    col = mix(col, mix(float3(1.0, 0.82, 0.6), S, 0.2), smoothstep(0.45, 0.8, haze) * 0.12 * smoothstep(0.2, 0.7, uv.y));

    // A pebble bouncing down a wall every few seconds, with a puff at each bounce.
    float cyc = mod(t, 6.0);
    float ps = floor(t / 6.0);
    float side = hash11(ps) > 0.5 ? 1.0 : -1.0;
    float py = 0.12 + cyc * 0.14;
    float ex = wallEdge(py, side < 0.0 ? 1.3 : 4.7) * (0.9 + 0.25 * smoothstep(0.7, 0.2, py)) * asp / 1.78;
    float bounce = abs(sin(cyc * 4.0)) * 0.025;
    float2 pp = float2(side < 0.0 ? ex + bounce : asp - ex - bounce, py);
    float alive = step(cyc, 3.5);
    col = mix(col, float3(0.4, 0.26, 0.18), (1.0 - smoothstep(0.0, px, length(uv - pp) - 0.006)) * alive);
    float lastHit = fract(cyc * 4.0 / PI);
    float2 puffP = float2(side < 0.0 ? ex : asp - ex, 0.12 + (cyc - lastHit * PI / 4.0) * 0.14);
    float puff = exp(-length(uv - puffP) / (0.01 + lastHit * 0.03)) * (1.0 - lastHit) * alive;
    col = mix(col, float3(0.85, 0.7, 0.55), puff * 0.5);
    return half4(finish(col * 0.92, fc), 1.0);
}
"""

    private const val WYRM = """
// Wyrm (dragon type): a storm at twilight with a great serpent of the sky swimming through it. Its
// long scaled body weaves in and out of the cloud banks - front coils in front of the clouds, back
// coils behind them - a ridge of spines along its back, scales catching the light in the theme's
// colours; lightning flickers inside the clouds and embers drift up.

// Height of the body's centre line at x, and its thickness, for coil c (0 = behind, 1 = in front).
float bodyY(float x, float t, float c) {
    return 0.45 + 0.12 * sin(x * 3.2 - t * 0.5 + c * 2.6) + 0.05 * sin(x * 7.0 - t * 0.9 + c);
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float px = 1.5 / uRes.y;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    // Sky: storm violet over a last band of light.
    float3 col = mix(BG * 1.3 + A * 0.06, mix(S, float3(1.0, 0.6, 0.4), 0.4) * 0.5, smoothstep(0.2, 0.95, uv.y));
    // Lightning inside the clouds: a flicker every few seconds lighting a patch from within.
    float lc = mod(t, 4.3);
    float flash = (exp(-lc * 14.0) + 0.6 * exp(-abs(lc - 0.18) * 30.0)) ;
    float2 lp = float2(hash11(floor(t / 4.3)) * asp, 0.25 + 0.2 * hash11(floor(t / 4.3) + 3.0));

    float3 cloudLit = mix(float3(0.55, 0.5, 0.7), S, 0.25);
    float3 cloudDark = mix(BG * 0.9, A * 0.2, 0.2);
    // Back cloud bank.
    float cb = fbm(float2(uv.x * 1.5 - t * 0.015, uv.y * 3.0));
    float backM = smoothstep(0.42, 0.62, cb);
    float3 backC = mix(cloudDark, cloudLit * 0.7, smoothstep(0.5, 0.75, fbm(float2(uv.x * 1.5 - t * 0.015, uv.y * 3.0 - 0.05))));
    backC += float3(0.85, 0.85, 1.0) * flash * exp(-length(uv - lp) * 4.0) * 0.8;

    // The serpent: two passes of the same long body; the back coil is drawn, then clouds, then the
    // front coil, so it weaves through the bank.
    float3 body = float3(0.0);
    float bodyM = 0.0;
    for (int c = 0; c < 2; c++) {
        float fcn = float(c);
        // Only part of each coil is visible: it dives in and out.
        float cy = bodyY(uv.x, t, fcn);
        float thick = 0.042 + 0.014 * sin(uv.x * 2.0 - t * 0.3 + fcn);
        // Slope for the scale direction and the lighting.
        float dy = (bodyY(uv.x + 0.01, t, fcn) - cy) / 0.01;
        float d = (uv.y - cy) / sqrt(1.0 + dy * dy);
        float inside = 1.0 - smoothstep(thick - px, thick + px, abs(d));
        float visible = smoothstep(-0.1, 0.1, sin(uv.x * 1.3 - t * 0.2 + fcn * 3.0));
        // Scales: overlapping rows along the body, offset every other row.
        float along = uv.x * 26.0 - t * 1.5;
        float row = floor(d / thick * 2.5);
        float2 sc = float2(fract(along + row * 0.5) - 0.5, fract(d / thick * 2.5) - 0.5);
        float scale = smoothstep(0.5, 0.2, length(sc * float2(1.0, 1.4)));
        float lit = 0.5 + 0.5 * (-d / thick);                     // lit from above
        float3 skin = mix(A * 0.45, mix(A, S, 0.5) * 0.9, lit);
        skin *= 0.55 + 0.6 * scale;
        skin += mix(S, float3(1.0), 0.4) * 0.25 * smoothstep(0.3, 0.45, length(sc * float2(1.0, 1.4))) * (1.0 - smoothstep(0.45, 0.5, length(sc * float2(1.0, 1.4)))) * lit;
        skin += float3(1.0) * pow(sat(1.0 - abs(d / thick + 0.5) * 3.0), 3.0) * 0.25;        // sheen line
        skin += float3(0.85, 0.85, 1.0) * flash * 0.35 * exp(-length(uv - lp) * 3.0);
        // Belly plates on the underside.
        skin = mix(skin, mix(S, float3(1.0, 0.9, 0.7), 0.5) * 0.7 * (0.8 + 0.2 * step(0.5, fract(along * 0.5))), smoothstep(0.35, 0.75, d / thick));
        // Spines along the back: little triangles above the body.
        float sx = fract(uv.x * 22.0 - t * 0.95) - 0.5;
        float spineD = (-d - thick) / (0.022 * (1.0 - abs(sx) * 2.0) + 1e-4);
        float spine = step(0.0, spineD) * step(spineD, 1.0) * step(abs(sx), 0.5);
        float3 spineC = mix(S, float3(1.0), 0.2) * 0.8;
        if (c == 0) {
            col = mix(col, skin * 0.65, inside * visible);
            col = mix(col, spineC * 0.6, spine * visible);
            col = mix(col, backC, backM * 0.92);
        } else {
            body = mix(body, skin, inside);
            body = mix(body, spineC, spine * (1.0 - inside));
            bodyM = max(inside, spine) * visible;
        }
    }
    // Front cloud wisps and the front coil.
    col = mix(col, body, bodyM);
    float cf = fbm(float2(uv.x * 2.2 - t * 0.03, uv.y * 4.5 + 3.0));
    float frontM = smoothstep(0.55, 0.7, cf) * smoothstep(0.35, 0.7, uv.y);
    col = mix(col, mix(cloudDark, cloudLit, 0.35) + float3(0.85, 0.85, 1.0) * flash * exp(-length(uv - lp) * 3.0) * 0.4, frontM * 0.85);

    // Embers drifting up.
    float emb = dots(uv + float2(sin(uv.y * 8.0 + t * 0.5) * 0.02, t * 0.05), 60.0, float2(0.0), 0.12, 0.06, 4.0);
    col += mix(float3(1.0, 0.6, 0.25), S, 0.3) * emb * 0.7 * smoothstep(0.2, 0.9, uv.y);
    return half4(finish(col, fc), 1.0);
}
"""

    private const val UMBRA = """
// Umbra (dark type): a city at the hour of an eclipse. A black sun hangs in a ring of corona with slow
// flares; stars show through the false night; shadow smoke rises between the rooftops with faint rims
// of light; a few windows still burn; crows circle the eclipse, and pairs of eyes open and blink in the
// dark alleys below.

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float px = 1.5 / uRes.y;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    float3 col = mix(BG * 0.6, BG * 1.4 + A * 0.05, smoothstep(0.0, 0.9, uv.y));
    col += float3(1.0) * dots(uv, 90.0, float2(0.0), 0.2, 0.04, 1.0) * 0.5 * smoothstep(0.7, 0.1, uv.y);

    // The eclipse: a black disc, a corona with streamers turning slowly, a diamond-ring glint.
    float2 ep = float2(asp * 0.66, 0.26);
    float er = 0.09;
    float2 eq = uv - ep;
    float ed = length(eq);
    float ea = atan(eq.y, eq.x);
    float streams = 0.55 + 0.45 * fbm(float2(ea * 2.0 + t * 0.02, ed * 6.0 - t * 0.05));
    float3 corona = mix(mix(S, float3(1.0), 0.5), A, 0.25);
    col += corona * exp(-(ed - er) * 22.0 / streams) * step(er, ed) * 0.9;
    col += corona * exp(-(ed - er) * 6.0) * step(er, ed) * 0.18;
    // A flare loop lifting off the rim now and then.
    float fa = floor(t / 7.0) * 2.3;
    float2 fp = ep + float2(cos(fa), sin(fa)) * er;
    float flare = exp(-abs(length(uv - fp) - 0.018) * 400.0) * step(er, ed) * smoothstep(0.0, 1.0, sin(fract(t / 7.0) * PI));
    col += mix(A, float3(1.0, 0.6, 0.5), 0.5) * flare * 0.8;
    col = mix(col, BG * 0.15, 1.0 - smoothstep(er - px, er + px, ed));
    float ga = 0.6 + t * 0.03;
    col += float3(1.0) * exp(-length(uv - ep - float2(cos(ga), sin(ga)) * er) * 180.0) * (0.6 + 0.4 * sin(t * 1.5));

    // Crows circling the eclipse.
    for (int i = 0; i < 5; i++) {
        float fi = float(i);
        float a = t * (0.18 + 0.04 * fi) + fi * 1.3;
        float2 bp = ep + float2(cos(a) * (0.2 + 0.06 * fi), sin(a) * (0.06 + 0.02 * fi) + 0.02 * sin(a * 3.0));
        float2 q = uv - bp;
        q.x *= sign(-sin(a));
        float flap = sin(t * 6.0 + fi * 2.0);
        float wing = abs(q.y + abs(q.x) * (0.5 * flap) - sqf(q.x / 0.014) * 0.003) - 0.0015;
        float crow = (1.0 - smoothstep(0.0, px, wing)) * step(abs(q.x), 0.014);
        crow = max(crow, 1.0 - smoothstep(0.0, px, length(q * float2(0.8, 1.4)) - 0.004));
        col = mix(col, BG * 0.1, crow);
    }

    // Rooftops: two rows of blocks, with chimneys, spires and some lit windows.
    for (int r = 0; r < 2; r++) {
        float fr = float(r);
        float w = 0.09 + 0.04 * fr;
        float x = uv.x / w + fr * 0.5;
        float id = floor(x);
        float lx = fract(x);
        float h = 0.52 + 0.12 * fr + 0.12 * hash11(id + fr * 9.0);
        float spire = step(0.8, hash11(id * 3.1 + fr)) * max(0.0, 0.08 - abs(lx - 0.5) * 0.4);
        float chim = step(0.5, hash11(id * 5.7 + fr)) * step(abs(lx - 0.25), 0.05) * 0.03;
        float top = h - spire - chim;
        float m = step(top, uv.y);
        float3 bc = BG * (0.18 + 0.12 * fr) + A * 0.02;
        // Windows: a few warm ones.
        float2 wg = float2(lx * 5.0, (uv.y - h) * 50.0);
        float2 wid = floor(wg);
        float win = step(0.3, fract(wg.x)) * step(fract(wg.x), 0.7) * step(0.35, fract(wg.y)) * step(fract(wg.y), 0.75) * step(h + 0.02, uv.y);
        float on = step(0.93, hash12(wid + id * 13.0 + fr * 7.0));
        bc += mix(float3(1.0, 0.7, 0.35), S, 0.3) * win * on * 0.7;
        col = mix(col, bc, m);
    }

    // Shadow smoke rising between the roofs: dark, with a faint rim where it catches the corona.
    float sm = fbm(float2(uv.x * 2.5 + sin(uv.y * 3.0 + t * 0.1) * 0.3, uv.y * 2.5 + t * 0.06));
    float smM = smoothstep(0.5, 0.75, sm) * smoothstep(0.3, 0.75, uv.y);
    float rim = smoothstep(0.5, 0.55, sm) * (1.0 - smoothstep(0.55, 0.62, sm)) * smoothstep(0.3, 0.75, uv.y);
    col = mix(col, BG * 0.08, smM * 0.75);
    col += mix(mix(S, float3(1.0), 0.5), A, 0.25) * rim * 0.05;

    // Eyes in the alleys: pairs that open, glance and blink.
    for (int i = 0; i < 6; i++) {
        float fi = float(i);
        float cyc = fract(t * 0.09 + hash11(fi * 7.3));
        float open = smoothstep(0.0, 0.08, cyc) * (1.0 - smoothstep(0.32, 0.4, cyc));
        open *= 1.0 - step(0.18, cyc) * step(cyc, 0.2);
        float2 p = float2((hash11(fi * 3.1) * 0.9 + 0.05) * asp, 0.8 + 0.12 * hash11(fi * 5.3));
        float2 q = uv - p;
        q.x = abs(q.x) - 0.012;
        float eye = length(q * float2(1.0, 1.0 / max(open, 0.05))) - 0.0045;
        float3 ec = mix(A, float3(1.0, 0.9, 0.3), 0.4);
        col += ec * (1.0 - smoothstep(0.0, px, eye)) * open * 1.2 + ec * exp(-length(q) * 120.0) * open * 0.2;
    }
    return half4(finish(col, fc), 1.0);
}
"""

    private const val ALLOY = """
// Alloy (steel type): a vault of brushed metal. Bevelled steel panels with rivets line the back wall,
// their brushed grain catching a light that sweeps slowly across; a mirror-polished floor reflects
// it all; chrome spheres hover and bob, each reflecting a little world of sky and floor and the moving
// light; far off, a welder's sparks spit now and then.

// What a chrome sphere sees in direction r: a bright ceiling strip, the theme-tinted wall and the
// dark floor below the horizon.
float3 envLook(float3 r, float3 A, float3 S, float3 BG, float sweep) {
    float3 c = mix(BG * 0.6, mix(float3(0.7, 0.74, 0.8), S, 0.2), smoothstep(-0.05, 0.4, -r.y));
    c = mix(c, BG * 0.25, smoothstep(0.0, 0.15, r.y));
    c += float3(1.0) * exp(-abs(r.x - sweep) * 18.0) * smoothstep(0.1, 0.6, -r.y) * 0.8;
    c += A * 0.25 * exp(-abs(r.y + 0.05) * 30.0);
    return c;
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float px = 1.5 / uRes.y;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float horizon = 0.68;
    float sweep = sin(t * 0.25) * 0.9;                 // the light sweeping across (-1..1)
    float sweepX = asp * (0.5 + 0.5 * sweep);

    float3 steel = mix(float3(0.42, 0.45, 0.5), BG * 2.5, 0.3);
    float3 col;
    float2 wuv = uv;
    float refl = 0.0;
    if (uv.y > horizon) { wuv.y = 2.0 * horizon - uv.y; refl = 1.0; }
    // Panels: a grid of bevelled plates.
    float2 pg = float2(wuv.x / 0.3, wuv.y / 0.22);
    float2 pid = floor(pg);
    float2 pf = fract(pg) - 0.5;
    float2 edge = 0.5 - abs(pf);
    float bevel = min(edge.x * 0.3, edge.y * 0.22);
    // Brushed grain: fine streaks along each plate, alternating direction plate to plate.
    float dir = mod(pid.x + pid.y, 2.0);
    float2 gq = dir > 0.5 ? float2(wuv.x * 3.0, wuv.y * 900.0) : float2(wuv.x * 900.0, wuv.y * 3.0);
    float grain = vnoise(gq + pid * 17.0) * 0.6 + vnoise(gq * 2.3) * 0.4;
    // The sweep: anisotropic highlight, stretched along the grain.
    float hl = dir > 0.5 ? exp(-abs(wuv.x - sweepX) * 5.0) : exp(-abs(wuv.x - sweepX) * 14.0);
    col = steel * (0.65 + 0.2 * hash12(pid)) * (0.85 + 0.25 * grain);
    col += float3(1.0, 0.98, 0.95) * hl * (0.25 + 0.3 * grain) * 0.6;
    // Bevels: top/left edges lit, bottom/right in shadow; dark seams between plates.
    float bevM = 1.0 - smoothstep(0.004, 0.009, bevel);
    float litSide = step(pf.y, 0.0) * step(abs(pf.x) * 0.3, abs(pf.y) * 0.22) + step(pf.x, 0.0) * step(abs(pf.y) * 0.22, abs(pf.x) * 0.3);
    col = mix(col, col * mix(0.55, 1.5, litSide), bevM);
    col *= smoothstep(0.0, 0.003, bevel);
    // Rivets at the corners.
    float2 rq = abs(pf * float2(0.3, 0.22)) - float2(0.3, 0.22) * 0.5 + 0.018;
    float rv = length(rq) - 0.006;
    float3 rivet = steel * (0.9 + 0.8 * sat(-(rq.x + rq.y) * 120.0)) + float3(1.0) * hl * 0.3;
    col = mix(col, rivet, 1.0 - smoothstep(-px, px, rv));
    // A channel of the theme colour along the horizon.
    col += A * exp(-abs(wuv.y - horizon + 0.02) * 120.0) * 0.4;
    if (refl > 0.5) {
        float fd = uv.y - horizon;
        col = mix(BG * 0.15, col * 0.55, exp(-fd * 6.0));
        col += float3(1.0) * exp(-abs(uv.x - sweepX) * 8.0) * exp(-fd * 10.0) * 0.12;
    }

    // Chrome spheres hovering, each with its reflection in the floor.
    for (int i = 0; i < 3; i++) {
        float fi = float(i);
        float r = 0.07 + 0.03 * fi;
        float2 c = float2(asp * (0.22 + 0.3 * fi), horizon - 0.2 - 0.06 * sin(fi * 2.0) + 0.02 * sin(t * 0.6 + fi * 2.0));
        for (int m = 0; m < 2; m++) {
            float2 cc = m == 0 ? c : float2(c.x, 2.0 * horizon - c.y);
            float2 q = (uv - cc) / r;
            float d = length(q);
            if (d < 1.0 && (m == 0 || uv.y > horizon)) {
                float3 n = float3(q.x, q.y, -sqrt(max(1.0 - d * d, 0.0)));
                float3 rr = reflect(float3(0.0, 0.0, 1.0), n);
                if (m == 1) rr.y = -rr.y;
                float3 sc = envLook(rr, A, S, BG, sweep);
                sc *= 0.6 + 0.4 * (1.0 - d * d);
                sc += float3(1.0) * pow(sat(1.0 - length(q - float2(-0.35, -0.4)) * 2.4), 6.0) * 0.8;
                float aa = 1.0 - smoothstep(1.0 - px / r * 1.5, 1.0, d);
                col = mix(col, sc * (m == 1 ? 0.45 * exp(-(uv.y - horizon) * 5.0) : 1.0), aa);
            }
        }
        // Soft contact shadow on the floor.
        col *= 1.0 - 0.3 * exp(-length((uv - float2(c.x, horizon + 0.012)) * float2(1.0, 6.0)) / r * 2.0) * step(horizon, uv.y);
    }

    // Distant welding sparks: bursts every few seconds, tiny falling arcs.
    float cyc = mod(t, 3.7);
    float2 wp = float2(asp * (0.15 + 0.7 * hash11(floor(t / 3.7))), horizon - 0.01);
    float burst = exp(-cyc * 1.6) * step(cyc, 1.8);
    for (int i = 0; i < 10; i++) {
        float fi = float(i);
        float2 v = float2((hash11(fi * 3.3) - 0.5) * 0.25, -0.15 - 0.15 * hash11(fi * 1.9));
        float2 p = wp + v * cyc + float2(0.0, 0.25 * cyc * cyc);
        col += mix(float3(1.0, 0.7, 0.3), float3(1.0), 0.4) * exp(-length(uv - p) * 1200.0) * burst * 2.0;
    }
    col += float3(0.8, 0.9, 1.0) * exp(-length(uv - wp) * 60.0) * burst * (0.5 + 0.5 * sin(t * 50.0));
    return half4(finish(col * 0.85, fc), 1.0);
}
"""

    private const val GLIMMER = """
// Glimmer (fairy type): a twilight glade wrapped in a soft pink-lilac haze. A ring of glowing
// mushrooms circles the clearing; little lights swirl in spirals around it, trailing sparkles that
// fade behind them; blossom petals and dreamy bokeh drift; a halo surrounds the pale moon and the
// mushroom caps pulse gently, one after another.

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float px = 1.5 / uRes.y;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float cx = asp * 0.5;

    // Haze: lilac above, rose near the ground.
    float3 col = mix(mix(BG * 1.6, A * 0.35, 0.35), mix(S, float3(1.0, 0.7, 0.85), 0.4) * 0.6, smoothstep(0.0, 0.85, uv.y));
    // Moon with a rainbow-tinged halo.
    float2 mp = float2(asp * 0.2, 0.18);
    float md = length(uv - mp);
    float halo = exp(-abs(md - 0.11) * 50.0);
    col += (0.5 + 0.5 * cos(TAU * (md * 6.0 + float3(0.0, 0.33, 0.67)))) * halo * 0.12;
    col += float3(1.0, 0.95, 1.0) * exp(-md * 10.0) * 0.25;
    col = mix(col, float3(1.0, 0.97, 0.99), 1.0 - smoothstep(0.04 - px, 0.04 + px, md));
    // Bokeh: soft discs drifting.
    for (int k = 0; k < 2; k++) {
        float fk = float(k);
        float2 bp = uv * (5.0 + fk * 3.0) + float2(t * 0.03, -t * 0.02 * (1.0 + fk));
        float2 id = floor(bp);
        float2 h = hash22(id + fk * 5.0);
        float2 f = fract(bp) - 0.5 - (h - 0.5) * 0.5;
        float disc = 1.0 - smoothstep(0.12, 0.2, length(f));
        col += mix(A, float3(1.0, 0.8, 0.95), h.y) * disc * step(0.75, h.x) * 0.08;
    }
    // Trees around the glade: soft rounded crowns, darker with nearness.
    float tr = 0.55 + 0.06 * sin(uv.x * 7.0) + 0.04 * sin(uv.x * 17.0 + 1.0) + 0.05 * smoothstep(0.3, 0.0, abs(uv.x - cx) / asp) ;
    col = mix(col, mix(BG * 0.9, A * 0.25, 0.3), smoothstep(tr - px, tr + px, uv.y) * 0.85);
    // The glade floor: soft moss.
    float gy = 0.72;
    float3 moss = mix(mix(float3(0.3, 0.42, 0.34), BG * 1.5, 0.4), mix(A, S, 0.5) * 0.45, 0.3) * (0.85 + 0.15 * vnoise(uv * float2(30.0, 90.0)));
    col = mix(col, moss, smoothstep(gy - px, gy + px, uv.y));
    // Glow pooled on the floor inside the ring.
    col += mix(A, S, 0.5) * exp(-length((uv - float2(cx, 0.8)) * float2(0.5, 2.0)) * 4.0) * 0.25;

    // The mushroom ring: an ellipse of glowing caps, the far ones smaller; caps pulse in a wave.
    for (int i = 0; i < 10; i++) {
        float fi = float(i);
        float a = fi / 10.0 * TAU + 0.3;
        float2 p = float2(cx + cos(a) * asp * 0.28, 0.8 + sin(a) * 0.07);
        float sc = (0.75 + 0.35 * (sin(a) * 0.5 + 0.5)) * 1.9;
        float pulse = 0.5 + 0.5 * sin(t * 1.2 - fi * 0.63);
        float2 q = (uv - p) / sc;
        float stem = sdRoundBox(q - float2(0.0, -0.012), float2(0.005, 0.014), 0.003);
        float cap = max(length((q - float2(0.0, -0.026)) * float2(1.0, 1.6)) - 0.02, q.y + 0.024);
        float3 capC = mix(A, float3(1.0, 0.75, 0.9), 0.35) * (0.8 + 0.5 * pulse);
        col = mix(col, float3(0.9, 0.86, 0.82) * 0.7, 1.0 - smoothstep(-px, px, stem * sc));
        col = mix(col, capC, 1.0 - smoothstep(-px, px, cap * sc));
        col += capC * exp(-length(q - float2(0.0, -0.03)) * 30.0) * (0.15 + 0.25 * pulse);
    }

    // Swirling lights with sparkle trails: each follows a spiral around the ring; the trail is the
    // same path a moment earlier, fading.
    for (int i = 0; i < 5; i++) {
        float fi = float(i);
        float sp = 0.5 + 0.15 * fi;
        float acc = 0.0;
        for (int j = 0; j < 8; j++) {
            float fj = float(j);
            float tt = t - fj * 0.08;
            float a = tt * sp + fi * 1.26;
            float rad = 0.18 + 0.08 * sin(tt * 0.4 + fi);
            float2 p = float2(cx + cos(a) * rad * asp * 0.8, 0.55 + sin(a) * rad * 0.45 - 0.08 * sin(tt * 0.3 + fi * 2.0));
            float d = length(uv - p);
            float w = 1.0 - fj / 8.0;
            float twinkle = 0.6 + 0.4 * sin(t * 12.0 + fj * 3.0 + fi);
            acc += (exp(-d * mix(240.0, 700.0, fj / 8.0)) + exp(-d * 40.0) * 0.04) * w * w * (fj > 0.5 ? twinkle * 0.8 : 1.6);
        }
        col += mix(float3(1.0, 0.92, 0.98), mix(A, S, fi / 4.0), 0.35) * acc;
    }

    // Petals drifting and turning.
    for (int i = 0; i < 8; i++) {
        float fi = float(i);
        float life = fract(t * (0.04 + 0.01 * hash11(fi)) + hash11(fi * 3.7));
        float2 p = float2(fract(hash11(fi * 1.3) + life * 0.5) * asp, life * 1.1 - 0.05);
        p.x += 0.04 * sin(life * 10.0 + fi);
        float2 q = rot(t * (0.8 + hash11(fi)) + fi) * (uv - p);
        float petal = length(q * float2(1.0, 2.2)) - 0.008;
        col = mix(col, mix(float3(1.0, 0.8, 0.88), S, 0.2), (1.0 - smoothstep(0.0, px, petal)) * 0.85);
    }
    return half4(finish(col, fc), 1.0);
}
