    if (i < 5.5) return uEqB.y;
    if (i < 6.5) return uEqB.z;
    return uEqB.w;
}

// The spectrum at m (0 = lowest band, 1 = highest), smoothly interpolated.
float eqAt(float m) {
    float f = clamp(m, 0.0, 1.0) * 7.0;
    float i = floor(f);
    float u = f - i;
    u = u * u * (3.0 - 2.0 * u);
    return mix(eqBand(i), eqBand(min(i + 1.0, 7.0)), u);
}

// Pushes a colour's saturation by s (1 = unchanged) around its own brightness.
float3 vivid(float3 c, float s) {
    float l = dot(c, float3(0.299, 0.587, 0.114));
    return max(mix(float3(l), c, s), 0.0);
}

// The cover, very soft and slowly drifting (or, without one, the palette swirling), dimmed by dim.
float3 coverField(float2 uv, float asp, float t, float bass, float dim, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float zoom = 1.7 + 0.08 * sin(t * 0.045) - 0.05 * bass * uIntensity;
    p = rot(0.05 * sin(t * 0.031)) * p / zoom;
    p += (float2(vnoise(p * 2.0 + float2(t * 0.1, 0.0)), vnoise(p * 2.0 + float2(7.3, -t * 0.08))) - 0.5) * 0.1;
    float2 q = p / max(asp, 1.0) + 0.5;
    float3 art = float3(uArt.eval(mirrorUv(q) * uArtSize).rgb);
    float sw = fbm3(uv * 1.4 + float2(t * 0.03, -t * 0.02));
    float3 noArt = mix(BG * 1.4 + A * 0.08, mix(A, S, sw) * 0.5, smoothstep(0.25, 0.8, sw));
    float3 col = mix(noArt, vivid(art, 1.35) * 0.62, uHasArt);
    return mix(col, BG, 0.14) * dim;
}

// The palette as a living gradient: A and S (the cover's colours) flowing round each other with a
// third, hue-shifted colour, brighter on the beat. A colourful base instead of a near-black one.
float3 paletteField(float2 uv, float asp, float t, float lift, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float n1 = fbm3(p * 1.3 + float2(t * 0.05, -t * 0.04));
    float n2 = fbm3(p * 1.7 + float2(-t * 0.035, t * 0.05) + 4.7);
    float3 C = float3(S.z, A.x, (A.y + S.y) * 0.5); // a third colour from the two
    float3 col = mix(A, S, smoothstep(0.25, 0.75, n1));
    col = mix(col, C, smoothstep(0.45, 0.85, n2) * 0.55);
    col = mix(BG, col, 0.42 + 0.18 * lift);
    return col;
}

// The sharp cover at q (0..1 across the square), or the palette when there's no cover yet.
float3 sharpCover(float2 q, float3 A, float3 S) {
    float3 art = float3(uCover.eval(clamp(q, 0.0, 1.0) * uCoverSize).rgb);
    return mix(mix(A, S, q.y), art, uHasArt);
}

// Where the cover's subject sits (x, y, size), with a sensible guess before it's known.
float3 subjectOf() { return uSubject.z > 0.001 ? uSubject : float3(0.5, 0.45, 0.3); }

// Ink of the song label at q (0..1 across the writing area): 0 = paper, 1 = ink.
float labelInk(float2 q) {
    if (q.x < 0.0 || q.x > 1.0 || q.y < 0.0 || q.y > 1.0) return 0.0;
    return float(uLabel.eval(q * uLabelSize).a);
}

// Cover of an earlier song: i = 0 the one before this, 1 the one before that... (wraps round the
// ones there are; with none yet, the current cover in the song's colours instead).
float3 pastCover(float i, float2 q, float3 A, float3 S) {
    q = clamp(q, 0.0, 1.0);
    if (uHistCount < 0.5) return mix(sharpCover(q, A, S), mix(A, S, q.y), 0.35);
    float n = mod(floor(i), uHistCount);
    float2 tile = float2(mod(n, 4.0), floor(n / 4.0));
    float2 p = (tile + 0.01 + q * 0.98) * 192.0;
    return float3(uHistory.eval(p).rgb);
}

// One fan of beams from origin o: brightness of the beams at point p.
float fan(float2 p, float2 o, float centre, float spread, float count, float width, float t, float seed) {
    float2 d = p - o;
    float ang = atan(d.x, -d.y);               // 0 = straight up
    float x = (ang - centre) / spread * count + count * 0.5;
    float id = floor(x);
    float inFan = step(0.0, x) * step(x, count);
    float f = fract(x) - 0.5;
    float r = length(d);
    // Thin in angle, so they widen with distance like real beams.
    float w = width / max(r, 0.05);
    float af = abs(f) / (w * count / spread);
    float beam = exp(-af * 1.2) + 0.22 * exp(-af * 0.12);
    float e = eqAt((id + 0.5) / count);
    return beam * inFan * (0.25 + e) * (0.6 + 0.4 * hash11(id + seed));
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float k = uIntensity;
    float play = uPlaying;
    float bass = uBass * play;
    float kick = exp(-uBeatAge * 9.0) * play;

    float floorY = 0.8;
    // Haze: dark with slow rolling smoke.
    float smoke = fbm(float2(uv.x * 1.3 - t * 0.04, uv.y * 2.2 + t * 0.02));
    float3 col = BG * 0.5 + mix(A, S, 0.5) * 0.04 * smoke;
    col = mix(col, coverField(uv, asp, t, bass, 0.35, BG, A, S), 0.4);

    float2 p = uv;
    bool below = uv.y > floorY;
    if (below) p.y = 2.0 * floorY - uv.y;      // the floor mirrors what's above it

    // Where the beams cross: the equalizer's line, held clear of the floor.
    float meetY = clamp(uWaveY, 0.2, floorY - 0.15);
    float swing = sin(t * 0.55) * 0.35 + sin(t * 0.21) * 0.2 + 0.25 * bass * k * sin(t * 2.3);
    float spread = 0.55 + 0.35 * (0.5 + 0.5 * sin(t * 0.3)) + 0.3 * bass * k;
    float2 oL = float2(asp * 0.12, floorY);
    float2 oR = float2(asp * 0.88, floorY);
    float2 oC = float2(asp * 0.5, floorY + 0.02);
    // The side fans aim at the crossing point, the middle one swings.
    float aimL = atan(asp * 0.5 - oL.x, -(meetY - oL.y));
    float aimR = atan(asp * 0.5 - oR.x, -(meetY - oR.y));
    float bA = fan(p, oL, aimL + swing * 0.5, spread, 7.0, 0.0012, t, 1.0);
    float bB = fan(p, oR, aimR - swing * 0.5, spread, 7.0, 0.0012, t, 9.0);
    float bC = fan(p, oC, swing, spread * 1.3, 9.0, 0.001, t, 5.0);
    // Haze makes them visible; denser smoke, brighter beam.
    float haze = 0.45 + 0.9 * smoke;
    float3 cA = mix(A, float3(1.0), 0.15);
    float3 cB = mix(S, float3(1.0), 0.15);
    float3 cC = mix(A, S, 0.5 + 0.5 * sin(t * 0.4));
    float3 light = (cA * bA + cB * bB + cC * bC * (0.6 + 0.6 * uHigh * play)) * haze * (0.35 + 0.65 * play);
    // Fade towards the far end of each beam.
    light *= smoothstep(-0.05, 0.6, p.y);
    col += light * (1.3 + 1.0 * k);

    // Emitters: hot points with a glow.
    float em = glow(length(p - oL), 0.004) + glow(length(p - oR), 0.004) + glow(length(p - oC), 0.005);
    col += mix(float3(1.0), A, 0.3) * em * 0.35;

    // The strobe on hard kicks, and a wash of the beams' colour with the bass.
    col += float3(1.0) * kick * kick * 0.18 * k * step(0.6, uBass);
    col += mix(A, S, 0.5) * bass * 0.05 * k;

    if (below) {
        // Wet floor: the reflection rippled and darker, plus a glossy line where the stage meets it.
        float rip = vnoise(float2(uv.x * 40.0, uv.y * 120.0 - t * 2.0));
        col = col * (0.35 + 0.15 * rip) + BG * 0.2;
        col += mix(A, S, 0.5) * exp(-(uv.y - floorY) * 160.0) * 0.25;
    }
    // A silhouetted crowd along the stage edge.
    float heads = 0.0;
    float hx = uv.x * 34.0;
    float hid = floor(hx);
    float bob = 0.006 * sin(t * 6.0 + hid * 2.0) * (0.3 + bass);
    float hy = 0.94 - 0.02 * hash11(hid) - bob;
    float hr = 0.012 + 0.005 * hash11(hid + 3.0);
    heads = step(length(float2((fract(hx) - 0.5) / 34.0, uv.y - hy)), hr);
    float shoulders = step(hy + hr * 0.6, uv.y) * step(uv.y, 1.0);
