    private const val VINYL = """
// Vinyl spin: the album's sleeve with the full cover on it, and the record half pulled out of it,
// turning, with the cover as its label (real 12" proportions: the label is a third of the record), in a room washed with
// the cover's own colours. Grooves catch a fixed light (so the sheen stays put while the record turns),
// the record thumps on the kick, the tonearm rides the outer grooves and a ring of light around the
// platter follows the spectrum. Centred where the equalizer is set (uWaveY), sized to its room.
// Shared by the music-reactive scenes (besides "Now playing", which has its own copy): the same
// uniforms NowPlayingScene feeds the music scene - cover, levels, kicks, eight equalizer bands and
// where on screen the visualizer goes - plus the soft cover background.
uniform shader uArt;      // the cover, square and blurred smooth (MusicTheme.softArt)
uniform float2 uArtSize;  // its size in pixels
uniform float uHasArt;    // 0 = no cover yet (or the cover is switched off)
uniform float uBass;      // 0..1, smoothed
uniform float uMid;
uniform float uHigh;
uniform float uBeatAge;   // seconds since the last kick (large = none)
uniform float uPlaying;   // 0..1, fades when paused
uniform float uIntensity; // 0..1, Settings > strength
uniform float4 uEqA;      // bands 0-3 (low), 0..1
uniform float4 uEqB;      // bands 4-7 (high)
uniform float uWaveY;     // 0..1 from the top: where the visualizer sits (Appearance > Equalizer)
uniform float uWaveH;     // room above / below that line (share of the height); the player sits under it
uniform float uWaveX;     // 0..1 from the left: where the visualizer sits across (0 = the middle; the player beside it)
uniform shader uCover;    // the cover, sharp (256 px square) - for the record / disc labels
uniform float2 uCoverSize;
uniform shader uLabel;    // the song's title and artist in dark ink on a clear picture (NowPlayingScene.songLabel)
uniform float2 uLabelSize;
uniform shader uHistory;  // covers of the last songs: a 4 x 2 grid (newest first), MusicTheme.historyAtlas
uniform float uHistCount; // how many of the 8 are filled
uniform float3 uSubject;   // where the cover's subject is: x, y (0..1 across the square) and its size; z = 0 until known (MusicTheme.subject)
// Clocks that only run while the music plays, so spins and scrolls slow down and stop smoothly instead of
// jumping (t * (a + b * level) jumps whenever the level moves). Kept by NowPlayingScene, in seconds:
uniform float uPlayT;     // time spent playing (integral of uPlaying)
uniform float uBassT;     // integral of uBass x uPlaying
uniform float uMidT;      // integral of uMid x uPlaying
uniform float uHighT;     // integral of uHigh x uPlaying

// The visualizer's room, with a sensible size when it isn't set (previews).
float room(float fallback) { return uWaveH > 0.001 ? uWaveH : fallback; }
// Across: the middle, or the left part when the player sits beside the visualizer (MusicPlayerLayout.SIDE).
float waveX(float asp) { return uWaveX > 0.001 ? uWaveX * asp : asp * 0.5; }

float2 mirrorUv(float2 q) { return 1.0 - abs(1.0 - mod(q, 2.0)); }

float eqBand(float i) {
    if (i < 0.5) return uEqA.x;
    if (i < 1.5) return uEqA.y;
    if (i < 2.5) return uEqA.z;
    if (i < 3.5) return uEqA.w;
    if (i < 4.5) return uEqB.x;
    if (i < 5.5) return uEqB.y;
    if (i < 6.5) return uEqB.z;
    return uEqB.w;
}

// The spectrum at m (0 = lowest band, 1 = highest), smoothly interpolated.
float eqAt(float m) {
    float f = clamp(m, 0.0, 1.0) * 7.0;
    float i = floor(f);
    float u = f - i;
    u = u * u * (3.0 - 2.0 * u);
    return mix(eqBand(i), eqBand(min(i + 1.0, 7.0)), u);
}

// Pushes a colour's saturation by s (1 = unchanged) around its own brightness.
float3 vivid(float3 c, float s) {
    float l = dot(c, float3(0.299, 0.587, 0.114));
    return max(mix(float3(l), c, s), 0.0);
}

// The cover, very soft and slowly drifting (or, without one, the palette swirling), dimmed by dim.
float3 coverField(float2 uv, float asp, float t, float bass, float dim, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float zoom = 1.7 + 0.08 * sin(t * 0.045) - 0.05 * bass * uIntensity;
    p = rot(0.05 * sin(t * 0.031)) * p / zoom;
    p += (float2(vnoise(p * 2.0 + float2(t * 0.1, 0.0)), vnoise(p * 2.0 + float2(7.3, -t * 0.08))) - 0.5) * 0.1;
    float2 q = p / max(asp, 1.0) + 0.5;
    float3 art = float3(uArt.eval(mirrorUv(q) * uArtSize).rgb);
    float sw = fbm3(uv * 1.4 + float2(t * 0.03, -t * 0.02));
    float3 noArt = mix(BG * 1.4 + A * 0.08, mix(A, S, sw) * 0.5, smoothstep(0.25, 0.8, sw));
    float3 col = mix(noArt, vivid(art, 1.35) * 0.62, uHasArt);
    return mix(col, BG, 0.14) * dim;
}

// The palette as a living gradient: A and S (the cover's colours) flowing round each other with a
// third, hue-shifted colour, brighter on the beat. A colourful base instead of a near-black one.
float3 paletteField(float2 uv, float asp, float t, float lift, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float n1 = fbm3(p * 1.3 + float2(t * 0.05, -t * 0.04));
    float n2 = fbm3(p * 1.7 + float2(-t * 0.035, t * 0.05) + 4.7);
    float3 C = float3(S.z, A.x, (A.y + S.y) * 0.5); // a third colour from the two
    float3 col = mix(A, S, smoothstep(0.25, 0.75, n1));
    col = mix(col, C, smoothstep(0.45, 0.85, n2) * 0.55);
    col = mix(BG, col, 0.42 + 0.18 * lift);
    return col;
}

// The sharp cover at q (0..1 across the square), or the palette when there's no cover yet.
float3 sharpCover(float2 q, float3 A, float3 S) {
    float3 art = float3(uCover.eval(clamp(q, 0.0, 1.0) * uCoverSize).rgb);
    return mix(mix(A, S, q.y), art, uHasArt);
}

// Where the cover's subject sits (x, y, size), with a sensible guess before it's known.
float3 subjectOf() { return uSubject.z > 0.001 ? uSubject : float3(0.5, 0.45, 0.3); }

// Ink of the song label at q (0..1 across the writing area): 0 = paper, 1 = ink.
float labelInk(float2 q) {
    if (q.x < 0.0 || q.x > 1.0 || q.y < 0.0 || q.y > 1.0) return 0.0;
    return float(uLabel.eval(q * uLabelSize).a);
}

// Cover of an earlier song: i = 0 the one before this, 1 the one before that... (wraps round the
// ones there are; with none yet, the current cover in the song's colours instead).
float3 pastCover(float i, float2 q, float3 A, float3 S) {
    q = clamp(q, 0.0, 1.0);
    if (uHistCount < 0.5) return mix(sharpCover(q, A, S), mix(A, S, q.y), 0.35);
    float n = mod(floor(i), uHistCount);
    float2 tile = float2(mod(n, 4.0), floor(n / 4.0));
    float2 p = (tile + 0.01 + q * 0.98) * 192.0;
    return float3(uHistory.eval(p).rgb);
}

float3 labelArt(float2 q, float3 A, float3 S) {
    // q: -1..1 across the label. The sharp cover, or (no cover) a printed label in the palette.
    float2 c = q * 0.5 + 0.5;
    float3 art = float3(uCover.eval(clamp(c, 0.0, 1.0) * uCoverSize).rgb);
    float r = length(q);
    float3 printed = mix(A, S, c.y) * (0.85 + 0.15 * step(0.55, fract(r * 6.0)));
    return mix(printed, art, uHasArt);
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float px = 1.5 / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float k = uIntensity;
    float play = uPlaying;
    float bass = uBass * play;
    float kick = exp(-uBeatAge * 5.0) * play;
    float lvl = bass * 0.55 + uMid * play * 0.3 + uHigh * play * 0.15;

    // The room: the cover's colours flowing, a soft light from the upper left.
    float3 col = paletteField(uv, asp, t, lvl * k, BG, A, S);
    col = mix(col, coverField(uv, asp, t, bass, 1.0, BG, A, S), 0.35 * uHasArt);
    col += mix(A, float3(1.0), 0.4) * exp(-length(uv - float2(asp * 0.12, -0.1)) * 1.6) * 0.18;

    float2 c0 = float2(waveX(asp), uWaveY);
    float R = room(0.38) * 0.95 * (1.0 + 0.018 * kick * k);
    // The sleeve to the left, the record pulled out to the right (side by side when there's room).
    float wide = step(1.2, asp) * step(R * 3.1, asp * 0.96);
    float2 c = c0 + float2(R * 0.5, 0.0) * wide;
    float2 sc = c0 - float2(R * 0.55, 0.0);
    if (wide > 0.5) {
        float2 sd = uv - sc;
        float side = R * 1.02;
        float sleeveSh = sdRoundBox(sd - float2(0.012, 0.02), float2(side), 0.006);
        col *= 1.0 - 0.45 * (1.0 - smoothstep(-0.01, 0.03, sleeveSh));
        float sleeve = sdRoundBox(sd, float2(side), 0.004);
        if (sleeve < 0.0) {
            float2 q = sd / (2.0 * side) + 0.5;
            float3 sl = sharpCover(q, A, S);
            // Card sleeve: slightly worn edges, a soft sheen from the upper left, ring wear.
            sl *= 0.94 + 0.06 * vnoise(q * 90.0);
            sl += float3(1.0) * 0.07 * smoothstep(0.6, 0.0, length(q - float2(0.15, 0.1)));
            float ringWear = exp(-abs(length(q - float2(0.62, 0.5)) - 0.4) * 160.0) * 0.06;
            sl += float3(1.0) * ringWear;
            col = mix(sl, col, smoothstep(-px, px, sleeve));
        }
        col = mix(col, float3(0.92), (1.0 - smoothstep(0.0, px * 1.5, abs(sleeve))) * 0.35);
    }
    float2 d = uv - c;
    float r = length(d);
    float ang = atan(d.y, d.x);
    float spin = 1.15 * uPlayT; // a touch slower than it used to be

    // Glow behind the platter, swelling with the bass, and a spectrum ring round it.
    col += mix(A, S, 0.5 + 0.5 * sin(t * 0.3)) * exp(-max(r - R, 0.0) * 9.0) * (0.12 + 0.45 * bass * k) * step(R, r);
    float a01 = fract(ang / TAU + 0.25);
    float m = abs(a01 - 0.5) * 2.0;
    float e = eqAt(m) * play;
    float ringR = R * 1.08;
    float ring = exp(-abs(r - ringR - e * R * 0.12 * k) * 260.0);
    col += mix(A, S, m) * ring * (0.35 + 0.9 * e);
    float ticks = step(0.5, fract(a01 * 96.0)) * step(ringR, r) * step(r, ringR + (0.006 + e * 0.07 * k) * R / 0.3);
    col = mix(col, mix(mix(A, S, m), float3(1.0), 0.35), ticks * 0.75);

    // Drop shadow under the record.
    col *= 1.0 - 0.45 * exp(-max(length(d - float2(0.012, 0.018)) - R, 0.0) * 40.0) * step(R, r);

    if (r < R) {
        float rn = r / R;
        float la = ang - spin;
        // Vinyl: near-black with fine grooves, a few wider track gaps, and the fixed light catching them.
        float grooves = 0.5 + 0.5 * sin(r * 1400.0 + hash11(floor(rn * 9.0)) * 6.0);
        float gap = smoothstep(0.0, 0.01, abs(fract(rn * 7.0 + 0.3) - 0.5) - 0.02);
        float3 vinyl = float3(0.035, 0.035, 0.045) + float3(0.02) * grooves * gap;
        // Two broad reflections at a fixed angle (they don't turn with the record), tinted by the room.
        float sheen = pow(abs(cos(ang - 0.7)), 18.0) + 0.6 * pow(abs(cos(ang + 1.2)), 30.0);
        vinyl += mix(float3(1.0), A, 0.35) * sheen * (0.10 + 0.08 * grooves) * smoothstep(0.42, 0.5, rn);
        // A thin colour shimmer moving along the grooves while it plays.
        vinyl += mix(A, S, 0.5 + 0.5 * sin(la * 3.0)) * 0.05 * play * (0.5 + 0.5 * sin(la * 2.0 + rn * 40.0));
        float3 disc = vinyl;
        // Label: the cover, turning with the record.
        float LR = 0.35;
        if (rn < LR) {
            float2 q = float2(cos(la), sin(la)) * (rn / LR);
            float3 lab = labelArt(q, A, S);
            // A little gloss and a darker rim on the label.
            lab *= 0.92 + 0.08 * smoothstep(1.0, 0.85, rn / LR);
            lab += float3(1.0) * pow(abs(cos(ang - 0.7)), 40.0) * 0.08;
            disc = mix(lab, vinyl, smoothstep(LR - 0.006, LR, rn));
        }
        // Spindle.
        disc = mix(float3(0.82), disc, smoothstep(0.022, 0.03, rn));
        disc = mix(BG * 0.3, disc, smoothstep(0.012, 0.018, rn));
        // Outer edge.
        disc = mix(disc, float3(0.18), smoothstep(0.985, 1.0, rn));
        col = disc;
    }

    // Tonearm: from a pivot at the upper right of the platter down onto the outer grooves.
    float2 pivot = c + float2(R * 1.25, -R * 0.95);
    float swing = 0.04 * sin(t * 0.7) * play + 0.02 * kick * k;
    float2 head = c + float2(R * 0.52, -R * 0.62) + float2(swing, swing * 0.5) * R;
    float arm = sdSegment(uv, pivot, head);
    float armW = R * 0.022;
    col *= 1.0 - 0.35 * exp(-max(sdSegment(uv - float2(0.01, 0.015), pivot, head) - armW, 0.0) * 120.0);
    float3 metal = mix(float3(0.55), float3(0.95), 0.5 + 0.5 * sin((uv.x + uv.y) * 40.0));
    col = mix(col, metal, 1.0 - smoothstep(armW - 0.002, armW, arm));
    float hd = length((uv - head) * float2(1.0, 1.4));
    col = mix(col, float3(0.15), 1.0 - smoothstep(R * 0.05, R * 0.055, hd));
    float pv = length(uv - pivot);
    col = mix(col, float3(0.25), 1.0 - smoothstep(R * 0.09, R * 0.095, pv));
    col = mix(col, metal, 1.0 - smoothstep(R * 0.05, R * 0.055, pv));

    // Dust motes drifting through the light.
    col += float3(1.0) * dots(uv, 26.0, float2(t * 0.03, -t * 0.02), 0.12, 0.08, 4.0) * 0.25;

    return half4(finish(col, fc), 1.0);
}
"""

    private const val CD_SPIN = """
// Disc spin: the cover printed on a compact disc spinning in a beam of light. The clear hub and
// the rainbow that a disc throws off stay fixed to the light while the print turns under them; light
// spikes burst outwards with the spectrum and rings roll off on every kick. Colours from the cover.
// Shared by the music-reactive scenes (besides "Now playing", which has its own copy): the same
// uniforms NowPlayingScene feeds the music scene - cover, levels, kicks, eight equalizer bands and
// where on screen the visualizer goes - plus the soft cover background.
uniform shader uArt;      // the cover, square and blurred smooth (MusicTheme.softArt)
uniform float2 uArtSize;  // its size in pixels
uniform float uHasArt;    // 0 = no cover yet (or the cover is switched off)
uniform float uBass;      // 0..1, smoothed
uniform float uMid;
uniform float uHigh;
uniform float uBeatAge;   // seconds since the last kick (large = none)
uniform float uPlaying;   // 0..1, fades when paused
uniform float uIntensity; // 0..1, Settings > strength
uniform float4 uEqA;      // bands 0-3 (low), 0..1
uniform float4 uEqB;      // bands 4-7 (high)
uniform float uWaveY;     // 0..1 from the top: where the visualizer sits (Appearance > Equalizer)
uniform float uWaveH;     // room above / below that line (share of the height); the player sits under it
uniform float uWaveX;     // 0..1 from the left: where the visualizer sits across (0 = the middle; the player beside it)
uniform shader uCover;    // the cover, sharp (256 px square) - for the record / disc labels
uniform float2 uCoverSize;
uniform shader uLabel;    // the song's title and artist in dark ink on a clear picture (NowPlayingScene.songLabel)
uniform float2 uLabelSize;
uniform shader uHistory;  // covers of the last songs: a 4 x 2 grid (newest first), MusicTheme.historyAtlas
uniform float uHistCount; // how many of the 8 are filled
uniform float3 uSubject;   // where the cover's subject is: x, y (0..1 across the square) and its size; z = 0 until known (MusicTheme.subject)
// Clocks that only run while the music plays, so spins and scrolls slow down and stop smoothly instead of
// jumping (t * (a + b * level) jumps whenever the level moves). Kept by NowPlayingScene, in seconds:
uniform float uPlayT;     // time spent playing (integral of uPlaying)
uniform float uBassT;     // integral of uBass x uPlaying
uniform float uMidT;      // integral of uMid x uPlaying
uniform float uHighT;     // integral of uHigh x uPlaying

// The visualizer's room, with a sensible size when it isn't set (previews).
float room(float fallback) { return uWaveH > 0.001 ? uWaveH : fallback; }
// Across: the middle, or the left part when the player sits beside the visualizer (MusicPlayerLayout.SIDE).
float waveX(float asp) { return uWaveX > 0.001 ? uWaveX * asp : asp * 0.5; }

float2 mirrorUv(float2 q) { return 1.0 - abs(1.0 - mod(q, 2.0)); }

float eqBand(float i) {
    if (i < 0.5) return uEqA.x;
    if (i < 1.5) return uEqA.y;
    if (i < 2.5) return uEqA.z;
    if (i < 3.5) return uEqA.w;
    if (i < 4.5) return uEqB.x;
    if (i < 5.5) return uEqB.y;
    if (i < 6.5) return uEqB.z;
    return uEqB.w;
}

// The spectrum at m (0 = lowest band, 1 = highest), smoothly interpolated.
float eqAt(float m) {
    float f = clamp(m, 0.0, 1.0) * 7.0;
    float i = floor(f);
    float u = f - i;
    u = u * u * (3.0 - 2.0 * u);
    return mix(eqBand(i), eqBand(min(i + 1.0, 7.0)), u);
}

// Pushes a colour's saturation by s (1 = unchanged) around its own brightness.
float3 vivid(float3 c, float s) {
    float l = dot(c, float3(0.299, 0.587, 0.114));
    return max(mix(float3(l), c, s), 0.0);
}

// The cover, very soft and slowly drifting (or, without one, the palette swirling), dimmed by dim.
float3 coverField(float2 uv, float asp, float t, float bass, float dim, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float zoom = 1.7 + 0.08 * sin(t * 0.045) - 0.05 * bass * uIntensity;
    p = rot(0.05 * sin(t * 0.031)) * p / zoom;
    p += (float2(vnoise(p * 2.0 + float2(t * 0.1, 0.0)), vnoise(p * 2.0 + float2(7.3, -t * 0.08))) - 0.5) * 0.1;
    float2 q = p / max(asp, 1.0) + 0.5;
    float3 art = float3(uArt.eval(mirrorUv(q) * uArtSize).rgb);
    float sw = fbm3(uv * 1.4 + float2(t * 0.03, -t * 0.02));
    float3 noArt = mix(BG * 1.4 + A * 0.08, mix(A, S, sw) * 0.5, smoothstep(0.25, 0.8, sw));
    float3 col = mix(noArt, vivid(art, 1.35) * 0.62, uHasArt);
    return mix(col, BG, 0.14) * dim;
}

// The palette as a living gradient: A and S (the cover's colours) flowing round each other with a
// third, hue-shifted colour, brighter on the beat. A colourful base instead of a near-black one.
float3 paletteField(float2 uv, float asp, float t, float lift, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float n1 = fbm3(p * 1.3 + float2(t * 0.05, -t * 0.04));
    float n2 = fbm3(p * 1.7 + float2(-t * 0.035, t * 0.05) + 4.7);
    float3 C = float3(S.z, A.x, (A.y + S.y) * 0.5); // a third colour from the two
    float3 col = mix(A, S, smoothstep(0.25, 0.75, n1));
    col = mix(col, C, smoothstep(0.45, 0.85, n2) * 0.55);
    col = mix(BG, col, 0.42 + 0.18 * lift);
    return col;
}

// The sharp cover at q (0..1 across the square), or the palette when there's no cover yet.
float3 sharpCover(float2 q, float3 A, float3 S) {
    float3 art = float3(uCover.eval(clamp(q, 0.0, 1.0) * uCoverSize).rgb);
    return mix(mix(A, S, q.y), art, uHasArt);
}

// Where the cover's subject sits (x, y, size), with a sensible guess before it's known.
float3 subjectOf() { return uSubject.z > 0.001 ? uSubject : float3(0.5, 0.45, 0.3); }

// Ink of the song label at q (0..1 across the writing area): 0 = paper, 1 = ink.
float labelInk(float2 q) {
    if (q.x < 0.0 || q.x > 1.0 || q.y < 0.0 || q.y > 1.0) return 0.0;
    return float(uLabel.eval(q * uLabelSize).a);
}

// Cover of an earlier song: i = 0 the one before this, 1 the one before that... (wraps round the
// ones there are; with none yet, the current cover in the song's colours instead).
float3 pastCover(float i, float2 q, float3 A, float3 S) {
    q = clamp(q, 0.0, 1.0);
    if (uHistCount < 0.5) return mix(sharpCover(q, A, S), mix(A, S, q.y), 0.35);
    float n = mod(floor(i), uHistCount);
    float2 tile = float2(mod(n, 4.0), floor(n / 4.0));
    float2 p = (tile + 0.01 + q * 0.98) * 192.0;
    return float3(uHistory.eval(p).rgb);
}

float3 hue3(float h) {
    return clamp(abs(fract(h + float3(0.0, 0.6667, 0.3333)) * 6.0 - 3.0) - 1.0, 0.0, 1.0);
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float k = uIntensity;
    float play = uPlaying;
    float bass = uBass * play;
    float high = uHigh * play;
    float kick = exp(-uBeatAge * 5.0) * play;
    float lvl = bass * 0.5 + uMid * play * 0.3 + high * 0.2;

    float3 col = paletteField(uv, asp, t, lvl * k, BG, A, S);
    float2 c = float2(waveX(asp), uWaveY);
    float R = room(0.28) * 0.9;
    float2 d = uv - c;
    float r = length(d);
    float ang = atan(d.y, d.x);
    float a01 = fract(ang / TAU + 0.25);

    // Diagonal beams of light through the room.
    float beam = sin((uv.x - uv.y * 0.6) * 5.0 - t * 0.3);
    col += mix(A, float3(1.0), 0.5) * smoothstep(0.75, 1.0, beam) * 0.08;

    // Light spikes round the disc, following the spectrum (bass at the top, mirrored).
    float m = abs(a01 - 0.5) * 2.0;
    float e = eqAt(m) * play;
    float N = 64.0;
    float fa = fract(a01 * N);
    float spikeLen = R * (0.08 + 0.55 * e * (0.5 + 0.5 * k));
    float spike = (1.0 - smoothstep(0.0, 0.35, abs(fa - 0.5))) * step(R * 1.04, r) * (1.0 - smoothstep(R * 1.04 + spikeLen * 0.6, R * 1.04 + spikeLen, r));
    float3 sc = hue3(a01 + t * 0.05) * 0.5 + mix(A, S, m) * 0.6;
    col += sc * spike * (0.4 + 0.6 * e);
    col += mix(A, S, 0.5) * exp(-max(r - R, 0.0) * 8.0) * (0.1 + 0.4 * bass * k);
    // Rings rolling off on the kick.
    float rr = R + uBeatAge * 0.5;
    col += mix(S, float3(1.0), 0.3) * exp(-abs(r - rr) * 90.0) * exp(-uBeatAge * 2.5) * 0.6 * k * play;
    // Shadow.
    col *= 1.0 - 0.4 * exp(-max(length(d - float2(0.01, 0.016)) - R, 0.0) * 45.0) * step(R, r);

    if (r < R) {
        float rn = r / R;
        float spin = 3.3 * uPlayT + t * 0.16; // a little slower than before: still clearly a disc spinning, easier on the eye
        float la = ang - spin;
        // The print: the cover, turning.
        float2 q = float2(cos(la), sin(la)) * rn;
        float3 print = mix(mix(A, S, q.y * 0.5 + 0.5), float3(1.0), 0.1);
        float3 art = float3(uCover.eval(clamp(q * 0.5 + 0.5, 0.0, 1.0) * uCoverSize).rgb);
        print = mix(print, art, uHasArt);
        // The rainbow: fixed to the light (ang), not to the print; strongest along two opposite bands.
        float band = pow(abs(cos(ang - 0.6 + 0.08 * sin(t * 0.5))), 6.0);
        float3 rainbow = hue3(rn * 1.2 + 0.1 * sin(t * 0.2) + 0.15 * cos(ang - 0.6));
        float3 disc = mix(print, rainbow, 0.06 + 0.32 * band);
        disc += float3(1.0) * pow(band, 8.0) * 0.35;
        // Silver data edge and the clear hub.
        disc = mix(disc, mix(float3(0.85), rainbow, 0.4), smoothstep(0.96, 0.975, rn));
        float hub = smoothstep(0.30, 0.31, rn);
        float3 clear = mix(col * 0.75 + float3(0.12), rainbow * 0.4 + 0.4, 0.3 * smoothstep(0.18, 0.3, rn));
        disc = mix(clear, disc, hub);
        disc = mix(disc, float3(0.9), (1.0 - smoothstep(0.0, 0.006, abs(rn - 0.305))) * 0.6);
        disc = mix(col * 0.6, disc, smoothstep(0.12, 0.13, rn)); // the hole
        disc = mix(disc, float3(0.95), (1.0 - smoothstep(0.0, 0.004, abs(rn - 0.995))) * 0.7);
        col = disc;
    }

    // Glints flying off with the highs.
    col += float3(1.0) * dots(uv, 34.0, float2(-t * 0.06, t * 0.03), 0.1, 0.07, 9.0) * (0.15 + 0.6 * high * k);
    return half4(finish(col, fc), 1.0);
}
"""

    private const val LAVA = """
