float3 tileColor(float h, float3 A, float3 S, float3 C) {
    return h < 0.33 ? A : (h < 0.66 ? S : C);
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float3 C = float3(S.z, A.x, (A.y + S.y) * 0.5);
    float k = uIntensity;
    float play = uPlaying;
    float bass = uBass * play;
    float high = uHigh * play;
    float kick = exp(-uBeatAge * 4.0) * play;
    float lvl = bass * 0.5 + uMid * play * 0.3 + high * 0.2;
    // A beat counter that steps on every kick (simulated: 112 bpm), for the floor's patterns.
    float beatN = floor(t * 112.0 / 60.0);

    float hz = clamp(uWaveY + room(0.16) * 0.2, 0.3, 0.75);
    float3 col;
    if (uv.y < hz) {
        // The room: a deep haze tinted by the cover, brighter near the floor.
        float v = uv.y / hz;
        col = mix(BG * 1.2, mix(BG, mix(A, S, 0.5), 0.45), pow(v, 1.5));
        col = mix(col, coverField(uv, asp, t, bass, 0.9, BG, A, S), 0.35 * uHasArt);
        // Spotlights from the ceiling, sweeping.
        for (int i = 0; i < 4; i++) {
            float fi = float(i);
            float2 o = float2(asp * (0.15 + 0.23 * fi), -0.02);
            float a = 0.5 * sin(t * (0.35 + 0.1 * fi) + fi * 1.7);
            float2 dir = float2(sin(a), cos(a));
            float2 p = uv - o;
            float along = dot(p, dir);
            float across = abs(p.x * dir.y - p.y * dir.x);
            float cone = (1.0 - smoothstep(0.0, 0.05 + along * 0.22, across)) * step(0.0, along);
            col += tileColor(fract(fi * 0.37 + 0.1), A, S, C) * cone * (0.10 + 0.25 * lvl * k) * exp(-along * 0.8);
        }
        // Mirror ball.
        float2 mb = float2(asp * 0.5, 0.11);
        float mr = 0.085;
        float2 dm = uv - mb;
        float dl = length(dm);
        if (dl < mr) {
            float2 q = dm / mr;
            float z = sqrt(max(1.0 - dot(q, q), 0.0));
            float lon = atan(q.x, z) + t * 0.6;
            float lat = asin(clamp(q.y, -1.0, 1.0));
            float2 facet = float2(floor(lon * 6.0), floor(lat * 6.0));
            float fl = hash12(facet + floor(t * 3.0));
            float3 ball = float3(0.55) * (0.4 + 0.6 * z) + float3(1.0) * step(0.86, fl) * (0.5 + 0.5 * high);
            ball *= 0.75 + 0.25 * step(0.08, fract(lon * 6.0 / TAU * 6.0)) * step(0.08, fract(lat * 6.0 / PI * 6.0));
            col = ball;
        }
        col = mix(col, float3(0.6), (1.0 - smoothstep(0.0, 0.0025, abs(uv.x - mb.x))) * step(uv.y, mb.y - mr));
        // Specks of light thrown round the room, turning with the ball.
        float2 sp = float2(uv.x * 14.0 + t * 0.9, uv.y * 14.0);
        float2 sid = floor(sp);
        float2 sh = hash22(sid);
        float speck = step(sh.x, 0.25) * (1.0 - smoothstep(0.04, 0.12, length(fract(sp) - 0.5 - (sh - 0.5) * 0.5)));
        col += mix(float3(1.0), tileColor(sh.y, A, S, C), 0.5) * speck * (0.2 + 0.5 * high * k) * (0.4 + 0.6 * uv.y / hz);
    } else {
        // The floor: perspective tiles.
        float dy = uv.y - hz;
        float z = 0.35 / max(dy, 0.002);
        float fx = (uv.x - asp * 0.5) * z;
        float2 tp = float2(fx * 1.6, z * 1.6 + 0.4 * uPlayT);
        float2 tid = floor(tp);
        float2 tf = fract(tp);
        float h = hash12(tid + beatN * 7.13);
        float m = clamp(abs(fx) / (asp * 1.8) , 0.0, 1.0);
        float e = eqAt(m) * play;
        float on = step(h, 0.42 + 0.45 * e * k);
        float3 tc = tileColor(hash12(tid + 3.7 + beatN), A, S, C);
        float edge = smoothstep(0.0, 0.06, tf.x) * smoothstep(0.0, 0.06, tf.y) * smoothstep(0.0, 0.06, 1.0 - tf.x) * smoothstep(0.0, 0.06, 1.0 - tf.y);
        float fade = exp(-z * 0.12);
        float3 floorCol = mix(BG, mix(A, S, 0.5), 0.18) * 1.3 + tc * on * edge * (0.55 + 0.7 * kick * k + 0.3 * e);
        floorCol += tc * on * 0.12;
        // Reflections of the room's light in the glossy floor near the horizon.
        floorCol += mix(A, S, 0.5) * exp(-dy * 10.0) * 0.25;
        col = mix(mix(BG, A, 0.2), floorCol, fade * 0.85 + 0.15);
        col += float3(1.0) * exp(-dy * 120.0) * 0.25;
    }
    return half4(finish(col, fc), 1.0);
}
"""

    private const val SPEAKER = """
// Bass cones: two big loudspeakers whose cones pump with the bass (the rings of the cone stretch
// and the dust cap shines as it pushes out), tweeters flickering with the highs, and shock rings
// thrown out on every kick, all in the cover's colours over a speaker-grille wall.
// Shared by the music-reactive scenes (besides "Now playing", which has its own copy): the same
// uniforms NowPlayingScene feeds the music scene - cover, levels, kicks, eight equalizer bands and
// where on screen the visualizer goes - plus the soft cover background.
uniform shader uArt;      // the cover, square and blurred smooth (MusicTheme.softArt)
uniform float2 uArtSize;  // its size in pixels
uniform float uHasArt;    // 0 = no cover yet (or the cover is switched off)
uniform float uBass;      // 0..1, smoothed
uniform float uMid;
uniform float uHigh;
uniform float uBeatAge;   // seconds since the last kick (large = none)
uniform float uPlaying;   // 0..1, fades when paused
uniform float uIntensity; // 0..1, Settings > strength
uniform float4 uEqA;      // bands 0-3 (low), 0..1
uniform float4 uEqB;      // bands 4-7 (high)
uniform float uWaveY;     // 0..1 from the top: where the visualizer sits (Appearance > Equalizer)
uniform float uWaveH;     // room above / below that line (share of the height); the player sits under it
uniform float uWaveX;     // 0..1 from the left: where the visualizer sits across (0 = the middle; the player beside it)
uniform shader uCover;    // the cover, sharp (256 px square) - for the record / disc labels
uniform float2 uCoverSize;
uniform shader uLabel;    // the song's title and artist in dark ink on a clear picture (NowPlayingScene.songLabel)
uniform float2 uLabelSize;
uniform shader uHistory;  // covers of the last songs: a 4 x 2 grid (newest first), MusicTheme.historyAtlas
uniform float uHistCount; // how many of the 8 are filled
uniform float3 uSubject;   // where the cover's subject is: x, y (0..1 across the square) and its size; z = 0 until known (MusicTheme.subject)
// Clocks that only run while the music plays, so spins and scrolls slow down and stop smoothly instead of
// jumping (t * (a + b * level) jumps whenever the level moves). Kept by NowPlayingScene, in seconds:
uniform float uPlayT;     // time spent playing (integral of uPlaying)
uniform float uBassT;     // integral of uBass x uPlaying
uniform float uMidT;      // integral of uMid x uPlaying
uniform float uHighT;     // integral of uHigh x uPlaying

// The visualizer's room, with a sensible size when it isn't set (previews).
float room(float fallback) { return uWaveH > 0.001 ? uWaveH : fallback; }
// Across: the middle, or the left part when the player sits beside the visualizer (MusicPlayerLayout.SIDE).
float waveX(float asp) { return uWaveX > 0.001 ? uWaveX * asp : asp * 0.5; }

float2 mirrorUv(float2 q) { return 1.0 - abs(1.0 - mod(q, 2.0)); }

float eqBand(float i) {
    if (i < 0.5) return uEqA.x;
    if (i < 1.5) return uEqA.y;
    if (i < 2.5) return uEqA.z;
    if (i < 3.5) return uEqA.w;
    if (i < 4.5) return uEqB.x;
    if (i < 5.5) return uEqB.y;
    if (i < 6.5) return uEqB.z;
    return uEqB.w;
}

// The spectrum at m (0 = lowest band, 1 = highest), smoothly interpolated.
float eqAt(float m) {
    float f = clamp(m, 0.0, 1.0) * 7.0;
    float i = floor(f);
    float u = f - i;
    u = u * u * (3.0 - 2.0 * u);
    return mix(eqBand(i), eqBand(min(i + 1.0, 7.0)), u);
}

// Pushes a colour's saturation by s (1 = unchanged) around its own brightness.
float3 vivid(float3 c, float s) {
    float l = dot(c, float3(0.299, 0.587, 0.114));
    return max(mix(float3(l), c, s), 0.0);
}

// The cover, very soft and slowly drifting (or, without one, the palette swirling), dimmed by dim.
float3 coverField(float2 uv, float asp, float t, float bass, float dim, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float zoom = 1.7 + 0.08 * sin(t * 0.045) - 0.05 * bass * uIntensity;
    p = rot(0.05 * sin(t * 0.031)) * p / zoom;
    p += (float2(vnoise(p * 2.0 + float2(t * 0.1, 0.0)), vnoise(p * 2.0 + float2(7.3, -t * 0.08))) - 0.5) * 0.1;
    float2 q = p / max(asp, 1.0) + 0.5;
    float3 art = float3(uArt.eval(mirrorUv(q) * uArtSize).rgb);
    float sw = fbm3(uv * 1.4 + float2(t * 0.03, -t * 0.02));
    float3 noArt = mix(BG * 1.4 + A * 0.08, mix(A, S, sw) * 0.5, smoothstep(0.25, 0.8, sw));
    float3 col = mix(noArt, vivid(art, 1.35) * 0.62, uHasArt);
    return mix(col, BG, 0.14) * dim;
}

// The palette as a living gradient: A and S (the cover's colours) flowing round each other with a
// third, hue-shifted colour, brighter on the beat. A colourful base instead of a near-black one.
float3 paletteField(float2 uv, float asp, float t, float lift, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float n1 = fbm3(p * 1.3 + float2(t * 0.05, -t * 0.04));
    float n2 = fbm3(p * 1.7 + float2(-t * 0.035, t * 0.05) + 4.7);
    float3 C = float3(S.z, A.x, (A.y + S.y) * 0.5); // a third colour from the two
    float3 col = mix(A, S, smoothstep(0.25, 0.75, n1));
    col = mix(col, C, smoothstep(0.45, 0.85, n2) * 0.55);
    col = mix(BG, col, 0.42 + 0.18 * lift);
    return col;
}

// The sharp cover at q (0..1 across the square), or the palette when there's no cover yet.
float3 sharpCover(float2 q, float3 A, float3 S) {
    float3 art = float3(uCover.eval(clamp(q, 0.0, 1.0) * uCoverSize).rgb);
    return mix(mix(A, S, q.y), art, uHasArt);
}

// Where the cover's subject sits (x, y, size), with a sensible guess before it's known.
float3 subjectOf() { return uSubject.z > 0.001 ? uSubject : float3(0.5, 0.45, 0.3); }

// Ink of the song label at q (0..1 across the writing area): 0 = paper, 1 = ink.
float labelInk(float2 q) {
    if (q.x < 0.0 || q.x > 1.0 || q.y < 0.0 || q.y > 1.0) return 0.0;
    return float(uLabel.eval(q * uLabelSize).a);
}

// Cover of an earlier song: i = 0 the one before this, 1 the one before that... (wraps round the
// ones there are; with none yet, the current cover in the song's colours instead).
float3 pastCover(float i, float2 q, float3 A, float3 S) {
    q = clamp(q, 0.0, 1.0);
    if (uHistCount < 0.5) return mix(sharpCover(q, A, S), mix(A, S, q.y), 0.35);
    float n = mod(floor(i), uHistCount);
    float2 tile = float2(mod(n, 4.0), floor(n / 4.0));
    float2 p = (tile + 0.01 + q * 0.98) * 192.0;
    return float3(uHistory.eval(p).rgb);
}

float3 cone(float2 p, float R, float push, float t, float3 A, float3 S, float3 BG) {
    float r = length(p) / R;
    // Surround (rubber edge), cone with ribs, dust cap.
    float3 col = BG * 0.4;
    float surround = smoothstep(0.80, 0.84, r) * (1.0 - smoothstep(0.97, 1.0, r));
    float rib = 0.5 + 0.5 * sin(r * 60.0 - push * 18.0);
    float3 coneCol = mix(float3(0.08), mix(A, S, r) * 0.35, 0.6) * (0.7 + 0.3 * rib);
    // Light from the upper left; the cone's slope steepens as it pushes out.
    float2 n = normalize(p + 1e-5);
    float lit = 0.5 + 0.5 * dot(n, normalize(float2(-0.6, -0.8))) * (0.5 + push);
    coneCol *= 0.6 + 0.6 * lit;
    col = coneCol;
    float3 sur = float3(0.12) + mix(A, S, 0.5) * 0.15 * (0.5 + 0.5 * sin(atan(p.y, p.x) * 2.0 + 1.0));
    col = mix(col, sur * (0.8 + 0.4 * lit), surround);
    // Chrome ring and coloured light ring.
    col = mix(col, float3(0.75), (1.0 - smoothstep(0.0, 0.015, abs(r - 0.985))) * 0.8);
    col += A * (1.0 - smoothstep(0.0, 0.02, abs(r - 1.03))) * (0.5 + push * 1.5);
    // Dust cap.
    float cap = 1.0 - smoothstep(0.26, 0.27, r);
    float3 capCol = mix(float3(0.1), S * 0.6, 0.4) + float3(1.0) * sqf(sat(1.0 - length(p / R + float2(0.08, 0.1)) * 4.0)) * (0.25 + 0.6 * push);
    col = mix(col, capCol, cap);
    return col * step(r, 1.06) + float3(0.0) * (1.0 - step(r, 1.06));
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float k = uIntensity;
    float play = uPlaying;
    float bass = uBass * play;
    float high = uHigh * play;
    float kick = exp(-uBeatAge * 6.0) * play;
    float lvl = bass * 0.5 + uMid * play * 0.3 + high * 0.2;

    float3 col = paletteField(uv, asp, t, lvl * k, BG, A, S) * 0.7;
    // Grille: a field of small holes.
    float2 gp = uv * 70.0;
    float2 gf = fract(gp + float2(0.5 * step(0.5, fract(floor(gp.y) * 0.5)), 0.0)) - 0.5;
    col *= 0.82 + 0.18 * smoothstep(0.18, 0.28, length(gf));

    float R = room(0.24) * 0.95;
    float gap = R * 1.25;
    float2 c = float2(waveX(asp), uWaveY);
    float push = (0.6 * bass + 0.6 * kick) * (0.4 + 0.6 * k);
    float scale = 1.0 + 0.04 * push;
    float2 cl = c - float2(gap, 0.0);
    float2 cr = c + float2(gap, 0.0);
    // Shock rings from both cones on the kick.
    float age = uBeatAge;
    float ringR = R * (1.05 + age * 1.6);
    float sh = exp(-age * 2.6) * play * k;
    col += mix(A, float3(1.0), 0.3) * (exp(-abs(length(uv - cl) - ringR) * 80.0) + exp(-abs(length(uv - cr) - ringR) * 80.0)) * sh * 0.5;
    // Light pooling round the speakers.
    col += mix(A, S, 0.5) * (exp(-length(uv - cl) / R * 1.5) + exp(-length(uv - cr) / R * 1.5)) * (0.06 + 0.25 * bass * k);

    float dl = length(uv - cl);
    float dr = length(uv - cr);
    if (dl < R * 1.06 * scale) col = cone((uv - cl) / scale, R, push, t, A, S, BG);
    if (dr < R * 1.06 * scale) col = cone((uv - cr) / scale, R, push, t, S, A, BG);

    // Tweeters between them, flickering with the highs; a spectrum strip of LEDs under them.
    float2 tw = c - float2(0.0, R * 0.45);
    float td = length(uv - tw) / (R * 0.22);
    if (td < 1.0) {
        col = mix(float3(0.06), mix(S, float3(1.0), 0.4) * (0.3 + 0.9 * high * k), 1.0 - smoothstep(0.35, 0.45, td));
        col = mix(col, float3(0.7), 1.0 - smoothstep(0.0, 0.08, abs(td - 0.9)));
    }
    float2 lp = uv - (c + float2(0.0, R * 0.35));
    float lx = lp.x / (R * 0.7) * 0.5 + 0.5;
    if (abs(lp.y) < R * 0.18 && lx > 0.0 && lx < 1.0) {
        float id = floor(lx * 8.0);
        float e = eqBand(id) * play;
        float seg = floor((R * 0.18 - lp.y) / (R * 0.36) * 6.0) / 6.0;
        float led = step(seg, e) * step(0.15, fract(lx * 8.0)) * step(fract(lx * 8.0), 0.85) * step(0.2, fract((R * 0.18 - lp.y) / (R * 0.36) * 6.0));
        col = mix(col * 0.6, mix(mix(A, S, id / 7.0), float3(1.0, 0.3, 0.2), step(0.8, seg)), led);
    }
    return half4(finish(col, fc), 1.0);
}
"""

    private const val ERA_8BIT = """
// 8-bit quest: a chunky pixel world scrolling by like an 8-bit platformer's attract mode - banded
// sky, a blocky sun, puffy pixel clouds, two rows of hills at their own speeds, a brick ground with
// floating gem blocks and spinning coins. Every layer snaps to a coarse pixel grid; a short palette.
float bayer2(float2 a) { a = floor(a); return fract(a.x / 2.0 + a.y * a.y * 0.75); }

half4 main(float2 fc) {
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    // ~96 "pixels" from top to bottom.
    float P = 96.0;
    float2 g = floor(fc / uRes.y * P);
    float2 uv = g / P;
    float x = uv.x;
    float y = uv.y;

    // Sky in four flat bands, dithered at the seams.
    float sk = y / 0.72;
    float band = floor(sk * 4.0 + bayer2(g) * 0.9);
    float3 sky0 = float3(0.12, 0.16, 0.42);
    float3 sky1 = float3(0.22, 0.38, 0.85);
    float3 col = mix(sky0, sky1, band / 3.0);
    col = mix(col, BG * 2.0 + sky0 * 0.5, 0.15);

    // Blocky sun.
    float2 sc = float2(asp * 0.78, 0.2);
    float sd = max(abs(uv.x - sc.x), abs(uv.y - sc.y)) * 0.75 + length(uv - sc) * 0.25;
    col = mix(col, float3(1.0, 0.86, 0.35), step(sd, 0.075));
    col = mix(col, float3(1.0, 0.97, 0.75), step(sd, 0.05));

    // Clouds: puffs of rounded blocks drifting left.
    float cx = x + t * 0.025;
    float cid = floor(cx / 0.55);
    float cf = cx - cid * 0.55;
    float ch = hash11(cid * 3.7);
    float cy = 0.12 + 0.18 * ch;
    float2 cp = float2(cf - 0.27, y - cy);
    float cloud = step(length(cp * float2(1.0, 2.2)), 0.11) + step(length((cp - float2(-0.07, 0.015)) * float2(1.3, 1.9)), 0.07) + step(length((cp - float2(0.08, 0.02)) * float2(1.3, 2.0)), 0.07);
    float3 cloudCol = mix(float3(1.0), float3(0.75, 0.85, 1.0), step(0.02, cp.y));
    col = mix(col, cloudCol, step(0.5, cloud) * step(0.3, ch));

    // Far hills (slow) and near hills (faster), stepped.
    float hx1 = x + t * 0.04;
    float h1 = 0.58 - 0.08 * abs(sin(hx1 * 4.0)) - 0.04 * abs(sin(hx1 * 9.0 + 1.0));
    col = mix(col, float3(0.10, 0.45, 0.42), step(h1, y));
    float hx2 = x + t * 0.09;
    float hh = fract(hx2 * 2.2);
    float h2 = 0.70 - 0.1 * (1.0 - abs(hh - 0.5) * 2.0) * step(0.35, hash11(floor(hx2 * 2.2)));
    float3 hill2 = mix(float3(0.18, 0.72, 0.30), float3(0.10, 0.52, 0.22), step(0.5, fract(g.x * 0.25 + g.y * 0.25)) * 0.4);
    col = mix(col, hill2, step(h2, y));
    // Little bushes.
    float bx = fract(hx2 * 5.0);
    col = mix(col, float3(0.30, 0.85, 0.35), step(0.7, y) * step(y, 0.72) * step(0.2, bx) * step(bx, 0.5));

    // Ground: bricks scrolling at the ground speed.
    float gx = x + t * 0.16;
    float gy = 0.78;
    if (y >= gy) {
        float2 bp = float2(gx * 12.0, (y - gy) * 24.0);
        float row = floor(bp.y);
        float2 bf = fract(bp + float2(0.5 * step(0.5, fract(row * 0.5)), 0.0));
        float mortar = step(bf.x, 0.08) + step(bf.y, 0.15);
        float3 brick = mix(A * 0.9 + float3(0.15, 0.05, 0.0), float3(0.15, 0.08, 0.06), step(0.5, mortar));
        col = mix(brick, float3(0.95, 0.7, 0.4), step(y, gy + 1.0 / P) * 0.7);
    }

    // Floating gem blocks and coins on the ground's layer.
    float bxw = gx * 3.0;
    float bid = floor(bxw);
    float bfr = fract(bxw);
    float hasBlock = step(0.55, hash11(bid * 5.3));
    float by = 0.56 - 0.06 * step(0.5, hash11(bid * 1.9));
    float2 bq = float2(bfr - 0.5, y - by);
    float blk = step(abs(bq.x) * 3.0, 0.11) * step(abs(bq.y), 0.036);
    float bump = sin(t * 3.0 + bid) * 0.004;
    if (blk * hasBlock > 0.5) {
        float edge = step(abs(bq.x) * 3.0, 0.09) * step(abs(bq.y), 0.026);
        float3 bc = mix(S * 0.6, S, edge);
        // A blinking gem in the middle.
        bc = mix(bc, mix(float3(1.0), A, 0.3), step(length(bq * float2(3.0, 1.0)), 0.012) * step(0.5, fract(t * 1.5 + bid * 0.3)));
        col = bc;
    }
    float cxw = gx * 6.0;
    float cidx = floor(cxw);
    float coin = step(0.45, hash11(cidx * 2.1 + 7.0));
    float spin = abs(cos(t * 3.0 + cidx));
    float2 cq = float2((fract(cxw) - 0.5) / max(spin, 0.25), y - (0.72 + bump * 0.0));
    float cd = length(cq * float2(1.0 / 6.0, 1.0) * float2(6.0, 1.0));
    float coinShape = step(length(float2(cq.x * 0.16, cq.y)), 0.022) * coin;
    col = mix(col, mix(float3(1.0, 0.8, 0.2), float3(1.0, 0.97, 0.7), step(cq.x, -0.5)), coinShape);

    // A faint scanline every other pixel row, like a CRT.
    col *= 0.93 + 0.07 * step(0.5, fract(fc.y * 0.5));
    return half4(finish(col, fc), 1.0);
}
"""

    private const val MODE7 = """
// 16-bit mode 7: a racetrack sweeping under you on a rotating, scaled floor - checkered grass, a road
// with red-and-white kerbs and a dashed line - under a sky with two parallax mountain ranges and
// stepped clouds. Drawn at a 16-bit-ish resolution with a horizon haze.
half4 main(float2 fc) {
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float P = 224.0;
    float2 g = floor(fc / uRes.y * P) + 0.5;
    float2 uv = g / P;
    float hz = 0.46;
    float turn = 0.35 * sin(t * 0.11);
    float3 col;
    if (uv.y < hz) {
        float k = uv.y / hz;
        col = mix(float3(0.18, 0.22, 0.62), mix(float3(0.98, 0.55, 0.45), A, 0.35), pow(k, 1.6));
        col = mix(col, BG * 1.5, 0.1);
        // Stepped cloud bands.
        float cb = step(0.6, fbm3(float2((uv.x + t * 0.01 + turn * 0.3) * 4.0, floor(uv.y * 40.0) * 0.3)));
        col = mix(col, float3(1.0, 0.92, 0.9), cb * 0.5 * (1.0 - k));
        // Far mountains (move with the turn), near mountains (move more).
        float mx1 = uv.x * 2.2 + turn * 1.2;
        float m1 = hz - 0.13 * pow(abs(sin(mx1 * 1.3)), 0.8) - 0.05 * abs(sin(mx1 * 4.1));
        col = mix(col, mix(S, float3(0.35, 0.3, 0.6), 0.6), step(m1, uv.y));
        float mx2 = uv.x * 3.0 + turn * 2.4 + 7.0;
        float m2 = hz - 0.07 * abs(sin(mx2 * 1.7)) - 0.03 * abs(sin(mx2 * 5.3));
        col = mix(col, float3(0.20, 0.30, 0.45), step(m2, uv.y));
    } else {
        // The mode-7 plane: rotate and scale by distance.
        float dy = uv.y - hz;
        float z = 0.18 / dy;
        float2 p = float2((uv.x - asp * 0.5) * z, z);
        float c = cos(turn);
        float s = sin(turn);
        p = float2(p.x * c - p.y * s, p.x * s + p.y * c);
        p.y += t * 2.2;
        // The road curves through the world.
        float roadX = 1.2 * sin(p.y * 0.08) + 0.6 * sin(p.y * 0.031 + 2.0);
        float dx = p.x - roadX;
        float roadW = 0.55;
        float checker = step(0.5, fract(floor(p.x * 1.5) * 0.5 + floor(p.y * 1.5) * 0.5));
        float3 grass = mix(float3(0.16, 0.55, 0.22), float3(0.12, 0.45, 0.18), checker);
        col = grass;
        float onRoad = step(abs(dx), roadW);
        float3 road = float3(0.32, 0.32, 0.38);
        // Dashed centre line and kerbs.
        road = mix(road, float3(0.95), step(abs(dx), 0.03) * step(0.5, fract(p.y * 0.8)));
        col = mix(col, road, onRoad);
        float kerb = step(roadW, abs(dx)) * step(abs(dx), roadW + 0.12);
        col = mix(col, mix(float3(0.92, 0.18, 0.16), float3(0.96), step(0.5, fract(p.y * 1.6))), kerb);
        // Boost pads in the accent colour.
        float pad = step(abs(dx - 0.25 * sin(floor(p.y * 0.25) * 2.0)), 0.12) * step(0.85, fract(p.y * 0.25)) * onRoad;
        col = mix(col, mix(A, float3(1.0), 0.3 + 0.3 * step(0.5, fract(t * 4.0))), pad);
        // Haze towards the horizon.
        col = mix(col, mix(float3(0.98, 0.65, 0.55), A, 0.3), exp(-dy * 18.0) * 0.8);
    }
    return half4(finish(col, fc), 1.0);
}
"""

    private const val PS1_POLY = """
// 32-bit polygons: the look of the first 3D consoles - a low-resolution frame with ordered
// dithering instead of smooth gradients, a checkered floor whose texture swims (affine mapping),
// faceted gems turning with their corners snapping to the pixel grid, and thick distance fog.
float bayer2(float2 a) { a = floor(a); return fract(a.x / 2.0 + a.y * a.y * 0.75); }
float bayer4(float2 a) { return bayer2(0.5 * a) * 0.25 + bayer2(a); }

// Flat-shaded spinning gem (an n-sided bipyramid seen from the side), snapped to the grid.
float3 gem(float2 p, float r, float spin, float3 base, float3 hi, float grid, inout float hit) {
    // Snap the shape's own coordinates: corners jump between pixels like old vertex maths.
    float2 q = floor(p / r * grid) / grid;
    float y = q.y;
    float w = (1.0 - abs(y)) * 0.62;
    if (abs(q.x) > w || abs(y) > 1.0) return float3(0.0);
    hit = 1.0;
    // Which facet: the angle round the spin axis.
    float u = asin(clamp(q.x / max(w, 0.001), -1.0, 1.0));
    float a = u + spin;
    float n = 6.0;
    float f = floor(a / TAU * n);
    float fa = (f + 0.5) / n * TAU - spin;
    float light = 0.45 + 0.55 * sat(cos(fa - 0.6)) * (y < 0.0 ? 1.0 : 0.6);
    return mix(base, hi, light) * light;
}

half4 main(float2 fc) {
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float P = 200.0;
    float2 g = floor(fc / uRes.y * P);
    float2 uv = (g + 0.5) / P;
    float d = bayer4(g) - 0.5;
    float hz = 0.5;
    float3 fogCol = mix(BG * 2.5, float3(0.25, 0.12, 0.3), 0.5);
    float3 col;
    if (uv.y < hz) {
        float k = uv.y / hz;
        col = mix(BG * 0.8, mix(fogCol, S * 0.6, 0.35), pow(k, 1.4));
        // Low-poly mountains: straight segments.
        float mx = uv.x * 5.0 + t * 0.03;
        float seg = fract(mx);
        float h0 = hash11(floor(mx));
        float h1 = hash11(floor(mx) + 1.0);
        float mh = hz - 0.04 - 0.12 * mix(h0, h1, seg);
        float3 mcol = mix(fogCol, BG * 1.6, 0.4) * (0.8 + 0.2 * step(0.5, seg));
        col = mix(col, mcol, step(mh, uv.y));
        // Stars.
        col += float3(1.0) * step(0.997, hash12(g)) * (1.0 - k);
    } else {
        // Floor: perspective depth, but the texture mixes in a screen-linear (affine) term that
        // wobbles - the swimming textures of hardware without perspective correction.
        float dy = max(uv.y - hz, 0.002);
        float z = 0.25 / dy;
        float aff = 0.35 * (0.5 + 0.5 * sin(t * 0.7));
        float2 tp = float2((uv.x - asp * 0.5) * mix(z, 1.0 / (dy + 0.1), aff), mix(z, dy * 6.0, aff * 0.3) + t * 0.6);
        float chk = step(0.5, fract(floor(tp.x * 2.0) * 0.5 + floor(tp.y * 2.0) * 0.5));
        float3 tex = mix(A * 0.55, S * 0.35 + BG, chk);
        // Grout lines.
        float2 tf = fract(tp * 2.0);
        tex *= 0.75 + 0.25 * step(0.06, tf.x) * step(0.06, tf.y);
        float fog = sat(1.0 - exp(-z * 0.18));
        col = mix(tex, fogCol, fog);
    }
    // Gems turning above the floor.
    for (int i = 0; i < 3; i++) {
        float fi = float(i);
        float orbit = t * 0.24 + fi * TAU / 3.0;
        float depth = 2.0 + 0.65 * cos(orbit);
        float projection = 1.0 / depth;
        float2 c = float2(asp * 0.5 + 0.7 * sin(orbit) * projection, hz - (0.32 + 0.035 * sin(t + fi)) * projection);
        float r = 0.23 * projection;
        float hit = 0.0;
        float3 gc = gem(uv - c, r, t * (0.8 + 0.3 * fi) + fi, fi < 0.5 ? A : (fi < 1.5 ? S : mix(A, S, 0.5)), float3(1.0), 22.0, hit);
        col = mix(col, gc, hit);
        // Blob shadow on the floor.
        float2 sh = (uv - float2(c.x, hz + 0.16 * projection)) * float2(1.0, 4.0);
        col *= 1.0 - 0.4 * (1.0 - smoothstep(r * 0.4, r, length(sh))) * step(hz, uv.y);
    }
    // 15-bit colour with ordered dithering.
    col = floor(col * 31.0 + d * 1.6 + 0.5) / 31.0;
    return half4(finish(col, fc), 1.0);
}
"""

    private const val PS2_HAZE = """
// 128-bit haze: towers of light rising and sinking out of a deep blue mist, row behind row, their
// tops glowing white; slow beams from above and particles drifting through - the mood of a
// late-90s / early-2000s console's start-up, in the theme's colours.
half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float3 col = mix(BG * 1.6, mix(BG, A, 0.35), pow(uv.y, 1.3));
    // Light from above.
    float beam = sin((uv.x - 0.3 * uv.y) * 7.0 + t * 0.1) * sin(uv.x * 3.0 - t * 0.07);
    col += mix(A, S, 0.5) * smoothstep(0.5, 1.0, beam) * 0.08 * (1.0 - uv.y);
    // Three rows of towers, far to near.
    for (int l = 0; l < 3; l++) {
        float fl = float(l);
        if (uLod > 1.5 && l == 0) continue;
        float depth = 1.0 - fl * 0.3; // 1 far .. 0.4 near
        float sc = 0.6 + fl * 0.5;
        float horizon = 0.62 + fl * 0.12;
        float x = (uv.x - asp * 0.5 + sin(t * 0.08) * 0.045 * sc) / sc + asp * 0.5 + t * 0.01 * (fl + 1.0);
        float cw = 0.11;
        float id = floor(x / cw);
        float fx = fract(x / cw);
        float h = hash11(id * 7.3 + fl * 31.0);
        float present = step(0.25, h);
        float th = (0.08 + 0.38 * h) * (0.75 + 0.25 * sin(t * (0.25 + 0.3 * h) + id * 2.0)) * sc;
        float top = horizon - th;
        float w = 0.28 + 0.2 * hash11(id + fl * 5.0);
        float inX = step(abs(fx - 0.5), w * 0.5);
        float body = inX * step(top, uv.y) * present;
        // A darker right face and sloping cap give each pillar real volume.
        float side = step(0.5 + w * 0.3, fx) * step(fx, 0.5 + w * 0.8) * step(top + 0.012 * sc, uv.y) * present;
        float cap = inX * (1.0 - smoothstep(0.0, 0.009 * sc, abs(uv.y - top + (fx - 0.5) * 0.02 * sc))) * present;
        float3 tower = mix(A * 0.5, mix(S, float3(1.0), 0.4), sat(1.0 - (uv.y - top) / max(th, 0.01)));
        tower *= 0.55 + 0.45 * smoothstep(0.0, w * 0.5, w * 0.5 - abs(fx - 0.5));
        float fog = depth * 0.65;
        col = mix(col, mix(tower, col, fog), body * (1.0 - smoothstep(horizon, horizon + 0.25, uv.y) * 0.5));
        col = mix(col, mix(tower * 0.32, col, fog), side * (1.0 - smoothstep(horizon, horizon + 0.2, uv.y)));
        col += mix(S, float3(1.0), 0.5) * cap * (1.0 - fog) * 0.55;
        // Glowing tops.
        float topGlow = exp(-abs(uv.y - top) * 140.0) * inX * present;
        col += mix(S, float3(1.0), 0.6) * topGlow * (0.5 - fog * 0.3);
        col += A * exp(-max(top - uv.y, 0.0) * 25.0) * step(uv.y, top) * inX * present * 0.12;
    }
    // Ground mist.
    col = mix(col, mix(BG * 2.2, A * 0.4, 0.3), smoothstep(0.55, 1.0, uv.y) * (0.5 + 0.2 * fbm3(uv * 3.0 + float2(t * 0.04, 0.0))));
    // Particles.
    col += mix(float3(1.0), S, 0.3) * dots(uv, 24.0, float2(t * 0.012, -t * 0.03), 0.18, 0.06, 2.0) * 0.6;
    col += mix(float3(1.0), A, 0.3) * dots(uv, 48.0, float2(-t * 0.02, -t * 0.05), 0.12, 0.08, 7.0) * 0.35;
    return half4(finish(col, fc), 1.0);
}
"""

    private const val N64_PLAINS = """
// 64-bit plains: a slow flight over a low-polygon world, the way the first 3D consoles drew it -
// big flat-shaded triangles of hills in saturated greens with chunky, blurry checker "textures",
// grey rock up the slopes and snow on the peaks, a lake of flat blue water, thick bright fog that
// swallows the draw distance, a huge soft sun, puffy low-res clouds - and gold coins spinning in
// the air ahead.

// Height of the faceted terrain: a grid of random corner heights, split into triangles (each one
// flat, so the light shades it as one face).
float cornerH(float2 c) {
    float big = sin(c.x * 0.23) * cos(c.y * 0.19) * 1.1 + sin(c.x * 0.07 + c.y * 0.05) * 1.6;
    return big + hash12(c) * 0.55;
}
float terrain(float2 p) {
    float2 i = floor(p);
    float2 f = fract(p);
    float h00 = cornerH(i);
    float h11 = cornerH(i + 1.0);
    if (f.x > f.y) {
        float h10 = cornerH(i + float2(1.0, 0.0));
        return h00 + (h10 - h00) * f.x + (h11 - h10) * f.y;
    }
    float h01 = cornerH(i + float2(0.0, 1.0));
    return h00 + (h01 - h00) * f.y + (h11 - h01) * f.x;
}

// A 5-point coin-star outline, for the spinning coins.
float coin(float2 p, float r) { return length(p) - r; }

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    // Camera: flying forward, gently banking.
    float2 sp = (fc - 0.5 * uRes) / uRes.y;
    sp.y = -sp.y;
    float z0 = t * 1.1;
    float3 ro = float3(sin(t * 0.07) * 3.0, 0.0, z0);
    ro.y = max(terrain(ro.xz * 0.5) * 1.2, 0.3) + 1.7;
    float bank = 0.06 * sin(t * 0.07 + 1.0);
    float2 rs = rot(bank) * sp;
    float3 rd = normalize(float3(rs.x, rs.y - 0.18, 1.0));

    float3 sunDir = normalize(float3(-0.5, 0.45, 0.8));
    float3 skyTop = float3(0.18, 0.42, 0.95);
    float3 skyLow = float3(0.72, 0.86, 1.0);
    float3 fogCol = float3(0.80, 0.89, 1.0);
    float3 sky = mix(skyLow, skyTop, sat(rd.y * 2.2 + 0.1));
    float sun = max(dot(rd, sunDir), 0.0);
    sky += float3(1.0, 0.95, 0.75) * (pow(sun, 64.0) * 0.9 + pow(sun, 6.0) * 0.18);
    // Clouds: low-res and blurry, like a stretched texture.
    if (rd.y > 0.06) {
        float2 cp = rd.xz / rd.y * 0.35 + float2(t * 0.02, 0.0);
        float2 cg = floor(cp * 6.0) / 6.0;
        float2 cf = fract(cp * 6.0);
        float cl = mix(mix(hash12(cg * 6.0), hash12(cg * 6.0 + float2(1.0, 0.0)), cf.x),
                       mix(hash12(cg * 6.0 + float2(0.0, 1.0)), hash12(cg * 6.0 + 1.0), cf.x), cf.y);
        sky = mix(sky, float3(1.0), smoothstep(0.62, 0.85, cl) * sat((rd.y - 0.06) * 8.0) * 0.85);
    }

    // March the heightfield.
    float tt = 0.0;
    float hit = 0.0;
    float3 p = ro;
    int steps = uLod > 0.5 ? 40 : 64;
    for (int i = 0; i < 64; i++) {
        if (i >= steps) break;
        p = ro + rd * tt;
        float h = max(terrain(p.xz * 0.5) * 1.2, 0.3);
        float dh = p.y - h;
        if (dh < 0.02) { hit = 1.0; break; }
        tt += max(0.04 + tt * 0.025, dh * 0.7);
        if (tt > 40.0) break;
    }
    // A ray that ran out of steps before leaving the world is ground lost in the fog, not sky:
    // without this, gaps of sky showed through the hills near the horizon.
    float far = 1.0 - hit;
    if (hit < 0.5 && tt <= 40.0) { hit = 1.0; }
    float3 col = sky;
    // Below the horizon the far terrain dissolves into fog (no sky colour under the land).
    col = mix(col, fogCol, smoothstep(0.02, -0.04, rd.y));
    if (hit > 0.5) {
        float h = terrain(p.xz * 0.5) * 1.2;
        float water = step(h, 0.3);
        // Flat normal of the triangle (finite differences stay on one face).
        float e = 0.01;
        float hx = terrain((p.xz + float2(e, 0.0)) * 0.5) * 1.2;
        float hz = terrain((p.xz + float2(0.0, e)) * 0.5) * 1.2;
        float3 n = normalize(float3(h - hx, e, h - hz));
        n = mix(n, float3(0.0, 1.0, 0.0), water);
        float dif = sat(dot(n, sunDir)) * 0.95 + 0.22;
        // Blurry checker texture on the grass (bilinear-looking).
        float2 tc = p.xz * 0.9;
        float chk = 0.5 + 0.5 * sin(tc.x * 3.14159) * sin(tc.y * 3.14159);
        float3 grass = mix(float3(0.13, 0.58, 0.18), float3(0.30, 0.78, 0.22), chk);
        grass = mix(grass, A * 0.6 + float3(0.05, 0.25, 0.05), 0.12);
        float3 rock = mix(float3(0.48, 0.45, 0.42), float3(0.62, 0.58, 0.52), chk);
        float3 snow = float3(0.95, 0.97, 1.0);
        float3 ground = mix(grass, rock, smoothstep(1.6, 2.1, h) + smoothstep(0.55, 0.35, n.y) * 0.8);
        ground = mix(ground, snow, smoothstep(2.4, 2.7, h));
        // Sandy shore by the water.
        ground = mix(ground, float3(0.9, 0.82, 0.55), smoothstep(0.42, 0.32, h) * (1.0 - water));
        float3 wat = mix(float3(0.10, 0.35, 0.85), float3(0.35, 0.65, 1.0), 0.5 + 0.5 * sin(p.x * 2.0 + t) * sin(p.z * 2.3 - t * 0.8));
        col = mix(ground * dif, wat + float3(1.0) * pow(sun, 24.0) * 0.4, water);
        // Thick bright fog.
        float fog = 1.0 - exp(-tt * 0.05);
        col = mix(col, fogCol, sat(fog * 1.05 + far));
    }

    // Gold coins spinning in the air ahead (screen-space, drifting towards the camera).
    for (int i = 0; i < 4; i++) {
        float fi = float(i);
        float life = fract(t * 0.08 + fi * 0.25);
        float sc = 0.012 + 0.05 * life * life;
        float2 cp = float2(asp * 0.5 + (hash11(fi + floor(t * 0.08 + fi * 0.25) * 3.1) - 0.5) * asp * 0.9 * (0.3 + life),
                           0.35 - 0.1 * life + 0.03 * sin(t * 1.5 + fi));
        float2 q = uv - cp;
        float sx = cos(t * 2.4 + fi * 1.3);
        q.x /= max(abs(sx), 0.1);
        float d = coin(q, sc);
        float3 gold = mix(float3(0.95, 0.68, 0.1), float3(1.0, 0.95, 0.45), sat(0.5 - q.y / sc * 0.6)) * (0.85 + 0.15 * abs(sx));
        float alive = smoothstep(0.0, 0.1, life) * (1.0 - smoothstep(0.85, 1.0, life));
        col = mix(col, gold, (1.0 - smoothstep(0.0, 0.003, d)) * alive);
        col = mix(col, float3(0.55, 0.36, 0.02), (1.0 - smoothstep(0.0, 0.003, abs(d + sc * 0.35))) * 0.6 * alive);
    }
    col = mix(col, BG * 3.0, 0.04);
    return half4(finish(col, fc), 1.0);
}
"""

    private const val XMB_WAVE = """
// Wave menu: the flowing light waves of a 2000s console menu, given real depth. A deep gradient sky
// with a soft horizon glow; three layers of ribbons - far ones thin, hazy and slow, near ones wide and
// crisp - each shaded like a sheet of light (bright front face, darker underside, a highlight sliding
// along the crest); a glossy floor below reflecting them; and soft bokeh motes at different depths.
half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float x = uv.x / asp;
    float horizon = 0.7;

    // Sky: deep at the top, glowing towards the horizon, a slow light shaft.
    float3 top = mix(BG * 1.3, A * 0.35, 0.35);
    float3 low = mix(BG * 1.8, A * 0.6, 0.55);
    float3 col = mix(top, low, smoothstep(0.0, horizon, uv.y));
    col += A * 0.12 * exp(-abs(uv.y - horizon) * 9.0);
    col += mix(A, float3(1.0), 0.5) * 0.035 * smoothstep(0.6, 1.0, sin(x * 3.0 - uv.y * 1.5 + t * 0.03));

    // The ribbons, far to near. Reflection pass uses the mirrored height.
    float3 light = float3(0.0);
    float3 refl = float3(0.0);
    for (int i = 0; i < 6; i++) {
        if (uLod > 1.5 && i > 3) break;
        float fi = float(i);
        float near = fi / 5.0;                      // 0 far .. 1 near
        float sp = mix(0.08, 0.26, near);
        float amp = mix(0.045, 0.12, near);
        float y0 = mix(0.5, 0.6, near) + 0.02 * sin(fi * 2.1);
        float freq = mix(3.6, 1.8, near);
        float ph = x * freq + t * sp + fi * 1.7;
        float y = y0 + amp * sin(ph) + amp * 0.35 * sin(x * freq * 2.3 - t * sp * 1.6 + fi);
        // Slope of the wave, for shading the sheet (facing up = lit).
        float slope = amp * freq * cos(ph);
        float th = mix(0.012, 0.045, near);
        float blur = mix(3.0, 1.0, near);           // far ribbons are softer
        float d = uv.y - y;
        // Sheet: a band below the crest; brighter where it faces the light.
        float sheet = smoothstep(-th * 0.2, th * 0.4, d) * (1.0 - smoothstep(th * 0.6, th * (1.6 + blur), d));
        float face = 0.55 + 0.45 * sat(-slope * 3.0 + 0.4);
        float crest = exp(-abs(d) * mix(90.0, 260.0, near) / blur);
        // A highlight running along the crest.
        float run = exp(-sqf(fract(x * 0.6 - t * sp * 0.5 + fi * 0.37) - 0.5) * 40.0);
        float haze = mix(0.45, 1.0, near);          // atmospheric fade
        float3 rc = mix(mix(A, S, 0.25 * fi / 5.0), float3(1.0), 0.25 + 0.35 * near);
        light += rc * haze * (sheet * 0.16 * face + crest * (0.32 + 0.6 * run)) * (0.7 + 0.3 * near);
        // Reflection on the floor (mirrored about the horizon, squashed and faded).
        float ry = horizon + (horizon - uv.y) * 2.2;
        float rd = ry - y;
        refl += rc * haze * exp(-abs(rd) * mix(40.0, 90.0, near)) * 0.22;
    }
    // Floor: below the horizon, darker and glossy, with the reflections and a fresnel lift at the back.
    float floorM = smoothstep(horizon - 0.002, horizon + 0.004, uv.y);
    float3 floorC = mix(BG * 0.8, BG * 0.5, sat((uv.y - horizon) * 3.0)) + A * 0.08 * exp(-(uv.y - horizon) * 10.0);
    col = mix(col + light, floorC + refl * exp(-(uv.y - horizon) * 4.0), floorM);
    col += A * 0.25 * exp(-abs(uv.y - horizon) * 160.0);    // the horizon line glints

    // Bokeh motes at three depths, drifting slowly.
    for (int k = 0; k < 3; k++) {
        if (uLod > 1.5 && k > 1) break;
        float fk = float(k);
        float sc = 4.0 + fk * 4.0;
        float2 bp = uv * sc + float2(t * (0.02 + 0.015 * fk), sin(t * 0.1 + fk) * 0.2);
        float2 id = floor(bp);
        float2 h = hash22(id + fk * 11.0);
        float2 f = fract(bp) - 0.5 - (h - 0.5) * 0.5;
        float rad = 0.12 + 0.18 * h.y;
        float on = step(0.72, h.x) * (1.0 - floorM * 0.7);
        float disc = 1.0 - smoothstep(rad * 0.7, rad, length(f));
        col += mix(A, float3(1.0), 0.6) * disc * on * mix(0.05, 0.02, fk / 2.0);
    }
    return half4(finish(col, fc), 1.0);
}
