    private const val INK = """
// Ink wash: ink dropped into water on rice paper. Blooms of ink unfurl slowly in soft tendrils,
// fade and are replaced by new drops; a brushed mountain range sits in the mist below, and a
// red seal-like sun rests in the corner.

float inkBloom(float2 p, float2 c, float age, float seed) {
    if (age < 0.0) return 0.0;
    // The drop sinks slowly as it spreads.
    float2 d = p - c - float2(0.0, age * 0.006);
    float grow = 0.05 + 0.28 * (1.0 - exp(-age * 0.3));
    // Billowing, folded clouds of ink: warped noise inside a ragged, growing edge.
    float2 w = d * 5.0 + 1.6 * float2(fbm3(d * 3.5 + seed + age * 0.04), fbm3(d * 3.5 + seed + 7.0 - age * 0.04));
    float cloud = fbm3(w + seed);
    float edge = length(d) + (cloud - 0.5) * grow * 0.9;
    float fall = 1.0 - smoothstep(grow * 0.35, grow, edge);
    float dens = fall * smoothstep(0.25, 0.75, cloud + 0.3 * fall);
    // A darker thread where folds of ink overlap.
    dens += fall * exp(-abs(cloud - 0.55) * 30.0) * 0.35;
    return sat(dens) * exp(-age * 0.08);
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    // Paper: warm off-white tinted by the theme, with fibres.
    float fib = vnoise(uv * float2(220.0, 40.0)) * 0.5 + vnoise(uv * float2(40.0, 260.0)) * 0.5;
    float3 paper = mix(float3(0.93, 0.9, 0.84), S, 0.12) * (0.92 + 0.06 * fib);
    // Dark mode: the paper is dimmed so the home screen stays readable.
    paper = mix(paper, BG * 1.8, 0.62);
    float3 inkCol = mix(BG * 0.25, A * 0.4, 0.25);

    float3 col = paper;
    // Mountains brushed in layers, fading into the mist.
    for (int i = 0; i < 3; i++) {
        float fi = float(i);
        float base = 0.62 + fi * 0.1;
        float h = base - (0.16 - fi * 0.04) * fbm3(float2(uv.x * (1.5 + fi) + fi * 7.0, fi));
        float brush = 0.04 * vnoise(float2(uv.x * 30.0, uv.y * 4.0 + fi));
        float m = smoothstep(h + brush, h - 0.01 + brush, uv.y) * 0.0 + smoothstep(h - 0.005, h + 0.03, uv.y + brush * 0.5);
        float mist = smoothstep(h + 0.02, h + 0.16, uv.y);
        col = mix(col, inkCol, m * (1.0 - mist * 0.85) * (0.35 + fi * 0.2));
    }
    // Seal-red sun.
    float2 sc = float2(asp * 0.82, 0.26);
    float sd = length(uv - sc) - 0.07 * (1.0 + 0.03 * vnoise(float2(atan(uv.y - sc.y, uv.x - sc.x) * 6.0, 0.0)));
    col = mix(col, mix(A, float3(0.8, 0.15, 0.12), 0.5) * 0.9, (1.0 - smoothstep(-0.003, 0.003, sd)) * 0.85);

    // Ink drops blooming one after another.
    float ink = 0.0;
    for (int i = 0; i < 4; i++) {
        float fi = float(i);
        float per = 13.0;
        float off = fi * per / 4.0;
        float cyc = floor((t + off) / per);
        float age = mod(t + off, per) * 1.6;
        float2 c = float2(asp * (0.12 + 0.76 * hash11(cyc * 3.1 + fi)), 0.15 + 0.4 * hash11(cyc * 1.7 + fi + 5.0));
        ink = max(ink, inkBloom(uv, c, age, cyc + fi * 3.0));
    }
    float3 tint = mix(BG * 0.15, A * 0.35, 0.3);
    col = mix(col, tint, sat(ink * 1.25));
    // A wet sheen at the edges of fresh ink.
    col += float3(1.0) * 0.03 * smoothstep(0.3, 0.6, ink) * (1.0 - smoothstep(0.6, 0.9, ink));

    return half4(finish(col, fc), 1.0);
}
"""

    private const val PAPERCUT = """
// Paper layers: a diorama of cut paper in a box lit by a lamp from the upper left. Each layer stands
// a little in front of the last, so it throws a soft, offset shadow onto the ones behind; cut edges
// catch the light where they face the lamp; far layers are paler (air between them), near ones rich
// and fibrous. Paper clouds hang on threads and sway, birds glide, the paper sun turns behind it all.

// Hill line of layer i (0 = furthest).
float hillLine(float x, float fi, float t) {
    float speed = 0.006 + fi * 0.012;
    float xx = x + t * speed + fi * 3.7;
    float h = 0.36 + fi * 0.11;
    h -= (0.09 - fi * 0.012) * sin(xx * (2.2 + fi * 0.9) + fi);
    h -= 0.05 * vnoise(float2(xx * (3.0 + fi), fi * 2.0));
    // Little paper trees on the nearer layers.
    float tx = xx * (6.0 + fi * 2.0);
    float tid = floor(tx);
    float tf = fract(tx) - 0.5;
    float tree = step(0.6, hash11(tid + fi * 11.0)) * step(1.5, fi) * max(0.0, 0.06 - abs(tf) * 0.18) * 1.0;
    return h - tree;
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float px = 1.5 / uRes.y;

    // Sky: a sheet of paper with a soft gradient.
    float grain = vnoise(uv * 300.0) * 0.03;
    float3 col = mix(mix(BG, S, 0.25) * 1.3, mix(BG, A, 0.2), uv.y) + grain;
    // The paper sun, a scalloped disc turning slowly.
    float2 sc = float2(asp * 0.7, 0.27);
    float2 sd = uv - sc;
    float sa = atan(sd.y, sd.x) + t * 0.05;
    float sr = 0.09 + 0.006 * cos(sa * 12.0);
    float sun = 1.0 - smoothstep(sr - px, sr + px, length(sd));
    float sunSh = 1.0 - smoothstep(sr - 0.01, sr + 0.02, length(sd - float2(0.006, 0.008)));
    col *= 1.0 - 0.25 * sunSh * (1.0 - sun);
    col = mix(col, mix(S, float3(1.0, 0.9, 0.6), 0.4), sun);

    float2 lamp = float2(asp * 0.15, -0.3);
    float2 L = normalize(float2(0.55, 0.85));          // light direction across the box (towards +x, +y)
    // Paper clouds hanging on threads, swaying, each with its shadow on the sky sheet.
    for (int i = 0; i < 2; i++) {
        float fi = float(i);
        float sw = 0.012 * sin(t * 0.5 + fi * 2.0);
        float2 cc = float2(asp * (0.22 + 0.36 * fi) + sw, 0.17 + 0.05 * fi);
        float cd = min(min(length((uv - cc) * float2(0.8, 1.0)) - 0.045, length(uv - cc - float2(0.045, 0.012)) - 0.032), length(uv - cc - float2(-0.05, 0.015)) - 0.028);
        cd = max(cd, uv.y - cc.y - 0.03);
        float cs = min(min(length((uv - cc - float2(0.012, 0.016)) * float2(0.8, 1.0)) - 0.045, length(uv - cc - float2(0.057, 0.028)) - 0.032), length(uv - cc - float2(-0.038, 0.031)) - 0.028);
        cs = max(cs, uv.y - cc.y - 0.046);
        col *= 1.0 - 0.18 * (1.0 - smoothstep(-0.01, 0.015, cs));
        float thread = (1.0 - smoothstep(0.0, px, abs(uv.x - cc.x - sw * (cc.y - uv.y) * 2.0))) * step(uv.y, cc.y - 0.03);
        col = mix(col, BG * 0.6, thread * 0.5);
        float3 paperW = mix(float3(0.97, 0.96, 0.93), S, 0.08) + grain;
        col = mix(col, paperW * (0.92 + 0.08 * smoothstep(0.02, -0.03, uv.y - cc.y)), 1.0 - smoothstep(-px, px, cd));
    }
    // Paper birds gliding across.
    for (int i = 0; i < 3; i++) {
        float fi = float(i);
        float x = fract(t * (0.02 + 0.01 * fi) + hash11(fi)) * (asp + 0.3) - 0.15;
        float y = 0.15 + 0.12 * hash11(fi + 3.0) + 0.01 * sin(t * 0.8 + fi);
        float2 b = uv - float2(x, y);
        float flap = 0.5 + 0.5 * sin(t * 3.0 + fi * 2.0);
        float wing = abs(b.y + abs(b.x) * (0.4 + 0.5 * flap)) - 0.003;
        float bird = (1.0 - smoothstep(0.0, px, wing)) * step(abs(b.x), 0.018);
        float2 bs = b - float2(0.008, 0.02);
        float wingS = abs(bs.y + abs(bs.x) * (0.4 + 0.5 * flap)) - 0.004;
        col *= 1.0 - 0.15 * (1.0 - smoothstep(0.0, 0.006, wingS)) * step(abs(bs.x), 0.02);
        col = mix(col, BG * 0.6, bird);
    }
    float3 skyCol = mix(mix(BG, S, 0.25) * 1.3, mix(BG, A, 0.2), uv.y) + grain;

    // Five layers, back to front. Each stands a little in front of the one behind: it casts a soft
    // shadow offset away from the lamp, its cut edge is lit where it faces the lamp, and the air
    // between the layers makes the far ones paler.
    for (int i = 0; i < 5; i++) {
        float fi = float(i);
        float d = fi / 4.0;
        float h = hillLine(uv.x, fi, t);
        // The drop shadow onto what's behind: the hill line shifted down-right, blurred wider for the
        // nearer layers (they stand further off the sheet behind).
        float off = 0.006 + 0.01 * fi;
        float hs = hillLine(uv.x - off * 0.6, fi, t) + off;
        float soft = 0.01 + 0.012 * fi;
        float cut = smoothstep(h - px, h + px, uv.y);
        float drop = smoothstep(hs - soft, hs + soft, uv.y) * (1.0 - cut);
        col *= 1.0 - (0.28 + 0.06 * fi) * drop;
        float3 paper = mix(mix(S, A, d) * (0.55 + 0.1 * fi), BG * (1.2 - fi * 0.15), 0.3 + fi * 0.06);
        paper = mix(skyCol * 0.95 + 0.04, paper, 0.45 + 0.55 * d);   // aerial perspective
        // Paper fibre and a lamp falloff across the sheet.
        float fib = fbm3(uv * float2(90.0, 140.0) + fi * 13.0) - 0.5;
        paper *= 1.0 + fib * 0.07 * (0.5 + d);
        paper *= 0.82 + 0.3 * exp(-length(uv - lamp) * 0.7);
        paper += grain;
        // The cut edge: its slope faces the lamp or turns away from it.
        float dh = (hillLine(uv.x + 0.003, fi, t) - h) / 0.003;
        float2 nrm = normalize(float2(dh, -1.0));
        float facing = sat(dot(nrm, -L) * 0.8 + 0.25);
        float edge = exp(-max(uv.y - h, 0.0) / (0.0025 + 0.001 * fi)) * cut;
        paper += float3(1.0, 0.97, 0.9) * edge * facing * 0.28;
        paper *= 1.0 - edge * (1.0 - facing) * 0.25;
        // The sheet darkens a little lower down, where the next layer shades it.
        paper *= 1.0 - 0.1 * smoothstep(h, h + 0.15, uv.y);
        col = mix(col, paper, cut);
    }
    // The box: a soft vignette, as if looking into it.
    float2 vq = (uv - float2(asp * 0.5, 0.5)) / float2(asp, 1.0);
    col *= 1.0 - 0.35 * smoothstep(0.25, 0.75, length(vq));
    return half4(finish(col, fc), 1.0);
}
"""

    private const val PARALLAX16 = """
// 16-bit valley: a pixel-art landscape in the style of the classic 16-bit platformers (all drawn
// here, nothing borrowed): a dithered sky with a big low sun, clouds, mountain and hill layers
// scrolling at their own speeds, pollen twinkling, and a row of grass in front.

// Snaps a position to the pixel grid, so everything looks hand-placed on a low-resolution screen.
float2 pix(float2 uv, float res) { return (floor(uv * res) + 0.5) / res; }

// 4x4 ordered dither threshold for a pixel cell.
float bayer(float2 c) {
    float2 a = mod(c, 4.0);
    float v = 0.0;
    // Bayer matrix by halves (no arrays in this subset).
    float2 b = floor(a / 2.0);
    float2 s = mod(a, 2.0);
    v = 2.0 * mod(b.x + b.y * 2.0 + b.y, 4.0) / 4.0;
    v = (mod(s.x * 2.0 + s.y * 3.0, 4.0) + v * 4.0) / 16.0;
    return v;
}

half4 main(float2 fc) {
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float res = 180.0;                              // pixels per screen height
    float2 cell = floor(fc / uRes.y * res);
    float2 uv = (cell + 0.5) / res;
    float d = bayer(cell);

    // Sky: banded gradient with dithered steps.
    float g = uv.y / 0.7;
    float band = floor(g * 6.0 + d) / 6.0;
    float3 col = mix(mix(S, float3(1.0, 0.8, 0.6), 0.3) * 0.8, mix(BG, A, 0.3) * 0.7, 1.0 - band);
    col = mix(col, BG * 0.6, 0.35);
    // The sun, low and big, with a dithered halo.
    float2 sc = float2(asp * 0.62, 0.42);
    float sdist = length(uv - sc);
    col = mix(col, mix(S, float3(1.0, 0.95, 0.7), 0.5), step(sdist, 0.11));
    col = mix(col, mix(S, A, 0.3) * 0.9, step(sdist, 0.15 + d * 0.02) * step(0.11, sdist) * 0.5);

    // Clouds: chunky rounded rows drifting.
    for (int i = 0; i < 3; i++) {
        float fi = float(i);
        float cx = mod(uv.x + t * (0.01 + 0.006 * fi) + fi * 1.3, asp + 0.6) - 0.3;
        float cy = 0.12 + fi * 0.08;
        float2 q = float2(cx - (0.2 + 0.5 * fi), uv.y - cy);
        float cl = length(q * float2(0.5, 1.6)) - 0.05 - 0.02 * step(0.0, q.x);
        cl = min(cl, length((q - float2(0.05, -0.012)) * float2(0.7, 1.4)) - 0.035);
        col = mix(col, mix(float3(1.0), S, 0.2) * 0.85, step(cl, 0.0));
        col = mix(col, mix(float3(1.0), A, 0.3) * 0.65, step(cl, 0.0) * step(0.004, uv.y - cy));
    }

    // Far mountains: stepped silhouettes.
    float mx = uv.x + t * 0.008;
    float mh = 0.5 - 0.14 * abs(fract(mx * 1.3) - 0.5) * 2.0 - 0.06 * abs(fract(mx * 3.1 + 0.3) - 0.5) * 2.0;
    mh = floor(mh * res / 2.0) * 2.0 / res;
    float3 mcol = mix(BG, A, 0.35) * 0.75;
    col = mix(col, mcol, step(mh, uv.y));
    // Snow caps.
    col = mix(col, mix(float3(0.95), S, 0.15) * 0.85, step(mh, uv.y) * step(uv.y, mh + 0.02) * step(mh, 0.4));

    // Mid hills with a dithered shade edge.
    float hx = uv.x + t * 0.025;
    float hh = 0.6 - 0.05 * sin(hx * 4.0) - 0.03 * sin(hx * 9.0 + 1.0);
    hh = floor(hh * res) / res;
    float3 hcol = mix(float3(0.25, 0.55, 0.3), S, 0.25) * 0.75;
    float shade = step(d, smoothstep(hh, hh + 0.08, uv.y));
    col = mix(col, mix(hcol, hcol * 0.7, shade), step(hh, uv.y));

    // Near ground with grass tufts and a dirt layer.
    float nx = uv.x + t * 0.06;
    float gh = 0.8 - 0.02 * step(0.5, fract(nx * 3.0));
    float tuft = step(0.5, fract(nx * 40.0)) * 0.006;
    col = mix(col, mix(float3(0.35, 0.7, 0.3), A, 0.15) * 0.85, step(gh - tuft, uv.y));
    col = mix(col, mix(float3(0.45, 0.3, 0.2), BG, 0.3), step(gh + 0.03, uv.y));
    col = mix(col, col * 0.75, step(gh + 0.03, uv.y) * step(0.5, fract(nx * 12.0 + floor(uv.y * res / 3.0) * 0.5)));

    // Fireflies / pollen twinkling over the grass.
    float sp = step(0.988, hash12(cell + floor(t * 4.0))) * step(0.6, uv.y) * step(uv.y, 0.8);
    col += mix(float3(1.0, 0.95, 0.6), S, 0.3) * sp * 0.5;

    // Dim it so the home screen stays readable.
    col *= 0.62;
    return half4(finish(col, fc), 1.0);
}
