    private const val HOLO = """
// Holo foil: the shimmer of a holographic trading-card foil, full screen. Rainbow bands slide across
// a fine diffraction pattern with interference ripples flowing over it, a sheen sweeps across and
// glitter flashes; the light catches differently as you tilt the handheld (motion sensor), and the foil
// keeps moving on its own without one.
uniform float2 uTilt;   // -1..1, from the device's tilt (0 when there is none)

float3 spectral(float x) {
    // A smooth rainbow (cos palette), shifted towards the theme's colours elsewhere.
    return 0.5 + 0.5 * cos(TAU * (x + float3(0.0, 0.33, 0.67)));
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    // Tilt: the sensor, plus a slow sway so it lives without one.
    float2 tilt = uTilt + 0.45 * float2(sin(t * 0.33), sin(t * 0.27 + 1.0));

    // Base: dark card stock.
    float3 col = BG * 0.8;

    // Diffraction: fine diagonal grooves whose colour depends on viewing angle (tilt) and position.
    float2 p = uv - float2(asp * 0.5, 0.5);
    float grooves = sin((p.x * 0.8 + p.y) * 380.0) * 0.5 + 0.5;
    float phase = dot(p, float2(0.9, 0.6)) * 1.4 + tilt.x * 0.6 + tilt.y * 0.4 + t * 0.02;
    float3 rainbow = spectral(phase + grooves * 0.05);
    rainbow = mix(rainbow, mix(A, S, 0.5 + 0.5 * sin(phase * 3.0)), 0.35);
    // Bright bands where the light hits, sliding with the tilt.
    float bandPos = dot(p, normalize(float2(1.0, 0.7))) - tilt.x * 0.35 - tilt.y * 0.2;
    float band = exp(-sqf(bandPos * 3.2)) * 0.9 + exp(-sqf((bandPos - 0.55) * 4.0)) * 0.4;
    col += rainbow * (0.12 + 0.55 * band) * (0.8 + 0.2 * grooves);

    // Moving interference: two slow ripple fields crossing, so colours flow over the foil even when
    // the handheld is still (no pressed shapes).
    float w1 = sin(length(p - float2(0.6 * sin(t * 0.11), 0.4 * cos(t * 0.09))) * 26.0 - t * 1.1);
    float w2 = sin(dot(p, float2(0.8, -0.6)) * 30.0 + t * 0.8 + w1 * 0.6);
    float inter = 0.5 + 0.25 * (w1 + w2);
    col += spectral(phase + inter * 0.35 + t * 0.03) * inter * (0.06 + 0.25 * band);
    // A sheen sweeping across every few seconds, as if the card turned under the lamp.
    float sweep = exp(-sqf((dot(p, normalize(float2(1.0, -0.4))) - (fract(t / 6.0) * 3.0 - 1.5)) * 5.0));
    col += mix(float3(1.0), rainbow, 0.5) * sweep * 0.22;

    // Glitter: tiny flakes that flash when their angle meets the light.
    float2 gp = fc / max(uRes.y / 540.0, 1.0) * 0.6;
    float2 gid = floor(gp);
    float2 gf = fract(gp) - 0.5;
    float2 h = hash22(gid);
    float facing = sin(h.x * TAU + tilt.x * 6.0 + tilt.y * 4.0 + t * 0.4);
    float flake = step(0.92, h.y) * smoothstep(0.92, 1.0, facing) * (1.0 - smoothstep(0.1, 0.35, length(gf)));
    col += mix(float3(1.0), spectral(h.x + phase), 0.4) * flake * 1.2;

    // Edge darkening like a card under a lamp.
    col *= 0.75 + 0.25 * smoothstep(1.2, 0.2, length(p));
    // Dim overall so the home screen stays readable.
    col = mix(col, BG, 0.25);
    return half4(finish(col, fc), 1.0);
}
"""

    private const val CAMPFIRE = """
// Campfire: a camp in a pine forest at night, seen from low down by the fire. A teepee of logs burns
// inside a ring of stones - tall licking flames, glowing coals, embers spiralling up and winking out,
// a thin column of smoke. The firelight breathes on everything: the ground, the stones, a tent on
// the left with its canvas glowing, a log bench on the right, the nearest pines; the forest behind
// fades into the dark under a sky full of slowly wheeling stars.

// A pine tree: negative inside. p relative to its foot, h = height.
float pineD(float2 p, float h) {
    float y = -p.y / h;
    float tiers = fract(y * 5.0);
    float w = (1.0 - y) * 0.30 * h * (0.75 + 0.25 * tiers);
    float d = abs(p.x) - w;
    d = max(d, p.y);
    d = max(d, -p.y - h);
    return d;
}

// Firelight reaching a point at distance d (screen units), flickering.
float3 fireLight(float d, float3 fire, float flick) { return fire * flick / (1.0 + d * d * 12.0); }

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float px = 1.5 / uRes.y;

    float2 fire = float2(asp * 0.5, 0.74);
    float flick = 0.82 + 0.1 * sin(t * 11.0) * sin(t * 7.3) + 0.08 * vnoise(float2(t * 6.0, 0.0));
    float3 FIRE = mix(float3(1.0, 0.52, 0.14), A, 0.3);

    // Sky: stars wheeling round the pole, a faint galaxy.
    float3 col = mix(BG * 0.3, BG * 0.9 + S * 0.02, uv.y);
    float2 sp = rot(t * 0.004) * (uv - float2(asp * 0.5, 1.4)) + float2(asp * 0.5, 1.4);
    col += float3(1.0) * dots(sp, 80.0, float2(0.0), 0.18, 0.07, 1.0) * 0.55;
    col += mix(float3(1.0), S, 0.4) * dots(sp, 28.0, float2(0.0), 0.08, 0.06, 4.0) * 0.6;
    float milky = fbm3(rot(0.5) * sp * 2.0) * exp(-sqf((sp.y - 0.25 + sp.x * 0.12) * 4.0));
    col += mix(S, float3(1.0), 0.5) * milky * 0.09;

    // The far forest: a ragged band of small pines, barely there.
    float fx = uv.x * 22.0;
    float fid = floor(fx);
    float fh = 0.07 + 0.06 * hash11(fid * 1.7);
    float far = pineD(float2((fract(fx) - 0.5) / 22.0, uv.y - 0.60), fh);
    col = mix(col, BG * 0.4 + fireLight(length(uv - fire), FIRE, flick) * 0.02, smoothstep(px, -px, far));
    col = mix(col, BG * 0.4, smoothstep(0.595, 0.6, uv.y));

    // Nearer pines, lit on the side that faces the fire.
    for (int i = 0; i < 9; i++) {
        float fi = float(i);
        float side = fi < 4.5 ? -1.0 : 1.0;
        float k = fi < 4.5 ? fi : fi - 5.0;
        float x = fire.x + side * (0.32 + k * 0.17 + 0.05 * hash11(fi * 3.3)) * (0.8 + 0.25 * asp / 1.78);
        float base = 0.63 + 0.015 * k;
        float h = 0.30 + 0.18 * hash11(fi * 5.1) + 0.05 * k;
        float2 q = uv - float2(x, base);
        float d = pineD(q, h);
        if (d < px) {
            float facing = sat(-side * q.x / max(0.3 * h * (1.0 + q.y / h), 0.01) * 0.5 + 0.5);
            float dist = length(float2(x, base - h * 0.3) - fire);
            float needles = 0.7 + 0.3 * vnoise(q * float2(90.0, 40.0));
            float3 tc = BG * 0.18 + fireLight(dist, FIRE, flick) * (0.08 + 0.45 * facing * facing) * (0.4 + 0.6 * sat(1.0 + q.y / h * 1.6)) * needles;
            col = mix(col, tc, smoothstep(px, -px, d));
        }
    }

    // The clearing: earth and grass, a pool of light round the fire.
    float gy = 0.62;
    if (uv.y > gy) {
        float g = vnoise(uv * float2(40.0, 120.0)) * 0.6 + vnoise(uv * float2(160.0, 300.0)) * 0.4;
        float3 ground = BG * (0.35 + 0.15 * g) + float3(0.02, 0.025, 0.012);
        float2 gp = (uv - fire) * float2(1.0, 3.0);
        ground += fireLight(length(gp), FIRE, flick) * (0.75 + 0.4 * g) * exp(-length(gp) * 1.5);
        ground *= smoothstep(gy, gy + 0.03, uv.y) * 0.6 + 0.4;
        col = mix(col, ground, smoothstep(gy, gy + px, uv.y));
    }

    // The tent, left: a glowing canvas A-frame with a dark doorway.
    float2 tq = uv - float2(fire.x - 0.42 * (0.8 + 0.2 * asp / 1.78), 0.70);
    float tent = max(abs(tq.x) * 0.95 + (-tq.y) * 0.62 - 0.12, tq.y);
    if (tent < px) {
        float lit = sat(0.5 + tq.x * 5.0);
        float3 canvas = mix(float3(0.10, 0.08, 0.05), FIRE * 0.55 * flick, lit * 0.8);
        canvas *= 0.8 + 0.2 * step(0.5, fract(tq.x * 30.0 + tq.y * 8.0));
        float door = max(abs(tq.x - 0.01) * 1.6 + (-tq.y) * 0.62 - 0.06, tq.y);
        canvas = mix(canvas, float3(0.015, 0.012, 0.01) + FIRE * 0.04 * flick, step(door, 0.0));
        float ridge = exp(-abs(tq.x) * 300.0) * step(-0.19, tq.y);
        canvas += FIRE * ridge * 0.15;
        col = mix(col, canvas, smoothstep(px, -px, tent));
    }

    // The log bench, right.
    float2 bq = uv - float2(fire.x + 0.36 * (0.8 + 0.2 * asp / 1.78), 0.77);
    float bench = sdRoundBox(bq, float2(0.12, 0.018), 0.018);
    if (bench < px) {
        float3 bark = float3(0.12, 0.07, 0.04) * (0.7 + 0.5 * vnoise(bq * float2(60.0, 15.0)));
        bark += FIRE * sat(-bq.x * 4.0 + 0.6) * 0.3 * flick * sat(0.5 - bq.y * 20.0);
        // The cut end, facing us, with its rings.
        float endD = length((bq - float2(-0.12, 0.0)) * float2(1.6, 1.0)) - 0.018;
        bark = mix(bark, mix(float3(0.35, 0.22, 0.12), float3(0.25, 0.15, 0.08), step(0.5, fract(length(bq - float2(-0.12, 0.0)) * 220.0))) * (0.5 + 0.7 * flick), step(endD, 0.0));
        col = mix(col, bark, smoothstep(px, -px, bench));
    }

    // The ring of stones round the fire.
    for (int i = 0; i < 12; i++) {
        float fi = float(i);
        float a = fi / 12.0 * TAU + 0.2;
        float2 c = fire + float2(cos(a) * 0.11, sin(a) * 0.028 + 0.012);
        float r = 0.016 + 0.006 * hash11(fi * 4.7);
        float2 sq = (uv - c) * float2(1.0, 1.35);
        float sd = length(sq) - r;
        if (sd < px) {
            // Front stones show their lit inner top; back ones their lit face.
            float lit = sat(0.6 - sq.y / r * 0.6) * (sin(a) < 0.0 ? 1.0 : 0.6);
            float3 stone = float3(0.12, 0.11, 0.1) + FIRE * lit * 0.45 * flick;
            stone *= 0.85 + 0.25 * vnoise(sq * 300.0);
            col = mix(col, stone, smoothstep(px, -px, sd) * step(0.0, sin(a) + 0.35 + (uv.y - fire.y) * 20.0));
        }
    }

    // Logs leaning together, glowing where they burn.
    float2 lp = uv - fire;
    float log1 = sdSegment(lp, float2(-0.075, 0.012), float2(0.015, -0.07)) - 0.011;
    float log2 = sdSegment(lp, float2(0.075, 0.012), float2(-0.015, -0.07)) - 0.011;
    float log3 = sdSegment(lp, float2(-0.02, 0.016), float2(0.0, -0.075)) - 0.010;
    float logs = min(min(log1, log2), log3);
    float coal = vnoise(lp * 120.0 + float2(0.0, t * 0.5));
    float burn = sat(smoothstep(0.012, -0.06, lp.y) * 0.4 + smoothstep(0.6, 0.85, coal) * 0.5);
    float3 logCol = mix(float3(0.10, 0.06, 0.035), FIRE * (0.6 + 0.8 * smoothstep(0.55, 0.8, coal)) * flick, burn);
    col = mix(col, logCol, smoothstep(px, -px, logs));
    // Bed of coals.
    float bed = length((lp - float2(0.0, 0.005)) * float2(1.0, 3.5)) - 0.07;
    col += FIRE * smoothstep(0.02, -0.02, bed) * (0.25 + 0.6 * smoothstep(0.5, 0.8, vnoise(lp * 200.0 + t * 0.7))) * flick * step(px, logs);

    // Flames: one turbulent heat field, cut into layers - deep orange, yellow, a pale core.
    float2 fq = (uv - fire - float2(0.0, 0.0)) / 0.36;
    float fy = -fq.y;
    float n = fbm3(float2(fq.x * 3.0, fy * 2.4 - t * 2.6));
    float n2 = vnoise(float2(fq.x * 8.0, fy * 7.0 - t * 4.8));
    float heat = 1.0 - fy * 1.05 - abs(fq.x + (n - 0.5) * 0.3 * fy) * (3.6 + fy * 4.0) + (n - 0.5) * (0.35 + 1.25 * fy) + (n2 - 0.5) * 0.4 * fy;
    heat *= step(-0.06, fy) * flick;
    // A smooth black-body ramp, drawn as light: soft tongues, a hot white heart.
    float3 deep = mix(float3(0.95, 0.24, 0.04), A, 0.35);
    float3 yel = mix(float3(1.0, 0.70, 0.2), S, 0.25);
    float hh = max(heat, 0.0);
    float3 flame = deep * smoothstep(0.0, 0.25, hh) * 1.1 + (yel - deep * 0.5) * smoothstep(0.2, 0.55, hh) + float3(0.6, 0.5, 0.35) * smoothstep(0.5, 0.9, hh);
    float alpha = smoothstep(0.0, 0.12, hh);
    col = col * (1.0 - alpha * 0.85) + flame;
    // Licks of flame breaking off at the tips.
    float tip = smoothstep(0.55, 0.75, vnoise(float2(fq.x * 10.0, fy * 5.0 - t * 5.0))) * smoothstep(0.1, -0.05, heat) * smoothstep(-0.25, -0.05, heat) * step(0.2, fy) * step(fy, 1.2) * exp(-abs(fq.x) * 6.0);
    col += deep * tip * 0.7 * flick;
    // Glow round the flames and the light they throw up into the air.
    col += FIRE * glow(length((uv - fire + float2(0.0, 0.09)) * float2(1.0, 0.8)), 0.06) * 0.3 * flick;
    col += FIRE * 0.06 * exp(-length(uv - fire + float2(0.0, 0.15)) * 3.0) * flick;

    // Embers spiralling up and winking out.
    for (int i = 0; i < 16; i++) {
        float fi = float(i);
        float per = 2.2 + 2.2 * hash11(fi);
        float cyc = t / per + hash11(fi + 3.0);
        float ph = fract(cyc);
        float sd = hash11(fi + floor(cyc) * 7.0);
        float2 e = fire + float2((sd - 0.5) * 0.12 + sin(ph * 7.0 + fi) * 0.04 * ph, -0.05 - ph * 0.62);
        float2 vel = float2(cos(ph * 7.0 + fi) * 0.28 * ph, -0.62);
        float ed = sdSegment(uv, e, e - normalize(vel) * 0.012);
        float life = (1.0 - ph) * step(0.15, hash11(fi + 9.0)) * (0.6 + 0.4 * sin(t * 20.0 + fi));
        col += FIRE * (1.0 - smoothstep(0.0, 0.003, ed)) * life * 1.6;
        col += FIRE * glow(ed, 0.004) * life * 0.12;
    }
    // Smoke drifting up and off to the side.
    float sm = fbm3(float2(uv.x * 4.0 - t * 0.05, uv.y * 3.0 + t * 0.25));
    float rise = fire.y - 0.25 - uv.y;
    float smoke = smoothstep(0.45, 0.75, sm) * exp(-abs(uv.x - fire.x - max(rise, 0.0) * 0.35) * (8.0 - rise * 4.0)) * smoothstep(0.0, 0.15, rise) * (1.0 - smoothstep(0.3, 0.6, rise));
    col = mix(col, BG * 0.8 + FIRE * 0.05, smoke * 0.3);

    return half4(finish(col, fc), 1.0);
}
"""

    private const val ARENA = """
// Arena entrance (music): a packed arena at showtime with your song as the entrance theme. The
// album cover fills the giant screen hanging over the stage, framed by LED strips that chase with
// the spectrum; spotlights sweep the haze faster when the song gets busy, pyro fountains erupt on
// both sides of the ramp on every real kick, the ramp's light bars pulse with the bass, and the
// crowd below twinkles with camera flashes on the highs.
// Shared by the music-reactive scenes (besides "Now playing", which has its own copy): the same
// uniforms NowPlayingScene feeds the music scene - cover, levels, kicks, eight equalizer bands and
// where on screen the visualizer goes - plus the soft cover background.
uniform shader uArt;      // the cover, square and blurred smooth (MusicTheme.softArt)
uniform float2 uArtSize;  // its size in pixels
uniform float uHasArt;    // 0 = no cover yet (or the cover is switched off)
uniform float uBass;      // 0..1, smoothed
uniform float uMid;
uniform float uHigh;
uniform float uBeatAge;   // seconds since the last kick (large = none)
uniform float uPlaying;   // 0..1, fades when paused
uniform float uIntensity; // 0..1, Settings > strength
uniform float4 uEqA;      // bands 0-3 (low), 0..1
uniform float4 uEqB;      // bands 4-7 (high)
uniform float uWaveY;     // 0..1 from the top: where the visualizer sits (Appearance > Equalizer)
uniform float uWaveH;     // room above / below that line (share of the height); the player sits under it
uniform float uWaveX;     // 0..1 from the left: where the visualizer sits across (0 = the middle; the player beside it)
uniform shader uCover;    // the cover, sharp (256 px square) - for the record / disc labels
uniform float2 uCoverSize;
uniform shader uLabel;    // the song's title and artist in dark ink on a clear picture (NowPlayingScene.songLabel)
uniform float2 uLabelSize;
uniform shader uHistory;  // covers of the last songs: a 4 x 2 grid (newest first), MusicTheme.historyAtlas
uniform float uHistCount; // how many of the 8 are filled
uniform float3 uSubject;   // where the cover's subject is: x, y (0..1 across the square) and its size; z = 0 until known (MusicTheme.subject)
// Clocks that only run while the music plays, so spins and scrolls slow down and stop smoothly instead of
// jumping (t * (a + b * level) jumps whenever the level moves). Kept by NowPlayingScene, in seconds:
uniform float uPlayT;     // time spent playing (integral of uPlaying)
uniform float uBassT;     // integral of uBass x uPlaying
uniform float uMidT;      // integral of uMid x uPlaying
uniform float uHighT;     // integral of uHigh x uPlaying

// The visualizer's room, with a sensible size when it isn't set (previews).
float room(float fallback) { return uWaveH > 0.001 ? uWaveH : fallback; }
// Across: the middle, or the left part when the player sits beside the visualizer (MusicPlayerLayout.SIDE).
float waveX(float asp) { return uWaveX > 0.001 ? uWaveX * asp : asp * 0.5; }

float2 mirrorUv(float2 q) { return 1.0 - abs(1.0 - mod(q, 2.0)); }

float eqBand(float i) {
    if (i < 0.5) return uEqA.x;
    if (i < 1.5) return uEqA.y;
    if (i < 2.5) return uEqA.z;
    if (i < 3.5) return uEqA.w;
    if (i < 4.5) return uEqB.x;
    if (i < 5.5) return uEqB.y;
    if (i < 6.5) return uEqB.z;
    return uEqB.w;
}

// The spectrum at m (0 = lowest band, 1 = highest), smoothly interpolated.
float eqAt(float m) {
    float f = clamp(m, 0.0, 1.0) * 7.0;
    float i = floor(f);
    float u = f - i;
    u = u * u * (3.0 - 2.0 * u);
    return mix(eqBand(i), eqBand(min(i + 1.0, 7.0)), u);
}

// Pushes a colour's saturation by s (1 = unchanged) around its own brightness.
float3 vivid(float3 c, float s) {
    float l = dot(c, float3(0.299, 0.587, 0.114));
    return max(mix(float3(l), c, s), 0.0);
}

// The cover, very soft and slowly drifting (or, without one, the palette swirling), dimmed by dim.
float3 coverField(float2 uv, float asp, float t, float bass, float dim, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float zoom = 1.7 + 0.08 * sin(t * 0.045) - 0.05 * bass * uIntensity;
    p = rot(0.05 * sin(t * 0.031)) * p / zoom;
    p += (float2(vnoise(p * 2.0 + float2(t * 0.1, 0.0)), vnoise(p * 2.0 + float2(7.3, -t * 0.08))) - 0.5) * 0.1;
    float2 q = p / max(asp, 1.0) + 0.5;
    float3 art = float3(uArt.eval(mirrorUv(q) * uArtSize).rgb);
    float sw = fbm3(uv * 1.4 + float2(t * 0.03, -t * 0.02));
    float3 noArt = mix(BG * 1.4 + A * 0.08, mix(A, S, sw) * 0.5, smoothstep(0.25, 0.8, sw));
    float3 col = mix(noArt, vivid(art, 1.35) * 0.62, uHasArt);
    return mix(col, BG, 0.14) * dim;
}

// The palette as a living gradient: A and S (the cover's colours) flowing round each other with a
// third, hue-shifted colour, brighter on the beat. A colourful base instead of a near-black one.
float3 paletteField(float2 uv, float asp, float t, float lift, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float n1 = fbm3(p * 1.3 + float2(t * 0.05, -t * 0.04));
    float n2 = fbm3(p * 1.7 + float2(-t * 0.035, t * 0.05) + 4.7);
    float3 C = float3(S.z, A.x, (A.y + S.y) * 0.5); // a third colour from the two
    float3 col = mix(A, S, smoothstep(0.25, 0.75, n1));
    col = mix(col, C, smoothstep(0.45, 0.85, n2) * 0.55);
    col = mix(BG, col, 0.42 + 0.18 * lift);
    return col;
}

// The sharp cover at q (0..1 across the square), or the palette when there's no cover yet.
float3 sharpCover(float2 q, float3 A, float3 S) {
    float3 art = float3(uCover.eval(clamp(q, 0.0, 1.0) * uCoverSize).rgb);
    return mix(mix(A, S, q.y), art, uHasArt);
}

// Where the cover's subject sits (x, y, size), with a sensible guess before it's known.
float3 subjectOf() { return uSubject.z > 0.001 ? uSubject : float3(0.5, 0.45, 0.3); }

// Ink of the song label at q (0..1 across the writing area): 0 = paper, 1 = ink.
float labelInk(float2 q) {
    if (q.x < 0.0 || q.x > 1.0 || q.y < 0.0 || q.y > 1.0) return 0.0;
    return float(uLabel.eval(q * uLabelSize).a);
}

// Cover of an earlier song: i = 0 the one before this, 1 the one before that... (wraps round the
// ones there are; with none yet, the current cover in the song's colours instead).
float3 pastCover(float i, float2 q, float3 A, float3 S) {
    q = clamp(q, 0.0, 1.0);
    if (uHistCount < 0.5) return mix(sharpCover(q, A, S), mix(A, S, q.y), 0.35);
    float n = mod(floor(i), uHistCount);
    float2 tile = float2(mod(n, 4.0), floor(n / 4.0));
    float2 p = (tile + 0.01 + q * 0.98) * 192.0;
    return float3(uHistory.eval(p).rgb);
}

// A column of fire rising from a flame pot at the origin (y up = negative screen y): its height h
// follows the kick; noise rising through it tears the top into tongues. Returns colour (premultiplied).
float3 fireColumn(float2 q, float h, float w, float t, float seed, float3 A) {
    float up = -q.y;
    if (up < -0.01 || h < 0.004 || abs(q.x) > w * 3.0) return float3(0.0);
    float n = fbm3(float2(q.x / w * 1.3 + seed, up * 9.0 - t * 5.0));
    float n2 = vnoise(float2(q.x / w * 3.0 - seed, up * 22.0 - t * 9.0));
    float ww = w * (0.7 + 1.4 * sat(up / h)) * (0.8 + 0.4 * n2);           // widens as it rises
    float across = 1.0 - smoothstep(0.4, 1.0, abs(q.x + (n - 0.5) * w * 1.5 * sat(up / h)) / ww);
    float T = sat(1.0 - max(up, 0.0) / (h * (0.6 + 0.7 * n))) * across * (0.8 + 0.4 * n2);
    float3 c = mix(mix(float3(0.6, 0.08, 0.02), A * 0.6, 0.15), float3(1.0, 0.45, 0.08), smoothstep(0.08, 0.35, T));
    c = mix(c, float3(1.0, 0.85, 0.35), smoothstep(0.4, 0.7, T));
    c = mix(c, float3(1.0, 0.97, 0.88), smoothstep(0.75, 0.95, T));
    return c * smoothstep(0.03, 0.2, T);
}

float3 bc0(float fi, float3 A, float3 S) { return mix(fi < 2.0 ? A : S, float3(1.0), 0.25); }

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float px = 1.5 / uRes.y;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float k = uIntensity;
    float play = uPlaying;
    float bass = uBass * play;
    float busy = (uMid + uHigh) * 0.5 * play;
    float kick = exp(-uBeatAge * 4.0) * play;

    // Dark arena, coloured haze.
    float3 col = BG * 0.5 + float3(0.01, 0.008, 0.02);
    col += mix(A, S, uv.x / asp) * 0.08 * fbm3(uv * 3.0 + float2(t * 0.03, 0.0)) * (0.6 + 0.6 * bass);

    // The giant screen with the cover, where the visualizer sits.
    float2 c = float2(waveX(asp), uWaveY);
    float R = room(0.3) * 0.82;
    float2 sp = uv - c;
    float2 half_ = float2(R * 1.0, R * 1.0);
    float scr = sdRoundBox(sp, half_, R * 0.03);
    // Truss above it.
    float truss = step(abs(sp.y + half_.y + R * 0.12), R * 0.03) * step(abs(sp.x), half_.x * 1.6);
    float trussX = step(abs(fract((sp.x / (R * 0.06))) - 0.5), 0.12) * truss;
    col = mix(col, float3(0.18, 0.18, 0.22), truss * 0.8);
    col = mix(col, float3(0.32), trussX);
    // LED frame chasing with the spectrum round the screen.
    float frame = sdRoundBox(sp, half_ + R * 0.06, R * 0.06);
    float onFrame = step(frame, 0.0) * step(0.0, scr);
    float per = atan(sp.y, sp.x) / TAU + 0.5;
    float seg = floor(per * 64.0);
    float e = eqAt(abs(fract(seg / 64.0 + 0.25) * 2.0 - 1.0)) * play;
    float chase = step(0.5, fract(seg * 0.5 + t * (1.0 + 3.0 * busy)));
    float3 led = mix(A, S, fract(seg / 16.0 + t * 0.1)) * (0.25 + 1.2 * e + 0.4 * chase * busy);
    col = mix(col, led, onFrame * step(abs(fract(per * 64.0) - 0.5), 0.38));
    // The cover on the screen: slightly zooming with the bass, scanlines, flashing on the kick.
    if (scr < px) {
        float2 cq = sp / (2.0 * half_) / (1.0 + 0.03 * bass * k) + 0.5;
        float3 cov = sharpCover(cq, A, S);
        cov *= 0.88 + 0.12 * step(0.5, fract(cq.y * 140.0));
        cov += float3(1.0) * kick * k * 0.18;
        col = mix(col, cov, 1.0 - smoothstep(-px, px, scr));
    }
    // Screen glow on the haze.
    col += mix(A, S, 0.5) * exp(-max(scr, 0.0) * 6.0) * 0.12 * (0.6 + 0.8 * bass);

    // The stage and the ramp, under the screen.
    float stageY = c.y + half_.y + R * 0.35;
    float ramp = step(stageY, uv.y) * step(abs(uv.x - c.x), 0.08 + (uv.y - stageY) * 1.4);
    float3 rampC = float3(0.06, 0.06, 0.09);
    // Light bars across the ramp, pulsing outwards with the bass.
    float bars = step(0.6, fract((uv.y - stageY) * 30.0 - (0.5 * t + 2.0 * uBassT)));
    rampC += mix(A, S, 0.5) * bars * (0.15 + 0.7 * bass * k) * step(abs(uv.x - c.x), 0.07 + (uv.y - stageY) * 1.35);
    col = mix(col, rampC, ramp);
    col = mix(col, float3(0.05), step(stageY - 0.01, uv.y) * step(uv.y, stageY) * step(abs(uv.x - c.x), half_.x * 1.8));

    // Spotlights sweeping the haze from both sides.
    for (int i = 0; i < 4; i++) {
        float fi = float(i);
        float side = i < 2 ? -1.0 : 1.0;
        float2 o = float2(c.x + side * (half_.x * (1.0 + 0.4 * fi - (fi > 1.5 ? 0.8 : 0.0))), c.y - half_.y - R * 0.12);
        float sweep = sin(t * (0.35 + 0.6 * busy) + fi * 1.7) * 0.35;
        float a = side * (0.25 + mod(fi, 2.0) * 0.2) + sweep;
        float2 dir = float2(-sin(a), cos(a));
        float3 bc = bc0(fi, A, S);
        float2 rel = uv - o;
        float along = dot(rel, dir);
        float across = abs(dot(rel, float2(-dir.y, dir.x)));
        float beam = exp(-across / (0.006 + max(along, 0.0) * 0.12) * 2.0) * step(0.0, along) * exp(-along * 0.9);
        // A bright lamp head on the truss and a pool where the beam meets the floor.
        col += mix(bc0(fi, A, S), float3(1.0), 0.6) * exp(-length(rel) * 220.0) * 0.8;
        col += bc * beam * (0.18 + 0.25 * busy + 0.2 * kick) * (0.6 + 0.4 * fbm3(uv * 4.0 + t * 0.1));
    }

    // Flame pots: four along the stage front. A pilot flame always flickers; on every real kick they
    // roar up into fire columns, throwing orange light over the stage, the truss and the crowd.
    float fireLight = 0.0;
    for (int s = 0; s < 4; s++) {
        float fs = float(s);
        float side = fs < 1.5 ? -1.0 : 1.0;
        float outer = mod(fs, 2.0);
        float2 base = float2(c.x + side * half_.x * (1.25 + 0.45 * outer), stageY - 0.006);
        float2 q = uv - base;
        float burst = kick * (0.6 + 0.6 * k) * (1.0 - 0.25 * outer);
        float h = 0.03 + 0.04 * bass + 0.34 * burst;
        float3 fcol = fireColumn(q, h, 0.012 + 0.018 * burst, t, fs * 3.1, A);
        col = col + fcol * (1.0 - 0.3 * sat(length(col)));
        // The pot itself.
        float pot = sdRoundBox(q - float2(0.0, 0.008), float2(0.016, 0.008), 0.002);
        col = mix(col, float3(0.08, 0.08, 0.1) + float3(1.0, 0.5, 0.15) * 0.25 * (0.3 + burst), 1.0 - smoothstep(-px, px, pot));
        // Sparks thrown up and falling back.
        float sparks = dots(q * float2(1.0, 0.6) + float2(0.0, t * 0.6), 60.0, float2(0.0), 0.3, 0.08, 3.0 + fs);
        col += float3(1.0, 0.8, 0.4) * sparks * 0.7 * step(abs(q.x), 0.03 + -q.y * 0.25) * step(-h * 1.3, q.y) * step(q.y, 0.0) * burst;
        fireLight += (0.15 + burst) * exp(-length((uv - base) * float2(0.7, 1.0)) * 4.0);
    }
    float3 FIREC = float3(1.0, 0.5, 0.15);
    col += FIREC * fireLight * 0.18;

    // Pools of the spotlights on the stage floor, and the screen reflected faintly in it.
    if (uv.y > stageY && uv.y < stageY + 0.06) {
        float2 rq = float2(uv.x - c.x, (stageY - (uv.y - stageY) * 3.0) - c.y);
        if (sdRoundBox(rq, half_, R * 0.03) < 0.0) {
            col += sharpCover(rq / (2.0 * half_) + 0.5, A, S) * 0.12 * (1.0 - (uv.y - stageY) / 0.06);
        }
    }

    // The crowd: rows of heads and shoulders, rim-lit by the stage and the fire, swaying to the
    // beat; camera flashes on the highs and arms going up on the kick.
    float3 crowdC = float3(0.02, 0.02, 0.04);
    for (int r = 0; r < 2; r++) {
        float fr = float(r);
        float rowY = 0.84 + fr * 0.06;
        float hs = 0.016 + fr * 0.006;                 // head size (near row larger)
        float cx = uv.x / (hs * 2.4) + fr * 0.5;
        float id = floor(cx);
        float lx = (fract(cx) - 0.5) * hs * 2.4;
        float bob = (0.004 + 0.006 * kick) * sin(t * 6.0 + id * 1.3) * play;
        float hy = rowY - hs * 1.6 + bob + 0.006 * hash11(id + fr * 9.0);
        float head = length(float2(lx, uv.y - hy)) - hs * (0.75 + 0.2 * hash11(id * 1.7));
        float body = sdRoundBox(float2(lx * (1.0 + 0.4 * sat((hy + hs * 1.2 - uv.y) / hs)), uv.y - hy - hs * 2.2), float2(hs * 1.25, hs * 1.6), hs * 0.9);
        float arm = sdSegment(float2(lx, uv.y), float2(hs * 0.6, hy + hs), float2(hs * 0.9, hy - hs * 2.2)) - hs * 0.18;
        arm += (1.0 - step(0.55, hash11(id * 4.1 + fr))) * 1.0 + (1.0 - kick) * 0.05;
        float person = min(min(head, body), arm);
        float m = 1.0 - smoothstep(-px, px, person);
        // Rim light on the top edge.
        float rim = smoothstep(-px * 3.0, 0.0, head) * (1.0 - smoothstep(-px, px, head)) * step(uv.y, hy);
        float3 rimC = mix(mix(A, S, 0.5) * 0.5, FIREC, sat(fireLight * 2.0));
        col = mix(col, crowdC + rimC * rim * (0.5 + 0.5 * bass) * (1.0 - fr * 0.3), m);
    }
    col = mix(col, crowdC, step(0.93, uv.y));
    float flash = dots(uv + float2(floor(t * 6.0) * 0.137, 0.0), 70.0, float2(0.0), 0.04 + 0.1 * uHigh * play, 0.06, 5.0) * step(0.83, uv.y);
    col += float3(1.0) * flash * 1.2;

    return half4(finish(col, fc), 1.0);
}
"""

    private const val PRISM_ATRIUM = """
// Glass archways recede through a reflective atrium. Perspective, occlusion and quiet camera drift.
half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float2 p = uv - float2(asp * 0.5 + sin(uTime * 0.08) * 0.035, 0.45);
    float3 col = uBg.rgb * (1.0 + uv.y * 0.4);
    float horizon = 0.45;
    float floorY = max(uv.y - horizon, 0.002);
    float z = 0.18 / floorY;
    float x = p.x * z;
    float2 grid = abs(fract(float2(x, z + uTime * 0.12)) - 0.5);
    float seam = 1.0 - smoothstep(0.005, 0.024, min(grid.x, grid.y));
    col += uAcc.rgb * seam * exp(-z * 0.22) * step(horizon, uv.y) * 0.14;
    // Back-to-front arches; fewer at low quality.
    for (int i = 0; i < 7; i++) {
        if (uLod > 1.5 && i < 3) continue;
        float depth = 1.3 + float(6 - i) * 0.85 + fract(uTime * 0.045);
        float scale = 1.0 / depth;
        float2 q = p / scale;
        float frame = abs(max(abs(q.x) - 0.66, abs(q.y + 0.1) - 0.54));
        float outline = 1.0 - smoothstep(0.01, 0.04, frame);
        float glow = exp(-frame * 18.0) * 0.11;
        float3 tint = mix(uAcc.rgb, uSec.rgb, mod(float(i), 2.0));
        col = mix(col, uSurf.rgb * 1.3, outline * 0.45);
        col += tint * (outline * 0.62 + glow) * (0.35 + 0.65 * scale);
        float2 reflected = float2(p.x, -abs(uv.y - horizon) - 0.1);
        float2 rq = reflected / scale;
        float reflection = exp(-abs(max(abs(rq.x) - 0.66, abs(rq.y + 0.1) - 0.54)) * 30.0);
        col += tint * reflection * step(horizon, uv.y) * exp(-floorY * 4.0) * 0.15;
    }
    return half4(finish(col, fc), 1.0);
}
"""

    private const val ORBIT_STATION = """
// A lit orbital habitat with overlapping tilted rings and a dark planet, in the chosen palette.
half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float2 p = uv - float2(asp * 0.62, 0.46);
    float3 col = uBg.rgb;
    col += uSec.rgb * exp(-length(p) * 3.0) * 0.075;
    col += mix(uAcc.rgb, float3(1.0), 0.5) * dots(uv, 25.0, float2(uTime * 0.002, 0.0), 0.12, 0.08, 7.0) * 0.3;
    float radius = 0.17;
    float planet = 1.0 - smoothstep(radius - 0.002, radius + 0.002, length(p));
    float light = sat(0.55 - p.x * 2.6 - p.y * 1.5);
    for (int i = 0; i < 3; i++) {
        if (uLod > 1.5 && i > 1) break;
        float fi = float(i);
        float2 q = rot(-0.25 + fi * 0.42 + sin(uTime * 0.04) * 0.04) * p;
        float rr = length(q * float2(1.0, 2.6));
        float ringR = 0.28 + fi * 0.07;
        float ring = exp(-abs(rr - ringR) * 240.0);
        float front = step(0.0, q.y);
        float visible = 1.0 - planet * (1.0 - front);
        col += mix(uAcc.rgb, uSec.rgb, fi * 0.4) * ring * visible * (0.25 + 0.65 * front);
        float a = uTime * (0.13 + fi * 0.05) + fi * 2.0;
        float2 shuttle = float2(cos(a) * ringR, sin(a) * ringR / 2.6);
        float dot = exp(-length(q - shuttle) * 500.0);
        col += float3(1.0) * dot * visible;
    }
    col = mix(col, mix(uBg.rgb * 0.65, uAcc.rgb * 0.45, light), planet * 0.97);
    col += uAcc.rgb * exp(-abs(length(p) - radius) * 190.0) * 0.45 * light;
    return half4(finish(col, fc), 1.0);
}
"""

    private const val ART_WALL = """
// Cover wall: the album cover printed again and again on a wall of tiles that never does the same
// thing twice in a row. It drifts, slowly turns and zooms; waves of tiles flip round (the backs in
// the cover's colours), tiles swell and shrink with their part of the spectrum, a ripple of light runs
// out from the middle on each kick, now and then a few tiles pop forward - and every so often the
// big cover in front grows until it fills the screen, then settles back.
// Shared by the music-reactive scenes (besides "Now playing", which has its own copy): the same
// uniforms NowPlayingScene feeds the music scene - cover, levels, kicks, eight equalizer bands and
// where on screen the visualizer goes - plus the soft cover background.
uniform shader uArt;      // the cover, square and blurred smooth (MusicTheme.softArt)
uniform float2 uArtSize;  // its size in pixels
uniform float uHasArt;    // 0 = no cover yet (or the cover is switched off)
uniform float uBass;      // 0..1, smoothed
uniform float uMid;
uniform float uHigh;
uniform float uBeatAge;   // seconds since the last kick (large = none)
uniform float uPlaying;   // 0..1, fades when paused
uniform float uIntensity; // 0..1, Settings > strength
uniform float4 uEqA;      // bands 0-3 (low), 0..1
uniform float4 uEqB;      // bands 4-7 (high)
uniform float uWaveY;     // 0..1 from the top: where the visualizer sits (Appearance > Equalizer)
uniform float uWaveH;     // room above / below that line (share of the height); the player sits under it
uniform float uWaveX;     // 0..1 from the left: where the visualizer sits across (0 = the middle; the player beside it)
uniform shader uCover;    // the cover, sharp (256 px square) - for the record / disc labels
uniform float2 uCoverSize;
uniform shader uLabel;    // the song's title and artist in dark ink on a clear picture (NowPlayingScene.songLabel)
uniform float2 uLabelSize;
uniform shader uHistory;  // covers of the last songs: a 4 x 2 grid (newest first), MusicTheme.historyAtlas
uniform float uHistCount; // how many of the 8 are filled
uniform float3 uSubject;   // where the cover's subject is: x, y (0..1 across the square) and its size; z = 0 until known (MusicTheme.subject)
// Clocks that only run while the music plays, so spins and scrolls slow down and stop smoothly instead of
// jumping (t * (a + b * level) jumps whenever the level moves). Kept by NowPlayingScene, in seconds:
uniform float uPlayT;     // time spent playing (integral of uPlaying)
uniform float uBassT;     // integral of uBass x uPlaying
uniform float uMidT;      // integral of uMid x uPlaying
uniform float uHighT;     // integral of uHigh x uPlaying

// The visualizer's room, with a sensible size when it isn't set (previews).
float room(float fallback) { return uWaveH > 0.001 ? uWaveH : fallback; }
// Across: the middle, or the left part when the player sits beside the visualizer (MusicPlayerLayout.SIDE).
float waveX(float asp) { return uWaveX > 0.001 ? uWaveX * asp : asp * 0.5; }

float2 mirrorUv(float2 q) { return 1.0 - abs(1.0 - mod(q, 2.0)); }

float eqBand(float i) {
    if (i < 0.5) return uEqA.x;
    if (i < 1.5) return uEqA.y;
    if (i < 2.5) return uEqA.z;
    if (i < 3.5) return uEqA.w;
    if (i < 4.5) return uEqB.x;
    if (i < 5.5) return uEqB.y;
    if (i < 6.5) return uEqB.z;
    return uEqB.w;
}

// The spectrum at m (0 = lowest band, 1 = highest), smoothly interpolated.
float eqAt(float m) {
    float f = clamp(m, 0.0, 1.0) * 7.0;
    float i = floor(f);
    float u = f - i;
    u = u * u * (3.0 - 2.0 * u);
    return mix(eqBand(i), eqBand(min(i + 1.0, 7.0)), u);
}

// Pushes a colour's saturation by s (1 = unchanged) around its own brightness.
float3 vivid(float3 c, float s) {
    float l = dot(c, float3(0.299, 0.587, 0.114));
    return max(mix(float3(l), c, s), 0.0);
}

// The cover, very soft and slowly drifting (or, without one, the palette swirling), dimmed by dim.
float3 coverField(float2 uv, float asp, float t, float bass, float dim, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float zoom = 1.7 + 0.08 * sin(t * 0.045) - 0.05 * bass * uIntensity;
    p = rot(0.05 * sin(t * 0.031)) * p / zoom;
    p += (float2(vnoise(p * 2.0 + float2(t * 0.1, 0.0)), vnoise(p * 2.0 + float2(7.3, -t * 0.08))) - 0.5) * 0.1;
    float2 q = p / max(asp, 1.0) + 0.5;
    float3 art = float3(uArt.eval(mirrorUv(q) * uArtSize).rgb);
    float sw = fbm3(uv * 1.4 + float2(t * 0.03, -t * 0.02));
    float3 noArt = mix(BG * 1.4 + A * 0.08, mix(A, S, sw) * 0.5, smoothstep(0.25, 0.8, sw));
    float3 col = mix(noArt, vivid(art, 1.35) * 0.62, uHasArt);
    return mix(col, BG, 0.14) * dim;
}

// The palette as a living gradient: A and S (the cover's colours) flowing round each other with a
// third, hue-shifted colour, brighter on the beat. A colourful base instead of a near-black one.
float3 paletteField(float2 uv, float asp, float t, float lift, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float n1 = fbm3(p * 1.3 + float2(t * 0.05, -t * 0.04));
    float n2 = fbm3(p * 1.7 + float2(-t * 0.035, t * 0.05) + 4.7);
    float3 C = float3(S.z, A.x, (A.y + S.y) * 0.5); // a third colour from the two
    float3 col = mix(A, S, smoothstep(0.25, 0.75, n1));
    col = mix(col, C, smoothstep(0.45, 0.85, n2) * 0.55);
    col = mix(BG, col, 0.42 + 0.18 * lift);
    return col;
}

// The sharp cover at q (0..1 across the square), or the palette when there's no cover yet.
float3 sharpCover(float2 q, float3 A, float3 S) {
    float3 art = float3(uCover.eval(clamp(q, 0.0, 1.0) * uCoverSize).rgb);
    return mix(mix(A, S, q.y), art, uHasArt);
}

// Where the cover's subject sits (x, y, size), with a sensible guess before it's known.
float3 subjectOf() { return uSubject.z > 0.001 ? uSubject : float3(0.5, 0.45, 0.3); }

// Ink of the song label at q (0..1 across the writing area): 0 = paper, 1 = ink.
float labelInk(float2 q) {
    if (q.x < 0.0 || q.x > 1.0 || q.y < 0.0 || q.y > 1.0) return 0.0;
    return float(uLabel.eval(q * uLabelSize).a);
}

// Cover of an earlier song: i = 0 the one before this, 1 the one before that... (wraps round the
// ones there are; with none yet, the current cover in the song's colours instead).
float3 pastCover(float i, float2 q, float3 A, float3 S) {
    q = clamp(q, 0.0, 1.0);
    if (uHistCount < 0.5) return mix(sharpCover(q, A, S), mix(A, S, q.y), 0.35);
    float n = mod(floor(i), uHistCount);
    float2 tile = float2(mod(n, 4.0), floor(n / 4.0));
    float2 p = (tile + 0.01 + q * 0.98) * 192.0;
    return float3(uHistory.eval(p).rgb);
}

// 0..1 bump that is 1 while t is inside [a, b] (soft 1 s edges), for mixing the moves.
float phaseW(float t, float a, float b) { return smoothstep(a, a + 1.0, t) * (1.0 - smoothstep(b - 1.0, b, t)); }

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float px = 1.5 / uRes.y;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float k = uIntensity;
    float play = uPlaying;
    float bass = uBass * play;
    float kick = exp(-uBeatAge * 5.0) * play;
    float2 c = float2(waveX(asp), uWaveY);

    // A 32-second programme of moves, mixed with soft edges.
    float pt = mod(t, 32.0);
    float wSpin = phaseW(pt, 0.0, 9.0);      // the whole wall slowly turning
    float wFlip = phaseW(pt, 7.0, 17.0);     // waves of tiles flipping round
    float wZoom = phaseW(pt, 15.0, 25.0);    // the wall breathing in and out
    float wFill = phaseW(pt, 23.0, 31.5);    // the front cover grows over the screen

    // The wall's transform: drift, a gentle turn, breathing zoom.
    float2 w = uv - c;
    float ang = 0.12 * sin(t * 0.13) * wSpin + 0.04 * kick * k;
    float zoom = 1.0 + 0.45 * (0.5 - 0.5 * cos(pt * TAU / 10.0)) * wZoom + 0.04 * bass * k;
    w = rot(ang) * w / zoom;
    float T = 0.19;
    float2 wp = w / T + float2(t * 0.05, 0.5) + float2(0.0, t * 0.02 * wSpin);
    float2 id = floor(wp);
    float2 q = fract(wp);
    float colPos = fract((id.x * 0.618) + 0.5);
    float e = eqAt(colPos) * play;

    // Ripple of light from the middle on each kick.
    float dist = length(id + 0.5 - float2(t * 0.05, 0.5)) * T;
    float ripple = exp(-abs(dist - uBeatAge * 0.9) * 9.0) * exp(-uBeatAge * 1.2) * play;

    // Flip waves: a front sweeps diagonally over the wall; each tile turns a full circle as it passes.
    float front = (id.x + id.y * 0.6) * 0.18 - pt * 1.1;
    float fl = sat(fract(front * 0.25) * 4.0 - 2.0) * wFlip;
    float flipA = fl * TAU;
    float cx = cos(flipA);
    // Pops: now and then a tile jumps forward and shines (changes every couple of seconds).
    float popId = hash12(id + floor(t * 0.5));
    float pop = step(0.93, popId) * (0.5 - 0.5 * cos(fract(t * 0.5) * TAU));

    float sc = 0.84 + 0.12 * e * k + 0.05 * ripple + 0.12 * pop;
    float2 tq = (q - 0.5) / sc;
    tq.x /= max(abs(cx), 0.04);                // turning round its vertical axis
    tq += 0.5;
    float inTile = step(0.0, tq.x) * step(tq.x, 1.0) * step(0.0, tq.y) * step(tq.y, 1.0);
    float back = step(cx, 0.0);
    float flip = step(0.5, hash12(id + 3.0));
    float2 aq = float2(mix(tq.x, 1.0 - tq.x, flip), tq.y);
    float3 tile = sharpCover(aq, A, S);
    float lum = dot(tile, float3(0.299, 0.587, 0.114));
    float3 duo = mix(BG * 0.6, mix(A, S, colPos), lum);
    tile = mix(duo, tile, 0.4 + 0.5 * e + 0.4 * ripple + 0.6 * pop);
    // Back of a turning tile: the cover's colours with a fine pattern.
    float3 backCol = mix(A, S, tq.y) * (0.45 + 0.25 * step(0.5, fract((tq.x + tq.y) * 6.0)));
    tile = mix(tile, backCol, back);
    tile *= (0.36 + 0.55 * e * (0.5 + 0.5 * k) + 0.6 * ripple + 0.7 * pop) * (0.7 + 0.3 * abs(cx));
    float3 grout = BG * 0.3 + mix(A, S, colPos) * (0.05 + 0.22 * e);
    float3 col = mix(grout, tile, inTile);
    col += mix(A, float3(1.0), 0.5) * pop * 0.15 * inTile;
    // A light sweep across the wall.
    col += float3(1.0) * 0.05 * exp(-sqf((uv.x - uv.y * 0.4 - fract(t * 0.03) * (asp + 1.0) + 0.5) * 3.0));

    // The big cover in front; every half minute it grows to fill the screen and settles back.
    float2 d = uv - c;
    float R0 = room(0.26) * 0.92 * (1.0 + 0.025 * bass * k + 0.02 * kick * k);
    float grow = smoothstep(0.0, 1.0, wFill);
    float R = mix(R0, max(asp, 1.0) * 0.62, grow);
    col *= mix(0.55 + 0.45 * smoothstep(R * 0.9, R * 2.6, length(d)), 1.0, grow);
    // A slow tilt for depth while it's small.
    float tilt = 0.04 * sin(t * 0.4) * (1.0 - grow);
    float2 dd = rot(tilt) * d;
    float box = sdRoundBox(dd, float2(R), R * 0.04);
    float sh = sdRoundBox(dd - float2(0.014, 0.022) * R / 0.24, float2(R), R * 0.04);
    col *= 1.0 - 0.5 * (1.0 - smoothstep(-0.02, 0.05, sh)) * (1.0 - grow);
    col += mix(A, S, 0.5) * exp(-max(box, 0.0) * 14.0) * (0.25 + 0.7 * bass * k) * step(0.0, box);
    if (box < px) {
        float2 cq = dd / (2.0 * R) + 0.5;
        float3 cov = sharpCover(cq, A, S);
        // Filling the screen it gets softer and darker, so the player stays readable.
        cov = mix(cov, cov * 0.55 + BG * 0.2, grow * 0.6);
        cov += float3(1.0) * 0.12 * pow(sat(1.0 - abs(cq.x + cq.y - 2.0 * fract(t * 0.05) * 1.6 + 0.3) * 3.0), 3.0);
        col = mix(col, cov, 1.0 - smoothstep(-px, px, box));
    }
    col += mix(float3(1.0), A, 0.3) * (1.0 - smoothstep(0.0, px * 2.0, abs(box))) * 0.35 * (1.0 - grow);

    return half4(finish(col, fc), 1.0);
}
"""

    private const val ART_TUNNEL = """
// Cover tunnel: the album cover inside itself, again and again - a picture-in-picture tunnel you
// keep falling into, faster with the bass, each frame turning a little on the beat, its edges lit by
// the spectrum.
// Shared by the music-reactive scenes (besides "Now playing", which has its own copy): the same
// uniforms NowPlayingScene feeds the music scene - cover, levels, kicks, eight equalizer bands and
// where on screen the visualizer goes - plus the soft cover background.
uniform shader uArt;      // the cover, square and blurred smooth (MusicTheme.softArt)
uniform float2 uArtSize;  // its size in pixels
uniform float uHasArt;    // 0 = no cover yet (or the cover is switched off)
uniform float uBass;      // 0..1, smoothed
uniform float uMid;
uniform float uHigh;
uniform float uBeatAge;   // seconds since the last kick (large = none)
uniform float uPlaying;   // 0..1, fades when paused
uniform float uIntensity; // 0..1, Settings > strength
uniform float4 uEqA;      // bands 0-3 (low), 0..1
uniform float4 uEqB;      // bands 4-7 (high)
uniform float uWaveY;     // 0..1 from the top: where the visualizer sits (Appearance > Equalizer)
uniform float uWaveH;     // room above / below that line (share of the height); the player sits under it
uniform float uWaveX;     // 0..1 from the left: where the visualizer sits across (0 = the middle; the player beside it)
uniform shader uCover;    // the cover, sharp (256 px square) - for the record / disc labels
uniform float2 uCoverSize;
uniform shader uLabel;    // the song's title and artist in dark ink on a clear picture (NowPlayingScene.songLabel)
uniform float2 uLabelSize;
uniform shader uHistory;  // covers of the last songs: a 4 x 2 grid (newest first), MusicTheme.historyAtlas
uniform float uHistCount; // how many of the 8 are filled
uniform float3 uSubject;   // where the cover's subject is: x, y (0..1 across the square) and its size; z = 0 until known (MusicTheme.subject)
// Clocks that only run while the music plays, so spins and scrolls slow down and stop smoothly instead of
// jumping (t * (a + b * level) jumps whenever the level moves). Kept by NowPlayingScene, in seconds:
uniform float uPlayT;     // time spent playing (integral of uPlaying)
uniform float uBassT;     // integral of uBass x uPlaying
uniform float uMidT;      // integral of uMid x uPlaying
uniform float uHighT;     // integral of uHigh x uPlaying

// The visualizer's room, with a sensible size when it isn't set (previews).
float room(float fallback) { return uWaveH > 0.001 ? uWaveH : fallback; }
// Across: the middle, or the left part when the player sits beside the visualizer (MusicPlayerLayout.SIDE).
float waveX(float asp) { return uWaveX > 0.001 ? uWaveX * asp : asp * 0.5; }

float2 mirrorUv(float2 q) { return 1.0 - abs(1.0 - mod(q, 2.0)); }

float eqBand(float i) {
    if (i < 0.5) return uEqA.x;
    if (i < 1.5) return uEqA.y;
    if (i < 2.5) return uEqA.z;
    if (i < 3.5) return uEqA.w;
    if (i < 4.5) return uEqB.x;
    if (i < 5.5) return uEqB.y;
    if (i < 6.5) return uEqB.z;
    return uEqB.w;
}

// The spectrum at m (0 = lowest band, 1 = highest), smoothly interpolated.
float eqAt(float m) {
    float f = clamp(m, 0.0, 1.0) * 7.0;
    float i = floor(f);
    float u = f - i;
    u = u * u * (3.0 - 2.0 * u);
    return mix(eqBand(i), eqBand(min(i + 1.0, 7.0)), u);
}

// Pushes a colour's saturation by s (1 = unchanged) around its own brightness.
float3 vivid(float3 c, float s) {
    float l = dot(c, float3(0.299, 0.587, 0.114));
    return max(mix(float3(l), c, s), 0.0);
}

// The cover, very soft and slowly drifting (or, without one, the palette swirling), dimmed by dim.
float3 coverField(float2 uv, float asp, float t, float bass, float dim, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float zoom = 1.7 + 0.08 * sin(t * 0.045) - 0.05 * bass * uIntensity;
    p = rot(0.05 * sin(t * 0.031)) * p / zoom;
    p += (float2(vnoise(p * 2.0 + float2(t * 0.1, 0.0)), vnoise(p * 2.0 + float2(7.3, -t * 0.08))) - 0.5) * 0.1;
    float2 q = p / max(asp, 1.0) + 0.5;
    float3 art = float3(uArt.eval(mirrorUv(q) * uArtSize).rgb);
    float sw = fbm3(uv * 1.4 + float2(t * 0.03, -t * 0.02));
    float3 noArt = mix(BG * 1.4 + A * 0.08, mix(A, S, sw) * 0.5, smoothstep(0.25, 0.8, sw));
    float3 col = mix(noArt, vivid(art, 1.35) * 0.62, uHasArt);
    return mix(col, BG, 0.14) * dim;
}

// The palette as a living gradient: A and S (the cover's colours) flowing round each other with a
// third, hue-shifted colour, brighter on the beat. A colourful base instead of a near-black one.
float3 paletteField(float2 uv, float asp, float t, float lift, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float n1 = fbm3(p * 1.3 + float2(t * 0.05, -t * 0.04));
    float n2 = fbm3(p * 1.7 + float2(-t * 0.035, t * 0.05) + 4.7);
    float3 C = float3(S.z, A.x, (A.y + S.y) * 0.5); // a third colour from the two
    float3 col = mix(A, S, smoothstep(0.25, 0.75, n1));
    col = mix(col, C, smoothstep(0.45, 0.85, n2) * 0.55);
    col = mix(BG, col, 0.42 + 0.18 * lift);
    return col;
}

// The sharp cover at q (0..1 across the square), or the palette when there's no cover yet.
float3 sharpCover(float2 q, float3 A, float3 S) {
    float3 art = float3(uCover.eval(clamp(q, 0.0, 1.0) * uCoverSize).rgb);
    return mix(mix(A, S, q.y), art, uHasArt);
}

// Where the cover's subject sits (x, y, size), with a sensible guess before it's known.
float3 subjectOf() { return uSubject.z > 0.001 ? uSubject : float3(0.5, 0.45, 0.3); }

// Ink of the song label at q (0..1 across the writing area): 0 = paper, 1 = ink.
float labelInk(float2 q) {
    if (q.x < 0.0 || q.x > 1.0 || q.y < 0.0 || q.y > 1.0) return 0.0;
    return float(uLabel.eval(q * uLabelSize).a);
}

// Cover of an earlier song: i = 0 the one before this, 1 the one before that... (wraps round the
// ones there are; with none yet, the current cover in the song's colours instead).
float3 pastCover(float i, float2 q, float3 A, float3 S) {
    q = clamp(q, 0.0, 1.0);
    if (uHistCount < 0.5) return mix(sharpCover(q, A, S), mix(A, S, q.y), 0.35);
    float n = mod(floor(i), uHistCount);
    float2 tile = float2(mod(n, 4.0), floor(n / 4.0));
    float2 p = (tile + 0.01 + q * 0.98) * 192.0;
    return float3(uHistory.eval(p).rgb);
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float k = uIntensity;
    float play = uPlaying;
    float bass = uBass * play;
    float kick = exp(-uBeatAge * 4.0) * play;

    float2 c = float2(waveX(asp), uWaveY);
    float2 d = uv - c;
    // Each frame is Z times the size of the next one in.
    float Z = 1.7;
    float lz = log(Z);
    // How far in we've fallen: steady, quicker while it's loud.
    float phase = 0.12 * t + 0.1 * uPlayT;
    phase = fract(phase);
    float rr = max(max(abs(d.x), abs(d.y)), 1e-4);
    float w = log(rr / 0.06) / lz + phase;
    float n = floor(w);
    float f = w - n;
    float level = n - phase;
    float scale = 0.06 * exp(level * lz);
    // Every level turns a little further, and kicks give it a nudge.
    float ang = n * (0.06 + 0.12 * k * kick);
    float2 local = rot(ang) * d / scale;          // |local| between 1 and Z
    float2 q = local / (2.0 * Z) + 0.5;
    float3 col = sharpCover(q, A, S);
    // Fog towards the far end, the outer frames brighter.
    float depth = sat((n + 2.0) / 7.0);
    col *= 0.35 + 0.75 * depth;
    // The frame's edge: a lit border, coloured by the spectrum around it.
    float edge = (max(abs(local.x), abs(local.y)) - 1.0) / (Z - 1.0);
    float m = fract(atan(local.y, local.x) / TAU + 0.5);
    float e = eqAt(abs(m - 0.5) * 2.0) * play;
    float border = exp(-edge * 40.0);
    col = mix(col, mix(A, S, m) * (0.7 + 1.0 * e), border * 0.7);
    col += mix(A, float3(1.0), 0.3) * border * kick * 0.3;
    // The centre glows.
    col += mix(A, S, 0.5) * exp(-length(d) * 12.0) * (0.3 + 0.8 * bass * k);
    col = mix(col, BG, 0.08);

    return half4(finish(col, fc), 1.0);
}
"""

