    private const val AURA_CLASH = """
// Aura clash: two anime power auras - one in each of the theme's colours - pushing against each
// other from the left and the right. Where they meet, a crackling seam of lightning, shockwave
// rings every few seconds, rocks lifting off the cracked ground and focus lines snapping in.
// Generic battle-anime drawing style only.
// Anime / manga drawing tricks shared by the anime-inspired scenes: focus (speed) lines, halftone
// dots, flat cel bands and jagged lightning. Generic drawing styles only - no characters or symbols.

// Focus lines radiating from c, the classic "speed lines" of a dramatic panel. n = how many around,
// they flicker to new positions 8 times a second. Clear near the centre, strongest at the edges.
float focusLines(float2 uv, float2 c, float t, float n, float seed) {
    float2 d = uv - c;
    float a = atan(d.y, d.x) / TAU + 0.5;
    float r = length(d);
    float id = floor(a * n);
    float h = hash11(id + seed + floor(t * 8.0) * 13.0);
    float w = abs(fract(a * n) - 0.5) * 2.0;
    float line = (1.0 - smoothstep(0.0, 0.12 + 0.25 * h, w)) * step(0.62, h);
    return line * smoothstep(0.22 + 0.35 * h, 0.95, r);
}

// Manga halftone: dots on a 45-degree grid, bigger where v is larger (0..1). 1 inside a dot.
float halftone(float2 uv, float scale, float v) {
    float2 p = rot(0.785398) * uv * scale;
    float2 g = fract(p) - 0.5;
    return 1.0 - smoothstep(v * 0.62 - 0.04, v * 0.62 + 0.04, length(g));
}

// Linear noise between random points: kinked, jagged lines (lightning) instead of smooth curves.
float jag(float x, float s) {
    float i = floor(x);
    return mix(hash11(i * 1.37 + s), hash11((i + 1.0) * 1.37 + s), fract(x)) - 0.5;
}

// Distance to a lightning bolt from a to b: a straight segment pushed sideways by jagged noise,
// thinning towards its ends.
float bolt(float2 p, float2 a, float2 b, float seed, float amp) {
    float2 ba = b - a;
    float L = max(length(ba), 1e-4);
    float2 dir = ba / L;
    float2 nrm = float2(-dir.y, dir.x);
    float2 pa = p - a;
    float along = dot(pa, dir);
    float h = sat(along / L);
    float off = (jag(h * 7.0, seed) + 0.45 * jag(h * 23.0, seed + 9.0)) * amp * sin(PI * h);
    float side = dot(pa, nrm) - off;
    float outside = max(-along, along - L);
    return length(float2(side, max(outside, 0.0)));
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float px = 1.5 / uRes.y;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    float2 c = float2(asp * 0.5, 0.52);
    // The seam wobbles between them: who's winning changes slowly.
    float push = 0.06 * sin(t * 0.35) + 0.02 * sin(t * 1.3);
    float seamX = c.x + push + 0.015 * (fbm3(float2(uv.y * 6.0, t * 2.0)) - 0.5);
    float side = uv.x - seamX;

    // Background: dark, each half washed in its aura's colour.
    float3 col = BG * 0.6;
    col = mix(col, mix(BG, A, 0.35), smoothstep(0.0, -0.6, side) * 0.8);
    col = mix(col, mix(BG, S, 0.35), smoothstep(0.0, 0.6, side) * 0.8);

    // Auras: flame-like streams flowing towards the seam, cel-banded.
    float dist = abs(side);
    float flow = fbm3(float2(dist * 6.0 - t * 2.5 * sign(side) * 0.0 - t * 2.5, uv.y * 4.0));
    float f = flow - dist * 2.4 + 0.45;
    float3 aura = side < 0.0 ? A : S;
    float b1 = step(0.25, f);
    float b2 = step(0.42, f);
    float b3 = step(0.6, f);
    col = mix(col, aura * 0.7, b1 * 0.8);
    col = mix(col, mix(aura, float3(1.0), 0.3), b2);
    col = mix(col, mix(aura, float3(1.0), 0.5), b3);

    // The seam: crackling lightning straight down the middle, white-hot.
    float bl = bolt(uv, float2(seamX, 0.05), float2(seamX, 0.95), floor(t * 12.0), 0.06);
    col += float3(1.0) * glow(bl, 0.003) * 0.9;
    col += mix(A, S, 0.5) * glow(bl, 0.02) * 0.35;
    // Side branches.
    for (int i = 0; i < 3; i++) {
        float fi = float(i);
        float y = 0.25 + fi * 0.22;
        float dir = mod(fi, 2.0) < 0.5 ? -1.0 : 1.0;
        float br = bolt(uv, float2(seamX, y), float2(seamX + dir * 0.2, y + 0.08), floor(t * 10.0) + fi * 7.0, 0.03);
        col += float3(1.0) * glow(br, 0.002) * 0.5 * step(0.4, hash11(floor(t * 3.0) + fi));
    }

    // Shockwave rings from the seam every few seconds.
    float st = fract(t / 3.0);
    float sr = length((uv - float2(seamX, c.y)) * float2(1.0, 1.6));
    col += float3(1.0) * exp(-abs(sr - st * 1.2) * 70.0) * (1.0 - st) * 0.6;
    col += float3(1.0) * focusLines(uv, float2(seamX, c.y), t, 80.0, 1.0) * (1.0 - smoothstep(0.0, 0.2, st)) * 0.35;

    // Cracked ground with glow, and rocks lifting off.
    if (uv.y > 0.82) {
        float3 ground = BG * 0.4;
        float cr = abs(fbm3(float2(uv.x * 8.0, uv.y * 30.0)) - 0.5);
        ground += mix(A, S, step(0.0, side)) * (1.0 - smoothstep(0.0, 0.03, cr)) * 0.8;
        col = ground;
    }
    float2 rp = uv * float2(6.0, 1.0) + float2(0.0, t * 0.08);
    float2 ri = floor(rp);
    float2 rf = fract(rp) - 0.5;
    float2 rh = hash22(ri + 2.0);
    float rock = sdRoundBox(rot(t * (rh.y - 0.5)) * ((rf - (rh - 0.5) * 0.5) * float2(1.0 / 6.0, 1.0)), float2(0.01 + 0.012 * rh.y), 0.003);
    col = mix(col, BG * 0.25 + mix(A, S, step(0.0, side)) * 0.25, (1.0 - smoothstep(0.0, px, rock)) * step(rh.x, 0.25));

    return half4(finish(col, fc), 1.0);
}
"""

    private const val AURA_BEAT = """
// Aura clash (music): two anime power auras - one in each of the song's colours - pushing against
// each other with the album cover held in the middle of the clash. The auras flare with their half
// of the spectrum (lows on the left, highs on the right), the one that's louder pushes the seam
// across, lightning crackles down the seam with the mids, and a real kick slams a shockwave ring and
// focus lines out from the cover. Generic battle-anime drawing style only.
// Shared by the music-reactive scenes (besides "Now playing", which has its own copy): the same
// uniforms NowPlayingScene feeds the music scene - cover, levels, kicks, eight equalizer bands and
// where on screen the visualizer goes - plus the soft cover background.
uniform shader uArt;      // the cover, square and blurred smooth (MusicTheme.softArt)
uniform float2 uArtSize;  // its size in pixels
uniform float uHasArt;    // 0 = no cover yet (or the cover is switched off)
uniform float uBass;      // 0..1, smoothed
uniform float uMid;
uniform float uHigh;
uniform float uBeatAge;   // seconds since the last kick (large = none)
uniform float uPlaying;   // 0..1, fades when paused
uniform float uIntensity; // 0..1, Settings > strength
uniform float4 uEqA;      // bands 0-3 (low), 0..1
uniform float4 uEqB;      // bands 4-7 (high)
uniform float uWaveY;     // 0..1 from the top: where the visualizer sits (Appearance > Equalizer)
uniform float uWaveH;     // room above / below that line (share of the height); the player sits under it
uniform float uWaveX;     // 0..1 from the left: where the visualizer sits across (0 = the middle; the player beside it)
uniform shader uCover;    // the cover, sharp (256 px square) - for the record / disc labels
uniform float2 uCoverSize;
uniform shader uLabel;    // the song's title and artist in dark ink on a clear picture (NowPlayingScene.songLabel)
uniform float2 uLabelSize;
uniform shader uHistory;  // covers of the last songs: a 4 x 2 grid (newest first), MusicTheme.historyAtlas
uniform float uHistCount; // how many of the 8 are filled
uniform float3 uSubject;   // where the cover's subject is: x, y (0..1 across the square) and its size; z = 0 until known (MusicTheme.subject)
// Clocks that only run while the music plays, so spins and scrolls slow down and stop smoothly instead of
// jumping (t * (a + b * level) jumps whenever the level moves). Kept by NowPlayingScene, in seconds:
uniform float uPlayT;     // time spent playing (integral of uPlaying)
uniform float uBassT;     // integral of uBass x uPlaying
uniform float uMidT;      // integral of uMid x uPlaying
uniform float uHighT;     // integral of uHigh x uPlaying

// The visualizer's room, with a sensible size when it isn't set (previews).
float room(float fallback) { return uWaveH > 0.001 ? uWaveH : fallback; }
// Across: the middle, or the left part when the player sits beside the visualizer (MusicPlayerLayout.SIDE).
float waveX(float asp) { return uWaveX > 0.001 ? uWaveX * asp : asp * 0.5; }

float2 mirrorUv(float2 q) { return 1.0 - abs(1.0 - mod(q, 2.0)); }

float eqBand(float i) {
    if (i < 0.5) return uEqA.x;
    if (i < 1.5) return uEqA.y;
    if (i < 2.5) return uEqA.z;
    if (i < 3.5) return uEqA.w;
    if (i < 4.5) return uEqB.x;
    if (i < 5.5) return uEqB.y;
    if (i < 6.5) return uEqB.z;
    return uEqB.w;
}

// The spectrum at m (0 = lowest band, 1 = highest), smoothly interpolated.
float eqAt(float m) {
    float f = clamp(m, 0.0, 1.0) * 7.0;
    float i = floor(f);
    float u = f - i;
    u = u * u * (3.0 - 2.0 * u);
    return mix(eqBand(i), eqBand(min(i + 1.0, 7.0)), u);
}

// Pushes a colour's saturation by s (1 = unchanged) around its own brightness.
float3 vivid(float3 c, float s) {
    float l = dot(c, float3(0.299, 0.587, 0.114));
    return max(mix(float3(l), c, s), 0.0);
}

// The cover, very soft and slowly drifting (or, without one, the palette swirling), dimmed by dim.
float3 coverField(float2 uv, float asp, float t, float bass, float dim, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float zoom = 1.7 + 0.08 * sin(t * 0.045) - 0.05 * bass * uIntensity;
    p = rot(0.05 * sin(t * 0.031)) * p / zoom;
    p += (float2(vnoise(p * 2.0 + float2(t * 0.1, 0.0)), vnoise(p * 2.0 + float2(7.3, -t * 0.08))) - 0.5) * 0.1;
    float2 q = p / max(asp, 1.0) + 0.5;
    float3 art = float3(uArt.eval(mirrorUv(q) * uArtSize).rgb);
    float sw = fbm3(uv * 1.4 + float2(t * 0.03, -t * 0.02));
    float3 noArt = mix(BG * 1.4 + A * 0.08, mix(A, S, sw) * 0.5, smoothstep(0.25, 0.8, sw));
    float3 col = mix(noArt, vivid(art, 1.35) * 0.62, uHasArt);
    return mix(col, BG, 0.14) * dim;
}

// The palette as a living gradient: A and S (the cover's colours) flowing round each other with a
// third, hue-shifted colour, brighter on the beat. A colourful base instead of a near-black one.
float3 paletteField(float2 uv, float asp, float t, float lift, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float n1 = fbm3(p * 1.3 + float2(t * 0.05, -t * 0.04));
    float n2 = fbm3(p * 1.7 + float2(-t * 0.035, t * 0.05) + 4.7);
    float3 C = float3(S.z, A.x, (A.y + S.y) * 0.5); // a third colour from the two
    float3 col = mix(A, S, smoothstep(0.25, 0.75, n1));
    col = mix(col, C, smoothstep(0.45, 0.85, n2) * 0.55);
    col = mix(BG, col, 0.42 + 0.18 * lift);
    return col;
}

// The sharp cover at q (0..1 across the square), or the palette when there's no cover yet.
float3 sharpCover(float2 q, float3 A, float3 S) {
    float3 art = float3(uCover.eval(clamp(q, 0.0, 1.0) * uCoverSize).rgb);
    return mix(mix(A, S, q.y), art, uHasArt);
}

// Where the cover's subject sits (x, y, size), with a sensible guess before it's known.
float3 subjectOf() { return uSubject.z > 0.001 ? uSubject : float3(0.5, 0.45, 0.3); }

// Ink of the song label at q (0..1 across the writing area): 0 = paper, 1 = ink.
float labelInk(float2 q) {
    if (q.x < 0.0 || q.x > 1.0 || q.y < 0.0 || q.y > 1.0) return 0.0;
    return float(uLabel.eval(q * uLabelSize).a);
}

// Cover of an earlier song: i = 0 the one before this, 1 the one before that... (wraps round the
// ones there are; with none yet, the current cover in the song's colours instead).
float3 pastCover(float i, float2 q, float3 A, float3 S) {
    q = clamp(q, 0.0, 1.0);
    if (uHistCount < 0.5) return mix(sharpCover(q, A, S), mix(A, S, q.y), 0.35);
    float n = mod(floor(i), uHistCount);
    float2 tile = float2(mod(n, 4.0), floor(n / 4.0));
    float2 p = (tile + 0.01 + q * 0.98) * 192.0;
    return float3(uHistory.eval(p).rgb);
}

// Anime / manga drawing tricks shared by the anime-inspired scenes: focus (speed) lines, halftone
// dots, flat cel bands and jagged lightning. Generic drawing styles only - no characters or symbols.

// Focus lines radiating from c, the classic "speed lines" of a dramatic panel. n = how many around,
// they flicker to new positions 8 times a second. Clear near the centre, strongest at the edges.
float focusLines(float2 uv, float2 c, float t, float n, float seed) {
    float2 d = uv - c;
    float a = atan(d.y, d.x) / TAU + 0.5;
    float r = length(d);
    float id = floor(a * n);
    float h = hash11(id + seed + floor(t * 8.0) * 13.0);
    float w = abs(fract(a * n) - 0.5) * 2.0;
    float line = (1.0 - smoothstep(0.0, 0.12 + 0.25 * h, w)) * step(0.62, h);
    return line * smoothstep(0.22 + 0.35 * h, 0.95, r);
}

// Manga halftone: dots on a 45-degree grid, bigger where v is larger (0..1). 1 inside a dot.
float halftone(float2 uv, float scale, float v) {
    float2 p = rot(0.785398) * uv * scale;
    float2 g = fract(p) - 0.5;
    return 1.0 - smoothstep(v * 0.62 - 0.04, v * 0.62 + 0.04, length(g));
}

// Linear noise between random points: kinked, jagged lines (lightning) instead of smooth curves.
float jag(float x, float s) {
    float i = floor(x);
    return mix(hash11(i * 1.37 + s), hash11((i + 1.0) * 1.37 + s), fract(x)) - 0.5;
}

// Distance to a lightning bolt from a to b: a straight segment pushed sideways by jagged noise,
// thinning towards its ends.
float bolt(float2 p, float2 a, float2 b, float seed, float amp) {
    float2 ba = b - a;
    float L = max(length(ba), 1e-4);
    float2 dir = ba / L;
    float2 nrm = float2(-dir.y, dir.x);
    float2 pa = p - a;
    float along = dot(pa, dir);
    float h = sat(along / L);
    float off = (jag(h * 7.0, seed) + 0.45 * jag(h * 23.0, seed + 9.0)) * amp * sin(PI * h);
    float side = dot(pa, nrm) - off;
    float outside = max(-along, along - L);
    return length(float2(side, max(outside, 0.0)));
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float px = 1.5 / uRes.y;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float k = uIntensity;
    float play = uPlaying;
    float kick = exp(-uBeatAge * 4.5) * play;
    float lows = (uEqA.x + uEqA.y + uEqA.z + uEqA.w) * 0.25 * play;
    float highs = (uEqB.x + uEqB.y + uEqB.z + uEqB.w) * 0.25 * play;

    float2 c = float2(waveX(asp), uWaveY);
    float R = room(0.26) * 0.62;
    // Whoever is louder pushes the seam.
    float push = (lows - highs) * 0.25 * (0.4 + 0.8 * k) + 0.02 * sin(t * 0.6);
    float seamX = c.x + push + 0.015 * (fbm3(float2(uv.y * 6.0, t * 2.0)) - 0.5);
    float side = uv.x - seamX;

    float3 col = BG * 0.55;
    col = mix(col, mix(BG, A, 0.3 + 0.3 * lows), smoothstep(0.0, -0.7, side) * 0.85);
    col = mix(col, mix(BG, S, 0.3 + 0.3 * highs), smoothstep(0.0, 0.7, side) * 0.85);

    // Auras: flame streams flowing towards the seam, cel-banded, taller when their half is loud.
    float dist = abs(side);
    float lv = side < 0.0 ? lows : highs;
    float flow = fbm3(float2(dist * 6.0 - t * (2.0 + 3.0 * lv), uv.y * 4.0 + sign(side) * 3.0));
    float f = flow - dist * (2.8 - 1.4 * lv * k) + 0.4 + 0.2 * kick;
    float3 aura = side < 0.0 ? A : S;
    col = mix(col, aura * 0.7, step(0.25, f) * 0.8);
    col = mix(col, mix(aura, float3(1.0), 0.3), step(0.42, f));
    col = mix(col, mix(aura, float3(1.0), 0.55), step(0.6, f));

    // Lightning down the seam: more of it with the mids.
    float bl = bolt(uv, float2(seamX, 0.0), float2(seamX, 1.0), floor(8.0 * t + 12.0 * uMidT), 0.05 + 0.04 * uMid * play);
    col += float3(1.0) * glow(bl, 0.003) * (0.5 + 0.8 * uMid * play);
    col += mix(A, S, 0.5) * glow(bl, 0.02) * 0.3;

    // Kick: shockwave ring and focus lines from the cover.
    float sr = length((uv - c) * float2(1.0, 1.5));
    float age = uBeatAge;
    col += float3(1.0) * exp(-abs(sr - R * 1.2 - age * 0.9) * 60.0) * kick * 0.7 * k;
    col += float3(1.0) * focusLines(uv, c, t, 90.0, 1.0) * kick * 0.45 * k;

    // The cover held in the clash: a square with a white-hot rim, shaking a little on the kick.
    float2 sh = float2(hash11(floor(t * 30.0)) - 0.5, hash11(floor(t * 30.0) + 3.0) - 0.5) * 0.008 * kick * k;
    float2 d = uv - c - sh;
    float box = sdRoundBox(d, float2(R), R * 0.05);
    col += mix(A, S, step(0.0, d.x)) * exp(-max(box, 0.0) * 18.0) * (0.4 + 0.8 * kick);
    if (box < px) {
        float3 cov = sharpCover(d / (2.0 * R) + 0.5, A, S);
        col = mix(col, cov, 1.0 - smoothstep(-px, px, box));
    }
    col += float3(1.0) * (1.0 - smoothstep(0.0, px * 2.5, abs(box))) * (0.5 + 0.5 * kick);

    // Rocks lifting off the ground with the bass.
    float2 rp = uv * float2(6.0, 1.0) + float2(0.0, t * (0.05 + 0.2 * lows));
    float2 ri = floor(rp);
    float2 rf = fract(rp) - 0.5;
    float2 rh = hash22(ri + 2.0);
    float rock = sdRoundBox(rot(t * (rh.y - 0.5)) * ((rf - (rh - 0.5) * 0.5) * float2(1.0 / 6.0, 1.0)), float2(0.01 + 0.012 * rh.y), 0.003);
    col = mix(col, BG * 0.25 + mix(A, S, step(0.0, side)) * 0.3, (1.0 - smoothstep(0.0, px, rock)) * step(rh.x, 0.2));

    return half4(finish(col, fc), 1.0);
}
"""

    private const val MOUNTAINS = """
// Mountains forming (music): a range of mountains that rises out of the plain - every peak is one
// band of the equalizer, so the range grows and sinks with the song (bass in the middle, highs out
// to the sides). Snow settles on the peaks that stand tall, a big sun sits behind, clouds stream
// past the summits, the plain below glows in the cover's colours, and a kick sends a tremor and a
// puff of dust along the foot of the range. With nothing playing it forms and erodes slowly by itself.
// Shared by the music-reactive scenes (besides "Now playing", which has its own copy): the same
// uniforms NowPlayingScene feeds the music scene - cover, levels, kicks, eight equalizer bands and
// where on screen the visualizer goes - plus the soft cover background.
uniform shader uArt;      // the cover, square and blurred smooth (MusicTheme.softArt)
uniform float2 uArtSize;  // its size in pixels
uniform float uHasArt;    // 0 = no cover yet (or the cover is switched off)
uniform float uBass;      // 0..1, smoothed
uniform float uMid;
uniform float uHigh;
uniform float uBeatAge;   // seconds since the last kick (large = none)
uniform float uPlaying;   // 0..1, fades when paused
uniform float uIntensity; // 0..1, Settings > strength
uniform float4 uEqA;      // bands 0-3 (low), 0..1
uniform float4 uEqB;      // bands 4-7 (high)
uniform float uWaveY;     // 0..1 from the top: where the visualizer sits (Appearance > Equalizer)
uniform float uWaveH;     // room above / below that line (share of the height); the player sits under it
uniform float uWaveX;     // 0..1 from the left: where the visualizer sits across (0 = the middle; the player beside it)
uniform shader uCover;    // the cover, sharp (256 px square) - for the record / disc labels
uniform float2 uCoverSize;
uniform shader uLabel;    // the song's title and artist in dark ink on a clear picture (NowPlayingScene.songLabel)
uniform float2 uLabelSize;
uniform shader uHistory;  // covers of the last songs: a 4 x 2 grid (newest first), MusicTheme.historyAtlas
uniform float uHistCount; // how many of the 8 are filled
uniform float3 uSubject;   // where the cover's subject is: x, y (0..1 across the square) and its size; z = 0 until known (MusicTheme.subject)
// Clocks that only run while the music plays, so spins and scrolls slow down and stop smoothly instead of
// jumping (t * (a + b * level) jumps whenever the level moves). Kept by NowPlayingScene, in seconds:
uniform float uPlayT;     // time spent playing (integral of uPlaying)
uniform float uBassT;     // integral of uBass x uPlaying
uniform float uMidT;      // integral of uMid x uPlaying
uniform float uHighT;     // integral of uHigh x uPlaying

// The visualizer's room, with a sensible size when it isn't set (previews).
float room(float fallback) { return uWaveH > 0.001 ? uWaveH : fallback; }
// Across: the middle, or the left part when the player sits beside the visualizer (MusicPlayerLayout.SIDE).
float waveX(float asp) { return uWaveX > 0.001 ? uWaveX * asp : asp * 0.5; }

float2 mirrorUv(float2 q) { return 1.0 - abs(1.0 - mod(q, 2.0)); }

float eqBand(float i) {
    if (i < 0.5) return uEqA.x;
    if (i < 1.5) return uEqA.y;
    if (i < 2.5) return uEqA.z;
    if (i < 3.5) return uEqA.w;
    if (i < 4.5) return uEqB.x;
    if (i < 5.5) return uEqB.y;
    if (i < 6.5) return uEqB.z;
    return uEqB.w;
}

// The spectrum at m (0 = lowest band, 1 = highest), smoothly interpolated.
float eqAt(float m) {
    float f = clamp(m, 0.0, 1.0) * 7.0;
    float i = floor(f);
    float u = f - i;
    u = u * u * (3.0 - 2.0 * u);
    return mix(eqBand(i), eqBand(min(i + 1.0, 7.0)), u);
}

// Pushes a colour's saturation by s (1 = unchanged) around its own brightness.
float3 vivid(float3 c, float s) {
    float l = dot(c, float3(0.299, 0.587, 0.114));
    return max(mix(float3(l), c, s), 0.0);
}

// The cover, very soft and slowly drifting (or, without one, the palette swirling), dimmed by dim.
float3 coverField(float2 uv, float asp, float t, float bass, float dim, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float zoom = 1.7 + 0.08 * sin(t * 0.045) - 0.05 * bass * uIntensity;
    p = rot(0.05 * sin(t * 0.031)) * p / zoom;
    p += (float2(vnoise(p * 2.0 + float2(t * 0.1, 0.0)), vnoise(p * 2.0 + float2(7.3, -t * 0.08))) - 0.5) * 0.1;
    float2 q = p / max(asp, 1.0) + 0.5;
    float3 art = float3(uArt.eval(mirrorUv(q) * uArtSize).rgb);
    float sw = fbm3(uv * 1.4 + float2(t * 0.03, -t * 0.02));
    float3 noArt = mix(BG * 1.4 + A * 0.08, mix(A, S, sw) * 0.5, smoothstep(0.25, 0.8, sw));
    float3 col = mix(noArt, vivid(art, 1.35) * 0.62, uHasArt);
    return mix(col, BG, 0.14) * dim;
}

// The palette as a living gradient: A and S (the cover's colours) flowing round each other with a
// third, hue-shifted colour, brighter on the beat. A colourful base instead of a near-black one.
float3 paletteField(float2 uv, float asp, float t, float lift, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float n1 = fbm3(p * 1.3 + float2(t * 0.05, -t * 0.04));
    float n2 = fbm3(p * 1.7 + float2(-t * 0.035, t * 0.05) + 4.7);
    float3 C = float3(S.z, A.x, (A.y + S.y) * 0.5); // a third colour from the two
    float3 col = mix(A, S, smoothstep(0.25, 0.75, n1));
    col = mix(col, C, smoothstep(0.45, 0.85, n2) * 0.55);
    col = mix(BG, col, 0.42 + 0.18 * lift);
    return col;
}

// The sharp cover at q (0..1 across the square), or the palette when there's no cover yet.
float3 sharpCover(float2 q, float3 A, float3 S) {
    float3 art = float3(uCover.eval(clamp(q, 0.0, 1.0) * uCoverSize).rgb);
    return mix(mix(A, S, q.y), art, uHasArt);
}

// Where the cover's subject sits (x, y, size), with a sensible guess before it's known.
float3 subjectOf() { return uSubject.z > 0.001 ? uSubject : float3(0.5, 0.45, 0.3); }

// Ink of the song label at q (0..1 across the writing area): 0 = paper, 1 = ink.
float labelInk(float2 q) {
    if (q.x < 0.0 || q.x > 1.0 || q.y < 0.0 || q.y > 1.0) return 0.0;
    return float(uLabel.eval(q * uLabelSize).a);
}

// Cover of an earlier song: i = 0 the one before this, 1 the one before that... (wraps round the
// ones there are; with none yet, the current cover in the song's colours instead).
float3 pastCover(float i, float2 q, float3 A, float3 S) {
    q = clamp(q, 0.0, 1.0);
    if (uHistCount < 0.5) return mix(sharpCover(q, A, S), mix(A, S, q.y), 0.35);
    float n = mod(floor(i), uHistCount);
    float2 tile = float2(mod(n, 4.0), floor(n / 4.0));
    float2 p = (tile + 0.01 + q * 0.98) * 192.0;
    return float3(uHistory.eval(p).rgb);
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float px = 1.5 / uRes.y;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float k = uIntensity;
    float play = uPlaying;
    float kick = exp(-uBeatAge * 4.0) * play;

    float2 c = float2(waveX(asp), uWaveY);
    float H = room(0.28) * 1.7;
    float baseY = c.y + room(0.28) * 0.9;
    // Sky: the song's colours, deep above, warming to a glowing band at the horizon.
    float3 sky = mix(BG * 0.7 + A * 0.05, mix(A, S, 0.5) * 0.55 + BG * 0.3, smoothstep(c.y - H, baseY, uv.y));
    float3 warm = mix(S, float3(1.0, 0.62, 0.3), 0.45);
    sky += warm * 0.22 * exp(-abs(uv.y - baseY + H * 0.2) / (H * 0.35));
    float3 col = sky;
    // The sun: a big setting disc low behind the range, hot white-gold in the middle, deeper at the
    // rim (limb darkening), with slow rays, a corona that breathes with the bass, thin cloud bars
    // drifting across its face and a shimmer of heat at the lower edge.
    float2 sunP = float2(c.x, baseY - H * 0.42);
    float sunR = H * 0.36 * (1.0 + 0.03 * uBass * play * k);
    float2 sq = uv - sunP;
    sq.x += 0.004 * sin(uv.y * 160.0 + t * 6.0) * smoothstep(sunP.y, sunP.y + sunR, uv.y);
    float sd = length(sq);
    float ang = atan(sq.y, sq.x);
    float rays = 0.5 + 0.5 * sin(ang * 14.0 + t * 0.15) * sin(ang * 5.0 - t * 0.1);
    float3 sunHot = mix(float3(1.0, 0.97, 0.86), S, 0.15);
    float3 sunRim = mix(float3(1.0, 0.5, 0.2), mix(A, S, 0.5), 0.35);
    col += sunRim * exp(-(sd - sunR) * 6.0 / H) * step(sunR, sd) * (0.35 + 0.25 * uBass * play) * (0.75 + 0.25 * rays);
    col += sunHot * exp(-sd * 2.0 / H) * 0.12;
    float disc = 1.0 - smoothstep(sunR - px, sunR + px, sd);
    float limb = sqrt(max(1.0 - sqf(sd / sunR), 0.0));
    float3 face = mix(sunRim, sunHot, smoothstep(0.0, 0.85, limb)) * (1.0 + 0.15 * kick);
    // Lower half redder, as the light passes through more air.
    face = mix(face, sunRim * 1.1, smoothstep(sunP.y - sunR * 0.2, sunP.y + sunR, uv.y) * 0.45);
    col = mix(col, face, disc);
    // Thin cloud bars crossing the sun, lit at their edges.
    for (int i = 0; i < 3; i++) {
        float fi = float(i);
        float cy = sunP.y + sunR * (-0.35 + 0.42 * fi) + 0.01 * sin(t * 0.1 + fi);
        float cx = uv.x - sunP.x + mod(t * (0.008 + 0.004 * fi) + fi * 0.37, 1.2) * asp * 0.4 - asp * 0.24;
        float thick = sunR * (0.05 + 0.03 * fi) * (0.6 + 0.8 * vnoise(float2(cx * 8.0, fi * 4.0)));
        float bar = (1.0 - smoothstep(thick * 0.6, thick, abs(uv.y - cy))) * smoothstep(sunR * 1.8, sunR * 0.4, abs(cx));
        float3 cc = mix(BG * 0.5 + A * 0.08, sunRim * 0.55, 0.5);
        cc += sunHot * 0.4 * smoothstep(thick * 0.3, thick, abs(uv.y - cy)) * disc;
        col = mix(col, cc, bar * mix(0.3, 0.85, disc));
    }

    // The range: several layers; the front one is the equalizer.
    float idle = 1.0 - play;
    for (int L = 0; L < 3; L++) {
        float fl = float(L);
        float scale = 1.0 - fl * 0.25;          // front layer is L = 2
        float x = (uv.x - c.x) / (asp * 0.5);  // -1..1 across
        float n = 16.0 - fl * 4.0;
        float slot = (x * 0.5 + 0.5) * n;
        float id0 = floor(slot);
        float ridge = 0.0;
        float hgt = 0.0;
        float localBest = 0.0;
        for (int j = -1; j <= 1; j++) {
            float id = id0 + float(j);
            float cxn = (id + 0.5) / n * 2.0 - 1.0;
            float m = abs(cxn);
            float e = eqAt(m) * play;
            float slow = 0.35 + 0.35 * sin(t * 0.15 + id * 1.7 + fl) * sin(t * 0.07 + id * 0.6);
            float hh = mix(slow, 0.15 + 0.85 * e * (0.5 + 0.7 * k), play) * (0.4 + 0.6 * scale) * (1.0 - 0.35 * m);
            float local = slot - id - 0.5;
            // A broad peak (about two slots wide) with a jagged edge.
            float r = hh * (1.0 - abs(local) * (0.75 + 0.25 * vnoise(float2(local * 7.0 + id, fl))));
            if (r > ridge) { ridge = r; hgt = hh; localBest = local; }
        }
        float local = localBest;
        ridge += 0.03 * (vnoise(float2(x * 40.0, fl * 3.0)) - 0.5) * scale;
        float top = baseY - H * max(ridge, 0.02) * (0.7 + 0.3 * scale) + (2.0 - fl) * 0.02;
        top += 0.006 * kick * sin(uv.x * 80.0 + t * 40.0) * step(1.5, fl);      // tremor on the kick
        if (uv.y > top) {
            float3 rock = mix(mix(BG, A, 0.35) * 0.6, mix(BG, S, 0.3) * 0.9, scale * 0.6 + 0.2);
            // Lit face towards the sun (left of each peak), shadow on the other side.
            rock *= 0.7 + 0.45 * step(local, 0.0) * (1.0 - fl * 0.2);
            // Snow on the tall peaks.
            float snow = smoothstep(0.35, 0.55, hgt) * smoothstep(top + H * 0.12 * hgt, top, uv.y);
            rock = mix(rock, float3(0.95, 0.96, 1.0) * (0.75 + 0.25 * step(local, 0.0)), snow);
            // Rim light where the ridge stands against the sun.
            rock += sunRim * 0.6 * exp(-(uv.y - top) * 160.0) * exp(-abs(uv.x - sunP.x) / (sunR * 1.6)) * (0.4 + 0.6 * scale);
            // Distance haze (towards the sky, not the sun, so the range stays solid).
            rock = mix(rock, sky + sunRim * 0.12 * exp(-abs(uv.x - sunP.x) / (sunR * 2.0)), (2.0 - fl) * 0.22);
            col = rock;
        }
    }
    // Clouds streaming past the summits.
    float cl = fbm3(float2(uv.x * 3.0 - t * 0.05, uv.y * 9.0));
    float band = exp(-sqf((uv.y - (baseY - H * 0.55)) / (H * 0.12)));
    col = mix(col, mix(float3(1.0), S, 0.2), smoothstep(0.5, 0.75, cl) * band * 0.55);
    // The plain glowing at the foot, dust puff on the kick.
    if (uv.y > baseY) {
        float3 plain = mix(mix(BG, A, 0.25), BG * 0.4, smoothstep(baseY, baseY + 0.25, uv.y));
        plain += mix(A, S, 0.5) * 0.25 * step(0.92, fract((uv.x - c.x) / (0.04 + (uv.y - baseY) * 0.6))) * smoothstep(baseY + 0.3, baseY, uv.y);
        col = plain;
    }
    float dust = fbm3(float2(uv.x * 6.0 + t * 0.2, uv.y * 20.0)) * exp(-abs(uv.y - baseY) * 40.0);
    col += float3(1.0, 0.9, 0.8) * dust * kick * 0.5 * k;
    col += mix(A, S, 0.5) * exp(-abs(uv.y - baseY) * 60.0) * (0.2 + 0.4 * uBass * play);

    return half4(finish(col, fc), 1.0);
}
"""

    private const val SPECIMEN_BEAT = """
// Specimen lab (music): the pixel-art lab, with the album cover floating in the glowing tank.
// The fluid glows in the song's colours and brightens with the bass, bubbles boil up faster when
// it's loud, the scan line sweeps on the beat, a kick flashes the tank and shakes the cover, and the
// monitors on both sides show the real music: an oscilloscope, spectrum bars, a beat radar and a
// scrolling readout that runs faster with the highs.
// Shared by the music-reactive scenes (besides "Now playing", which has its own copy): the same
// uniforms NowPlayingScene feeds the music scene - cover, levels, kicks, eight equalizer bands and
// where on screen the visualizer goes - plus the soft cover background.
uniform shader uArt;      // the cover, square and blurred smooth (MusicTheme.softArt)
uniform float2 uArtSize;  // its size in pixels
uniform float uHasArt;    // 0 = no cover yet (or the cover is switched off)
uniform float uBass;      // 0..1, smoothed
uniform float uMid;
uniform float uHigh;
uniform float uBeatAge;   // seconds since the last kick (large = none)
uniform float uPlaying;   // 0..1, fades when paused
uniform float uIntensity; // 0..1, Settings > strength
uniform float4 uEqA;      // bands 0-3 (low), 0..1
uniform float4 uEqB;      // bands 4-7 (high)
uniform float uWaveY;     // 0..1 from the top: where the visualizer sits (Appearance > Equalizer)
uniform float uWaveH;     // room above / below that line (share of the height); the player sits under it
uniform float uWaveX;     // 0..1 from the left: where the visualizer sits across (0 = the middle; the player beside it)
uniform shader uCover;    // the cover, sharp (256 px square) - for the record / disc labels
uniform float2 uCoverSize;
uniform shader uLabel;    // the song's title and artist in dark ink on a clear picture (NowPlayingScene.songLabel)
uniform float2 uLabelSize;
uniform shader uHistory;  // covers of the last songs: a 4 x 2 grid (newest first), MusicTheme.historyAtlas
uniform float uHistCount; // how many of the 8 are filled
uniform float3 uSubject;   // where the cover's subject is: x, y (0..1 across the square) and its size; z = 0 until known (MusicTheme.subject)
// Clocks that only run while the music plays, so spins and scrolls slow down and stop smoothly instead of
// jumping (t * (a + b * level) jumps whenever the level moves). Kept by NowPlayingScene, in seconds:
uniform float uPlayT;     // time spent playing (integral of uPlaying)
uniform float uBassT;     // integral of uBass x uPlaying
uniform float uMidT;      // integral of uMid x uPlaying
uniform float uHighT;     // integral of uHigh x uPlaying

// The visualizer's room, with a sensible size when it isn't set (previews).
float room(float fallback) { return uWaveH > 0.001 ? uWaveH : fallback; }
// Across: the middle, or the left part when the player sits beside the visualizer (MusicPlayerLayout.SIDE).
float waveX(float asp) { return uWaveX > 0.001 ? uWaveX * asp : asp * 0.5; }

float2 mirrorUv(float2 q) { return 1.0 - abs(1.0 - mod(q, 2.0)); }

float eqBand(float i) {
    if (i < 0.5) return uEqA.x;
    if (i < 1.5) return uEqA.y;
    if (i < 2.5) return uEqA.z;
    if (i < 3.5) return uEqA.w;
    if (i < 4.5) return uEqB.x;
    if (i < 5.5) return uEqB.y;
    if (i < 6.5) return uEqB.z;
    return uEqB.w;
}

// The spectrum at m (0 = lowest band, 1 = highest), smoothly interpolated.
float eqAt(float m) {
    float f = clamp(m, 0.0, 1.0) * 7.0;
    float i = floor(f);
    float u = f - i;
    u = u * u * (3.0 - 2.0 * u);
    return mix(eqBand(i), eqBand(min(i + 1.0, 7.0)), u);
}

// Pushes a colour's saturation by s (1 = unchanged) around its own brightness.
float3 vivid(float3 c, float s) {
    float l = dot(c, float3(0.299, 0.587, 0.114));
    return max(mix(float3(l), c, s), 0.0);
}

// The cover, very soft and slowly drifting (or, without one, the palette swirling), dimmed by dim.
float3 coverField(float2 uv, float asp, float t, float bass, float dim, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float zoom = 1.7 + 0.08 * sin(t * 0.045) - 0.05 * bass * uIntensity;
    p = rot(0.05 * sin(t * 0.031)) * p / zoom;
    p += (float2(vnoise(p * 2.0 + float2(t * 0.1, 0.0)), vnoise(p * 2.0 + float2(7.3, -t * 0.08))) - 0.5) * 0.1;
    float2 q = p / max(asp, 1.0) + 0.5;
    float3 art = float3(uArt.eval(mirrorUv(q) * uArtSize).rgb);
    float sw = fbm3(uv * 1.4 + float2(t * 0.03, -t * 0.02));
    float3 noArt = mix(BG * 1.4 + A * 0.08, mix(A, S, sw) * 0.5, smoothstep(0.25, 0.8, sw));
    float3 col = mix(noArt, vivid(art, 1.35) * 0.62, uHasArt);
    return mix(col, BG, 0.14) * dim;
}

// The palette as a living gradient: A and S (the cover's colours) flowing round each other with a
// third, hue-shifted colour, brighter on the beat. A colourful base instead of a near-black one.
float3 paletteField(float2 uv, float asp, float t, float lift, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float n1 = fbm3(p * 1.3 + float2(t * 0.05, -t * 0.04));
    float n2 = fbm3(p * 1.7 + float2(-t * 0.035, t * 0.05) + 4.7);
    float3 C = float3(S.z, A.x, (A.y + S.y) * 0.5); // a third colour from the two
    float3 col = mix(A, S, smoothstep(0.25, 0.75, n1));
    col = mix(col, C, smoothstep(0.45, 0.85, n2) * 0.55);
    col = mix(BG, col, 0.42 + 0.18 * lift);
    return col;
}

// The sharp cover at q (0..1 across the square), or the palette when there's no cover yet.
float3 sharpCover(float2 q, float3 A, float3 S) {
    float3 art = float3(uCover.eval(clamp(q, 0.0, 1.0) * uCoverSize).rgb);
    return mix(mix(A, S, q.y), art, uHasArt);
}

// Where the cover's subject sits (x, y, size), with a sensible guess before it's known.
float3 subjectOf() { return uSubject.z > 0.001 ? uSubject : float3(0.5, 0.45, 0.3); }

// Ink of the song label at q (0..1 across the writing area): 0 = paper, 1 = ink.
float labelInk(float2 q) {
    if (q.x < 0.0 || q.x > 1.0 || q.y < 0.0 || q.y > 1.0) return 0.0;
    return float(uLabel.eval(q * uLabelSize).a);
}

// Cover of an earlier song: i = 0 the one before this, 1 the one before that... (wraps round the
// ones there are; with none yet, the current cover in the song's colours instead).
float3 pastCover(float i, float2 q, float3 A, float3 S) {
    q = clamp(q, 0.0, 1.0);
    if (uHistCount < 0.5) return mix(sharpCover(q, A, S), mix(A, S, q.y), 0.35);
    float n = mod(floor(i), uHistCount);
    float2 tile = float2(mod(n, 4.0), floor(n / 4.0));
    float2 p = (tile + 0.01 + q * 0.98) * 192.0;
    return float3(uHistory.eval(p).rgb);
}

float inRect(float2 p, float2 a, float2 b) {
    return step(a.x, p.x) * step(p.x, b.x) * step(a.y, p.y) * step(p.y, b.y);
}

half4 main(float2 fc) {
    // Everything is drawn on a 180-pixel-tall grid, so it stays chunky pixel art at any size.
    float P = uRes.y / 180.0;
    float2 c = floor(fc / P) + 0.5;
    float W = floor(uRes.x / P);
    float asp = uRes.x / uRes.y;
    float cx = floor(waveX(asp) / asp * W);
    float k = uIntensity;
    float play = uPlaying;
    float bass = uBass * play;
    float kick = exp(-uBeatAge * 5.0) * play;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float3 white = float3(1.0);

    // --- The room: a blue wall, lighter towards the top, panel seams, pipes, big tanks in the dark.
    float3 col = mix(BG * 1.2, mix(BG, S, 0.42), sat(1.0 - c.y / 170.0));
    float seam = step(mod(c.x - cx, 32.0), 1.0) * step(c.y, 112.0);
    col = mix(col, BG * 0.8, seam * 0.5);
    col = mix(col, BG * 0.85, (step(abs(c.y - 22.5), 0.6) + step(abs(c.y - 62.5), 0.6)) * 0.6);
    // Pipes along the ceiling.
    float pipe = inRect(c, float2(0.0, 10.0), float2(W, 15.0));
    col = mix(col, mix(BG, S, 0.6), pipe);
    col = mix(col, mix(S, white, 0.25), inRect(c, float2(0.0, 11.0), float2(W, 11.9)) * 0.6);
    // Pipe clamps.
    col = mix(col, BG * 0.9, pipe * step(mod(c.x, 40.0), 3.0));
    // Background tanks (both sides), with tiny amber windows.
    for (int i = 0; i < 4; i++) {
        float fi = float(i);
        float side = i < 2 ? -1.0 : 1.0;
        float x0 = cx + side * (66.0 + mod(fi, 2.0) * 56.0);
        float hw = 12.0 + mod(fi, 2.0) * 3.0;
        float top = 30.0 + mod(fi, 2.0) * 10.0;
        float body = inRect(c, float2(x0 - hw, top), float2(x0 + hw, 112.0));
        float dome = step(length((c - float2(x0, top)) / float2(hw, 6.0)), 1.0);
        float tank = max(body, dome);
        float shade = 0.5 + 0.5 * sat((c.x - x0 + hw) / (2.0 * hw));
        col = mix(col, mix(BG, S, 0.3 + 0.14 * shade), tank);
        col = mix(col, mix(BG, S, 0.62), tank * step(abs(c.x - (x0 - hw * 0.5)), 0.6) * 0.7);
        float2 win = float2(x0 - 2.0, top + 18.0 + fi * 7.0);
        float blink = step(0.3, fract(sin(fi * 7.1 + floor(t * 0.7 + fi)) * 43.7));
        col = mix(col, float3(1.0, 0.72, 0.3), inRect(c, win, win + float2(1.0, 0.0)) * (0.5 + 0.5 * blink));
        col = mix(col, float3(1.0, 0.72, 0.3), inRect(c, win + float2(3.0, 0.0), win + float2(4.0, 0.0)) * (0.5 + 0.5 * blink));
    }
    // Hanging cables on the right.
    for (int i = 0; i < 2; i++) {
        float fi = float(i);
        float y = 38.0 + fi * 9.0 + 16.0 * sin((c.x - cx) * 0.035 + fi * 1.7) + 1.5 * sin(t * 0.4 + fi);
        col = mix(col, BG * 0.85, step(abs(c.y - y), 0.6) * step(cx + 40.0, c.x) * 0.8);
    }
    // Floor.
    col = mix(col, mix(BG, S, 0.12) * (1.0 - 0.3 * sat((c.y - 150.0) / 30.0)), step(150.0, c.y));
    col = mix(col, mix(BG, S, 0.35), step(abs(c.y - 150.5), 0.6));

    // --- The tank in the middle.
    // The tank fits the room the visualizer was given.
    float rh = clamp(floor(room(0.3) * 180.0 * 0.95), 30.0, 60.0);
    float tw = floor(rh * 0.62);
    float tMid = floor(uWaveY * 180.0);
    float tTop = tMid - rh;
    float tBot = tMid + rh;
    float3 metal = mix(BG, S, 0.62);
    float3 metalLit = mix(S, white, 0.3);
    // Its glow on the room.
    float2 dTank = max(abs(c - float2(cx, (tTop + tBot) * 0.5)) - float2(tw, (tBot - tTop) * 0.5), 0.0);
    col += A * 0.22 * exp(-length(dTank) / 14.0) * (0.6 + 0.6 * bass + 0.5 * kick);
    // Side pillars with little blue lights.
    for (int s = 0; s < 2; s++) {
        float sx = s == 0 ? -1.0 : 1.0;
        float x0 = cx + sx * (tw + 7.0);
        float pil = inRect(c, float2(x0 - 5.0, tTop - 8.0), float2(x0 + 5.0, tBot + 14.0));
        col = mix(col, mix(BG, S, 0.45), pil);
        col = mix(col, metalLit, pil * step(abs(c.x - (x0 - sx * 4.0)), 0.6) * 0.5);
        float2 cell = floor((c - float2(x0 - 3.0, tTop - 2.0)) / float2(4.0, 5.0));
        float2 inCell = c - float2(x0 - 3.0, tTop - 2.0) - cell * float2(4.0, 5.0);
        float lit = step(0.35 - 0.3 * eqAt(sat(cell.y / 18.0)) * play, hash12(cell + float2(sx * 13.0, floor(t * 3.0 + cell.y * 0.3))));
        float light = pil * step(inCell.x, 2.0) * step(inCell.y, 2.0) * step(0.0, cell.x) * step(cell.x, 1.0)
            * step(0.0, cell.y) * step(cell.y, floor((tBot - tTop) / 5.0));
        col = mix(col, mix(S, white, 0.45) * (0.55 + 0.6 * lit), light);
    }
    // Pedestal and the top cap.
    col = mix(col, mix(BG, S, 0.4), inRect(c, float2(cx - tw - 14.0, tBot + 10.0), float2(cx + tw + 14.0, tBot + 22.0)));
    col = mix(col, metal, inRect(c, float2(cx - tw - 4.0, tBot), float2(cx + tw + 4.0, tBot + 10.0)));
    col = mix(col, metal, inRect(c, float2(cx - tw - 4.0, tTop - 8.0), float2(cx + tw + 4.0, tTop)));
    col = mix(col, metalLit, (inRect(c, float2(cx - tw - 4.0, tTop - 8.0), float2(cx + tw + 4.0, tTop - 7.0))
        + inRect(c, float2(cx - tw - 4.0, tBot), float2(cx + tw + 4.0, tBot + 0.9))) * 0.6);
    // Vents on the base.
    col = mix(col, BG * 0.8, inRect(c, float2(cx - tw, tBot + 4.0), float2(cx + tw, tBot + 6.0)) * step(mod(c.x, 4.0), 2.0));
    // The fluid.
    float glass = inRect(c, float2(cx - tw, tTop), float2(cx + tw, tBot));
    if (glass > 0.5) {
        float ly = (c.y - tTop) / (tBot - tTop);
        float lx = (c.x - cx) / tw;
        float3 fluid = mix(mix(A, BG, 0.3), mix(A, S, 0.45) * 0.7, ly) * (0.75 + 0.45 * bass * k) + float3(1.0) * kick * 0.12 * k;
        fluid *= 0.8 + 0.25 * (1.0 - lx * lx);
        // Slow currents.
        fluid += A * 0.08 * step(0.7, vnoise(float2(c.x * 0.12, c.y * 0.05 + t * 0.4)));
        // The cover floating in the fluid, bobbing, shaken by the kick, framed by a thin glow.
        float side = floor(tw * 1.25);
        float2 shake = float2(floor((hash11(floor(t * 24.0)) - 0.5) * 3.0 * kick * k), 0.0);
        float2 cc = float2(cx, tMid + floor(2.5 * sin(t * 0.7))) + shake;
        float2 cq = (c - cc) / side + 0.5;
        float inCov = step(0.0, cq.x) * step(cq.x, 1.0) * step(0.0, cq.y) * step(cq.y, 1.0);
        // Pixelate the cover to the lab's grid.
        float3 cov = sharpCover((floor(cq * side) + 0.5) / side, A, S);
        float edge = step(cq.x, 1.0 / side) + step(1.0 - 1.0 / side, cq.x) + step(cq.y, 1.0 / side) + step(1.0 - 1.0 / side, cq.y);
        fluid = mix(fluid, mix(cov, fluid, 0.12), inCov);
        fluid = mix(fluid, mix(A, white, 0.5), inCov * sat(edge) * (0.5 + 0.5 * kick));
        // Cables holding it.
        float cable = step(abs(abs(c.x - cc.x) - side * 0.3), 0.6) * step(c.y, cc.y - side * 0.5);
        fluid = mix(fluid, mix(BG, A, 0.18), cable * 0.8);
        float pulse = 0.5 + 0.5 * bass;
        // Bubbles rising in a few columns.
        float colId = floor(c.x / 3.0);
        float h = hash11(colId * 3.7);
        if (h > 0.55 - 0.3 * bass) {
            float by = tBot - fract(h * 9.1 + t * (0.12 + 0.12 * h) * (1.0 + 2.0 * bass)) * (tBot - tTop);
            float bx = colId * 3.0 + 1.0 + floor(sin(t * 2.0 + h * 10.0) + 0.5);
            fluid = mix(fluid, mix(A, white, 0.6), inRect(c, float2(bx, by), float2(bx + 1.0, by + 1.0)) * 0.95);
        }
        // Bright bands at the top and bottom, and the scan line sweeping down.
        float dash = step(0.4, fract((c.x + t * 12.0) / 9.0));
        fluid = mix(fluid, mix(A, white, 0.5), (step(abs(c.y - (tTop + 2.5)), 0.6) + step(abs(c.y - (tBot - 3.5)), 0.6)) * dash);
        float scanY = tTop + floor(sat(uBeatAge * 1.4) * (tBot - tTop));
        fluid = mix(fluid, mix(A, white, 0.5), step(abs(c.y - scanY), 0.6) * 0.45);
        // Glass highlights and the edges.
        fluid = mix(fluid, white, (step(abs(c.x - (cx - tw + 4.5)), 0.6) * 0.25 + step(abs(c.x - (cx + tw - 8.5)), 0.6) * 0.12));
        fluid = mix(fluid, mix(S, white, 0.2), step(tw - 1.0, abs(c.x - cx)) * 0.7);
        // Every other pixel row a touch darker - the CRT shimmer.
        fluid *= 0.94 + 0.06 * step(mod(c.y, 2.0), 1.0);
        col = fluid;
    }

    // --- Monitor banks on both sides.
    float bankL = cx - tw - 18.0;
    float bankR = cx + tw + 18.0;
    float onBank = step(c.x, bankL) + step(bankR, c.x);
    // Desks.
    float desk = onBank * inRect(c, float2(0.0, 138.0), float2(W, 158.0));
    col = mix(col, mix(BG, S, 0.34), desk);
    col = mix(col, metalLit, onBank * inRect(c, float2(0.0, 138.0), float2(W, 139.0)) * 0.6);
    col = mix(col, BG * 0.85, desk * step(mod(c.x, 22.0), 0.9));
    // Blinking lights on the desks.
    float2 led = floor(c / float2(5.0, 1.0));
    float ledOn = step(0.45, hash12(float2(led.x, floor(t * 2.0 + hash11(led.x) * 3.0))));
    float3 ledCol = hash11(led.x * 1.3) > 0.6 ? float3(1.0, 0.7, 0.3) : mix(S, white, 0.4);
    col = mix(col, ledCol * (0.4 + 0.7 * ledOn), desk * step(abs(c.y - 145.5), 0.6) * step(mod(c.x, 5.0), 1.0) * step(0.3, hash11(led.x * 2.1)));
    // Monitors: slots of 34 pixels outwards from the tank, each a screen with its own readout.
    float side = c.x < cx ? -1.0 : 1.0;
    float rel = side < 0.0 ? bankL - c.x : c.x - bankR;
    float slot = floor(rel / 34.0);
    float sx0 = slot * 34.0;
    float hs = hash11(slot * 5.3 + side * 17.0);
    float mw = 22.0 + floor(hs * 9.0);
    float mh = 16.0 + floor(hash11(slot * 2.1 + side * 3.0) * 12.0);
    float mTop = 136.0 - mh - floor(hash11(slot * 8.7 + side) * 6.0);
    // Local coordinates inside the monitor (x from its tank-side edge outwards, mirrored on the left).
    float2 m = float2(rel - sx0 - 4.0, c.y - mTop);
    float inMon = onBank * step(0.0, rel) * inRect(m, float2(-2.0, -2.0), float2(mw + 2.0, mh + 2.0));
    if (inMon > 0.5) {
        float3 frame = mix(BG, S, 0.25);
        float3 scr = mix(A, BG, 0.4);
        float3 ink = mix(A, white, 0.5);
        float inner = inRect(m, float2(0.0, 0.0), float2(mw, mh));
        float3 mc = frame;
        if (inner > 0.5) {
            mc = scr;
            float type = floor(hash11(slot * 11.3 + side * 7.0) * 4.0);
            float v = 0.0;
            if (type < 1.0) {
                // A waveform.
                float y = mh * 0.5 + floor(sin(m.x * 0.45 + t * 6.0 + hs * 6.0) * mh * (0.08 + 0.38 * eqAt(sat(m.x / mw)) * play) + 0.5);
                v = step(abs(m.y - y), 0.6);
                v = max(v, step(abs(m.y - mh * 0.5), 0.6) * 0.35 * step(mod(m.x, 2.0), 1.0));
            } else if (type < 2.0) {
                // Bar graph.
                float b = floor(m.x / 4.0);
                float bh = floor((0.1 + 0.88 * eqAt(sat(b * 4.0 / mw)) * play) * (mh - 3.0));
                v = step(mod(m.x, 4.0), 2.0) * step(mh - 2.0 - bh, m.y) * step(m.y, mh - 2.0) * step(1.0, m.x) * step(m.x, mw - 2.0);
            } else if (type < 3.0) {
                // Radar with a crosshair and a sweep.
                float2 rc = m - float2(mw, mh) * 0.5;
                float r = min(mw, mh) * 0.42;
                float d = length(rc);
                v = step(abs(d - r), 0.7) + step(abs(rc.x), 0.5) * step(d, r) * 0.6 + step(abs(rc.y), 0.5) * step(d, r) * 0.6;
                float a = fract(atan(rc.y, rc.x) / TAU - t * 0.3);
                v = max(v, step(d, r) * smoothstep(0.85, 1.0, a) * 0.8);
                float2 blip = float2(cos(hs * 6.0), sin(hs * 6.0)) * r * 0.55;
                v = max(v, step(length(rc - blip), 1.0 + 1.5 * kick) * (0.4 + 0.6 * kick));
            } else {
                // Scrolling readout.
                float row = floor((m.y + floor(4.0 * t + 14.0 * uHighT)) / 3.0);
                float len = 4.0 + floor(hash11(row * 1.7 + slot) * (mw - 8.0));
                v = step(mod(m.y + floor(4.0 * t + 14.0 * uHighT), 3.0), 0.9) * step(2.0, m.x) * step(m.x, len)
                    * step(0.2, hash12(float2(floor(m.x / 3.0), row)));
            }
            mc = mix(mc, ink, sat(v));
            // Screen glow edge and scanlines.
            mc = mix(mc, mix(A, white, 0.4), step(abs(m.y - 0.5), 0.6) * 0.5);
            mc *= 0.9 + 0.1 * step(mod(m.y, 2.0), 1.0);
        }
        col = mc;
    }
    // The monitors light the wall above them a little.
    col += A * 0.05 * onBank * exp(-max(110.0 - c.y, 0.0) / 10.0) * step(c.y, 138.0);

    // A soft vignette.
    float2 vv = fc / uRes - 0.5;
    col *= 1.0 - 0.35 * dot(vv, vv);
    return half4(finish(col, fc), 1.0);
}
"""

    private const val TOWERS_128 = """
// 128-bit towers (music): a boot-screen-style void of the early-2000s consoles - deep blue fog,
// a field of glowing translucent towers of stacked cubes stretching away on a grid - except every
// tower is a band of the equalizer, growing and shrinking with the song. Little lights rise up
// the towers on the beat, the floor's grid ripples out from the middle on each kick, and the album
// cover floats above it all like the console's logo, slowly turning.
// Shared by the music-reactive scenes (besides "Now playing", which has its own copy): the same
// uniforms NowPlayingScene feeds the music scene - cover, levels, kicks, eight equalizer bands and
// where on screen the visualizer goes - plus the soft cover background.
uniform shader uArt;      // the cover, square and blurred smooth (MusicTheme.softArt)
uniform float2 uArtSize;  // its size in pixels
uniform float uHasArt;    // 0 = no cover yet (or the cover is switched off)
uniform float uBass;      // 0..1, smoothed
uniform float uMid;
uniform float uHigh;
uniform float uBeatAge;   // seconds since the last kick (large = none)
uniform float uPlaying;   // 0..1, fades when paused
uniform float uIntensity; // 0..1, Settings > strength
uniform float4 uEqA;      // bands 0-3 (low), 0..1
uniform float4 uEqB;      // bands 4-7 (high)
uniform float uWaveY;     // 0..1 from the top: where the visualizer sits (Appearance > Equalizer)
uniform float uWaveH;     // room above / below that line (share of the height); the player sits under it
uniform float uWaveX;     // 0..1 from the left: where the visualizer sits across (0 = the middle; the player beside it)
uniform shader uCover;    // the cover, sharp (256 px square) - for the record / disc labels
uniform float2 uCoverSize;
uniform shader uLabel;    // the song's title and artist in dark ink on a clear picture (NowPlayingScene.songLabel)
uniform float2 uLabelSize;
uniform shader uHistory;  // covers of the last songs: a 4 x 2 grid (newest first), MusicTheme.historyAtlas
uniform float uHistCount; // how many of the 8 are filled
uniform float3 uSubject;   // where the cover's subject is: x, y (0..1 across the square) and its size; z = 0 until known (MusicTheme.subject)
// Clocks that only run while the music plays, so spins and scrolls slow down and stop smoothly instead of
// jumping (t * (a + b * level) jumps whenever the level moves). Kept by NowPlayingScene, in seconds:
uniform float uPlayT;     // time spent playing (integral of uPlaying)
uniform float uBassT;     // integral of uBass x uPlaying
uniform float uMidT;      // integral of uMid x uPlaying
uniform float uHighT;     // integral of uHigh x uPlaying

// The visualizer's room, with a sensible size when it isn't set (previews).
float room(float fallback) { return uWaveH > 0.001 ? uWaveH : fallback; }
// Across: the middle, or the left part when the player sits beside the visualizer (MusicPlayerLayout.SIDE).
float waveX(float asp) { return uWaveX > 0.001 ? uWaveX * asp : asp * 0.5; }

float2 mirrorUv(float2 q) { return 1.0 - abs(1.0 - mod(q, 2.0)); }

float eqBand(float i) {
    if (i < 0.5) return uEqA.x;
    if (i < 1.5) return uEqA.y;
    if (i < 2.5) return uEqA.z;
    if (i < 3.5) return uEqA.w;
    if (i < 4.5) return uEqB.x;
    if (i < 5.5) return uEqB.y;
    if (i < 6.5) return uEqB.z;
    return uEqB.w;
}

// The spectrum at m (0 = lowest band, 1 = highest), smoothly interpolated.
float eqAt(float m) {
    float f = clamp(m, 0.0, 1.0) * 7.0;
    float i = floor(f);
    float u = f - i;
    u = u * u * (3.0 - 2.0 * u);
    return mix(eqBand(i), eqBand(min(i + 1.0, 7.0)), u);
}

// Pushes a colour's saturation by s (1 = unchanged) around its own brightness.
float3 vivid(float3 c, float s) {
    float l = dot(c, float3(0.299, 0.587, 0.114));
    return max(mix(float3(l), c, s), 0.0);
}

// The cover, very soft and slowly drifting (or, without one, the palette swirling), dimmed by dim.
float3 coverField(float2 uv, float asp, float t, float bass, float dim, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float zoom = 1.7 + 0.08 * sin(t * 0.045) - 0.05 * bass * uIntensity;
    p = rot(0.05 * sin(t * 0.031)) * p / zoom;
    p += (float2(vnoise(p * 2.0 + float2(t * 0.1, 0.0)), vnoise(p * 2.0 + float2(7.3, -t * 0.08))) - 0.5) * 0.1;
    float2 q = p / max(asp, 1.0) + 0.5;
    float3 art = float3(uArt.eval(mirrorUv(q) * uArtSize).rgb);
    float sw = fbm3(uv * 1.4 + float2(t * 0.03, -t * 0.02));
    float3 noArt = mix(BG * 1.4 + A * 0.08, mix(A, S, sw) * 0.5, smoothstep(0.25, 0.8, sw));
    float3 col = mix(noArt, vivid(art, 1.35) * 0.62, uHasArt);
    return mix(col, BG, 0.14) * dim;
}

// The palette as a living gradient: A and S (the cover's colours) flowing round each other with a
// third, hue-shifted colour, brighter on the beat. A colourful base instead of a near-black one.
float3 paletteField(float2 uv, float asp, float t, float lift, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float n1 = fbm3(p * 1.3 + float2(t * 0.05, -t * 0.04));
    float n2 = fbm3(p * 1.7 + float2(-t * 0.035, t * 0.05) + 4.7);
    float3 C = float3(S.z, A.x, (A.y + S.y) * 0.5); // a third colour from the two
    float3 col = mix(A, S, smoothstep(0.25, 0.75, n1));
    col = mix(col, C, smoothstep(0.45, 0.85, n2) * 0.55);
    col = mix(BG, col, 0.42 + 0.18 * lift);
    return col;
}

// The sharp cover at q (0..1 across the square), or the palette when there's no cover yet.
float3 sharpCover(float2 q, float3 A, float3 S) {
    float3 art = float3(uCover.eval(clamp(q, 0.0, 1.0) * uCoverSize).rgb);
    return mix(mix(A, S, q.y), art, uHasArt);
}

// Where the cover's subject sits (x, y, size), with a sensible guess before it's known.
float3 subjectOf() { return uSubject.z > 0.001 ? uSubject : float3(0.5, 0.45, 0.3); }

// Ink of the song label at q (0..1 across the writing area): 0 = paper, 1 = ink.
float labelInk(float2 q) {
    if (q.x < 0.0 || q.x > 1.0 || q.y < 0.0 || q.y > 1.0) return 0.0;
    return float(uLabel.eval(q * uLabelSize).a);
}

// Cover of an earlier song: i = 0 the one before this, 1 the one before that... (wraps round the
// ones there are; with none yet, the current cover in the song's colours instead).
float3 pastCover(float i, float2 q, float3 A, float3 S) {
    q = clamp(q, 0.0, 1.0);
    if (uHistCount < 0.5) return mix(sharpCover(q, A, S), mix(A, S, q.y), 0.35);
    float n = mod(floor(i), uHistCount);
    float2 tile = float2(mod(n, 4.0), floor(n / 4.0));
    float2 p = (tile + 0.01 + q * 0.98) * 192.0;
    return float3(uHistory.eval(p).rgb);
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float px = 1.5 / uRes.y;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float k = uIntensity;
    float play = uPlaying;
    float kick = exp(-uBeatAge * 4.0) * play;

    float2 c = float2(waveX(asp), uWaveY);
    float hz = c.y + room(0.26) * 0.25;          // horizon
    // Void: deep blue fog, brighter towards the horizon.
    float3 fogC = mix(float3(0.05, 0.08, 0.3), mix(A, S, 0.5) * 0.4, 0.25);
    float3 col = mix(BG * 0.5 + float3(0.0, 0.01, 0.05), fogC * 1.6, exp(-abs(uv.y - hz) * 5.0));

    // Floor grid in perspective, rippling on the kick.
    if (uv.y > hz) {
        float z = 0.12 / (uv.y - hz + 0.001);
        float x = (uv.x - c.x) * z;
        float2 g = float2(x, z + t * 0.4);
        float2 gf = abs(fract(g * 2.0) - 0.5);
        float line = 1.0 - smoothstep(0.0, 0.03 * z, min(gf.x, gf.y));
        float ring = exp(-abs(length(float2(x, z * 0.3)) - uBeatAge * 4.0) * 3.0) * kick;
        col += mix(A, S, 0.5) * line * 0.4 * exp(-z * 0.25) * (0.5 + 1.5 * ring);
    }

    // Towers: rows going back; columns across. Each column is a band.
    for (int r = 0; r < 4; r++) {
        float fr = float(r);
        float z = 4.5 - fr * 1.0;                 // far to near
        float sc = 0.12 / z;
        float baseY = hz + sc * 0.45;
        float colW = sc * 0.55;
        float xi = (uv.x - c.x) / colW;
        float id = floor(xi + 0.5);
        if (abs(id) > 9.0) continue;
        float lx = xi - id;
        float m = sat(abs(id) / 9.0);
        float e = eqAt(m) * play;
        float idle = 0.15 + 0.1 * sin(t * 0.5 + id * 0.9 + fr);
        float hgt = mix(idle, 0.1 + e * (0.6 + 0.6 * k), play) * (1.0 + hash11(id + fr * 7.0) * 0.4) * sc * 8.0;
        float topY = baseY - hgt;
        float inT = step(abs(lx), 0.32) * step(topY, uv.y) * step(uv.y, baseY);
        if (inT > 0.5) {
            // Stacked cubes: bands with darker seams, translucent, brighter towards the top.
            float cube = colW * 0.64;
            float yy = (baseY - uv.y) / cube;
            float seam = step(0.9, fract(yy));
            float3 tc = mix(mix(A, S, m), float3(0.6, 0.8, 1.0), 0.35) * (0.35 + 0.5 * sat(yy * cube / max(hgt, 0.001)));
            tc *= 1.0 - 0.45 * seam;
            tc *= 0.75 + 0.35 * step(lx, 0.0);
            // A light climbing the tower on the beat.
            float climb = fract(uBeatAge * 0.8);
            tc += float3(1.0) * exp(-abs(yy * cube / max(hgt, 0.001) - climb) * 30.0) * kick * 0.6;
            float fogK = 1.0 - exp(-z * 0.35);
            col = mix(col, mix(tc, fogC, fogK * 0.7), 0.85);
        }
    }

    // The cover floating above like the logo, slowly turning about its vertical axis.
    float R = room(0.26) * 0.3;
    float2 lc = float2(c.x, c.y - room(0.26) * 0.72);
    float turn = cos(t * 0.5);
    float2 d = uv - lc;
    d.x /= max(abs(turn), 0.06);
    float box = sdRoundBox(d, float2(R), R * 0.06);
    col += mix(A, S, 0.5) * exp(-max(box, 0.0) * 20.0) * (0.25 + 0.5 * kick);
    if (box < px) {
        float2 q = d / (2.0 * R) + 0.5;
        float3 cov = turn > 0.0 ? sharpCover(q, A, S) : mix(A, S, q.y) * 0.6;
        cov *= 0.7 + 0.3 * abs(turn);
        col = mix(col, cov, 1.0 - smoothstep(-px, px, box));
    }
    // Floating particles in the fog.
    col += float3(0.6, 0.8, 1.0) * dots(uv, 30.0, float2(t * 0.01, -t * 0.02), 0.05, 0.06, 4.0) * 0.4;
    return half4(finish(col, fc), 1.0);
}
"""

    private const val CARTRIDGE_16 = """
// 16-bit cartridge (music): a chunky game cartridge plugged into a console, its label printed with
// the album cover - the whole scene drawn on a coarse 16-bit pixel grid with a limited palette. The
// console's power light blinks on the beat, a row of pixel equalizer bars glows in the cartridge
// slot, star sprites twinkle in the dithered sky behind, and the cartridge hops a pixel or two on
// each kick.
// Shared by the music-reactive scenes (besides "Now playing", which has its own copy): the same
// uniforms NowPlayingScene feeds the music scene - cover, levels, kicks, eight equalizer bands and
// where on screen the visualizer goes - plus the soft cover background.
uniform shader uArt;      // the cover, square and blurred smooth (MusicTheme.softArt)
uniform float2 uArtSize;  // its size in pixels
uniform float uHasArt;    // 0 = no cover yet (or the cover is switched off)
uniform float uBass;      // 0..1, smoothed
uniform float uMid;
uniform float uHigh;
uniform float uBeatAge;   // seconds since the last kick (large = none)
uniform float uPlaying;   // 0..1, fades when paused
uniform float uIntensity; // 0..1, Settings > strength
uniform float4 uEqA;      // bands 0-3 (low), 0..1
uniform float4 uEqB;      // bands 4-7 (high)
uniform float uWaveY;     // 0..1 from the top: where the visualizer sits (Appearance > Equalizer)
uniform float uWaveH;     // room above / below that line (share of the height); the player sits under it
uniform float uWaveX;     // 0..1 from the left: where the visualizer sits across (0 = the middle; the player beside it)
uniform shader uCover;    // the cover, sharp (256 px square) - for the record / disc labels
uniform float2 uCoverSize;
uniform shader uLabel;    // the song's title and artist in dark ink on a clear picture (NowPlayingScene.songLabel)
uniform float2 uLabelSize;
uniform shader uHistory;  // covers of the last songs: a 4 x 2 grid (newest first), MusicTheme.historyAtlas
uniform float uHistCount; // how many of the 8 are filled
uniform float3 uSubject;   // where the cover's subject is: x, y (0..1 across the square) and its size; z = 0 until known (MusicTheme.subject)
// Clocks that only run while the music plays, so spins and scrolls slow down and stop smoothly instead of
// jumping (t * (a + b * level) jumps whenever the level moves). Kept by NowPlayingScene, in seconds:
uniform float uPlayT;     // time spent playing (integral of uPlaying)
uniform float uBassT;     // integral of uBass x uPlaying
uniform float uMidT;      // integral of uMid x uPlaying
uniform float uHighT;     // integral of uHigh x uPlaying

// The visualizer's room, with a sensible size when it isn't set (previews).
float room(float fallback) { return uWaveH > 0.001 ? uWaveH : fallback; }
// Across: the middle, or the left part when the player sits beside the visualizer (MusicPlayerLayout.SIDE).
float waveX(float asp) { return uWaveX > 0.001 ? uWaveX * asp : asp * 0.5; }

float2 mirrorUv(float2 q) { return 1.0 - abs(1.0 - mod(q, 2.0)); }

float eqBand(float i) {
    if (i < 0.5) return uEqA.x;
    if (i < 1.5) return uEqA.y;
    if (i < 2.5) return uEqA.z;
    if (i < 3.5) return uEqA.w;
    if (i < 4.5) return uEqB.x;
    if (i < 5.5) return uEqB.y;
    if (i < 6.5) return uEqB.z;
    return uEqB.w;
}

// The spectrum at m (0 = lowest band, 1 = highest), smoothly interpolated.
float eqAt(float m) {
    float f = clamp(m, 0.0, 1.0) * 7.0;
    float i = floor(f);
    float u = f - i;
    u = u * u * (3.0 - 2.0 * u);
    return mix(eqBand(i), eqBand(min(i + 1.0, 7.0)), u);
}

// Pushes a colour's saturation by s (1 = unchanged) around its own brightness.
float3 vivid(float3 c, float s) {
    float l = dot(c, float3(0.299, 0.587, 0.114));
    return max(mix(float3(l), c, s), 0.0);
}

// The cover, very soft and slowly drifting (or, without one, the palette swirling), dimmed by dim.
float3 coverField(float2 uv, float asp, float t, float bass, float dim, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float zoom = 1.7 + 0.08 * sin(t * 0.045) - 0.05 * bass * uIntensity;
    p = rot(0.05 * sin(t * 0.031)) * p / zoom;
    p += (float2(vnoise(p * 2.0 + float2(t * 0.1, 0.0)), vnoise(p * 2.0 + float2(7.3, -t * 0.08))) - 0.5) * 0.1;
    float2 q = p / max(asp, 1.0) + 0.5;
    float3 art = float3(uArt.eval(mirrorUv(q) * uArtSize).rgb);
    float sw = fbm3(uv * 1.4 + float2(t * 0.03, -t * 0.02));
    float3 noArt = mix(BG * 1.4 + A * 0.08, mix(A, S, sw) * 0.5, smoothstep(0.25, 0.8, sw));
    float3 col = mix(noArt, vivid(art, 1.35) * 0.62, uHasArt);
    return mix(col, BG, 0.14) * dim;
}

// The palette as a living gradient: A and S (the cover's colours) flowing round each other with a
// third, hue-shifted colour, brighter on the beat. A colourful base instead of a near-black one.
float3 paletteField(float2 uv, float asp, float t, float lift, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float n1 = fbm3(p * 1.3 + float2(t * 0.05, -t * 0.04));
    float n2 = fbm3(p * 1.7 + float2(-t * 0.035, t * 0.05) + 4.7);
    float3 C = float3(S.z, A.x, (A.y + S.y) * 0.5); // a third colour from the two
    float3 col = mix(A, S, smoothstep(0.25, 0.75, n1));
    col = mix(col, C, smoothstep(0.45, 0.85, n2) * 0.55);
    col = mix(BG, col, 0.42 + 0.18 * lift);
    return col;
}

// The sharp cover at q (0..1 across the square), or the palette when there's no cover yet.
float3 sharpCover(float2 q, float3 A, float3 S) {
    float3 art = float3(uCover.eval(clamp(q, 0.0, 1.0) * uCoverSize).rgb);
    return mix(mix(A, S, q.y), art, uHasArt);
}

// Where the cover's subject sits (x, y, size), with a sensible guess before it's known.
float3 subjectOf() { return uSubject.z > 0.001 ? uSubject : float3(0.5, 0.45, 0.3); }

// Ink of the song label at q (0..1 across the writing area): 0 = paper, 1 = ink.
float labelInk(float2 q) {
    if (q.x < 0.0 || q.x > 1.0 || q.y < 0.0 || q.y > 1.0) return 0.0;
    return float(uLabel.eval(q * uLabelSize).a);
}

// Cover of an earlier song: i = 0 the one before this, 1 the one before that... (wraps round the
// ones there are; with none yet, the current cover in the song's colours instead).
float3 pastCover(float i, float2 q, float3 A, float3 S) {
    q = clamp(q, 0.0, 1.0);
    if (uHistCount < 0.5) return mix(sharpCover(q, A, S), mix(A, S, q.y), 0.35);
    float n = mod(floor(i), uHistCount);
    float2 tile = float2(mod(n, 4.0), floor(n / 4.0));
    float2 p = (tile + 0.01 + q * 0.98) * 192.0;
    return float3(uHistory.eval(p).rgb);
}

half4 main(float2 fc) {
    float P = uRes.y / 160.0;
    float2 g = floor(fc / P) + 0.5;           // 16-bit pixel grid, 160 rows tall
    float W = floor(uRes.x / P);
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float k = uIntensity;
    float play = uPlaying;
    float kick = exp(-uBeatAge * 5.0) * play;
    float asp = uRes.x / uRes.y;
    float cx = floor(waveX(asp) / asp * W);
    float cy = floor(uWaveY * 160.0);
    float rm = clamp(floor(room(0.3) * 160.0), 26.0, 60.0);

    // Dithered sky gradient in four bands.
    float yy = g.y / 160.0;
    float lvl = yy * 4.0 + (mod(g.x + g.y, 2.0) - 0.5) * 0.5;
    float band = floor(lvl);
    float3 col = mix(BG * 0.5, mix(BG, A, 0.35), sat(band / 3.0));
    // Twinkling star sprites (plus shapes).
    float2 sc = floor(g / 12.0);
    float2 sl = g - sc * 12.0 - 6.0;
    float sh = hash12(sc);
    float tw = step(0.5, fract(t * (0.5 + sh) + sh * 7.0));
    float star = step(0.93, sh) * (step(abs(sl.x), 0.5) * step(abs(sl.y), 0.5 + tw) + step(abs(sl.y), 0.5) * step(abs(sl.x), 0.5 + tw));
    col = mix(col, mix(S, float3(1.0), 0.6), sat(star) * step(g.y, cy - rm * 0.2));

    // Console body (bottom part), slot on top.
    float conW = floor(rm * 1.5);
    float conTop = cy + floor(rm * 0.35);
    float conBot = conTop + floor(rm * 0.55);
    float inCon = step(abs(g.x - cx), conW) * step(conTop, g.y) * step(g.y, conBot);
    float3 conC = mix(float3(0.62, 0.62, 0.66), float3(0.42, 0.42, 0.48), step(conTop + 3.0, g.y));
    conC = mix(conC, float3(0.25, 0.25, 0.3), step(conBot - 2.0, g.y));
    col = mix(col, conC, inCon);
    // Vents and the power light.
    col = mix(col, float3(0.2, 0.2, 0.24), inCon * step(abs(g.x - cx - conW * 0.5), conW * 0.3) * step(conTop + 6.0, g.y) * step(g.y, conBot - 5.0) * step(mod(g.y, 3.0), 0.9));
    float led = step(abs(g.x - (cx - conW + 6.0)), 1.0) * step(abs(g.y - (conTop + 6.0)), 1.0);
    col = mix(col, mix(float3(0.4, 0.05, 0.05), float3(1.0, 0.2, 0.2), 0.3 + 0.7 * kick), led);
    // EQ bars glowing in the slot.
    float slotW = floor(rm * 0.95);
    float inSlot = step(abs(g.x - cx), slotW) * step(conTop - 1.0, g.y) * step(g.y, conTop + 1.0);
    float bi = floor((g.x - cx + slotW) / 4.0);
    float e = eqAt(sat(abs(bi - slotW / 4.0) / (slotW / 4.0))) * play;
    col = mix(col, mix(A, S, e), inSlot * step(1.0, mod(g.x - cx + slotW, 4.0)) * (0.3 + 0.7 * step(0.25, e)));

    // The cartridge, hopping on the kick.
    float hop = floor(2.0 * kick * k);
    float cw = floor(rm * 0.85);
    float ch = floor(rm * 1.05);
    float cTop = conTop - ch - hop;
    float2 cl = g - float2(cx, cTop);
    float inCart = step(abs(cl.x), cw) * step(0.0, cl.y) * step(cl.y, ch);
    // Notched top corners and grip ridges.
    inCart *= 1.0 - step(cw - 3.0, abs(cl.x)) * step(cl.y, 3.0);
    float3 cart = float3(0.32, 0.32, 0.36);
    cart = mix(cart, float3(0.22, 0.22, 0.26), step(mod(cl.y, 3.0), 0.9) * step(cl.y, 7.0) * step(abs(cl.x), cw - 4.0));
    // Outline.
    float outl = inCart * (step(cw - 0.6, abs(cl.x)) + step(ch - 0.6, cl.y));
    col = mix(col, cart, inCart);
    col = mix(col, float3(0.08), sat(outl));
    // The label: the album cover, quantised to a 16-bit palette.
    float lw = cw - 5.0;
    float ltop = 10.0;
    float lh = ch - ltop - 6.0;
    float2 lq = (cl - float2(-lw, ltop)) / float2(2.0 * lw, lh);
    float inLab = step(0.0, lq.x) * step(lq.x, 1.0) * step(0.0, lq.y) * step(lq.y, 1.0) * inCart;
    float3 lab = sharpCover((floor(lq * float2(2.0 * lw, lh)) + 0.5) / float2(2.0 * lw, lh), A, S);
    lab = floor(lab * 5.0 + 0.5) / 5.0;
    col = mix(col, lab, inLab);
    // A shine pixel line on the label.
    col = mix(col, float3(1.0), inLab * step(abs(lq.x + lq.y * 0.6 - fract(t * 0.2) * 2.0 + 0.3), 0.012) * 0.6);

    return half4(finish(col, fc), 1.0);
}
