// The Voltcap mark, shared by the Voltcap scenes: the capsule (half width 1, half height VR in its own
// units) and the bolt inside it - the same shapes as the start-up animation (VoltcapIntro).
const float VR = 0.44;

float sdCapsuleMark(float2 q) { return sdRoundBox(q, float2(1.0, VR), VR); }

// One edge of a polygon for its signed distance (squared distance, and 1 when it flips the inside test).
float2 polyEdge(float2 p, float2 vi, float2 vj) {
    float2 e = vj - vi;
    float2 w = p - vi;
    float2 b = w - e * sat(dot(w, e) / dot(e, e));
    float c1 = step(vi.y, p.y);
    float c2 = 1.0 - step(vj.y, p.y);
    float c3 = step(e.y * w.x, e.x * w.y);
    return float2(dot(b, b), c1 * c2 * c3 + (1.0 - c1) * (1.0 - c2) * (1.0 - c3));
}

// The bolt (capsule units; y down), signed distance.
float sdBoltMark(float2 p) {
    float2 v0 = float2(0.13, -0.33);
    float2 v1 = float2(-0.17, 0.045);
    float2 v2 = float2(-0.015, 0.045);
    float2 v3 = float2(-0.11, 0.33);
    float2 v4 = float2(0.19, -0.055);
    float2 v5 = float2(0.035, -0.055);
    float d = dot(p - v0, p - v0);
    float flips = 0.0;
    float2 r;
    r = polyEdge(p, v0, v5); d = min(d, r.x); flips += r.y;
    r = polyEdge(p, v1, v0); d = min(d, r.x); flips += r.y;
    r = polyEdge(p, v2, v1); d = min(d, r.x); flips += r.y;
    r = polyEdge(p, v3, v2); d = min(d, r.x); flips += r.y;
    r = polyEdge(p, v4, v3); d = min(d, r.x); flips += r.y;
    r = polyEdge(p, v5, v4); d = min(d, r.x); flips += r.y;
    float s = mod(flips, 2.0) > 0.5 ? -1.0 : 1.0;
    return s * sqrt(d);
}

// A point on the capsule's outline at angle a (close enough to the real outline for sparks).
float2 capsulePoint(float a) {
    return float2(clamp(1.35 * cos(a), -1.0, 1.0) * (1.0 - VR), 0.0) + VR * float2(cos(a), sin(a));
}

float3 sprite(float2 local, float kind, float3 A, float3 S, out float a) {
    // local: -0.5..0.5 across a 32x32 sprite.
    float2 pix = (floor((local + 0.5) * 32.0) + 0.5) / 32.0 - 0.5;
    float2 pq = pix * 2.2;
    float dShape = kind < 0.5 ? sdCapsuleMark(pq) : sdBoltMark(pq * 0.42);
    float pxs = 2.2 / 32.0 * (kind < 0.5 ? 1.0 : 0.42);
    float inside = step(dShape, 0.0);
    float outline = step(dShape, pxs * 1.1) * (1.0 - inside);
    a = sat(inside + outline);
    float3 body;
    if (kind < 0.5) {
        body = mix(A * 0.8, A * 1.15, step(pq.y, 0.0));
        body = mix(body, mix(S, float3(1.0), 0.3), step(sdBoltMark(pq * 0.85), 0.0));
    } else {
        body = mix(S * 0.85, mix(S, float3(1.0), 0.45), step(pq.x + pq.y * 0.5, 0.0));
    }
    body += float3(1.0) * 0.25 * step(pix.y, -0.28) * step(pix.x, -0.1) * inside;
    return mix(float3(0.05, 0.04, 0.06), body, inside);
}

half4 main(float2 fc) {
    float P = uRes.y / 180.0;
    float2 g = floor(fc / P) + 0.5;
    float2 uv = g * P / uRes.y;                 // pixel-snapped uv
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float k = uIntensity;
    float play = uPlaying;
    float bass = uBass * play;
    float kick = exp(-uBeatAge * 6.0) * play;

    float2 c = float2(waveX(asp), uWaveY);
    float R = room(0.3);
    float floorY = c.y + R * 0.55;
    float3 col = mix(BG * 0.6, BG * 1.2 + A * 0.05, uv.y);
    float2 ck = floor(uv * 30.0);
    col *= 0.94 + 0.06 * mod(ck.x + ck.y, 2.0);

    // Pixel spotlights swinging from the top.
    for (int i = 0; i < 2; i++) {
        float fi = float(i);
        float2 o = float2(c.x + (fi - 0.5) * asp * 0.6, 0.0);
        float ang = (fi - 0.5) * -0.6 + sin(t * 1.2 + fi * 2.0) * 0.35;
        float2 dir = float2(sin(ang), cos(ang));
        float2 rel = uv - o;
        float along = dot(rel, dir);
        float across = abs(dot(rel, float2(-dir.y, dir.x)));
        float beam = step(across, 0.02 + along * 0.15) * step(0.0, along) * step(along, floorY + 0.1);
        col += (fi < 0.5 ? A : S) * beam * (0.1 + 0.15 * kick) * step(0.5, mod(g.x + g.y, 2.0) + 0.5);
    }

    // The cover as a pixel banner above the stage.
    float bw = R * 0.6;
    float2 bc = float2(c.x, c.y - R * 0.5);
    float2 bq = (uv - bc) / (2.0 * bw) + 0.5;
    float inBan = step(0.0, bq.x) * step(bq.x, 1.0) * step(0.0, bq.y) * step(bq.y, 1.0);
    float3 ban = sharpCover((floor(bq * 32.0) + 0.5) / 32.0, A, S);
    ban = floor(ban * 6.0 + 0.5) / 6.0;
    col = mix(col, ban, inBan);
    float frameB = inBan * (step(bq.x, 1.0 / 32.0) + step(31.0 / 32.0, bq.x) + step(bq.y, 1.0 / 32.0) + step(31.0 / 32.0, bq.y));
    col = mix(col, mix(A, float3(1.0), 0.5), sat(frameB));

    // Dance floor: tiles lighting with the bass.
    if (uv.y > floorY) {
        float2 tile = floor((uv - float2(c.x, floorY)) / 0.05);
        float lit = step(0.6 - 0.4 * bass, hash12(tile + floor(t * 4.0 - uBeatAge)));
        col = mix(BG * 0.7 + mix(A, S, 0.5) * 0.05, mix(A, S, hash12(tile)), lit * (0.2 + 0.5 * bass));
        float2 tf = fract((uv - float2(c.x, floorY)) / 0.05);
        col *= 0.8 + 0.2 * step(0.1, min(tf.x, tf.y));
    }

    // The dancers: a row of sprites, each on its band.
    float size = R * 0.62;
    float n = 7.0;
    float span = min(asp * 0.85, size * 9.0);
    for (int i = 0; i < 7; i++) {
        float fi = float(i);
        float x = c.x + (fi / (n - 1.0) - 0.5) * span;
        float m = abs(fi / (n - 1.0) - 0.5) * 2.0;
        float e = eqAt(1.0 - m) * play;
        // Hop on the beat, height from the band; idle bob when nothing plays.
        float ph = uBeatAge * 3.0 + fi * 0.05;
        float hop = play > 0.05 ? sat(1.0 - ph) * (0.3 + 0.7 * e) * (0.5 + 0.6 * k) * sin(sat(ph) * PI) : abs(sin(t * 1.5 + fi)) * 0.3;
        float land = sat(1.0 - ph * 6.0) * play;
        float2 base = float2(x, floorY);
        float2 pos = base - float2(0.0, size * 0.5 + hop * size * 0.9);
        float2 sh = (uv - base) / float2(size * 0.5 * (1.0 - hop * 0.4), size * 0.08);
        col *= 1.0 - 0.4 * (1.0 - smoothstep(0.7, 1.0, length(sh)));
        float2 sq = float2(1.0 + 0.2 * land, 1.0 - 0.2 * land);
        float2 local = (uv - pos) / (size * sq);
        if (abs(local.x) < 0.55 && abs(local.y) < 0.55) {
            float a;
            float3 sp = sprite(local, mod(fi, 2.0), A, S, a);
            col = mix(col, sp, a);
        }
    }
    col += mix(S, float3(1.0), 0.5) * dots(uv, 18.0, float2(0.0), 0.05, 0.05, 11.0) * (0.3 + 0.6 * kick);
    return half4(finish(col, fc), 1.0);
}
"""

    private const val CAMPFIRE_BEAT = """
// Campfire (music): a campfire in a clearing at night that plays along with the song. The flames
// are an equalizer - each tongue of fire is a band, leaping with its part of the spectrum - sparks
// burst up on every kick and drift off into the stars, the glow breathes over the ground and the
// pine silhouettes with the bass, and the smoke curls faster when it's loud. The cover glows softly
// in the night sky like a moon.
// Shared by the music-reactive scenes (besides "Now playing", which has its own copy): the same
// uniforms NowPlayingScene feeds the music scene - cover, levels, kicks, eight equalizer bands and
// where on screen the visualizer goes - plus the soft cover background.
uniform shader uArt;      // the cover, square and blurred smooth (MusicTheme.softArt)
uniform float2 uArtSize;  // its size in pixels
uniform float uHasArt;    // 0 = no cover yet (or the cover is switched off)
uniform float uBass;      // 0..1, smoothed
uniform float uMid;
uniform float uHigh;
uniform float uBeatAge;   // seconds since the last kick (large = none)
uniform float uPlaying;   // 0..1, fades when paused
uniform float uIntensity; // 0..1, Settings > strength
uniform float4 uEqA;      // bands 0-3 (low), 0..1
uniform float4 uEqB;      // bands 4-7 (high)
uniform float uWaveY;     // 0..1 from the top: where the visualizer sits (Appearance > Equalizer)
uniform float uWaveH;     // room above / below that line (share of the height); the player sits under it
uniform float uWaveX;     // 0..1 from the left: where the visualizer sits across (0 = the middle; the player beside it)
uniform shader uCover;    // the cover, sharp (256 px square) - for the record / disc labels
uniform float2 uCoverSize;
uniform shader uLabel;    // the song's title and artist in dark ink on a clear picture (NowPlayingScene.songLabel)
uniform float2 uLabelSize;
uniform shader uHistory;  // covers of the last songs: a 4 x 2 grid (newest first), MusicTheme.historyAtlas
uniform float uHistCount; // how many of the 8 are filled
uniform float3 uSubject;   // where the cover's subject is: x, y (0..1 across the square) and its size; z = 0 until known (MusicTheme.subject)
// Clocks that only run while the music plays, so spins and scrolls slow down and stop smoothly instead of
// jumping (t * (a + b * level) jumps whenever the level moves). Kept by NowPlayingScene, in seconds:
uniform float uPlayT;     // time spent playing (integral of uPlaying)
uniform float uBassT;     // integral of uBass x uPlaying
uniform float uMidT;      // integral of uMid x uPlaying
uniform float uHighT;     // integral of uHigh x uPlaying

// The visualizer's room, with a sensible size when it isn't set (previews).
float room(float fallback) { return uWaveH > 0.001 ? uWaveH : fallback; }
// Across: the middle, or the left part when the player sits beside the visualizer (MusicPlayerLayout.SIDE).
float waveX(float asp) { return uWaveX > 0.001 ? uWaveX * asp : asp * 0.5; }

float2 mirrorUv(float2 q) { return 1.0 - abs(1.0 - mod(q, 2.0)); }

float eqBand(float i) {
    if (i < 0.5) return uEqA.x;
    if (i < 1.5) return uEqA.y;
    if (i < 2.5) return uEqA.z;
    if (i < 3.5) return uEqA.w;
    if (i < 4.5) return uEqB.x;
    if (i < 5.5) return uEqB.y;
    if (i < 6.5) return uEqB.z;
    return uEqB.w;
}

// The spectrum at m (0 = lowest band, 1 = highest), smoothly interpolated.
float eqAt(float m) {
    float f = clamp(m, 0.0, 1.0) * 7.0;
    float i = floor(f);
    float u = f - i;
    u = u * u * (3.0 - 2.0 * u);
    return mix(eqBand(i), eqBand(min(i + 1.0, 7.0)), u);
}

// Pushes a colour's saturation by s (1 = unchanged) around its own brightness.
float3 vivid(float3 c, float s) {
    float l = dot(c, float3(0.299, 0.587, 0.114));
    return max(mix(float3(l), c, s), 0.0);
}

// The cover, very soft and slowly drifting (or, without one, the palette swirling), dimmed by dim.
float3 coverField(float2 uv, float asp, float t, float bass, float dim, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float zoom = 1.7 + 0.08 * sin(t * 0.045) - 0.05 * bass * uIntensity;
    p = rot(0.05 * sin(t * 0.031)) * p / zoom;
    p += (float2(vnoise(p * 2.0 + float2(t * 0.1, 0.0)), vnoise(p * 2.0 + float2(7.3, -t * 0.08))) - 0.5) * 0.1;
    float2 q = p / max(asp, 1.0) + 0.5;
    float3 art = float3(uArt.eval(mirrorUv(q) * uArtSize).rgb);
    float sw = fbm3(uv * 1.4 + float2(t * 0.03, -t * 0.02));
    float3 noArt = mix(BG * 1.4 + A * 0.08, mix(A, S, sw) * 0.5, smoothstep(0.25, 0.8, sw));
    float3 col = mix(noArt, vivid(art, 1.35) * 0.62, uHasArt);
    return mix(col, BG, 0.14) * dim;
}

// The palette as a living gradient: A and S (the cover's colours) flowing round each other with a
// third, hue-shifted colour, brighter on the beat. A colourful base instead of a near-black one.
float3 paletteField(float2 uv, float asp, float t, float lift, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float n1 = fbm3(p * 1.3 + float2(t * 0.05, -t * 0.04));
    float n2 = fbm3(p * 1.7 + float2(-t * 0.035, t * 0.05) + 4.7);
    float3 C = float3(S.z, A.x, (A.y + S.y) * 0.5); // a third colour from the two
    float3 col = mix(A, S, smoothstep(0.25, 0.75, n1));
    col = mix(col, C, smoothstep(0.45, 0.85, n2) * 0.55);
    col = mix(BG, col, 0.42 + 0.18 * lift);
    return col;
}

// The sharp cover at q (0..1 across the square), or the palette when there's no cover yet.
float3 sharpCover(float2 q, float3 A, float3 S) {
    float3 art = float3(uCover.eval(clamp(q, 0.0, 1.0) * uCoverSize).rgb);
    return mix(mix(A, S, q.y), art, uHasArt);
}

// Where the cover's subject sits (x, y, size), with a sensible guess before it's known.
float3 subjectOf() { return uSubject.z > 0.001 ? uSubject : float3(0.5, 0.45, 0.3); }

// Ink of the song label at q (0..1 across the writing area): 0 = paper, 1 = ink.
float labelInk(float2 q) {
    if (q.x < 0.0 || q.x > 1.0 || q.y < 0.0 || q.y > 1.0) return 0.0;
    return float(uLabel.eval(q * uLabelSize).a);
}

// Cover of an earlier song: i = 0 the one before this, 1 the one before that... (wraps round the
// ones there are; with none yet, the current cover in the song's colours instead).
float3 pastCover(float i, float2 q, float3 A, float3 S) {
    q = clamp(q, 0.0, 1.0);
    if (uHistCount < 0.5) return mix(sharpCover(q, A, S), mix(A, S, q.y), 0.35);
    float n = mod(floor(i), uHistCount);
    float2 tile = float2(mod(n, 4.0), floor(n / 4.0));
    float2 p = (tile + 0.01 + q * 0.98) * 192.0;
    return float3(uHistory.eval(p).rgb);
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float px = 1.5 / uRes.y;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float k = uIntensity;
    float play = uPlaying;
    float bass = uBass * play;
    float kick = exp(-uBeatAge * 4.0) * play;

    float2 c = float2(waveX(asp), uWaveY);
    float R = room(0.3);
    float2 fire = float2(c.x, c.y + R * 0.75);
    float3 FIRE = mix(float3(1.0, 0.55, 0.15), A, 0.3);

    // Night sky with stars.
    float3 col = mix(BG * 0.3, BG * 0.7, uv.y);
    col += float3(1.0) * dots(uv, 70.0, float2(t * 0.002, 0.0), 0.25, 0.04, 1.0) * 0.6 * (1.0 - uv.y);
    // The cover as a moon.
    float2 mp = float2(c.x + asp * 0.3, c.y - R * 0.7);
    float mr = R * 0.32;
    float md = length(uv - mp);
    col += mix(S, float3(1.0), 0.5) * exp(-md * 10.0) * 0.18;
    if (md < mr) {
        float3 cov = sharpCover((uv - mp) / (2.0 * mr) + 0.5, A, S);
        col = mix(col, cov * 0.85 + 0.1, 1.0 - smoothstep(mr - px, mr, md));
    }
    // Pine silhouettes in two rows: tiered trees (stacked, drooping boughs) of different heights,
    // the near row lit warm from below by the fire.
    float glowAmt = 0.5 + 0.5 * bass + 0.3 * kick;
    for (int i = 0; i < 2; i++) {
        float fi = float(i);
        float sc = 9.0 - fi * 3.5;                       // trees per screen height (near row larger)
        float x = uv.x * sc + fi * 3.7;
        float id = floor(x);
        float lx = fract(x) - 0.5 - (hash11(id + fi * 5.0) - 0.5) * 0.3;
        float base = fire.y + 0.01 + 0.015 * fi;
        float th = (0.16 + 0.14 * hash11(id * 1.7 + fi * 9.0)) * (1.0 + 0.5 * fi);
        float yy = (base - uv.y) / th;                   // 0 at the base, 1 at the tip
        // Five tiers: each widens downward, then steps in.
        float tier = fract(yy * 5.0);
        float wd = (1.0 - yy) * 0.42 * (0.35 + 0.65 * tier) + 0.012;
        float droop = 0.03 * (1.0 - tier);
        float tree = step(0.0, yy) * step(yy, 1.0) * step(abs(lx) + droop * 0.0, wd);
        float trunk = step(abs(lx), 0.03) * step(-0.02, yy) * step(yy, 0.1);
        float m = max(tree, trunk) * step(hash11(id * 3.3 + fi), 0.8 + 0.2 * fi);
        float warm = exp(-abs(uv.x - fire.x) * (3.0 - fi)) * (0.3 + 0.7 * sat(1.0 - yy)) * fi;
        float3 tc = BG * (0.12 + 0.08 * fi) + FIRE * 0.2 * glowAmt * warm;
        tc += mix(S, float3(1.0), 0.5) * 0.05 * step(0.0, lx) * (1.0 - fi);  // moonlit side, far row
        col = mix(col, tc, m);
    }
    // Ground lit by the fire.
    if (uv.y > fire.y) {
        float3 g = BG * 0.2;
        g += FIRE * 0.45 * glowAmt * exp(-length((uv - fire) * float2(0.6, 2.2)) * 3.5);
        col = g;
    }
    // Flames: one living fire whose height across follows the spectrum (bass in the middle, highs
    // at the sides). Noise rising through it splits the top into licking tongues; colour runs from a
    // white-hot heart through yellow and orange to deep red at the ragged edges.
    float2 fp = uv - fire;
    float FW = 0.15 * (0.7 + 0.6 * R / 0.3);
    float up = -fp.y;
    if (up > -0.03 && abs(fp.x) < FW * 1.4 && up < 0.75) {
        float xn = fp.x / FW;
        float e = eqAt(abs(xn)) * play;
        float H = (0.1 + 0.3 * e * (0.5 + 0.7 * k) + 0.06 * kick) * (1.0 - 0.45 * xn * xn) * (0.7 + 0.6 * R / 0.3);
        H = max(H, 0.04);
        // Sway: the whole fire leans and wobbles more the higher it goes.
        float sway = (vnoise(float2(t * 0.8, up * 3.0)) - 0.5) * 0.06 * up / H;
        float xd = fp.x - sway;
        float n = fbm3(float2(xd * 11.0, up * 6.0 - t * 3.2));
        float n2 = vnoise(float2(xd * 26.0, up * 14.0 - t * 6.0));
        float Hl = H * (0.55 + 0.9 * n);
        float w = FW * (1.05 - 0.55 * sat(up / H)) * (0.85 + 0.3 * n2);
        float across = 1.0 - smoothstep(0.55, 1.0, abs(xd) / max(w, 0.001));
        float T = sat(1.0 - max(up, 0.0) / Hl) * across;
        T *= 0.8 + 0.4 * n2;
        T = sat(T * (1.0 + 0.25 * kick) + smoothstep(0.0, -0.03, up) * across * 0.4);
        float3 red = mix(float3(0.55, 0.06, 0.02), A * 0.6, 0.15);
        float3 orange = mix(float3(1.0, 0.42, 0.08), FIRE, 0.25);
        float3 yellow = float3(1.0, 0.82, 0.32);
        float3 white = float3(1.0, 0.97, 0.86);
        float3 fc3 = mix(red, orange, smoothstep(0.08, 0.35, T));
        fc3 = mix(fc3, yellow, smoothstep(0.38, 0.68, T));
        fc3 = mix(fc3, white, smoothstep(0.72, 0.95, T));
        float alpha = smoothstep(0.03, 0.2, T);
        col = mix(col, fc3, alpha * 0.92);
        col += orange * smoothstep(0.0, 0.1, T) * 0.12;
    }
    // Logs.
    float l1 = sdSegment(uv, fire + float2(-0.08, 0.025), fire + float2(0.08, -0.005)) - 0.012;
    float l2 = sdSegment(uv, fire + float2(-0.08, -0.005), fire + float2(0.08, 0.025)) - 0.012;
    col = mix(col, float3(0.18, 0.1, 0.06) + FIRE * 0.15 * glowAmt, 1.0 - smoothstep(0.0, px, min(l1, l2)));

    // Embers glowing in the bed under the logs.
    float bed = exp(-length((uv - fire - float2(0.0, 0.012)) * float2(0.9, 4.0)) * 22.0);
    col += mix(float3(1.0, 0.35, 0.05), FIRE, 0.3) * bed * (0.5 + 0.4 * vnoise(float2(uv.x * 60.0, t * 2.0))) * 0.8;
    col += FIRE * exp(-length((uv - fire - float2(0.0, -0.06)) * float2(1.0, 0.8)) * 8.0) * (0.25 + 0.5 * glowAmt);

    // Sparks bursting up on the kick and drifting.
    for (int i = 0; i < 14; i++) {
        float fi = float(i);
        float life = fract(uBeatAge * 0.6 + hash11(fi) * 0.3);
        float2 v = float2((hash11(fi * 3.1) - 0.5) * 0.25, -0.35 - 0.3 * hash11(fi * 7.7));
        float2 sp = fire + v * life + float2(sin(life * 6.0 + fi) * 0.02, 0.0);
        float d = length(uv - sp);
        col += mix(float3(1.0, 0.8, 0.4), FIRE, life) * (1.0 - smoothstep(0.0, 0.004, d)) * (1.0 - life) * (0.3 + 0.9 * kick) * play;
    }
    // Smoke curling up.
    float sm = fbm3(float2(uv.x * 4.0, uv.y * 3.0 + 0.2 * t + 0.4 * uBassT));
    col = mix(col, float3(0.4, 0.38, 0.4), smoothstep(0.55, 0.8, sm) * exp(-abs(uv.x - fire.x - (fire.y - uv.y) * 0.2) * 9.0) * step(uv.y, fire.y - 0.1) * 0.25);

    return half4(finish(col, fc), 1.0);
}
"""

    private const val MANGA_BEAT = """
// Manga beat (music): a black-and-white manga page in action. The album cover sits in the middle
// panel inked like a manga frame, screentone shading fills the background, speed lines rush in
// towards it with the song's energy, ink splashes and impact bursts hit on every real kick, the
// panel borders jolt, and a splash of the cover's colour bleeds in when the bass swells.
// Shared by the music-reactive scenes (besides "Now playing", which has its own copy): the same
// uniforms NowPlayingScene feeds the music scene - cover, levels, kicks, eight equalizer bands and
// where on screen the visualizer goes - plus the soft cover background.
