uniform float4 uEqB;      // bands 4-7 (high)
uniform float uWaveY;     // 0..1 from the top: where the visualizer sits (Appearance > Equalizer)
uniform float uWaveH;     // room above / below that line (share of the height); the player sits under it
uniform float uWaveX;     // 0..1 from the left: where the visualizer sits across (0 = the middle; the player beside it)
uniform shader uCover;    // the cover, sharp (256 px square) - for the record / disc labels
uniform float2 uCoverSize;
uniform shader uLabel;    // the song's title and artist in dark ink on a clear picture (NowPlayingScene.songLabel)
uniform float2 uLabelSize;
uniform shader uHistory;  // covers of the last songs: a 4 x 2 grid (newest first), MusicTheme.historyAtlas
uniform float uHistCount; // how many of the 8 are filled
uniform float3 uSubject;   // where the cover's subject is: x, y (0..1 across the square) and its size; z = 0 until known (MusicTheme.subject)
// Clocks that only run while the music plays, so spins and scrolls slow down and stop smoothly instead of
// jumping (t * (a + b * level) jumps whenever the level moves). Kept by NowPlayingScene, in seconds:
uniform float uPlayT;     // time spent playing (integral of uPlaying)
uniform float uBassT;     // integral of uBass x uPlaying
uniform float uMidT;      // integral of uMid x uPlaying
uniform float uHighT;     // integral of uHigh x uPlaying

// The visualizer's room, with a sensible size when it isn't set (previews).
float room(float fallback) { return uWaveH > 0.001 ? uWaveH : fallback; }
// Across: the middle, or the left part when the player sits beside the visualizer (MusicPlayerLayout.SIDE).
float waveX(float asp) { return uWaveX > 0.001 ? uWaveX * asp : asp * 0.5; }

float2 mirrorUv(float2 q) { return 1.0 - abs(1.0 - mod(q, 2.0)); }

float eqBand(float i) {
    if (i < 0.5) return uEqA.x;
    if (i < 1.5) return uEqA.y;
    if (i < 2.5) return uEqA.z;
    if (i < 3.5) return uEqA.w;
    if (i < 4.5) return uEqB.x;
    if (i < 5.5) return uEqB.y;
    if (i < 6.5) return uEqB.z;
    return uEqB.w;
}

// The spectrum at m (0 = lowest band, 1 = highest), smoothly interpolated.
float eqAt(float m) {
    float f = clamp(m, 0.0, 1.0) * 7.0;
    float i = floor(f);
    float u = f - i;
    u = u * u * (3.0 - 2.0 * u);
    return mix(eqBand(i), eqBand(min(i + 1.0, 7.0)), u);
}

// Pushes a colour's saturation by s (1 = unchanged) around its own brightness.
float3 vivid(float3 c, float s) {
    float l = dot(c, float3(0.299, 0.587, 0.114));
    return max(mix(float3(l), c, s), 0.0);
}

// The cover, very soft and slowly drifting (or, without one, the palette swirling), dimmed by dim.
float3 coverField(float2 uv, float asp, float t, float bass, float dim, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float zoom = 1.7 + 0.08 * sin(t * 0.045) - 0.05 * bass * uIntensity;
    p = rot(0.05 * sin(t * 0.031)) * p / zoom;
    p += (float2(vnoise(p * 2.0 + float2(t * 0.1, 0.0)), vnoise(p * 2.0 + float2(7.3, -t * 0.08))) - 0.5) * 0.1;
    float2 q = p / max(asp, 1.0) + 0.5;
    float3 art = float3(uArt.eval(mirrorUv(q) * uArtSize).rgb);
    float sw = fbm3(uv * 1.4 + float2(t * 0.03, -t * 0.02));
    float3 noArt = mix(BG * 1.4 + A * 0.08, mix(A, S, sw) * 0.5, smoothstep(0.25, 0.8, sw));
    float3 col = mix(noArt, vivid(art, 1.35) * 0.62, uHasArt);
    return mix(col, BG, 0.14) * dim;
}

// The palette as a living gradient: A and S (the cover's colours) flowing round each other with a
// third, hue-shifted colour, brighter on the beat. A colourful base instead of a near-black one.
float3 paletteField(float2 uv, float asp, float t, float lift, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float n1 = fbm3(p * 1.3 + float2(t * 0.05, -t * 0.04));
    float n2 = fbm3(p * 1.7 + float2(-t * 0.035, t * 0.05) + 4.7);
    float3 C = float3(S.z, A.x, (A.y + S.y) * 0.5); // a third colour from the two
    float3 col = mix(A, S, smoothstep(0.25, 0.75, n1));
    col = mix(col, C, smoothstep(0.45, 0.85, n2) * 0.55);
    col = mix(BG, col, 0.42 + 0.18 * lift);
    return col;
}

// The sharp cover at q (0..1 across the square), or the palette when there's no cover yet.
float3 sharpCover(float2 q, float3 A, float3 S) {
    float3 art = float3(uCover.eval(clamp(q, 0.0, 1.0) * uCoverSize).rgb);
    return mix(mix(A, S, q.y), art, uHasArt);
}

// Where the cover's subject sits (x, y, size), with a sensible guess before it's known.
float3 subjectOf() { return uSubject.z > 0.001 ? uSubject : float3(0.5, 0.45, 0.3); }

// Ink of the song label at q (0..1 across the writing area): 0 = paper, 1 = ink.
float labelInk(float2 q) {
    if (q.x < 0.0 || q.x > 1.0 || q.y < 0.0 || q.y > 1.0) return 0.0;
    return float(uLabel.eval(q * uLabelSize).a);
}

// Cover of an earlier song: i = 0 the one before this, 1 the one before that... (wraps round the
// ones there are; with none yet, the current cover in the song's colours instead).
float3 pastCover(float i, float2 q, float3 A, float3 S) {
    q = clamp(q, 0.0, 1.0);
    if (uHistCount < 0.5) return mix(sharpCover(q, A, S), mix(A, S, q.y), 0.35);
    float n = mod(floor(i), uHistCount);
    float2 tile = float2(mod(n, 4.0), floor(n / 4.0));
    float2 p = (tile + 0.01 + q * 0.98) * 192.0;
    return float3(uHistory.eval(p).rgb);
}

// Anime / manga drawing tricks shared by the anime-inspired scenes: focus (speed) lines, halftone
// dots, flat cel bands and jagged lightning. Generic drawing styles only - no characters or symbols.

// Focus lines radiating from c, the classic "speed lines" of a dramatic panel. n = how many around,
// they flicker to new positions 8 times a second. Clear near the centre, strongest at the edges.
float focusLines(float2 uv, float2 c, float t, float n, float seed) {
    float2 d = uv - c;
    float a = atan(d.y, d.x) / TAU + 0.5;
    float r = length(d);
    float id = floor(a * n);
    float h = hash11(id + seed + floor(t * 8.0) * 13.0);
    float w = abs(fract(a * n) - 0.5) * 2.0;
    float line = (1.0 - smoothstep(0.0, 0.12 + 0.25 * h, w)) * step(0.62, h);
    return line * smoothstep(0.22 + 0.35 * h, 0.95, r);
}

// Manga halftone: dots on a 45-degree grid, bigger where v is larger (0..1). 1 inside a dot.
float halftone(float2 uv, float scale, float v) {
    float2 p = rot(0.785398) * uv * scale;
    float2 g = fract(p) - 0.5;
    return 1.0 - smoothstep(v * 0.62 - 0.04, v * 0.62 + 0.04, length(g));
}

// Linear noise between random points: kinked, jagged lines (lightning) instead of smooth curves.
float jag(float x, float s) {
    float i = floor(x);
    return mix(hash11(i * 1.37 + s), hash11((i + 1.0) * 1.37 + s), fract(x)) - 0.5;
}

// Distance to a lightning bolt from a to b: a straight segment pushed sideways by jagged noise,
// thinning towards its ends.
float bolt(float2 p, float2 a, float2 b, float seed, float amp) {
    float2 ba = b - a;
    float L = max(length(ba), 1e-4);
    float2 dir = ba / L;
    float2 nrm = float2(-dir.y, dir.x);
    float2 pa = p - a;
    float along = dot(pa, dir);
    float h = sat(along / L);
    float off = (jag(h * 7.0, seed) + 0.45 * jag(h * 23.0, seed + 9.0)) * amp * sin(PI * h);
    float side = dot(pa, nrm) - off;
    float outside = max(-along, along - L);
    return length(float2(side, max(outside, 0.0)));
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float px = 1.5 / uRes.y;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float k = uIntensity;
    float play = uPlaying;
    float bass = uBass * play;
    float kick = exp(-uBeatAge * 5.0) * play;
    float loud = sat((uEqA.x + uEqA.y + uEqB.x + uEqB.y) * 0.25) * play;

    float2 c = float2(waveX(asp), uWaveY);
    float R = room(0.28) * 0.78;
    float3 paper = float3(0.95, 0.94, 0.9);
    float3 ink = float3(0.06, 0.06, 0.08);

    // Screentone: dot size grows away from the centre.
    float r = length((uv - c) * float2(0.7, 1.0));
    float3 col = mix(paper, ink, halftone(uv, 70.0, sat(r * 0.9 - 0.1)) * 0.85);
    // Speed lines towards the panel, denser when it's loud.
    float fl = focusLines(uv, c, t * (1.0 + 2.0 * loud), 80.0 + 120.0 * loud, 3.0);
    col = mix(col, ink, fl * (0.35 + 0.6 * loud));
    // The cover's colour bleeding in with the bass.
    col = mix(col, col * mix(A, float3(1.0), 0.35), smoothstep(0.2, 0.9, bass) * (1.0 - smoothstep(R, R * 4.0, r)) * 0.6);

    // Impact burst on the kick: a jagged star behind the panel.
    float2 d = uv - c;
    float a = atan(d.y, d.x);
    float burstR = R * (1.45 + 0.6 * kick * k) * (0.85 + 0.15 * step(0.5, fract(a / TAU * 18.0 + floor(t * 4.0) * 0.37)));
    float burst = step(length(d * float2(0.8, 1.0)), burstR) * step(0.05, kick);
    col = mix(col, paper, burst);
    col = mix(col, ink, step(abs(length(d * float2(0.8, 1.0)) - burstR), 0.004) * step(0.05, kick));

    // Ink splashes on the kick.
    for (int i = 0; i < 5; i++) {
        float fi = float(i);
        float ang = fi * 1.26 + floor(t - uBeatAge) * 2.3;
        float2 sp = c + float2(cos(ang), sin(ang)) * R * (1.7 + 0.4 * hash11(fi));
        float sr = R * 0.12 * kick * (0.6 + 0.6 * hash11(fi + 3.0));
        float blob = length(uv - sp) - sr * (0.8 + 0.3 * vnoise(float2(atan(uv.y - sp.y, uv.x - sp.x) * 3.0, fi)));
        col = mix(col, ink, (1.0 - smoothstep(0.0, px, blob)) * step(0.02, kick));
    }

    // The panel with the cover, jolting on the kick.
    float2 jolt = float2(hash11(floor(t * 25.0)) - 0.5, hash11(floor(t * 25.0) + 1.0) - 0.5) * 0.01 * kick * k;
    float2 pd = rot(0.03 * sin(t * 0.3)) * (uv - c - jolt);
    float box = sdRoundBox(pd, float2(R), 0.0);
    if (box < 0.0) {
        float3 cov = sharpCover(pd / (2.0 * R) + 0.5, A, S);
        // Inked look: crush to a few tones, keep a little colour.
        float lum = dot(cov, float3(0.299, 0.587, 0.114));
        float tone = floor(lum * 4.0) / 3.0;
        float3 inked = mix(ink, paper, tone);
        inked = mix(inked, ink, halftone(pd, 90.0, sat(0.7 - lum)) * step(tone, 0.5));
        col = mix(inked, cov, 0.35 + 0.3 * bass);
    }
    col = mix(col, ink, step(abs(box), 0.006));
    // Outer page borders.
    float2 e = min(uv, float2(asp, 1.0) - uv);
    col = mix(col, ink, step(min(e.x, e.y), 0.012));
    return half4(finish(col, fc), 1.0);
}
"""

    private const val COMIC_PANELS = """
// Comic pages: a comic-book page that keeps redrawing itself. Panels with thick ink borders slide
// in and settle, each one a different moment - halftone skies, speed lines rushing past, a starburst
// "impact" flash, radiating sun rays, a cityscape at dusk - in bold flat colours with Ben-Day dots.
// Every few seconds a panel flips to a new picture. Generic comic drawing styles only.
// Anime / manga drawing tricks shared by the anime-inspired scenes: focus (speed) lines, halftone
// dots, flat cel bands and jagged lightning. Generic drawing styles only - no characters or symbols.

// Focus lines radiating from c, the classic "speed lines" of a dramatic panel. n = how many around,
// they flicker to new positions 8 times a second. Clear near the centre, strongest at the edges.
float focusLines(float2 uv, float2 c, float t, float n, float seed) {
    float2 d = uv - c;
    float a = atan(d.y, d.x) / TAU + 0.5;
    float r = length(d);
    float id = floor(a * n);
    float h = hash11(id + seed + floor(t * 8.0) * 13.0);
    float w = abs(fract(a * n) - 0.5) * 2.0;
    float line = (1.0 - smoothstep(0.0, 0.12 + 0.25 * h, w)) * step(0.62, h);
    return line * smoothstep(0.22 + 0.35 * h, 0.95, r);
}

// Manga halftone: dots on a 45-degree grid, bigger where v is larger (0..1). 1 inside a dot.
float halftone(float2 uv, float scale, float v) {
    float2 p = rot(0.785398) * uv * scale;
    float2 g = fract(p) - 0.5;
    return 1.0 - smoothstep(v * 0.62 - 0.04, v * 0.62 + 0.04, length(g));
}

// Linear noise between random points: kinked, jagged lines (lightning) instead of smooth curves.
float jag(float x, float s) {
    float i = floor(x);
    return mix(hash11(i * 1.37 + s), hash11((i + 1.0) * 1.37 + s), fract(x)) - 0.5;
}

// Distance to a lightning bolt from a to b: a straight segment pushed sideways by jagged noise,
// thinning towards its ends.
float bolt(float2 p, float2 a, float2 b, float seed, float amp) {
    float2 ba = b - a;
    float L = max(length(ba), 1e-4);
    float2 dir = ba / L;
    float2 nrm = float2(-dir.y, dir.x);
    float2 pa = p - a;
    float along = dot(pa, dir);
    float h = sat(along / L);
    float off = (jag(h * 7.0, seed) + 0.45 * jag(h * 23.0, seed + 9.0)) * amp * sin(PI * h);
    float side = dot(pa, nrm) - off;
    float outside = max(-along, along - L);
    return length(float2(side, max(outside, 0.0)));
}

float3 panelArt(float kind, float2 q, float t, float seed, float3 A, float3 S, float3 BG) {
    // q: 0..1 inside the panel.
    float3 c = float3(1.0);
    if (kind < 1.0) {
        // Halftone sky with a big sun.
        c = mix(mix(S, float3(1.0), 0.5), A, q.y);
        float sun = length(q - float2(0.7, 0.35)) - 0.18;
        c = mix(c, float3(1.0, 0.85, 0.25), step(sun, 0.0));
        c = mix(c, c * 0.65, halftone(q, 38.0, q.y * 0.9) * 0.6);
    } else if (kind < 2.0) {
        // Speed lines rushing past.
        c = mix(float3(1.0), mix(A, float3(1.0), 0.6), q.x);
        float l = step(0.7, hash11(floor(q.y * 40.0) + floor(t * 6.0) * 7.0 + seed));
        float streak = l * step(fract(q.x * 0.6 + t * 2.0 + hash11(floor(q.y * 40.0))), 0.6);
        c = mix(c, float3(0.08), streak);
    } else if (kind < 3.0) {
        // Impact starburst.
        float2 d = q - 0.5;
        float a = atan(d.y, d.x);
        float r = length(d);
        float spikes = 0.22 + 0.12 * step(0.5, fract(a / TAU * 14.0)) + 0.02 * sin(t * 6.0);
        c = mix(S, A, step(0.5, fract(a / TAU * 24.0 + t * 0.2)));
        c = mix(c, float3(1.0, 0.95, 0.3), step(r, spikes));
        c = mix(c, float3(0.08), step(abs(r - spikes), 0.008));
        c = mix(c, float3(1.0, 0.4, 0.2), step(r, spikes * 0.55));
    } else if (kind < 4.0) {
        // Sun rays.
        float2 d = q - float2(0.5, 1.0);
        float a = atan(d.y, d.x);
        c = mix(A, mix(A, float3(1.0), 0.5), step(0.5, fract(a / TAU * 20.0 + t * 0.05)));
        c = mix(c, c * 0.75, halftone(q, 30.0, 0.5) * 0.5);
    } else {
        // City at dusk: buildings with lit windows over a halftone gradient.
        c = mix(mix(A, S, 0.5), float3(1.0, 0.75, 0.5), q.y);
        c = mix(c, c * 0.7, halftone(q, 34.0, 1.0 - q.y) * 0.6);
        float bx = floor(q.x * 9.0);
        float bh = 0.35 + 0.4 * hash11(bx + seed);
        float inB = step(1.0 - bh, q.y);
        float win = step(0.6, hash12(floor(q * float2(45.0, 40.0)) + seed)) * step(0.3, fract(q.x * 45.0)) * step(0.35, fract(q.y * 40.0));
        c = mix(c, float3(0.1, 0.1, 0.18), inB);
        c = mix(c, float3(1.0, 0.9, 0.4), inB * win);
    }
    return c;
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float px = 1.5 / uRes.y;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    // Paper.
    float3 col = float3(0.96, 0.94, 0.88) * (0.95 + 0.05 * vnoise(uv * 300.0));
    // A page layout: 3 columns x 2 rows with jittered gutters; the layout itself changes every 12 s.
    float page = floor(t / 12.0);
    float pt = fract(t / 12.0) * 12.0;
    float2 m = float2(0.05);
    float2 area = float2(asp, 1.0) - 2.0 * m;
    float2 q = (uv - m) / area;
    float split = 0.5 + (hash11(page + 1.0) - 0.5) * 0.2;
    float row = step(split, q.y);
    float c1 = 0.33 + (hash11(page * 3.0 + row) - 0.5) * 0.15;
    float c2 = 0.66 + (hash11(page * 5.0 + row) - 0.5) * 0.15;
    float colI = step(c1, q.x) + step(c2, q.x);
    float x0 = colI < 0.5 ? 0.0 : (colI < 1.5 ? c1 : c2);
    float x1 = colI < 0.5 ? c1 : (colI < 1.5 ? c2 : 1.0);
    float y0 = row < 0.5 ? 0.0 : split;
    float y1 = row < 0.5 ? split : 1.0;
    float gut = 0.012;
    float2 lo = float2(x0 + gut, y0 + gut * asp);
    float2 hi = float2(x1 - gut, y1 - gut * asp);
    float id = colI + row * 3.0;
    // Slide in, staggered, at the start of each page.
    float enter = smoothstep(0.0, 0.6, pt - id * 0.25);
    float2 off = float2((hash11(id + page) - 0.5) * 0.4, 0.3) * (1.0 - enter);
    float2 pq = (q - lo - off) / (hi - lo);
    float inP = step(0.0, pq.x) * step(pq.x, 1.0) * step(0.0, pq.y) * step(pq.y, 1.0);
    if (inP > 0.5) {
        // A panel flips to new art every few seconds.
        float flipT = floor((t + id * 1.7) / 4.0);
        float kind = floor(hash11(id * 9.0 + flipT * 3.7 + page) * 5.0);
        float3 art = panelArt(kind, pq, t, id + flipT, A, S, BG);
        col = art;
        // Ink border.
        float2 e = min(pq, 1.0 - pq) * (hi - lo) * area;
        float border = 1.0 - smoothstep(0.004, 0.006, min(e.x, e.y));
        col = mix(col, float3(0.06), border);
    }
    // Drop shadow under panels (offset).
    float2 sq = (q - lo - off - float2(0.006, 0.01)) / (hi - lo);
    float inS = step(0.0, sq.x) * step(sq.x, 1.0) * step(0.0, sq.y) * step(sq.y, 1.0) * (1.0 - inP);
    col = mix(col, col * 0.75, inS);
    return half4(finish(col, fc), 1.0);
}
"""

    private const val PIXEL_SKY = """
// Pixel sky: a 32-bit day in the clouds. Chunky pixel clouds drift past in parallax layers, a
// little Voltcap capsule airship putters along with its propeller spinning, pixel birds flap by,
// hot-air balloons in the theme's colours rise and fall, and the sun's rays turn slowly - all on a
// coarse pixel grid with a dithered sky.
// The Voltcap mark, shared by the Voltcap scenes: the capsule (half width 1, half height VR in its own
// units) and the bolt inside it - the same shapes as the start-up animation (VoltcapIntro).
const float VR = 0.44;

float sdCapsuleMark(float2 q) { return sdRoundBox(q, float2(1.0, VR), VR); }

// One edge of a polygon for its signed distance (squared distance, and 1 when it flips the inside test).
float2 polyEdge(float2 p, float2 vi, float2 vj) {
    float2 e = vj - vi;
    float2 w = p - vi;
    float2 b = w - e * sat(dot(w, e) / dot(e, e));
    float c1 = step(vi.y, p.y);
    float c2 = 1.0 - step(vj.y, p.y);
    float c3 = step(e.y * w.x, e.x * w.y);
    return float2(dot(b, b), c1 * c2 * c3 + (1.0 - c1) * (1.0 - c2) * (1.0 - c3));
}

// The bolt (capsule units; y down), signed distance.
float sdBoltMark(float2 p) {
    float2 v0 = float2(0.13, -0.33);
    float2 v1 = float2(-0.17, 0.045);
    float2 v2 = float2(-0.015, 0.045);
    float2 v3 = float2(-0.11, 0.33);
    float2 v4 = float2(0.19, -0.055);
    float2 v5 = float2(0.035, -0.055);
    float d = dot(p - v0, p - v0);
    float flips = 0.0;
    float2 r;
    r = polyEdge(p, v0, v5); d = min(d, r.x); flips += r.y;
    r = polyEdge(p, v1, v0); d = min(d, r.x); flips += r.y;
    r = polyEdge(p, v2, v1); d = min(d, r.x); flips += r.y;
    r = polyEdge(p, v3, v2); d = min(d, r.x); flips += r.y;
    r = polyEdge(p, v4, v3); d = min(d, r.x); flips += r.y;
    r = polyEdge(p, v5, v4); d = min(d, r.x); flips += r.y;
    float s = mod(flips, 2.0) > 0.5 ? -1.0 : 1.0;
    return s * sqrt(d);
}

// A point on the capsule's outline at angle a (close enough to the real outline for sparks).
float2 capsulePoint(float a) {
    return float2(clamp(1.35 * cos(a), -1.0, 1.0) * (1.0 - VR), 0.0) + VR * float2(cos(a), sin(a));
}

half4 main(float2 fc) {
    float P = uRes.y / 150.0;
    float2 g = floor(fc / P) + 0.5;
    float2 uv = g * P / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    // Dithered sky in bands.
    float lvl = uv.y * 5.0 + (mod(g.x + g.y, 2.0) - 0.5) * 0.45;
    float3 top = mix(float3(0.25, 0.5, 0.95), BG * 2.0 + float3(0.1, 0.3, 0.7), 0.2);
    float3 bot = float3(0.75, 0.88, 1.0);
    float3 col = mix(top, bot, floor(lvl) / 4.0);
    // Sun with turning rays (pixelated).
    float2 sp = uv - float2(asp * 0.82, 0.2);
    float a = atan(sp.y, sp.x);
    float r = length(sp);
    float rays = step(0.5, fract(a / TAU * 12.0 + t * 0.02)) * step(r, 0.16) * step(0.08, r);
    col = mix(col, float3(1.0, 0.95, 0.6), rays * 0.35);
    col = mix(col, float3(1.0, 0.9, 0.35), step(r, 0.07));
    col = mix(col, float3(1.0, 1.0, 0.8), step(r, 0.05));

    // Cloud layers: puffs made of overlapping circles, pixel-snapped, three speeds.
    for (int L = 0; L < 3; L++) {
        float fl = float(L);
        float sc = 0.45 - fl * 0.08;
        float x = uv.x + t * (0.01 + fl * 0.015);
        float id = floor(x / sc);
        float lx = x - (id + 0.5) * sc;
        float h = hash11(id + fl * 13.0);
        float cy = 0.22 + fl * 0.17 + (hash11(id * 3.3 + fl) - 0.5) * 0.16;
        float2 q = float2(lx, uv.y - cy);
        float d = min(min(length(q * float2(1.0, 1.8)) - 0.07 * (0.7 + h), length((q - float2(0.06, 0.01)) * float2(1.0, 1.6)) - 0.05),
                      length((q + float2(0.06, -0.01)) * float2(1.0, 1.6)) - 0.045);
        float inC = step(d, 0.0) * step(0.4, h);
        float3 cc = mix(float3(1.0), float3(0.82, 0.88, 0.98), step(0.0, q.y) * 0.8);
        col = mix(col, mix(cc, col, 0.15 * (2.0 - fl)), inC);
        col = mix(col, float3(0.55, 0.62, 0.8), step(d, 0.006) * (1.0 - inC) * step(0.4, h) * 0.5);
    }

    // Balloons rising and falling.
    for (int i = 0; i < 3; i++) {
        float fi = float(i);
        float2 bp = float2(asp * (0.15 + fi * 0.3) + sin(t * 0.1 + fi) * 0.05, 0.45 + 0.12 * sin(t * 0.2 + fi * 2.0));
        float2 q = uv - bp;
        float env = length(q * float2(1.0, 0.85)) - 0.045;
        float stripes = step(0.5, fract(q.x * 40.0));
        col = mix(col, mix(i == 1 ? S : A, float3(1.0), stripes * 0.5), step(env, 0.0));
        float basket = step(abs(q.x), 0.012) * step(0.06, q.y) * step(q.y, 0.075);
        col = mix(col, float3(0.5, 0.3, 0.15), basket);
        float rope = step(abs(abs(q.x) - 0.01), 0.002) * step(0.045, q.y) * step(q.y, 0.06);
        col = mix(col, float3(0.3), rope);
    }

    // The capsule airship.
    float ax = fract(t * 0.02) * (asp + 0.5) - 0.25;
    float2 ap = uv - float2(ax, 0.3 + 0.02 * sin(t * 0.8));
    float2 aq = ap / 0.06;
    float dShip = sdCapsuleMark(aq);
    float3 shipC = mix(A * 0.8, A * 1.15, step(aq.y, 0.0));
    shipC = mix(shipC, mix(S, float3(1.0), 0.3), step(sdBoltMark(aq * 0.9), 0.0));
    col = mix(col, float3(0.05), step(dShip, 0.12));
    col = mix(col, shipC, step(dShip, 0.0));
    // Gondola and propeller.
    float gond = step(abs(ap.x), 0.015) * step(0.03, ap.y) * step(ap.y, 0.04);
    col = mix(col, float3(0.25, 0.2, 0.3), gond);
    float prop = step(abs(ap.x + 0.07), 0.003) * step(abs(ap.y), 0.02 * abs(sin(t * 20.0)));
    col = mix(col, float3(0.2), prop);

    // Pixel birds: little Vs flapping.
    for (int i = 0; i < 4; i++) {
        float fi = float(i);
        float bx = fract(t * 0.03 + fi * 0.27) * (asp + 0.2) - 0.1;
        float2 q = uv - float2(bx, 0.15 + fi * 0.05);
        float up = step(0.5, fract(t * 4.0 + fi));
        float v = step(abs(q.y + abs(q.x) * (up > 0.5 ? 0.8 : -0.3)), 0.004) * step(abs(q.x), 0.016);
        col = mix(col, float3(0.15, 0.15, 0.25), v);
    }
    return half4(finish(col, fc), 1.0);
}
