        page = mix(page, mix(S, float3(1.0), 0.3), step(st, 0.0));
        // Gloss sweep.
        page += float3(1.0) * 0.12 * pow(sat(1.0 - abs(q.x + q.y - fract(t * 0.07) * 3.0 + 0.5) * 3.0), 3.0);
        col = page;
    }
    return half4(finish(col, fc), 1.0);
