    float mid = abs(uv.y - 0.5);
    col *= mix(1.0, 0.45, smoothstep(0.28, 0.5, mid));
    col += mix(A, S, 0.5) * exp(-length((uv - float2(asp * 0.5, 0.5)) * float2(0.6, 1.6)) * 2.0) * kick * 0.1;
    return half4(finish(col, fc), 1.0);
}
