    float2 c = float2(waveX(asp), uWaveY);
    float H = room(0.28) * 0.9 * (1.0 + 0.012 * kick * k); // half the sleeve's side
    float2 cc = c - float2(H * 0.5, 0.0);                  // sleeve centre
    float R = H * 0.93;
    float2 dc = cc + float2(H * 1.0, 0.0);                 // disc centre: half of it out of the sleeve

    // A soft spotlight from above and a faint floor glow under the pair.
    float2 sp = (uv - c) * float2(0.5, 1.0);
    col += mix(A, float3(1.0), 0.45) * exp(-length(sp) * 2.4) * (0.10 + 0.14 * lvl * k);
    col += mix(A, S, 0.5) * exp(-abs(uv.y - (c.y + H * 1.12)) * 30.0) * 0.06 * (1.0 - smoothstep(0.0, H * 2.2, abs(uv.x - c.x)));

    // The disc (behind the sleeve).
    float2 d = uv - dc;
    float r = length(d);
    float ang = atan(d.y, d.x);
    col += mix(A, S, 0.5) * exp(-max(r - R, 0.0) * 9.0) * (0.06 + 0.35 * bass * k);
    float rr = R + uBeatAge * 0.45;
    col += mix(S, float3(1.0), 0.3) * exp(-abs(r - rr) * 90.0) * exp(-uBeatAge * 2.5) * 0.45 * k * play;
    col *= 1.0 - 0.35 * exp(-max(length(d - float2(0.01, 0.018)) - R, 0.0) * 40.0) * step(R, r);
    if (r < R) {
        float rn = r / R;
        float spin = 2.6 * uPlayT + t * 0.12; // slower than before: calm, still clearly spinning
        float la = ang - spin;
        float2 q = float2(cos(la), sin(la)) * rn;
        float3 print = mix(mix(A, S, q.y * 0.5 + 0.5), float3(1.0), 0.1);
        float3 art = float3(uCover.eval(clamp(q * 0.5 + 0.5, 0.0, 1.0) * uCoverSize).rgb);
        print = mix(print, art, uHasArt);
        float band = pow(abs(cos(ang - 0.7 + 0.08 * sin(t * 0.4))), 6.0);
        float3 rainbow = hue3(rn * 1.2 + 0.1 * sin(t * 0.2) + 0.15 * cos(ang - 0.7));
        float3 disc = mix(print, rainbow, 0.06 + 0.3 * band);
        disc += float3(1.0) * pow(band, 8.0) * 0.32;
        disc = mix(disc, mix(float3(0.85), rainbow, 0.4), smoothstep(0.96, 0.975, rn));
        float hub = smoothstep(0.30, 0.31, rn);
        float3 clear = mix(col * 0.75 + float3(0.12), rainbow * 0.4 + 0.4, 0.3 * smoothstep(0.18, 0.3, rn));
        disc = mix(clear, disc, hub);
        disc = mix(disc, float3(0.9), (1.0 - smoothstep(0.0, 0.006, abs(rn - 0.305))) * 0.6);
        disc = mix(col * 0.6, disc, smoothstep(0.12, 0.13, rn));
        disc = mix(disc, float3(0.95), (1.0 - smoothstep(0.0, 0.004, abs(rn - 0.995))) * 0.7);
        col = disc;
    }

    // The sleeve on top: its shadow on the disc and the floor, then the cover.
    float2 q = uv - cc;
    float sh = rbox(q - float2(H * 0.05, H * 0.06), float2(H), H * 0.03);
    col *= 1.0 - 0.5 * (1.0 - smoothstep(0.0, H * 0.16, sh)) * step(0.0, sh);
    float bd = rbox(q, float2(H), H * 0.03);
    if (bd < 0.0) {
        float2 st = q / (2.0 * H) + 0.5;
        float3 art = float3(uCover.eval(clamp(st, 0.0, 1.0) * uCoverSize).rgb);
        float3 fallback = mix(mix(A, S, st.y), BG * 1.4 + 0.05, 0.35 * st.x);
        float3 cv = mix(fallback, art, uHasArt);
        // Glossy sleeve: a slow diagonal sheen, light from the top, a bevelled edge.
        float sheen = 1.0 - smoothstep(0.0, 0.22, abs(st.x * 0.8 + st.y * 0.6 - 0.45 - 0.15 * sin(t * 0.12)));
        cv += float3(1.0) * sheen * 0.07;
        cv *= 1.04 - 0.1 * st.y;
        float edge = 1.0 - smoothstep(0.0, H * 0.025, -bd);
        cv = mix(cv, cv * 0.55 + float3(0.28), edge * 0.45);
        col = cv;
    }

    col += float3(1.0) * dots(uv, 34.0, float2(-t * 0.05, t * 0.025), 0.1, 0.07, 9.0) * (0.1 + 0.5 * high * k);
    return half4(finish(col, fc), 1.0);
}
"""

    private const val ALBUM_TIDE = """
// Album tide: an original paper-white album card over a softly drifting cover field.
// The wave joins the artwork to the label; the launcher's existing player stays below it.
// Shared by the music-reactive scenes (besides "Now playing", which has its own copy): the same
// uniforms NowPlayingScene feeds the music scene - cover, levels, kicks, eight equalizer bands and
// where on screen the visualizer goes - plus the soft cover background.
uniform shader uArt;      // the cover, square and blurred smooth (MusicTheme.softArt)
uniform float2 uArtSize;  // its size in pixels
uniform float uHasArt;    // 0 = no cover yet (or the cover is switched off)
uniform float uBass;      // 0..1, smoothed
uniform float uMid;
uniform float uHigh;
uniform float uBeatAge;   // seconds since the last kick (large = none)
uniform float uPlaying;   // 0..1, fades when paused
uniform float uIntensity; // 0..1, Settings > strength
uniform float4 uEqA;      // bands 0-3 (low), 0..1
uniform float4 uEqB;      // bands 4-7 (high)
uniform float uWaveY;     // 0..1 from the top: where the visualizer sits (Appearance > Equalizer)
uniform float uWaveH;     // room above / below that line (share of the height); the player sits under it
uniform float uWaveX;     // 0..1 from the left: where the visualizer sits across (0 = the middle; the player beside it)
uniform shader uCover;    // the cover, sharp (256 px square) - for the record / disc labels
uniform float2 uCoverSize;
uniform shader uLabel;    // the song's title and artist in dark ink on a clear picture (NowPlayingScene.songLabel)
uniform float2 uLabelSize;
uniform shader uHistory;  // covers of the last songs: a 4 x 2 grid (newest first), MusicTheme.historyAtlas
uniform float uHistCount; // how many of the 8 are filled
uniform float3 uSubject;   // where the cover's subject is: x, y (0..1 across the square) and its size; z = 0 until known (MusicTheme.subject)
// Clocks that only run while the music plays, so spins and scrolls slow down and stop smoothly instead of
// jumping (t * (a + b * level) jumps whenever the level moves). Kept by NowPlayingScene, in seconds:
uniform float uPlayT;     // time spent playing (integral of uPlaying)
uniform float uBassT;     // integral of uBass x uPlaying
uniform float uMidT;      // integral of uMid x uPlaying
uniform float uHighT;     // integral of uHigh x uPlaying

// The visualizer's room, with a sensible size when it isn't set (previews).
float room(float fallback) { return uWaveH > 0.001 ? uWaveH : fallback; }
// Across: the middle, or the left part when the player sits beside the visualizer (MusicPlayerLayout.SIDE).
float waveX(float asp) { return uWaveX > 0.001 ? uWaveX * asp : asp * 0.5; }

float2 mirrorUv(float2 q) { return 1.0 - abs(1.0 - mod(q, 2.0)); }

float eqBand(float i) {
    if (i < 0.5) return uEqA.x;
    if (i < 1.5) return uEqA.y;
    if (i < 2.5) return uEqA.z;
    if (i < 3.5) return uEqA.w;
    if (i < 4.5) return uEqB.x;
    if (i < 5.5) return uEqB.y;
    if (i < 6.5) return uEqB.z;
    return uEqB.w;
}

// The spectrum at m (0 = lowest band, 1 = highest), smoothly interpolated.
float eqAt(float m) {
    float f = clamp(m, 0.0, 1.0) * 7.0;
    float i = floor(f);
    float u = f - i;
    u = u * u * (3.0 - 2.0 * u);
    return mix(eqBand(i), eqBand(min(i + 1.0, 7.0)), u);
}

// Pushes a colour's saturation by s (1 = unchanged) around its own brightness.
float3 vivid(float3 c, float s) {
    float l = dot(c, float3(0.299, 0.587, 0.114));
    return max(mix(float3(l), c, s), 0.0);
}

// The cover, very soft and slowly drifting (or, without one, the palette swirling), dimmed by dim.
float3 coverField(float2 uv, float asp, float t, float bass, float dim, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float zoom = 1.7 + 0.08 * sin(t * 0.045) - 0.05 * bass * uIntensity;
    p = rot(0.05 * sin(t * 0.031)) * p / zoom;
    p += (float2(vnoise(p * 2.0 + float2(t * 0.1, 0.0)), vnoise(p * 2.0 + float2(7.3, -t * 0.08))) - 0.5) * 0.1;
    float2 q = p / max(asp, 1.0) + 0.5;
    float3 art = float3(uArt.eval(mirrorUv(q) * uArtSize).rgb);
    float sw = fbm3(uv * 1.4 + float2(t * 0.03, -t * 0.02));
    float3 noArt = mix(BG * 1.4 + A * 0.08, mix(A, S, sw) * 0.5, smoothstep(0.25, 0.8, sw));
    float3 col = mix(noArt, vivid(art, 1.35) * 0.62, uHasArt);
    return mix(col, BG, 0.14) * dim;
}

// The palette as a living gradient: A and S (the cover's colours) flowing round each other with a
// third, hue-shifted colour, brighter on the beat. A colourful base instead of a near-black one.
float3 paletteField(float2 uv, float asp, float t, float lift, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float n1 = fbm3(p * 1.3 + float2(t * 0.05, -t * 0.04));
    float n2 = fbm3(p * 1.7 + float2(-t * 0.035, t * 0.05) + 4.7);
    float3 C = float3(S.z, A.x, (A.y + S.y) * 0.5); // a third colour from the two
    float3 col = mix(A, S, smoothstep(0.25, 0.75, n1));
    col = mix(col, C, smoothstep(0.45, 0.85, n2) * 0.55);
    col = mix(BG, col, 0.42 + 0.18 * lift);
    return col;
}

// The sharp cover at q (0..1 across the square), or the palette when there's no cover yet.
float3 sharpCover(float2 q, float3 A, float3 S) {
    float3 art = float3(uCover.eval(clamp(q, 0.0, 1.0) * uCoverSize).rgb);
    return mix(mix(A, S, q.y), art, uHasArt);
}

// Where the cover's subject sits (x, y, size), with a sensible guess before it's known.
float3 subjectOf() { return uSubject.z > 0.001 ? uSubject : float3(0.5, 0.45, 0.3); }

// Ink of the song label at q (0..1 across the writing area): 0 = paper, 1 = ink.
float labelInk(float2 q) {
    if (q.x < 0.0 || q.x > 1.0 || q.y < 0.0 || q.y > 1.0) return 0.0;
    return float(uLabel.eval(q * uLabelSize).a);
}

// Cover of an earlier song: i = 0 the one before this, 1 the one before that... (wraps round the
// ones there are; with none yet, the current cover in the song's colours instead).
float3 pastCover(float i, float2 q, float3 A, float3 S) {
    q = clamp(q, 0.0, 1.0);
    if (uHistCount < 0.5) return mix(sharpCover(q, A, S), mix(A, S, q.y), 0.35);
    float n = mod(floor(i), uHistCount);
    float2 tile = float2(mod(n, 4.0), floor(n / 4.0));
    float2 p = (tile + 0.01 + q * 0.98) * 192.0;
    return float3(uHistory.eval(p).rgb);
}

float tideBox(float2 p, float2 b, float r) {
    float2 q = abs(p) - b + r;
    return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r;
}
half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float level = (uBass * 0.55 + uMid * 0.3 + uHigh * 0.15) * uPlaying * uIntensity;
    float2 bgq = float2(uv.x / asp, uv.y);
    bgq = (bgq - 0.5) * 0.8 + 0.5 + float2(sin(t * 0.035), cos(t * 0.027)) * 0.025;
    float3 art = float3(uArt.eval(clamp(bgq, 0.0, 1.0) * uArtSize).rgb);
    float3 col = mix(paletteField(uv, asp, t * 0.3, level, uBg.rgb, uAcc.rgb, uSec.rgb), art, uHasArt * 0.9);
    col *= 0.3 + 0.08 * level;
    float2 centre = float2(waveX(asp), uWaveY);
    float vignette = length((uv - float2(asp * 0.5, 0.5)) * float2(1.0 / asp, 0.8));
    col *= 1.0 - 0.4 * smoothstep(0.2, 0.8, vignette);
    // A sparse, slow layer of luminous dust; deliberately calmer than falling code.
    col += mix(uAcc.rgb, float3(1.0), 0.7) * dots(uv, 26.0, float2(t * 0.004, -t * 0.007), 0.018, 0.09, 21.0) * 0.15;
    // DESKTOP_CARD_OVERLAY
    float H = room(0.32) * 0.91;
    float W = H * 0.79;
    float2 p = uv - centre;
    float mask = 1.0 - smoothstep(-0.0015, 0.0015, tideBox(p, float2(W, H), H * 0.04));
    float shadow = exp(-max(tideBox(p - float2(0.0, H * 0.055), float2(W, H), H * 0.04), 0.0) * 65.0);
    col *= 1.0 - shadow * 0.38;
    if (mask > 0.0) {
        float2 q = (p + float2(W, H)) / float2(W * 2.0, H * 2.0);
        float3 card = float3(0.97, 0.97, 0.98);
        float artBottom = 0.79;
        float2 coverQ = float2(q.x, q.y / artBottom);
        float3 picture = sharpCover(coverQ, uAcc.rgb, uSec.rgb);
        float wave = 0.76 - (0.01 + level * 0.055) * (0.65 + 0.35 * sin(q.x * 18.0 - t * 1.6))
            - uBass * uPlaying * uIntensity * 0.06 * exp(-sqf((q.x - 0.67) * 9.0));
        float backWave = wave - 0.015 - level * 0.025 * sin(q.x * 24.0 + t * 1.2);
        card = mix(picture, mix(uAcc.rgb, uSec.rgb, q.x) * 0.8, smoothstep(backWave - 0.003, backWave + 0.003, q.y));
        card = mix(card, float3(0.97, 0.97, 0.98), smoothstep(wave - 0.002, wave + 0.002, q.y));
        if (q.y > 0.81) {
            float2 labelQ = float2((q.x - 0.08) / 0.84, (q.y - 0.81) / 0.16);
            float4 ink = uLabel.eval(clamp(labelQ, 0.0, 1.0) * uLabelSize);
            card = mix(card, ink.rgb, ink.a);
        }
        col = mix(col, card, mask);
    }
    return half4(finish(col, fc), 1.0);
}
"""

    private const val CHILL_BLADES = """
// Glass blades: a calm console dashboard. Wide curved blades of tinted glass sweep in from the bottom-left
// and the top-right corners, each with a bright polished edge and a soft sheen gliding along it; a few
// glassy orbs float near them and a soft light breathes behind. The middle stays clear (original design).

// One glass blade: the crescent inside circle (ca, ra) and outside circle (cb, rb). Returns its glass
// colour (rgb) and coverage (a) at p, lit by a sheen that runs along it.
float4 blade(float2 p, float2 ca, float ra, float2 cb, float rb, float3 tint, float sheenPos, float seed) {
    float da = length(p - ca) - ra;
    float db = length(p - cb) - rb;
    float inside = smoothstep(0.004, -0.004, da) * smoothstep(-0.004, 0.004, db);
    // Thickness across the blade: 0 at the outer edge, 1 at the inner one.
    float th = sat(-da / max(-da + db, 1e-4));
    // Where along the arc this point sits (angle round circle a).
    float2 v = normalize(p - ca);
    float ang = atan(v.y, v.x);
    float sheen = exp(-sqf((ang - sheenPos) * 3.2));
    float3 glass = tint * (0.10 + 0.55 * sqf(1.0 - th)) + float3(1.0) * sheen * sqf(1.0 - th) * 0.35;
    // A faint ripple of streaks inside the glass.
    glass += tint * 0.05 * smoothstep(0.6, 1.0, vnoise(float2(ang * 18.0 + seed, th * 3.0)));
    float edge = exp(-abs(da) * 520.0) * (0.55 + 0.9 * sheen) * smoothstep(-0.02, 0.03, db);
    float inner = exp(-abs(db) * 700.0) * 0.25 * smoothstep(0.03, -0.02, da);
    float a = inside * (0.35 + 0.5 * (1.0 - th));
    float3 c = glass + mix(tint, float3(1.0), 0.45) * (edge + inner);
    float halo = exp(-max(da, 0.0) * 22.0) * smoothstep(-0.05, 0.1, db);
    c += tint * halo * 0.07 * (1.0 - inside);
    return float4(c, max(a, sat(edge + inner + halo * 0.5)));
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime * 0.05;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    // Backdrop: deep colour, a large soft light breathing behind the left blades and a cooler one top-right.
    float3 col = BG;
    float2 l1 = uv - float2(asp * 0.18, 0.92);
    float2 l2 = uv - float2(asp * 0.9, 0.08);
    float breathe = 0.85 + 0.15 * sin(uTime * 0.21);
    col += A * exp(-dot(l1, l1) * 1.6) * 0.30 * breathe;
    col += mix(A, float3(1.0), 0.4) * exp(-dot(l1, l1) * 9.0) * 0.12 * breathe;
    col += mix(A, S, 0.6) * exp(-dot(l2, l2) * 3.0) * 0.12;
    col += BG * 0.5 * smoothstep(1.0, 0.0, uv.y);
    // Fine diagonal light lines across the back, very faint.
    float diag = uv.x * 0.55 + uv.y;
    col += A * smoothstep(0.985, 1.0, sin(diag * 70.0 + t * 2.0)) * 0.02 * smoothstep(0.2, 1.0, abs(uv.y - 0.5) * 2.0);

    // Blades from the bottom-left, three layers sliding slowly.
    for (int i = 0; i < 3; i++) {
        float fi = float(i);
        float wob = sin(t * (0.9 + fi * 0.3) + fi * 2.1);
        float2 ca = float2(asp * (0.05 + 0.06 * fi), 1.92 - 0.04 * fi + 0.015 * wob);
        float ra = 1.02 + 0.05 * fi;
        float2 cb = ca + float2(0.05 + 0.03 * fi + 0.02 * wob, 0.11 + 0.02 * fi);
        float3 tint = mix(mix(A, float3(1.0), 0.15), mix(S, A, 0.4), fi / 2.0);
        float sheenPos = -1.3 + 0.55 * sin(t * 1.3 + fi * 1.7);
        float4 b = blade(uv, ca, ra, cb, ra + 0.02, tint, sheenPos, fi * 9.0);
        col = mix(col, col * 0.75 + b.rgb, b.a);
    }
    // Blades from the top-right.
    for (int i = 0; i < 2; i++) {
        float fi = float(i);
        float wob = sin(t * (1.1 + fi * 0.4) + fi * 1.3 + 2.0);
        float2 ca = float2(asp * (0.98 - 0.05 * fi), -0.92 + 0.04 * fi + 0.015 * wob);
        float ra = 1.0 + 0.04 * fi;
        float2 cb = ca + float2(-0.05 - 0.03 * fi + 0.02 * wob, -0.10 - 0.02 * fi);
        float3 tint = mix(mix(A, float3(1.0), 0.25), S, 0.3 + 0.4 * fi);
        float sheenPos = 1.95 + 0.5 * sin(t * 1.1 + fi * 2.3 + 1.0);
        float4 b = blade(uv, ca, ra, cb, ra + 0.02, tint, sheenPos, fi * 5.0 + 3.0);
        col = mix(col, col * 0.8 + b.rgb * 0.85, b.a * 0.85);
    }

    // Glass orbs floating near the blades (never in the middle).
    for (int i = 0; i < 7; i++) {
        if (uLod > 1.5 && i > 3) break;
        float fi = float(i);
        float side = step(3.5, fi);
        float2 home = mix(float2(asp * (0.05 + 0.08 * fi), 0.7 + 0.07 * fi),
                          float2(asp * (1.0 - 0.07 * (fi - 4.0)), 0.06 + 0.08 * (fi - 4.0)), side);
        float2 o = home + float2(sin(uTime * 0.05 + fi * 1.9), cos(uTime * 0.043 + fi * 2.7)) * 0.03;
        float rr = 0.012 + 0.022 * hash11(fi * 3.7 + 1.0);
        float2 q = uv - o;
        float d = length(q);
        float body = smoothstep(rr, rr - 0.002, d);
        float3 oc = mix(A, S, hash11(fi + 4.0));
        float rimL = exp(-abs(d - rr) * 900.0 / (rr * 30.0));
        float spec = exp(-length(q - float2(-0.35, -0.4) * rr) * 140.0 / (rr * 30.0));
        col = mix(col, col * 0.85 + oc * 0.08, body * 0.6);
        col += mix(oc, float3(1.0), 0.5) * (rimL * 0.25 + spec * 0.55 * body);
    }

    return half4(finish(col, fc), 1.0);
}
"""

    private const val CHILL_POLAR = """
// Polar veil: Toni's painting of northern lights over a snowy peak (res scene_chill_polar), brought to life.
// The curtains sway and shimmer — fine rays drifting along them, brightness rolling slowly across —
// the stars twinkle, a shooting star crosses now and then, and the snow sparkles in the green light.
// (The procedural version is kept as chill_polar_drawn.agsl.)
// Shared by the painted scenes (the user's own paintings with motion added on top: aurora, meadow,
// px_dojo): the painting fills the screen like a cover (cropped, never stretched) round a chosen point.
uniform shader uPaint;      // the painting (ScenePainting: res/drawable-nodpi/scene_*.webp)
uniform float2 uPaintSize;  // its decoded size in pixels
uniform float uHasPaint;    // 0 while it decodes (a plain gradient in the theme's colours shows)

// The painting's pixel under screen point fc, filling the screen, the crop centred on (fx, fy) (0..1 across it).
float2 paintPx(float2 fc, float fx, float fy) {
    float2 sz = max(uPaintSize, float2(1.0));
    float s = max(uRes.x / sz.x, uRes.y / sz.y);
    float2 off = (sz * s - uRes) * float2(fx, fy);
    return (fc + off) / s;
}

// The painting's colour at pixel p (clamped inside it).
float3 paintAt(float2 p) { return float3(uPaint.eval(clamp(p, float2(0.5), max(uPaintSize, float2(1.0)) - 0.5)).rgb); }

// Brightness, for picking out lit parts of the painting.
float luma(float3 c) { return dot(c, float3(0.299, 0.587, 0.114)); }

// How much pixel p is a small bright speck (a star) rather than part of a bright area: brighter than the
// painting a few pixels away on both sides. lum is its own brightness.
float speckAt(float2 p, float lum) {
    float k = max(uPaintSize.y, 1.0) / 941.0 * 4.0;
    float n = (luma(paintAt(p + float2(k, k * 0.5))) + luma(paintAt(p - float2(k * 0.5, k)))) * 0.5;
    return smoothstep(0.06, 0.2, lum - n);
}

// The painted chill scenes' finish: the painting's own colours and framing (no vignette, no highlight
// roll-off), only the fine noise that keeps dark gradients from banding.
float3 finishPaint(float3 col, float2 fc) {
    col = clamp(col, 0.0, 1.0);
    return col + (hash12(fc) - 0.5) / 255.0;
}

half4 main(float2 fc) {
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 BG = uBg.rgb;
    if (uHasPaint < 0.5) {
        float2 uv = fc / uRes;
        return half4(finish(mix(BG * 1.2, BG * 0.7, uv.y), fc), 1.0);
    }
    float2 sz = max(uPaintSize, float2(1.0));
    float2 p = paintPx(fc, 0.5, 0.5);
    float2 q = p / sz;
    float aspP = sz.x / sz.y;

    // The aurora's area (top-left): its curtains sway sideways, more at their lower hem.
    float area = smoothstep(0.75, 0.6, q.x + q.y * 0.35) * smoothstep(0.48, 0.36, q.y);
    float sway = sin(q.y * 9.0 - t * 0.4 + q.x * 3.0) * 0.6 + sin(q.x * 13.0 + t * 0.3) * 0.4;
    float2 off = float2(sway * 0.0035 * (0.4 + q.y * 2.0), 0.0) * area;
    float3 col = paintAt(p + off * sz);
    float lum = luma(col);

    // Shimmer on the green / violet light.
    float green = sat((col.g - max(col.r, col.b * 0.8)) * 4.0);
    float violet = sat((col.b - col.g) * 3.0) * sat((col.r - col.g * 0.55) * 3.0);
    float aur = sat(green + violet * 0.8) * sat(lum * 2.5 - 0.1) * smoothstep(0.55, 0.42, q.y);
    float rays = vnoise(float2(q.x * 120.0 + q.y * 30.0 + t * 0.45, q.y * 2.0 + t * 0.12));
    float roll = 0.5 + 0.5 * sin(q.x * 5.5 - t * 0.3 + sin(t * 0.11) * 2.0);
    col *= 1.0 + aur * ((rays - 0.5) * 0.5 + (roll - 0.5) * 0.4);
    col += col * aur * 0.1 * (0.5 + 0.5 * sin(t * 0.55 + q.x * 4.0));
    // The hem glows brighter now and then as a wave runs along it.
    float hemWave = exp(-sqf(fract(q.x * 0.8 - t * 0.05) - 0.5) * 30.0);
    col += A * aur * hemWave * smoothstep(0.2, 0.38, q.y) * 0.18;

    // Stars twinkle (bright specks outside the aurora and above the mountain).
    float sky = (1.0 - aur) * step(q.y, 0.55) * (1.0 - smoothstep(0.0, 0.3, area));
    float speck = speckAt(p, lum) * sky * (1.0 - green);
    float2 cell = floor(q * sz / 3.0);
    float tw = 0.5 + 0.5 * sin(t * (1.4 + 2.0 * hash12(cell)) + hash12(cell + 9.0) * 40.0);
    col *= 1.0 + speck * (tw - 0.5);

    // A shooting star every 13 s, across the right side of the sky.
    float ts = fract(t / 13.0) * 13.0;
    if (ts < 0.8) {
        float2 a = float2(0.62 + 0.25 * hash11(floor(t / 13.0)), 0.05 + 0.08 * hash11(floor(t / 13.0) + 3.0));
        float2 dir = float2(-0.22, 0.1);
        float2 head = a + dir * ts;
        float2 tail = head - dir * min(ts, 0.25);
        float d = sdSegment(q * float2(aspP, 1.0), tail * float2(aspP, 1.0), head * float2(aspP, 1.0));
        col += float3(0.9, 1.0, 0.95) * exp(-d * 1200.0) * (1.0 - ts / 0.8);
    }

    // Snow on the mountain and the slope sparkles in the green light.
    float snow = smoothstep(0.55, 0.62, q.y) * smoothstep(0.35, 0.6, lum);
    col += mix(A, float3(1.0), 0.6) * dots(q * float2(aspP, 1.0), 180.0, float2(0.0), 0.05, 0.08, 7.0) * snow * 0.7;
    // The aurora's light on the snow breathes with it.
    col += A * snow * 0.04 * (0.5 + 0.5 * sin(t * 0.55 + 1.0));

    return half4(finishPaint(col, fc), 1.0);
}
"""

    private const val CHILL_PLANET = """
// Planet rise: a huge planet fills the lower-right corner, the sun just coming up behind its rim — a thin
// bright crescent, a soft atmosphere, cloud bands sliding slowly over the night side with a few city lights.
// A small moon up in the far corner, a satellite drifting over the rim. The middle stays open space.

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    // Deep space: a little lighter towards the planet, a faint dust veil up in the top-right.
    float3 col = BG * (0.75 + 0.35 * sat(uv.y));
    float2 nv = uv * float2(1.6, 2.2) + float2(t * 0.004, 0.0);
    float veil = fbm(nv) * smoothstep(asp * 0.35, asp, uv.x) * smoothstep(0.75, 0.0, uv.y);
    col += mix(S, A, 0.35) * sqf(veil) * 0.09;

    // Stars (fewer close to the planet's glow).
    float st = dots(uv, 62.0, float2(t * 0.0015, 0.0), 0.16, 0.06, 3.0) * 0.55
             + dots(uv, 31.0, float2(t * 0.003, 0.0), 0.07, 0.07, 9.0) * 0.8;

    float2 C = float2(asp * 0.80, 2.08);
    float R = 1.47;
    float2 dp = uv - C;
    float r = length(dp);
    float d = r - R;
    float2 n2 = dp / max(r, 1e-4);
    // The sun sits just behind the rim, up and to the left of the planet's top.
    float2 sunDir = normalize(float2(-0.36, -1.0));
    float2 sunPos = C + sunDir * (R - 0.012);
    float facing = sat(dot(n2, sunDir));
    float nearSun = exp(-(1.0 - facing) * 9.0);

    float3 air = mix(A, float3(0.85, 0.95, 1.0), 0.25);
    float3 warm = mix(S, float3(1.0, 0.92, 0.75), 0.35);
    if (d > 0.0) {
        // Atmosphere outside the rim: a thin bright skin and a wide soft glow, warm where the sun comes up.
        float skin = exp(-d * 90.0);
        float halo = exp(-d * 7.0);
        float3 ac = mix(air, warm, nearSun * 0.8);
        col += ac * (skin * (0.18 + 0.85 * nearSun) + halo * (0.05 + 0.20 * nearSun));
        col += float3(1.0) * st * sat(1.0 - halo * 1.6);
    } else {
        // The planet: a sphere seen from above its night side.
        float2 q = dp / R;
        float z = sqrt(max(1.0 - dot(q, q), 0.0));
        float3 n = float3(q, z);
        // Slow spin round the axis pointing at you: the cloud bands slide along the rim.
        float lon = atan(n.y, n.x) + t * 0.004;
        float2 tex = float2(lon * 7.0, acos(sat(z)) * 7.0);
        float land = fbm(tex * 2.2 + 3.1);
        float clouds = fbm(tex * float2(1.4, 3.2) + float2(t * 0.012, 0.0));
        clouds = smoothstep(0.48, 0.8, clouds);
        // Light from the sun behind the planet: only a crescent along the rim is lit.
        float3 L = normalize(float3(sunDir * 0.42, -0.9));
        float lit = sat(dot(n, L) * 2.2 + 0.05);
        float ocean = smoothstep(0.52, 0.47, land);
        float3 day = mix(mix(float3(0.16, 0.2, 0.14), float3(0.32, 0.27, 0.2), smoothstep(0.55, 0.75, land)), A * 0.5, ocean * 0.7);
        day = mix(day, float3(0.95), clouds * 0.85);
        float3 night = BG * 0.55 + A * 0.025;
        // City lights on land in the dark, in small clusters.
        float2 cid = floor(tex * 26.0);
        float city = step(0.8, hash12(cid)) * smoothstep(0.5, 0.56, land) * (1.0 - clouds);
        float2 cf = fract(tex * 26.0) - 0.5;
        city *= exp(-dot(cf, cf) * 22.0);
        night += warm * city * 0.7 * sat(1.0 - lit * 3.0) * (0.75 + 0.25 * sin(t * 0.7 + cid.x));
        night += float3(0.55, 0.6, 0.7) * clouds * 0.05;
        col = mix(night, day * (0.4 + 0.9 * lit), sat(lit * 1.3));
        // Rim light inside the edge and a little atmosphere over the disc.
        float rim = exp(d * 120.0);
        col += mix(air, warm, nearSun) * rim * (0.12 + 0.95 * nearSun);
        col += air * exp(d * 14.0) * 0.06;
    }

    // The sun's flare as it clears the rim: a bright point, a glow and a long thin streak along the horizon.
    float2 sp = uv - sunPos;
    float2 tng = float2(-sunDir.y, sunDir.x);
    float along = dot(sp, tng);
    float across = dot(sp, sunDir);
    float breathe = 0.88 + 0.12 * sin(t * 0.25);
    col += float3(1.0, 0.97, 0.9) * exp(-length(sp) * 70.0) * 0.9 * breathe;
    col += warm * exp(-length(sp) * 9.0) * 0.16 * breathe;
    col += mix(warm, float3(1.0), 0.5) * exp(-abs(across) * 260.0) * exp(-abs(along) * 4.5) * 0.22 * breathe;

    // A satellite gliding over the rim, its light blinking.
    float sa = fract(t * 0.012) * 1.6 - 0.8;
    float2 satPos = C + float2(sin(sa), -cos(sa)) * (R + 0.07);
    float blink = 0.35 + 0.65 * step(0.92, fract(t * 0.7));
    col += float3(1.0, 0.9, 0.8) * exp(-length(uv - satPos) * 900.0) * blink * 0.9;

    // A small moon far away, lit from the same sun.
    float2 mc = float2(asp * 0.11, 0.17);
    float mr = 0.032;
    float2 mp = uv - mc;
    float md = length(mp);
    if (md < mr) {
        float2 mq = mp / mr;
        float3 mn = float3(mq, sqrt(max(1.0 - dot(mq, mq), 0.0)));
        float ml = sat(dot(mn, normalize(float3(0.75, -0.35, 0.55))));
        float crater = fbm(mq * 3.0 + 7.0);
        col = mix(col, float3(0.8, 0.82, 0.86) * (0.35 + 0.65 * crater) * ml + BG * 0.6, smoothstep(mr, mr - 0.0025, md));
    }
    col += air * exp(-max(md - mr, 0.0) * 60.0) * 0.06;

    return half4(finish(col, fc), 1.0);
}
"""

    private const val CHILL_MOON = """
// Moon tide: Toni's painting of a lighthouse under a full moon (res scene_chill_moon), brought to life.
// The sea swells and glitters along the moon's path, the lighthouse lamp pulses and its beam breathes with
// mist drifting through it, the moon's halo glows softly, thin wisps drift past and the stars twinkle.
// (The procedural version is kept as chill_moon_drawn.agsl.)
// Shared by the painted scenes (the user's own paintings with motion added on top: aurora, meadow,
// px_dojo): the painting fills the screen like a cover (cropped, never stretched) round a chosen point.
uniform shader uPaint;      // the painting (ScenePainting: res/drawable-nodpi/scene_*.webp)
uniform float2 uPaintSize;  // its decoded size in pixels
uniform float uHasPaint;    // 0 while it decodes (a plain gradient in the theme's colours shows)

// The painting's pixel under screen point fc, filling the screen, the crop centred on (fx, fy) (0..1 across it).
float2 paintPx(float2 fc, float fx, float fy) {
    float2 sz = max(uPaintSize, float2(1.0));
    float s = max(uRes.x / sz.x, uRes.y / sz.y);
    float2 off = (sz * s - uRes) * float2(fx, fy);
    return (fc + off) / s;
}

// The painting's colour at pixel p (clamped inside it).
float3 paintAt(float2 p) { return float3(uPaint.eval(clamp(p, float2(0.5), max(uPaintSize, float2(1.0)) - 0.5)).rgb); }

// Brightness, for picking out lit parts of the painting.
float luma(float3 c) { return dot(c, float3(0.299, 0.587, 0.114)); }

// How much pixel p is a small bright speck (a star) rather than part of a bright area: brighter than the
// painting a few pixels away on both sides. lum is its own brightness.
float speckAt(float2 p, float lum) {
    float k = max(uPaintSize.y, 1.0) / 941.0 * 4.0;
    float n = (luma(paintAt(p + float2(k, k * 0.5))) + luma(paintAt(p - float2(k * 0.5, k)))) * 0.5;
    return smoothstep(0.06, 0.2, lum - n);
}

// The painted chill scenes' finish: the painting's own colours and framing (no vignette, no highlight
// roll-off), only the fine noise that keeps dark gradients from banding.
float3 finishPaint(float3 col, float2 fc) {
    col = clamp(col, 0.0, 1.0);
    return col + (hash12(fc) - 0.5) / 255.0;
}

half4 main(float2 fc) {
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 BG = uBg.rgb;
    if (uHasPaint < 0.5) {
        float2 uv = fc / uRes;
        return half4(finish(mix(BG * 1.2, BG * 0.8, uv.y), fc), 1.0);
    }
    float2 sz = max(uPaintSize, float2(1.0));
    float2 p = paintPx(fc, 0.5, 0.5);
    float2 q = p / sz;
    float2 r = q * float2(1672.0, 941.0);          // painting reference pixels
    float aspP = sz.x / sz.y;

    // The sea (below the horizon, right of the rock): a slow swell sways the reflections.
    float hz = 668.0;
    float rockX = 240.0 + max(r.y - 680.0, 0.0) * 0.8;
    float sea = smoothstep(hz + 2.0, hz + 10.0, r.y) * smoothstep(rockX + 10.0, rockX + 45.0, r.x);
    float depth = sat((r.y - hz) / 270.0);
    float sw = sin(r.y * 0.09 - t * 0.9 + sin(r.x * 0.01) * 2.0) * 0.6 + sin(r.y * 0.23 + r.x * 0.004 - t * 1.4) * 0.4;
    float2 off = float2(sw * (0.6 + 4.5 * depth), sin(r.x * 0.02 + t * 0.6) * 0.6 * depth) * sea;
    float3 col = paintAt(p + off / float2(1672.0, 941.0) * sz);
    float lum = luma(col);

    // Glitter on the moon's path: bright crests sparkling and moving.
    float path = exp(-sqf((r.x - 1420.0) / (55.0 + depth * 90.0))) * sea;
    float2 gp = float2(r.x * 0.05, r.y * (0.12 + 0.3 * (1.0 - depth)));
    float glit = smoothstep(0.78, 0.95, vnoise(gp + float2(t * 0.6, -t * 0.4))) * (0.5 + 0.5 * sin(t * 3.0 + r.x));
    col += float3(0.9, 0.93, 1.0) * glit * path * 0.45;
    col *= 1.0 + path * smoothstep(0.3, 0.6, lum) * 0.12 * sin(t * 1.2 + r.y * 0.1);

    // The lighthouse: the lamp pulses, the beam breathes, mist drifts through it.
    float2 lamp = float2(140.0, 508.0);
    float pulse = 0.85 + 0.15 * sin(t * 1.6) + 0.05 * sin(t * 4.3);
    float2 bdir = normalize(float2(460.0, 372.0));
    float2 bp = r - lamp;
    float along = dot(bp, bdir);
    float across = abs(bp.x * bdir.y - bp.y * bdir.x);
    float beam = step(0.0, along) * exp(-across / (6.0 + max(along, 0.0) * 0.07)) * exp(-max(along, 0.0) * 0.0018);
    float mist = fbm3(float2(along * 0.012 - t * 0.25, across * 0.05 + t * 0.05));
    col *= 1.0 + beam * ((pulse - 0.9) * 1.2 + (mist - 0.5) * 0.5);
    col += float3(1.0, 0.92, 0.75) * beam * smoothstep(0.5, 0.8, mist) * 0.06;
    col += float3(1.0, 0.85, 0.55) * exp(-length(r - lamp) * 0.06) * (pulse - 0.8) * 0.6;

    // The moon's halo glows softly; thin wisps drift past it.
    float md = length(r - float2(1420.0, 185.0));
    col += float3(0.85, 0.9, 1.0) * exp(-max(md - 105.0, 0.0) * 0.02) * step(105.0, md) * 0.04 * (0.6 + 0.4 * sin(t * 0.3));
    float wisp = fbm(float2(r.x * 0.0025 + t * 0.008, r.y * 0.012));
    float wispBand = exp(-sqf((r.y - 230.0) / 110.0)) * smoothstep(900.0, 1250.0, r.x) * step(r.y, hz);
    col += float3(0.75, 0.8, 0.95) * smoothstep(0.55, 0.78, wisp) * wispBand * exp(-max(md - 105.0, 0.0) * 0.004) * 0.14;

    // Stars twinkle.
    float sky = step(r.y, hz - 20.0) * step(130.0, md) * (1.0 - beam);
    float speck = speckAt(p, lum) * sky;
    float2 cell = floor(r / 3.0);
    float tw = 0.5 + 0.5 * sin(t * (1.3 + 2.0 * hash12(cell)) + hash12(cell + 5.0) * 40.0);
    col *= 1.0 + speck * (tw - 0.5) * 0.9;

    return half4(finishPaint(col, fc), 1.0);
}
"""

    private const val CHILL_ORBS = """
// Glass orbs: big glass spheres resting in two clusters, bottom-left and top-right, floating up and down
// very slowly. Each one bends the soft coloured light behind it, has a bright rim, a window-shaped
// highlight and a warm caustic glowing under it. Between them, only the soft gradient (original design).

// The backdrop at p: soft coloured lights on a deep gradient (also what the glass bends).
float3 backdrop(float2 p, float asp, float t, float3 A, float3 S, float3 BG) {
    float3 c = mix(BG * 1.25, BG * 0.8, sat(p.y));
    float2 l1 = p - float2(asp * 0.12 + 0.05 * sin(t * 0.07), 0.85);
    float2 l2 = p - float2(asp * 0.9, 0.12 + 0.04 * cos(t * 0.06));
    float2 l3 = p - float2(asp * 0.62, 0.95);
    c += A * exp(-dot(l1, l1) * 3.5) * 0.35;
    c += S * exp(-dot(l2, l2) * 4.0) * 0.3;
    c += mix(A, S, 0.5) * exp(-dot(l3, l3) * 6.0) * 0.12;
    // Faint diagonal bands so the bending shows.
    c += mix(A, S, 0.5) * 0.035 * sin((p.x + p.y * 0.6) * 9.0 + t * 0.05);
    return c;
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    float3 col = backdrop(uv, asp, t, A, S, BG);
    float3 L = normalize(float3(-0.5, -0.65, 0.6));

    // Draw the orbs back to front (smaller ones are further away).
    for (int i = 0; i < 9; i++) {
        if (uLod > 1.5 && i > 5) break;
        float fi = float(i);
        float corner = step(4.5, fi);            // 0 bottom-left cluster, 1 top-right
        float k = fi - corner * 5.0;
        float h1 = hash11(fi * 3.17 + 0.5);
        float h2 = hash11(fi * 7.31 + 1.7);
        // Clusters hugging their corners: a big orb partly off-screen, smaller ones fanned round it.
        float r = k < 0.5 ? 0.21 - 0.03 * corner : mix(0.04, 0.1, h1) * (1.0 - 0.1 * corner);
        float a = mix(-1.5, -0.05, (k - 1.0) / 3.0) + 0.15 * (h2 - 0.5);
        float dist = k < 0.5 ? 0.0 : 0.23 + 0.12 * h2 + 0.02 * k;
        float2 home = corner < 0.5
            ? float2(asp * 0.06, 0.93) + float2(cos(a), sin(a)) * dist * float2(1.15, 1.0)
            : float2(asp * 0.95, 0.07) - float2(cos(a), sin(a)) * dist * float2(1.15, 1.0);
        float2 c = home + float2(0.012 * sin(t * 0.11 + fi * 2.0), 0.02 * sin(t * 0.17 + fi * 1.3));
        float2 q = (uv - c) / r;
        float d2 = dot(q, q);
        // Soft shadow / caustic on the backdrop below-right of the orb.
        float2 sh = (uv - c - float2(0.25, 0.55) * r) / (r * 1.1);
        col *= 1.0 - 0.18 * exp(-dot(sh, sh) * 2.5);
        float3 tint = mix(A, S, h2);
        col += mix(tint, float3(1.0, 0.95, 0.85), 0.4) * exp(-dot(sh * float2(1.0, 2.2) + float2(0.0, 0.25), sh * float2(1.0, 2.2) + float2(0.0, 0.25)) * 6.0) * 0.12;
        if (d2 < 1.0) {
            float z = sqrt(1.0 - d2);
            float3 n = float3(q, z);
            // Refraction: the backdrop seen through the glass, bent and flipped a little.
            float2 bent = c - q * r * (0.55 + 0.35 * z);
            float3 inside = backdrop(bent, asp, t, A, S, BG);
            inside = mix(inside, inside * tint * 1.6, 0.35) * 1.1;
            float fres = pow(1.0 - z, 3.0);
            float3 glass = inside + tint * fres * 0.55;
            // Highlights: a soft window-shaped one and a sharp point, plus a faint second one opposite.
            float2 hp = q - float2(-0.38, -0.42);
            float win = exp(-dot(hp * float2(2.2, 3.2), hp * float2(2.2, 3.2)) * 6.0);
            float spec = pow(sat(dot(reflect(-L, n), float3(0.0, 0.0, 1.0))), 60.0);
            glass += float3(1.0) * (win * 0.4 + spec * 0.6);
            float2 rp = q - float2(0.45, 0.5);
            glass += mix(tint, float3(1.0), 0.5) * exp(-dot(rp, rp) * 18.0) * 0.18 * (1.0 - z);
            // Inner caustic: light gathered at the bottom inside the sphere.
            float2 cp = q - float2(0.15, 0.55);
            glass += mix(tint, float3(1.0, 0.95, 0.8), 0.3) * exp(-dot(cp, cp) * 9.0) * 0.18;
            float edgeAA = smoothstep(1.0, 0.96, d2);
            col = mix(col, glass, edgeAA);
        }
        // Thin bright rim.
        col += mix(tint, float3(1.0), 0.6) * exp(-abs(sqrt(d2) - 1.0) * r * 900.0) * 0.25;
    }

    // A few tiny bubbles drifting up near the clusters.
    float bub = dots(uv, 40.0, float2(0.0, t * 0.02), 0.1, 0.07, 6.0);
    float zone = max(exp(-length(uv - float2(asp * 0.15, 0.85)) * 3.0), exp(-length(uv - float2(asp * 0.88, 0.15)) * 3.0));
    col += mix(A, float3(1.0), 0.6) * bub * zone * 0.4;

    return half4(finish(col, fc), 1.0);
}
"""

    private const val CHILL_SILK = """
// Silk folds: Toni's painting of two satin sheets in the corners (res scene_chill_silk), brought to life.
// The silk ripples softly as if a breeze ran under it, a sheen slides slowly along the folds, a glint of
// light travels along each sheet's edge, and the dark middle breathes a faint glow.
// (The procedural version is kept as chill_silk_drawn.agsl.)
// Shared by the painted scenes (the user's own paintings with motion added on top: aurora, meadow,
// px_dojo): the painting fills the screen like a cover (cropped, never stretched) round a chosen point.
uniform shader uPaint;      // the painting (ScenePainting: res/drawable-nodpi/scene_*.webp)
uniform float2 uPaintSize;  // its decoded size in pixels
uniform float uHasPaint;    // 0 while it decodes (a plain gradient in the theme's colours shows)

// The painting's pixel under screen point fc, filling the screen, the crop centred on (fx, fy) (0..1 across it).
float2 paintPx(float2 fc, float fx, float fy) {
    float2 sz = max(uPaintSize, float2(1.0));
    float s = max(uRes.x / sz.x, uRes.y / sz.y);
    float2 off = (sz * s - uRes) * float2(fx, fy);
    return (fc + off) / s;
}

// The painting's colour at pixel p (clamped inside it).
float3 paintAt(float2 p) { return float3(uPaint.eval(clamp(p, float2(0.5), max(uPaintSize, float2(1.0)) - 0.5)).rgb); }

// Brightness, for picking out lit parts of the painting.
