    private const val CHILL_RAIN = """
// Rainy window: night city lights melted into soft bokeh behind a window pane. Raindrops bead on the glass,
// most of them round the edges and corners, each a tiny upside-down lens of the lights behind; now and
// then one runs down, leaving a clear trail through the mist on the glass. The middle stays clearer.

// The city behind the glass, out of focus: soft discs of light on a dark gradient.
float3 bokeh(float2 p, float asp, float t, float3 A, float3 S, float3 BG) {
    float3 c = mix(BG * 1.4 + S * 0.03, BG * 0.9 + A * 0.04, smoothstep(0.1, 1.0, p.y));
    // The glow of the street low down.
    c += mix(A, S, 0.3) * exp(-sqf((p.y - 0.95) / 0.3)) * 0.12;
    for (int layer = 0; layer < 2; layer++) {
        float fl = float(layer);
        float sc = 3.2 + 2.4 * fl;
        for (int j = 0; j < 4; j++) {
            float2 off = float2(float(j / 2), float(j - (j / 2) * 2)) * 0.5;
            float2 g = p * sc + off + float2(t * 0.01 * (1.0 + fl), 0.0);
            float2 id = floor(g);
            float2 f = g - id - 0.5;
            float2 r = hash22(id + fl * 17.0 + off * 3.0);
            // More lights lower down (the street) and towards the sides.
            float2 cellP = (id + 0.5 - off - float2(t * 0.01 * (1.0 + fl), 0.0)) / sc;
            float2 cq = (cellP - float2(asp * 0.5, 0.45)) / float2(asp * 0.5, 0.5);
            float want = 0.62 * smoothstep(0.55, 1.05, length(cq * float2(0.9, 1.1)));
            if (r.x > want) continue;
            float rad = 0.14 + 0.12 * r.y;
            float d = length(f - (hash22(id + 5.0 + fl) - 0.5) * 0.36);
            float disc = smoothstep(rad, rad - 0.035, d);
            float rim = exp(-abs(d - rad + 0.02) * 40.0) * disc;
            float3 lc = r.y > 0.5 ? A : S;
            lc = mix(lc, float3(1.0, 0.95, 0.85), hash11(id.x * 3.0 + id.y + fl) * 0.4);
            float tw = 0.75 + 0.25 * sin(t * (0.5 + r.y) + r.x * 30.0);
            c += lc * (disc * 0.26 + rim * 0.14) * tw * (1.0 - 0.4 * fl);
        }
    }
    return c;
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    // How misty / wet the glass is here: more round the edges and corners.
    float2 cq = (uv - float2(asp * 0.5, 0.5)) / float2(asp * 0.5, 0.5);
    float edge = sat(max(abs(cq.x), abs(cq.y)) * 0.6 + length(cq) * 0.35 - 0.35);
    float mist = smoothstep(0.15, 0.8, edge) * (0.75 + 0.25 * fbm3(uv * 3.0));

    float3 behind = bokeh(uv, asp, t, A, S, BG);
    // Mist: lighter, flatter, a little blue.
    float3 col = mix(behind, behind * 0.7 + mix(BG, S, 0.2) * 0.9 + 0.025, mist * 0.6);

    // Beaded drops on the glass.
    float sc = 22.0;
    float2 g = uv * sc;
    float2 id = floor(g);
    float2 f = g - id - 0.5;
    float2 r = hash22(id + 3.7);
    float dropHere = step(r.x, 0.03 + 0.55 * mist * mist);
    float rad = 0.12 + 0.24 * r.y * r.y;
    float2 dc = (hash22(id + 9.1) - 0.5) * (0.9 - rad * 2.0);
    float2 dq = (f - dc) / rad;
    float dd = dot(dq, dq);
    // Running drops: in a few columns a drop slides down now and then, clearing a trail.
    float colW = 0.045;
    float cx = floor(uv.x / colW);
    float ch = hash11(cx * 1.37 + 2.0);
    float runs = step(0.62, ch) * smoothstep(0.1, 0.5, edge + 0.2 * ch);
    float speed = 0.05 + 0.08 * ch;
    float headY = fract(t * speed + ch * 7.0) * 1.4 - 0.2;
    float lx = (fract(uv.x / colW) - 0.5 + 0.12 * sin(uv.y * 30.0 + ch * 10.0)) * colW;
    float trail = runs * step(uv.y, headY) * smoothstep(0.012, 0.004, abs(lx)) * exp(-(headY - uv.y) * 2.5);
    col = mix(col, behind, trail * 0.8 * mist);
    float2 hq = float2(lx / 0.011, (uv.y - headY) / 0.016);
    float hd = dot(hq, hq) * runs;
    // Drop shading (beaded or running): an upside-down lens of the lights, dark rim, bright glint.
    float isDrop = dropHere * step(dd, 1.0) * (1.0 - trail);
    float isHead = step(hd, 1.0) * runs;
    if (isDrop + isHead > 0.0) {
        float2 q = isHead > 0.0 ? hq : dq;
        float z = sqrt(max(1.0 - dot(q, q), 0.0));
        float3 lens = bokeh(uv - q * 0.08 + float2(0.0, 0.05), asp, t, A, S, BG) * 1.5 + 0.03;
        lens *= 0.55 + 0.45 * z;
        lens += float3(1.0) * exp(-dot(q - float2(-0.35, -0.45), q - float2(-0.35, -0.45)) * 18.0) * 0.6;
        lens += mix(A, float3(1.0), 0.5) * exp(-abs(sqrt(dot(q, q)) - 0.92) * 20.0) * 0.08;
        lens *= 1.0 - 0.3 * smoothstep(0.75, 1.0, sqrt(dot(q, q)));
        col = mix(col, lens, smoothstep(1.0, 0.8, dot(q, q)));
    }
    // A fine haze of tiny droplets in the mist.
    col += float3(0.8, 0.85, 0.9) * dots(uv, 120.0, float2(0.0), 0.35, 0.12, 4.0) * mist * 0.05;

    return half4(finish(col, fc), 1.0);
}
"""

    private const val CHILL_CITY = """
// Rooftop dusk: Toni's painting of a city skyline at dusk (res scene_chill_city), brought to life. Lights in
// the windows dim and come back here and there as people come and go, the far skyline's windows shimmer,
// the antenna's red light blinks, the pink clouds drift, the stars twinkle and a plane glides over.
// (The procedural version is kept as chill_city_drawn.agsl.)
// Shared by the painted scenes (the user's own paintings with motion added on top: aurora, meadow,
// px_dojo): the painting fills the screen like a cover (cropped, never stretched) round a chosen point.
uniform shader uPaint;      // the painting (ScenePainting: res/drawable-nodpi/scene_*.webp)
uniform float2 uPaintSize;  // its decoded size in pixels
uniform float uHasPaint;    // 0 while it decodes (a plain gradient in the theme's colours shows)

// The painting's pixel under screen point fc, filling the screen, the crop centred on (fx, fy) (0..1 across it).
float2 paintPx(float2 fc, float fx, float fy) {
    float2 sz = max(uPaintSize, float2(1.0));
    float s = max(uRes.x / sz.x, uRes.y / sz.y);
    float2 off = (sz * s - uRes) * float2(fx, fy);
    return (fc + off) / s;
}

// The painting's colour at pixel p (clamped inside it).
float3 paintAt(float2 p) { return float3(uPaint.eval(clamp(p, float2(0.5), max(uPaintSize, float2(1.0)) - 0.5)).rgb); }

// Brightness, for picking out lit parts of the painting.
float luma(float3 c) { return dot(c, float3(0.299, 0.587, 0.114)); }

// How much pixel p is a small bright speck (a star) rather than part of a bright area: brighter than the
// painting a few pixels away on both sides. lum is its own brightness.
float speckAt(float2 p, float lum) {
    float k = max(uPaintSize.y, 1.0) / 941.0 * 4.0;
    float n = (luma(paintAt(p + float2(k, k * 0.5))) + luma(paintAt(p - float2(k * 0.5, k)))) * 0.5;
    return smoothstep(0.06, 0.2, lum - n);
}

// The painted chill scenes' finish: the painting's own colours and framing (no vignette, no highlight
// roll-off), only the fine noise that keeps dark gradients from banding.
float3 finishPaint(float3 col, float2 fc) {
    col = clamp(col, 0.0, 1.0);
    return col + (hash12(fc) - 0.5) / 255.0;
}

half4 main(float2 fc) {
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 BG = uBg.rgb;
    if (uHasPaint < 0.5) {
        float2 uv = fc / uRes;
        return half4(finish(mix(BG * 1.2, mix(BG, A, 0.3), uv.y), fc), 1.0);
    }
    float2 sz = max(uPaintSize, float2(1.0));
    float2 p = paintPx(fc, 0.5, 0.5);
    float2 q = p / sz;
    float2 r = q * float2(1672.0, 941.0);
    float aspP = sz.x / sz.y;

    // The pink clouds drift slowly to the right (their band only).
    float cloudBand = exp(-sqf((r.y - 365.0) / 60.0));
    float2 coff = float2(sin(r.y * 0.05 + t * 0.07) * 12.0 + sin(t * 0.03) * 10.0, 0.0) * cloudBand;
    float3 col = paintAt(p - coff / float2(1672.0, 941.0) * sz);
    float lum = luma(col);

    // Windows: warm lit pixels below the skyline. Areas of them dim and come back slowly.
    float city = smoothstep(560.0, 600.0, r.y);
    // (Yellow, not the pink-orange sky: windows have far less blue than green.)
    float warm = sat((col.g - col.b) * 5.0) * sat((col.r - col.b) * 3.0) * smoothstep(0.25, 0.45, lum) * city;
    float area = vnoise(r * float2(0.018, 0.022) + float2(t * 0.03, t * 0.017));
    float dim = smoothstep(0.62, 0.78, area);
    float3 wall = float3(0.05, 0.04, 0.07);
    col = mix(col, mix(col, wall, 0.85), warm * dim);
    // A gentle flicker on the near windows (TV light), and a shimmer on the far ones.
    float near = smoothstep(640.0, 720.0, r.y);
    float flick = 0.94 + 0.06 * sin(t * 6.0 + floor(r.x / 21.0) * 1.7) * sin(t * 2.3 + floor(r.y / 18.0));
    col *= 1.0 + warm * (1.0 - dim) * (flick - 0.97) * 2.0 * near;
    col *= 1.0 + warm * (1.0 - near) * 0.15 * sin(t * 1.5 + r.x * 0.3 + r.y * 0.2);

    // The antenna's red light blinks.
    float2 ant = float2(1514.0, 557.0);
    float red = step(0.55, fract(t * 0.5));
    float ad = length(r - ant);
    col += float3(1.0, 0.18, 0.12) * (exp(-ad * 0.45) * 0.9 + exp(-ad * 0.05) * 0.12) * red;

    // Stars twinkle.
    float sky = step(r.y, 300.0);
    float speck = speckAt(p, lum) * sky;
    float2 cell = floor(r / 3.0);
    float tw = 0.5 + 0.5 * sin(t * (1.3 + 2.0 * hash12(cell)) + hash12(cell + 5.0) * 40.0);
    col *= 1.0 + speck * (tw - 0.5) * 0.9;

    // A plane gliding across high up, its lights blinking (once every 70 s).
    float pt = fract(t / 70.0) * 70.0;
    if (pt < 40.0) {
        float2 pl = float2(-40.0 + pt / 40.0 * 1750.0, 150.0 + 25.0 * sin(pt * 0.05));
        float pd = length(r - pl);
        float blink = step(0.85, fract(t * 0.9));
        col += float3(1.0, 0.3, 0.25) * exp(-pd * 0.7) * (0.25 + 0.75 * blink);
        col += float3(1.0) * exp(-length(r - pl - float2(-6.0, 0.0)) * 0.9) * 0.6;
    }

    return half4(finishPaint(col, fc), 1.0);
}
"""

    private const val CHILL_JELLY = """
// Jellyfish drift: the open sea at dusk, light falling in soft rays from the surface. A few glowing
// jellyfish drift in the corners — bells pulsing slowly, frilled edges, long tentacles swaying behind —
// while specks of sea snow float past. The middle stays deep, quiet water (original design).

// One jellyfish at c (bell radius r), pulsing with phase ph, heading up (tilt a). Returns glow (rgb) and alpha.
float4 jelly(float2 p, float2 c, float r, float ph, float a, float3 tint, float t) {
    float2 q = rot(a) * (p - c) / r;
    float pulse = 0.5 + 0.5 * sin(t * 1.3 + ph);
    // Bell: a dome, wider when it opens, taller when it squeezes.
    float2 bq = q * float2(1.0 / (1.0 + 0.12 * pulse), 1.0 / (1.0 - 0.1 * pulse));
    float dome = length(bq * float2(1.0, 1.25)) - 1.0;
    float below = step(0.0, bq.y);
    float hem = 0.05 * sin(atan(bq.x, 0.2) * 9.0 + t * 2.0);
    float bell = max(dome, (bq.y - 0.15 - hem)) ;
    float inBell = smoothstep(0.04, -0.04, bell);
    // Inner pattern: four soft lobes and radial lines.
    float ang = atan(bq.x, -bq.y + 0.4);
    float lobes = exp(-sqf(length(bq - float2(0.0, -0.25)) - 0.35) * 30.0) * (0.6 + 0.4 * sin(ang * 4.0));
    float lines = smoothstep(0.85, 1.0, sin(ang * 16.0)) * 0.4;
    float rim = exp(-abs(bell) * 18.0);
    float3 jc = tint * (inBell * (0.22 + 0.45 * sat(-bq.y)) + lobes * inBell * 0.5 + lines * inBell * 0.25 + rim * 0.8);
    // Glowing dots round the bell's edge.
    float2 ep = float2(atan(bq.x, bq.y - 0.1) * 6.0, bell * 12.0);
    jc += mix(tint, float3(1.0), 0.5) * exp(-dot(fract(ep) - 0.5, fract(ep) - 0.5) * 30.0) * exp(-abs(bell) * 25.0) * (0.4 + 0.6 * pulse);
    float alpha = inBell * 0.65 + rim * 0.3;
    // Tentacles: a few wavy threads trailing below the bell.
    float tent = 0.0;
    for (int k = 0; k < 5; k++) {
        float fk = float(k) - 2.0;
        float x0 = fk * 0.28 * (1.0 + 0.1 * pulse);
        float y = q.y - 0.15;
        float wave = 0.12 * sin(y * 3.0 - t * 1.6 + fk * 1.3 + ph) * sat(y * 0.6);
        float d = abs(q.x - x0 - wave - fk * 0.05 * y);
        tent += smoothstep(0.035, 0.0, d) * step(0.0, y) * exp(-y * 0.3) * smoothstep(5.0, 3.5, y);
    }
    // Oral arms: two thicker frilly ribbons in the middle.
    float y2 = q.y - 0.1;
    float arm = smoothstep(0.12, 0.0, abs(abs(q.x) - 0.1 - 0.06 * sin(y2 * 5.0 - t * 1.2 + ph))) * step(0.0, y2) * exp(-y2 * 0.9);
    jc += mix(tint, float3(1.0), 0.2) * (tent * 0.45 + arm * 0.5);
    alpha = max(alpha, sat(tent * 0.35 + arm * 0.5));
    return float4(jc, alpha);
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    // Water: lighter towards the surface, light rays slanting down from the top.
    float3 col = mix(BG * 2.2 + A * 0.04, BG * 0.7, smoothstep(0.0, 1.0, uv.y));
    float rx = uv.x + uv.y * 0.35;
    float rays = fbm3(float2(rx * 5.0 + t * 0.03, t * 0.05)) * smoothstep(0.9, 0.0, uv.y);
    col += mix(A, float3(0.8, 0.95, 1.0), 0.5) * sqf(rays) * 0.12;
    // Surface shimmer at the very top.
    col += A * smoothstep(0.6, 0.9, vnoise(float2(uv.x * 14.0 + t * 0.2, t * 0.3))) * exp(-uv.y * 18.0) * 0.12;

    // Sea snow drifting.
    col += float3(0.8, 0.9, 1.0) * dots(uv, 45.0, float2(t * 0.004, -t * 0.006), 0.12, 0.05, 4.0) * 0.18;
    col += float3(0.8, 0.9, 1.0) * dots(uv, 90.0, float2(t * 0.002, -t * 0.003), 0.15, 0.06, 9.0) * 0.1;

    // Jellyfish: two near the bottom-left, two near the top-right, one small far away.
    for (int i = 0; i < 5; i++) {
        if (uLod > 1.5 && i > 2) break;
        float fi = float(i);
        float2 home = i == 0 ? float2(0.1, 0.58) : i == 1 ? float2(0.24, 0.8) : i == 2 ? float2(0.87, 0.14) : i == 3 ? float2(0.72, 0.1) : float2(0.95, 0.6);
        float r = i == 0 ? 0.11 : i == 1 ? 0.07 : i == 2 ? 0.1 : i == 3 ? 0.055 : 0.04;
        // A slow rise and drift, then sink back: they never leave their corner.
        float2 c = float2(home.x * asp, home.y) + float2(0.03 * sin(t * 0.05 + fi * 2.0), 0.04 * sin(t * 0.07 + fi * 1.4));
        float a = 0.25 * sin(t * 0.06 + fi * 1.7);
        float3 tint = mix(A, S, hash11(fi * 3.3 + 1.0));
        float4 j = jelly(uv, c, r, fi * 1.9, a, tint, t);
        // Far ones fade into the water.
        float fade = i == 4 ? 0.55 : 1.0;
        col = mix(col, col * 0.85 + j.rgb, j.a * fade);
        col += tint * exp(-length(uv - c) / r * 0.9) * 0.1 * fade;
    }

    return half4(finish(col, fc), 1.0);
}
"""

    private const val CHILL_GLADE = """
// Firefly glade: Toni's painting of a misty night forest (res scene_chill_glade), brought to life. The
// fireflies blink and more drift between the trees, mist rolls slowly through the clearing, the moonbeam
// shimmers with motes floating in it, and the leaves and grass sway a little.
// (The procedural version is kept as chill_glade_drawn.agsl.)
// Shared by the painted scenes (the user's own paintings with motion added on top: aurora, meadow,
// px_dojo): the painting fills the screen like a cover (cropped, never stretched) round a chosen point.
uniform shader uPaint;      // the painting (ScenePainting: res/drawable-nodpi/scene_*.webp)
uniform float2 uPaintSize;  // its decoded size in pixels
uniform float uHasPaint;    // 0 while it decodes (a plain gradient in the theme's colours shows)

// The painting's pixel under screen point fc, filling the screen, the crop centred on (fx, fy) (0..1 across it).
float2 paintPx(float2 fc, float fx, float fy) {
    float2 sz = max(uPaintSize, float2(1.0));
    float s = max(uRes.x / sz.x, uRes.y / sz.y);
    float2 off = (sz * s - uRes) * float2(fx, fy);
    return (fc + off) / s;
}

// The painting's colour at pixel p (clamped inside it).
float3 paintAt(float2 p) { return float3(uPaint.eval(clamp(p, float2(0.5), max(uPaintSize, float2(1.0)) - 0.5)).rgb); }

// Brightness, for picking out lit parts of the painting.
float luma(float3 c) { return dot(c, float3(0.299, 0.587, 0.114)); }

// How much pixel p is a small bright speck (a star) rather than part of a bright area: brighter than the
// painting a few pixels away on both sides. lum is its own brightness.
float speckAt(float2 p, float lum) {
    float k = max(uPaintSize.y, 1.0) / 941.0 * 4.0;
    float n = (luma(paintAt(p + float2(k, k * 0.5))) + luma(paintAt(p - float2(k * 0.5, k)))) * 0.5;
    return smoothstep(0.06, 0.2, lum - n);
}

// The painted chill scenes' finish: the painting's own colours and framing (no vignette, no highlight
// roll-off), only the fine noise that keeps dark gradients from banding.
float3 finishPaint(float3 col, float2 fc) {
    col = clamp(col, 0.0, 1.0);
    return col + (hash12(fc) - 0.5) / 255.0;
}

// The painted fireflies (painting reference pixels).
float paintedFly(float2 r, float2 c, float rad) { return exp(-dot(r - c, r - c) / (rad * rad)); }

half4 main(float2 fc) {
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    if (uHasPaint < 0.5) {
        float2 uv = fc / uRes;
        return half4(finish(mix(BG * 2.0, BG, uv.y), fc), 1.0);
    }
    float2 sz = max(uPaintSize, float2(1.0));
    float2 p = paintPx(fc, 0.5, 0.5);
    float2 q = p / sz;
    float2 r = q * float2(1672.0, 941.0);
    float aspP = sz.x / sz.y;

    // Leaves in the top corners and grass along the bottom sway a little.
    float leaves = max(smoothstep(320.0, 120.0, r.x), smoothstep(1420.0, 1600.0, r.x)) * smoothstep(260.0, 60.0, r.y);
    float grass = smoothstep(760.0, 860.0, r.y);
    float sway = sin(t * 0.7 + r.x * 0.01) * 0.6 + sin(t * 1.3 + r.y * 0.05) * 0.4;
    float2 off = float2(sway * (2.2 * leaves + 1.6 * grass * (1.0 - smoothstep(860.0, 941.0, r.y) * 0.7)), sway * 0.8 * leaves);
    float3 col = paintAt(p + off / float2(1672.0, 941.0) * sz);
    float lum = luma(col);

    // The moonbeam shimmers; motes float in it.
    float cx = mix(1040.0, 880.0, r.y / 600.0);
    float w = mix(55.0, 170.0, sat(r.y / 600.0));
    float beam = exp(-sqf((r.x - cx) / w)) * smoothstep(720.0, 300.0, r.y);
    float shim = fbm3(float2((r.x - cx) * 0.02, r.y * 0.006 - t * 0.08));
    col *= 1.0 + beam * (shim - 0.5) * 0.25;
    col += float3(0.8, 0.95, 0.9) * dots(q * float2(aspP, 1.0), 70.0, float2(t * 0.004, t * 0.01), 0.18, 0.06, 5.0) * beam * 0.6;

    // Mist rolling slowly through the clearing.
    float2 mp = float2(r.x * 0.0022 + t * 0.012, r.y * 0.006);
    float mist = fbm(mp + float2(fbm3(mp * 1.7 - t * 0.01) * 0.8, 0.0));
    float band = exp(-sqf((r.y - 620.0) / 160.0));
    col = mix(col, mix(S, float3(0.6, 0.8, 0.75), 0.5) * 0.42, smoothstep(0.5, 0.85, mist) * band * 0.16);

    // The painted fireflies blink, each at its own pace: dimming one fades it towards the forest just above it.
    for (int i = 0; i < 6; i++) {
        float2 c = i == 0 ? float2(22.0, 403.0) : i == 1 ? float2(240.0, 518.0) : i == 2 ? float2(533.0, 428.0)
