    private const val CHILL_HEX = """
// Hex lattice: a calm tech panel. Bevelled hexagon tiles fill the bottom-right and top-left corners and
// fade out towards the middle; now and then a soft pulse runs across them, lighting tiles as it passes,
// and a few tiles glow on their own. A thin sweep of light crosses slowly (original design).

// Hex grid: returns (local x, local y, cell id x, cell id y).
float4 hexCell(float2 p) {
    float2 r = float2(1.0, 1.7320508);
    float2 h = r * 0.5;
    float2 a = mod(p, r) - h;
    float2 b = mod(p - h, r) - h;
    float2 gv = dot(a, a) < dot(b, b) ? a : b;
    float2 id = p - gv;
    return float4(gv, id);
}

float hexDist(float2 p) {
    p = abs(p);
    return max(dot(p, normalize(float2(1.0, 1.7320508))), p.x);
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    float3 col = mix(BG * 1.4, BG * 0.8, sat(uv.y));
    col += A * exp(-length((uv - float2(asp, 1.0)) * float2(0.9, 1.0)) * 2.2) * 0.12;
    col += S * exp(-length(uv * float2(0.9, 1.0)) * 2.8) * 0.1;
    col += mix(A, S, 0.5) * exp(-length(uv - float2(asp * 0.5, 0.5)) * 2.5) * 0.03;

    // How much lattice shows here: the two corners.
    float2 c1 = (uv - float2(asp, 1.0)) * float2(0.9, 1.0);
    float2 c2 = (uv - float2(0.0, 0.0)) * float2(0.9, 1.0);
    float zone = max(smoothstep(0.85, 0.25, length(c1)), smoothstep(0.62, 0.18, length(c2)) * 0.85);

    float sc = 13.0;
    float4 h = hexCell(uv * sc);
    float2 gv = h.xy;
    float2 id = h.zw;
    float d = hexDist(gv);                       // 0 centre .. 0.5 edge
    float2 cellC = id / sc;
    float2 cc1 = (cellC - float2(asp, 1.0)) * float2(0.9, 1.0);
    float2 cc2 = cellC * float2(0.9, 1.0);
    float cellZone = max(smoothstep(0.85, 0.25, length(cc1)), smoothstep(0.62, 0.18, length(cc2)) * 0.85);
    // Tiles thin out at the edge of the zone (some missing).
    float present = step(hash12(id) * 0.9, cellZone);
    // Each tile: a raised plate with a bevel lit from the top-left.
    float plate = smoothstep(0.47, 0.44, d);
    float bevel = smoothstep(0.36, 0.44, d) * plate;
    float2 nrm = normalize(gv + 1e-4);
    float lightSide = dot(nrm, normalize(float2(-0.6, -0.8)));
    // Faces shade from the secondary colour near the corner to dark further out.
    float3 tile = BG * 2.0 + mix(S, A, 0.3) * (0.06 + 0.12 * cellZone);
    tile += mix(A, S, 0.5) * 0.05 * (1.0 - uv.y);
    tile += float3(1.0) * bevel * lightSide * 0.08;
    tile *= 0.9 + 0.2 * vnoise(id * 0.7 + t * 0.05);
    // A pulse rolling across the lattice from the bottom-right corner.
    float wave = fract(t * 0.05);
    float rd = length(cc1);
    float pulse = exp(-sqf((rd - wave * 1.6) / 0.08)) * (1.0 - wave) + exp(-sqf((length(cc2) - fract(t * 0.05 + 0.5) * 1.2) / 0.07)) * (1.0 - fract(t * 0.05 + 0.5));
    // Tiles glowing on their own, fading in and out.
    float own = hash12(id + 7.0);
    float glowOwn = step(0.78, own) * sqf(sat(sin(t * (0.2 + 0.3 * hash12(id + 3.0)) + own * 20.0)));
    float lit = max(pulse, glowOwn) * present;
    float3 lc = mix(A, S, hash12(id + 1.0) * 0.6);
    tile += lc * lit * (0.35 + 0.45 * smoothstep(0.44, 0.0, d));
    // Edge line glows faintly.
    float edgeLine = exp(-abs(d - 0.46) * 90.0);
    tile += mix(A, S, 0.3) * edgeLine * (0.22 + 0.25 * cellZone + lit * 0.7);
    // Inner ring detail on lit tiles.
    tile += lc * exp(-abs(d - 0.22) * 120.0) * lit * 0.25;
    col = mix(col, tile, plate * present * sat(cellZone * 1.4));
    // Gaps between tiles stay dark; a soft halo round lit ones.
    col += lc * lit * exp(-d * 4.0) * 0.06 * present;

    // A thin sweep of light crossing slowly on a diagonal.
    float sweep = uv.x * 0.6 + uv.y - fract(t * 0.03) * (asp * 0.6 + 1.6) + 0.3;
    col += mix(A, float3(1.0), 0.5) * exp(-abs(sweep) * 120.0) * zone * 0.12;

    return half4(finish(col, fc), 1.0);
}
"""

    private const val CHILL_CLOUDS = """
// Above the clouds: Toni's painting of a sunrise over a sea of clouds (res scene_chill_clouds), brought to
// life. The cloud sea drifts slowly past (nearer clouds faster), the thin streaks in the sky glide by, the sun
// glows and breathes, and light glints along the cloud tops near it. The peaks stand still.
// (The procedural version is kept as chill_clouds_drawn.agsl.)
// Shared by the painted scenes (the user's own paintings with motion added on top: aurora, meadow,
// px_dojo): the painting fills the screen like a cover (cropped, never stretched) round a chosen point.
uniform shader uPaint;      // the painting (ScenePainting: res/drawable-nodpi/scene_*.webp)
uniform float2 uPaintSize;  // its decoded size in pixels
uniform float uHasPaint;    // 0 while it decodes (a plain gradient in the theme's colours shows)

// The painting's pixel under screen point fc, filling the screen, the crop centred on (fx, fy) (0..1 across it).
float2 paintPx(float2 fc, float fx, float fy) {
    float2 sz = max(uPaintSize, float2(1.0));
    float s = max(uRes.x / sz.x, uRes.y / sz.y);
    float2 off = (sz * s - uRes) * float2(fx, fy);
    return (fc + off) / s;
}

// The painting's colour at pixel p (clamped inside it).
float3 paintAt(float2 p) { return float3(uPaint.eval(clamp(p, float2(0.5), max(uPaintSize, float2(1.0)) - 0.5)).rgb); }

// Brightness, for picking out lit parts of the painting.
float luma(float3 c) { return dot(c, float3(0.299, 0.587, 0.114)); }

// How much pixel p is a small bright speck (a star) rather than part of a bright area: brighter than the
// painting a few pixels away on both sides. lum is its own brightness.
float speckAt(float2 p, float lum) {
    float k = max(uPaintSize.y, 1.0) / 941.0 * 4.0;
    float n = (luma(paintAt(p + float2(k, k * 0.5))) + luma(paintAt(p - float2(k * 0.5, k)))) * 0.5;
    return smoothstep(0.06, 0.2, lum - n);
}

// The painted chill scenes' finish: the painting's own colours and framing (no vignette, no highlight
// roll-off), only the fine noise that keeps dark gradients from banding.
float3 finishPaint(float3 col, float2 fc) {
    col = clamp(col, 0.0, 1.0);
    return col + (hash12(fc) - 0.5) / 255.0;
}

// The painting drifting sideways by up to `dist` reference pixels, endlessly: two copies offset by half a
// cycle, cross-faded so neither ever jumps (a flow-map drift).
float3 driftAt(float2 p, float2 sz, float dist, float t, float speed) {
    float ph = fract(t * speed);
    float ph2 = fract(t * speed + 0.5);
    float2 k = float2(1.0 / 1672.0, 0.0) * sz.x;
    // Never reach past the painting's left edge (it would smear): drift less right at the edge.
    dist = min(dist, p.x / k.x);
    float3 a = paintAt(p - float2(ph * dist, 0.0) * k);
    float3 b = paintAt(p - float2(ph2 * dist, 0.0) * k);
    float wa = 1.0 - abs(ph * 2.0 - 1.0);
    return mix(b, a, wa);
}

half4 main(float2 fc) {
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 BG = uBg.rgb;
    if (uHasPaint < 0.5) {
        float2 uv = fc / uRes;
        return half4(finish(mix(BG * 1.6, mix(BG, A, 0.5), uv.y), fc), 1.0);
    }
    float2 sz = max(uPaintSize, float2(1.0));
    float2 p = paintPx(fc, 0.5, 0.5);
    float2 q = p / sz;
    float2 r = q * float2(1672.0, 941.0);
    float aspP = sz.x / sz.y;

    float2 sunC = float2(1435.0, 493.0);
    float sd = length(r - sunC);
    // Where things drift: the cloud sea (below the horizon, not the peaks) and the sky streaks (not the sun).
    float peaks = smoothstep(600.0, 540.0, r.x) * smoothstep(605.0, 585.0, r.y);
    float sea = smoothstep(552.0, 575.0, r.y) * (1.0 - peaks);
    float sky = smoothstep(530.0, 500.0, r.y) * smoothstep(55.0, 110.0, sd) * (1.0 - step(r.x, 560.0) * step(400.0, r.y));
    float3 col = paintAt(p);
    if (sea > 0.0) {
        float near = sat((r.y - 550.0) / 390.0);
        float3 d = driftAt(p, sz, 30.0 + 60.0 * near, t, 0.02);
        col = mix(col, d, sea);
    } else if (sky > 0.0) {
        float3 d = driftAt(p, sz, 40.0, t, 0.008);
        col = mix(col, d, sky);
    }
    float lum = luma(col);

    // The sun breathes; its glow and a soft horizontal flare.
    float breathe = 0.5 + 0.5 * sin(t * 0.35);
    col += float3(1.0, 0.85, 0.6) * exp(-sd * 0.012) * (0.04 + 0.04 * breathe);
    col += float3(1.0, 0.85, 0.6) * exp(-abs(r.y - sunC.y) * 0.08) * exp(-abs(r.x - sunC.x) * 0.004) * 0.04 * breathe;

    // Light glinting along the cloud tops near the sun.
    float tops = smoothstep(0.6, 0.85, lum) * sea * exp(-abs(r.x - sunC.x) * 0.0025);
    float gl = smoothstep(0.75, 0.95, vnoise(float2(r.x * 0.03 - t * 0.3, r.y * 0.05)));
    col += float3(1.0, 0.92, 0.75) * tops * gl * 0.12;

    return half4(finishPaint(col, fc), 1.0);
}
"""

    private const val CHILL_KOI = """
// Koi pond: Toni's painting of koi among lily pads (res scene_chill_koi), brought to life. The koi swim in
// place — gliding a little forward and back, bodies rippling, tails swishing — the water shimmers over them
// with moving caustic light, and rings spread now and then where one touches the surface. The lily pads
// float still. (The procedural version is kept as chill_koi_drawn.agsl.)
// Shared by the painted scenes (the user's own paintings with motion added on top: aurora, meadow,
// px_dojo): the painting fills the screen like a cover (cropped, never stretched) round a chosen point.
uniform shader uPaint;      // the painting (ScenePainting: res/drawable-nodpi/scene_*.webp)
uniform float2 uPaintSize;  // its decoded size in pixels
uniform float uHasPaint;    // 0 while it decodes (a plain gradient in the theme's colours shows)

// The painting's pixel under screen point fc, filling the screen, the crop centred on (fx, fy) (0..1 across it).
float2 paintPx(float2 fc, float fx, float fy) {
    float2 sz = max(uPaintSize, float2(1.0));
    float s = max(uRes.x / sz.x, uRes.y / sz.y);
    float2 off = (sz * s - uRes) * float2(fx, fy);
    return (fc + off) / s;
}

// The painting's colour at pixel p (clamped inside it).
float3 paintAt(float2 p) { return float3(uPaint.eval(clamp(p, float2(0.5), max(uPaintSize, float2(1.0)) - 0.5)).rgb); }

// Brightness, for picking out lit parts of the painting.
float luma(float3 c) { return dot(c, float3(0.299, 0.587, 0.114)); }

// How much pixel p is a small bright speck (a star) rather than part of a bright area: brighter than the
// painting a few pixels away on both sides. lum is its own brightness.
float speckAt(float2 p, float lum) {
    float k = max(uPaintSize.y, 1.0) / 941.0 * 4.0;
    float n = (luma(paintAt(p + float2(k, k * 0.5))) + luma(paintAt(p - float2(k * 0.5, k)))) * 0.5;
    return smoothstep(0.06, 0.2, lum - n);
}

// The painted chill scenes' finish: the painting's own colours and framing (no vignette, no highlight
// roll-off), only the fine noise that keeps dark gradients from banding.
float3 finishPaint(float3 col, float2 fc) {
    col = clamp(col, 0.0, 1.0);
    return col + (hash12(fc) - 0.5) / 255.0;
}

// How far the painting moves at reference point r for one koi (head h, tail tip e, half-width hw), at phase ph.
float2 koiMove(float2 r, float2 h, float2 e, float hw, float ph, float t) {
    float2 axis = e - h;
    float L = length(axis);
    float2 d = axis / L;
    float2 n = float2(-d.y, d.x);
    float u = dot(r - h, d) / L;          // 0 at the head, 1 at the tail tip
    float v = dot(r - h, n);
    float w = exp(-sqf(v / (hw * 1.9))) * smoothstep(-0.35, 0.0, u) * smoothstep(1.35, 1.0, u);
    float glide = 4.0 * sin(t * 0.55 + ph);
    float wag = 7.0 * sqf(sat((u - 0.4) / 0.6)) * sin(t * 2.6 + ph * 2.0);
    float ripple = 1.6 * sin(u * 7.0 - t * 2.6 + ph) * sat(u * 2.0);
    return (d * glide + n * (wag + ripple)) * w;
}

half4 main(float2 fc) {
    float t = uTime;
    float3 BG = uBg.rgb;
    if (uHasPaint < 0.5) {
        float2 uv = fc / uRes;
        return half4(finish(mix(BG * 2.0, BG * 1.2, uv.y), fc), 1.0);
    }
    float2 sz = max(uPaintSize, float2(1.0));
    float2 p = paintPx(fc, 0.5, 0.5);
    float2 q = p / sz;
    float2 r = q * float2(1672.0, 941.0);
    float aspP = sz.x / sz.y;

    // The lily pads (green, lit) stay put; everything else is under rippling water.
    float3 here = paintAt(p);
    float pad = sat((here.g - max(here.r * 1.25, here.b * 1.1)) * 6.0) * smoothstep(0.15, 0.3, luma(here));
    float flower = smoothstep(0.7, 0.85, luma(here)) * step(here.b, here.g + 0.1);
    float still = sat(pad + flower);

    float2 move = koiMove(r, float2(1450.0, 177.0), float2(1650.0, 270.0), 32.0, 0.0, t)
                + koiMove(r, float2(205.0, 780.0), float2(355.0, 925.0), 32.0, 2.1, t)
                + koiMove(r, float2(1600.0, 680.0), float2(1555.0, 790.0), 22.0, 4.2, t) * 0.6
                + koiMove(r, float2(8.0, 222.0), float2(110.0, 262.0), 26.0, 5.3, t) * 0.5;
    // Water shimmer.
    float2 wv = float2(sin(r.y * 0.045 + t * 0.9) + sin(r.x * 0.02 - t * 0.6), cos(r.x * 0.04 - t * 0.8) + sin(r.y * 0.025 + t * 0.5)) * 0.9;
    float2 off = (move + wv) * (1.0 - still);
    float3 col = paintAt(p - off / float2(1672.0, 941.0) * sz);

    // Moving caustic light over the water (not on the pads).
    float2 cp = r * 0.009;
    float c1 = abs(sin(cp.x + sin(cp.y * 1.3 + t * 0.35) * 1.2 + t * 0.2));
    float c2 = abs(sin(cp.y * 1.1 + sin(cp.x * 0.9 - t * 0.3) * 1.3 - t * 0.15));
    float caus = pow(sat(1.0 - min(c1, c2)), 7.0);
    col += float3(0.7, 0.95, 0.85) * caus * 0.07 * (1.0 - still);

    // Rings spreading where a koi touches the surface (near the fish, now and then).
    for (int i = 0; i < 3; i++) {
        float fi = float(i);
        float cyc = t * 0.09 + fi * 0.37;
        float ph = fract(cyc);
        float n = floor(cyc);
        float2 c = i == 0 ? float2(1460.0, 175.0) : i == 1 ? float2(210.0, 780.0) : float2(600.0 + 500.0 * hash11(n * 3.1), 150.0 + 600.0 * hash11(n * 7.3));
        float rr = ph * 140.0;
        float d = length(r - c);
        float ring = exp(-abs(d - rr) * 0.35) + exp(-abs(d - rr * 0.6) * 0.45) * 0.6;
        col += float3(0.75, 0.95, 0.9) * ring * (1.0 - ph) * (1.0 - ph) * 0.1 * (1.0 - still);
    }

    return half4(finishPaint(col, fc), 1.0);
}
"""

    private const val CHILL_PEAKS = """
// Winter peaks: Toni's painting of a snowy night in the mountains (res scene_chill_peaks), brought to life.
// Snow falls gently, the cabin's smoke drifts and curls upward, its windows flicker like a fire inside and
// the glow on the snow breathes with them, the stars twinkle and the lights down in the valley shimmer.
// (The procedural version is kept as chill_peaks_drawn.agsl.)
// Shared by the painted scenes (the user's own paintings with motion added on top: aurora, meadow,
// px_dojo): the painting fills the screen like a cover (cropped, never stretched) round a chosen point.
uniform shader uPaint;      // the painting (ScenePainting: res/drawable-nodpi/scene_*.webp)
uniform float2 uPaintSize;  // its decoded size in pixels
uniform float uHasPaint;    // 0 while it decodes (a plain gradient in the theme's colours shows)

// The painting's pixel under screen point fc, filling the screen, the crop centred on (fx, fy) (0..1 across it).
float2 paintPx(float2 fc, float fx, float fy) {
    float2 sz = max(uPaintSize, float2(1.0));
    float s = max(uRes.x / sz.x, uRes.y / sz.y);
    float2 off = (sz * s - uRes) * float2(fx, fy);
    return (fc + off) / s;
}

// The painting's colour at pixel p (clamped inside it).
float3 paintAt(float2 p) { return float3(uPaint.eval(clamp(p, float2(0.5), max(uPaintSize, float2(1.0)) - 0.5)).rgb); }

// Brightness, for picking out lit parts of the painting.
float luma(float3 c) { return dot(c, float3(0.299, 0.587, 0.114)); }

// How much pixel p is a small bright speck (a star) rather than part of a bright area: brighter than the
// painting a few pixels away on both sides. lum is its own brightness.
float speckAt(float2 p, float lum) {
    float k = max(uPaintSize.y, 1.0) / 941.0 * 4.0;
    float n = (luma(paintAt(p + float2(k, k * 0.5))) + luma(paintAt(p - float2(k * 0.5, k)))) * 0.5;
    return smoothstep(0.06, 0.2, lum - n);
}

// The painted chill scenes' finish: the painting's own colours and framing (no vignette, no highlight
// roll-off), only the fine noise that keeps dark gradients from banding.
float3 finishPaint(float3 col, float2 fc) {
    col = clamp(col, 0.0, 1.0);
    return col + (hash12(fc) - 0.5) / 255.0;
}

// Centre of the painted smoke column at painting row y (it leans right as it rises from the chimney).
float smokeX(float y) { return 1432.0 + 75.0 * pow(sat((605.0 - y) / 400.0), 0.7); }

half4 main(float2 fc) {
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 BG = uBg.rgb;
    if (uHasPaint < 0.5) {
        float2 uv = fc / uRes;
        return half4(finish(mix(BG * 0.8, mix(BG, A, 0.3), uv.y), fc), 1.0);
    }
    float2 sz = max(uPaintSize, float2(1.0));
    float2 p = paintPx(fc, 0.5, 0.5);
    float2 q = p / sz;
    float2 r = q * float2(1672.0, 941.0);          // painting reference pixels

    // The smoke: the painted column sways and flows upward.
    float rise = sat((605.0 - r.y) / 420.0);
    float band = exp(-sqf((r.x - smokeX(r.y)) / (14.0 + 40.0 * rise))) * smoothstep(600.0, 570.0, r.y) * step(160.0, r.y);
    float flow = sin(r.y * 0.045 + t * 1.1) * 0.6 + sin(r.y * 0.11 - t * 0.7 + 1.3) * 0.4;
    float2 warp = float2(flow * (2.0 + 9.0 * rise) * band, 0.0);
    float3 col = paintAt(p + warp / float2(1672.0, 941.0) * sz);
    float lum = luma(col);
    // A soft puff drifting up through it.
    float puff = fbm3(float2((r.x - smokeX(r.y)) * 0.025, r.y * 0.012 + t * 0.35));
    col += float3(0.6, 0.65, 0.78) * band * smoothstep(0.45, 0.8, puff) * 0.12 * (1.0 - rise * 0.6);

    // The windows: warm, bright pixels round the cabin flicker like a fire inside.
    float warm = sat((col.r - col.b) * 2.5) * smoothstep(0.35, 0.7, lum);
    float cabin = step(1300.0, r.x) * step(r.x, 1500.0) * step(660.0, r.y) * step(r.y, 735.0);
    float fire = 0.9 + 0.07 * sin(t * 5.3) * sin(t * 2.1 + 1.0) + 0.05 * sin(t * 11.0);
    col *= 1.0 + warm * cabin * (fire - 0.95) * 1.6;
    // Their glow on the snow below breathes with them.
    float2 g = (r - float2(1395.0, 745.0)) / float2(240.0, 70.0);
    col += float3(1.0, 0.7, 0.35) * exp(-dot(g, g) * 1.5) * (fire - 0.9) * 0.35;

    // Stars twinkle (bright specks in the sky), the valley lights shimmer.
    float sky = step(r.y, 470.0);
    float speck = speckAt(p, lum) * sky * (1.0 - band);
    float2 cell = floor(r / 3.0);
    float tw = 0.5 + 0.5 * sin(t * (1.3 + 2.2 * hash12(cell)) + hash12(cell + 7.0) * 40.0);
    col *= 1.0 + speck * (tw - 0.5) * 0.9;
    float valley = exp(-sqf((r.x - 800.0) / 60.0) - sqf((r.y - 737.0) / 8.0));
    col += float3(1.0, 0.8, 0.45) * valley * smoothstep(0.3, 0.6, lum) * (0.5 + 0.5 * sin(t * 3.0 + r.x * 0.7)) * 0.2;

    // Snow falling: small far flakes, bigger soft near ones, drifting with a little wind.
    float2 sv = q * float2(sz.x / sz.y, 1.0);
    sv.x += 0.015 * sin(t * 0.3 + sv.y * 4.0);
    float flakes = dots(sv, 60.0, float2(t * 0.012, -t * 0.06), 0.16, 0.08, 3.0) * 0.45
                 + dots(sv, 28.0, float2(t * 0.02, -t * 0.1), 0.08, 0.1, 7.0) * 0.55
                 + dots(sv, 11.0, float2(t * 0.03, -t * 0.17), 0.05, 0.16, 11.0) * 0.35;
    col += float3(0.92, 0.95, 1.0) * flakes * 0.55;
    // Snow sparkling on the slope in the cabin's light.
    float slope = step(740.0, r.y);
    col += float3(1.0, 0.9, 0.75) * dots(sv, 190.0, float2(0.0), 0.06, 0.08, 13.0) * slope * smoothstep(0.45, 0.8, lum) * 0.6;

    return half4(finishPaint(col, fc), 1.0);
}
"""

    private const val HANDHELD_BOOT = """
// Handheld boot: an original pocket console standing front-on, booting up over and over. The power
// light comes on, a bolt capsule logo drops down the four-shade LCD, a shine sweeps across it with a
// ripple, then it fades into a menu of icons where a cursor hops from one to the next before the screen
// goes dark again (a 12 s loop). Soft bokeh drifts behind; the device bobs gently on its shadow.

// The LCD's picture at pixel q (0..80 across, 0..64 down) at loop time T: a shade 0 (dark) .. 3 (light).
float lcdShade(float2 q, float T) {
    float on = step(0.6, T) * (1.0 - step(11.4, T));
    if (on < 0.5) return -1.0;                       // screen off
    float shade = 3.0;                                // the light background
    // The logo: a capsule 30 x 14 pixels with a bolt, sliding down, then fading.
    float ly = floor(mix(-16.0, 20.0, smoothstep(0.6, 2.6, T)));
    float2 lp = q - float2(40.0, ly + 7.0);
    float fade = 1.0 - smoothstep(4.6, 5.2, T);
    if (fade > 0.0) {
        float2 b = abs(lp) - float2(15.0, 7.0);
        float capD = length(max(b + float2(6.0, 0.0), 0.0)) - 7.0;
        if (abs(lp.y) <= 7.0 && abs(lp.x) <= 15.0 && capD < 0.0) {
            shade = capD > -1.5 ? 0.0 : 2.0;
            // The bolt: two slanted bars.
            float2 bq = lp;
            float bolt = step(abs(bq.x + bq.y * 0.6 + 1.0), 1.6) * step(-5.0, bq.y) * step(bq.y, 0.5)
                       + step(abs(bq.x + bq.y * 0.6 - 1.0), 1.6) * step(-0.5, bq.y) * step(bq.y, 5.0)
                       + step(abs(bq.y), 0.6) * step(abs(bq.x), 3.0);
            if (bolt > 0.5) shade = 0.0;
            // The shine sweeping across.
            float sh = (T - 2.9) * 70.0 - 20.0;
            if (abs(lp.x + lp.y * 0.5 - sh) < 2.5 && T > 2.9 && T < 3.6) shade = 3.0;
        }
        // Ripples round the logo just after the shine.
        float rr = length(lp * float2(0.6, 1.0));
        float rt = (T - 3.0) * 30.0;
        if (T > 3.0 && T < 4.0 && abs(rr - rt) < 0.8) shade = min(shade, 1.0);
        shade = mix(3.0, shade, step(0.5, fade * 3.0 - floor(fade * 3.0) * 0.0) * step(0.34, fade));
        if (fade < 0.67 && shade < 3.0) shade = min(3.0, shade + 1.0);
    }
    // The menu: six icons in a 3 x 2 grid sliding in, a cursor hopping between them.
    float mIn = smoothstep(5.2, 6.0, T) * (1.0 - smoothstep(10.8, 11.3, T));
    if (mIn > 0.0) {
        float slide = floor((1.0 - mIn) * 80.0);
        float2 mq = q - float2(slide, 0.0);
        // Title bar.
        if (mq.y < 9.0 && mq.x > 2.0 && mq.x < 78.0) shade = mq.y < 1.0 || mq.y > 8.0 ? 3.0 : 1.0;
        float2 cellG = floor((mq - float2(4.0, 14.0)) / float2(25.0, 24.0));
        float2 inC = mq - float2(4.0, 14.0) - cellG * float2(25.0, 24.0);
        if (cellG.x >= 0.0 && cellG.x < 3.0 && cellG.y >= 0.0 && cellG.y < 2.0) {
            float id = cellG.y * 3.0 + cellG.x;
            float2 ic = inC - float2(11.0, 10.0);
            float icon = 0.0;
            if (id < 0.5) icon = step(abs(ic.x), 6.0) * step(abs(ic.y), 7.0) * (1.0 - step(abs(ic.x), 4.0) * step(abs(ic.y + 2.0), 3.0));    // cartridge
            else if (id < 1.5) icon = step(length(ic), 7.5) * step(1.8, length(ic));                                                   // disc
            else if (id < 2.5) icon = step(abs(ic.x) + abs(ic.y) * 0.6, 6.0) + step(abs(ic.y) + abs(ic.x) * 0.6, 6.0) * 0.0;           // star-ish
            else if (id < 3.5) icon = step(length(ic - float2(-2.0, 4.0)), 3.0) + step(abs(ic.x - 0.5), 1.0) * step(-7.0, ic.y) * step(ic.y, 4.0) + step(abs(ic.y + 6.5), 1.0) * step(0.0, ic.x) * step(ic.x, 5.0); // note
            else if (id < 4.5) icon = step(length(ic), 6.5 + step(0.5, fract(atan(ic.y, ic.x) / TAU * 8.0)) * 1.5) * step(2.5, length(ic)); // gear
            else icon = step(length(ic - float2(-2.6, -2.0)), 3.5) + step(length(ic - float2(2.6, -2.0)), 3.5) + step(ic.y, 6.0 - abs(ic.x) * 1.1) * step(-2.0, ic.y); // heart
            if (icon > 0.5) shade = 0.0;
            // The cursor: a frame round the current icon.
            float cur = mod(floor((T - 6.0) / 1.0), 6.0);
            if (T > 6.0 && abs(id - cur) < 0.5) {
                float2 f = abs(inC - float2(11.0, 10.0)) - float2(11.0, 10.5);
                if (max(f.x, f.y) > -1.5 && max(f.x, f.y) < 0.0) shade = 0.0;
                if (icon > 0.5) shade = 1.0;
            }
        }
    }
    return shade;
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float T = mod(t, 12.0);

    // Backdrop: the theme's colours in a soft pool of light, bokeh drifting.
    float3 col = mix(BG, mix(BG, S, 0.25), exp(-length(uv - float2(asp * 0.5, 0.45)) * 2.0));
    for (int i = 0; i < 9; i++) {
        float fi = float(i);
        float2 p = float2(fract(hash11(fi) + t * 0.006 * (1.0 + hash11(fi * 3.0))) * asp, hash11(fi * 5.0) * 0.9 + 0.05);
        float r = 0.04 + 0.06 * hash11(fi * 7.0);
        float d = length(uv - p);
        col += mix(A, S, hash11(fi * 2.0)) * 0.08 * (1.0 - smoothstep(r * 0.85, r, d));
    }

    float bob = 0.008 * sin(t * 0.8);
    float2 c = float2(asp * 0.5, 0.5 + bob);
    float R = 0.43;
    float2 p = (uv - c) / R;
    float px = 1.5 / uRes.y / R;
    // Shadow on the floor below.
    float sh = length((uv - float2(asp * 0.5, 0.95)) * float2(1.0, 6.0));
    col *= 1.0 - 0.45 * (1.0 - smoothstep(0.1, 0.35 + bob, sh));

    // Body: Voltcap's own capsule shape stood on end - a tall pill, two-tone (light top, theme-coloured
    // lower shell) with a seam across the middle.
    float2 hb = float2(0.62, 1.0);
    float body = sdRoundBox(p, hb, 0.55);
    float3 shell = mix(float3(0.86, 0.85, 0.83), S, 0.12);
    float3 lower = mix(shell, A, 0.45) * 0.92;
    if (body < 0.0) {
        col = p.y < 0.12 ? shell : lower;
        col *= 0.92 + 0.1 * (-p.y * 0.5 + 0.5) * 0.4;
        // Rim light round the top-left, shade bottom-right.
        float edge = smoothstep(-0.06, 0.0, body);
        col = mix(col, col * (p.x + p.y > 0.0 ? 0.68 : 1.12), edge);
        col = mix(col, col * 0.75, (1.0 - smoothstep(0.0, px * 1.5, abs(p.y - 0.12))) * 0.8);
    }
    col = mix(col, shell * 0.45, (1.0 - smoothstep(0.0, px, abs(body))) * 0.6);

    // The screen's bezel (rounded, dark glass) and the power light above it.
    float2 bc = float2(0.0, -0.42);
    float bez = sdRoundBox(p - bc, float2(0.46, 0.38), 0.12);
    col = mix(col, mix(float3(0.16, 0.16, 0.2), BG, 0.3), 1.0 - smoothstep(0.0, px, bez));
    col += 0.06 * (1.0 - smoothstep(0.0, px, bez)) * smoothstep(-0.3, -0.36, p.y - bc.y);
    float on = step(0.6, T) * (1.0 - step(11.4, T));
    float led = length(p - float2(0.0, -0.88)) - 0.022;
    col = mix(col, mix(float3(0.15, 0.2, 0.15), mix(float3(0.4, 1.0, 0.5), A, 0.4), on), 1.0 - smoothstep(0.0, px, led));
    col += mix(float3(0.4, 1.0, 0.5), A, 0.4) * on * 0.25 * exp(-max(led, 0.0) * 30.0);

    // The LCD.
    float2 lc = float2(0.0, -0.42);
    float2 lh = float2(0.36, 0.29);
    float2 lq = (p - lc + lh) / (2.0 * lh);            // 0..1 across the LCD
    if (lq.x > 0.0 && lq.x < 1.0 && lq.y > 0.0 && lq.y < 1.0) {
        float2 pixq = lq * float2(64.0, 51.2);
        float s = lcdShade(floor(pixq) * 1.25, T);
        float3 c0 = mix(float3(0.06, 0.12, 0.09), A * 0.3, 0.35);
        float3 c1 = mix(float3(0.2, 0.32, 0.18), A * 0.6, 0.35);
        float3 c2 = mix(float3(0.45, 0.58, 0.3), A, 0.3);
        float3 c3 = mix(float3(0.66, 0.76, 0.42), mix(A, float3(1.0), 0.5), 0.3);
        float3 off = mix(float3(0.38, 0.45, 0.3), c2, 0.2) * 0.75;
        float3 lcd = s < -0.5 ? off : (s < 0.5 ? c0 : (s < 1.5 ? c1 : (s < 2.5 ? c2 : c3)));
        // Pixel gaps and a soft shadow under the bezel's top edge.
        float2 g = abs(fract(pixq) - 0.5);
        lcd *= 0.9 + 0.1 * step(max(g.x, g.y), 0.4);
        lcd *= 0.85 + 0.15 * smoothstep(0.0, 0.08, lq.y);
        col = lcd;
    }

    // The home button: a round key with the bolt, between the controls.
    float2 hp = p - float2(0.0, 0.3);
    col = mix(col, lower * 0.6, 1.0 - smoothstep(0.0, px, length(hp) - 0.075));
    col = mix(col, shell, 1.0 - smoothstep(0.0, px, length(hp) - 0.06));
    float emblem = step(abs(hp.x + hp.y * 0.6 + 0.01), 0.012) * step(-0.038, hp.y) * step(hp.y, 0.004) + step(abs(hp.x + hp.y * 0.6 - 0.01), 0.012) * step(-0.004, hp.y) * step(hp.y, 0.038);
    col = mix(col, mix(A, float3(0.2), 0.35), sat(emblem));
    // D-pad on the left.
    float2 dp = p - float2(-0.33, 0.36);
    float dcross = min(sdRoundBox(dp, float2(0.15, 0.05), 0.02), sdRoundBox(dp, float2(0.05, 0.15), 0.02));
    col = mix(col, lower * 0.55, (1.0 - smoothstep(0.0, px, dcross - 0.02)) * 0.6);
    col = mix(col, float3(0.15, 0.15, 0.18), 1.0 - smoothstep(0.0, px, dcross));
    col = mix(col, float3(0.24, 0.24, 0.28), 1.0 - smoothstep(0.0, px, length(dp) - 0.025));
    // One big action key and a small one on the right; the big one presses as the cursor hops.
    float hop = step(6.0, T) * step(fract(T - 6.0), 0.15) * step(T, 11.0);
    for (int i = 0; i < 2; i++) {
        float fi = float(i);
        float2 bp = p - (fi < 0.5 ? float2(0.33, 0.34) : float2(0.24, 0.5));
        float r = fi < 0.5 ? 0.1 : 0.055;
        float pressed = fi < 0.5 ? hop : 0.0;
        col = mix(col, lower * 0.55, (1.0 - smoothstep(0.0, px, length(bp) - r - 0.02)) * 0.6);
        col = mix(col, mix(float3(0.95, 0.95, 0.92), S, 0.3) * (1.0 - 0.3 * pressed), 1.0 - smoothstep(0.0, px, length(bp) - r * (1.0 - 0.06 * pressed)));
        col += 0.12 * (1.0 - smoothstep(0.0, px, length(bp + float2(r * 0.35, r * 0.35)) - r * 0.3)) * (1.0 - pressed);
    }
    // The speaker: a ring of holes at the bottom.
    float2 spq = p - float2(0.0, 0.72);
    float sr = length(spq);
    float sa = atan(spq.y, spq.x);
    float hole = (1.0 - smoothstep(0.0, px, length(float2(fract(sa / TAU * 10.0) - 0.5, (sr - 0.09) * 6.0)) * 0.11 - 0.014)) * step(abs(sr - 0.09), 0.03);
    hole = max(hole, 1.0 - smoothstep(0.0, px, sr - 0.02));
    col = mix(col, lower * 0.4, hole);
    return half4(finish(col, fc), 1.0);
}
"""

    private const val POCKET_BEAT = """
// Pocket beat (music): a wide, original pocket console held landscape - D-pad on the left, A and B on
// the right - with the album cover on its screen and a pixel equalizer along the bottom of it. The
// D-pad presses a new direction on every beat, A and B take turns, the shoulder keys tap on the kick
// and the whole console nudges with the bass. Pixel notes float up from it over the song's colours.
// Shared by the music-reactive scenes (besides "Now playing", which has its own copy): the same
// uniforms NowPlayingScene feeds the music scene - cover, levels, kicks, eight equalizer bands and
// where on screen the visualizer goes - plus the soft cover background.
uniform shader uArt;      // the cover, square and blurred smooth (MusicTheme.softArt)
uniform float2 uArtSize;  // its size in pixels
uniform float uHasArt;    // 0 = no cover yet (or the cover is switched off)
uniform float uBass;      // 0..1, smoothed
uniform float uMid;
uniform float uHigh;
uniform float uBeatAge;   // seconds since the last kick (large = none)
uniform float uPlaying;   // 0..1, fades when paused
uniform float uIntensity; // 0..1, Settings > strength
uniform float4 uEqA;      // bands 0-3 (low), 0..1
uniform float4 uEqB;      // bands 4-7 (high)
uniform float uWaveY;     // 0..1 from the top: where the visualizer sits (Appearance > Equalizer)
uniform float uWaveH;     // room above / below that line (share of the height); the player sits under it
uniform float uWaveX;     // 0..1 from the left: where the visualizer sits across (0 = the middle; the player beside it)
uniform shader uCover;    // the cover, sharp (256 px square) - for the record / disc labels
uniform float2 uCoverSize;
uniform shader uLabel;    // the song's title and artist in dark ink on a clear picture (NowPlayingScene.songLabel)
uniform float2 uLabelSize;
uniform shader uHistory;  // covers of the last songs: a 4 x 2 grid (newest first), MusicTheme.historyAtlas
uniform float uHistCount; // how many of the 8 are filled
uniform float3 uSubject;   // where the cover's subject is: x, y (0..1 across the square) and its size; z = 0 until known (MusicTheme.subject)
// Clocks that only run while the music plays, so spins and scrolls slow down and stop smoothly instead of
// jumping (t * (a + b * level) jumps whenever the level moves). Kept by NowPlayingScene, in seconds:
uniform float uPlayT;     // time spent playing (integral of uPlaying)
uniform float uBassT;     // integral of uBass x uPlaying
uniform float uMidT;      // integral of uMid x uPlaying
uniform float uHighT;     // integral of uHigh x uPlaying

// The visualizer's room, with a sensible size when it isn't set (previews).
float room(float fallback) { return uWaveH > 0.001 ? uWaveH : fallback; }
// Across: the middle, or the left part when the player sits beside the visualizer (MusicPlayerLayout.SIDE).
float waveX(float asp) { return uWaveX > 0.001 ? uWaveX * asp : asp * 0.5; }

float2 mirrorUv(float2 q) { return 1.0 - abs(1.0 - mod(q, 2.0)); }

float eqBand(float i) {
    if (i < 0.5) return uEqA.x;
    if (i < 1.5) return uEqA.y;
    if (i < 2.5) return uEqA.z;
    if (i < 3.5) return uEqA.w;
    if (i < 4.5) return uEqB.x;
    if (i < 5.5) return uEqB.y;
    if (i < 6.5) return uEqB.z;
    return uEqB.w;
}

// The spectrum at m (0 = lowest band, 1 = highest), smoothly interpolated.
float eqAt(float m) {
    float f = clamp(m, 0.0, 1.0) * 7.0;
    float i = floor(f);
    float u = f - i;
    u = u * u * (3.0 - 2.0 * u);
    return mix(eqBand(i), eqBand(min(i + 1.0, 7.0)), u);
}

// Pushes a colour's saturation by s (1 = unchanged) around its own brightness.
float3 vivid(float3 c, float s) {
    float l = dot(c, float3(0.299, 0.587, 0.114));
    return max(mix(float3(l), c, s), 0.0);
}

// The cover, very soft and slowly drifting (or, without one, the palette swirling), dimmed by dim.
float3 coverField(float2 uv, float asp, float t, float bass, float dim, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float zoom = 1.7 + 0.08 * sin(t * 0.045) - 0.05 * bass * uIntensity;
    p = rot(0.05 * sin(t * 0.031)) * p / zoom;
    p += (float2(vnoise(p * 2.0 + float2(t * 0.1, 0.0)), vnoise(p * 2.0 + float2(7.3, -t * 0.08))) - 0.5) * 0.1;
    float2 q = p / max(asp, 1.0) + 0.5;
    float3 art = float3(uArt.eval(mirrorUv(q) * uArtSize).rgb);
    float sw = fbm3(uv * 1.4 + float2(t * 0.03, -t * 0.02));
    float3 noArt = mix(BG * 1.4 + A * 0.08, mix(A, S, sw) * 0.5, smoothstep(0.25, 0.8, sw));
    float3 col = mix(noArt, vivid(art, 1.35) * 0.62, uHasArt);
    return mix(col, BG, 0.14) * dim;
}

// The palette as a living gradient: A and S (the cover's colours) flowing round each other with a
// third, hue-shifted colour, brighter on the beat. A colourful base instead of a near-black one.
float3 paletteField(float2 uv, float asp, float t, float lift, float3 BG, float3 A, float3 S) {
    float2 p = uv - float2(asp * 0.5, 0.5);
    float n1 = fbm3(p * 1.3 + float2(t * 0.05, -t * 0.04));
    float n2 = fbm3(p * 1.7 + float2(-t * 0.035, t * 0.05) + 4.7);
    float3 C = float3(S.z, A.x, (A.y + S.y) * 0.5); // a third colour from the two
    float3 col = mix(A, S, smoothstep(0.25, 0.75, n1));
    col = mix(col, C, smoothstep(0.45, 0.85, n2) * 0.55);
    col = mix(BG, col, 0.42 + 0.18 * lift);
    return col;
}

// The sharp cover at q (0..1 across the square), or the palette when there's no cover yet.
float3 sharpCover(float2 q, float3 A, float3 S) {
    float3 art = float3(uCover.eval(clamp(q, 0.0, 1.0) * uCoverSize).rgb);
    return mix(mix(A, S, q.y), art, uHasArt);
}

// Where the cover's subject sits (x, y, size), with a sensible guess before it's known.
float3 subjectOf() { return uSubject.z > 0.001 ? uSubject : float3(0.5, 0.45, 0.3); }

// Ink of the song label at q (0..1 across the writing area): 0 = paper, 1 = ink.
float labelInk(float2 q) {
    if (q.x < 0.0 || q.x > 1.0 || q.y < 0.0 || q.y > 1.0) return 0.0;
    return float(uLabel.eval(q * uLabelSize).a);
}

// Cover of an earlier song: i = 0 the one before this, 1 the one before that... (wraps round the
// ones there are; with none yet, the current cover in the song's colours instead).
float3 pastCover(float i, float2 q, float3 A, float3 S) {
    q = clamp(q, 0.0, 1.0);
    if (uHistCount < 0.5) return mix(sharpCover(q, A, S), mix(A, S, q.y), 0.35);
    float n = mod(floor(i), uHistCount);
    float2 tile = float2(mod(n, 4.0), floor(n / 4.0));
    float2 p = (tile + 0.01 + q * 0.98) * 192.0;
    return float3(uHistory.eval(p).rgb);
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float k = uIntensity;
    float play = uPlaying;
    float bass = uBass * play;
    float kick = exp(-uBeatAge * 7.0) * play;
    float beatN = floor((t - uBeatAge) * 1.866);

    // Backdrop: the song's colours as a soft field, checker tiles drifting.
    float3 col = uHasArt > 0.5 ? coverField(uv, asp, t, bass, 0.75, BG, A, S) : paletteField(uv, asp, t, kick, BG, A, S) * 0.8;
    float2 tg = (uv + float2(t * 0.02, t * 0.01)) * 9.0;
    col *= 0.94 + 0.06 * step(0.5, mod(floor(tg.x) + floor(tg.y), 2.0));

    float2 c = float2(waveX(asp), uWaveY);
    float R = room(0.3) * 1.05;
    float2 p = (uv - c) / R;
    p.y += 0.04 * kick * k;
    p = rot(0.03 * sin(t * 0.5) - 0.025 * bass * k) * p;
    float px = 1.5 / uRes.y / R;

    // Pixel notes floating up from behind the console.
    for (int i = 0; i < 6; i++) {
        float fi = float(i);
        float life = fract(uPlayT * 0.18 + hash11(fi));
        float2 np = float2((hash11(fi * 3.0) - 0.5) * 3.6, 0.6 - life * 2.4);
        float2 q = floor((p - np) * 28.0);
        float note = step(abs(q.x - 1.0), 0.5) * step(-5.0, q.y) * step(q.y, 0.0) + step(length(q - float2(-0.5, 0.5)), 1.6) + step(abs(q.y + 5.0), 0.5) * step(1.0, q.x) * step(q.x, 3.0);
        col = mix(col, mix(A, float3(1.0), 0.5), step(0.5, note) * sat(1.0 - life) * play);
    }

    // Shadow and body: a wide rounded slab with grips.
    float2 hb = float2(1.55, 0.72);
    float body = sdRoundBox(p, hb, 0.5);
    col *= 1.0 - 0.4 * (1.0 - smoothstep(-0.05, 0.25, sdRoundBox(p - float2(0.06, 0.1), hb, 0.5)));
    // Shoulder keys peeking over the top edge, tapping on the kick.
    for (int i = 0; i < 2; i++) {
        float fi = float(i) * 2.0 - 1.0;
        float down = kick * step(0.5, mod(beatN + float(i), 2.0));
        float sk = sdRoundBox(p - float2(fi * 1.05, -0.7 + 0.03 * down), float2(0.32, 0.08), 0.08);
        col = mix(col, mix(float3(0.3, 0.3, 0.35), S, 0.2) * (1.0 - 0.3 * down), 1.0 - smoothstep(0.0, px, sk));
    }
    float3 shell = mix(mix(float3(0.92, 0.9, 0.88), A, 0.35), float3(1.0), 0.1);
    if (body < 0.0) {
        col = shell * (0.9 + 0.12 * (-p.y));
        float edge = smoothstep(-0.07, 0.0, body);
        col = mix(col, col * (p.y > 0.0 ? 0.72 : 1.1), edge);
    }
    col = mix(col, shell * 0.5, (1.0 - smoothstep(0.0, px, abs(body))) * 0.6);

    // The screen with the cover and a pixel equalizer.
    float bez = sdRoundBox(p, float2(0.78, 0.6), 0.08);
    col = mix(col, float3(0.12, 0.12, 0.15), 1.0 - smoothstep(0.0, px, bez));
    float2 sh = float2(0.68, 0.51);
    float2 q = (p + sh) / (2.0 * sh);
    if (q.x > 0.0 && q.x < 1.0 && q.y > 0.0 && q.y < 1.0) {
        // The cover fills the screen's height (square, centred); bars beside it in the song's colours.
        float cx = (q.x - 0.5) * (sh.x / sh.y) + 0.5;
        float3 scr = mix(BG * 0.6, mix(A, S, q.y) * 0.4, 0.6);
        if (cx > 0.0 && cx < 1.0) scr = sharpCover(float2(cx, q.y), A, S);
        // Equalizer strip along the bottom: chunky pixel bars.
        float strip = step(0.7, q.y);
        float bi = floor(q.x * 20.0);
        float e = eqAt(abs(bi / 19.0 - 0.5) * 2.0) * play;
        float lvl = (1.0 - q.y) / 0.3;
        float bar = step(lvl, e * 1.1) * step(0.12, fract(q.x * 20.0)) * step(0.2, fract(q.y * 30.0));
        scr = mix(scr, mix(scr * 0.35, mix(A, S, bi / 19.0) + 0.15, bar), strip * 0.9);
        // A play-bar on top and the screen's pixel grid.
        scr = mix(scr, float3(1.0), step(q.y, 0.025) * step(q.x, fract(uPlayT / 200.0)) * 0.7);
        float2 g = abs(fract(q * float2(160.0, 120.0)) - 0.5);
        scr *= 0.9 + 0.1 * step(max(g.x, g.y), 0.42);
        col = scr;
    }
    // Glass glint.
    col += 0.05 * (1.0 - smoothstep(0.0, px, bez)) * smoothstep(0.1, 0.0, abs(p.x + p.y * 0.8 + 0.3));

    // D-pad on the left: presses a new direction on every beat.
    float2 dp = p - float2(-1.17, 0.0);
    float dir = mod(beatN, 4.0);
    float2 pv = dir < 1.0 ? float2(0.0, -1.0) : (dir < 2.0 ? float2(1.0, 0.0) : (dir < 3.0 ? float2(0.0, 1.0) : float2(-1.0, 0.0)));
    float dcross = min(sdRoundBox(dp, float2(0.21, 0.07), 0.025), sdRoundBox(dp, float2(0.07, 0.21), 0.025));
    col = mix(col, shell * 0.55, (1.0 - smoothstep(0.0, px, dcross - 0.025)) * 0.6);
    float dShade = 1.0 - 0.45 * kick * step(0.08, dot(dp, pv));
    col = mix(col, float3(0.16, 0.16, 0.2) * dShade, 1.0 - smoothstep(0.0, px, dcross));
    col += 0.05 * (1.0 - smoothstep(0.0, px, dcross)) * step(dot(dp, float2(0.7, 0.7)), -0.05);
    // A and B on the right, diagonal; they take turns on the beat.
    for (int i = 0; i < 2; i++) {
        float fi = float(i);
        float2 bp = p - float2(1.08 + fi * 0.2, 0.08 - fi * 0.16);
        float pressed = kick * step(0.5, abs(mod(beatN, 2.0) - fi));
        float r = 0.1 * (1.0 - 0.07 * pressed);
        col = mix(col, shell * 0.55, (1.0 - smoothstep(0.0, px, length(bp) - 0.125)) * 0.6);
        col = mix(col, (i == 0 ? A : S) * (0.9 - 0.35 * pressed), 1.0 - smoothstep(0.0, px, length(bp) - r));
        col += 0.22 * (1.0 - smoothstep(0.0, px, length(bp + float2(0.03, 0.035)) - 0.028)) * (1.0 - pressed);
        col += (i == 0 ? A : S) * 0.5 * pressed * exp(-max(length(bp) - r, 0.0) * 25.0) * step(r, length(bp));
    }
    // Start / select and the speaker holes that pulse with the bass.
    for (int i = 0; i < 2; i++) {
        float fi = float(i);
        col = mix(col, float3(0.35, 0.35, 0.4), 1.0 - smoothstep(0.0, px, sdRoundBox(p - float2(-1.27 + fi * 0.2, 0.42), float2(0.06, 0.02), 0.02)));
    }
    float2 spq = p - float2(1.22, 0.45);
    float2 sg = fract(spq * 14.0) - 0.5;
    float hole = step(length(sg), 0.16 + 0.1 * bass * k) * step(abs(spq.x), 0.13) * step(abs(spq.y), 0.08);
    col = mix(col, shell * 0.35, hole * step(body, 0.0));
    return half4(finish(col, fc), 1.0);
}
"""

    private const val CONSOLE_DISC = """
// Console disc: an original round disc console - a low puck seen from above at an angle, its clear
// dome lid swung up at the back. The disc spins in the bay with its printed label turning and a rainbow
// sheen sliding round the rim, the laser glows red as it tracks in and out underneath, a light ring
// round the bay breathes in the theme's colours, and the puck is mirrored in the glossy floor.
// With a game picked, the disc in the bay is that game's real disc (ScreenScraper's picture of it), or
// its cover printed on the disc when there's no picture; a cartridge game's cartridge stands in the bay
// instead, swaying slowly in a beam of light.

uniform shader uMedia;      // the game's disc / cartridge picture, or its cover (SceneArt)
uniform float2 uMediaSize;
uniform float uHasMedia;    // 0 = the console's own drawn disc
uniform float uMediaKind;   // 0 = a disc picture, 1 = a cartridge / card picture, 2 = only the cover (printed on the disc)
uniform float uFocusY;      // 0.5 + how far to move the console down (share of the height; 0 = not set)

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float px = 1.5 / uRes.y;
    float breathe = 0.5 + 0.5 * sin(t * 1.3);

    // Floor: dark gloss under a soft overhead light.
    float3 col = mix(BG * 0.65, mix(BG, S, 0.2) * 1.5, exp(-length((uv - float2(asp * 0.5, 0.5)) * float2(0.55, 1.2)) * 2.2));

    float2 c = float2(asp * 0.5, 0.6 + (uFocusY > 0.001 ? clamp(uFocusY - 0.5, -0.15, 0.25) : 0.0));
    float cart = step(0.5, uHasMedia) * step(0.5, uMediaKind) * step(uMediaKind, 1.5);
    float2 p = uv - c;
    float sq = 0.42;                                   // the top is seen at an angle: squashed
    float R = 0.46;
    float Hgt = 0.07;                                  // the puck's side height on screen
    // Mirror image in the floor and the shadow.
    float2 mq = float2(p.x, (p.y - Hgt * 2.0 - 0.02) / sq);
    float mirror = 1.0 - smoothstep(0.0, px / sq, length(mq) - R);
    col = mix(col, mix(col, mix(BG, A, 0.25), 0.35), mirror * step(Hgt, p.y) * 0.8);
    col *= 1.0 - 0.4 * (1.0 - smoothstep(0.0, 0.08, length(float2(p.x, (p.y - Hgt) / sq)) - R));
    // The puck's side band (front half only shows).
    float3 dark = mix(float3(0.12, 0.12, 0.14), BG, 0.4);
    float3 top = mix(float3(0.24, 0.25, 0.28), S * 0.4, 0.3);
    float topD = length(float2(p.x, p.y / sq)) - R;
    float sideD = length(float2(p.x, (p.y - Hgt) / sq)) - R;
    float side = (1.0 - smoothstep(0.0, px, sideD)) * step(0.0, p.y);
    float sideShade = 0.6 + 0.4 * (1.0 - abs(p.x) / R);
    col = mix(col, dark * (0.8 + 0.4 * sideShade), side * step(0.0, topD));
    // A light strip running round the front of the side.
    float strip = step(abs(sideD + 0.0 - (length(float2(p.x, (p.y - Hgt * 0.5) / sq)) - R) * 0.0), 1.0) * step(abs(p.y - Hgt * 0.5 - sq * sqrt(max(R * R - p.x * p.x, 0.0))), 0.004) * step(abs(p.x), R * 0.8);
    col = mix(col, mix(A, S, 0.5 + 0.5 * p.x / R) * (0.6 + 0.5 * breathe), strip);
    // Top face.
    if (topD < 0.0) {
        float2 tq = float2(p.x, p.y / sq);
        col = top * (0.85 + 0.25 * (-tq.y / R) * 0.5 + 0.1);
        col = mix(col, top * 1.35, smoothstep(-0.02, 0.0, topD) * step(tq.y, 0.0));
        // Brushed rings.
        col *= 0.96 + 0.04 * sin(length(tq) * 600.0);
        // A small bolt badge at the front and two touch keys.
        float2 bq = tq - float2(0.0, 0.38);
        float bolt = step(abs(bq.x + bq.y * 0.6 + 0.008), 0.009) * step(-0.03, bq.y) * step(bq.y, 0.002) + step(abs(bq.x + bq.y * 0.6 - 0.008), 0.009) * step(-0.002, bq.y) * step(bq.y, 0.03);
        col = mix(col, mix(A, float3(1.0), 0.3), sat(bolt));
        for (int i = 0; i < 2; i++) {
            float fi = float(i) * 2.0 - 1.0;
            float kd = length(tq - float2(fi * 0.3, 0.27)) - 0.025;
            col = mix(col, top * 0.6, 1.0 - smoothstep(0.0, px, kd));
            col = mix(col, mix(A, S, float(i)) * 0.8, 1.0 - smoothstep(0.0, px, abs(kd + 0.004) - 0.0025));
        }
    }
    // The bay: a well with a breathing light ring.
    float2 bq = float2(p.x, p.y / sq);
    float rb = length(bq);
    float bay = rb - 0.3;
    col = mix(col, mix(A, S, 0.5 + 0.5 * sin(atan(bq.y, bq.x) + t * 0.5)) * (0.5 + 0.6 * breathe), (1.0 - smoothstep(0.0, px, abs(bay) - 0.006)));
    col = mix(col, dark * 0.5, 1.0 - smoothstep(0.0, px, bay + 0.008));
    // The laser's red glow under the disc, tracking in and out.
    float sledR = 0.08 + 0.17 * (0.5 + 0.5 * sin(t * 0.3));
    // The disc.
    float an = atan(bq.y, bq.x);
    float spin = t * 3.0;
    float discM = (1.0 - smoothstep(0.0, px, rb - 0.27)) * smoothstep(0.024 - px, 0.024, rb) * (1.0 - cart);
    if (discM > 0.0 && uHasMedia > 0.5) {
        // The game's own disc: its picture turning with the spin (a disc picture fills its square), or its
        // cover printed on the disc's label ring; a little rainbow sheen and the clear hub stay.
        float2 lp = rot(-spin) * bq;
        float2 sz = max(uMediaSize, float2(1.0));
        float3 discCol;
        if (uMediaKind < 0.5) {
            float4 pc = float4(uMedia.eval((lp / 0.54 + 0.5) * sz));
            discCol = mix(float3(0.72, 0.74, 0.78), pc.rgb, pc.a);
        } else {
            float side = min(sz.x, sz.y);
            float2 cq = lp / 0.54;
            float3 cov = float3(uMedia.eval(sz * 0.5 + cq * side).rgb);
            discCol = mix(cov, float3(0.8, 0.82, 0.86), smoothstep(0.255, 0.262, rb));
        }
        float rbw = fract(an / TAU * 2.0 - t * 0.05 + rb * 3.0);
        float3 rainbow = 0.5 + 0.5 * cos(TAU * (rbw + float3(0.0, 0.33, 0.67)));
        discCol += rainbow * 0.08 * smoothstep(0.15, 0.26, rb);
        discCol = mix(discCol, float3(0.75, 0.8, 0.86) * 0.6, step(rb, 0.045));
        discCol += 0.2 * smoothstep(0.1, 0.0, abs(an - 2.3)) * smoothstep(0.05, 0.24, rb);
        col = mix(col, discCol, discM);
    } else if (discM > 0.0) {
        float rbw = fract(an / TAU * 2.0 - t * 0.05 + rb * 3.0);
        float3 rainbow = 0.5 + 0.5 * cos(TAU * (rbw + float3(0.0, 0.33, 0.67)));
        float3 discCol = mix(float3(0.72, 0.74, 0.78), rainbow, 0.4 * smoothstep(0.2, 0.26, rb)) * (0.85 + 0.15 * sin(rb * 320.0));
        float la = an - spin;
        if (rb < 0.2) {
            discCol = mix(A, S, step(0.5, fract(la / TAU * 3.0))) * 0.85;
            discCol = mix(discCol, float3(0.95), step(abs(rb - 0.13), 0.012));
            discCol = mix(discCol, mix(A, float3(1.0), 0.6), step(abs(fract(la / TAU) - 0.5), 0.03) * step(0.07, rb));
            float2 lp = rot(-spin) * bq;
            float2 q2 = lp - float2(0.0, -0.13);
            float bolt = step(abs(q2.x + q2.y * 0.6 + 0.008), 0.01) * step(-0.034, q2.y) * step(q2.y, 0.002) + step(abs(q2.x + q2.y * 0.6 - 0.008), 0.01) * step(-0.002, q2.y) * step(q2.y, 0.034);
            discCol = mix(discCol, float3(1.0), sat(bolt));
        }
        discCol = mix(discCol, float3(0.75, 0.8, 0.86) * 0.6, step(rb, 0.06));
        discCol += 0.28 * smoothstep(0.1, 0.0, abs(an - 2.3)) * smoothstep(0.05, 0.24, rb);
        col = mix(col, discCol, discM);
    }
    col += float3(1.0, 0.15, 0.1) * 0.4 * exp(-length(bq - float2(sledR, 0.0)) * 35.0) * step(rb, 0.3) * (0.75 + 0.25 * sin(t * 25.0));
    // The dome lid swung up at the back: a clear half-dome, seen edge-on, with its rim and a highlight.
    float2 lc = float2(0.0, -0.3 * sq - 0.17);
    float2 lq = (p - lc) * float2(1.0, 1.5);
    float dome = length(lq) - 0.3;
    float lidM = (1.0 - smoothstep(0.0, px, dome)) * step(lq.y, 0.12);
    col = mix(col, mix(col, mix(float3(0.85, 0.9, 1.0), S, 0.3), 0.25), lidM);
    col = mix(col, mix(float3(0.9, 0.95, 1.0), A, 0.2), (1.0 - smoothstep(0.0, px, abs(dome) - 0.003)) * step(lq.y, 0.12) * 0.8);
    col += 0.25 * lidM * smoothstep(0.04, 0.0, abs(length(lq - float2(0.06, 0.04)) - 0.22)) * step(lq.x, -0.05) * step(lq.y, -0.05);
    col = mix(col, top * 0.8, (1.0 - smoothstep(0.0, px, sdRoundBox(p - float2(0.0, -0.3 * sq - 0.005), float2(0.08, 0.012), 0.008))));
    // A cartridge game: its cartridge stands in the bay, swaying slowly in a beam of light from the laser.
    if (cart > 0.5) {
        float2 sz = max(uMediaSize, float2(1.0));
        float hgt = 0.36;
        float wid = hgt * sz.x / sz.y;
        if (wid > 0.3) { wid = 0.3; hgt = wid * sz.y / sz.x; }
        float turn = 0.8 + 0.2 * sin(t * 0.6);            // turning a little to and fro, always facing us
        float2 base = float2(0.0, 0.01 + 0.006 * sin(t * 1.4));
        float2 cq = p - base;
        float beam = exp(-abs(cq.x) / (0.05 + max(-cq.y, 0.0) * 0.4)) * step(cq.y, 0.0) * step(-0.55, cq.y);
        col += mix(A, S, 0.5) * beam * 0.18 * (0.7 + 0.3 * breathe);
        float hw = wid * 0.5 * max(abs(turn), 0.04);
        float2 q = float2(cq.x / (2.0 * hw) + 0.5, (cq.y + hgt) / hgt);
        if (q.x > 0.0 && q.x < 1.0 && q.y > 0.0 && q.y < 1.0) {
            float2 tq = float2(turn < 0.0 ? 1.0 - q.x : q.x, q.y);
            float4 pc = float4(uMedia.eval(tq * sz));
            float3 cc = turn < 0.0 ? pc.rgb * 0.35 + top * 0.4 : pc.rgb;  // its back: dark plastic
            cc *= 0.8 + 0.35 * abs(turn) * (1.0 - q.x * 0.4);
            cc += float3(1.0) * 0.12 * smoothstep(0.08, 0.0, abs(q.x - 0.15 - 0.5 * fract(t * 0.1)));
            col = mix(col, cc, step(0.5, pc.a));
        }
    }
    return half4(finish(col, fc), 1.0);
}
"""

    private const val ARCADE_ATTRACT = """
// Arcade attract: an original arcade cabinet in a dark arcade, running its attract mode. The marquee
// glows with a bolt and racing stripes; on the curved screen a little shooter plays itself - a ship
// weaving and firing at a marching formation that bursts apart wave after wave - the score ticking up,
// "INSERT COIN" blinking under it. The joystick and buttons glow, the coin slots shine, neighbouring
// cabinets flicker in the dark and everything is mirrored in the polished floor.
// A tiny 3 x 5 pixel font for scenes that print a few words or numbers (arcade screens, scoreboards).
// Each glyph is 15 bits, rows top to bottom, left pixel first.

// 1 where glyph [code] has a pixel at cell q (0..2 across, 0..4 down; anything else is 0).
float fontBit(float code, float2 q) {
    if (q.x < 0.0 || q.x > 2.0 || q.y < 0.0 || q.y > 4.0 || code < 0.5) return 0.0;
    float idx = (4.0 - q.y) * 3.0 + (2.0 - q.x);
    return mod(floor(code / exp2(idx)), 2.0);
}

float digitCode(float d) {
    if (d < 0.5) return 31599.0;
    if (d < 1.5) return 11415.0;
    if (d < 2.5) return 29671.0;
    if (d < 3.5) return 29647.0;
    if (d < 4.5) return 23497.0;
    if (d < 5.5) return 31183.0;
    if (d < 6.5) return 31215.0;
    if (d < 7.5) return 29257.0;
    if (d < 8.5) return 31727.0;
    return 31695.0;
}

// Pixel of number n (whole, up to 6 digits, zero padded to [digits]) at pixel q from its top-left; 4 pixels per digit.
float fontNumber(float n, float digits, float2 q) {
    float i = floor(q.x / 4.0);
    if (i < 0.0 || i >= digits) return 0.0;
    float d = mod(floor(n / pow(10.0, digits - 1.0 - i) + 0.0001), 10.0);
    return fontBit(digitCode(floor(d)), float2(q.x - i * 4.0, q.y));
}

// "INSERT COIN": the code of character i (spaces are 0).
float coinChar(float i) {
    if (i < 0.5) return 29847.0;   // I
    if (i < 1.5) return 24557.0;   // N
    if (i < 2.5) return 31183.0;   // S
    if (i < 3.5) return 31143.0;   // E
    if (i < 4.5) return 27565.0;   // R
    if (i < 5.5) return 29842.0;   // T
    if (i < 6.5) return 0.0;
    if (i < 7.5) return 31015.0;   // C
    if (i < 8.5) return 31599.0;   // O
    if (i < 9.5) return 29847.0;   // I
    return 24557.0;                // N
}

// The demo game at screen pixel q (0..96 across, 0..120 down): colour.
float3 demo(float2 q, float t, float3 A, float3 S) {
    float3 col = float3(0.0, 0.0, 0.03);
    // Scrolling starfield.
    float2 sp = float2(q.x, q.y - t * 20.0);
    col += float3(0.5, 0.6, 0.9) * step(0.985, hash12(floor(sp))) * 0.8;
    // Score and high score along the top.
    float wave = floor(t / 16.0);
    float wt = mod(t, 16.0);
    float score = wave * 1800.0 + floor(wt * 7.0) * 50.0;
    col = mix(col, float3(1.0), fontNumber(mod(score, 1000000.0), 6.0, floor(q - float2(4.0, 3.0))));
    col = mix(col, mix(A, float3(1.0), 0.3), fontBit(23533.0, floor(q - float2(58.0, 3.0))) + fontBit(29847.0, floor(q - float2(62.0, 3.0))));
    col = mix(col, mix(A, float3(1.0), 0.3), fontNumber(50000.0 + wave * 0.0, 5.0, floor(q - float2(67.0, 3.0))));
    // The formation: 6 x 3 drones, marching side to side and down a little.
    float march = floor(wt * 2.0);
    float2 fo = float2(14.0 + 10.0 * abs(mod(march, 8.0) - 4.0) / 4.0 * 2.0, 18.0 + min(wt, 12.0) * 1.2);
    float2 fq = q - fo;
    float2 gi = floor(fq / float2(12.0, 11.0));
    float2 gf = fq - gi * float2(12.0, 11.0);
    if (gi.x >= 0.0 && gi.x < 6.0 && gi.y >= 0.0 && gi.y < 3.0) {
        float id = gi.y * 6.0 + gi.x;
        float dieAt = 1.0 + hash11(id + wave * 31.0) * 13.0;
        float2 e = floor(gf) - float2(1.0, 1.0);
        float frame = mod(march, 2.0);
        if (wt < dieAt) {
            // An 8 x 7 drone: a diamond core with an eye, wings that flap each step.
            float core = step(abs(e.x - 3.5) + abs(e.y - 3.0) * 1.2, 3.1);
            float eye = step(abs(e.x - 3.5), 1.0) * step(abs(e.y - 3.0), 0.5);
            float wy = frame < 0.5 ? 2.0 : 4.0;
            float wings = step(abs(e.y - wy), 0.5) * (step(-1.0, e.x) * step(e.x, 0.5) + step(6.5, e.x) * step(e.x, 8.0));
            float body = core; float eyes = eye; float legs = wings; float ant = 0.0;
            float3 ec = gi.y < 0.5 ? mix(A, float3(1.0, 0.4, 0.6), 0.4) : (gi.y < 1.5 ? mix(S, float3(0.4, 1.0, 0.6), 0.4) : mix(A, S, 0.5));
            col = mix(col, ec, sat(body + legs + ant) * (1.0 - eyes));
        } else if (wt < dieAt + 0.3) {
            // Burst.
            float2 bq = e - float2(3.5, 3.0);
            col = mix(col, float3(1.0, 0.9, 0.5), step(abs(length(bq) - (wt - dieAt) * 18.0), 0.8) * step(0.5, fract(atan(bq.y, bq.x) / TAU * 8.0)));
        }
    }
    // The ship: weaving along the bottom.
    float sx = 48.0 + 34.0 * sin(t * 0.9) * cos(t * 0.37);
    float2 sq = floor(q - float2(sx, 106.0));
    float ship = step(abs(sq.x), 4.0 - max(sq.y, 0.0) * 0.0) * step(0.0, sq.y) * step(sq.y, 4.0) * step(abs(sq.x), 1.0 + sq.y);
    ship = max(ship, step(abs(sq.x), 0.5) * step(-2.0, sq.y) * step(sq.y, 0.0));
    col = mix(col, mix(float3(0.6, 0.9, 1.0), S, 0.3), ship);
    // Shots going up.
    for (int i = 0; i < 4; i++) {
        float fi = float(i);
        float st = fract(t * 1.6 + fi * 0.25);
        float bx = 48.0 + 34.0 * sin((t - st / 1.6) * 0.9) * cos((t - st / 1.6) * 0.37);
        float by = 104.0 - st * 110.0;
        col = mix(col, float3(1.0, 1.0, 0.6), step(abs(q.x - bx), 0.6) * step(abs(q.y - by), 2.0));
    }
    // INSERT COIN, blinking.
    if (fract(t * 0.8) < 0.6) {
        float2 tq = floor(q - float2(26.0, 114.0) + float2(0.0, 0.0));
        float ci = floor(tq.x / 4.0);
        if (ci >= 0.0 && ci < 11.0) col = mix(col, float3(1.0, 0.85, 0.3), fontBit(coinChar(ci), float2(tq.x - ci * 4.0, tq.y + 5.0)));
    }
    return col;
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float px = 1.5 / uRes.y;
    float cx = asp * 0.5;
    float x = uv.x - cx;

    // The arcade: dark walls with a neon strip, other cabinets glowing dimly on both sides.
    float3 col = mix(BG * 0.5, BG * 1.2, uv.y);
    col += mix(A, S, 0.5) * 0.08 * exp(-abs(uv.y - 0.08) * 40.0);
    for (int i = 0; i < 4; i++) {
        float fi = float(i);
        float side = fi < 2.0 ? -1.0 : 1.0;
        float k = mod(fi, 2.0);
        float ox = side * (0.48 + k * 0.32);
        float2 q = uv - float2(cx + ox, 0.48);
        float cab = sdRoundBox(q, float2(0.11, 0.42), 0.01);
        col = mix(col, BG * 0.35, 1.0 - smoothstep(0.0, px, cab));
        float scr = sdRoundBox(q - float2(0.0, -0.1), float2(0.075, 0.08), 0.01);
        float3 sc = mix(A, S, hash11(fi)) * (0.3 + 0.15 * sin(t * 3.0 + fi * 2.0));
        col = mix(col, sc, 1.0 - smoothstep(0.0, px, scr));
        col += sc * 0.15 * exp(-max(scr, 0.0) * 20.0);
    }
    // Polished floor with reflections.
    if (uv.y > 0.9) col = mix(col, BG * 0.4, 0.6);

    // The cabinet: side panels with stripes, then the face.
    float2 q = float2(x, uv.y);
    float sideP = step(abs(x), 0.25) * step(0.06, uv.y) * step(uv.y, 0.92);
    float face = step(abs(x), 0.21);
    float3 cabC = mix(float3(0.1, 0.1, 0.13), BG, 0.3);
    col = mix(col, cabC * 1.3, sideP);
    col = mix(col, mix(A, S, step(0.0, x)), sideP * step(0.21, abs(x)) * step(abs(fract(uv.y * 6.0 - abs(x) * 4.0) - 0.5), 0.12));
    // Marquee.
    float mq = sdRoundBox(q - float2(0.0, 0.13), float2(0.2, 0.055), 0.01);
    if (mq < 0.0) {
        float3 m = mix(A * 0.35, S * 0.35, (x + 0.2) / 0.4);
        m += 0.15 * step(abs(fract((x + uv.y * 0.6) * 12.0 - t * 0.5) - 0.5), 0.12);
        float2 b = q - float2(0.0, 0.13);
        float bolt = step(abs(b.x + b.y * 0.6 + 0.01), 0.012) * step(-0.04, b.y) * step(b.y, 0.003) + step(abs(b.x + b.y * 0.6 - 0.01), 0.012) * step(-0.003, b.y) * step(b.y, 0.04);
        m = mix(m, float3(1.0, 0.95, 0.8), sat(bolt));
        col = m * (0.9 + 0.1 * sin(t * 13.0) * step(0.97, fract(t * 0.2)));
    }
    col += mix(A, S, 0.5) * 0.2 * exp(-max(mq, 0.0) * 25.0) * (1.0 - step(mq, 0.0));
    // The bezel and the screen.
    float bz = sdRoundBox(q - float2(0.0, 0.4), float2(0.2, 0.2), 0.02);
    col = mix(col, float3(0.04), (1.0 - smoothstep(0.0, px, bz)) * face);
    float2 sh = float2(0.16, 0.19);
    float2 s = (q - float2(0.0, 0.4) + sh) / (2.0 * sh);
    // Curved tube: barrel distortion.
    float2 sc = s * 2.0 - 1.0;
    sc *= 1.0 + 0.06 * dot(sc, sc);
    float2 s2 = sc * 0.5 + 0.5;
    if (s2.x > 0.0 && s2.x < 1.0 && s2.y > 0.0 && s2.y < 1.0) {
        float3 g = demo(s2 * float2(96.0, 120.0), t, A, S);
        g *= 0.85 + 0.15 * sin(s2.y * 120.0 * PI);            // scanlines
        g *= 1.0 - 0.35 * dot(sc, sc) * 0.5;
        col = g * 1.2 + 0.03;
        col += 0.04 * smoothstep(0.3, 0.0, abs(s2.x + s2.y * 0.4 - 0.4));
    }
    col += mix(A, S, 0.5) * 0.06 * exp(-max(bz, 0.0) * 30.0) * step(0.0, bz) * face;
    // Control panel: slanted, with a joystick and three buttons.
    float cp = sdRoundBox(q - float2(0.0, 0.66), float2(0.23, 0.04), 0.008);
    col = mix(col, mix(cabC * 2.2, A * 0.4, 0.2), 1.0 - smoothstep(0.0, px, cp));
    col = mix(col, cabC * 3.0, (1.0 - smoothstep(0.0, px, cp)) * step(q.y, 0.63));
    float js = sin(t * 0.9 * 1.0) * cos(t * 0.37);
    float2 jq = q - float2(-0.11, 0.66);
    col = mix(col, float3(0.1), 1.0 - smoothstep(0.0, px, length(jq * float2(1.0, 2.0)) - 0.025));
    col = mix(col, float3(0.15), 1.0 - smoothstep(0.0, px, sdSegment(q, float2(-0.11, 0.66), float2(-0.11 + js * 0.015, 0.6)) - 0.004));
    col = mix(col, mix(A, float3(1.0, 0.3, 0.3), 0.3), 1.0 - smoothstep(0.0, px, length(q - float2(-0.11 + js * 0.015, 0.598)) - 0.014));
    for (int i = 0; i < 3; i++) {
        float fi = float(i);
        float2 bq = (q - float2(0.03 + fi * 0.055, 0.66 - fi * 0.006)) * float2(1.0, 2.0);
        float lit = step(0.7, fract(t * 1.6 + fi * 0.33));
        float3 bc = fi < 0.5 ? A : (fi < 1.5 ? S : mix(A, S, 0.5));
        col = mix(col, bc * (0.6 + 0.6 * lit), 1.0 - smoothstep(0.0, px, length(bq) - 0.018));
        col += bc * 0.2 * lit * exp(-max(length(bq) - 0.018, 0.0) * 40.0);
    }
    // Coin door.
    float cd = sdRoundBox(q - float2(0.0, 0.8), float2(0.08, 0.07), 0.006);
    col = mix(col, cabC * 1.7, (1.0 - smoothstep(0.0, px, cd)));
    for (int i = 0; i < 2; i++) {
        float fi = float(i) * 2.0 - 1.0;
        float slot = sdRoundBox(q - float2(fi * 0.035, 0.78), float2(0.016, 0.022), 0.004);
        col = mix(col, mix(float3(1.0, 0.25, 0.2), A, 0.3) * (0.7 + 0.3 * sin(t * 2.0 + fi)), 1.0 - smoothstep(0.0, px, slot));
        col = mix(col, float3(0.05), 1.0 - smoothstep(0.0, px, sdRoundBox(q - float2(fi * 0.035, 0.78), float2(0.002, 0.014), 0.001)));
    }
    // Floor reflection of the screen glow.
    col += mix(A, S, 0.5) * 0.12 * step(0.92, uv.y) * exp(-abs(x) * 6.0) * (0.8 + 0.2 * sin(uv.y * 200.0 + t));
    return half4(finish(col, fc), 1.0);
}
"""

    private const val NEON_CARTRIDGE = """
// Neon cartridge: a game cartridge drawn in neon tubes on a dark brick wall, above a neon console.
// The tubes buzz on with a flicker, the cartridge hovers, then slides down into the console's slot;
// the console lights up - power light, a glowing screen arc, a burst of sparks - before the cartridge
// rises out again (a 10 s loop). The wet floor below mirrors all of it.

// Glowing tube at distance d: a hot core and a wide soft glow.
float3 tube(float d, float3 c, float on, float px) {
    float core = 1.0 - smoothstep(0.0025, 0.0025 + px, d);
    float glowN = exp(-d * 90.0) * 0.55 + exp(-d * 22.0) * 0.22;
    return (mix(c, float3(1.0), 0.65) * core + c * glowN) * on;
}

// The cartridge outline at p (cartridge units, centre 0): shell, label window, grip ridges.
float cartD(float2 p) {
    float shell = abs(sdRoundBox(p, float2(0.16, 0.19), 0.02));
    // A notch cut in the top corners.
    float label = abs(sdRoundBox(p - float2(0.0, -0.035), float2(0.11, 0.1), 0.015));
    float d = min(shell, label);
    for (int i = 0; i < 3; i++) {
        float fi = float(i);
        d = min(d, sdSegment(p, float2(-0.09, 0.105 + fi * 0.025), float2(0.09, 0.105 + fi * 0.025)));
    }
    return d;
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float px = 1.5 / uRes.y;
    float T = mod(t, 10.0);
    float floorY = 0.86;
    // Below the floor line: the reflection (mirror the point, darken, ripple).
    float refl = step(floorY, uv.y);
    float2 w = uv;
    if (refl > 0.5) {
        w.y = 2.0 * floorY - uv.y;
        w.x += 0.004 * sin(uv.y * 160.0 + t * 2.0);
    }

    // Brick wall.
    float2 b = float2(w.x * 7.0, w.y * 14.0);
    b.x += step(0.5, fract(b.y * 0.5)) * 0.5;
    float2 bf = fract(b);
    float mortar = step(min(bf.x * 2.0, bf.y), 0.06) + step(0.94, bf.y) + step(0.97, bf.x);
    float3 brick = mix(float3(0.2, 0.09, 0.08), BG, 0.4) * (0.75 + 0.35 * hash12(floor(b)));
    float3 col = mix(brick, BG * 0.4, sat(mortar));
    col *= 0.6 + 0.4 * vnoise(w * 30.0);

    // Flicker-on at the start of each loop.
    float on = step(0.15, T) * (step(0.35, T) + step(fract(T * 23.0), 0.5) * step(T, 0.35)) * (1.0 - 0.15 * step(0.985, fract(t * 1.7)));
    on = sat(on);
    // Cartridge position: hovers, slides into the slot, stays, rises out.
    float down = smoothstep(3.0, 3.9, T) - smoothstep(8.2, 9.3, T);
    float2 cc = float2(asp * 0.5, 0.36 + 0.012 * sin(t * 1.5) * (1.0 - down) + down * 0.2);
    float slotY = 0.6;                                  // the top of the console: the cartridge hides below it
    float2 cp = w - cc;
    float dc = cartD(cp);
    float hidden = step(slotY, w.y);
    col += tube(dc, A, on * (1.0 - hidden), px);
    // A bolt on the label, in the second colour.
    float2 bq = cp - float2(0.0, -0.035);
    float bolt = min(sdSegment(bq, float2(0.02, -0.06), float2(-0.025, 0.005)), min(sdSegment(bq, float2(-0.025, 0.005), float2(0.025, -0.005)), sdSegment(bq, float2(0.025, -0.005), float2(-0.02, 0.06))));
    col += tube(bolt, S, on * (1.0 - hidden), px);

    // The console below: a wide rounded body with the slot on top, a screen arc and a power light.
    float lit = smoothstep(3.9, 4.3, T) * (1.0 - smoothstep(8.0, 8.4, T));
    float2 kp = w - float2(asp * 0.5, 0.72);
    float body = abs(sdRoundBox(kp, float2(0.34, 0.11), 0.06));
    float slot = sdSegment(kp, float2(-0.17, -0.12), float2(0.17, -0.12));
    float slotSides = min(sdSegment(kp, float2(-0.17, -0.12), float2(-0.17, -0.09)), sdSegment(kp, float2(0.17, -0.12), float2(0.17, -0.09)));
    col += tube(min(body, min(slot, slotSides)), S, on, px);
    // Pads on the console face.
    float pad = min(abs(length(kp - float2(-0.22, 0.02)) - 0.035), abs(length(kp - float2(0.22, 0.02)) - 0.035));
    col += tube(pad, mix(A, S, 0.5), on, px);
    // The screen arc lights up once the cartridge is in.
    float arc = abs(length(kp - float2(0.0, 0.12)) - 0.12);
    arc = max(arc, kp.y - 0.06);
    col += tube(arc, A, on * lit, px) * (0.9 + 0.1 * sin(t * 30.0));
    float led = length(kp - float2(0.0, 0.07)) - 0.008;
    col += mix(float3(0.2, 1.0, 0.4), A, 0.3) * (1.0 - smoothstep(0.0, px, led)) * lit;
    col += mix(float3(0.2, 1.0, 0.4), A, 0.3) * exp(-max(led, 0.0) * 50.0) * 0.6 * lit;
    // The burst of sparks as it clicks in.
    float sa = T - 3.9;
    if (sa > 0.0 && sa < 1.2) {
        for (int i = 0; i < 12; i++) {
            float fi = float(i);
            float ang = fi / 12.0 * TAU + 0.3;
            float2 sp = float2(asp * 0.5, slotY) + float2(cos(ang), sin(ang) * 0.6 - 0.4) * sa * (0.25 + 0.1 * hash11(fi)) + float2(0.0, 0.3 * sa * sa);
            col += mix(A, float3(1.0), 0.5) * exp(-length(w - sp) * 300.0) * (1.0 - sa / 1.2) * 1.5;
        }
    }
    // The wall glows where the tubes are.
    col += mix(A, S, 0.4) * 0.05 * on * exp(-length((w - float2(asp * 0.5, 0.5)) * float2(0.7, 1.0)) * 3.0);

    if (refl > 0.5) {
        col *= 0.38 * (1.0 - (uv.y - floorY) * 2.5);
        col += BG * 0.15;
    }
    return half4(finish(col, fc), 1.0);
}
