    private const val POSTER_WALL = """
// Poster wall: a long plaster wall covered in game-style posters (original designs: sunbursts, bold
// stripes, mountain sunsets, halftone targets, bolt prints), pinned in three layers at different
// depths. The view drifts slowly along it so the layers slide past each other; posters cast soft
// shadows, the far ones sit in haze, tape corners catch the light and two spotlights sweep across.
// Most posters are the covers of the games in your row (the one you're on among them), printed on the
// same paper; the rest keep the original designs.

uniform shader uCovers;     // the row's covers: 4 x 2 cells of 160 x 224 px (SceneArt), the game you're on first
uniform float2 uCoversSize;
uniform float uCoverN;      // how many cells are filled (0 = only the original designs)

float3 posterArt(float kind, float2 q, float3 A, float3 S, float3 BG) {
    // q: 0..1 across and down the poster.
    float3 ink = float3(0.08, 0.07, 0.1);
    float3 paper = float3(0.95, 0.92, 0.85);
    float3 c;
    float2 m = q - float2(0.5, 0.42);
    if (kind < 0.5) {
        float a = atan(m.y, m.x);
        c = mix(A, mix(A, float3(1.0), 0.3), step(0.0, sin(a * 12.0)));
        c = mix(c, S, 1.0 - step(0.2, length(m)));
    } else if (kind < 1.5) {
        c = mix(S, BG * 1.5, step(0.5, fract((q.x + q.y) * 5.0)));
        c = mix(c, A, step(abs(q.y - 0.35), 0.12));
    } else if (kind < 2.5) {
        c = mix(mix(A, float3(1.0, 0.8, 0.5), 0.3), S, q.y * 1.3);
        c = mix(c, float3(1.0, 0.95, 0.7), 1.0 - step(0.15, length(m - float2(0.0, -0.05))));
        float mtn = 0.55 - 0.2 * (1.0 - abs(fract(q.x * 1.5) - 0.5) * 2.0);
        c = mix(c, BG * 1.2, step(mtn, q.y));
    } else if (kind < 3.5) {
        float r = length(m);
        c = mix(paper, A, step(0.5, fract(r * 9.0)));
        float2 h = fract(q * 30.0) - 0.5;
        c = mix(c, S, step(length(h), 0.45 * q.y) * step(0.6, q.y));
    } else {
        c = BG * 1.4;
        float2 b = m * 1.3;
        float bolt = step(abs(b.x + b.y * 0.6 + 0.06), 0.07) * step(-0.25, b.y) * step(b.y, 0.02) + step(abs(b.x + b.y * 0.6 - 0.06), 0.07) * step(-0.02, b.y) * step(b.y, 0.25);
        c = mix(c, A, sat(bolt));
        float2 dg = fract(q * 12.0) - 0.5;
        c = mix(c, S * 0.8, step(length(dg), 0.18) * (1.0 - sat(bolt)) * 0.5);
    }
    // A bold title block at the bottom and a thin frame line.
    c = mix(c, ink, step(0.8, q.y) * step(abs(q.x - 0.5), 0.38) * step(q.y, 0.88));
    c = mix(c, paper, step(0.815, q.y) * step(q.y, 0.835) * step(abs(q.x - 0.5), 0.3) * step(0.5, fract(q.x * 9.0)));
    c = mix(c, paper, 1.0 - step(0.035, min(min(q.x, 1.0 - q.x), min(q.y, 1.0 - q.y))));
    return c;
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float px = 1.5 / uRes.y;
    float pan = t * 0.02 + 0.15 * sin(t * 0.07);

    // Plaster wall with a warm wash.
    float3 col = mix(float3(0.32, 0.28, 0.26), BG * 2.0, 0.5) * (0.85 + 0.15 * fbm3(uv * 6.0));
    // Three layers of posters: far (small, hazy, slow) to near (big, sharp, fast).
    for (int l = 0; l < 3; l++) {
        float fl = float(l);
        float sc = 0.6 + fl * 0.35;
        float off = pan * (0.6 + fl * 0.7);
        float cellW = 0.42 * sc;
        float2 lp = float2(uv.x + off + fl * 0.23, uv.y);
        float ci = floor(lp.x / cellW);
        float h1 = hash11(ci * 3.7 + fl * 11.0);
        if (h1 < 0.25 + 0.15 * fl) continue;              // gaps
        float2 size = float2(0.15, 0.21) * sc * (0.9 + 0.2 * hash11(ci + fl));
        float2 pc = float2((ci + 0.5) * cellW, 0.42 + (hash11(ci * 5.1 + fl) - 0.5) * 0.3);
        float ang = (hash11(ci * 9.3 + fl) - 0.5) * 0.12;
        float2 q = rot(ang) * (lp - pc);
        // Shadow, larger for nearer layers.
        float2 sq = rot(ang) * (lp - pc - float2(0.008, 0.012) * (1.0 + fl));
        float shD = sdRoundBox(sq, size, 0.002);
        col *= 1.0 - 0.35 * (1.0 - smoothstep(-0.01, 0.02 + fl * 0.01, shD));
        float pd = sdRoundBox(q, size, 0.002);
        if (pd < 0.0) {
            float2 pq = q / (2.0 * size) + 0.5;
            float3 art;
            float pick = hash11(ci * 2.3 + fl * 7.0);
            if (uCoverN > 0.5 && fract(pick * 7.3) > 0.18) {
                // A game's cover printed as a poster: a white border, the picture a little faded.
                float k = mod(floor(pick * 97.0) + ci, uCoverN);
                float2 cell = float2(mod(k, 4.0), floor(k / 4.0));
                float2 iq = clamp((pq - 0.045) / 0.91, 0.003, 0.997);
                art = float3(uCovers.eval((cell + iq) * uCoversSize / float2(4.0, 2.0)).rgb);
                art = mix(art, float3(0.96, 0.94, 0.88), 0.07);
                art = mix(art, float3(0.95, 0.92, 0.85), 1.0 - step(0.045, min(min(pq.x, 1.0 - pq.x), min(pq.y, 1.0 - pq.y))));
            } else {
                art = posterArt(floor(pick * 5.0), pq, A, S, BG);
            }
            // Paper: a slight curl shading and grain.
            art *= 0.9 + 0.1 * pq.y + 0.04 * (vnoise(pq * 80.0) - 0.5);
            art *= 1.0 - 0.12 * smoothstep(0.8, 1.0, pq.x) * smoothstep(0.7, 1.0, pq.y);
            // Haze on the far layers.
            art = mix(art, mix(float3(0.3, 0.28, 0.27), BG * 2.0, 0.5), 0.45 - fl * 0.22);
            col = art;
        }
        // Tape on the top corners.
        for (int k = 0; k < 2; k++) {
            float fk = float(k) * 2.0 - 1.0;
            float2 tq = rot(0.7 * fk) * (q - float2(fk * size.x, -size.y));
            float tape = step(abs(tq.x), 0.018 * sc) * step(abs(tq.y), 0.007 * sc);
            col = mix(col, mix(col, float3(0.95, 0.92, 0.75), 0.6), tape);
        }
    }
    // Two spotlights sweeping along the wall.
    for (int i = 0; i < 2; i++) {
        float fi = float(i);
        float sx = asp * (0.3 + 0.4 * fi) + 0.25 * sin(t * 0.13 + fi * 2.0);
        float2 sq = (uv - float2(sx, 0.42)) * float2(1.0, 0.8);
        col *= 0.75 + 0.55 * exp(-dot(sq, sq) * 9.0) * mix(float3(1.0, 0.9, 0.75), mix(A, float3(1.0), 0.6), fi);
    }
    // Floor strip with a skirting board.
    if (uv.y > 0.86) col = mix(BG * 0.6, float3(0.15, 0.12, 0.1), 0.5) * (0.8 + 0.2 * step(0.5, fract(uv.x * 4.0 + pan * 4.0)));
    col = mix(col, float3(0.1, 0.09, 0.09), step(abs(uv.y - 0.855), 0.008));
    // Dust motes in the light.
    col += float3(1.0, 0.95, 0.8) * 0.25 * dots(uv, 34.0, float2(t * 0.2, -t * 0.1), 0.1, 0.06, 7.0);
    return half4(finish(col, fc), 1.0);
}
"""

    private const val TROPHY_VAULT = """
// Trophy vault (32-bit): a dark hall of honour. Seven pedestals stand in a row, each with a badge
// floating above it - a star, gold and silver coins, a red bolt plaque, a blue bolt octagon - glowing in
// chunky pixels. A red carpet with gold trim runs up to the middle pedestal under a beam of light, where a
// gold coin turns on its edge; the coins spin, the badges bob, sparkles twinkle, and every few seconds
// one badge flares as if it had just been unlocked.
// Signed in to RetroAchievements, the pedestals hold your own trophies instead (TrophyShelf.kt): the games
// you mastered most recently in gold frames (the newest on the carpet, under the beam), then your latest
// unlocked badges in silver ones. Each one spins round every few seconds, showing its gold or silver back.
// Pedestals left over keep the drawn badges.
// Shared by the 32-bit creature-type scenes (px_*.agsl): a chunky pixel grid, an ordered dither and
// banded shading, so every scene reads as one 32-bit sprite picture. Shapes are evaluated at each
// pixel's centre with hard edges (no smoothing), colours are stepped through a few shades with a 4 x 4
// Bayer dither between them.

// The pixel a fragment belongs to, with PX_ROWS pixels on the screen's height.
const float PX_ROWS = 180.0;
float2 pxCell(float2 fc) { return floor(fc / uRes.y * PX_ROWS); }
// The centre of that pixel in screen heights (0..aspect across, 0..1 down).
float2 pxUv(float2 cell) { return (cell + 0.5) / PX_ROWS; }
// One pixel, in screen heights.
const float PX = 1.0 / 180.0;

// 4 x 4 ordered dither threshold for an integer cell, 0..1.
float bayer2(float2 p) { return 2.0 * p.x + 3.0 * p.y - 4.0 * p.x * p.y; }
float bayer4(float2 c) {
    float2 a = mod(c, 2.0);
    float2 b = mod(floor(c * 0.5), 2.0);
    return (4.0 * bayer2(a) + bayer2(b) + 0.5) / 16.0;
}

// v (0..1) stepped into n bands, dithered across each step.
float pxBand(float v, float n, float2 cell) {
    return clamp(floor(v * n + bayer4(cell)) / n, 0.0, 1.0);
}

// The colour stepped to a small palette (levels per channel), dithered.
float3 pxQuant(float3 c, float levels, float2 cell) {
    return floor(max(c, 0.0) * levels + bayer4(cell)) / levels;
}

// Four-shade ramp: dark, mid, light, highlight (v 0..1), banded and dithered.
float3 pxRamp(float v, float2 cell, float3 c0, float3 c1, float3 c2, float3 c3) {
    float b = pxBand(sat(v), 3.0, cell);
    return b < 0.17 ? c0 : (b < 0.5 ? c1 : (b < 0.84 ? c2 : c3));
}

// 1 inside a box of half size h around c (hard edge).
float pxBox(float2 p, float2 c, float2 h) {
    float2 d = abs(p - c) - h;
    return step(max(d.x, d.y), 0.0);
}

// 1 inside a circle (hard edge).
float pxDisc(float2 p, float2 c, float r) { return step(length(p - c), r); }

// 1 on a line from a to b that is w pixels thick (hard edge).
float pxLine(float2 p, float2 a, float2 b, float w) { return step(sdSegment(p, a, b), w * PX * 0.5 + 1e-5); }

// Snaps a moving position to the pixel grid, so sprites move a whole pixel at a time.
float2 pxSnap(float2 p) { return (floor(p * PX_ROWS) + 0.5) / PX_ROWS; }

uniform shader uTrophies;    // the trophies side by side: 7 square cells, uTrophySize.y pixels each
uniform float2 uTrophySize;
uniform float uTrophyN;      // how many cells are filled (0 = the drawn badges everywhere)
uniform float uFocusY;       // 0.5 + how far to move the hall down (share of the height; 0 = not set)
uniform float uMasteredN;    // the first this many are mastered games (gold), the rest badges (silver)

// Badge kind k at q (pixels from its centre), size r (pixels): 1 inside, 2 on the rim, 3 on the bolt.
float badgeShape(float k, float2 q, float r) {
    float d;
    if (k < 0.5) {                                    // star
        float a = atan(q.y, q.x) + PI * 0.5;
        float f = abs(fract(a / TAU * 5.0) - 0.5) * 2.0;
        d = length(q) - r * mix(0.45, 1.0, f * f * f);
        return d < 0.0 ? 1.0 : 0.0;
    }
    if (k < 1.5) d = length(q) - r;                                                       // coin
    else if (k < 2.5) d = max(abs(q.x) - r * 0.72, abs(q.y) - r) - 0.0 + 0.0 * r;         // plaque
    else { float2 h = abs(q); d = max(h.x * 0.924 + h.y * 0.383, max(h.y * 0.924 + h.x * 0.383, max(h.x, h.y))) - r; }   // octagon
    if (d > 0.0) return 0.0;
    if (d > -1.6) return 2.0;
    // The bolt: two slanted strokes.
    float2 b = q / max(r, 1.0) * 6.0;
    float bolt = step(abs(b.x + b.y * 0.55 + 0.7), 0.9) * step(-3.6, b.y) * step(b.y, 0.3)
               + step(abs(b.x + b.y * 0.55 - 0.7), 0.9) * step(-0.3, b.y) * step(b.y, 3.6);
    return bolt > 0.5 ? 3.0 : 1.0;
}

half4 main(float2 fc) {
    float2 cell = pxCell(fc);
    // Moved down (a game row at the top, or Theme look › Scene position): whole pixels, the wall continues above.
    cell.y -= floor((uFocusY > 0.001 ? clamp(uFocusY - 0.5, -0.15, 0.3) : 0.0) * PX_ROWS);
    float2 uv = pxUv(cell);
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float W = asp * PX_ROWS;                           // screen width in pixels
    float2 p = cell + 0.5;                             // this pixel
    float cx = W * 0.5;
    float hor = PX_ROWS * 0.6;                         // where the wall meets the floor

    // The hall: navy wall, a darker dado band, a floor of big dim tiles in perspective.
    float3 wall = mix(BG * 1.4 + float3(0.06, 0.08, 0.16), float3(0.12, 0.15, 0.3), 0.5);
    float3 col = wall * (0.8 + 0.25 * (p.y / hor));
    if (p.y > hor - 22.0) col = wall * 0.75;
    if (p.y > hor) {
        float z = 40.0 / (p.y - hor + 6.0);
        float xx = (p.x - cx) / W * z * 4.0;
        float tile = mod(floor(xx) + floor(z * 1.5), 2.0);
        col = mix(wall * 0.55, wall * 0.62, tile) * (0.75 + 0.25 * (p.y - hor) / (PX_ROWS - hor));
    }
    // Beams of light from above: a bright one in the middle, two faint ones beside it.
    float beamC = step(abs(p.x - cx), 10.0 + p.y * 0.35) * step(p.y, hor + 8.0);
    float beamL = step(abs(p.x - cx + W * 0.13 + p.y * 0.12), 8.0 + p.y * 0.25) * step(p.y, hor);
    float beamR = step(abs(p.x - cx - W * 0.13 - p.y * 0.12), 8.0 + p.y * 0.25) * step(p.y, hor);
    col += float3(0.6, 0.7, 1.0) * (0.13 * beamC + 0.05 * (beamL + beamR)) * (0.85 + 0.15 * sin(t * 0.7));
    col += float3(0.6, 0.7, 1.0) * 0.06 * step(abs(p.x - cx), 34.0) * exp(-abs(p.y - hor) * 0.08) * step(hor - 3.0, p.y);

    // The carpet: from the bottom edge up to the middle pedestal, widening towards you, gold edges.
    float cy0 = hor + 4.0;
    if (p.y > cy0) {
        float f = (p.y - cy0) / (PX_ROWS - cy0);
        float cw = 14.0 + f * 52.0;
        float dx = abs(p.x - cx);
        if (dx < cw) col = mix(mix(float3(0.62, 0.16, 0.14), A * 0.6, 0.15), mix(float3(0.78, 0.24, 0.2), A, 0.15), step(mod(floor(p.y * 0.25), 2.0), 0.5) * 0.3 + 0.35 * (1.0 - f));
        if (dx >= cw && dx < cw + 2.0 + f * 2.0) col = mix(float3(0.85, 0.6, 0.2), S * 0.8 + 0.2, 0.15);
    }

    // Seven pedestals with their badges. kind: 0 star, 1 coin, 2 plaque, 3 octagon.
    float flareN = floor(t / 4.0);
    float flareA = fract(t / 4.0) * 4.0;
    float flareI = mod(floor(hash11(flareN * 3.7) * 7.0), 7.0);
    for (int i = 0; i < 7; i++) {
        float fi = float(i);
        float u = fi < 0.5 ? 0.1 : (fi < 1.5 ? 0.215 : (fi < 2.5 ? 0.365 : (fi < 3.5 ? 0.5 : (fi < 4.5 ? 0.635 : (fi < 5.5 ? 0.785 : 0.9)))));
        float px0 = floor(W * u);
        float near = fi < 0.5 || fi > 5.5 ? 0.0 : 1.0;
        float base = hor + 12.0 - abs(fi - 3.0) * 1.0;
        float topY = base - 24.0 - 2.0 * step(abs(fi - 3.0), 1.5);
        float hw = 9.0 + 2.0 * step(abs(fi - 3.0), 2.5);
        // Column with a lit right edge, and a wider cap.
        float2 cq = p - float2(px0, 0.0);
        if (abs(cq.x) <= hw && p.y > topY && p.y < base) {
            col = mix(float3(0.13, 0.15, 0.25), BG + 0.08, 0.2);
            if (cq.x > hw - 4.0) col = float3(0.26, 0.29, 0.45);
            if (cq.x < -hw + 2.0) col *= 0.8;
        }
        if (abs(cq.x) <= hw + 3.0 && p.y > topY - 4.0 && p.y <= topY) col = p.y < topY - 2.0 ? float3(0.36, 0.4, 0.58) : float3(0.24, 0.27, 0.42);
        // The badge, bobbing; coins turn round.
        float kind = fi < 0.5 ? 0.0 : (fi < 1.5 || fi > 4.5 ? 1.0 : (fi < 2.5 ? 2.0 : (fi < 3.5 ? 1.0 : 3.0)));
        float r = fi < 0.5 ? 9.0 : (abs(fi - 3.0) < 0.5 ? 10.0 : (fi < 2.5 || abs(fi - 4.0) < 0.5 ? 13.0 : 11.0));
        float bob = floor(2.0 * sin(t * 1.3 + fi * 1.1) + 0.5);
        float2 bc = float2(px0, topY - r - 6.0 + bob);
        float spin = kind > 0.5 && kind < 1.5 ? cos(t * (abs(fi - 3.0) < 0.5 ? 2.2 : 0.9) + fi) : 1.0;
        if (abs(fi - 3.0) < 0.5) spin = 0.3 + 0.12 * sin(t * 2.5);      // the middle coin turns slowly on its edge
        float sx = max(abs(spin), 0.12);
        float2 q = floor(p - bc) + 0.5;
        q.x /= sx;
        float shape = badgeShape(kind, q, r);
        float3 bcol = fi < 0.5 ? float3(1.0, 0.78, 0.25) : (fi < 1.5 || fi > 5.5 ? float3(1.0, 0.75, 0.2) : (fi < 2.5 ? mix(float3(0.85, 0.3, 0.25), A, 0.25) : (fi < 3.5 ? float3(1.0, 0.82, 0.3) : (fi < 4.5 ? mix(float3(0.25, 0.45, 1.0), S, 0.25) : float3(0.82, 0.84, 0.92)))));
        float flare = abs(fi - flareI) < 0.5 ? exp(-flareA * 1.6) : 0.0;
        // Your own trophy on this pedestal: the middle first, then out to the sides.
        float slot = fi < 0.5 ? 5.0 : (fi < 1.5 ? 3.0 : (fi < 2.5 ? 1.0 : (fi < 3.5 ? 0.0 : (fi < 4.5 ? 2.0 : (fi < 5.5 ? 4.0 : 6.0)))));
        if (slot < uTrophyN - 0.5) {
            float mast = step(slot, uMasteredN - 0.5);
            float rr = 12.0 + 2.0 * mast + 3.0 * step(abs(fi - 3.0), 0.5);
            float3 fr = mast > 0.5 ? float3(1.0, 0.8, 0.3) : float3(0.8, 0.84, 0.95);
            // A full turn now and then (each on its own beat), resting face-on in between.
            float ph = fract(t / 5.5 + fi * 0.29);
            float cs = cos(TAU * smoothstep(0.0, 0.32, ph));
            float sxx = max(abs(cs), 0.1);
            float2 tc = float2(px0, topY - rr - 6.0 + bob);
            float2 q2 = floor(p - tc) + 0.5;
            float2 qq = float2(q2.x / sxx, q2.y);
            float gd2 = max(abs(q2.x) - rr * sxx, abs(q2.y) - rr);
            col = mix(col, mix(col, fr, 0.45), (1.0 - gd2 / (5.0 + 6.0 * flare)) * step(gd2, 5.0 + 6.0 * flare) * step(0.0, gd2) * step(0.5, mod(cell.x + cell.y, 2.0)) * (0.55 + 0.45 * flare));
            if (abs(qq.x) < rr && abs(qq.y) < rr) {
                float edge = rr - max(abs(qq.x), abs(qq.y));
                float3 c;
                if (cs > 0.0) {
                    float2 tuv = clamp(qq / rr * 0.5 + 0.5, 0.02, 0.98);
                    c = float3(uTrophies.eval(float2((slot + tuv.x) * uTrophySize.y, tuv.y * uTrophySize.y)).rgb);
