    private const val PIXEL_WORLD = """
// Pixel world: a 32-bit overworld map scrolling slowly by, as if a traveller were crossing it. Tiles
// of sea with rolling waves, beaches, meadows with flowers, forests, snowy mountains, winding roads and
// little towns; clouds drift over with their shadows and a small capsule hero walks in the middle -
// along the main road, which the map follows round its bends (the land either side of it is open
// meadow, so the hero never walks over trees, mountains or water).
// Shared by the 32-bit creature-type scenes (px_*.agsl): a chunky pixel grid, an ordered dither and
// banded shading, so every scene reads as one 32-bit sprite picture. Shapes are evaluated at each
// pixel's centre with hard edges (no smoothing), colours are stepped through a few shades with a 4 x 4
// Bayer dither between them.

// The pixel a fragment belongs to, with PX_ROWS pixels on the screen's height.
const float PX_ROWS = 180.0;
float2 pxCell(float2 fc) { return floor(fc / uRes.y * PX_ROWS); }
// The centre of that pixel in screen heights (0..aspect across, 0..1 down).
float2 pxUv(float2 cell) { return (cell + 0.5) / PX_ROWS; }
// One pixel, in screen heights.
const float PX = 1.0 / 180.0;

// 4 x 4 ordered dither threshold for an integer cell, 0..1.
float bayer2(float2 p) { return 2.0 * p.x + 3.0 * p.y - 4.0 * p.x * p.y; }
float bayer4(float2 c) {
    float2 a = mod(c, 2.0);
    float2 b = mod(floor(c * 0.5), 2.0);
    return (4.0 * bayer2(a) + bayer2(b) + 0.5) / 16.0;
}

// v (0..1) stepped into n bands, dithered across each step.
float pxBand(float v, float n, float2 cell) {
    return clamp(floor(v * n + bayer4(cell)) / n, 0.0, 1.0);
}

// The colour stepped to a small palette (levels per channel), dithered.
float3 pxQuant(float3 c, float levels, float2 cell) {
    return floor(max(c, 0.0) * levels + bayer4(cell)) / levels;
}

// Four-shade ramp: dark, mid, light, highlight (v 0..1), banded and dithered.
float3 pxRamp(float v, float2 cell, float3 c0, float3 c1, float3 c2, float3 c3) {
    float b = pxBand(sat(v), 3.0, cell);
    return b < 0.17 ? c0 : (b < 0.5 ? c1 : (b < 0.84 ? c2 : c3));
}

// 1 inside a box of half size h around c (hard edge).
float pxBox(float2 p, float2 c, float2 h) {
    float2 d = abs(p - c) - h;
    return step(max(d.x, d.y), 0.0);
}

// 1 inside a circle (hard edge).
float pxDisc(float2 p, float2 c, float r) { return step(length(p - c), r); }

// 1 on a line from a to b that is w pixels thick (hard edge).
float pxLine(float2 p, float2 a, float2 b, float w) { return step(sdSegment(p, a, b), w * PX * 0.5 + 1e-5); }

// Snaps a moving position to the pixel grid, so sprites move a whole pixel at a time.
float2 pxSnap(float2 p) { return (floor(p * PX_ROWS) + 0.5) / PX_ROWS; }

// The main road's centre across the world (in world pixels) at height y.
float mainRoad(float y) { return 60.0 * sin(y * 0.01) + 25.0 * sin(y * 0.027 + 1.3); }

half4 main(float2 fc) {
    float2 cell = pxCell(fc);
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    // World pixel under this screen pixel: the view follows the main road (a whole pixel at a time),
    // keeping the hero in the middle of the screen on it.
    float2 hc = floor(float2(asp * PX_ROWS * 0.5, PX_ROWS * 0.5));
    float camY = floor(t * 5.0);
    float2 cam = float2(floor(mainRoad(camY)), camY);
    float2 wp = cell - hc + cam;
    float2 tile = floor(wp / 8.0);
    float2 lp = wp - tile * 8.0;                       // 0..7 inside the tile
    float h = fbm3(tile * 0.07) * 0.75 + vnoise(tile * 0.25) * 0.25;
    h = (h - 0.5) * 2.4 + 0.5;
    // Open meadow for a couple of tiles either side of the main road.
    float2 tc = tile * 8.0 + 4.0;
    float roadTile = abs(tc.x - mainRoad(tc.y));
    h = mix(0.5, h, smoothstep(10.0, 26.0, roadTile));
    float onMain = step(abs(wp.x - floor(mainRoad(wp.y))), 3.5);
    float rd = abs(vnoise(tile * 0.05 + 7.0) - 0.5);   // roads follow a noise contour
    float th = hash12(tile);
    float3 col;
    if (h < 0.36) {
        // Sea: deeper further out, wave pixels rolling.
        col = mix(mix(float3(0.15, 0.4, 0.75), S, 0.25), mix(float3(0.25, 0.6, 0.9), S, 0.2), step(0.3, h));
        float wv = step(0.86, fract((wp.x + wp.y * 0.5) / 16.0 + t * 0.15 + th)) * step(abs(lp.y - 3.0), 0.5);
        col = mix(col, float3(0.85, 0.95, 1.0), wv);
    } else if (h < 0.4) {
        col = mix(float3(0.92, 0.85, 0.6), float3(0.85, 0.75, 0.5), step(0.8, hash12(wp)));
    } else if (h < 0.62) {
        col = mix(mix(float3(0.35, 0.68, 0.3), A, 0.12), mix(float3(0.42, 0.75, 0.35), A, 0.1), step(0.5, mod(tile.x + tile.y, 2.0)) * 0.6);
        // Flowers on some tiles.
        if (th > 0.8) col = mix(col, mix(float3(1.0, 0.9, 0.4), S, step(0.9, th)), step(abs(lp.x - 2.0), 0.5) * step(abs(lp.y - 5.0), 0.5) + step(abs(lp.x - 5.0), 0.5) * step(abs(lp.y - 2.0), 0.5));
        col = mix(col, col * 0.85, step(0.92, hash12(wp)));
    } else if (h < 0.8) {
        // Forest: round tree crowns with a lit side and a trunk.
        col = float3(0.2, 0.45, 0.2);
        float2 tq = lp - float2(3.5, 3.0);
        float crown = step(length(tq), 3.2);
        col = mix(col, mix(float3(0.15, 0.42, 0.2), float3(0.3, 0.62, 0.28), step(tq.x + tq.y, -1.0)), crown);
        col = mix(col, float3(0.4, 0.25, 0.15), step(abs(lp.x - 3.5), 0.6) * step(6.0, lp.y));
    } else {
        // Mountains: a peak per tile, snow on the high ones.
        col = mix(float3(0.45, 0.42, 0.4), float3(0.3, 0.42, 0.25), 0.3);
        float peak = step(abs(lp.x - 3.5) * 1.1, lp.y);
        float3 rock = mix(float3(0.55, 0.5, 0.48), float3(0.38, 0.35, 0.34), step(3.5, lp.x));
        col = mix(col, rock, peak);
        col = mix(col, float3(0.95, 0.97, 1.0), peak * step(lp.y, 2.5) * step(0.85, h));
    }
    // Roads on land: a sandy path with edge pixels (the main road, and side roads along a noise contour).
    if (h >= 0.4 && h < 0.8 && (rd < 0.025 || onMain > 0.5)) {
        col = mix(float3(0.85, 0.72, 0.48), float3(0.7, 0.58, 0.38), step(0.85, hash12(wp)));
    }
    // Towns: a few houses on meadow tiles near the road.
    if (h >= 0.4 && h < 0.62 && rd < 0.08 && rd >= 0.025 && th > 0.86 && roadTile > 9.0) {
        float2 hq = lp - float2(3.5, 4.0);
        float wall = step(abs(hq.x), 2.5) * step(0.0, hq.y) * step(hq.y, 3.0);
        float roof = step(abs(hq.x) - 3.0, -hq.y * 0.0) * step(-3.0, hq.y) * step(hq.y, -0.5) * step(abs(hq.x), 3.5 + hq.y);
        col = mix(col, float3(0.95, 0.92, 0.85), wall);
        col = mix(col, mix(float3(0.85, 0.3, 0.25), A, 0.35), roof);
        col = mix(col, float3(0.35, 0.25, 0.2), step(abs(hq.x), 0.5) * step(1.5, hq.y) * step(hq.y, 3.0));
    }
    // Cloud shadows, then clouds above.
    float2 cw = (cell + float2(t * 12.0, t * 4.0)) / 60.0;
    float cl = fbm3(cw);
    float clS = fbm3(cw + float2(0.12, 0.2));
    col *= 1.0 - 0.2 * step(0.62, clS);
    if (cl > 0.64) col = mix(float3(0.92, 0.94, 1.0), float3(1.0), step(0.7, cl));
    // The hero: a little capsule figure walking along the road in the middle.
    float2 q = cell - hc;
    float step2 = mod(floor(t * 4.0), 2.0);
    q.y += step2;
    float body = step(abs(q.x), 2.5) * step(-6.0, q.y) * step(q.y, 2.0) * step(length(max(abs(q - float2(0.0, -2.0)) - float2(0.0, 2.0), 0.0)), 2.6);
    float legs = step(2.0, q.y) * step(q.y, 4.0 - step2) * (step(abs(q.x + 1.0), 0.5) + step(abs(q.x - 1.0), 0.5));
    float3 heroC = mix(mix(A, float3(1.0), 0.15), float3(0.95), step(q.y, -2.0));
    col = mix(col, float3(0.1, 0.1, 0.12), sat(legs));
    col = mix(col, heroC, body);
    col = mix(col, float3(0.1), body * step(abs(q.y + 4.0), 0.5) * step(abs(abs(q.x) - 1.0), 0.5));
    col = mix(col, float3(0.0, 0.0, 0.0), 0.25 * step(abs(q.y - 5.0 + step2), 0.5) * step(abs(q.x), 2.5) * (1.0 - body));
    col = pxQuant(col, 10.0, cell);
    return half4(finish(col, fc), 1.0);
}
"""

    private const val BADGE_BOUNCE = """
// Badge bounce: the backdrop for your earned badges bouncing round the screen (BadgeBounceLayer draws
// them on top, in their own full quality and a little see-through). A deep velvet gradient in the
// theme's colours, big soft lights drifting slowly behind a faint honeycomb, and a shimmer that sweeps
// across the cells now and then, like light catching a trophy cabinet's glass.

// Distance to the nearest hexagon cell's edge (0 on the edge), for a honeycomb of size s.
float hexEdge(float2 p, float s) {
    float2 q = p / s;
    float2 r = float2(1.0, 1.7320508);
    float2 h = r * 0.5;
    float2 a = mod(q, r) - h;
    float2 b = mod(q - h, r) - h;
    float2 g = dot(a, a) < dot(b, b) ? a : b;
    float2 ag = abs(g);
    return 0.5 - max(dot(ag, normalize(float2(1.0, 1.7320508))), ag.x);
}

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    // Velvet: a diagonal gradient, deepest in the corners.
    float d = (uv.x / asp + uv.y) * 0.5;
    float3 col = mix(BG * 1.6 + S * 0.05, BG * 0.7 + A * 0.03, d);
    // Big soft lights drifting.
    for (int i = 0; i < 3; i++) {
        float fi = float(i);
        float2 c = float2(asp * (0.5 + 0.38 * sin(t * (0.05 + fi * 0.017) + fi * 2.1)), 0.5 + 0.32 * cos(t * (0.043 + fi * 0.013) + fi * 1.3));
        float3 lc = fi < 0.5 ? A : (fi < 1.5 ? S : mix(A, S, 0.5));
        col += lc * 0.16 * exp(-dot(uv - c, uv - c) * 4.0);
    }
    // A faint honeycomb with a shimmer sweeping across it.
    float e = hexEdge(uv + float2(t * 0.004, 0.0), 0.075);
    float line = 1.0 - smoothstep(0.0, 0.035, e);
    float sweep = exp(-sqf((uv.x / asp - uv.y * 0.35) - (fract(t / 9.0) * 1.8 - 0.4)) * 60.0);
    col += mix(A, float3(1.0), 0.4) * line * (0.025 + 0.12 * sweep);
    col += mix(S, A, 0.5) * (1.0 - smoothstep(0.0, 0.5, e)) * 0.015;
    // Tiny glints drifting up.
    col += mix(A, float3(1.0), 0.6) * dots(uv + float2(0.0, t * 0.01), 40.0, float2(0.0), 0.08, 0.05, 3.0) * 0.4;
    return half4(finish(col, fc), 1.0);
}
"""

    private const val PX_SPARK = """
// Spark · 32-bit (electric type): a pixel power line at night in a thunderstorm. Rolling storm clouds in
// three dithered shades, lattice pylons marching off over the hills, sagging wires with sparks racing
// along them, rain streaks, and every few seconds a forked bolt that strikes the nearest pylon and lights
// the whole sky.
// Shared by the 32-bit creature-type scenes (px_*.agsl): a chunky pixel grid, an ordered dither and
// banded shading, so every scene reads as one 32-bit sprite picture. Shapes are evaluated at each
// pixel's centre with hard edges (no smoothing), colours are stepped through a few shades with a 4 x 4
// Bayer dither between them.

// The pixel a fragment belongs to, with PX_ROWS pixels on the screen's height.
const float PX_ROWS = 180.0;
float2 pxCell(float2 fc) { return floor(fc / uRes.y * PX_ROWS); }
// The centre of that pixel in screen heights (0..aspect across, 0..1 down).
float2 pxUv(float2 cell) { return (cell + 0.5) / PX_ROWS; }
// One pixel, in screen heights.
const float PX = 1.0 / 180.0;

// 4 x 4 ordered dither threshold for an integer cell, 0..1.
float bayer2(float2 p) { return 2.0 * p.x + 3.0 * p.y - 4.0 * p.x * p.y; }
float bayer4(float2 c) {
    float2 a = mod(c, 2.0);
    float2 b = mod(floor(c * 0.5), 2.0);
    return (4.0 * bayer2(a) + bayer2(b) + 0.5) / 16.0;
}

// v (0..1) stepped into n bands, dithered across each step.
float pxBand(float v, float n, float2 cell) {
    return clamp(floor(v * n + bayer4(cell)) / n, 0.0, 1.0);
}

// The colour stepped to a small palette (levels per channel), dithered.
float3 pxQuant(float3 c, float levels, float2 cell) {
    return floor(max(c, 0.0) * levels + bayer4(cell)) / levels;
}

// Four-shade ramp: dark, mid, light, highlight (v 0..1), banded and dithered.
float3 pxRamp(float v, float2 cell, float3 c0, float3 c1, float3 c2, float3 c3) {
    float b = pxBand(sat(v), 3.0, cell);
    return b < 0.17 ? c0 : (b < 0.5 ? c1 : (b < 0.84 ? c2 : c3));
}

// 1 inside a box of half size h around c (hard edge).
float pxBox(float2 p, float2 c, float2 h) {
    float2 d = abs(p - c) - h;
    return step(max(d.x, d.y), 0.0);
}

// 1 inside a circle (hard edge).
float pxDisc(float2 p, float2 c, float r) { return step(length(p - c), r); }

// 1 on a line from a to b that is w pixels thick (hard edge).
float pxLine(float2 p, float2 a, float2 b, float w) { return step(sdSegment(p, a, b), w * PX * 0.5 + 1e-5); }

// Snaps a moving position to the pixel grid, so sprites move a whole pixel at a time.
float2 pxSnap(float2 p) { return (floor(p * PX_ROWS) + 0.5) / PX_ROWS; }

half4 main(float2 fc) {
    float2 cell = pxCell(fc);
    float2 uv = pxUv(cell);
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    // The strike: every 4.5 s, a short double flash.
    float cyc = t / 4.5;
    float k = floor(cyc);
    float age = fract(cyc) * 4.5;
    float flash = exp(-age * 9.0) + 0.6 * exp(-max(age - 0.18, 0.0) * 12.0) * step(0.18, age);

    // Sky: deep storm blue, banded.
    float3 sky0 = mix(BG, S * 0.25, 0.5) * 0.7;
    float3 sky1 = mix(BG * 1.6, S * 0.45, 0.5);
    float3 col = mix(sky1, sky0, pxBand(1.0 - uv.y * 1.3, 4.0, cell));
    // Clouds: three shades, the light side lit by the flash.
    float c = fbm3(float2(uv.x * 2.2 + t * 0.03, uv.y * 4.0 - t * 0.01));
    float cm = c - uv.y * 0.9;
    float3 cloudD = mix(BG, S * 0.35, 0.4) * 0.9;
    float3 cloudM = mix(BG * 2.0, S * 0.6, 0.5);
    float3 cloudL = mix(cloudM, float3(0.85, 0.88, 1.0), 0.15 + 0.7 * flash);
    if (cm > 0.12) col = cloudD;
    if (cm > 0.22) col = mix(cloudD, cloudM, pxBand(sat((cm - 0.22) * 4.0), 2.0, cell));
    if (cm > 0.32 && fbm3(float2(uv.x * 2.2 + t * 0.03, uv.y * 4.0 - t * 0.01) - 0.04) < c) col = cloudL;
    col += (S * 0.4 + 0.25) * flash * 0.35 * (1.0 - uv.y);

    // Hills: two silhouettes.
    float h1 = 0.68 + 0.05 * sin(uv.x * 3.1) + 0.02 * sin(uv.x * 9.0 + 1.0);
    float h2 = 0.8 + 0.04 * sin(uv.x * 2.3 + 2.0);
    if (uv.y > h1) col = mix(BG * 1.3, S * 0.15, 0.3) + flash * 0.08;
    if (uv.y > h2) col = BG * 0.8 + flash * 0.05;

    // Pylons: lattice towers every 0.95 screen heights, smaller further back (two rows).
    float3 steel = mix(float3(0.45, 0.48, 0.55), S, 0.2) * (0.6 + 0.9 * flash);
    float wireHit = 0.0;
    float sparkHit = 0.0;
    for (int r = 0; r < 2; r++) {
        float fr = float(r);
        float sc = fr < 0.5 ? 1.0 : 0.55;
        float spacing = 0.95 * sc;
        float base = fr < 0.5 ? 0.97 : 0.76;
        float hgt = 0.48 * sc;
        float xi = floor(uv.x / spacing + 0.5);
        float px0 = xi * spacing;
        float2 q = float2(uv.x - px0, uv.y);
        float yTop = base - hgt;
        float f = sat((uv.y - yTop) / hgt);             // 0 at the top, 1 at the foot
        float halfW = (0.012 + 0.06 * f * f) * sc;
        float inY = step(yTop, uv.y) * step(uv.y, base);
        float legs = step(abs(abs(q.x) - halfW), PX * 0.6) * inY;
        // Cross braces: an X in each storey.
        float st = (uv.y - yTop) / (hgt / 5.0);
        float sf = fract(st);
        float brace = step(abs(abs(q.x) / max(halfW, 1e-4) - abs(1.0 - 2.0 * sf)), 0.12 / max(sc, 0.5)) * step(abs(q.x), halfW) * inY;
        // Two crossarms near the top.
        float arm = (pxBox(q, float2(0.0, yTop + 0.03 * sc), float2(0.07 * sc, PX * 0.5)) + pxBox(q, float2(0.0, yTop + 0.09 * sc), float2(0.055 * sc, PX * 0.5)));
        float tower = max(max(legs, brace), min(arm, 1.0));
        if (tower > 0.5) col = steel * (fr < 0.5 ? 1.0 : 0.7);
        // Wires between this tower's arms and the next: catenaries.
        for (int w = 0; w < 2; w++) {
            float fw = float(w);
            float armY = yTop + (fw < 0.5 ? 0.03 : 0.09) * sc;
            float armX = (fw < 0.5 ? 0.07 : 0.055) * sc;
            float u = fract((uv.x - armX) / spacing);
            float sag = 0.05 * sc * 4.0 * u * (1.0 - u);
            float wy = armY + sag;
            float on = step(abs(uv.y - wy), PX * 0.55);
            wireHit = max(wireHit, on * (fr < 0.5 ? 1.0 : 0.6));
            // A spark racing along the wire, with a short trail.
            float sp = fract(t * (0.35 + 0.1 * fw + 0.07 * fr) + fw * 0.4 + fr * 0.17);
            float span = floor((uv.x - armX) / spacing);
            float lead = sp - u;
            float trail = step(0.0, lead) * step(lead, 0.08) * (1.0 - lead / 0.08) * step(0.5, hash11(span * 3.1 + fw + fr * 7.0) + 0.3);
            sparkHit = max(sparkHit, on * trail);
        }
    }
    col = mix(col, float3(0.08, 0.08, 0.1) + flash * 0.3, wireHit * 0.9);
    col = mix(col, mix(A, float3(1.0), 0.4), step(0.35, sparkHit));
    col = mix(col, A, step(0.05, sparkHit) * step(sparkHit, 0.35) * 0.8);

    // The bolt: from the clouds to the top of a front pylon, jagged, forking once.
    float targetI = floor(hash11(k * 7.3) * (asp / 0.95)) + 1.0;
    float2 tip = float2(targetI * 0.95, 0.97 - 0.48);
    float2 top = float2(tip.x + (hash11(k * 2.7) - 0.5) * 0.5, 0.05);
    float bolt = 0.0;
    float halo = 0.0;
    float2 prev = top;
    for (int i = 1; i <= 7; i++) {
        float fi = float(i) / 7.0;
        float zig = (mod(float(i), 2.0) < 0.5 ? 1.0 : -1.0) * (0.03 + 0.05 * hash11(k * 13.0 + float(i)));
        float2 nx = mix(top, tip, fi) + float2(zig * (1.0 - fi * fi * 0.7), 0.0);
        if (i == 7) nx = tip;
        bolt = max(bolt, pxLine(uv, prev, nx, 2.0));
        halo = max(halo, pxLine(uv, prev, nx, 6.0));
        if (i == 3) {
            float2 fork = nx + float2((hash11(k * 5.0) - 0.5) * 0.25, 0.16);
            bolt = max(bolt, pxLine(uv, nx, fork, 1.0) * 0.8);
        }
        prev = nx;
    }
    float lit = step(age, 0.32) * (step(age, 0.08) + step(0.18, age));
    col = mix(col, mix(col, A, 0.6), halo * lit * 0.6);
    col = mix(col, mix(float3(1.0), A, 0.25), bolt * lit);
    // A glow ring round the struck tower top.
    col += A * 0.6 * step(length(uv - tip), 0.03 + age * 0.1) * step(age * 0.1 + 0.015, length(uv - tip)) * exp(-age * 5.0);

    // Rain: slanted pixel streaks.
    float2 rp = float2(uv.x + uv.y * 0.35 + t * 0.6, uv.y + t * 1.8);
    float2 rc = floor(rp * float2(60.0, 9.0));
    float rn = hash12(rc);
    float rf = fract(rp.y * 9.0);
    col = mix(col, mix(col, float3(0.7, 0.75, 0.9), 0.5), step(0.9, rn) * step(rf, 0.35) * step(abs(fract(rp.x * 60.0) - 0.5), 0.2));

    col = pxQuant(col, 10.0, cell);
    return half4(finish(col, fc), 1.0);
}
"""

    private const val PX_TORRENT = """
// Torrent · 32-bit (water type): a sunny bay cut at the waterline. Above, a little sailboat bobs on
// rolling pixel waves under a high sun and gulls; below, light shafts sway through banded blue water,
// a school of fish wheels past, kelp sways from the sandy floor and bubbles climb to the surface.
// Shared by the 32-bit creature-type scenes (px_*.agsl): a chunky pixel grid, an ordered dither and
// banded shading, so every scene reads as one 32-bit sprite picture. Shapes are evaluated at each
// pixel's centre with hard edges (no smoothing), colours are stepped through a few shades with a 4 x 4
// Bayer dither between them.

// The pixel a fragment belongs to, with PX_ROWS pixels on the screen's height.
const float PX_ROWS = 180.0;
float2 pxCell(float2 fc) { return floor(fc / uRes.y * PX_ROWS); }
// The centre of that pixel in screen heights (0..aspect across, 0..1 down).
float2 pxUv(float2 cell) { return (cell + 0.5) / PX_ROWS; }
// One pixel, in screen heights.
const float PX = 1.0 / 180.0;

// 4 x 4 ordered dither threshold for an integer cell, 0..1.
float bayer2(float2 p) { return 2.0 * p.x + 3.0 * p.y - 4.0 * p.x * p.y; }
float bayer4(float2 c) {
    float2 a = mod(c, 2.0);
    float2 b = mod(floor(c * 0.5), 2.0);
    return (4.0 * bayer2(a) + bayer2(b) + 0.5) / 16.0;
}

// v (0..1) stepped into n bands, dithered across each step.
float pxBand(float v, float n, float2 cell) {
    return clamp(floor(v * n + bayer4(cell)) / n, 0.0, 1.0);
}

// The colour stepped to a small palette (levels per channel), dithered.
float3 pxQuant(float3 c, float levels, float2 cell) {
    return floor(max(c, 0.0) * levels + bayer4(cell)) / levels;
}

// Four-shade ramp: dark, mid, light, highlight (v 0..1), banded and dithered.
float3 pxRamp(float v, float2 cell, float3 c0, float3 c1, float3 c2, float3 c3) {
    float b = pxBand(sat(v), 3.0, cell);
    return b < 0.17 ? c0 : (b < 0.5 ? c1 : (b < 0.84 ? c2 : c3));
}

// 1 inside a box of half size h around c (hard edge).
float pxBox(float2 p, float2 c, float2 h) {
    float2 d = abs(p - c) - h;
    return step(max(d.x, d.y), 0.0);
}

// 1 inside a circle (hard edge).
float pxDisc(float2 p, float2 c, float r) { return step(length(p - c), r); }

// 1 on a line from a to b that is w pixels thick (hard edge).
float pxLine(float2 p, float2 a, float2 b, float w) { return step(sdSegment(p, a, b), w * PX * 0.5 + 1e-5); }

// Snaps a moving position to the pixel grid, so sprites move a whole pixel at a time.
float2 pxSnap(float2 p) { return (floor(p * PX_ROWS) + 0.5) / PX_ROWS; }

half4 main(float2 fc) {
    float2 cell = pxCell(fc);
    float2 uv = pxUv(cell);
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    float sea = 0.36 + 0.012 * sin(uv.x * 9.0 - t * 1.6) + 0.006 * sin(uv.x * 23.0 + t * 2.3);
    float3 col;
    if (uv.y < sea) {
        // Sky, sun and clouds.
        float3 skyTop = mix(float3(0.25, 0.55, 0.9), A * 0.7, 0.3);
        float3 skyLow = mix(float3(0.75, 0.9, 1.0), S, 0.25);
        col = mix(skyTop, skyLow, pxBand(uv.y / sea, 4.0, cell));
        float2 sun = float2(asp * 0.78, 0.1);
        float sd = length(uv - sun);
        if (sd < 0.075) col = mix(float3(1.0, 0.95, 0.7), float3(1.0), step(sd, 0.05));
        else col = mix(col, float3(1.0, 0.97, 0.85), pxBand(sat(0.11 - sd) * 4.0, 2.0, cell) * 0.5);
        float cl = fbm3(float2(uv.x * 3.0 + t * 0.02, uv.y * 9.0));
        if (cl > 0.62 - uv.y * 0.3 && uv.y < 0.25) col = mix(float3(0.92, 0.95, 1.0), float3(1.0), step(0.7, cl));
        // Gulls: little "v"s gliding.
        for (int i = 0; i < 3; i++) {
            float fi = float(i);
            float2 g = pxSnap(float2(fract(fi * 0.37 + t * 0.012 * (1.0 + fi * 0.3)) * (asp + 0.2) - 0.1, 0.12 + 0.06 * fi + 0.01 * sin(t + fi)));
            float2 q = (uv - g) / PX;
            float flap = step(0.0, sin(t * 6.0 + fi * 2.0));
            float wing = step(abs(abs(q.x) - 2.0 - (flap > 0.5 ? 0.0 : 0.0)), 1.6) * step(abs(q.y + abs(q.x) * (flap > 0.5 ? 0.5 : -0.3)), 0.6) * step(abs(q.x), 3.6);
            col = mix(col, float3(0.15, 0.18, 0.25), wing);
        }
        // The boat: hull, mast and sail, rocking with the waves.
        float bx = asp * 0.3;
        float by = 0.36 + 0.012 * sin(bx * 9.0 - t * 1.6) - 0.004;
        float2 bq = rot(0.08 * sin(t * 1.6 - bx * 9.0 + 1.5)) * (uv - float2(bx, by));
        float hull = step(bq.y, 0.0) * step(-0.022, bq.y) * step(abs(bq.x), 0.06 - (bq.y + 0.022) * -0.9);
        float mast = pxBox(bq, float2(0.0, -0.075), float2(PX * 0.5, 0.055));
        float sail = step(bq.y, -0.03) * step(-0.12, bq.y) * step(PX, bq.x) * step(bq.x, (bq.y + 0.12) * 0.55);
        float jib = step(bq.y, -0.03) * step(-0.1, bq.y) * step(bq.x, -PX) * step(-(bq.y + 0.1) * 0.4, bq.x);
        col = mix(col, float3(0.98, 0.96, 0.9), max(sail, jib));
        col = mix(col, mix(A, float3(0.7, 0.25, 0.2), 0.4), hull);
        col = mix(col, float3(0.35, 0.25, 0.2), mast);
    } else {
        // Under the water: banded depth.
        float d = (uv.y - sea) / (1.0 - sea);
        float3 w0 = mix(float3(0.2, 0.65, 0.85), S, 0.3);
        float3 w1 = mix(float3(0.05, 0.25, 0.5), A * 0.4, 0.25);
        col = mix(w0, w1, pxBand(d, 5.0, cell));
        // Light shafts, swaying.
        float sh = sin((uv.x + uv.y * 0.35) * 14.0 + sin(t * 0.5) * 1.5) * sin((uv.x + uv.y * 0.35) * 5.0 - t * 0.3);
        col += float3(0.6, 0.9, 1.0) * 0.12 * pxBand(sat(sh) * (1.0 - d), 3.0, cell);
        // The surface seen from below: a bright rippling band.
        col = mix(col, float3(0.75, 0.95, 1.0), step(uv.y - sea, PX * 1.5) * 0.8);
        // Sand and rocks.
        float floorY = 0.9 + 0.025 * sin(uv.x * 4.0 + 1.0);
        if (uv.y > floorY) col = mix(float3(0.85, 0.75, 0.5), float3(0.65, 0.55, 0.35), pxBand(hash12(cell) * 0.4 + (uv.y - floorY) * 6.0, 3.0, cell));
        float rk = length((uv - float2(asp * 0.72, 0.93)) * float2(1.0, 1.6)) - 0.06;
        if (rk < 0.0) col = mix(float3(0.3, 0.32, 0.38), float3(0.45, 0.47, 0.52), step(uv.y, 0.905));
        // Kelp: wavy stalks swaying.
        for (int i = 0; i < 7; i++) {
            float fi = float(i);
            float kx = (fi + 0.5 + 0.3 * hash11(fi)) / 7.0 * asp;
            float kh = 0.3 + 0.2 * hash11(fi * 3.0);
            float yy = (floorY - uv.y) / kh;
            float sway = sin(t * 1.2 + fi + uv.y * 10.0) * 0.015 * yy;
            float stalk = step(0.0, yy) * step(yy, 1.0) * step(abs(uv.x - kx - sway), PX * 1.2);
            float leaf = step(0.0, yy) * step(yy, 0.95) * step(abs(uv.x - kx - sway - 0.012 * sin(uv.y * 60.0)), PX * 2.0) * step(0.5, fract(uv.y * 25.0 + fi));
            col = mix(col, mix(float3(0.15, 0.5, 0.25), float3(0.35, 0.7, 0.3), step(0.5, fract(uv.y * 40.0))), max(stalk, leaf));
        }
        // A school of fish wheeling round.
        float2 sc = float2(asp * 0.55 + 0.25 * sin(t * 0.21), 0.6 + 0.08 * sin(t * 0.33));
        float dirX = cos(t * 0.21) >= 0.0 ? 1.0 : -1.0;
        for (int i = 0; i < 10; i++) {
            float fi = float(i);
            float2 o = float2(cos(fi * 2.4 + t * 0.8), sin(fi * 1.7 + t * 0.6)) * float2(0.16, 0.08) * (0.5 + 0.5 * hash11(fi));
            float2 f = pxSnap(sc + o);
            float2 q = (uv - f) / PX / 1.5;
            q.x *= dirX;
            float body = step(abs(q.y), 1.1 - abs(q.x) * 0.3) * step(abs(q.x), 2.6);
            float tail = step(-4.6, q.x) * step(q.x, -2.4) * step(abs(q.y), (-q.x - 2.4) * 0.8 + 0.2);
            float3 fcol = mix(mix(float3(1.0, 0.55, 0.2), S, 0.25), float3(1.0, 0.9, 0.55), step(q.y, -0.5));
            fcol = mix(fcol, float3(1.0), step(abs(q.x + 0.3), 0.45) * step(abs(q.y), 1.0));
            col = mix(col, fcol, max(body, tail));
            col = mix(col, float3(0.05), step(length(q - float2(1.4, -0.3)), 0.5));
        }
        // Bubbles.
        for (int i = 0; i < 8; i++) {
            float fi = float(i);
            float life = fract(t * (0.12 + 0.05 * hash11(fi)) + hash11(fi * 9.0));
            float2 b = pxSnap(float2((hash11(fi * 4.3) * 0.9 + 0.05) * asp + 0.01 * sin(life * 20.0), mix(0.92, sea + 0.02, life)));
            float r = length(uv - b);
            col = mix(col, float3(0.85, 0.97, 1.0), step(abs(r - PX * 1.6), PX * 0.6) + step(length(uv - b + float2(PX * 0.6, PX * 0.6)), PX * 0.5));
        }
    }
    col = pxQuant(col, 10.0, cell);
    return half4(finish(col, fc), 1.0);
}
"""

    private const val PX_SPROUT = """
// Sprout · 32-bit (grass type): a sunny garden bed. Vines climb their bamboo canes in turn - leaves
// unfurling at each node as the tip passes, a flower opening at the top - while butterflies flit
// between them, sunflowers nod at the back and the grass sways in tiles at the front.
// Shared by the 32-bit creature-type scenes (px_*.agsl): a chunky pixel grid, an ordered dither and
// banded shading, so every scene reads as one 32-bit sprite picture. Shapes are evaluated at each
// pixel's centre with hard edges (no smoothing), colours are stepped through a few shades with a 4 x 4
// Bayer dither between them.

// The pixel a fragment belongs to, with PX_ROWS pixels on the screen's height.
const float PX_ROWS = 180.0;
float2 pxCell(float2 fc) { return floor(fc / uRes.y * PX_ROWS); }
// The centre of that pixel in screen heights (0..aspect across, 0..1 down).
float2 pxUv(float2 cell) { return (cell + 0.5) / PX_ROWS; }
// One pixel, in screen heights.
const float PX = 1.0 / 180.0;

// 4 x 4 ordered dither threshold for an integer cell, 0..1.
float bayer2(float2 p) { return 2.0 * p.x + 3.0 * p.y - 4.0 * p.x * p.y; }
float bayer4(float2 c) {
    float2 a = mod(c, 2.0);
    float2 b = mod(floor(c * 0.5), 2.0);
    return (4.0 * bayer2(a) + bayer2(b) + 0.5) / 16.0;
}

// v (0..1) stepped into n bands, dithered across each step.
float pxBand(float v, float n, float2 cell) {
    return clamp(floor(v * n + bayer4(cell)) / n, 0.0, 1.0);
}

// The colour stepped to a small palette (levels per channel), dithered.
float3 pxQuant(float3 c, float levels, float2 cell) {
    return floor(max(c, 0.0) * levels + bayer4(cell)) / levels;
}

// Four-shade ramp: dark, mid, light, highlight (v 0..1), banded and dithered.
float3 pxRamp(float v, float2 cell, float3 c0, float3 c1, float3 c2, float3 c3) {
    float b = pxBand(sat(v), 3.0, cell);
    return b < 0.17 ? c0 : (b < 0.5 ? c1 : (b < 0.84 ? c2 : c3));
}

// 1 inside a box of half size h around c (hard edge).
float pxBox(float2 p, float2 c, float2 h) {
    float2 d = abs(p - c) - h;
    return step(max(d.x, d.y), 0.0);
}

// 1 inside a circle (hard edge).
float pxDisc(float2 p, float2 c, float r) { return step(length(p - c), r); }

// 1 on a line from a to b that is w pixels thick (hard edge).
float pxLine(float2 p, float2 a, float2 b, float w) { return step(sdSegment(p, a, b), w * PX * 0.5 + 1e-5); }

// Snaps a moving position to the pixel grid, so sprites move a whole pixel at a time.
float2 pxSnap(float2 p) { return (floor(p * PX_ROWS) + 0.5) / PX_ROWS; }

half4 main(float2 fc) {
    float2 cell = pxCell(fc);
    float2 uv = pxUv(cell);
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    // Sky with a soft sun and two cloud puffs.
    float3 col = mix(mix(float3(0.45, 0.75, 0.95), S * 0.6 + 0.25, 0.25), float3(0.88, 0.96, 0.9), pxBand(uv.y * 1.4, 4.0, cell));
    float sd = length(uv - float2(asp * 0.15, 0.12));
    col = mix(col, float3(1.0, 0.96, 0.75), step(sd, 0.06));
    for (int i = 0; i < 2; i++) {
        float fi = float(i);
        float2 c = float2(fract(0.3 + fi * 0.5 + t * 0.006) * (asp + 0.4) - 0.2, 0.1 + fi * 0.08);
        float puff = step(length((uv - c) * float2(0.6, 1.3)), 0.04) + step(length((uv - c - float2(0.04, 0.012)) * float2(0.6, 1.3)), 0.032) + step(length((uv - c + float2(0.04, -0.01)) * float2(0.6, 1.3)), 0.028);
        col = mix(col, float3(1.0), step(0.5, puff));
    }
    // Back hedge and sunflowers.
    float hedge = 0.5 + 0.02 * sin(uv.x * 30.0) * sin(uv.x * 7.0);
    if (uv.y > hedge) col = mix(float3(0.18, 0.42, 0.2), mix(float3(0.28, 0.55, 0.25), A, 0.15), pxBand(vnoise(uv * 40.0), 2.0, cell));
    for (int i = 0; i < 4; i++) {
        float fi = float(i);
        float x = (fi + 0.7) / 4.3 * asp;
        float nod = 0.008 * sin(t * 0.7 + fi * 1.3);
        float2 head = float2(x + nod, 0.4 + 0.03 * hash11(fi));
        col = mix(col, float3(0.25, 0.5, 0.2), step(abs(uv.x - x - nod * (uv.y - 0.7) / (head.y - 0.7)), PX * 0.8) * step(head.y, uv.y) * step(uv.y, 0.7));
        float r = length(uv - head);
        float ang = atan(uv.y - head.y, uv.x - head.x);
        float petal = step(r, 0.032 + 0.008 * step(0.0, sin(ang * 12.0)));
        col = mix(col, mix(float3(1.0, 0.8, 0.15), S, 0.2), petal);
        col = mix(col, float3(0.4, 0.22, 0.1), step(r, 0.016));
    }
    // Soil bed.
    float soilY = 0.83;
    if (uv.y > soilY) col = mix(float3(0.42, 0.27, 0.16), float3(0.3, 0.18, 0.1), pxBand(hash12(cell) * 0.5 + (uv.y - soilY) * 4.0, 3.0, cell));
    // Vines on canes, each on its own 14 s growth cycle.
    for (int i = 0; i < 5; i++) {
        float fi = float(i);
        float x = (fi + 0.5) / 5.0 * asp;
        float caneTop = 0.42;
        // Cane.
        col = mix(col, float3(0.75, 0.66, 0.4), pxBox(uv, float2(x, (caneTop + soilY) * 0.5), float2(PX * 0.6, (soilY - caneTop) * 0.5)) * step(0.5, fract(uv.y * 30.0) + 0.3));
        float g = fract(t / 14.0 + fi * 0.21);
        float grow = smoothstep(0.0, 0.7, g);
        float fade = 1.0 - smoothstep(0.92, 1.0, g);
        float tipY = mix(soilY, caneTop + 0.02, grow);
        // The stem winding round the cane.
        float wind = 0.012 * sin(uv.y * 70.0 + fi);
        float stem = step(tipY, uv.y) * step(uv.y, soilY) * step(abs(uv.x - x - wind), PX * 0.9);
        col = mix(col, float3(0.2, 0.55, 0.2), stem * step(0.3, fade));
        // Leaves at the nodes behind the tip.
        for (int j = 0; j < 6; j++) {
            float fj = float(j);
            float ny = soilY - 0.06 - fj * 0.065;
            float side = mod(fj, 2.0) < 0.5 ? 1.0 : -1.0;
            float open = sat((ny - tipY) / 0.04) * fade;
            float2 lc = float2(x + side * (0.012 + 0.012 * open), ny - 0.006 * open);
            float2 q = (uv - lc) / max(open, 0.01);
            float leaf = step(length(q * float2(0.7, 1.4)), 0.016) * step(0.05, open);
            col = mix(col, mix(float3(0.3, 0.7, 0.25), float3(0.45, 0.85, 0.3), step(q.y, -0.003)), leaf);
        }
        // The flower at the top once it's grown.
        float bloom = smoothstep(0.7, 0.8, g) * fade;
        float2 fcn = float2(x + 0.012 * sin(caneTop * 70.0 + fi), caneTop + 0.015);
        float rr = length(uv - fcn);
        float an = atan(uv.y - fcn.y, uv.x - fcn.x) + t * 0.2;
        float pet = step(rr, 0.03 * bloom * (0.7 + 0.3 * step(0.0, sin(an * 5.0))));
        float3 fl = mix(A, float3(1.0, 0.5, 0.7), hash11(fi * 2.0) * 0.6);
        col = mix(col, fl, pet);
        col = mix(col, float3(1.0, 0.9, 0.3), step(rr, 0.009 * bloom));
    }
    // Butterflies.
    for (int i = 0; i < 3; i++) {
        float fi = float(i);
        float2 b = pxSnap(float2(fract(fi * 0.31 + t * 0.03) * asp, 0.55 + 0.12 * sin(t * 0.9 + fi * 2.0) + 0.02 * sin(t * 7.0 + fi)));
        float2 q = (uv - b) / PX;
        float flap = 0.4 + 0.6 * abs(sin(t * 10.0 + fi));
        float wing = step(length((abs(q) - float2(1.8 * flap, 0.9)) * float2(1.0 / max(flap, 0.3), 1.0)), 1.6);
        col = mix(col, mix(S, float3(1.0, 0.6, 0.2), fi * 0.4), wing);
        col = mix(col, float3(0.1), step(abs(q.x), 0.5) * step(abs(q.y), 1.8));
    }
    // Grass tiles at the front, swaying.
    float gy = 0.94;
    float gx = uv.x * 90.0;
    float bl = fract(gx);
    float hgt = 0.03 + 0.02 * hash11(floor(gx));
    float sw = 0.3 * sin(t * 1.5 + floor(gx) * 0.3);
    float yy = (gy - uv.y) / hgt;
    float blade = step(0.0, yy) * step(yy, 1.0) * step(abs(bl - 0.5 - sw * yy), 0.35 * (1.0 - yy) + 0.1);
    if (uv.y > gy) col = mix(float3(0.22, 0.48, 0.18), float3(0.16, 0.38, 0.14), pxBand(hash12(cell), 2.0, cell));
    col = mix(col, mix(float3(0.3, 0.62, 0.22), float3(0.5, 0.8, 0.3), yy), blade);

    col = pxQuant(col, 10.0, cell);
    return half4(finish(col, fc), 1.0);
}
