float pxLine(float2 p, float2 a, float2 b, float w) { return step(sdSegment(p, a, b), w * PX * 0.5 + 1e-5); }

// Snaps a moving position to the pixel grid, so sprites move a whole pixel at a time.
float2 pxSnap(float2 p) { return (floor(p * PX_ROWS) + 0.5) / PX_ROWS; }

half4 main(float2 fc) {
    float2 cell = pxCell(fc);
    float2 uv = pxUv(cell);
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float2 c = float2(asp * 0.5, 0.45);
    float2 p = uv - c;
    float r = length(p);
    float a = atan(p.y, p.x);

    // The void: violet bands swirling outwards, stars.
    float sw = fract(r * 3.0 - t * 0.08 + 0.15 * sin(a * 3.0 + t * 0.2));
    float3 col = mix(BG * 1.2 + S * 0.08, mix(BG, A, 0.25), pxBand(sw * (1.0 - r * 0.8), 4.0, cell) * 0.7);
    float st = step(0.985, hash12(cell)) * step(0.5, sin(t * 2.0 + hash12(cell + 3.0) * 30.0));
    col = mix(col, float3(1.0, 0.9, 1.0), st * step(0.25, r));

    // Thought waves rippling out.
    for (int i = 0; i < 3; i++) {
        float fi = float(i);
        float wr = fract(t * 0.15 + fi / 3.0) * 0.6;
        col = mix(col, mix(A, S, 0.5), step(abs(r - wr), PX * 0.8) * (1.0 - wr / 0.6) * step(0.5, fract(a * 8.0 / TAU + t * 0.2)));
    }
    // Two rune rings turning in opposite directions.
    for (int k = 0; k < 2; k++) {
        float fk = float(k);
        float rr = 0.2 + fk * 0.08;
        float n = 16.0 + fk * 8.0;
        float aa = a + (fk < 0.5 ? t * 0.25 : -t * 0.18);
        float seg = floor(aa / TAU * n);
        float sa = fract(aa / TAU * n) - 0.5;
        float2 q = float2(sa * TAU * rr / n, r - rr) / PX;      // in pixels round the ring
        float h = hash11(seg + fk * 40.0);
        float rune = 0.0;
        rune = max(rune, step(abs(q.x), 0.6) * step(abs(q.y), 2.6));
        rune = max(rune, step(abs(q.y - (h > 0.5 ? 2.0 : -2.0)), 0.6) * step(abs(q.x), 2.0));
        rune = max(rune, step(abs(q.x - (h > 0.3 ? 1.5 : -1.5)), 0.6) * step(abs(q.y), 1.0) * step(0.3, fract(h * 7.0)));
        col = mix(col, mix(S, float3(1.0), 0.3), rune * step(abs(q.x), 3.0));
        col = mix(col, A * 0.8, step(abs(r - rr - (fk < 0.5 ? 0.025 : -0.025)), PX * 0.5));
    }
    // The eye: almond outline, iris and pupil, blinking every 7 s.
    float bl = fract(t / 7.0);
    float open = 1.0 - smoothstep(0.9, 0.95, bl) + smoothstep(0.95, 1.0, bl);
    float2 e = p / float2(0.13, 0.07 * max(open, 0.05));
    float lid = length(float2(e.x, abs(e.y) + 0.6)) ;
    float almond = step(abs(e.y), (1.0 - e.x * e.x)) * step(abs(e.x), 1.0);
    float outline = step(abs(e.y), (1.0 - e.x * e.x) + 0.25 / max(open, 0.2)) * step(abs(e.x), 1.12) * (1.0 - almond);
    col = mix(col, float3(1.0, 0.95, 1.0) * 0.95, almond);
    float2 look = float2(0.02 * sin(t * 0.5), 0.008 * sin(t * 0.37));
    float ir = length(p - look);
    col = mix(col, mix(A, S, pxBand(sat(ir / 0.045), 2.0, cell)), almond * step(ir, 0.045));
    col = mix(col, float3(0.05, 0.0, 0.08), almond * step(ir, 0.018));
    col = mix(col, float3(1.0), almond * step(length(p - look - float2(-0.012, -0.012)), 0.007));
    col = mix(col, mix(A, float3(1.0), 0.4), outline);
    // Rays from the eye.
    col = mix(col, mix(A, float3(1.0), 0.5), step(0.97, cos(a * 12.0)) * step(0.16, r) * step(r, 0.19) * open);

    // Floating stones: slabs with a lit top, bobbing.
    for (int i = 0; i < 6; i++) {
        float fi = float(i);
        float side = mod(fi, 2.0) < 0.5 ? -1.0 : 1.0;
        float2 sp = float2(c.x + side * (0.42 + 0.22 * hash11(fi)) * asp / 1.78, 0.2 + 0.6 * hash11(fi * 3.0));
        sp.y += 0.015 * sin(t * 0.8 + fi * 1.7);
        sp = pxSnap(sp);
        float2 hw = float2(0.03 + 0.03 * hash11(fi * 5.0), 0.012);
        float slab = pxBox(uv, sp, hw);
        float topL = pxBox(uv, sp - float2(0.0, hw.y - PX), float2(hw.x, PX));
        float under = step(sp.y + hw.y, uv.y) * step(uv.y, sp.y + hw.y + 0.03) * step(abs(uv.x - sp.x), hw.x * (1.0 - (uv.y - sp.y - hw.y) / 0.03));
        col = mix(col, float3(0.32, 0.28, 0.4), max(slab, under));
        col = mix(col, float3(0.6, 0.55, 0.72), topL);
        // A pillar on some.
        float pil = step(0.5, hash11(fi * 11.0)) * pxBox(uv, sp - float2(0.0, hw.y + 0.04), float2(0.008, 0.04));
        col = mix(col, mix(float3(0.75, 0.7, 0.85), float3(0.55, 0.5, 0.68), step(sp.x, uv.x)), pil);
    }
    col = pxQuant(col, 10.0, cell);
    return half4(finish(col, fc), 1.0);
}
"""

    private const val PX_BLAZE = """
// Blaze · 32-bit (fire type): a volcano at night. The crater glows and every few seconds it erupts,
// throwing lava bombs in arcs that leave pixel trails; lava rivers crawl down its flanks, ash drifts
// across a smoky red sky, and a bubbling lava lake glows below black rocks rimmed with red light.
// Shared by the 32-bit creature-type scenes (px_*.agsl): a chunky pixel grid, an ordered dither and
// banded shading, so every scene reads as one 32-bit sprite picture. Shapes are evaluated at each
// pixel's centre with hard edges (no smoothing), colours are stepped through a few shades with a 4 x 4
// Bayer dither between them.

// The pixel a fragment belongs to, with PX_ROWS pixels on the screen's height.
const float PX_ROWS = 180.0;
float2 pxCell(float2 fc) { return floor(fc / uRes.y * PX_ROWS); }
// The centre of that pixel in screen heights (0..aspect across, 0..1 down).
float2 pxUv(float2 cell) { return (cell + 0.5) / PX_ROWS; }
// One pixel, in screen heights.
const float PX = 1.0 / 180.0;

// 4 x 4 ordered dither threshold for an integer cell, 0..1.
float bayer2(float2 p) { return 2.0 * p.x + 3.0 * p.y - 4.0 * p.x * p.y; }
float bayer4(float2 c) {
    float2 a = mod(c, 2.0);
    float2 b = mod(floor(c * 0.5), 2.0);
    return (4.0 * bayer2(a) + bayer2(b) + 0.5) / 16.0;
}

// v (0..1) stepped into n bands, dithered across each step.
float pxBand(float v, float n, float2 cell) {
    return clamp(floor(v * n + bayer4(cell)) / n, 0.0, 1.0);
}

// The colour stepped to a small palette (levels per channel), dithered.
float3 pxQuant(float3 c, float levels, float2 cell) {
    return floor(max(c, 0.0) * levels + bayer4(cell)) / levels;
}

// Four-shade ramp: dark, mid, light, highlight (v 0..1), banded and dithered.
float3 pxRamp(float v, float2 cell, float3 c0, float3 c1, float3 c2, float3 c3) {
    float b = pxBand(sat(v), 3.0, cell);
    return b < 0.17 ? c0 : (b < 0.5 ? c1 : (b < 0.84 ? c2 : c3));
}

// 1 inside a box of half size h around c (hard edge).
float pxBox(float2 p, float2 c, float2 h) {
    float2 d = abs(p - c) - h;
    return step(max(d.x, d.y), 0.0);
}

// 1 inside a circle (hard edge).
float pxDisc(float2 p, float2 c, float r) { return step(length(p - c), r); }

// 1 on a line from a to b that is w pixels thick (hard edge).
float pxLine(float2 p, float2 a, float2 b, float w) { return step(sdSegment(p, a, b), w * PX * 0.5 + 1e-5); }

// Snaps a moving position to the pixel grid, so sprites move a whole pixel at a time.
float2 pxSnap(float2 p) { return (floor(p * PX_ROWS) + 0.5) / PX_ROWS; }

half4 main(float2 fc) {
    float2 cell = pxCell(fc);
    float2 uv = pxUv(cell);
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float3 lava0 = mix(float3(0.55, 0.06, 0.02), A * 0.6, 0.3);
    float3 lava1 = mix(float3(1.0, 0.4, 0.05), A, 0.35);
    float3 lava2 = mix(float3(1.0, 0.85, 0.3), S, 0.3);

    float cyc = t / 6.0;
    float k = floor(cyc);
    float age = fract(cyc) * 6.0;
    float erupt = exp(-age * 1.2);

    // Sky: smoky red bands, darker up top, glowing more after an eruption.
    float3 col = mix(BG * 0.9, mix(float3(0.45, 0.08, 0.04), A * 0.35, 0.4), pxBand(uv.y * 1.2 + 0.15 * erupt, 5.0, cell));
    float smoke = fbm3(float2(uv.x * 2.0 - t * 0.02, uv.y * 3.0 + t * 0.05));
    col = mix(col, BG * 0.6 + float3(0.08, 0.02, 0.02), step(0.55, smoke) * step(uv.y, 0.55) * 0.8);
    // Volcano cone.
    float cx = asp * 0.5;
    float crater = 0.38;
    float slope = crater + abs(uv.x - cx) * 0.75 - 0.05 + 0.015 * sin(uv.x * 30.0);
    float onCone = step(slope, uv.y) * step(0.06, abs(uv.x - cx) + step(0.42, uv.y));
    if (onCone > 0.5) {
        float shade = pxBand(0.6 - (uv.x - cx) * 1.2, 3.0, cell);
        col = mix(float3(0.08, 0.05, 0.05), float3(0.22, 0.12, 0.1), shade);
        // Lava rivers down the flanks.
        for (int i = 0; i < 3; i++) {
            float fi = float(i);
            float side = fi - 1.0;
            float rx = cx + side * (0.06 + 0.5 * (uv.y - crater)) + 0.03 * sin(uv.y * 25.0 + fi * 3.0);
            float wdt = 0.008 + 0.006 * sin(uv.y * 40.0 - t * 2.0 + fi);
            float flow = vnoise(float2(uv.x * 40.0, uv.y * 30.0 - t * 2.5 + fi * 5.0));
            if (abs(uv.x - rx) < wdt && uv.y < crater + 0.35 + 0.1 * fi) col = flow > 0.6 ? lava2 : (flow > 0.3 ? lava1 : lava0);
        }
    }
    // The crater's glow.
    float2 cp = uv - float2(cx, crater + 0.01);
    col = mix(col, lava1, step(length(cp * float2(1.0, 2.5)), 0.05) * step(-0.005, cp.y));
    col = mix(col, lava2, step(length(cp * float2(1.0, 2.5)), 0.03) * step(-0.005, cp.y) * (0.5 + 0.5 * erupt));
    col += lava1 * 0.25 * pxBand(sat(1.0 - length(cp) * 5.0), 3.0, cell) * (0.4 + 0.8 * erupt);
    // Lava bombs: parabolas from the crater, with trails.
    for (int i = 0; i < 9; i++) {
        float fi = float(i);
        float vx = (hash11(k * 3.0 + fi) - 0.5) * 0.5;
        float vy = 0.35 + 0.25 * hash11(k * 5.0 + fi * 1.3);
        for (int j = 0; j < 4; j++) {
            float tt = age - float(j) * 0.04;
            if (tt < 0.0) continue;
            float2 bp = float2(cx + vx * tt, crater - vy * tt + 0.35 * tt * tt);
            bp = pxSnap(bp);
            float on = step(length(uv - bp), PX * (j == 0 ? 1.6 : 1.0));
            col = mix(col, j == 0 ? lava2 : (j < 2 ? lava1 : lava0), on * step(tt, 2.5));
        }
    }
    // Ash: grey pixels drifting.
    float2 ap = float2(uv.x + t * 0.03, uv.y - t * 0.015) * 50.0;
    col = mix(col, float3(0.5, 0.45, 0.45), step(0.985, hash12(floor(ap))) * step(abs(fract(ap.x) - 0.5), 0.3) * step(abs(fract(ap.y) - 0.5), 0.3));
    // The lava lake below, bubbling.
    float lakeY = 0.86;
    if (uv.y > lakeY) {
        float n = vnoise(float2(uv.x * 25.0 + t * 0.4, uv.y * 30.0 - t * 0.2)) + 0.4 * sin(uv.x * 40.0 + t * 1.5) * 0.3;
        col = n > 0.65 ? lava2 : (n > 0.35 ? lava1 : lava0);
        for (int i = 0; i < 5; i++) {
            float fi = float(i);
            float bt = fract(t * 0.4 + hash11(fi));
            float2 bc = pxSnap(float2(hash11(fi * 7.0) * asp, lakeY + 0.05 + 0.04 * hash11(fi * 3.0)));
            col = mix(col, lava2, step(abs(length(uv - bc) - bt * 0.02), PX * 0.6) * step(bt, 0.8));
        }
    }
    // Black rocks in front with a red rim from the lake.
    float rock = 0.0;
    for (int i = 0; i < 3; i++) {
        float fi = float(i);
        float2 rc = float2((fi * 0.45 + 0.1) * asp, 0.98);
        float d = length((uv - rc) * float2(0.8, 1.4)) - (0.1 + 0.05 * hash11(fi)) + 0.015 * vnoise(uv * 30.0);
        if (d < 0.0) col = d > -PX * 2.0 ? lava1 * 0.8 : float3(0.06, 0.04, 0.04);
    }
    col = pxQuant(col, 10.0, cell);
    return half4(finish(col, fc), 1.0);
}
"""

    private const val PX_PHANTOM = """
// Phantom · 32-bit (ghost type): a haunted manor on a hill under a big moon. Clouds slide across the
// moon, windows light up and go dark one by one, ghosts drift through the graveyard in see-through
// dither, bats flap past and bare trees claw at the sky.
// Shared by the 32-bit creature-type scenes (px_*.agsl): a chunky pixel grid, an ordered dither and
// banded shading, so every scene reads as one 32-bit sprite picture. Shapes are evaluated at each
// pixel's centre with hard edges (no smoothing), colours are stepped through a few shades with a 4 x 4
// Bayer dither between them.

// The pixel a fragment belongs to, with PX_ROWS pixels on the screen's height.
const float PX_ROWS = 180.0;
float2 pxCell(float2 fc) { return floor(fc / uRes.y * PX_ROWS); }
// The centre of that pixel in screen heights (0..aspect across, 0..1 down).
float2 pxUv(float2 cell) { return (cell + 0.5) / PX_ROWS; }
// One pixel, in screen heights.
const float PX = 1.0 / 180.0;

// 4 x 4 ordered dither threshold for an integer cell, 0..1.
float bayer2(float2 p) { return 2.0 * p.x + 3.0 * p.y - 4.0 * p.x * p.y; }
float bayer4(float2 c) {
    float2 a = mod(c, 2.0);
    float2 b = mod(floor(c * 0.5), 2.0);
    return (4.0 * bayer2(a) + bayer2(b) + 0.5) / 16.0;
}

// v (0..1) stepped into n bands, dithered across each step.
float pxBand(float v, float n, float2 cell) {
    return clamp(floor(v * n + bayer4(cell)) / n, 0.0, 1.0);
}

// The colour stepped to a small palette (levels per channel), dithered.
float3 pxQuant(float3 c, float levels, float2 cell) {
    return floor(max(c, 0.0) * levels + bayer4(cell)) / levels;
}

// Four-shade ramp: dark, mid, light, highlight (v 0..1), banded and dithered.
float3 pxRamp(float v, float2 cell, float3 c0, float3 c1, float3 c2, float3 c3) {
    float b = pxBand(sat(v), 3.0, cell);
    return b < 0.17 ? c0 : (b < 0.5 ? c1 : (b < 0.84 ? c2 : c3));
}

// 1 inside a box of half size h around c (hard edge).
float pxBox(float2 p, float2 c, float2 h) {
    float2 d = abs(p - c) - h;
    return step(max(d.x, d.y), 0.0);
}

// 1 inside a circle (hard edge).
float pxDisc(float2 p, float2 c, float r) { return step(length(p - c), r); }

// 1 on a line from a to b that is w pixels thick (hard edge).
float pxLine(float2 p, float2 a, float2 b, float w) { return step(sdSegment(p, a, b), w * PX * 0.5 + 1e-5); }

// Snaps a moving position to the pixel grid, so sprites move a whole pixel at a time.
float2 pxSnap(float2 p) { return (floor(p * PX_ROWS) + 0.5) / PX_ROWS; }

float ghostSprite(float2 q, float t) {
    // q in pixels, the ghost about 10 x 12 pixels.
    float top = step(length(q - float2(0.0, -2.0)), 5.0) * step(q.y, -2.0);
    float body = step(abs(q.x), 5.0) * step(-2.0, q.y) * step(q.y, 5.0 + 1.5 * sin(q.x * 1.2 + t * 6.0));
    return max(top, body);
}

half4 main(float2 fc) {
    float2 cell = pxCell(fc);
    float2 uv = pxUv(cell);
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    // Night sky: violet bands, stars, a big moon.
    float3 col = mix(BG * 0.8, mix(BG * 1.8, A * 0.35, 0.4), pxBand(uv.y * 1.4, 4.0, cell));
    col = mix(col, float3(0.9, 0.9, 1.0), step(0.992, hash12(cell)) * step(uv.y, 0.5));
    float2 moon = float2(asp * 0.7, 0.24);
    float md = length(uv - moon);
    if (md < 0.13) {
        col = mix(float3(0.95, 0.95, 0.85), mix(float3(0.8, 0.8, 0.75), S, 0.2), step(0.62, vnoise((uv - moon) * 30.0)));
    } else col += mix(A, float3(0.8), 0.5) * 0.12 * pxBand(sat(0.25 - md) * 4.0, 2.0, cell);
    // Clouds passing over.
    float cl = fbm3(float2(uv.x * 2.5 - t * 0.03, uv.y * 6.0));
    if (cl > 0.6 && uv.y < 0.45) col = mix(BG * 2.0 + S * 0.1, float3(0.55, 0.52, 0.65), step(0.68, cl));
    // Hill.
    float hill = 0.68 - 0.12 * exp(-sqf((uv.x - asp * 0.42) * 2.2)) + 0.01 * sin(uv.x * 20.0);
    if (uv.y > hill) col = float3(0.07, 0.06, 0.1);
    // The manor: a block with a tower and pointed roofs.
    float mx = asp * 0.42;
    float base = hill + 0.01;
    float house = pxBox(uv, float2(mx, base - 0.08), float2(0.16, 0.08));
    float roof = step(base - 0.16 - (0.17 - abs(uv.x - mx)) * 0.5, uv.y) * step(uv.y, base - 0.16) * step(abs(uv.x - mx), 0.17);
    float tower = pxBox(uv, float2(mx + 0.1, base - 0.2), float2(0.035, 0.12));
    float spire = step(base - 0.32 - (0.04 - abs(uv.x - mx - 0.1)) * 2.8, uv.y) * step(uv.y, base - 0.32) * step(abs(uv.x - mx - 0.1), 0.04);
    float m = max(max(house, roof), max(tower, spire));
    col = mix(col, float3(0.1, 0.08, 0.14), m);
    // Windows: lit at random, changing every few seconds.
    float2 wg = (uv - float2(mx - 0.14, base - 0.14)) / float2(0.04, 0.05);
    float2 wi = floor(wg);
    float2 wf = fract(wg);
    float inWin = step(0.0, wi.x) * step(wi.x, 6.0) * step(0.0, wi.y) * step(wi.y, 1.0) * step(abs(wf.x - 0.5), 0.22) * step(abs(wf.y - 0.5), 0.3);
    float litW = step(0.55, hash12(wi + floor(t / 3.0 + hash12(wi) * 3.0)));
    col = mix(col, litW > 0.5 ? mix(float3(1.0, 0.85, 0.4), A, 0.3) : float3(0.05, 0.05, 0.1), inWin * house);
    float tw = pxBox(uv, float2(mx + 0.1, base - 0.26), float2(0.01, 0.015)) * step(0.5, sin(t * 1.3));
    col = mix(col, mix(float3(0.6, 1.0, 0.8), S, 0.5), tw);
    // Bare trees.
    for (int i = 0; i < 2; i++) {
        float fi = float(i);
        float2 tb = float2(fi < 0.5 ? asp * 0.12 : asp * 0.9, 0.85);
        float tr = pxLine(uv, tb, tb - float2(0.0, 0.25), 3.0);
        tr = max(tr, pxLine(uv, tb - float2(0.0, 0.15), tb - float2(0.08, 0.25), 2.0));
        tr = max(tr, pxLine(uv, tb - float2(0.0, 0.2), tb - float2(-0.07, 0.3), 2.0));
        tr = max(tr, pxLine(uv, tb - float2(0.04, 0.2), tb - float2(0.09, 0.22), 1.0));
        tr = max(tr, pxLine(uv, tb - float2(-0.035, 0.25), tb - float2(-0.02, 0.33), 1.0));
        col = mix(col, float3(0.04, 0.03, 0.06), tr);
    }
    // Graveyard: crosses and stones.
    for (int i = 0; i < 6; i++) {
        float fi = float(i);
        float2 g = pxSnap(float2((0.08 + fi * 0.17) * asp, 0.86 + 0.03 * hash11(fi)));
        float stone = mod(fi, 2.0) < 0.5 ? max(pxBox(uv, g, float2(PX * 0.6, 0.03)), pxBox(uv, g - float2(0.0, 0.012), float2(0.012, PX * 0.6)))
                                       : max(pxBox(uv, g + float2(0.0, 0.006), float2(0.014, 0.024)), pxDisc(uv, g - float2(0.0, 0.018), 0.014));
        col = mix(col, float3(0.32, 0.3, 0.38), stone);
    }
    if (uv.y > 0.93) col = float3(0.05, 0.05, 0.08);
    // Ghosts drifting, see-through (every other pixel).
    for (int i = 0; i < 4; i++) {
        float fi = float(i);
        float2 g = float2(fract(fi * 0.29 + t * (0.02 + 0.006 * fi)) * (asp + 0.3) - 0.15, 0.55 + 0.2 * hash11(fi) + 0.03 * sin(t * 1.3 + fi));
        g = pxSnap(g);
        float2 q = (uv - g) / PX;
        float gh = ghostSprite(q, t + fi);
        float see = mod(cell.x + cell.y, 2.0) < 0.5 ? 1.0 : 0.55;
        col = mix(col, mix(float3(0.85, 1.0, 0.95), S, 0.25) * see, gh * 0.85);
