    private const val PX_FROST = """
// Frost · 32-bit (ice type): inside an ice cave looking out. Blue crystal walls frame the mouth of the
// cave; through it a frozen lake lies under green aurora curtains; icicles drip at the top, crystals
// glint one after another, and snow blows in across the opening.
// Shared by the 32-bit creature-type scenes (px_*.agsl): a chunky pixel grid, an ordered dither and
// banded shading, so every scene reads as one 32-bit sprite picture. Shapes are evaluated at each
// pixel's centre with hard edges (no smoothing), colours are stepped through a few shades with a 4 x 4
// Bayer dither between them.

// The pixel a fragment belongs to, with PX_ROWS pixels on the screen's height.
const float PX_ROWS = 180.0;
float2 pxCell(float2 fc) { return floor(fc / uRes.y * PX_ROWS); }
// The centre of that pixel in screen heights (0..aspect across, 0..1 down).
float2 pxUv(float2 cell) { return (cell + 0.5) / PX_ROWS; }
// One pixel, in screen heights.
const float PX = 1.0 / 180.0;

// 4 x 4 ordered dither threshold for an integer cell, 0..1.
float bayer2(float2 p) { return 2.0 * p.x + 3.0 * p.y - 4.0 * p.x * p.y; }
float bayer4(float2 c) {
    float2 a = mod(c, 2.0);
    float2 b = mod(floor(c * 0.5), 2.0);
    return (4.0 * bayer2(a) + bayer2(b) + 0.5) / 16.0;
}

// v (0..1) stepped into n bands, dithered across each step.
float pxBand(float v, float n, float2 cell) {
    return clamp(floor(v * n + bayer4(cell)) / n, 0.0, 1.0);
}

// The colour stepped to a small palette (levels per channel), dithered.
float3 pxQuant(float3 c, float levels, float2 cell) {
    return floor(max(c, 0.0) * levels + bayer4(cell)) / levels;
}

// Four-shade ramp: dark, mid, light, highlight (v 0..1), banded and dithered.
float3 pxRamp(float v, float2 cell, float3 c0, float3 c1, float3 c2, float3 c3) {
    float b = pxBand(sat(v), 3.0, cell);
    return b < 0.17 ? c0 : (b < 0.5 ? c1 : (b < 0.84 ? c2 : c3));
}

// 1 inside a box of half size h around c (hard edge).
float pxBox(float2 p, float2 c, float2 h) {
    float2 d = abs(p - c) - h;
    return step(max(d.x, d.y), 0.0);
}

// 1 inside a circle (hard edge).
float pxDisc(float2 p, float2 c, float r) { return step(length(p - c), r); }

// 1 on a line from a to b that is w pixels thick (hard edge).
float pxLine(float2 p, float2 a, float2 b, float w) { return step(sdSegment(p, a, b), w * PX * 0.5 + 1e-5); }

// Snaps a moving position to the pixel grid, so sprites move a whole pixel at a time.
float2 pxSnap(float2 p) { return (floor(p * PX_ROWS) + 0.5) / PX_ROWS; }

half4 main(float2 fc) {
    float2 cell = pxCell(fc);
    float2 uv = pxUv(cell);
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float2 c = float2(asp * 0.5, 0.52);

    // Outside: night sky, aurora, mountains, a frozen lake.
    float3 col = mix(BG * 0.9, mix(BG * 2.0, S * 0.3, 0.4), pxBand(uv.y * 1.6, 4.0, cell));
    col = mix(col, float3(0.9, 0.95, 1.0), step(0.99, hash12(cell)) * step(uv.y, 0.45));
    for (int i = 0; i < 2; i++) {
        float fi = float(i);
        float ax = uv.x * (3.0 + fi) + t * (0.05 + 0.03 * fi);
        float cy = 0.18 + fi * 0.08 + 0.05 * sin(ax) + 0.025 * sin(ax * 2.7 + t * 0.2);
        float band = sat(1.0 - (uv.y - cy) / 0.12) * step(cy, uv.y) * (0.5 + 0.5 * sin(uv.x * 40.0 + t * 0.8 + fi));
        col = mix(col, mix(float3(0.3, 1.0, 0.6), A, 0.35 + 0.3 * fi), pxBand(band, 3.0, cell) * 0.75);
    }
    float mtn = 0.5 - 0.1 * abs(fract(uv.x * 2.2 + 0.3) - 0.5) * 2.0 - 0.03 * sin(uv.x * 11.0);
    if (uv.y > mtn) col = mix(float3(0.75, 0.85, 0.95), float3(0.35, 0.45, 0.6), pxBand((uv.y - mtn) * 8.0 + step(0.5, fract(uv.x * 2.2 + 0.3)) * 0.4, 3.0, cell));
    if (uv.y > 0.58) {
        col = mix(mix(S, float3(0.6, 0.8, 0.95), 0.6), float3(0.3, 0.45, 0.65), pxBand((uv.y - 0.58) * 3.0, 3.0, cell));
        // The aurora reflected, and cracks in the ice.
        col += mix(float3(0.3, 1.0, 0.6), A, 0.4) * 0.15 * step(0.6, sin(uv.x * 40.0 + t * 0.8)) * step(uv.y, 0.66);
        col = mix(col, float3(0.9, 0.97, 1.0), step(abs(sin(uv.x * 9.0 + uv.y * 30.0) * 0.02 - (uv.y - 0.72)), PX * 0.5) * 0.8);
    }
    // The cave mouth: everything outside the arch is ice wall.
    float2 q = (uv - c) / float2(asp * 0.36, 0.42);
    float arch = length(q * float2(1.0, q.y < 0.0 ? 1.0 : 0.6)) + 0.06 * vnoise(uv * 25.0) + 0.04 * sin(atan(q.y, q.x) * 9.0);
    if (arch > 1.0) {
        // Crystal facets: a cheap Voronoi, each cell one flat shade.
        float2 g = uv * 9.0;
        float2 gi = floor(g);
        float best = 9.0;
        float2 id = gi;
        for (int yy = -1; yy <= 1; yy++) {
            for (int xx = -1; xx <= 1; xx++) {
                float2 o = gi + float2(float(xx), float(yy));
                float2 pnt = o + hash22(o);
                float dd = length(g - pnt);
                if (dd < best) { best = dd; id = o; }
            }
        }
        float facet = hash12(id);
        float3 ice0 = mix(float3(0.05, 0.15, 0.3), BG, 0.3);
        float3 ice1 = mix(float3(0.2, 0.45, 0.7), S, 0.3);
        float3 ice2 = mix(float3(0.55, 0.8, 0.95), S, 0.2);
        col = pxRamp(facet * 0.55 + sat(1.6 - arch) * 0.45, cell, ice0, ice1, ice2, float3(0.9, 0.98, 1.0));
        // The rim lit from outside.
        col = mix(col, float3(0.85, 0.97, 1.0), step(arch, 1.04));
    }
    // Icicles along the top, with drips.
    float ix = uv.x * 30.0;
    float il = (0.06 + 0.08 * hash11(floor(ix))) * (1.0 - abs(fract(ix) - 0.5) * 2.0);
    if (uv.y < il) col = mix(float3(0.7, 0.9, 1.0), float3(0.95, 1.0, 1.0), step(fract(ix), 0.35));
    float dripT = fract(t * 0.4 + hash11(floor(ix) * 3.0));
    float2 dp = pxSnap(float2((floor(ix) + 0.5) / 30.0, (0.06 + 0.08 * hash11(floor(ix))) + dripT * dripT * 0.8));
    col = mix(col, float3(0.85, 0.97, 1.0), step(length(uv - dp), PX * 0.8) * step(0.7, hash11(floor(ix) * 5.0)));
    // Crystal clusters on the cave floor, glinting in turn.
    for (int i = 0; i < 5; i++) {
        float fi = float(i);
        float2 cb = float2((fi < 2.5 ? 0.05 + fi * 0.08 : asp - 0.05 - (fi - 3.0) * 0.09), 0.98);
        for (int j = 0; j < 3; j++) {
            float fj = float(j);
            float2 dir = normalize(float2((fj - 1.0) * 0.5, -1.0));
            float len = 0.08 + 0.06 * hash11(fi * 3.0 + fj);
            float2 rel = uv - cb;
            float along = dot(rel, dir);
            float across = dot(rel, float2(-dir.y, dir.x));
            float w = 0.018 * (1.0 - along / len);
            float shard = step(0.0, along) * step(along, len) * step(abs(across), w);
            float lit = step(0.0, across);
            col = mix(col, mix(mix(float3(0.3, 0.6, 0.9), A, 0.3), float3(0.8, 0.95, 1.0), lit), shard);
            float gl = step(0.92, fract(t * 0.3 + fi * 0.37 + fj * 0.13));
            float2 tip = cb + dir * len;
            col = mix(col, float3(1.0), gl * (step(abs(uv.x - tip.x), PX * 0.5) * step(abs(uv.y - tip.y), PX * 3.0) + step(abs(uv.y - tip.y), PX * 0.5) * step(abs(uv.x - tip.x), PX * 3.0)));
        }
    }
    // Snow blowing in.
    for (int l = 0; l < 2; l++) {
        float fl = float(l);
        float2 sp = float2(uv.x - t * (0.08 + 0.05 * fl), uv.y - t * (0.04 + 0.03 * fl) + 0.02 * sin(uv.x * 10.0 + t)) * (35.0 - fl * 12.0);
        float2 si = floor(sp);
        float2 sf = fract(sp) - 0.5;
        col = mix(col, float3(1.0), step(0.93, hash12(si + fl * 50.0)) * step(max(abs(sf.x), abs(sf.y)), 0.18 + fl * 0.1));
    }
    col = pxQuant(col, 10.0, cell);
    return half4(finish(col, fc), 1.0);
}
"""

    private const val PX_TERRA = """
// Terra · 32-bit (ground type): a desert canyon at the golden hour, scrolling past in parallax. Mesas
// on the horizon, banded dunes, cacti and a bleached skull; heat shimmer above the sand and every so
// often a dust devil spins across, kicking up pixel grit.
// Shared by the 32-bit creature-type scenes (px_*.agsl): a chunky pixel grid, an ordered dither and
// banded shading, so every scene reads as one 32-bit sprite picture. Shapes are evaluated at each
// pixel's centre with hard edges (no smoothing), colours are stepped through a few shades with a 4 x 4
// Bayer dither between them.

// The pixel a fragment belongs to, with PX_ROWS pixels on the screen's height.
const float PX_ROWS = 180.0;
float2 pxCell(float2 fc) { return floor(fc / uRes.y * PX_ROWS); }
// The centre of that pixel in screen heights (0..aspect across, 0..1 down).
float2 pxUv(float2 cell) { return (cell + 0.5) / PX_ROWS; }
// One pixel, in screen heights.
const float PX = 1.0 / 180.0;

// 4 x 4 ordered dither threshold for an integer cell, 0..1.
float bayer2(float2 p) { return 2.0 * p.x + 3.0 * p.y - 4.0 * p.x * p.y; }
float bayer4(float2 c) {
    float2 a = mod(c, 2.0);
    float2 b = mod(floor(c * 0.5), 2.0);
    return (4.0 * bayer2(a) + bayer2(b) + 0.5) / 16.0;
}

// v (0..1) stepped into n bands, dithered across each step.
float pxBand(float v, float n, float2 cell) {
    return clamp(floor(v * n + bayer4(cell)) / n, 0.0, 1.0);
}

// The colour stepped to a small palette (levels per channel), dithered.
float3 pxQuant(float3 c, float levels, float2 cell) {
    return floor(max(c, 0.0) * levels + bayer4(cell)) / levels;
}

// Four-shade ramp: dark, mid, light, highlight (v 0..1), banded and dithered.
float3 pxRamp(float v, float2 cell, float3 c0, float3 c1, float3 c2, float3 c3) {
    float b = pxBand(sat(v), 3.0, cell);
    return b < 0.17 ? c0 : (b < 0.5 ? c1 : (b < 0.84 ? c2 : c3));
}

// 1 inside a box of half size h around c (hard edge).
float pxBox(float2 p, float2 c, float2 h) {
    float2 d = abs(p - c) - h;
    return step(max(d.x, d.y), 0.0);
}

// 1 inside a circle (hard edge).
float pxDisc(float2 p, float2 c, float r) { return step(length(p - c), r); }

// 1 on a line from a to b that is w pixels thick (hard edge).
float pxLine(float2 p, float2 a, float2 b, float w) { return step(sdSegment(p, a, b), w * PX * 0.5 + 1e-5); }

// Snaps a moving position to the pixel grid, so sprites move a whole pixel at a time.
float2 pxSnap(float2 p) { return (floor(p * PX_ROWS) + 0.5) / PX_ROWS; }

half4 main(float2 fc) {
    float2 cell = pxCell(fc);
    float2 uv = pxUv(cell);
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    // Sky: warm bands, a low sun with heat shimmer under it.
    float3 col = mix(mix(float3(0.95, 0.55, 0.3), S, 0.3), mix(float3(1.0, 0.85, 0.55), A, 0.25), pxBand(uv.y * 1.8, 5.0, cell));
    float2 sun = float2(asp * 0.3, 0.32);
    float sd = length(uv - sun);
    col = mix(col, float3(1.0, 0.95, 0.75), step(sd, 0.07));
    col = mix(col, mix(float3(1.0, 0.75, 0.4), A, 0.3), step(sd, 0.1) * step(0.07, sd) * step(0.5, fract(uv.y * 45.0)));
    // Mesas far away (slow), then the canyon walls (faster).
    float x1 = uv.x + t * 0.01;
    float mesa = 0.42 - 0.08 * step(0.45, fract(x1 * 0.9)) * step(fract(x1 * 0.9), 0.75) - 0.05 * step(0.1, fract(x1 * 1.7 + 0.3)) * step(fract(x1 * 1.7 + 0.3), 0.3);
    float shim = step(0.38, uv.y) * step(uv.y, 0.46) * sin(uv.y * 400.0 + t * 8.0) * 0.004;
    if (uv.y > mesa + shim) col = mix(mix(float3(0.75, 0.4, 0.3), S, 0.2), float3(0.85, 0.55, 0.4), step(0.5, fract((uv.y - mesa) * 30.0)) * 0.4);
    float x2 = uv.x + t * 0.025;
    float wall = 0.52 - 0.12 * smoothstep(0.3, 0.32, fract(x2 * 0.6)) * (1.0 - smoothstep(0.6, 0.62, fract(x2 * 0.6)));
    if (uv.y > wall) {
        float strata = floor((uv.y - wall) * 40.0 + 0.6 * sin(x2 * 8.0));
        col = mix(float3(0.6, 0.3, 0.18), mix(float3(0.8, 0.45, 0.25), A, 0.2), step(0.5, fract(strata * 0.5)));
        col *= 0.8 + 0.2 * step(0.0, sin(x2 * 30.0));
    }
    // Dunes in front (fastest), banded light and shade.
    float x3 = uv.x + t * 0.06;
    float dune = 0.66 + 0.05 * sin(x3 * 5.0) + 0.02 * sin(x3 * 13.0 + 1.0);
    if (uv.y > dune) {
        float slopeLit = cos(x3 * 5.0) * 0.5 + 0.5;
        col = pxRamp(slopeLit * 0.8 + 0.1 - (uv.y - dune) * 0.6, cell, float3(0.6, 0.4, 0.2), float3(0.8, 0.58, 0.3), mix(float3(0.95, 0.75, 0.42), A, 0.15), float3(1.0, 0.88, 0.6));
        // Ripples.
        col *= 1.0 - 0.12 * step(0.8, fract((uv.y - dune) * 60.0 + sin(x3 * 20.0) * 2.0));
    }
    // Cacti and a skull, riding with the dunes.
    for (int i = 0; i < 3; i++) {
        float fi = float(i);
        float cx = fract((fi * 0.37 + 0.1) - t * 0.06 / (asp + 0.4) * 1.0) * (asp + 0.4) - 0.2;
        cx = (floor(cx * PX_ROWS) + 0.5) / PX_ROWS;
        float gy = 0.66 + 0.05 * sin((cx + t * 0.06) * 5.0) + 0.02 * sin((cx + t * 0.06) * 13.0 + 1.0) + 0.01;
        float2 q = uv - float2(cx, gy);
        float trunk = pxBox(q, float2(0.0, -0.07), float2(0.009, 0.07));
        float arm1 = pxBox(q, float2(-0.022, -0.08), float2(0.006, 0.025)) + pxBox(q, float2(-0.012, -0.058), float2(0.012, 0.005));
        float arm2 = pxBox(q, float2(0.022, -0.1), float2(0.006, 0.02)) + pxBox(q, float2(0.012, -0.082), float2(0.012, 0.005));
        float cac = sat(trunk + arm1 + arm2);
        col = mix(col, mix(float3(0.2, 0.5, 0.25), float3(0.35, 0.65, 0.3), step(0.0, q.x)), cac);
        col = mix(col, float3(0.9, 0.95, 0.7), cac * step(0.7, fract(q.y * 120.0)) * step(abs(q.x), 0.004));
    }
    float sx = fract(0.75 - t * 0.06 / (asp + 0.4)) * (asp + 0.4) - 0.2;
    float2 sk = uv - float2(sx, 0.9);
    col = mix(col, float3(0.95, 0.92, 0.85), step(length(sk * float2(1.0, 1.3)), 0.018) + pxBox(sk, float2(0.0, 0.014), float2(0.01, 0.006)));
    col = mix(col, float3(0.25, 0.15, 0.1), step(length(sk - float2(-0.007, -0.002)), 0.005) + step(length(sk - float2(0.007, -0.002)), 0.005));
    // A dust devil crossing every 12 s.
    float dt = fract(t / 12.0);
    float dx = mix(-0.2, asp + 0.2, dt);
    float2 dq = uv - float2(dx + 0.02 * sin(uv.y * 30.0 + t * 6.0), 0.0);
    float funnel = step(abs(dq.x), 0.01 + (0.75 - uv.y) * 0.18) * step(0.45, uv.y) * step(uv.y, 0.78);
    float swirl = step(0.5, fract(uv.y * 40.0 + dq.x * 30.0 - t * 5.0));
    col = mix(col, mix(float3(0.85, 0.65, 0.4), float3(0.7, 0.5, 0.3), swirl), funnel * 0.8 * step(0.4, hash12(cell + floor(t * 10.0))));
    // Grit.
    float2 gp = float2(uv.x + t * 0.4, uv.y + 0.05 * sin(uv.x * 5.0 + t)) * float2(80.0, 60.0);
    col = mix(col, float3(0.95, 0.8, 0.55), step(0.992, hash12(floor(gp))) * step(0.6, uv.y));
    col = pxQuant(col, 10.0, cell);
    return half4(finish(col, fc), 1.0);
}
"""

