    for (int i = 0; i < 4; i++) {
        float fi = float(i);
        float bx = (fi + 0.3 + 0.4 * hash11(fi)) / 4.0 * asp;
        float lean = (hash11(fi * 3.0) - 0.5) * 0.15;
        float y0 = 0.62;
        float h = 0.4 + 0.15 * hash11(fi * 5.0);
        float f = sat((y0 - uv.y) / h);
        float trunk = step(abs(uv.x - bx - lean * f - 0.01 * sin(f * 9.0)), 0.012 * (1.0 - f) + PX) * step(y0 - h, uv.y) * step(uv.y, y0);
        float br = pxLine(uv, float2(bx + lean * 0.6, y0 - h * 0.6), float2(bx + lean * 0.6 + 0.08, y0 - h * 0.8), 2.0)
                 + pxLine(uv, float2(bx + lean * 0.75, y0 - h * 0.75), float2(bx + lean * 0.75 - 0.06, y0 - h * 0.95), 1.0);
        col = mix(col, mix(float3(0.12, 0.08, 0.14), BG, 0.3) * (1.0 - 0.3 * fi / 4.0), sat(trunk + br));
    }
    // Mist band.
    float mist = fbm3(float2(uv.x * 3.0 + t * 0.03, uv.y * 8.0));
    col = mix(col, mix(goo1, goo2, 0.3) * 0.7, step(0.58, mist) * step(0.45, uv.y) * step(uv.y, 0.65) * step(0.5, mod(cell.x + cell.y, 2.0)) * 0.5);
    // The bank.
    float bank = 0.62 + 0.02 * sin(uv.x * 12.0);
    if (uv.y > bank) col = mix(float3(0.14, 0.1, 0.12), float3(0.2, 0.16, 0.14), pxBand(vnoise(uv * 50.0), 2.0, cell));
    // The pool: glowing, swirling.
    float2 pc = float2(asp * 0.5, 0.82);
    float2 pq = (uv - pc) / float2(asp * 0.38, 0.12);
    float pd = length(pq);
    if (pd < 1.0) {
        float sw = vnoise(float2(atan(pq.y, pq.x) * 2.0 + t * 0.3, pd * 5.0 - t * 0.5));
        col = pxRamp(sw * 0.7 + (1.0 - pd) * 0.4, cell, goo0, goo1, mix(goo1, goo2, 0.5), goo2);
        col = mix(col, mix(goo1, goo2, 0.5), step(0.94, pd) * 0.6);
        // Bubbles popping: a dome, then a ring.
        for (int i = 0; i < 6; i++) {
            float fi = float(i);
            float bt = fract(t * 0.35 + hash11(fi * 1.7));
            float2 bc = pxSnap(pc + float2((hash11(fi * 5.0) - 0.5) * asp * 0.5, (hash11(fi * 3.0) - 0.5) * 0.12));
            float r = length((uv - bc) * float2(1.0, 1.8));
            float dome = step(r, 0.02 * smoothstep(0.0, 0.6, bt)) * step(bt, 0.6);
            float ring = step(abs(r - (bt - 0.6) * 0.12), PX * 0.7) * step(0.6, bt);
            col = mix(col, goo2, dome);
            col = mix(col, float3(1.0), dome * step(length(uv - bc + float2(0.006, 0.006)), PX * 1.2));
            col = mix(col, goo2, ring * (1.0 - bt));
        }
    }
    // Fumes rising from the pool.
    float fume = fbm3(float2(uv.x * 6.0, uv.y * 4.0 + t * 0.4));
    col = mix(col, mix(goo1, goo2, 0.5), step(0.62, fume) * step(0.45, uv.y) * step(uv.y, 0.72) * step(abs(uv.x - pc.x), asp * 0.3) * 0.5 * step(0.5, mod(cell.x + cell.y, 2.0)));
    // Glowing mushrooms on the bank.
    for (int i = 0; i < 5; i++) {
        float fi = float(i);
        float side = fi < 2.5 ? 0.1 + fi * 0.09 : asp - 0.1 - (fi - 3.0) * 0.1;
        float2 m = pxSnap(float2(side, 0.95 - 0.02 * hash11(fi)));
        float sz = 0.025 + 0.015 * hash11(fi * 7.0);
        float2 q = uv - m;
        float cap = step(length(q * float2(1.0, 1.6) + float2(0.0, sz * 1.1)), sz) * step(q.y, -sz * 0.45);
        float stem = pxBox(q, float2(0.0, -sz * 0.25), float2(sz * 0.3, sz * 0.3));
        float pulse = 0.6 + 0.4 * sin(t * 2.0 + fi);
        col = mix(col, float3(0.85, 0.8, 0.75), stem);
        col = mix(col, mix(goo1, goo2, step(0.5, hash11(fi * 11.0))) * (0.7 + 0.5 * pulse), cap);
        col = mix(col, float3(1.0), cap * step(0.82, vnoise(q * 300.0 + fi)));
        col += goo2 * 0.15 * pulse * step(length(q + float2(0.0, sz)), sz * 2.5) * (1.0 - cap) * step(0.5, mod(cell.x + cell.y, 2.0));
    }
    // Fireflies.
    for (int i = 0; i < 8; i++) {
        float fi = float(i);
        float2 f = pxSnap(float2(fract(hash11(fi) + t * 0.01 * (fi + 1.0) * 0.4) * asp, 0.35 + 0.3 * hash11(fi * 2.0) + 0.04 * sin(t * 0.9 + fi * 2.0)));
        float bl = step(0.3, sin(t * 2.5 + fi * 1.9));
        col = mix(col, goo2 + 0.2, step(length(uv - f), PX * 0.7) * bl);
        col = mix(col, mix(col, goo2, 0.5), step(length(uv - f), PX * 2.0) * bl * step(0.5, mod(cell.x + cell.y, 2.0)));
    }
    col = pxQuant(col, 10.0, cell);
    return half4(finish(col, fc), 1.0);
}
"""

    private const val PX_MEADOW = """
// Meadow · 32-bit (normal type): a hilltop village on a lazy afternoon. Cottages with smoking chimneys
// sit on rolling tiled hills, washing flaps on a line, a path winds down past a fence, clouds sail
// over and birds cross the sky.
// Shared by the 32-bit creature-type scenes (px_*.agsl): a chunky pixel grid, an ordered dither and
// banded shading, so every scene reads as one 32-bit sprite picture. Shapes are evaluated at each
// pixel's centre with hard edges (no smoothing), colours are stepped through a few shades with a 4 x 4
// Bayer dither between them.

// The pixel a fragment belongs to, with PX_ROWS pixels on the screen's height.
const float PX_ROWS = 180.0;
float2 pxCell(float2 fc) { return floor(fc / uRes.y * PX_ROWS); }
// The centre of that pixel in screen heights (0..aspect across, 0..1 down).
float2 pxUv(float2 cell) { return (cell + 0.5) / PX_ROWS; }
// One pixel, in screen heights.
const float PX = 1.0 / 180.0;

// 4 x 4 ordered dither threshold for an integer cell, 0..1.
float bayer2(float2 p) { return 2.0 * p.x + 3.0 * p.y - 4.0 * p.x * p.y; }
float bayer4(float2 c) {
    float2 a = mod(c, 2.0);
    float2 b = mod(floor(c * 0.5), 2.0);
    return (4.0 * bayer2(a) + bayer2(b) + 0.5) / 16.0;
}

// v (0..1) stepped into n bands, dithered across each step.
float pxBand(float v, float n, float2 cell) {
    return clamp(floor(v * n + bayer4(cell)) / n, 0.0, 1.0);
}

// The colour stepped to a small palette (levels per channel), dithered.
float3 pxQuant(float3 c, float levels, float2 cell) {
    return floor(max(c, 0.0) * levels + bayer4(cell)) / levels;
}

// Four-shade ramp: dark, mid, light, highlight (v 0..1), banded and dithered.
float3 pxRamp(float v, float2 cell, float3 c0, float3 c1, float3 c2, float3 c3) {
    float b = pxBand(sat(v), 3.0, cell);
    return b < 0.17 ? c0 : (b < 0.5 ? c1 : (b < 0.84 ? c2 : c3));
}

// 1 inside a box of half size h around c (hard edge).
float pxBox(float2 p, float2 c, float2 h) {
    float2 d = abs(p - c) - h;
    return step(max(d.x, d.y), 0.0);
}

// 1 inside a circle (hard edge).
float pxDisc(float2 p, float2 c, float r) { return step(length(p - c), r); }

// 1 on a line from a to b that is w pixels thick (hard edge).
float pxLine(float2 p, float2 a, float2 b, float w) { return step(sdSegment(p, a, b), w * PX * 0.5 + 1e-5); }

// Snaps a moving position to the pixel grid, so sprites move a whole pixel at a time.
float2 pxSnap(float2 p) { return (floor(p * PX_ROWS) + 0.5) / PX_ROWS; }

float cottage(float2 q, float s) {
    // q relative to the cottage's foot (middle), s its scale.
    float wall = pxBox(q, float2(0.0, -0.025 * s), float2(0.035 * s, 0.025 * s));
    float roof = step(-0.08 * s + abs(q.x) * 0.9, q.y) * step(q.y, -0.048 * s) * step(abs(q.x), 0.045 * s);
    return max(wall, roof * 2.0);
}

half4 main(float2 fc) {
    float2 cell = pxCell(fc);
    float2 uv = pxUv(cell);
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    float3 col = mix(mix(float3(0.45, 0.68, 0.92), S * 0.5 + 0.3, 0.2), float3(0.92, 0.95, 0.88), pxBand(uv.y * 1.6, 4.0, cell));
    // Clouds: chunky pixel puffs sailing.
    for (int i = 0; i < 4; i++) {
        float fi = float(i);
        float2 c = float2(fract(fi * 0.27 + t * 0.006 * (1.0 + fi * 0.2)) * (asp + 0.5) - 0.25, 0.08 + fi * 0.05);
        float p = step(length((uv - c) * float2(0.5, 1.0)), 0.025) + step(length((uv - c - float2(0.035, 0.008)) * float2(0.5, 1.0)), 0.02) + step(length((uv - c + float2(0.03, -0.01)) * float2(0.55, 1.0)), 0.018);
        col = mix(col, mix(float3(1.0), float3(0.85, 0.88, 0.95), step(c.y + 0.01, uv.y)), step(0.5, p));
    }
    // Birds.
    for (int i = 0; i < 3; i++) {
        float fi = float(i);
        float2 b = pxSnap(float2(fract(fi * 0.4 + t * 0.03) * (asp + 0.2) - 0.1, 0.2 + 0.03 * fi + 0.01 * sin(t * 2.0 + fi)));
        float2 q = (uv - b) / PX;
        float f = step(0.0, sin(t * 8.0 + fi));
        col = mix(col, float3(0.2, 0.22, 0.3), step(abs(q.x), 3.0) * step(abs(q.y - abs(q.x) * (f > 0.5 ? -0.5 : 0.4)), 0.6));
    }
    // Far hills, then the village hill.
    float h1 = 0.52 + 0.04 * sin(uv.x * 2.5 + 1.0);
    if (uv.y > h1) col = mix(mix(float3(0.45, 0.65, 0.45), S, 0.15), float3(0.6, 0.75, 0.55), 0.4);
    float h2 = 0.6 - 0.1 * exp(-sqf((uv.x - asp * 0.35) * 2.0)) + 0.015 * sin(uv.x * 7.0);
    if (uv.y > h2) {
        float tile = step(0.5, fract((uv.x + floor(uv.y * 40.0) * 0.5 / 40.0) * 40.0)) ;
        col = mix(mix(float3(0.35, 0.62, 0.3), A, 0.1), float3(0.42, 0.7, 0.35), tile * 0.5 + pxBand(1.0 - (uv.y - h2) * 3.0, 2.0, cell) * 0.5);
    }
    // The path winding down.
    float pathX = asp * 0.35 + 0.08 * sin(uv.y * 9.0) + (uv.y - 0.55) * 0.3;
    float pw = 0.01 + (uv.y - 0.5) * 0.08;
    if (uv.y > h2 + 0.02 && abs(uv.x - pathX) < pw) col = mix(float3(0.85, 0.75, 0.55), float3(0.75, 0.65, 0.45), step(0.6, hash12(cell)));
    // Cottages.
    for (int i = 0; i < 4; i++) {
        float fi = float(i);
        float cx = asp * 0.35 + (fi - 1.5) * 0.12 + 0.02 * hash11(fi);
        float hy = 0.6 - 0.1 * exp(-sqf((cx - asp * 0.35) * 2.0)) + 0.015 * sin(cx * 7.0) + 0.01;
        float s = 1.0 + 0.2 * hash11(fi * 3.0);
        float2 q = uv - float2(cx, hy);
        float c = cottage(q, s);
        float3 wallC = mix(float3(0.95, 0.9, 0.8), float3(0.85, 0.78, 0.65), step(0.0, q.x));
        float3 roofC = mix(mix(float3(0.75, 0.3, 0.2), A, 0.3 * hash11(fi)), float3(0.55, 0.22, 0.15), step(0.0, q.x));
        if (c > 1.5) col = roofC; else if (c > 0.5) col = wallC;
        col = mix(col, mix(float3(1.0, 0.9, 0.5), float3(0.3, 0.4, 0.5), step(0.5, sin(t * 0.3 + fi))), pxBox(q, float2(-0.012 * s, -0.03 * s), float2(0.007 * s, 0.007 * s)));
        col = mix(col, float3(0.4, 0.25, 0.15), pxBox(q, float2(0.014 * s, -0.012 * s), float2(0.006 * s, 0.012 * s)));
        // Chimney and smoke puffs.
        float2 ch = float2(0.02 * s, -0.075 * s);
        col = mix(col, float3(0.5, 0.35, 0.3), pxBox(q, ch, float2(0.004 * s, 0.01 * s)));
        for (int j = 0; j < 3; j++) {
            float fj = float(j);
            float life = fract(t * 0.25 + fj / 3.0 + fi * 0.3);
            float2 sp = pxSnap(float2(cx + ch.x + life * 0.03 + 0.005 * sin(life * 8.0), hy + ch.y - 0.015 - life * 0.08));
            col = mix(col, mix(float3(0.95), float3(0.75), life), step(length(uv - sp), (0.004 + 0.008 * life)) * (1.0 - step(0.85, life)));
        }
    }
    // Fence and the washing line in front.
    float fy = 0.85;
    float post = step(fract(uv.x * 18.0), 0.12) * step(fy - 0.05, uv.y) * step(uv.y, fy + 0.02);
    float rail = (step(abs(uv.y - (fy - 0.035)), PX * 0.6) + step(abs(uv.y - (fy - 0.01)), PX * 0.6));
    col = mix(col, float3(0.55, 0.4, 0.25), sat(post + rail * step(fy - 0.06, uv.y)));
    if (uv.y > fy + 0.02) col = mix(float3(0.3, 0.55, 0.25), float3(0.25, 0.48, 0.2), pxBand(hash12(cell), 2.0, cell));
    float lx0 = asp * 0.62;
    float lx1 = asp * 0.92;
    float u = (uv.x - lx0) / (lx1 - lx0);
    float ly = 0.66 + 0.03 * 4.0 * u * (1.0 - u);
    col = mix(col, float3(0.3), step(abs(uv.y - ly), PX * 0.5) * step(0.0, u) * step(u, 1.0));
    col = mix(col, float3(0.5, 0.38, 0.25), (pxBox(uv, float2(lx0, 0.76), float2(PX, 0.1)) + pxBox(uv, float2(lx1, 0.76), float2(PX, 0.1))));
    for (int i = 0; i < 4; i++) {
        float fi = float(i);
        float cu = 0.15 + fi * 0.22;
        float cx = mix(lx0, lx1, cu);
        float cy = 0.66 + 0.12 * cu * (1.0 - cu);
        float flap = 0.008 * sin(t * 3.0 + fi * 1.3);
        float2 q = uv - float2(cx, cy);
        float cloth = step(0.0, q.y) * step(q.y, 0.035 + 0.01 * hash11(fi)) * step(abs(q.x - flap * q.y / 0.035), 0.018);
        col = mix(col, mix(mix(A, S, hash11(fi * 2.0)), float3(1.0), 0.3 * step(0.5, fract(q.y * 80.0))), cloth);
    }
    col = pxQuant(col, 10.0, cell);
    return half4(finish(col, fc), 1.0);
}
"""

    private const val PX_DOJO = """
// Dojo · 32-bit: the user's painting of a training yard at sunset (res scene_dojo), brought to life.
// The two banners ripple in the wind, the sandbag swings after every punch and settles, the lanterns
// either side of the door flicker, the setting sun shimmers, blossom petals blow off the tree and
// across the yard, and dust motes drift in the low light.
// Shared by the painted scenes (the user's own paintings with motion added on top: aurora, meadow,
// px_dojo): the painting fills the screen like a cover (cropped, never stretched) round a chosen point.
uniform shader uPaint;      // the painting (ScenePainting: res/drawable-nodpi/scene_*.webp)
uniform float2 uPaintSize;  // its decoded size in pixels
uniform float uHasPaint;    // 0 while it decodes (a plain gradient in the theme's colours shows)

// The painting's pixel under screen point fc, filling the screen, the crop centred on (fx, fy) (0..1 across it).
float2 paintPx(float2 fc, float fx, float fy) {
    float2 sz = max(uPaintSize, float2(1.0));
    float s = max(uRes.x / sz.x, uRes.y / sz.y);
    float2 off = (sz * s - uRes) * float2(fx, fy);
    return (fc + off) / s;
}

// The painting's colour at pixel p (clamped inside it).
float3 paintAt(float2 p) { return float3(uPaint.eval(clamp(p, float2(0.5), max(uPaintSize, float2(1.0)) - 0.5)).rgb); }

// Brightness, for picking out lit parts of the painting.
float luma(float3 c) { return dot(c, float3(0.299, 0.587, 0.114)); }

// How much pixel p is a small bright speck (a star) rather than part of a bright area: brighter than the
// painting a few pixels away on both sides. lum is its own brightness.
float speckAt(float2 p, float lum) {
    float k = max(uPaintSize.y, 1.0) / 941.0 * 4.0;
    float n = (luma(paintAt(p + float2(k, k * 0.5))) + luma(paintAt(p - float2(k * 0.5, k)))) * 0.5;
    return smoothstep(0.06, 0.2, lum - n);
}

// The painted chill scenes' finish: the painting's own colours and framing (no vignette, no highlight
// roll-off), only the fine noise that keeps dark gradients from banding.
float3 finishPaint(float3 col, float2 fc) {
    col = clamp(col, 0.0, 1.0);
    return col + (hash12(fc) - 0.5) / 255.0;
}

// Where things are in the painting (its own pixels, 1672 x 941; scaled if it's decoded smaller).
const float2 PAINT_REF = float2(1672.0, 941.0);
const float2 BAG_PIVOT = float2(1169.0, 463.0);      // the rope's knot on the beam
const float2 BAG_C = float2(1167.5, 609.0);          // the bag's middle
const float2 BAG_H = float2(25.0, 71.0);             // and half its size

float bagBox(float2 r) { return sdRoundBox(r - BAG_C, BAG_H, 6.0); }

half4 main(float2 fc) {
    float t = uTime;
    float3 BG = uBg.rgb;
    if (uHasPaint < 0.5) {
        float2 uv = fc / uRes;
        return half4(finish(mix(float3(0.95, 0.45, 0.25), float3(0.25, 0.15, 0.2), uv.y), fc), 1.0);
    }
    float2 sz = max(uPaintSize, float2(1.0));
    float2 p = paintPx(fc, 0.5, 0.5);
    float2 q = p / sz;
    float2 r = q * PAINT_REF;                         // in the painting's reference pixels
    float2 k = sz / PAINT_REF;                        // reference pixels -> decoded pixels
    float asp = sz.x / sz.y;

    // The banners: the cloth ripples, more towards its free end (the bottom).
    float2 sp2 = r;
    for (int i = 0; i < 2; i++) {
        float x0 = i == 0 ? 457.0 : 1392.0;
        float inB = step(x0, r.x) * step(r.x, x0 + 62.0) * step(208.0, r.y) * step(r.y, 412.0);
        float f = sat((r.y - 212.0) / 195.0);
        sp2.x += inB * sin(r.y * 0.075 - t * 4.5 + float(i) * 2.0) * 2.4 * f;
    }
    float3 col = paintAt(sp2 * k);

    // The sandbag swings on its rope after each punch (every 6 s), settling slowly; a little sway between.
    float ph = fract(t / 6.0) * 6.0;
    float ang = 0.11 * exp(-ph * 0.7) * sin(ph * 3.2) + 0.012 * sin(t * 0.9);
    float2 rel = r - BAG_PIVOT;
    if (abs(rel.x) < 60.0 && rel.y > -4.0 && rel.y < 230.0) {
        float2 s = BAG_PIVOT + rot(ang) * rel;        // where this pixel was before the swing
        bool wasBag = bagBox(s) < 0.0;
        bool wasRope = abs(s.x - 1169.0) < 4.5 && s.y > 460.0 && s.y < 542.0;
        float3 srcC = paintAt(s * k);
        bool rope = wasRope && luma(srcC) > 0.42 && srcC.r > srcC.b;
        bool here = bagBox(r) < 1.5 || (abs(r.x - 1169.0) < 5.0 && r.y > 460.0 && r.y < 542.0);
        if (wasBag || rope) col = srcC;
        else if (here) {
            // What's behind the bag (fence, wall, yard run across in bands): from either side of it.
            float3 lc = paintAt(float2(1137.0, r.y) * k);
            float3 rc = paintAt(float2(1199.0, r.y) * k);
            col = mix(lc, rc, sat((r.x - 1137.0) / 62.0));
        }
    }
    float lum = luma(col);

    // The sun: a slow shimmer and a breathing glow round it.
    float2 sunQ = float2(0.4994, 0.229);
    float sd = length((q - sunQ) * float2(asp, 1.0));
    col += float3(1.0, 0.75, 0.4) * (exp(-sd * 14.0) * (0.07 + 0.05 * sin(t * 0.8)) + exp(-sd * 4.0) * 0.025);

    // The lanterns flicker and throw a warm glow.
    for (int i = 0; i < 2; i++) {
        float2 lq = i == 0 ? float2(0.414, 0.506) : float2(0.580, 0.506);
        float fl = 0.8 + 0.12 * sin(t * 7.0 + float(i) * 2.0) + 0.08 * sin(t * 13.0 + float(i));
        float ld = length((q - lq) * float2(asp, 1.0));
        float lit = step(0.55, lum) * (1.0 - smoothstep(0.012, 0.02, ld));
        col *= 1.0 + lit * (fl - 0.85) * 1.5;
        col += float3(1.0, 0.65, 0.3) * exp(-ld * 60.0) * 0.12 * fl;
    }

    // Blossom petals: blown off the tree on the left, across the yard to the right.
    float2 uv = q * float2(asp, 1.0);
    float pxs = 3.0 / PAINT_REF.y;                       // one of the painting's pixel blocks
    for (int i = 0; i < 14; i++) {
        float fi = float(i);
        float life = fract(t * (0.05 + 0.03 * hash11(fi)) + hash11(fi * 3.7));
        float2 start = float2(asp * (0.03 + 0.17 * hash11(fi * 5.1)), 0.38 + 0.15 * hash11(fi * 2.3));
        float2 c = start + float2(life * asp * (0.45 + 0.4 * hash11(fi * 7.7)), life * (0.3 + 0.2 * hash11(fi * 1.9)) + 0.02 * sin(life * 18.0 + fi));
        c = (floor(c / pxs) + 0.5) * pxs;                // whole blocks, like the painting
        float2 d = abs(uv - c) / pxs;
        float flutter = step(0.0, sin(t * 6.0 + fi * 2.0));
