    float gem = step(0.97, hash12(floor(uv * float2(40.0, 30.0)))) * step(uv.y, 0.55);
    float sp = step(0.85, fract(t * 0.5 + hash12(floor(uv * float2(40.0, 30.0))) * 7.0));
    col = mix(col, mix(mix(A, S, 0.5), float3(1.0), sp), gem * step(length(fract(uv * float2(40.0, 30.0)) - 0.5), 0.3));
    // The mine mouth: a dark tunnel with timber frame.
    float2 mq = uv - float2(asp * 0.62, 0.62);
    float mouth = step(abs(mq.x), 0.13) * step(-0.18, mq.y) * step(mq.y, 0.12);
    if (mouth > 0.5) col = mix(float3(0.03, 0.02, 0.02), mix(float3(0.3, 0.18, 0.08), A, 0.15), pxBand(sat(1.0 - length(mq * float2(1.0, 0.8)) / 0.16), 3.0, cell) * pxBand(sat((mq.y + 0.18) * 4.0), 2.0, cell));
    float frame = (step(abs(abs(mq.x) - 0.13), 0.012) * step(-0.19, mq.y) * step(mq.y, 0.12)) + step(abs(mq.y + 0.19), 0.012) * step(abs(mq.x), 0.15);
    col = mix(col, mix(float3(0.45, 0.3, 0.15), float3(0.6, 0.42, 0.22), step(0.5, fract(uv.y * 60.0 + uv.x * 60.0))), sat(frame));
    // Lanterns hanging, flickering, lighting the rock round them.
    for (int i = 0; i < 2; i++) {
        float fi = float(i);
        float2 lp = float2(asp * 0.62 + (fi - 0.5) * 0.36, 0.38);
        float fl = 0.8 + 0.2 * sin(t * 11.0 + fi * 3.0) * sin(t * 7.0 + fi);
        col += mix(float3(1.0, 0.6, 0.2), A, 0.3) * 0.35 * fl * pxBand(sat(1.0 - length(uv - lp) * 5.0), 3.0, cell);
        col = mix(col, float3(0.2), pxBox(uv, lp - float2(0.0, 0.03), float2(PX * 0.4, 0.02)));
        col = mix(col, float3(0.25, 0.2, 0.15), pxBox(uv, lp, float2(0.012, 0.016)));
        col = mix(col, mix(float3(1.0, 0.85, 0.4), float3(1.0, 0.6, 0.2), 1.0 - fl), pxBox(uv, lp, float2(0.007, 0.01)));
    }
    // The track and its slope.
    float ground = 0.8;
    if (uv.y > ground) col = mix(r0, r1, pxBand(hash12(cell) * 0.6 + (1.0 - uv.y) * 2.0, 2.0, cell));
    float rails = step(abs(uv.y - (ground - 0.005)), PX * 0.6) + step(abs(uv.y - (ground + 0.008)), PX * 0.5);
    float ties = step(fract(uv.x * 25.0), 0.3) * step(ground - 0.005, uv.y) * step(uv.y, ground + 0.015);
    col = mix(col, float3(0.4, 0.26, 0.15), ties);
    col = mix(col, float3(0.7, 0.72, 0.78), sat(rails));
    // The mine cart: rolls out of the tunnel and across, loaded with ore.
    float ct = fract(t / 10.0);
    float cx = asp * 0.62 - 0.05 - ct * (asp * 0.62 + 0.3);
    float2 cq = uv - float2(cx, ground - 0.012);
    float bounce = step(0.5, fract(t * 6.0)) * PX;
    cq.y += bounce;
    float tub = step(-0.06, cq.y) * step(cq.y, -0.01) * step(abs(cq.x), 0.05 - (cq.y + 0.06) * -0.25);
    col = mix(col, mix(float3(0.45, 0.47, 0.52), float3(0.3, 0.32, 0.36), step(0.0, cq.x)), tub);
    col = mix(col, float3(0.6, 0.62, 0.68), tub * step(abs(cq.y + 0.045), PX * 0.6));
    float ore = step(length((cq - float2(0.0, -0.06)) * float2(0.7, 1.4)), 0.035) * step(cq.y, -0.06);
    col = mix(col, mix(r1, mix(A, S, 0.5), step(0.8, hash12(floor(cq * 200.0)))), ore);
    float wheel = step(length(cq - float2(-0.03, -0.005)), 0.012) + step(length(cq - float2(0.03, -0.005)), 0.012);
    col = mix(col, float3(0.15), sat(wheel));
    // Pebbles bouncing down from the top right.
    for (int i = 0; i < 3; i++) {
        float fi = float(i);
        float pt = fract(t * 0.15 + fi / 3.0);
        float x = asp * (0.95 - 0.5 * pt) + 0.05 * fi;
        float y = 0.05 + pt * 0.75 - 0.05 * abs(sin(pt * 12.0 + fi));
        col = mix(col, r3, step(length(uv - pxSnap(float2(x, y))), PX * 1.3));
    }
    col = pxQuant(col, 10.0, cell);
    return half4(finish(col, fc), 1.0);
}
"""

    private const val PX_WYRM = """
// Wyrm · 32-bit (dragon type): castle ruins on a crag under a stormy moon. A long sky serpent winds
// round the moon in a loop, its scaled body rippling and its fins flickering, lightning lights the
// clouds, and banners on the broken towers whip in the wind.
// Shared by the 32-bit creature-type scenes (px_*.agsl): a chunky pixel grid, an ordered dither and
// banded shading, so every scene reads as one 32-bit sprite picture. Shapes are evaluated at each
// pixel's centre with hard edges (no smoothing), colours are stepped through a few shades with a 4 x 4
// Bayer dither between them.

// The pixel a fragment belongs to, with PX_ROWS pixels on the screen's height.
const float PX_ROWS = 180.0;
float2 pxCell(float2 fc) { return floor(fc / uRes.y * PX_ROWS); }
// The centre of that pixel in screen heights (0..aspect across, 0..1 down).
float2 pxUv(float2 cell) { return (cell + 0.5) / PX_ROWS; }
// One pixel, in screen heights.
const float PX = 1.0 / 180.0;

// 4 x 4 ordered dither threshold for an integer cell, 0..1.
float bayer2(float2 p) { return 2.0 * p.x + 3.0 * p.y - 4.0 * p.x * p.y; }
float bayer4(float2 c) {
    float2 a = mod(c, 2.0);
    float2 b = mod(floor(c * 0.5), 2.0);
    return (4.0 * bayer2(a) + bayer2(b) + 0.5) / 16.0;
}

// v (0..1) stepped into n bands, dithered across each step.
float pxBand(float v, float n, float2 cell) {
    return clamp(floor(v * n + bayer4(cell)) / n, 0.0, 1.0);
}

// The colour stepped to a small palette (levels per channel), dithered.
float3 pxQuant(float3 c, float levels, float2 cell) {
    return floor(max(c, 0.0) * levels + bayer4(cell)) / levels;
}

// Four-shade ramp: dark, mid, light, highlight (v 0..1), banded and dithered.
float3 pxRamp(float v, float2 cell, float3 c0, float3 c1, float3 c2, float3 c3) {
    float b = pxBand(sat(v), 3.0, cell);
    return b < 0.17 ? c0 : (b < 0.5 ? c1 : (b < 0.84 ? c2 : c3));
}

// 1 inside a box of half size h around c (hard edge).
float pxBox(float2 p, float2 c, float2 h) {
    float2 d = abs(p - c) - h;
    return step(max(d.x, d.y), 0.0);
}

// 1 inside a circle (hard edge).
float pxDisc(float2 p, float2 c, float r) { return step(length(p - c), r); }

// 1 on a line from a to b that is w pixels thick (hard edge).
float pxLine(float2 p, float2 a, float2 b, float w) { return step(sdSegment(p, a, b), w * PX * 0.5 + 1e-5); }

// Snaps a moving position to the pixel grid, so sprites move a whole pixel at a time.
float2 pxSnap(float2 p) { return (floor(p * PX_ROWS) + 0.5) / PX_ROWS; }

half4 main(float2 fc) {
    float2 cell = pxCell(fc);
    float2 uv = pxUv(cell);
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float flash = step(0.96, fract(t * 0.18)) * step(0.5, fract(t * 6.0));

    float3 col = mix(BG * 0.8, mix(BG * 2.0, A * 0.3, 0.5), pxBand(uv.y * 1.3, 4.0, cell)) + flash * 0.15;
    float2 moon = float2(asp * 0.5, 0.36);
    float md = length(uv - moon);
    col = mix(col, mix(float3(0.95, 0.9, 0.8), S, 0.15), step(md, 0.15));
    col = mix(col, mix(float3(0.85, 0.8, 0.72), S, 0.2), step(md, 0.15) * step(0.6, vnoise((uv - moon) * 25.0)));
    // Storm clouds.
    float cl = fbm3(float2(uv.x * 2.0 + t * 0.03, uv.y * 5.0));
    if (cl > 0.62 - uv.y * 0.2 && md > 0.16) col = mix(BG * 1.6 + S * 0.05, float3(0.5, 0.5, 0.65) + flash * 0.3, step(0.66, cl));
    // The serpent: a chain of scaled segments along a loop round the moon (body behind the moon on the far side).
    float body = 0.0;
    float bodyLit = 0.0;
    float fin = 0.0;
    float headD = 9.0;
    float front = 0.0;
    for (int i = 0; i < 34; i++) {
        float fi = float(i);
        float s = t * 0.35 - fi * 0.06;
        float2 p = moon + float2(cos(s) * 0.33 * asp / 1.78 * 1.4, sin(s) * 0.16 + 0.04 * sin(s * 3.0 + t));
        float depth = sin(s);                        // > 0 in front of the moon
        float r = (0.036 - fi * 0.0008);
        float d = length(uv - pxSnap(p));
        if (d < r && (depth > -0.2 || md > 0.15)) {
            body = 1.0;
            bodyLit = step(0.0, (uv - p).y * -1.0) ;
            front = depth;
            float sc = step(0.5, fract((uv.x - p.x) * 120.0 + (uv.y - p.y) * 120.0));
            bodyLit = max(bodyLit * 0.6, sc * 0.3 + bodyLit * 0.5);
        }
        if (mod(fi, 3.0) < 0.5 && i > 1) {
            float2 fp = p + float2(0.0, -r * 1.3 - 0.01 * (0.5 + 0.5 * sin(t * 8.0 + fi)));
            fin = max(fin, step(length((uv - pxSnap(fp)) * float2(1.6, 1.0)), 0.012) * step(depth, 9.0));
        }
        if (i == 0) headD = length(uv - pxSnap(p));
    }
    float3 scale0 = mix(float3(0.15, 0.4, 0.3), A, 0.45);
    float3 scale1 = mix(float3(0.35, 0.7, 0.45), A, 0.35);
    col = mix(col, mix(S, float3(1.0, 0.4, 0.3), 0.4), fin);
    col = mix(col, mix(scale0, scale1, bodyLit), body);
    // Head: a wedge with horns and a glowing eye.
    float hs = t * 0.35;
    float2 hp = moon + float2(cos(hs) * 0.33 * asp / 1.78 * 1.4, sin(hs) * 0.16 + 0.04 * sin(hs * 3.0 + t));
    float2 dir = normalize(float2(-sin(hs) * 0.33 * asp / 1.78 * 1.4, cos(hs) * 0.16));
    float2 hq = float2(dot(uv - hp, dir), dot(uv - hp, float2(-dir.y, dir.x)));
    float head = step(0.0, hq.x + 0.02) * step(hq.x, 0.06) * step(abs(hq.y), 0.038 * (1.0 - hq.x / 0.075));
    float horn = pxLine(uv, hp - dir * 0.01 + float2(-dir.y, dir.x) * 0.02, hp - dir * 0.05 + float2(-dir.y, dir.x) * 0.05, 2.0);
    col = mix(col, scale1, head);
    col = mix(col, float3(0.9, 0.85, 0.7), horn);
    col = mix(col, mix(float3(1.0, 0.9, 0.3), S, 0.3), step(length(hq - float2(0.02, 0.01)), PX * 1.2) * head);
    // Ruins on a crag in front.
    float crag = 0.78 - 0.1 * exp(-sqf((uv.x - asp * 0.25) * 3.0)) + 0.02 * sin(uv.x * 23.0);
    float t1 = pxBox(uv, float2(asp * 0.2, 0.6), float2(0.035, 0.14)) * step(0.48 + 0.03 * step(0.5, fract(uv.x * 40.0)), uv.y);
    float t2 = pxBox(uv, float2(asp * 0.32, 0.64), float2(0.03, 0.1)) * step(0.55 + 0.04 * sin(uv.x * 80.0), uv.y);
    float wall = pxBox(uv, float2(asp * 0.26, 0.7), float2(0.1, 0.04)) * step(0.66 + 0.02 * step(0.5, fract(uv.x * 30.0)), uv.y);
    float ruin = sat(t1 + t2 + wall);
    col = mix(col, mix(float3(0.12, 0.1, 0.16), BG, 0.3) + flash * 0.1, max(ruin, step(crag, uv.y)));
    col = mix(col, mix(float3(1.0, 0.8, 0.4), A, 0.3), ruin * step(abs(fract(uv.y * 20.0) - 0.5), 0.2) * step(abs(fract(uv.x * 30.0) - 0.5), 0.15) * step(0.8, hash12(floor(uv * float2(30.0, 20.0)))));
    // Banners on the towers.
    for (int i = 0; i < 2; i++) {
        float fi = float(i);
        float2 bp = fi < 0.5 ? float2(asp * 0.2, 0.42) : float2(asp * 0.32, 0.5);
        col = mix(col, float3(0.2), pxBox(uv, bp + float2(0.0, 0.03), float2(PX * 0.5, 0.04)));
        float2 q = uv - bp;
        float w = 0.008 * sin(q.x * 50.0 - t * 8.0);
        col = mix(col, mix(float3(0.7, 0.15, 0.2), A, 0.3), step(0.0, q.x) * step(q.x, 0.06) * step(abs(q.y - w), 0.012));
    }
    // Lightning bolt now and then.
    float2 lb = float2(asp * (0.75 + 0.1 * hash11(floor(t * 0.18))), 0.05);
    float zig = lb.x + 0.03 * sign(sin(uv.y * 40.0)) * fract(uv.y * 6.0);
    col = mix(col, float3(1.0), flash * step(abs(uv.x - zig), PX) * step(uv.y, 0.55));
    col = pxQuant(col, 10.0, cell);
    return half4(finish(col, fc), 1.0);
}
"""

    private const val PX_UMBRA = """
// Umbra · 32-bit (dark type): city rooftops under an eclipse. The black sun burns with a thin ring of
// fire, water towers and antennas stand against it, a flock of crows lifts off in a gust, eyes blink in
// dark alleys and shadow smoke curls up between the buildings.
// Shared by the 32-bit creature-type scenes (px_*.agsl): a chunky pixel grid, an ordered dither and
// banded shading, so every scene reads as one 32-bit sprite picture. Shapes are evaluated at each
// pixel's centre with hard edges (no smoothing), colours are stepped through a few shades with a 4 x 4
// Bayer dither between them.

// The pixel a fragment belongs to, with PX_ROWS pixels on the screen's height.
const float PX_ROWS = 180.0;
float2 pxCell(float2 fc) { return floor(fc / uRes.y * PX_ROWS); }
// The centre of that pixel in screen heights (0..aspect across, 0..1 down).
float2 pxUv(float2 cell) { return (cell + 0.5) / PX_ROWS; }
// One pixel, in screen heights.
const float PX = 1.0 / 180.0;

// 4 x 4 ordered dither threshold for an integer cell, 0..1.
float bayer2(float2 p) { return 2.0 * p.x + 3.0 * p.y - 4.0 * p.x * p.y; }
float bayer4(float2 c) {
    float2 a = mod(c, 2.0);
    float2 b = mod(floor(c * 0.5), 2.0);
    return (4.0 * bayer2(a) + bayer2(b) + 0.5) / 16.0;
}

// v (0..1) stepped into n bands, dithered across each step.
float pxBand(float v, float n, float2 cell) {
    return clamp(floor(v * n + bayer4(cell)) / n, 0.0, 1.0);
}

// The colour stepped to a small palette (levels per channel), dithered.
float3 pxQuant(float3 c, float levels, float2 cell) {
    return floor(max(c, 0.0) * levels + bayer4(cell)) / levels;
}

// Four-shade ramp: dark, mid, light, highlight (v 0..1), banded and dithered.
float3 pxRamp(float v, float2 cell, float3 c0, float3 c1, float3 c2, float3 c3) {
    float b = pxBand(sat(v), 3.0, cell);
    return b < 0.17 ? c0 : (b < 0.5 ? c1 : (b < 0.84 ? c2 : c3));
}

// 1 inside a box of half size h around c (hard edge).
float pxBox(float2 p, float2 c, float2 h) {
    float2 d = abs(p - c) - h;
    return step(max(d.x, d.y), 0.0);
}

// 1 inside a circle (hard edge).
float pxDisc(float2 p, float2 c, float r) { return step(length(p - c), r); }

// 1 on a line from a to b that is w pixels thick (hard edge).
float pxLine(float2 p, float2 a, float2 b, float w) { return step(sdSegment(p, a, b), w * PX * 0.5 + 1e-5); }

// Snaps a moving position to the pixel grid, so sprites move a whole pixel at a time.
float2 pxSnap(float2 p) { return (floor(p * PX_ROWS) + 0.5) / PX_ROWS; }

half4 main(float2 fc) {
    float2 cell = pxCell(fc);
    float2 uv = pxUv(cell);
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    // Sky: deep red-violet bands, darkest round the eclipse.
    float2 sun = float2(asp * 0.62, 0.3);
    float sd = length(uv - sun);
    float3 col = mix(mix(float3(0.35, 0.08, 0.12), A * 0.4, 0.4), BG * 0.6, pxBand(sat(uv.y * 0.6 + 0.6 - sd * 1.2), 5.0, cell));
    // The eclipse: corona rays, a fiery ring, the black disc.
    float ang = atan(uv.y - sun.y, uv.x - sun.x);
    float rays = step(0.6, sin(ang * 14.0 + sin(t * 0.3) * 2.0)) * step(sd, 0.2 + 0.03 * sin(ang * 5.0 + t)) * step(0.11, sd);
    col = mix(col, mix(A, float3(1.0, 0.6, 0.4), 0.4), rays * 0.5 * step(0.5, mod(cell.x + cell.y, 2.0)));
    col = mix(col, mix(float3(1.0, 0.85, 0.6), A, 0.3), step(sd, 0.112) * step(0.098, sd));
    col = mix(col, float3(0.02, 0.0, 0.02), step(sd, 0.1));
    // Rooftops: three rows of buildings, nearer ones darker and taller.
    for (int r = 0; r < 3; r++) {
        float fr = float(r);
        float w = 0.12 - fr * 0.02;
        float id = floor(uv.x / w + fr * 0.37);
        float h = 0.55 + fr * 0.08 + 0.12 * hash11(id + fr * 20.0);
        float3 bc = mix(float3(0.12, 0.08, 0.12), BG, 0.3) * (1.0 - fr * 0.3);
        if (uv.y > h) {
            col = bc;
            // Windows, a few lit.
            float2 wg = float2(fract(uv.x / w + fr * 0.37) * 4.0, (uv.y - h) * 50.0);
            float lit = step(0.9, hash12(floor(wg) + id * 7.0 + fr));
            col = mix(col, mix(float3(1.0, 0.7, 0.4), A, 0.4), lit * step(abs(fract(wg.x) - 0.5), 0.25) * step(abs(fract(wg.y) - 0.5), 0.3) * step(0.02, uv.y - h));
        }
        // Water towers and antennas on some roofs.
        float rx = (id - fr * 0.37 + 0.5) * w;
        if (hash11(id * 3.0 + fr) > 0.6) {
            float tank = pxBox(uv, float2(rx, h - 0.05), float2(0.02, 0.025)) + step(h - 0.085 + abs(uv.x - rx) * 0.6, uv.y) * step(uv.y, h - 0.075) * step(abs(uv.x - rx), 0.022);
            float legs = step(abs(abs(uv.x - rx) - 0.015), PX * 0.5) * step(h - 0.025, uv.y) * step(uv.y, h);
            col = mix(col, bc, sat(tank + legs));
        } else if (hash11(id * 5.0 + fr) > 0.5) {
            col = mix(col, bc, pxBox(uv, float2(rx, h - 0.06), float2(PX * 0.5, 0.06)) + pxBox(uv, float2(rx, h - 0.09), float2(0.012, PX * 0.5)));
            col = mix(col, float3(1.0, 0.2, 0.2), pxDisc(uv, float2(rx, h - 0.12), PX) * step(0.5, sin(t * 3.0 + id)));
        }
    }
    // Eyes blinking in the alleys.
    for (int i = 0; i < 4; i++) {
        float fi = float(i);
        float2 e = pxSnap(float2((0.15 + fi * 0.24) * asp, 0.86 + 0.06 * hash11(fi * 3.0)));
        float open = step(0.08, fract(t * 0.2 + hash11(fi))) * step(0.5, hash11(fi + floor(t * 0.2)));
        float eye = (step(length((uv - e - float2(-0.012, 0.0)) * float2(1.0, 2.0)), 0.007) + step(length((uv - e - float2(0.012, 0.0)) * float2(1.0, 2.0)), 0.007)) * open;
        col = mix(col, mix(float3(1.0, 0.9, 0.3), S, 0.3), eye);
    }
    // Shadow smoke curling up.
    float sm = fbm3(float2(uv.x * 5.0, uv.y * 3.0 + t * 0.15));
    col = mix(col, mix(float3(0.15, 0.05, 0.2), A * 0.3, 0.3), step(0.6, sm) * step(0.55, uv.y) * step(0.5, mod(cell.x + cell.y, 2.0)) * 0.8);
    // Crows: lift off in a gust every 9 s and wheel away.
    float ct = fract(t / 9.0);
    for (int i = 0; i < 8; i++) {
        float fi = float(i);
        float2 start = float2(asp * 0.3 + fi * 0.025, 0.55);
        float2 p = start + float2(ct * (0.5 + 0.3 * hash11(fi)), -ct * (0.4 + 0.3 * hash11(fi * 2.0))) + float2(0.02 * sin(ct * 20.0 + fi), 0.0);
        p = pxSnap(p);
        float2 q = (uv - p) / PX;
        float f = sin(t * 12.0 + fi);
        float crow = step(abs(q.x), 3.5) * step(abs(q.y - abs(q.x) * 0.45 * f), 0.8) + step(length(q), 1.3);
        col = mix(col, float3(0.02), step(0.5, crow) * step(ct, 0.9));
    }
    col = pxQuant(col, 10.0, cell);
    return half4(finish(col, fc), 1.0);
}
"""

    private const val PX_ALLOY = """
// Alloy · 32-bit (steel type): a factory line. A riveted steel wall with a big turning gear, a
// conveyor belt carrying gleaming parts under a stamping press that slams down in rhythm, a robot arm
// picking each part up, sparks from a welding torch and a hazard light rolling round.
// Shared by the 32-bit creature-type scenes (px_*.agsl): a chunky pixel grid, an ordered dither and
// banded shading, so every scene reads as one 32-bit sprite picture. Shapes are evaluated at each
// pixel's centre with hard edges (no smoothing), colours are stepped through a few shades with a 4 x 4
// Bayer dither between them.

// The pixel a fragment belongs to, with PX_ROWS pixels on the screen's height.
const float PX_ROWS = 180.0;
float2 pxCell(float2 fc) { return floor(fc / uRes.y * PX_ROWS); }
// The centre of that pixel in screen heights (0..aspect across, 0..1 down).
float2 pxUv(float2 cell) { return (cell + 0.5) / PX_ROWS; }
// One pixel, in screen heights.
const float PX = 1.0 / 180.0;

// 4 x 4 ordered dither threshold for an integer cell, 0..1.
float bayer2(float2 p) { return 2.0 * p.x + 3.0 * p.y - 4.0 * p.x * p.y; }
float bayer4(float2 c) {
    float2 a = mod(c, 2.0);
    float2 b = mod(floor(c * 0.5), 2.0);
    return (4.0 * bayer2(a) + bayer2(b) + 0.5) / 16.0;
}

// v (0..1) stepped into n bands, dithered across each step.
float pxBand(float v, float n, float2 cell) {
    return clamp(floor(v * n + bayer4(cell)) / n, 0.0, 1.0);
}

// The colour stepped to a small palette (levels per channel), dithered.
float3 pxQuant(float3 c, float levels, float2 cell) {
    return floor(max(c, 0.0) * levels + bayer4(cell)) / levels;
}

// Four-shade ramp: dark, mid, light, highlight (v 0..1), banded and dithered.
float3 pxRamp(float v, float2 cell, float3 c0, float3 c1, float3 c2, float3 c3) {
    float b = pxBand(sat(v), 3.0, cell);
    return b < 0.17 ? c0 : (b < 0.5 ? c1 : (b < 0.84 ? c2 : c3));
}

// 1 inside a box of half size h around c (hard edge).
float pxBox(float2 p, float2 c, float2 h) {
    float2 d = abs(p - c) - h;
    return step(max(d.x, d.y), 0.0);
}

// 1 inside a circle (hard edge).
float pxDisc(float2 p, float2 c, float r) { return step(length(p - c), r); }

// 1 on a line from a to b that is w pixels thick (hard edge).
float pxLine(float2 p, float2 a, float2 b, float w) { return step(sdSegment(p, a, b), w * PX * 0.5 + 1e-5); }

// Snaps a moving position to the pixel grid, so sprites move a whole pixel at a time.
float2 pxSnap(float2 p) { return (floor(p * PX_ROWS) + 0.5) / PX_ROWS; }

float gearShape(float2 q, float r, float teeth, float a) {
    float rr = length(q);
    float an = atan(q.y, q.x) + a;
    float tooth = step(0.5, fract(an / TAU * teeth));
    return step(rr, r + tooth * r * 0.16) * step(r * 0.35, rr);
}

half4 main(float2 fc) {
    float2 cell = pxCell(fc);
    float2 uv = pxUv(cell);
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float3 st0 = mix(float3(0.2, 0.22, 0.26), BG, 0.3);
    float3 st1 = mix(float3(0.42, 0.45, 0.5), A * 0.6, 0.15);
    float3 st2 = mix(float3(0.62, 0.66, 0.72), A, 0.15);
    float3 st3 = float3(0.88, 0.92, 0.96);

    // Riveted panels with a sweeping sheen.
    float2 pg = uv * float2(5.0, 4.0);
    float2 pf = fract(pg);
    float sheen = step(abs(fract(uv.x * 0.6 + uv.y * 0.3 - t * 0.08) - 0.5), 0.06);
    float3 col = pxRamp(0.18 + 0.25 * (1.0 - uv.y) + 0.45 * sheen, cell, st0, st1, st2, st3);
    col = mix(col, st0, step(min(pf.x, pf.y), 0.03));
    float2 rv = abs(pf - 0.5) - 0.42;
    col = mix(col, st3, step(length(max(rv, 0.0) - 0.0), 0.0) * step(length(pf - float2(0.08, 0.08)), 0.03));
    col = mix(col, st3, step(length(pf - float2(0.92, 0.08)), 0.03) + step(length(pf - float2(0.08, 0.92)), 0.03) + step(length(pf - float2(0.92, 0.92)), 0.03));
    // A hazard stripe band.
    float hz = step(abs(uv.y - 0.12), 0.025);
    col = mix(col, mix(float3(1.0, 0.8, 0.1), float3(0.08), step(0.5, fract((uv.x + uv.y) * 12.0))), hz);
    // Two meshing gears.
    float2 g1 = float2(asp * 0.2, 0.42);
    float2 g2 = g1 + float2(0.24, -0.14);
    float ga = gearShape(uv - g1, 0.16, 12.0, t * 0.5);
    float gb = gearShape(uv - g2, 0.1, 8.0, -t * 0.5 * 12.0 / 8.0 + 0.2);
    col = mix(col, mix(st2, st3, step(uv.y, g1.y - 0.02)), ga);
    col = mix(col, mix(mix(st2, A, 0.4), st3, step(uv.y, g2.y - 0.02)), gb);
    col = mix(col, st0, step(length(uv - g1), 0.025) + step(length(uv - g2), 0.018));
    // The press: slams down every 2 s.
    float pt = fract(t / 2.0);
    float drop = pt < 0.15 ? pt / 0.15 : (pt < 0.3 ? 1.0 : 1.0 - smoothstep(0.3, 0.7, pt));
    drop = drop * drop;
    float px0 = asp * 0.55;
    float headY = 0.42 + drop * 0.2;
    col = mix(col, st1, pxBox(uv, float2(px0, 0.25 + (headY - 0.25) * 0.5), float2(0.015, (headY - 0.25) * 0.5)));
    col = mix(col, mix(st2, A, 0.2), pxBox(uv, float2(px0, headY), float2(0.07, 0.025)));
    col = mix(col, mix(float3(1.0, 0.8, 0.1), float3(0.1), step(0.5, fract(uv.x * 30.0))), pxBox(uv, float2(px0, headY + 0.02), float2(0.07, 0.006)));
    col = mix(col, st0, pxBox(uv, float2(px0, 0.22), float2(0.12, 0.03)));
    // Conveyor belt with rollers.
    float beltY = 0.7;
    col = mix(col, st0, pxBox(uv, float2(asp * 0.5, beltY + 0.03), float2(asp, 0.03)));
    col = mix(col, float3(0.12), pxBox(uv, float2(asp * 0.5, beltY), float2(asp, 0.012)) * step(0.3, fract(uv.x * 40.0 + t * 1.2)));
    float roll = step(abs(fract(uv.x * 10.0 + t * 0.12 * 0.0) - 0.5), 0.15) * step(abs(uv.y - beltY - 0.035), 0.012);
    col = mix(col, st2, roll);
    // Parts riding the belt (stamped once they pass the press).
    for (int i = 0; i < 6; i++) {
        float fi = float(i);
        float x = fract(fi / 6.0 + t * 0.05) * (asp + 0.3) - 0.15;
        float2 q = uv - float2(x, beltY - 0.03);
        float stamped = step(px0, x);
        float part = stamped > 0.5 ? pxBox(q, float2(0.0, 0.01), float2(0.03, 0.008)) : pxBox(q, float2(0.0, 0.0), float2(0.018, 0.018));
        col = mix(col, mix(st2, st3, step(q.y, -0.005)), part);
        col = mix(col, mix(A, S, 0.5), part * step(length(q - float2(0.0, stamped > 0.5 ? 0.01 : 0.0)), 0.006));
    }
    // Robot arm on the right, swinging between belt and bin.
    float2 base = float2(asp * 0.85, 0.66);
    float sw = 0.6 * sin(t * 1.2);
    float2 elbow = base + float2(sin(sw) * 0.12, -cos(sw) * 0.14);
    float2 hand = elbow + float2(-cos(sw * 1.3) * 0.12, 0.05 + 0.03 * sin(t * 2.4));
    col = mix(col, st1, pxLine(uv, base, elbow, 6.0));
    col = mix(col, st2, pxLine(uv, elbow, hand, 4.0));
    col = mix(col, st0, pxDisc(uv, elbow, 0.012) + pxDisc(uv, base, 0.02));
    col = mix(col, mix(float3(1.0, 0.8, 0.1), A, 0.2), pxBox(uv, hand + float2(0.0, 0.012), float2(0.014, 0.006)));
    // Welding sparks at the press.
    float wt = step(pt, 0.4);
    for (int i = 0; i < 10; i++) {
        float fi = float(i);
        float life = fract(pt * 4.0 + hash11(fi));
        float2 v = float2((hash11(fi * 3.0) - 0.5) * 0.4, -0.15 - 0.2 * hash11(fi * 5.0));
        float2 sp = pxSnap(float2(px0, headY + 0.03) + v * life + float2(0.0, 0.4 * life * life));
        col = mix(col, mix(float3(1.0, 0.9, 0.4), S, 0.2), step(length(uv - sp), PX * 0.8) * wt * (1.0 - life));
    }
    // Hazard light rolling round.
    float2 hl = float2(asp * 0.55, 0.06);
    float beam = step(0.85, cos(atan(uv.y - hl.y, uv.x - hl.x) - t * 3.0)) * step(length(uv - hl), 0.35);
    col = mix(col, mix(col, float3(1.0, 0.6, 0.1), 0.35), beam * step(0.5, mod(cell.x + cell.y, 2.0)));
    col = mix(col, float3(1.0, 0.55, 0.1), pxDisc(uv, hl, 0.012));
    if (uv.y > 0.78) col = mix(st0, st1, pxBand(hash12(cell) * 0.3 + 0.2, 2.0, cell));
    col = pxQuant(col, 10.0, cell);
    return half4(finish(col, fc), 1.0);
}
"""

    private const val PX_GLIMMER = """
// Glimmer · 32-bit (fairy type): an enchanted glade at twilight. A ring of glowing mushrooms circles a
// mossy clearing, fairies loop through the air leaving sparkling trails, giant bell flowers sway and
// chime with light, and petals and stars float down.
// Shared by the 32-bit creature-type scenes (px_*.agsl): a chunky pixel grid, an ordered dither and
// banded shading, so every scene reads as one 32-bit sprite picture. Shapes are evaluated at each
// pixel's centre with hard edges (no smoothing), colours are stepped through a few shades with a 4 x 4
// Bayer dither between them.

// The pixel a fragment belongs to, with PX_ROWS pixels on the screen's height.
const float PX_ROWS = 180.0;
float2 pxCell(float2 fc) { return floor(fc / uRes.y * PX_ROWS); }
// The centre of that pixel in screen heights (0..aspect across, 0..1 down).
float2 pxUv(float2 cell) { return (cell + 0.5) / PX_ROWS; }
// One pixel, in screen heights.
const float PX = 1.0 / 180.0;

// 4 x 4 ordered dither threshold for an integer cell, 0..1.
float bayer2(float2 p) { return 2.0 * p.x + 3.0 * p.y - 4.0 * p.x * p.y; }
float bayer4(float2 c) {
    float2 a = mod(c, 2.0);
    float2 b = mod(floor(c * 0.5), 2.0);
    return (4.0 * bayer2(a) + bayer2(b) + 0.5) / 16.0;
}

// v (0..1) stepped into n bands, dithered across each step.
float pxBand(float v, float n, float2 cell) {
    return clamp(floor(v * n + bayer4(cell)) / n, 0.0, 1.0);
}

// The colour stepped to a small palette (levels per channel), dithered.
float3 pxQuant(float3 c, float levels, float2 cell) {
    return floor(max(c, 0.0) * levels + bayer4(cell)) / levels;
}

// Four-shade ramp: dark, mid, light, highlight (v 0..1), banded and dithered.
float3 pxRamp(float v, float2 cell, float3 c0, float3 c1, float3 c2, float3 c3) {
    float b = pxBand(sat(v), 3.0, cell);
    return b < 0.17 ? c0 : (b < 0.5 ? c1 : (b < 0.84 ? c2 : c3));
}

// 1 inside a box of half size h around c (hard edge).
float pxBox(float2 p, float2 c, float2 h) {
    float2 d = abs(p - c) - h;
    return step(max(d.x, d.y), 0.0);
}

// 1 inside a circle (hard edge).
float pxDisc(float2 p, float2 c, float r) { return step(length(p - c), r); }

// 1 on a line from a to b that is w pixels thick (hard edge).
float pxLine(float2 p, float2 a, float2 b, float w) { return step(sdSegment(p, a, b), w * PX * 0.5 + 1e-5); }

// Snaps a moving position to the pixel grid, so sprites move a whole pixel at a time.
float2 pxSnap(float2 p) { return (floor(p * PX_ROWS) + 0.5) / PX_ROWS; }

half4 main(float2 fc) {
    float2 cell = pxCell(fc);
    float2 uv = pxUv(cell);
    float asp = uRes.x / uRes.y;
    float t = uTime;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;

    // Twilight: pink to violet bands, stars.
    float3 col = mix(mix(float3(0.3, 0.2, 0.45), BG * 1.5, 0.4), mix(float3(0.95, 0.6, 0.75), A, 0.35), pxBand(uv.y * 1.5, 5.0, cell));
    col = mix(col, float3(1.0, 0.95, 1.0), step(0.99, hash12(cell)) * step(uv.y, 0.4) * step(0.3, sin(t * 2.0 + hash12(cell) * 40.0)));
    // Tree line silhouettes with round crowns.
    float trees = 0.5 - 0.06 * abs(sin(uv.x * 8.0)) - 0.03 * abs(sin(uv.x * 19.0 + 1.0));
    if (uv.y > trees) col = mix(float3(0.18, 0.12, 0.28), BG, 0.3);
    // Glade floor.
    float floorY = 0.66;
    if (uv.y > floorY) col = mix(mix(float3(0.25, 0.45, 0.3), S * 0.5, 0.2), float3(0.18, 0.32, 0.22), pxBand((uv.y - floorY) * 3.0 + hash12(cell) * 0.2, 3.0, cell));
    // The ring's glow on the moss.
    float2 rc = float2(asp * 0.5, 0.8);
    float2 rq = (uv - rc) / float2(0.4, 0.1);
    float rr = length(rq);
    col += mix(A, S, 0.4) * 0.25 * pxBand(sat(1.0 - abs(rr - 1.0) * 2.5), 3.0, cell) * step(floorY, uv.y);
    // Bell flowers swaying at the sides.
    for (int i = 0; i < 4; i++) {
        float fi = float(i);
        float bx = fi < 2.0 ? 0.08 + fi * 0.12 : asp - 0.08 - (fi - 2.0) * 0.12;
        float sw = 0.02 * sin(t * 0.8 + fi);
        float topY = 0.42 + 0.05 * hash11(fi);
        float f = sat((uv.y - topY) / (0.95 - topY));
        col = mix(col, float3(0.2, 0.45, 0.25), step(abs(uv.x - bx - sw * (1.0 - f)), PX * 1.2) * step(topY, uv.y) * step(uv.y, 0.95));
        float2 bell = uv - float2(bx + sw + 0.03, topY + 0.04);
        float b = step(-0.03, bell.y) * step(bell.y, 0.02) * step(abs(bell.x), 0.018 + (bell.y + 0.03) * 0.3);
        float glow = 0.6 + 0.4 * sin(t * 1.5 + fi * 1.7);
        col = mix(col, mix(mix(A, float3(1.0, 0.7, 0.9), 0.4), float3(1.0), step(0.02 - (bell.y + 0.03) * 0.0, bell.y) * 0.5) * (0.8 + 0.3 * glow), b);
        col = mix(col, mix(S, float3(1.0), 0.5), pxDisc(uv, float2(bx + sw + 0.03, topY + 0.07), PX * 1.2) * glow);
    }
    // The mushroom ring: back half, then front half (drawn by order of depth).
    for (int i = 0; i < 14; i++) {
        float fi = float(i);
        float an = fi / 14.0 * TAU;
        float2 m = pxSnap(rc + float2(cos(an) * 0.4, sin(an) * 0.1));
        float sc = 1.1 + 0.6 * (sin(an) * 0.5 + 0.5);
        float2 q = (uv - m) / sc;
        float cap = step(length(q * float2(1.0, 1.7) + float2(0.0, 0.022)), 0.018) * step(q.y, -0.012);
        float stem = pxBox(q, float2(0.0, -0.006), float2(0.005, 0.007));
        float pulse = 0.65 + 0.35 * sin(t * 2.0 - fi * 0.45);
        col = mix(col, float3(0.95, 0.9, 0.85), stem);
        col = mix(col, mix(mix(A, S, mod(fi, 2.0)), float3(1.0), 0.15) * (0.75 + 0.4 * pulse), cap);
        col = mix(col, float3(1.0), cap * step(length(q + float2(0.006, 0.022)), 0.004));
    }
    // Fairies looping with sparkle trails.
    for (int i = 0; i < 3; i++) {
        float fi = float(i);
        for (int j = 0; j < 8; j++) {
            float fj = float(j);
            float s = t * 0.7 + fi * 2.1 - fj * 0.045;
            float2 p = float2(asp * 0.5 + cos(s) * (0.35 + 0.1 * fi) * asp / 1.78, 0.45 + 0.15 * sin(s * 2.0 + fi) + 0.05 * sin(s * 3.0));
            p = pxSnap(p);
            float d = length(uv - p);
            if (j == 0) {
                col = mix(col, mix(col, mix(A, S, fi / 2.0), 0.7), step(d, PX * 6.0) * step(0.5, mod(cell.x + cell.y, 2.0)));
                col = mix(col, mix(mix(A, S, fi / 2.0), float3(1.0), 0.6), step(d, PX * 3.0));
                col = mix(col, float3(1.0), step(d, PX * 1.6));
                float2 wq = (uv - p) / PX;
                float wing = step(length((abs(wq) - float2(3.5, 2.5)) * float2(0.7, 1.1)), 2.4 + 1.0 * step(0.0, sin(t * 30.0 + fi)));
                col = mix(col, mix(col, float3(0.9, 1.0, 1.0), 0.6), wing);
            } else {
                float tw = step(0.4, fract(t * 4.0 + fj * 0.3 + fi));
                col = mix(col, mix(mix(A, S, fi / 2.0), float3(1.0), 0.4), step(d, PX * 1.3) * tw * (1.0 - fj / 10.0));
            }
        }
    }
    // Petals and stars drifting down.
    for (int i = 0; i < 10; i++) {
        float fi = float(i);
        float2 p = pxSnap(float2(fract(hash11(fi * 3.0) + 0.03 * sin(t * 0.5 + fi)) * asp, fract(hash11(fi) + t * (0.02 + 0.015 * hash11(fi * 2.0)))));
        float2 q = (uv - p) / PX;
        float star = step(abs(q.x), 0.6) * step(abs(q.y), 2.0) + step(abs(q.y), 0.6) * step(abs(q.x), 2.0);
        float petal = step(length(q * float2(1.0, 1.6)), 1.4);
        col = mix(col, mod(fi, 2.0) < 0.5 ? float3(1.0, 0.95, 0.7) : mix(float3(1.0, 0.7, 0.85), A, 0.3), sat(mod(fi, 2.0) < 0.5 ? star : petal) * step(0.3, sin(t * 3.0 + fi)));
    }
    col = pxQuant(col, 10.0, cell);
    return half4(finish(col, fc), 1.0);
}
"""

    private const val GAMING_ROOM = """
// Gaming room (game showcase): the user's painting of a cosy gaming room at night
// (res/drawable-nodpi/gaming_room.webp, 1692 x 845), with the game you're on playing on the monitor: its hero
// art, then its screenshots, a new one every 9 s (ShowcaseScene feeds uShot like the CRT room's TV). The picture
// is cropped and zoomed a little so the monitor always sits in the middle of the screen, clear of the game
// row whether that is at the top or the bottom. The monitor's light spills onto the wall and desk in the
// colours of what it shows; the PC's fans turn, the LED strips breathe, the lamp flickers softly, stars
// twinkle through the window and dust drifts in the moonlight.

uniform shader uRoom;     // the room picture
uniform float2 uRoomSize; // its decoded size in pixels (it may be decoded smaller than 1692 x 845)
uniform shader uShot;     // the game's picture for the monitor
uniform float2 uShotSize;
uniform float uHasShot;   // 0 = no art yet: the painting's own screen shows
uniform float3 uTvL;      // average colour of the picture's left half
uniform float3 uTvR;      // and right half (the light it throws)
uniform float uTune;      // 1 -> 0 just after the picture changed (a quick blink)
uniform shader uPoster;   // the game's cover, for the framed poster above the monitor
uniform float2 uPosterSize;
uniform float uHasPoster;
uniform float uFocusY;    // 0..1 down the screen: where the monitor goes (the middle of the open space, clear of the row)

const float2 ROOM = float2(1692.0, 845.0);
const float2 SCR0 = float2(811.0, 324.0);        // the monitor's screen in the painting
const float2 SCR1 = float2(1134.0, 492.0);
const float2 POS0 = float2(920.0, 77.0);         // the framed poster's picture
const float2 POS1 = float2(1086.0, 271.0);
const float2 FAN1 = float2(1508.0, 396.0);
const float2 FAN2 = float2(1508.0, 471.0);

float3 room(float2 ip) { return float3(uRoom.eval(clamp(ip, float2(0.5), ROOM - 0.5) * uRoomSize / ROOM).rgb); }

half4 main(float2 fc) {
    float t = uTime;
    // Cover the screen, zoomed in a touch, with the monitor where the open space is (uFocusY: above the game
    // row when it's at the bottom, below it when it's at the top), zooming in further when needed so the
    // picture still fills the screen.
    float2 M = (SCR0 + SCR1) * 0.5;
    float fy = clamp(uFocusY, 0.25, 0.75);
    float k = max(1.12 * max(uRes.x / ROOM.x, uRes.y / ROOM.y),  // screen pixels per picture pixel
                  max(fy * uRes.y / M.y, (1.0 - fy) * uRes.y / (ROOM.y - M.y)));
    float2 P = float2(clamp(uRes.x * 0.55, uRes.x - (ROOM.x - M.x) * k, M.x * k),
                      clamp(uRes.y * fy, uRes.y - (ROOM.y - M.y) * k, M.y * k));
    float2 ip = M + (fc - P) / k;                               // the picture pixel under this screen pixel
    float3 col = room(ip);

    // The poster above it: the game's cover, cropped to fill the frame, a little faded like printed paper.
    float2 pq = (ip - POS0) / (POS1 - POS0);
    if (uHasPoster > 0.5 && pq.x >= 0.0 && pq.x <= 1.0 && pq.y >= 0.0 && pq.y <= 1.0) {
        float fa = (POS1.x - POS0.x) / (POS1.y - POS0.y);
        float ca = uPosterSize.x / max(uPosterSize.y, 1.0);
        float2 aq = pq;
        if (ca > fa) aq.x = 0.5 + (pq.x - 0.5) * fa / ca; else aq.y = 0.5 + (pq.y - 0.5) * ca / fa;
        float3 pc = float3(uPoster.eval(aq * uPosterSize).rgb);
        pc = mix(pc, float3(dot(pc, float3(0.33))), 0.08) * 0.82 + 0.02;           // printed, in a dim room
        pc *= 0.85 + 0.15 * (1.0 - pq.y);                                           // the lamp-less top is lighter
        pc *= 1.0 - 0.18 * smoothstep(0.35, 0.75, length(pq - 0.5));                // and its corners darker
        pc += 0.05 * smoothstep(0.1, 0.0, abs(pq.x - pq.y * 0.5 - 0.2));            // glass glare
        col = pc;
    }
    // The monitor: the game's picture fitted to the screen (cropped to fill), a soft LCD look and a glass sheen.
    float2 q = (ip - SCR0) / (SCR1 - SCR0);
    float inScr = step(0.0, q.x) * step(q.x, 1.0) * step(0.0, q.y) * step(q.y, 1.0);
    if (inScr > 0.5 && uHasShot > 0.5) {
        float sa = (SCR1.x - SCR0.x) / (SCR1.y - SCR0.y);
        float pa = uShotSize.x / max(uShotSize.y, 1.0);
        float2 aq = q;
        if (pa > sa) aq.x = 0.5 + (q.x - 0.5) * sa / pa; else aq.y = 0.5 + (q.y - 0.5) * pa / sa;
        float3 g = float3(uShot.eval(aq * uShotSize).rgb);
        g *= 1.05 - 0.25 * sqf(length(q - 0.5) * 1.2);
        g = mix(g, float3(0.02), uTune);                        // the blink as the picture changes
        // Rounded corners of the panel.
        float2 e = min(q, 1.0 - q) * (SCR1 - SCR0);
        float corner = step(length(max(3.0 - e, 0.0)), 3.0);
        col = mix(col, g, corner);
    }
    if (inScr > 0.5) col += 0.05 * smoothstep(0.12, 0.0, abs(q.x - q.y * 0.6 - 0.15)) * (1.0 - q.y);
    // Its light on the wall, the desk and the lamp side, in the picture's colours.
    float3 tv = uHasShot > 0.5 ? mix(uTvL, uTvR, sat((ip.x - SCR0.x) / (SCR1.x - SCR0.x))) : float3(0.35, 0.6, 0.95);
    float2 d = max(abs(ip - M) - (SCR1 - SCR0) * 0.5, 0.0);
    float spill = exp(-length(d) / 90.0) * (1.0 - inScr);
    float flick = 0.9 + 0.1 * sin(t * 2.3) * sin(t * 0.7);
    col += tv * spill * 0.22 * flick;
    // On the desk top just under it, stronger.
    col += tv * 0.18 * exp(-abs(ip.y - 560.0) / 12.0) * exp(-abs(ip.x - M.x) / 220.0) * flick;

    // PC fans: a turning highlight round each ring.
    for (int i = 0; i < 2; i++) {
        float2 f = (i == 0 ? FAN1 : FAN2);
        float2 fq = ip - f;
        float r = length(fq);
        float a = atan(fq.y, fq.x);
        float blades = 0.5 + 0.5 * cos(a * 5.0 - t * 7.0 - float(i));
        col *= 1.0 + 0.35 * blades * (1.0 - smoothstep(24.0, 30.0, r)) * smoothstep(5.0, 9.0, r);
        col *= 1.0 + 0.25 * (0.5 + 0.5 * sin(t * 1.4)) * exp(-abs(r - 31.0) / 3.0);
    }
    // LED strips under the shelf and the desk breathe.
    float breathe = 0.5 + 0.5 * sin(t * 1.1);
    col *= 1.0 + 0.3 * breathe * exp(-abs(ip.y - 280.0) / 10.0) * step(1210.0, ip.x) * step(ip.x, 1585.0);
    col *= 1.0 + 0.25 * breathe * exp(-abs(ip.y - 566.0) / 8.0) * step(660.0, ip.x) * step(ip.x, 1620.0);
    // The lamp's warm pool flickers a little.
    col *= 1.0 + 0.05 * (vnoise(float2(t * 6.0, 1.0)) - 0.5) * exp(-length(ip - float2(760.0, 470.0)) / 160.0);
    // Stars twinkling and the moon glowing in the window.
    float2 w = ip - float2(83.0, 73.0);
    if (w.x > 0.0 && w.x < 393.0 && w.y > 0.0 && w.y < 230.0) {
        float2 sc = floor(ip / 6.0);
        float tw = step(0.985, hash12(sc)) * (0.5 + 0.5 * sin(t * 2.5 + hash12(sc + 3.0) * 30.0));
        col += float3(0.8, 0.85, 1.0) * tw * 0.5 * (1.0 - smoothstep(1.5, 2.5, length(fract(ip / 6.0) * 6.0 - 3.0)));
    }
    col += float3(0.7, 0.75, 1.0) * 0.06 * (0.5 + 0.5 * sin(t * 0.8)) * exp(-length(ip - float2(287.0, 149.0)) / 45.0);
    // Dust drifting in the moonlight below the window.
    float beam = step(60.0, ip.x) * step(ip.x, 560.0) * step(380.0, ip.y) * step(abs(ip.x - 280.0 + (ip.y - 460.0) * 0.55), 190.0);
    float2 dg = floor((ip + float2(t * 6.0, -t * 9.0)) / 5.0);
    col += float3(0.6, 0.7, 1.0) * 0.35 * beam * step(0.993, hash12(dg));
    return half4(finish(col, fc), 1.0);
}
"""

    private const val STILL_DUSK = """
// Still dusk: a calm, unmoving picture — a deep gradient sky warming towards a low glow, a soft halo
// and fine grain. Drawn once; costs nothing while you rest on it. Theme colours throughout.

half4 main(float2 fc) {
    float2 uv = fc / uRes.y;
    float asp = uRes.x / uRes.y;
    float3 A = uAcc.rgb;
    float3 S = uSec.rgb;
    float3 BG = uBg.rgb;
    float y = uv.y;
    float3 col = mix(BG * 0.8, mix(BG, A, 0.35), smoothstep(0.0, 1.0, y));
    col = mix(col, mix(A, S, 0.4) * 0.7 + BG * 0.3, smoothstep(0.55, 1.0, y) * 0.6);
    float2 g = uv - float2(asp * 0.7, 0.78);
